import {
  SCORE_PASS_THRESHOLD,
  SCORE_WARNING_THRESHOLD,
} from "@bao/shared/constants/score-thresholds";
import { PROGRESS_BAR_VARIANT_CLASS, ALERT_VARIANT_CLASS } from "~/constants/layout-tokens";
import { BADGE_VARIANT_CLASS } from "~/constants/layout-badges";

export type ScoreLevel = "pass" | "warning" | "developing" | "unknown";

function resolveScoreLevel(score: number | undefined): ScoreLevel {
  if (!Number.isFinite(score ?? Number.NaN)) return "unknown";
  const s = score ?? 0;
  if (s >= SCORE_PASS_THRESHOLD) return "pass";
  if (s >= SCORE_WARNING_THRESHOLD) return "warning";
  return "developing";
}

const LEVEL_TEXT_MAP: Record<ScoreLevel, string> = {
  pass: "text-success",
  warning: "text-warning",
  developing: "text-error",
  unknown: "text-warning",
};

const LEVEL_BADGE_MAP: Record<ScoreLevel, string> = {
  pass: BADGE_VARIANT_CLASS.success,
  warning: BADGE_VARIANT_CLASS.warning,
  developing: BADGE_VARIANT_CLASS.error,
  unknown: BADGE_VARIANT_CLASS.warning,
};

const LEVEL_PROGRESS_MAP: Record<ScoreLevel, string> = {
  pass: PROGRESS_BAR_VARIANT_CLASS.success,
  warning: PROGRESS_BAR_VARIANT_CLASS.warning,
  developing: PROGRESS_BAR_VARIANT_CLASS.error,
  unknown: PROGRESS_BAR_VARIANT_CLASS.warning,
};

const LEVEL_BORDER_MAP: Record<ScoreLevel, string> = {
  pass: "border-success",
  warning: "border-warning",
  developing: "border-error",
  unknown: "border-warning",
};

const LEVEL_BG_MAP: Record<ScoreLevel, string> = {
  pass: "bg-success",
  warning: "bg-warning",
  developing: "bg-error",
  unknown: "bg-warning",
};

const LEVEL_ALERT_MAP: Record<ScoreLevel, string> = {
  pass: ALERT_VARIANT_CLASS.success,
  warning: ALERT_VARIANT_CLASS.warning,
  developing: ALERT_VARIANT_CLASS.error,
  unknown: ALERT_VARIANT_CLASS.warning,
};

export function useScoreColor() {
  function getScoreColorClass(score: number | undefined): string {
    return LEVEL_TEXT_MAP[resolveScoreLevel(score)];
  }

  function getScoreTextClass(score: number | undefined): string {
    return getScoreColorClass(score);
  }

  function getScoreBadgeClass(score: number | undefined): string {
    return LEVEL_BADGE_MAP[resolveScoreLevel(score)];
  }

  function getScoreProgressClass(score: number | undefined): string {
    return LEVEL_PROGRESS_MAP[resolveScoreLevel(score)];
  }

  function getScoreBorderClass(score: number | undefined): string {
    return LEVEL_BORDER_MAP[resolveScoreLevel(score)];
  }

  function getTimelineLineClass(score: number | undefined): string {
    return LEVEL_BG_MAP[resolveScoreLevel(score)];
  }

  function getAlertClass(score: number | undefined): string {
    return LEVEL_ALERT_MAP[resolveScoreLevel(score)];
  }

  return {
    getScoreColorClass,
    getScoreTextClass,
    getScoreBadgeClass,
    getScoreProgressClass,
    getScoreBorderClass,
    getTimelineLineClass,
    getAlertClass,
  };
}

import { INTERVIEW_FALLBACK_STUDIO_ID } from "@bao/shared/constants/interview";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { InterviewConfig, InterviewSession } from "@bao/shared/types/interview";
import { useI18n } from "vue-i18n";
import { assertApiResponse, requireValue, withLoadingState } from "./async-flow";
import { toInterviewSession, toInterviewSessions, toNumericRecord } from "./interview-normalizers";

interface SubmitResponseInput {
  questionId?: string;
  questionIndex?: number;
  response: string;
}

interface InterviewState {
  sessions: ReturnType<typeof useState<InterviewSession[]>>;
  currentSession: ReturnType<typeof useState<InterviewSession | null>>;
  stats: ReturnType<typeof useState<Record<string, number> | null>>;
  loading: ReturnType<typeof useState<boolean>>;
}

interface InterviewContext extends InterviewState {
  api: ReturnType<typeof useApi>;
  t: ReturnType<typeof useI18n>["t"];
}
const requireSession = (value: unknown, invalidMessage: string): InterviewSession =>
  requireValue(toInterviewSession(value), invalidMessage);

const createInterviewState = (): InterviewState => ({
  sessions: useState<InterviewSession[]>(STATE_KEYS.INTERVIEW_SESSIONS, () => []),
  currentSession: useState<InterviewSession | null>(
    STATE_KEYS.INTERVIEW_CURRENT_SESSION,
    () => null,
  ),
  stats: useState<Record<string, number> | null>(STATE_KEYS.INTERVIEW_STATS, () => null),
  loading: useState(STATE_KEYS.INTERVIEW_LOADING, () => false),
});

const createFetchSessionsAction = (context: InterviewContext) => async () =>
  withLoadingState(context.loading, async () => {
    const { data, error } = await context.api.interview.sessions.get();
    assertApiResponse(error, context.t("apiErrors.interview.fetchSessionsFailed"));
    context.sessions.value = toInterviewSessions(data);
  });

const createFetchStatsAction = (context: InterviewContext) => async () =>
  withLoadingState(context.loading, async () => {
    const { data, error } = await context.api.interview.stats.get();
    assertApiResponse(error, context.t("apiErrors.interview.fetchStatsFailed"));
    context.stats.value = toNumericRecord(data);
  });

const createStartSessionAction =
  (context: InterviewContext, fetchSessions: () => Promise<void>) =>
  async (studioId?: string, config?: Partial<InterviewConfig>) =>
    withLoadingState(context.loading, async () => {
      const trimmedStudioId = studioId?.trim() ?? "";
      const resolvedStudioId =
        trimmedStudioId.length > 0 ? trimmedStudioId : INTERVIEW_FALLBACK_STUDIO_ID;
      const { data, error } = await context.api.interview.sessions.post({
        studioId: resolvedStudioId,
        config,
      });
      assertApiResponse(error, context.t("apiErrors.interview.startFailed"));
      const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
      context.currentSession.value = normalized;
      await fetchSessions();
      return normalized;
    });

const createGetSessionAction = (context: InterviewContext) => async (id: string) =>
  withLoadingState(context.loading, async () => {
    const { data, error } = await context.api.interview.sessions({ id }).get();
    assertApiResponse(error, context.t("apiErrors.interview.fetchSessionFailed"));
    const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
    context.currentSession.value = normalized;
    return normalized;
  });

const createSubmitResponseAction =
  (context: InterviewContext) => async (sessionId: string, response: SubmitResponseInput) =>
    withLoadingState(context.loading, async () => {
      const { data, error } = await context.api.interview
        .sessions({ id: sessionId })
        .response.post(response);
      assertApiResponse(error, context.t("apiErrors.interview.submitResponseFailed"));
      const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
      context.currentSession.value = normalized;
      return normalized;
    });

const createCompleteSessionAction =
  (
    context: InterviewContext,
    fetchSessions: () => Promise<void>,
    fetchStats: () => Promise<void>,
  ) =>
  async (id: string) =>
    withLoadingState(context.loading, async () => {
      const { data, error } = await context.api.interview.sessions({ id }).complete.post();
      assertApiResponse(error, context.t("apiErrors.interview.completeFailed"));
      const normalized = requireSession(data, context.t("apiErrors.interview.invalidPayload"));
      context.currentSession.value = normalized;
      await fetchSessions();
      await fetchStats();
      return normalized;
    });

/**
 * Interview practice session management composable.
 */
export function useInterview() {
  const state = createInterviewState();
  const context: InterviewContext = {
    ...state,
    api: useApi(),
    t: useI18n().t,
  };

  const fetchSessions = createFetchSessionsAction(context);
  const fetchStats = createFetchStatsAction(context);
  const actions = {
    startSession: createStartSessionAction(context, fetchSessions),
    fetchSessions,
    getSession: createGetSessionAction(context),
    submitResponse: createSubmitResponseAction(context),
    completeSession: createCompleteSessionAction(context, fetchSessions, fetchStats),
    fetchStats,
  };

  return {
    sessions: readonly(state.sessions),
    currentSession: readonly(state.currentSession),
    stats: readonly(state.stats),
    loading: readonly(state.loading),
    ...actions,
  };
}

import type { ComposerTranslation } from "vue-i18n";
import type { NuxtApp } from "#app";
import { settlePromise } from "~/composables/async-flow";
import type { ResumePageActionsInput } from "~/composables/resume-page-actions-contracts";
import { getErrorMessage } from "~/utils/errors";

function createResumeCreationPayload(
  name: string,
  template: ResumePageActionsInput["newResumeTemplate"]["value"],
): Parameters<ResumePageActionsInput["createResume"]>[0] {
  return {
    name,
    template,
    personalInfo: {},
    experience: [],
    education: [],
    skills: {},
    projects: [],
    gamingExperience: {},
  };
}

function resolveCreatedResumeId(
  result: Awaited<ReturnType<ResumePageActionsInput["createResume"]>>,
): string | null {
  if (
    typeof result === "object" &&
    result !== null &&
    "id" in result &&
    typeof result.id === "string"
  ) {
    return result.id;
  }
  return null;
}

function createResumeCreateAction(
  input: Pick<
    ResumePageActionsInput,
    | "createResume"
    | "creating"
    | "newResumeName"
    | "newResumeTemplate"
    | "selectedResumeId"
    | "showCreateModal"
  >,
  feedback: {
    $toast: Pick<NuxtApp["$toast"], "error" | "success">;
    t: ComposerTranslation;
  },
) {
  return async function handleCreate(): Promise<void> {
    if (!input.newResumeName.value.trim()) {
      return;
    }
    if (input.newResumeName.value.trim().length < 2) {
      feedback.$toast.error(feedback.t("resumePage.toasts.resumeNameMinLength"));
      return;
    }

    input.creating.value = true;
    const createResult = await settlePromise(
      input.createResume(
        createResumeCreationPayload(input.newResumeName.value, input.newResumeTemplate.value),
      ),
      feedback.t("resumePage.toasts.resumeCreateFailed"),
    );
    input.creating.value = false;

    if (!createResult.ok) {
      feedback.$toast.error(
        getErrorMessage(createResult.error, feedback.t("resumePage.toasts.resumeCreateFailed")),
      );
      return;
    }

    input.showCreateModal.value = false;
    input.newResumeName.value = "";
    input.selectedResumeId.value = resolveCreatedResumeId(createResult.value);
    feedback.$toast.success(feedback.t("resumePage.toasts.resumeCreated"));
  };
}

function createResumeDeleteAction(
  input: Pick<
    ResumePageActionsInput,
    "closeDeleteResumeDialog" | "deleteResume" | "pendingDeleteResumeId" | "selectedResumeId"
  >,
  feedback: {
    $toast: Pick<NuxtApp["$toast"], "error" | "success">;
    t: ComposerTranslation;
  },
) {
  return async function handleDeleteResume(): Promise<void> {
    const id = input.pendingDeleteResumeId.value;
    if (!id) {
      return;
    }

    const deleteResult = await settlePromise(
      input.deleteResume(id),
      feedback.t("resumePage.toasts.resumeDeleteFailed"),
    );
    input.closeDeleteResumeDialog();

    if (!deleteResult.ok) {
      feedback.$toast.error(
        getErrorMessage(deleteResult.error, feedback.t("resumePage.toasts.resumeDeleteFailed")),
      );
      return;
    }

    if (input.selectedResumeId.value === id) {
      input.selectedResumeId.value = null;
    }
    feedback.$toast.success(feedback.t("resumePage.toasts.resumeDeleted"));
  };
}

export function useResumeMutationActions(
  {
    closeDeleteResumeDialog,
    createResume,
    creating,
    deleteResume,
    newResumeName,
    newResumeTemplate,
    pendingDeleteResumeId,
    selectedResumeId,
    showCreateModal,
  }: Pick<
    ResumePageActionsInput,
    | "closeDeleteResumeDialog"
    | "createResume"
    | "creating"
    | "deleteResume"
    | "newResumeName"
    | "newResumeTemplate"
    | "pendingDeleteResumeId"
    | "selectedResumeId"
    | "showCreateModal"
  >,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;
  const feedback = { $toast, t };
  const handleCreate = createResumeCreateAction(
    {
      createResume,
      creating,
      newResumeName,
      newResumeTemplate,
      selectedResumeId,
      showCreateModal,
    },
    feedback,
  );
  const handleDeleteResume = createResumeDeleteAction(
    {
      closeDeleteResumeDialog,
      deleteResume,
      pendingDeleteResumeId,
      selectedResumeId,
    },
    feedback,
  );

  return {
    handleCreate,
    handleDeleteResume,
  };
}

