    : [];

interface JobsContext {
  api: ReturnType<typeof useApi>;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  jobs: ReturnType<typeof useState<Job[]>>;
  savedJobs: ReturnType<typeof useState<Job[]>>;
  applications: ReturnType<typeof useState<Job[]>>;
  recommendations: ReturnType<typeof useState<Job[]>>;
  filters: ReturnType<typeof useState<Record<string, string>>>;
}

async function searchJobs(
  context: JobsContext,
  searchFilters?: Record<string, string>,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    if (searchFilters) {
      context.filters.value = searchFilters;
    }
    const data = await readRequiredApiPayload(
      context.api.jobs.get({ query: context.filters.value }),
      context.t("apiErrors.jobs.searchFailed"),
    );
    context.jobs.value =
      isRecord(data) && Array.isArray(data.jobs) ? toJobList(data.jobs) : toJobList(data);
  });
}

async function getJob(context: JobsContext, id: string): Promise<Job | null> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.jobs({ id }).get(),
      context.t("apiErrors.jobs.fetchFailed"),
    );
    return toJob(data);
  });
}

async function fetchSavedJobs(context: JobsContext): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.jobs.saved.get(),
      context.t("apiErrors.jobs.fetchSavedFailed"),
    );
    if (!Array.isArray(data)) {
      context.savedJobs.value = [];
      return;
    }
    const entries = asJsonArray(data) ?? [];
    const jobs: Job[] = [];
    for (const entry of entries) {
      if (!isRecord(entry)) {
        continue;
      }
      const job = toJob(entry.job);
      if (job) {
        jobs.push(job);
      }
    }
    context.savedJobs.value = jobs;
  });
}

async function saveJob(context: JobsContext, jobId: string): Promise<unknown> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.jobs.save.post({ jobId }),
      context.t("apiErrors.jobs.saveFailed"),
    );
    await fetchSavedJobs(context);
    return data;
  });
}

async function unsaveJob(context: JobsContext, jobId: string): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const jobSaveRoute = context.api.jobs.save({ jobId });
    await readRequiredApiPayload(jobSaveRoute.delete(), context.t("apiErrors.jobs.unsaveFailed"));
    await fetchSavedJobs(context);
  });
}

async function fetchApplications(context: JobsContext): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.jobs.applications.get(),
      context.t("apiErrors.jobs.fetchApplicationsFailed"),
    );
    if (!Array.isArray(data)) {
      context.applications.value = [];
      return;
    }
    const entries = asJsonArray(data) ?? [];
    const jobs: Job[] = [];
    for (const entry of entries) {
      if (!isRecord(entry)) {
        continue;
      }
      const job = toJob(entry.job);
      if (job) {
        jobs.push(job);
      }
    }
    context.applications.value = jobs;
  });
}

async function applyToJob(context: JobsContext, jobId: string, notes?: string): Promise<unknown> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.jobs.apply.post({ jobId, notes }),
      context.t("apiErrors.jobs.applyFailed"),
    );
    await fetchApplications(context);
    return data;
  });
}

async function updateApplication(
  context: JobsContext,
  id: string,
  status: string,
): Promise<unknown> {
  return withLoadingState(context.loading, async () => {
    const applicationRoute = context.api.jobs.apply({ id });
    const data = await readRequiredApiPayload(
      applicationRoute.put({ status }),
      context.t("apiErrors.jobs.updateApplicationFailed"),
    );
    await fetchApplications(context);
    return data;
  });
}

async function refreshJobs(context: JobsContext): Promise<unknown> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.jobs.refresh.post(),
      context.t("apiErrors.jobs.refreshFailed"),
    );
    await searchJobs(context);
    return data;
  });
}

async function fetchRecommendations(context: JobsContext): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.jobs.recommendations.get(),
      context.t("apiErrors.jobs.fetchRecommendationsFailed"),
    );
    if (isRecord(data) && Array.isArray(data.recommendations)) {
      context.recommendations.value = toJobList(data.recommendations);
      return;
    }
    context.recommendations.value = toJobList(data);
  });
}

/**
 * Job search and application management composable.
 */
export function useJobs() {
  const context: JobsContext = {
    api: useApi(),
    t: useI18n().t,
    jobs: useState<Job[]>(STATE_KEYS.JOBS_LIST, () => []),
    savedJobs: useState<Job[]>(STATE_KEYS.JOBS_SAVED, () => []),
    applications: useState<Job[]>(STATE_KEYS.JOBS_APPLICATIONS, () => []),
    recommendations: useState<Job[]>(STATE_KEYS.JOBS_RECOMMENDATIONS, () => []),
    loading: useState(STATE_KEYS.JOBS_LOADING, () => false),
    filters: useState<Record<string, string>>(STATE_KEYS.JOBS_FILTERS, () => ({})),
  };

  return {
    jobs: readonly(context.jobs),
    savedJobs: readonly(context.savedJobs),
    applications: readonly(context.applications),
    recommendations: readonly(context.recommendations),
    loading: readonly(context.loading),
    filters: readonly(context.filters),
    searchJobs: (searchFilters?: Record<string, string>) => searchJobs(context, searchFilters),
    getJob: (id: string) => getJob(context, id),
    saveJob: (jobId: string) => saveJob(context, jobId),
    unsaveJob: (jobId: string) => unsaveJob(context, jobId),
    fetchSavedJobs: () => fetchSavedJobs(context),
    applyToJob: (jobId: string, notes?: string) => applyToJob(context, jobId, notes),
    updateApplication: (id: string, status: string) => updateApplication(context, id, status),
    fetchApplications: () => fetchApplications(context),
    refreshJobs: () => refreshJobs(context),
    fetchRecommendations: () => fetchRecommendations(context),
  };
}

import { useRuntimeConfig } from "#imports";
import { useClientApiRequestRuntime } from "~/composables/api-request";
import {
  createInterviewRealtimeSocket,
  type InterviewResponseFeedbackPayload,
  submitInterviewResponseViaWs,
} from "~/composables/interview-realtime-socket";

/**
 * Interview coaching WS — WS-or-HTTP single path (never both).
 * submitViaWs writes once on the server and returns response_feedback.
 */
export function useInterviewRealtime() {
  const runtime = useClientApiRequestRuntime();
  const config = useRuntimeConfig();
  const wsBase = String(config.public.wsBase || config.public.apiBase || "/");
  const connected = ref(false);
  const lastFeedback = ref<InterviewResponseFeedbackPayload | null>(null);

  const socketApi = createInterviewRealtimeSocket({
    wsBase,
    requestUrl: runtime.requestUrl,
    connected,
    lastFeedback,
  });

  const submitViaWs = (sessionId: string, content: string) =>
    submitInterviewResponseViaWs(socketApi, lastFeedback, sessionId, content);

  onUnmounted(() => {
    socketApi.disconnect();
  });

  return {
    connect: socketApi.connect,
    connected: readonly(connected),
    disconnect: socketApi.disconnect,
    lastFeedback: readonly(lastFeedback),
    submitViaWs,
  };
}

import { escapeRegExp } from "@bao/shared/utils/string";
import { getCurrentScope, onScopeDispose, readonly, ref } from "vue";
const RATIO_0_1 = 0.1;
const RATIO_0_3 = 0.3;
const RATIO_0_5 = 0.5;
const RATIO_0_8 = 0.8;

type ScrollSpyOptions = {
  rootMargin?: string;
  threshold?: number[];
  hashPrefix?: string;
};

const DEFAULT_HASH_PREFIX = "#";
const DEFAULT_ROOT_MARGIN = "-20% 0px -60% 0px";
const DEFAULT_THRESHOLD = [RATIO_0_1, RATIO_0_3, RATIO_0_5, RATIO_0_8];
const MANUAL_SCROLL_LOCK_MS = 250;
const normalizeHashValue = (value: string, hashPrefix: string): string =>
  value.replace(new RegExp(`^${escapeRegExp(hashPrefix)}`, "u"), "").trim();

type ObserverHolder = {
  value: IntersectionObserver | null;
};

interface ScrollSpyState {
  activeSectionId: ReturnType<typeof ref<string>>;
  sectionNodes: Map<string, HTMLElement>;
  observer: ObserverHolder;
  hashPrefix: string;
  lastManualScrollAt: number;
}

function createScrollSpyState(options: ScrollSpyOptions): ScrollSpyState {
  return {
    activeSectionId: ref(""),
    sectionNodes: new Map<string, HTMLElement>(),
    observer: { value: null },
    hashPrefix: options.hashPrefix ?? DEFAULT_HASH_PREFIX,
    lastManualScrollAt: 0,
  };
}

function resolveFallbackSectionId(state: ScrollSpyState): string | null {
  const firstSection = state.sectionNodes.values().next().value;
  return firstSection?.id || null;
}

function updateActiveSection(state: ScrollSpyState, sectionId: string, updateHash: boolean): void {
  if (sectionId.length === 0 || state.activeSectionId.value === sectionId) {
    return;
  }

  state.activeSectionId.value = sectionId;
  if (!updateHash || typeof window === "undefined") {
    return;
  }

  const nextHash = `${state.hashPrefix}${sectionId}`;
  if (window.location.hash !== nextHash) {
    window.history.replaceState({}, "", nextHash);
  }
}

function shouldIgnoreObserverTick(state: ScrollSpyState): boolean {
  if (typeof window === "undefined") {
    return false;
  }
  return Date.now() - state.lastManualScrollAt < MANUAL_SCROLL_LOCK_MS;
}

function pickEntryId(
  state: ScrollSpyState,
  entries: readonly IntersectionObserverEntry[],
): string | null {
  const nextEntry = entries
    .filter((entry) => entry.isIntersecting)
    .sort((a, b) => {
      const ratioCompare = b.intersectionRatio - a.intersectionRatio;
      if (ratioCompare !== 0) {
        return ratioCompare;
      }
      return a.boundingClientRect.top - b.boundingClientRect.top;
    })[0];

  return nextEntry?.target.id || resolveFallbackSectionId(state);
}

function createObserverCallback(state: ScrollSpyState): IntersectionObserverCallback {
  return (entries) => {
    if (shouldIgnoreObserverTick(state)) {
      return;
    }

    const nextId = pickEntryId(state, entries);
    if (nextId) {
      updateActiveSection(state, nextId, true);
    }
  };
}

function refreshObserver(state: ScrollSpyState): void {
  const activeObserver = state.observer.value;
  if (!activeObserver) {
    return;
  }

  activeObserver.disconnect();
  for (const section of state.sectionNodes.values()) {
    activeObserver.observe(section);
  }
}

function startObserver(state: ScrollSpyState, options: ScrollSpyOptions): void {
  if (typeof window === "undefined" || typeof IntersectionObserver === "undefined") {
    return;
  }

  if (!state.observer.value) {
    state.observer.value = new IntersectionObserver(createObserverCallback(state), {
      root: null,
      threshold: options.threshold ?? DEFAULT_THRESHOLD,
      rootMargin: options.rootMargin ?? DEFAULT_ROOT_MARGIN,
    });
  }

  refreshObserver(state);
}

function stopObserver(state: ScrollSpyState): void {
  state.observer.value?.disconnect();
  state.observer.value = null;
}

function setSectionRef(state: ScrollSpyState, sectionId: string, element: Element | null): void {
  const previous = state.sectionNodes.get(sectionId);
  if (previous && state.observer.value) {
    state.observer.value.unobserve(previous);
  }

  if (!element) {
    state.sectionNodes.delete(sectionId);
    if (state.activeSectionId.value === sectionId) {
      state.activeSectionId.value = resolveFallbackSectionId(state) ?? "";
    }
    return;
  }

  if (element instanceof HTMLElement) {
    state.sectionNodes.set(sectionId, element);
    state.observer.value?.observe(element);
  }
}

function scrollToSection(
  state: ScrollSpyState,
  sectionId: string,
  optionsValue: {
    smooth?: boolean;
    focus?: boolean;
    updateHash?: boolean;
  } = {},
): void {
  const section = state.sectionNodes.get(sectionId);
  if (!section) {
    return;
  }

  const smooth = optionsValue.smooth ?? true;
  const focus = optionsValue.focus ?? true;
  const updateHash = optionsValue.updateHash ?? true;

  state.lastManualScrollAt = Date.now();
  updateActiveSection(state, sectionId, updateHash);
  section.scrollIntoView({
    behavior: smooth ? "smooth" : "auto",
    block: "start",
  });
  if (focus) {
    section.focus({ preventScroll: true });
  }
}

function syncFromHash(state: ScrollSpyState, hashValue: string): boolean {
  const normalizedHash = normalizeHashValue(hashValue, state.hashPrefix);
  if (!(normalizedHash && state.sectionNodes.has(normalizedHash))) {
    return false;
  }

  scrollToSection(state, normalizedHash, {
    smooth: false,
    focus: false,
    updateHash: false,
  });
  return true;
}

/**
 * Generic section-based scroll spy composable with deterministic active-id updates.
 */
export function useScrollSpy(options: ScrollSpyOptions = {}) {
  const state = createScrollSpyState(options);
  const stop = (): void => stopObserver(state);
  if (getCurrentScope()) {
    onScopeDispose(stop);
  }

  return {
    activeSectionId: readonly(state.activeSectionId),
    setSectionRef: (sectionId: string, element: Element | null) =>
      setSectionRef(state, sectionId, element),
    scrollToSection: (
      sectionId: string,
      optionsValue: {
        smooth?: boolean;
        focus?: boolean;
        updateHash?: boolean;
      } = {},
    ) => scrollToSection(state, sectionId, optionsValue),
    syncFromHash: (hashValue: string) => syncFromHash(state, hashValue),
    startObserver: () => startObserver(state, options),
    refreshObserver: () => refreshObserver(state),
    stopObserver: stop,
  };
}

import type { ComposerTranslation } from "vue-i18n";
import { assertApiResponse, withLoadingState } from "~/composables/async-flow";

interface CoverLetterGenerationInput {
  company: string;
  position: string;
  resumeId: string;
  jobId?: string;
}

interface DataActionInput {
  api: ReturnType<typeof useApi>;
  t: ComposerTranslation;
  loading: ReturnType<typeof useState<boolean>>;
}

export function createDataActions(input: DataActionInput) {
  const analyzeResume = async (resumeId: string) =>
    withLoadingState(input.loading, async () => {
      const { data, error } = await input.api.ai["analyze-resume"].post({ resumeId });
      assertApiResponse(error, input.t("apiErrors.ai.analyzeResumeFailed"));
      return data;
    });

  const generateCoverLetter = async (generationData: CoverLetterGenerationInput) =>
    withLoadingState(input.loading, async () => {
      const { data, error } = await input.api.ai["generate-cover-letter"].post(generationData);
      assertApiResponse(error, input.t("apiErrors.ai.generateCoverLetterFailed"));
      return data;
    });

  const matchJobs = async (resumeId: string) =>
    withLoadingState(input.loading, async () => {
      const { data, error } = await input.api.ai["match-jobs"].post({ resumeId });
      assertApiResponse(error, input.t("apiErrors.ai.matchJobsFailed"));
      return data;
    });

  const getModels = async () =>
    withLoadingState(input.loading, async () => {
      const { data, error } = await input.api.ai.models.get();
      assertApiResponse(error, input.t("apiErrors.ai.fetchModelsFailed"));
