import {
  BADGE_ERROR_SM_CLASS,
  BADGE_GHOST_SM_CLASS,
  BADGE_SUCCESS_SM_CLASS,
  BADGE_WARNING_SM_CLASS,
} from "~/constants/layout-badges";
import type {
  DashboardStats,
  ProviderConfig,
  ProviderConnectivityResult,
  ProviderHealth,
} from "~/types/ai-dashboard";
