} from "@bao/shared/constants/cover-letter";
import { APP_ROUTE_BUILDERS, APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import type { Ref } from "vue";
import { settlePromise } from "~/composables/async-flow";
import { getErrorMessage } from "~/utils/errors";
import type { GenerateCoverLetterInput, GenerateCoverLetterResult } from "./useCoverLetter";

export type CoverLetterGenerateForm = {
  company: string;
  position: string;
  jobDescription: string;
  resumeId: string;
  template: CoverLetterTemplate;
};

type TranslateFn = (key: string, values?: Record<string, string | number>) => string;
type ToastApi = {
  error(message: string): void;
  success(message: string): void;
};

type CoverLetterPageActionServices = {
  deleteCoverLetter(id: string): Promise<void>;
  generateCoverLetter(payload: GenerateCoverLetterInput): Promise<GenerateCoverLetterResult | null>;
  fetchCoverLetters(): Promise<void>;
  fetchResumes(): Promise<void>;
  router: { push(path: string): void };
  route: { query: Record<string, string | (string | null)[] | null | undefined> };
  $toast: ToastApi;
  t: TranslateFn;
};

type CoverLetterPageActionState = {
  showGenerateModal: Ref<boolean>;
  generating: Ref<boolean>;
  initialResumeId: Ref<string>;
  generateForm: CoverLetterGenerateForm;
  pendingDeleteId: Ref<string | null>;
  closeDeleteDialog(): void;
  searchQuery: Ref<string>;
  templateFilter: Ref<CoverLetterTemplate | "all">;
  sortOrder: Ref<"newest" | "oldest">;
};

function resetGenerateForm(state: CoverLetterPageActionState) {
  state.generateForm.company = "";
  state.generateForm.position = "";
  state.generateForm.jobDescription = "";
  state.generateForm.resumeId = state.initialResumeId.value;
  state.generateForm.template = COVER_LETTER_DEFAULT_TEMPLATE;
}

function initializeResumeSelection(
  state: Pick<CoverLetterPageActionState, "generateForm" | "initialResumeId">,
  route: CoverLetterPageActionServices["route"],
) {
  const routeResumeId = route.query[APP_ROUTE_QUERY_KEYS.resumeId];
  if (typeof routeResumeId === "string" && routeResumeId.trim().length > 0) {
    state.initialResumeId.value = routeResumeId.trim();
    state.generateForm.resumeId = state.initialResumeId.value;
  }
}

function validateGenerateForm(state: CoverLetterPageActionState, toast: ToastApi, t: TranslateFn) {
  if (state.generateForm.company.trim().length < COVER_LETTER_COMPANY_MIN_LENGTH) {
    toast.error(
      t("coverLetterPage.toasts.companyMinLength", {
        count: COVER_LETTER_COMPANY_MIN_LENGTH,
      }),
    );
    return false;
  }

  if (state.generateForm.position.trim().length < COVER_LETTER_POSITION_MIN_LENGTH) {
    toast.error(
      t("coverLetterPage.toasts.positionMinLength", {
        count: COVER_LETTER_POSITION_MIN_LENGTH,
      }),
    );
    return false;
  }

  const description = state.generateForm.jobDescription.trim();
  if (description.length > 0 && description.length < COVER_LETTER_JOB_DESCRIPTION_MIN_LENGTH) {
    toast.error(
      t("coverLetterPage.toasts.jobDescriptionMinLength", {
        count: COVER_LETTER_JOB_DESCRIPTION_MIN_LENGTH,
      }),
    );
    return false;
  }

  return true;
}

function buildGeneratePayload(state: CoverLetterPageActionState) {
  const description = state.generateForm.jobDescription.trim();
  return {
    company: state.generateForm.company.trim(),
    position: state.generateForm.position.trim(),
    resumeId:
      state.generateForm.resumeId.trim().length > 0
        ? state.generateForm.resumeId.trim()
        : undefined,
    template: state.generateForm.template,
    save: true,
    ...(description.length > 0 ? { jobInfo: { description } } : {}),
  };
}

function createEditLetterAction(services: Pick<CoverLetterPageActionServices, "router">) {
  return async (id: string) => {
    await services.router.push(APP_ROUTE_BUILDERS.coverLetterDetail(id));
  };
}

function createDeleteCoverLetterHandler(
  services: CoverLetterPageActionServices,
  state: CoverLetterPageActionState,
) {
  return async () => {
    const id = state.pendingDeleteId.value;
    if (!id) {
      return;
    }

    const deleteResult = await settlePromise(
      services.deleteCoverLetter(id),
      services.t("coverLetterPage.toasts.deleteFailed"),
    );
    state.closeDeleteDialog();

    if (!deleteResult.ok) {
      services.$toast.error(
        getErrorMessage(deleteResult.error, services.t("coverLetterPage.toasts.deleteFailed")),
      );
      return;
    }

    services.$toast.success(services.t("coverLetterPage.toasts.deleted"));
  };
}

function resolveGeneratedCoverLetterId(result: GenerateCoverLetterResult | null): string | null {
  if (!(result && "coverLetter" in result)) {
    return null;
  }

  return result.coverLetter.id ?? null;
}

function createGenerateCoverLetterHandler(
  services: CoverLetterPageActionServices,
  state: CoverLetterPageActionState,
) {
  return async () => {
    if (!validateGenerateForm(state, services.$toast, services.t)) {
      return;
    }

    state.generating.value = true;
    const generateResult = await settlePromise(
      services.generateCoverLetter(buildGeneratePayload(state)),
      services.t("coverLetterPage.toasts.generateFailed"),
    );
    state.generating.value = false;

    if (!generateResult.ok) {
      services.$toast.error(
        getErrorMessage(generateResult.error, services.t("coverLetterPage.toasts.generateFailed")),
      );
      return;
    }

    state.showGenerateModal.value = false;
    resetGenerateForm(state);
    const generatedId = resolveGeneratedCoverLetterId(generateResult.value);
    if (!generatedId) {
      services.$toast.success(services.t("coverLetterPage.toasts.generatedWithoutRedirect"));
      return;
    }

    services.$toast.success(services.t("coverLetterPage.toasts.generated"));
    await services.router.push(APP_ROUTE_BUILDERS.coverLetterDetail(generatedId));
  };
}

export function createCoverLetterActions(
  services: CoverLetterPageActionServices,
  state: CoverLetterPageActionState,
) {
  const clearFilters = () => {
    state.searchQuery.value = "";
    state.templateFilter.value = "all";
    state.sortOrder.value = "newest";
  };

  const coverLetterPageAria = (page: number) =>
    services.t("coverLetterPage.pagination.pageAria", { page });

  return {
    clearFilters,
    coverLetterPageAria,
    editLetter: createEditLetterAction(services),
    handleDeleteCoverLetter: createDeleteCoverLetterHandler(services, state),
    handleGenerate: createGenerateCoverLetterHandler(services, state),
  };
}

export function useCoverLetterPageBootstrap(
  services: Pick<
    CoverLetterPageActionServices,
    "fetchCoverLetters" | "fetchResumes" | "route" | "$toast" | "t"
  >,
  state: Pick<CoverLetterPageActionState, "generateForm" | "initialResumeId">,
) {
  return useAsyncData("cover-letter-page-bootstrap", async () => {
    initializeResumeSelection(state, services.route);
    const [coverLettersResult, resumesResult] = await Promise.all([
      settlePromise(services.fetchCoverLetters(), services.t("coverLetterPage.toasts.fetchFailed")),
      settlePromise(services.fetchResumes(), services.t("apiErrors.resumes.fetchListFailed")),
    ]);

    if (!coverLettersResult.ok) {
      const failure = getErrorMessage(
        coverLettersResult.error,
        services.t("coverLetterPage.toasts.fetchFailed"),
      );
      services.$toast.error(failure);
      throw coverLettersResult.error;
    }

    if (!resumesResult.ok) {
      const failure = getErrorMessage(
        resumesResult.error,
        services.t("apiErrors.resumes.fetchListFailed"),
      );
      services.$toast.error(failure);
      throw resumesResult.error;
    }

    return true;
  });
}

import { buildResumeExportEndpoint } from "@bao/shared/constants/endpoints";
import type { ResumeTemplate } from "@bao/shared/constants/resume";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { ResumeData } from "@bao/shared/types/resume";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import type { ClientApi } from "~/types/client-api";
import { readRequiredApiPayload } from "~/utils/api-response";
import { toResumeData } from "./api-normalizer-resume";
import {
  type ClientApiRequestRuntime,
  downloadApiFile,
  useClientApiRequestRuntime,
} from "./api-request";
import { requireValue, withLoadingState } from "./async-flow";
import { useApi } from "./useApi";

type CreateResumeInput = Record<string, unknown>;
type UpdateResumeInput = Record<string, unknown>;
type ExportResumeInput = Record<string, unknown>;
type ScoreResumeInput = {
  jobId: string;
};
type ScoreResumeError = {
  details?: string;
  error: string;
};
type ScoreResumeSuccess = {
  [key: string]: unknown;
  details?: unknown;
  error?: undefined;
  score?: unknown;
};

type ResumeSynthesisSuccess = Partial<ResumeData> & {
  id: string;
  name?: string;
  personalInfo?: ResumeData["personalInfo"];
};

type ResumeSynthesisError = {
  error?: string;
  details?: string;
};

interface ResumeContext {
  api: ClientApi;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  resumes: ReturnType<typeof useState<ResumeData[]>>;
  currentResume: ReturnType<typeof useState<ResumeData | null>>;
  runtime: ClientApiRequestRuntime;
}

interface ResumeExportRequest {
  id: string;
  template?: ResumeTemplate;
  format?: string;
}

const isResumeSynthesisError = (value: unknown): value is ResumeSynthesisError =>
  isRecord(value) && typeof value.error === "string";

const isResumeSynthesisSuccess = (value: unknown): value is ResumeSynthesisSuccess =>
  isRecord(value) && "id" in value && typeof value.id === "string";

const isResumeScoreError = (value: unknown): value is ScoreResumeError =>
  isRecord(value) && typeof value.error === "string";

const isResumeScoreSuccess = (value: unknown): value is ScoreResumeSuccess =>
  isRecord(value) && !("error" in value);

function toResumeList(value: unknown): ResumeData[] {
  return Array.isArray(value)
    ? value
        .map((entry) => toResumeData(entry))
        .filter((entry): entry is ResumeData => entry !== null)
    : [];
}

function toExportPayload(template?: ResumeTemplate, format?: string): ExportResumeInput {
  const payload: ExportResumeInput = {};
  if (template) {
    payload.template = template;
  }
  if (format) {
    payload.format = format;
  }
  return payload;
}

async function fetchResumes(context: ResumeContext): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.resumes.get(),
      context.t("apiErrors.resumes.fetchListFailed"),
    );
    context.resumes.value = toResumeList(data);
  });
}

async function getResume(context: ResumeContext, id: string): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.resumes({ id }).get(),
      context.t("apiErrors.resumes.fetchFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    context.currentResume.value = normalized;
    return normalized;
  });
}

async function createResume(
  context: ResumeContext,
  resumeData: CreateResumeInput,
): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.resumes.post(resumeData),
      context.t("apiErrors.resumes.createFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    await fetchResumes(context);
    return normalized;
  });
}

async function updateResume(
  context: ResumeContext,
  id: string,
  updates: UpdateResumeInput,
): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.resumes({ id }).put(updates),
      context.t("apiErrors.resumes.updateFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    context.currentResume.value = normalized;
    await fetchResumes(context);
    return normalized;
  });
}

async function deleteResume(context: ResumeContext, id: string): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await readRequiredApiPayload(
      context.api.resumes({ id }).delete(),
      context.t("apiErrors.resumes.deleteFailed"),
    );
    if (context.currentResume.value?.id === id) {
      context.currentResume.value = null;
    }
    await fetchResumes(context);
  });
}

async function performExportResume(
  context: ResumeContext,
  request: ResumeExportRequest,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await downloadApiFile(
      context.runtime,
      buildResumeExportEndpoint(request.id),
      {
        method: "POST",
        body: toExportPayload(request.template, request.format),
      },
      `resume-${request.id}.${request.format === "docx" ? "docx" : "pdf"}`,
    );
  });
}

async function exportResume(
  context: ResumeContext,
  id: string,
  template?: ResumeTemplate,
  format?: string,
): Promise<unknown> {
  return performExportResume(context, {
    id,
    template,
    format,
  });
}

async function exportResumeOnePage(
  context: ResumeContext,
  id: string,
  template?: ResumeTemplate,
  format?: string,
): Promise<unknown> {
  return performExportResume(context, {
    id,
    template,
    format,
  });
}

async function aiEnhance(context: ResumeContext, id: string): Promise<ResumeData> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.resumes({ id })["ai-enhance"].post({}),
      context.t("apiErrors.resumes.enhanceFailed"),
    );
    const normalized = requireValue(
      toResumeData(data),
      context.t("apiErrors.resumes.invalidPayload"),
    );
    context.currentResume.value = normalized;
    await fetchResumes(context);
    return normalized;
  });
}

async function aiScore(
  context: ResumeContext,
  id: string,
  jobId: string,
): Promise<ScoreResumeSuccess> {
  return withLoadingState(context.loading, async () => {
    const payload: ScoreResumeInput = { jobId };
    const data = await readRequiredApiPayload(
      context.api.resumes({ id })["ai-score"].post(payload),
      context.t("apiErrors.resumes.scoreFailed"),
    );
    if (isResumeScoreError(data)) {
      throw new Error(
        String(data.details ?? data.error ?? context.t("apiErrors.resumes.scoreFailed")),
      );
    }
    if (!isResumeScoreSuccess(data)) {
      throw new Error(context.t("apiErrors.resumes.scoreFailed"));
    }
    return data;
  });
}

async function generateCvQuestions(
  context: ResumeContext,
  config: {
    targetRole: string;
    studioName?: string;
    experienceLevel?: string;
  },
): Promise<Array<{ id: string; question: string; category: string }>> {
  const data = await readRequiredApiPayload(
    context.api.resumes["from-questions"].generate.post(config),
    context.t("apiErrors.resumes.fetchFailed"),
  );
  if (!isRecord(data) || !Array.isArray(data.questions)) {
    return [];
  }
  return data.questions.filter(
    (entry): entry is { id: string; question: string; category: string } =>
      isRecord(entry) &&
      typeof entry.id === "string" &&
      typeof entry.question === "string" &&
      typeof entry.category === "string",
  );
}

async function synthesizeCvResume(
  context: ResumeContext,
  questionsAndAnswers: Array<{ id: string; question: string; answer: string; category: string }>,
): Promise<ResumeSynthesisSuccess> {
  const response = await readRequiredApiPayload(
    context.api.resumes["from-questions"].synthesize.post({ questionsAndAnswers }),
    context.t("apiErrors.resumes.createFailed"),
  );

  if (isResumeSynthesisError(response) && response.error) {
    throw new Error(String(response.details ?? response.error ?? "Unknown error"));
  }
  if (!isResumeSynthesisSuccess(response)) {
    throw new Error("Resume synthesis payload is missing an id");
  }

  return response;
}

/**
 * Resume management composable — Eden JSON fabric; binary export stays downloadApiFile.
 */
export function useResume() {
  const context: ResumeContext = {
    api: useApi(),
    t: useI18n().t,
    runtime: useClientApiRequestRuntime(),
    resumes: useState<ResumeData[]>(STATE_KEYS.RESUME_LIST, () => []),
    currentResume: useState<ResumeData | null>(STATE_KEYS.RESUME_CURRENT, () => null),
    loading: useState(STATE_KEYS.RESUME_LOADING, () => false),
  };

  return {
    resumes: readonly(context.resumes),
    currentResume: readonly(context.currentResume),
    loading: readonly(context.loading),
    fetchResumes: () => fetchResumes(context),
    getResume: (id: string) => getResume(context, id),
    createResume: (resumeData: CreateResumeInput) => createResume(context, resumeData),
    updateResume: (id: string, updates: UpdateResumeInput) => updateResume(context, id, updates),
    deleteResume: (id: string) => deleteResume(context, id),
    exportResume: (id: string, template?: ResumeTemplate, format?: string) =>
      exportResume(context, id, template, format),
    exportResumeOnePage: (id: string, template?: ResumeTemplate, format?: string) =>
      exportResumeOnePage(context, id, template, format),
    aiEnhance: (id: string) => aiEnhance(context, id),
    aiScore: (id: string, jobId: string) => aiScore(context, id, jobId),
    generateCvQuestions: (config: {
      targetRole: string;
      studioName?: string;
      experienceLevel?: string;
    }) => generateCvQuestions(context, config),
    synthesizeCvResume: (
      questionsAndAnswers: Array<{
        id: string;
        question: string;
        answer: string;
        category: string;
      }>,
    ) => synthesizeCvResume(context, questionsAndAnswers),
  };
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { GameStudio } from "@bao/shared/types/interview";
import { useI18n } from "vue-i18n";
import type { ClientApi } from "~/types/client-api";
import { readRequiredApiPayload } from "~/utils/api-response";
import { toGameStudio } from "./api-normalizer-studios";
import { requireValue, withLoadingState } from "./async-flow";
import { useApi } from "./useApi";

interface StudioContext {
  api: ClientApi;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  studios: ReturnType<typeof useState<GameStudio[]>>;
  currentStudio: ReturnType<typeof useState<GameStudio | null>>;
}

type CreateStudioInput = {
  [key: string]: unknown;
};
type UpdateStudioInput = {
  [key: string]: unknown;
};

const toStudioList = (value: unknown): GameStudio[] =>
  Array.isArray(value)
    ? value
        .map((entry) => toGameStudio(entry))
        .filter((entry): entry is GameStudio => entry !== null)
    : [];

function createReadStudioActions(context: StudioContext) {
  const searchStudios = async (query?: Record<string, string>) =>
    withLoadingState(context.loading, async () => {
      const data = await readRequiredApiPayload(
        context.api.studios.get({ query: query || {} }),
        context.t("apiErrors.studios.searchFailed"),
      );
      context.studios.value = toStudioList(data);
    });

  const getStudio = async (id: string) =>
    withLoadingState(context.loading, async () => {
      const data = await readRequiredApiPayload(
        context.api.studios({ id }).get(),
        context.t("apiErrors.studios.fetchFailed"),
      );
      const normalized = requireValue(
        toGameStudio(data),
        context.t("apiErrors.studios.invalidPayload"),
      );
      context.currentStudio.value = normalized;
      return normalized;
    });

  return {
    searchStudios,
    getStudio,
  };
}

function createWriteStudioActions(
  context: StudioContext,
  searchStudios: (query?: Record<string, string>) => Promise<void>,
) {
  const createStudio = async (studioData: CreateStudioInput) =>
    withLoadingState(context.loading, async () => {
      const data = await readRequiredApiPayload(
        context.api.studios.post(studioData),
        context.t("apiErrors.studios.createFailed"),
      );
      const normalized = requireValue(
        toGameStudio(data),
        context.t("apiErrors.studios.invalidPayload"),
      );
      await searchStudios();
      return normalized;
    });

  const updateStudio = async (id: string, updates: UpdateStudioInput) =>
    withLoadingState(context.loading, async () => {
      const data = await readRequiredApiPayload(
        context.api.studios({ id }).put(updates),
        context.t("apiErrors.studios.updateFailed"),
      );
      const normalized = requireValue(
        toGameStudio(data),
        context.t("apiErrors.studios.invalidPayload"),
      );
      context.currentStudio.value = normalized;
      await searchStudios();
      return normalized;
    });

  const deleteStudio = async (id: string) =>
    withLoadingState(context.loading, async () => {
      await readRequiredApiPayload(
        context.api.studios({ id }).delete(),
        context.t("apiErrors.studios.deleteFailed"),
      );
      if (context.currentStudio.value?.id === id) {
        context.currentStudio.value = null;
      }
      await searchStudios();
    });

  return {
    createStudio,
    updateStudio,
    deleteStudio,
  };
}

/**
 * Studio discovery composable — Eden fabric. Analytics page owns api.studios.analytics.
 */
export function useStudio() {
  const context: StudioContext = {
    api: useApi(),
    t: useI18n().t,
    studios: useState<GameStudio[]>(STATE_KEYS.STUDIOS_LIST, () => []),
    currentStudio: useState<GameStudio | null>(STATE_KEYS.STUDIO_CURRENT, () => null),
    loading: useState(STATE_KEYS.STUDIO_LOADING, () => false),
  };

  const readActions = createReadStudioActions(context);
  const writeActions = createWriteStudioActions(context, readActions.searchStudios);

  return {
    studios: readonly(context.studios),
    studio: readonly(context.currentStudio),
    currentStudio: readonly(context.currentStudio),
    loading: readonly(context.loading),
    searchStudios: readActions.searchStudios,
    fetchStudios: readActions.searchStudios,
    getStudio: readActions.getStudio,
    fetchStudioById: readActions.getStudio,
    createStudio: writeActions.createStudio,
    updateStudio: writeActions.updateStudio,
    deleteStudio: writeActions.deleteStudio,
  };
}

import type { UserProfile } from "@bao/shared/types/user";
import {
  asBoolean,
  asNumber,
  asRecord,
  asString,
  asStringArray,
  isRecord,
} from "@bao/shared/utils/type-guards";
import { asEnum, asEnumArray } from "~/composables/api-normalizer-shared";

const USER_EXPERIENCE_LEVELS: readonly Exclude<
  UserProfile["gamingExperience"]["experienceLevel"],
  undefined
>[] = ["entry", "junior", "mid", "senior", "lead", "principal", "director"];

const USER_GAMING_SPECIALIZATIONS: readonly UserProfile["gamingExperience"]["specializations"][number][] =
  [
    "game-programming",
    "gameplay-programming",
    "engine-programming",
    "graphics-programming",
    "ai-programming",
    "ui-programming",
    "network-programming",
    "tools-programming",
    "game-design",
    "level-design",
    "narrative-design",
    "systems-design",
    "ui-ux-design",
    "3d-art",
    "2d-art",
    "concept-art",
    "character-art",
    "environment-art",
    "vfx-art",
    "animation",
    "rigging",
    "technical-art",
    "audio-design",
    "sound-engineering",
    "music-composition",
    "quality-assurance",
    "production",
    "project-management",
    "marketing",
    "community-management",
    "business-development",
    "data-analytics",
  ];

const USER_REMOTE_PREFERENCES: readonly NonNullable<
  UserProfile["careerGoals"]["remotePreference"]
>[] = ["onsite", "hybrid", "remote", "flexible"];

const toUserShippedTitle = (
  value: Record<string, unknown>,
): UserProfile["gamingExperience"]["shippedTitles"][number] => ({
  name: asString(value.name) ?? "",
  platforms: asStringArray(value.platforms),
  releaseDate: asString(value.releaseDate),
  role: asString(value.role) ?? "",
  teamSize: asNumber(value.teamSize),
});

const normalizeUserSalaryRange = (value: unknown): UserProfile["careerGoals"]["salaryRange"] => {
  const salaryRange = asRecord(value);
  if (!salaryRange) {
    return;
  }

  const min = asNumber(salaryRange.min);
  const max = asNumber(salaryRange.max);
  if (min === undefined || max === undefined) {
    return;
  }

  return {
    min,
    max,
    currency: asString(salaryRange.currency),
  };
};

const normalizeUserCareerGoals = (value: unknown): UserProfile["careerGoals"] => {
  const careerGoals = asRecord(value) ?? {};
  const remotePreference = asEnum(careerGoals.remotePreference, USER_REMOTE_PREFERENCES);
  const salaryRange = normalizeUserSalaryRange(careerGoals.salaryRange);

  return {
    desiredRoles: asStringArray(careerGoals.desiredRoles),
    preferredCompanySize: asStringArray(careerGoals.preferredCompanySize),
    preferredLocations: asStringArray(careerGoals.preferredLocations),
    willingToRelocate: asBoolean(careerGoals.willingToRelocate),
    ...(remotePreference ? { remotePreference } : {}),
    ...(salaryRange ? { salaryRange } : {}),
  };
};

const normalizeUserGamingExperience = (value: unknown): UserProfile["gamingExperience"] => {
  const gamingExperience = asRecord(value) ?? {};
  const shippedTitles = Array.isArray(gamingExperience.shippedTitles)
    ? gamingExperience.shippedTitles
        .map((entry) => (isRecord(entry) ? toUserShippedTitle(entry) : null))
        .filter(
          (entry): entry is UserProfile["gamingExperience"]["shippedTitles"][number] =>
            entry !== null,
        )
    : [];

  return {
    yearsInGaming: asNumber(gamingExperience.yearsInGaming),
    experienceLevel: asEnum(gamingExperience.experienceLevel, USER_EXPERIENCE_LEVELS),
    specializations: asEnumArray(gamingExperience.specializations, USER_GAMING_SPECIALIZATIONS),
    gameEngines: asStringArray(gamingExperience.gameEngines),
    platforms: asStringArray(gamingExperience.platforms),
    genres: asStringArray(gamingExperience.genres),
    shippedTitles,
  };
};

export const toUserProfile = (value: unknown): UserProfile | null => {
  if (!isRecord(value)) return null;

  return {
    id: asString(value.id) ?? "default",
    name: asString(value.name) ?? "",
    email: asString(value.email),
    phone: asString(value.phone),
    location: asString(value.location),
    website: asString(value.website),
    linkedin: asString(value.linkedin),
    github: asString(value.github),
    summary: asString(value.summary),
    currentRole: asString(value.currentRole),
    currentCompany: asString(value.currentCompany),
    yearsExperience: asNumber(value.yearsExperience),
    technicalSkills: asStringArray(value.technicalSkills),
    softSkills: asStringArray(value.softSkills),
    gamingExperience: normalizeUserGamingExperience(value.gamingExperience),
    careerGoals: normalizeUserCareerGoals(value.careerGoals),
  };
};

import { normalizeAIRouting } from "@bao/shared/constants/ai-provider";
import { normalizeAppDataTheme, resolveBrandSettings } from "@bao/shared/constants/branding";
import { DEFAULT_JOB_TAXONOMY_SETTINGS } from "@bao/shared/constants/jobs-taxonomy";
import { APP_LANGUAGE_CODES, DEFAULT_APP_LANGUAGE } from "@bao/shared/constants/settings";
import type { JobTaxonomySettings } from "@bao/shared/types/jobs-taxonomy";
import type { AppSettings, EmailTransportSettings } from "@bao/shared/types/settings-contracts";
import {
  DEFAULT_APP_AI_ROUTING,
  DEFAULT_EMAIL_TRANSPORT_SETTINGS,
} from "@bao/shared/types/settings-defaults";
import { normalizeLocalModelEndpoint } from "@bao/shared/types/settings-normalization";
import {
  asBoolean,
  asNumber,
  asRecord,
  asString,
  asStringArray,
  isRecord,
} from "@bao/shared/utils/type-guards";
import { normalizeAutomationSettings } from "~/composables/api-normalizer-settings-automation";
import {
  JOB_TAXONOMY_CATEGORIES,
  JOB_TAXONOMY_STUDIO_TYPES,
} from "~/composables/api-normalizer-settings-constants";
import {
  asEnum,
  isProviderId,
  normalizeAIProvider,
  normalizeProviderDiagnosticCode,
} from "~/composables/api-normalizer-shared";

const normalizeAIRoutingValue = (
  value: unknown,
  preferredProvider: ReturnType<typeof normalizeAIProvider>,
) => {
  if (!isRecord(value)) return normalizeAIRouting(DEFAULT_APP_AI_ROUTING, preferredProvider);
  return normalizeAIRouting(
    Object.fromEntries(
      Object.entries(value).flatMap(([purpose, target]) =>
        !isRecord(target)
          ? []
          : [
              [
                purpose,
                { provider: normalizeAIProvider(target.provider), model: asString(target.model) },
              ],
            ],
      ),
    ),
    preferredProvider,
  );
};

const normalizeProviderDiagnostics = (value: unknown) => {
  if (!isRecord(value)) return;
  return Object.fromEntries(
    Object.entries(value).flatMap(([providerId, entry]) =>
      !(isProviderId(providerId) && isRecord(entry))
        ? []
        : [
            [
              providerId,
              {
                provider: normalizeAIProvider(entry.provider ?? providerId),
                code: normalizeProviderDiagnosticCode(entry.code),
                checkedAt: asString(entry.checkedAt) ?? new Date(0).toISOString(),
                endpoint: asString(entry.endpoint),
                selectedModel: asString(entry.selectedModel),
                availableModels: asStringArray(entry.availableModels),
                message: asString(entry.message),
              },
            ],
          ],
    ),
  );
};

const normalizeEmailTransportSettings = (value: unknown): EmailTransportSettings | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const security =
    value.security === "tls" || value.security === "plain" ? value.security : "starttls";
  const authMethod = value.authMethod === "login" ? "login" : "plain";

  return {
    host: asString(value.host) ?? DEFAULT_EMAIL_TRANSPORT_SETTINGS.host,
    port: asNumber(value.port) ?? DEFAULT_EMAIL_TRANSPORT_SETTINGS.port,
    security,
    username: asString(value.username) ?? DEFAULT_EMAIL_TRANSPORT_SETTINGS.username,
    fromEmail: asString(value.fromEmail) ?? DEFAULT_EMAIL_TRANSPORT_SETTINGS.fromEmail,
    fromName: asString(value.fromName) ?? DEFAULT_EMAIL_TRANSPORT_SETTINGS.fromName,
    authMethod,
    connectionTimeoutSeconds:
      asNumber(value.connectionTimeoutSeconds) ??
      DEFAULT_EMAIL_TRANSPORT_SETTINGS.connectionTimeoutSeconds,
  };
};

const normalizeJobTaxonomySettings = (value: unknown): JobTaxonomySettings | undefined => {
  if (!isRecord(value)) return;
  const keywords = Array.isArray(value.keywords)
    ? value.keywords.filter(isRecord).map((entry, index) => ({
        id: asString(entry.id) ?? `keyword-${index}`,
        category: asEnum(entry.category, JOB_TAXONOMY_CATEGORIES) ?? "technology",
        label: asString(entry.label) ?? "",
        synonyms: asStringArray(entry.synonyms),
        sortOrder: asNumber(entry.sortOrder) ?? index,
        enabled: asBoolean(entry.enabled) ?? true,
      }))
    : DEFAULT_JOB_TAXONOMY_SETTINGS.keywords;
  const studioRules = Array.isArray(value.studioRules)
    ? value.studioRules.filter(isRecord).map((entry, index) => ({
        id: asString(entry.id) ?? `studio-rule-${index}`,
        studioType: asEnum(entry.studioType, JOB_TAXONOMY_STUDIO_TYPES) ?? "Indie",
        keyword: asString(entry.keyword) ?? "",
        sortOrder: asNumber(entry.sortOrder) ?? index,
        enabled: asBoolean(entry.enabled) ?? true,
      }))
    : DEFAULT_JOB_TAXONOMY_SETTINGS.studioRules;
  return { keywords, studioRules };
};

export const toAppSettings = (value: unknown): AppSettings | null => {
  if (!isRecord(value)) return null;
  const id = asString(value.id);
  if (!id) return null;

  const notificationsRecord = asRecord(value.notifications) ?? {};
  const preferredProvider = normalizeAIProvider(value.preferredProvider);
  return {
    id,
    geminiApiKey: asString(value.geminiApiKey),
    openaiApiKey: asString(value.openaiApiKey),
    claudeApiKey: asString(value.claudeApiKey),
    huggingfaceToken: asString(value.huggingfaceToken),
    localModelEndpoint:
      normalizeLocalModelEndpoint(asString(value.localModelEndpoint)) ?? undefined,
    localModelName: asString(value.localModelName),
    aiRouting: normalizeAIRoutingValue(value.aiRouting, preferredProvider),
    providerDiagnostics: normalizeProviderDiagnostics(value.providerDiagnostics),
    preferredModel: asString(value.preferredModel),
    preferredProvider,
    theme: normalizeAppDataTheme(asString(value.theme)),
    language: asEnum(value.language, APP_LANGUAGE_CODES) ?? DEFAULT_APP_LANGUAGE,
    brandSettings: resolveBrandSettings(isRecord(value.brandSettings) ? value.brandSettings : null),
    notifications: {
      achievements: asBoolean(notificationsRecord.achievements) ?? true,
      dailyChallenges: asBoolean(notificationsRecord.dailyChallenges) ?? true,
      levelUp: asBoolean(notificationsRecord.levelUp) ?? true,
      jobAlerts: asBoolean(notificationsRecord.jobAlerts) ?? true,
    },
    automationSettings: normalizeAutomationSettings(value.automationSettings),
    jobTaxonomy: normalizeJobTaxonomySettings(value.jobTaxonomy),
    emailTransportSettings: normalizeEmailTransportSettings(value.emailTransportSettings),
    hasGeminiKey: asBoolean(value.hasGeminiKey),
    hasOpenaiKey: asBoolean(value.hasOpenaiKey),
    hasClaudeKey: asBoolean(value.hasClaudeKey),
    hasHuggingfaceToken: asBoolean(value.hasHuggingfaceToken),
    hasEmailTransportPassword: asBoolean(value.hasEmailTransportPassword),
    hasLocalKey: asBoolean(value.hasLocalKey),
  };
};

import type { DashboardStats } from "@bao/shared/types/search";
import type { Ref } from "vue";
import type { SetupAuthStatus } from "~/components/setup/setup-page-contracts";
import { settlePromise } from "~/composables/async-flow";
import type { ApiEnvelope } from "~/types/client-api-contracts";
import { getErrorMessage } from "~/utils/errors";

interface SetupPageSettingsSnapshot {
  localModelEndpoint?: string | null;
  localModelName?: string | null;
}

interface SetupPageBootstrapContext {
  authStatus: Ref<SetupAuthStatus | null>;
  checkAuthStatus: () => Promise<SetupAuthStatus>;
  dashboardStats: Ref<DashboardStats | null>;
  fetchDashboardStats: () => Promise<ApiEnvelope<DashboardStats>>;
  fetchSettings: () => Promise<void>;
  localModelEndpoint: Ref<string>;
  localModelName: Ref<string>;
  settings: Ref<SetupPageSettingsSnapshot | null>;
  t: (key: string) => string;
}

const applyLocalModelFields = (ctx: SetupPageBootstrapContext): void => {
  if (ctx.settings.value?.localModelEndpoint) {
    ctx.localModelEndpoint.value = ctx.settings.value.localModelEndpoint;
  }
  if (ctx.settings.value?.localModelName) {
    ctx.localModelName.value = ctx.settings.value.localModelName;
  }
};

const loadDashboardStats = async (ctx: SetupPageBootstrapContext): Promise<void> => {
  const statsResult = await settlePromise(
    ctx.fetchDashboardStats(),
    ctx.t("apiErrors.statistics.fetchDashboardFailed"),
  );
  ctx.dashboardStats.value =
    statsResult.ok && !statsResult.value.error ? statsResult.value.data : null;
};

const runSetupBootstrap = async (
  ctx: SetupPageBootstrapContext,
): Promise<{ initialized: true }> => {
  // Auth first: bootstrap/setup must not require authenticated /api/settings.
  const authStatusResult = await settlePromise(
    ctx.checkAuthStatus(),
    ctx.t("apiErrors.auth.initFailed"),
  );
  if (!authStatusResult.ok) {
    throw new Error(getErrorMessage(authStatusResult.error, ctx.t("apiErrors.auth.initFailed")));
  }
  ctx.authStatus.value = authStatusResult.value;

  const needsBootstrap = authStatusResult.value.bootstrapRequired === true;
  const settingsResult = await settlePromise(
    needsBootstrap || ctx.settings.value ? Promise.resolve() : ctx.fetchSettings(),
    ctx.t("apiErrors.settings.fetchFailed"),
  );
  if (!settingsResult.ok) {
    throw new Error(getErrorMessage(settingsResult.error, ctx.t("apiErrors.settings.fetchFailed")));
  }

  applyLocalModelFields(ctx);

  if (needsBootstrap) {
    ctx.dashboardStats.value = null;
  } else {
    await loadDashboardStats(ctx);
  }

  return { initialized: true };
};

export function useSetupPageBootstrap(ctx: SetupPageBootstrapContext) {
  const { error, refresh, status } = useAsyncData("setup-bootstrap", () => runSetupBootstrap(ctx), {
    server: true,
    lazy: false,
  });

  return {
    setupBootstrapError: error,
    setupBootstrapPending: computed(() => status.value === "pending" || status.value === "idle"),
    refreshSetupBootstrap: refresh,
  };
}

import { APP_ROUTES } from "@bao/shared/constants/routes";
import type { AIChatContext, AIChatContextSource, ChatMessage } from "@bao/shared/types/ai";
import { generateId } from "@bao/shared/utils/validation";
import type { ComposerTranslation } from "vue-i18n";
import { assertApiResponse, settlePromise, withLoadingState } from "~/composables/async-flow";
import { useChatRealtime } from "~/composables/useChatRealtime";
import { parseJobApplyAutomationAction } from "~/utils/ai-automation-action";
import { createChatMessage } from "~/utils/chat";

type AIChatResponse = {
  message?: string;
  id?: string;
  sessionId?: string;
  timestamp?: string;
  provider?: string;
  model?: string;
};

interface SendMessageOptions {
  source?: AIChatContextSource;
}

interface ChatActionInput {
  api: ReturnType<typeof useApi>;
  t: ComposerTranslation;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
  loading: ReturnType<typeof useState<boolean>>;
  streaming: ReturnType<typeof useState<boolean>>;
  streamingContent: ReturnType<typeof useState<string>>;
  messages: ReturnType<typeof useState<ChatMessage[]>>;
  sessionId: ReturnType<typeof useState<string>>;
  buildAssistantGreetingMessage: () => ChatMessage;
  buildCurrentContext: (source?: AIChatContextSource) => AIChatContext;
  unableToProcessFallback: () => string;
  requestErrorFallback: () => string;
}

function parseAIChatResponse(data: unknown): AIChatResponse {
  const response: AIChatResponse = {};
  if (!(data && typeof data === "object")) {
    return response;
  }

  if ("message" in data && typeof data.message === "string") {
    response.message = data.message;
  }
  if ("id" in data && typeof data.id === "string") {
    response.id = data.id;
  }
  if ("sessionId" in data && typeof data.sessionId === "string") {
    response.sessionId = data.sessionId;
  }
  if ("timestamp" in data && typeof data.timestamp === "string") {
    response.timestamp = data.timestamp;
  }
  if ("provider" in data && typeof data.provider === "string") {
    response.provider = data.provider;
  }
  if ("model" in data && typeof data.model === "string") {
    response.model = data.model;
  }

  return response;
}

function pushUserMessage(input: ChatActionInput, content: string): void {
  input.messages.value.push(
    createChatMessage({
      role: "user",
      content,
      sessionId: input.sessionId.value,
      timestamp: new Date().toISOString(),
    }),
  );
}

function pushAssistantMessage(input: ChatActionInput, response: AIChatResponse): void {
  input.messages.value.push(
    createChatMessage({
      role: "assistant",
      content: response.message || input.unableToProcessFallback(),
      id: response.id,
      sessionId: response.sessionId ?? input.sessionId.value,
      timestamp: response.timestamp ?? new Date().toISOString(),
      provider: response.provider,
      model: response.model,
    }),
  );
}

async function requestAIChatResponseHttp(
  input: ChatActionInput,
  content: string,
  source?: AIChatContextSource,
): Promise<AIChatResponse> {
  const { data, error } = await input.api.ai.chat.post({
    message: content,
    sessionId: input.sessionId.value,
    context: input.buildCurrentContext(source),
  });
  assertApiResponse(error, input.t("apiErrors.ai.sendMessageFailed"));

  const response = parseAIChatResponse(data);
  if (typeof response.sessionId === "string" && response.sessionId.length > 0) {
    input.sessionId.value = response.sessionId;
  }
  pushAssistantMessage(input, response);
  return response;
}

async function requestAIChatResponseRealtime(
  input: ChatActionInput,
  content: string,
  chatRealtime: ReturnType<typeof useChatRealtime>,
): Promise<AIChatResponse | null> {
  input.streamingContent.value = "";
  const streamResult = await settlePromise(
    chatRealtime.sendStreamingMessage({
      content,
      sessionId: input.sessionId.value,
      onChunk: (chunk) => {
        input.streamingContent.value += chunk;
      },
      onSessionId: (sessionId) => {
        input.sessionId.value = sessionId;
      },
    }),
    input.t("aiChatCommon.requestErrorToast"),
  );
  if (!streamResult.ok) {
    return null;
  }
  const fullText = streamResult.value.fullText.trim();
  const response: AIChatResponse = {
    message: fullText.length > 0 ? fullText : input.unableToProcessFallback(),
    sessionId: streamResult.value.sessionId,
    timestamp: new Date().toISOString(),
  };
  input.sessionId.value = streamResult.value.sessionId;
  pushAssistantMessage(input, response);
  return response;
}

async function executeDetectedAutomationAction(
  input: ChatActionInput,
  response: AIChatResponse,
): Promise<void> {
  const action = parseJobApplyAutomationAction(response.message ?? "");
  if (!action) {
    return;
  }
  const { data, error } = await input.api.ai["automation-action"].post(action);
  if (error) {
    input.toast.error(input.t("aiChatCommon.automationActionFailed"));
    return;
  }
  const runId =
    data && typeof data === "object" && "runId" in data && typeof data.runId === "string"
      ? data.runId
      : "";
  if (!runId) {
    input.toast.error(input.t("aiChatCommon.automationActionFailed"));
    return;
  }
  input.toast.success(input.t("aiChatCommon.automationActionStarted", { runId }));
  input.messages.value.push(
    createChatMessage({
      role: "assistant",
      content: `${input.t("aiChatCommon.automationActionStarted", { runId })} ${input.t("aiChatCommon.automationActionOpenRuns")}: ${APP_ROUTES.automationRuns}`,
      sessionId: input.sessionId.value,
      timestamp: new Date().toISOString(),
    }),
  );
}

export function createChatActions(input: ChatActionInput) {
  const chatRealtime = useChatRealtime();

  const sendMessage = async (content: string, options: SendMessageOptions = {}) => {
    pushUserMessage(input, content);
    input.streaming.value = true;
    input.streamingContent.value = "";

    const realtimeResult = await settlePromise(
      withLoadingState(input.loading, () =>
        requestAIChatResponseRealtime(input, content, chatRealtime),
      ),
      input.t("aiChatCommon.requestErrorToast"),
    );

    let response: AIChatResponse | null = null;
    if (realtimeResult.ok && realtimeResult.value) {
      response = realtimeResult.value;
    } else {
      const httpResult = await settlePromise(
        withLoadingState(input.loading, () =>
          requestAIChatResponseHttp(input, content, options.source),
        ),
        input.t("aiChatCommon.requestErrorToast"),
      );
      if (httpResult.ok) {
        response = httpResult.value;
      }
    }

    input.streaming.value = false;
    input.streamingContent.value = "";

    if (!response) {
      input.toast.error(input.t("aiChatCommon.requestErrorToast"));
      input.messages.value.push(
        createChatMessage({
          role: "assistant",
          content: input.requestErrorFallback(),
          sessionId: input.sessionId.value,
          timestamp: new Date().toISOString(),
        }),
      );
      return null;
    }

    await settlePromise(
      executeDetectedAutomationAction(input, response),
      input.t("aiChatCommon.automationActionFailed"),
    );
    return response;
  };

  const clearMessages = (): void => {
    input.sessionId.value = generateId();
    input.messages.value = [input.buildAssistantGreetingMessage()];
    input.streamingContent.value = "";
  };

  return {
    sendMessage,
    clearMessages,
  };
}

/**
 * Live WebSocket subscription wiring for the automation runs list.
 */
import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import type { Ref } from "vue";
import { onBeforeUnmount, watch } from "vue";
import { isLiveRun, mergeRunWithEvent } from "~/composables/automation-runs-page-merge";
import type { useAutomation } from "~/composables/useAutomation";

type SubscribeToRun = ReturnType<typeof useAutomation>["subscribeToRun"];
/** AsyncData/ref runs list — value may be undefined while pending. */
type RunsList = Ref<RpaRunExecutionEnvelope[] | null | undefined>;

export function useAutomationRunsLiveSync(
  runs: RunsList,
  subscribeToRun: SubscribeToRun,
  liveRunById: Ref<Record<string, RpaRunExecutionEnvelope>>,
): void {
  const activeSubscriptions = new Map<string, () => void>();

  const unsubscribeRun = (runId: string): void => {
    const unsubscribe = activeSubscriptions.get(runId);
    if (!unsubscribe) {
      return;
    }
    unsubscribe();
    activeSubscriptions.delete(runId);
  };

  const clearSubscriptions = (): void => {
    for (const [runId, unsubscribe] of activeSubscriptions.entries()) {
      unsubscribe();
      activeSubscriptions.delete(runId);
    }
  };

  const subscribeRun = (run: RpaRunExecutionEnvelope): void => {
    if (!isLiveRun(run) || activeSubscriptions.has(run.id)) {
      return;
    }
    const unsubscribe = subscribeToRun(run.id, (event) => {
      const currentRun =
        liveRunById.value[event.runId] || runs.value?.find((item) => item.id === event.runId);
      if (!currentRun) {
        return;
      }
      const mergedRun = mergeRunWithEvent(currentRun, event);
      liveRunById.value = {
        ...liveRunById.value,
        [event.runId]: mergedRun,
      };
      if (!isLiveRun(mergedRun)) {
        unsubscribeRun(event.runId);
      }
    });
    activeSubscriptions.set(run.id, unsubscribe);
  };

  const syncSubscriptions = (nextRuns: readonly RpaRunExecutionEnvelope[]): void => {
    const liveRunIds = new Set(nextRuns.filter((run) => isLiveRun(run)).map((run) => run.id));
    for (const runId of activeSubscriptions.keys()) {
      if (!liveRunIds.has(runId)) {
        unsubscribeRun(runId);
      }
    }
    for (const run of nextRuns) {
      subscribeRun(run);
    }
  };

  watch(
    () => (runs.value || []).map((run) => liveRunById.value[run.id] || run),
    (nextRuns) => {
      syncSubscriptions(nextRuns);
    },
    { immediate: true },
  );

  onBeforeUnmount(() => {
    clearSubscriptions();
  });
}

import type {
  ResumeData,
  ResumeEducationItem,
  ResumeExperienceItem,
  ResumeProject,
} from "@bao/shared/types/resume";
import {
  asBoolean,
  asRecord,
