import type { useI18n } from "vue-i18n";
import { formatDateWithLocale } from "~/utils/locale-format";
import { parseInterviewHistoryDurationMinutes } from "./interview-history-page-state";

export const createInterviewHistoryFormatters = (
  t: ReturnType<typeof useI18n>["t"],
  localeValue: () => unknown,
  fallbackLocaleValue: () => unknown,
) => {
  const formatDate = (value: string | undefined): string => {
    if (!value || value.length === 0) {
      return t("interviewHistory.notAvailable");
    }

    const formattedDate = formatDateWithLocale(value, localeValue(), fallbackLocaleValue(), {
      dateStyle: "medium",
    });
    return formattedDate ?? t("interviewHistory.notAvailable");
  };

  const formatDuration = (value: number | string | null): string => {
    if (typeof value === "number" && Number.isFinite(value)) {
      return t("interviewHistory.minutesLabel", { count: value });
    }

    if (typeof value === "string") {
      const parsedMinutes = parseInterviewHistoryDurationMinutes(value);
      if (parsedMinutes !== null) {
        return t("interviewHistory.minutesLabel", { count: parsedMinutes });
      }
    }

    return t("interviewHistory.notAvailable");
  };

  const formatScore = (value: number | undefined): string =>
    Number.isFinite(value ?? Number.NaN) ? `${value}%` : t("interviewHistory.notAvailable");

  const questionScoreText = (score: number | undefined): number =>
    Number.isFinite(score ?? Number.NaN) ? (score ?? 0) : 0;

  return {
    formatDate,
    formatDuration,
    formatScore,
    questionScoreText,
  };
};

export const createInterviewHistoryScoreState = () => {
  const {
    getScoreBadgeClass: scoreBadgeClass,
    getScoreColorClass,
    getTimelineLineClass,
  } = useScoreColor();

  return {
    scoreBadgeClass,
    getScoreColorClass,
    getTimelineLineClass,
  };
};

import {
  SKILL_CATEGORY_IDS,
  type SkillCategory,
  type SkillMapping,
} from "@bao/shared/types/skill-mapping";
import type { ComputedRef, Ref } from "vue";
import {
  SKILLS_CATEGORY_LABEL_KEYS,
  SKILLS_FILTER_ALL_VALUE,
  SKILLS_TOP_MAPPINGS_PREVIEW_LIMIT,
} from "~/constants/skills";

type SkillsFilterValue = typeof SKILLS_FILTER_ALL_VALUE | SkillCategory;

type SkillsPageDerivedInput = {
  mappings: Ref<SkillMapping[]>;
  categoryFilter: Ref<SkillsFilterValue>;
  searchFilter: Ref<string>;
  level: Ref<number>;
  xp: Ref<number>;
  t: (key: string) => string;
};

function createSkillCategoryOptions(t: SkillsPageDerivedInput["t"]) {
  return computed(() =>
    SKILL_CATEGORY_IDS.map((value) => ({
      value,
      label: t(SKILLS_CATEGORY_LABEL_KEYS[value]),
    })),
  );
}

function createFilteredMappings({
  mappings,
  categoryFilter,
  searchFilter,
}: Pick<SkillsPageDerivedInput, "mappings" | "categoryFilter" | "searchFilter">) {
  return computed(() => {
    const normalizedSearch = searchFilter.value.trim().toLowerCase();
    return mappings.value.filter((mapping) => {
      const categoryMatches =
        categoryFilter.value === SKILLS_FILTER_ALL_VALUE ||
        mapping.category === categoryFilter.value;
      if (!categoryMatches) {
        return false;
      }

      if (normalizedSearch.length === 0) {
        return true;
      }

      const searchableContent = [
        mapping.gameExpression,
        mapping.transferableSkill,
        ...mapping.industryApplications,
      ]
        .join(" ")
        .toLowerCase();

      return searchableContent.includes(normalizedSearch);
    });
  });
}

function createMappingMetrics(mappings: SkillsPageDerivedInput["mappings"]) {
  return computed(() => {
    const total = mappings.value.length;
    const confidenceTotal = mappings.value.reduce((accumulator, mapping) => {
      const confidenceValue = Number.isFinite(mapping.confidence) ? mapping.confidence : 0;
      return accumulator + confidenceValue;
    }, 0);

    return {
      total,
      averageConfidence: total > 0 ? Math.round(confidenceTotal / total) : 0,
      aiGeneratedCount: mappings.value.filter((mapping) => mapping.aiGenerated).length,
      categoriesUsed: new Set(mappings.value.map((mapping) => mapping.category)).size,
    };
  });
}

function createTopMappings(filteredMappings: ComputedRef<SkillMapping[]>) {
  return computed(() =>
    [...filteredMappings.value]
      .sort((left, right) => right.confidence - left.confidence)
      .slice(0, SKILLS_TOP_MAPPINGS_PREVIEW_LIMIT),
  );
}

function createGamificationSummary({
  mappings,
  categoryFilter,
  searchFilter,
  level,
  xp,
}: SkillsPageDerivedInput) {
  return {
    gamificationLevel: computed(() => level.value),
    gamificationXP: computed(() => xp.value),
    hasMappings: computed(() => mappings.value.length > 0),
    hasActiveFilters: computed(
      () =>
        categoryFilter.value !== SKILLS_FILTER_ALL_VALUE || searchFilter.value.trim().length > 0,
    ),
  };
}

export function createSkillsPageDerived(input: SkillsPageDerivedInput) {
  const categoryOptions = createSkillCategoryOptions(input.t);
  const filteredMappings = createFilteredMappings(input);
  const mappingMetrics = createMappingMetrics(input.mappings);
  const topMappings = createTopMappings(filteredMappings);
  const summary = createGamificationSummary(input);

  function clearFilters(): void {
    input.categoryFilter.value = SKILLS_FILTER_ALL_VALUE;
    input.searchFilter.value = "";
  }

  return {
    categoryOptions,
    clearFilters,
    filteredMappings,
    mappingMetrics,
    topMappings,
    ...summary,
  };
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import {
  type CareerPathway,
  type ReadinessAssessment,
  SKILL_READINESS_FEEDBACK_IDS,
  SKILL_READINESS_IMPROVEMENT_IDS,
  SKILL_READINESS_NEXT_STEP_IDS,
  type SkillMapping,
  type SkillReadinessFeedbackId,
  type SkillReadinessImprovementId,
  type SkillReadinessNextStepId,
} from "@bao/shared/types/skill-mapping";
import {
  asJsonArray,
  asNumber,
  asString,
  asStringArray,
  isRecord,
} from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import { toSkillMapping } from "./api-normalizer-skills";
import { assertApiResponse, withLoadingState } from "./async-flow";
import { readRequiredApiPayload } from "~/utils/api-response";

type ApiClient = ReturnType<typeof useApi>;
type CreateMappingInput = NonNullable<Parameters<ApiClient["skills"]["mappings"]["post"]>[0]>;
type MappingRoute = ReturnType<ApiClient["skills"]["mappings"]>;
type UpdateMappingInput = NonNullable<Parameters<MappingRoute["put"]>[0]>;

type ReadinessCategory = ReadinessAssessment["categories"]["technical"];

interface SkillMappingContext {
  api: ApiClient;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  mappings: ReturnType<typeof useState<SkillMapping[]>>;
  pathways: ReturnType<typeof useState<CareerPathway[]>>;
  readiness: ReturnType<typeof useState<ReadinessAssessment | null>>;
}

const SKILL_READINESS_FEEDBACK_ID_SET = new Set<string>(SKILL_READINESS_FEEDBACK_IDS);
const SKILL_READINESS_IMPROVEMENT_ID_SET = new Set<string>(SKILL_READINESS_IMPROVEMENT_IDS);
const SKILL_READINESS_NEXT_STEP_ID_SET = new Set<string>(SKILL_READINESS_NEXT_STEP_IDS);

function isSkillReadinessFeedbackId(value: string): value is SkillReadinessFeedbackId {
  return SKILL_READINESS_FEEDBACK_ID_SET.has(value);
}

function toSkillReadinessFeedbackId(value: unknown): SkillReadinessFeedbackId | null {
  const feedbackId = asString(value);
  if (!(feedbackId && isSkillReadinessFeedbackId(feedbackId))) {
    return null;
  }
  return feedbackId;
}

function toSkillReadinessImprovementIds(value: unknown): SkillReadinessImprovementId[] {
  return asStringArray(value).filter((entry): entry is SkillReadinessImprovementId =>
    SKILL_READINESS_IMPROVEMENT_ID_SET.has(entry),
  );
}

function toSkillReadinessNextStepIds(value: unknown): SkillReadinessNextStepId[] {
  return asStringArray(value).filter((entry): entry is SkillReadinessNextStepId =>
    SKILL_READINESS_NEXT_STEP_ID_SET.has(entry),
  );
}

function toCareerSalary(value: unknown): CareerPathway["averageSalary"] {
  if (isRecord(value) && typeof value.min === "number" && typeof value.max === "number") {
    return {
      min: value.min,
      max: value.max,
      currency: asString(value.currency),
    };
  }
}

function toCareerStage(entry: unknown): CareerPathway["stages"][number] | null {
  if (!isRecord(entry)) {
    return null;
  }

  const title = asString(entry.title);
  const duration = asString(entry.duration);
  const description = asString(entry.description);
  if (!(title && duration && description)) {
    return null;
  }

  const stage: CareerPathway["stages"][number] = { title, duration, description };
  if (typeof entry.completed === "boolean") {
    stage.completed = entry.completed;
  }
  if (typeof entry.current === "boolean") {
    stage.current = entry.current;
  }

  const requirements = asStringArray(entry.requirements);
  const outcomes = asStringArray(entry.outcomes);
  if (requirements.length > 0) {
    stage.requirements = requirements;
  }
  if (outcomes.length > 0) {
    stage.outcomes = outcomes;
  }

  return stage;
}

function toCareerPathway(value: unknown): CareerPathway | null {
  if (!isRecord(value)) {
    return null;
  }

  const id = asString(value.id);
  const title = asString(value.title);
  const description = asString(value.description);
  const estimatedTimeToEntry = asString(value.estimatedTimeToEntry);
  if (!(id && title && description && estimatedTimeToEntry)) {
    return null;
  }

  const stages = Array.isArray(value.stages)
    ? value.stages
        .map((entry) => toCareerStage(entry))
        .filter((entry): entry is CareerPathway["stages"][number] => entry !== null)
    : [];
  const trend = value.jobMarketTrend;

  return {
    id,
    title,
    description,
    detailedDescription: asString(value.detailedDescription),
    matchScore: asNumber(value.matchScore) ?? 0,
    stages,
    requiredSkills: asStringArray(value.requiredSkills),
    estimatedTimeToEntry,
    icon: asString(value.icon),
    averageSalary: toCareerSalary(value.averageSalary),
    jobMarketTrend:
      trend === "growing" || trend === "stable" || trend === "declining" ? trend : "stable",
  };
}

function toReadinessCategory(entry: unknown): ReadinessCategory | null {
  if (!isRecord(entry)) {
    return null;
  }

  const score = asNumber(entry.score);
  const feedbackId = toSkillReadinessFeedbackId(entry.feedbackId);
  if (score === undefined || feedbackId === null) {
    return null;
  }

  return {
    score,
    feedbackId,
    strengths: asStringArray(entry.strengths),
    improvements: toSkillReadinessImprovementIds(entry.improvements),
  };
}

function toTargetRoleReadiness<T>(
  value: T,
): NonNullable<ReadinessAssessment["targetRoleReadiness"]> {
  const entries = asJsonArray(value);
  if (!entries) {
    return [];
  }

  const readinessEntries: NonNullable<ReadinessAssessment["targetRoleReadiness"]> = [];
  for (const entry of entries) {
    if (!isRecord(entry)) {
      continue;
    }
    const roleId = asString(entry.roleId);
    const roleTitle = asString(entry.roleTitle);
    if (!(roleId && roleTitle)) {
      continue;
    }

    const readiness: NonNullable<ReadinessAssessment["targetRoleReadiness"]>[number] = {
      roleId,
      roleTitle,
      readinessScore: asNumber(entry.readinessScore) ?? 0,
      missingSkills: asStringArray(entry.missingSkills),
      matchingSkills: asStringArray(entry.matchingSkills),
      recommendedActions: asStringArray(entry.recommendedActions),
    };
    const timeToReady = asString(entry.timeToReady);
    if (timeToReady) {
      readiness.timeToReady = timeToReady;
    }
    readinessEntries.push(readiness);
  }
  return readinessEntries;
}

function toReadinessAssessment(value: unknown): ReadinessAssessment | null {
  if (!(isRecord(value) && isRecord(value.categories))) {
    return null;
  }

  const technical = toReadinessCategory(value.categories.technical);
  const softSkills = toReadinessCategory(value.categories.softSkills);
  const industryKnowledge = toReadinessCategory(value.categories.industryKnowledge);
  const portfolio = toReadinessCategory(value.categories.portfolio);
  if (!(technical && softSkills && industryKnowledge && portfolio)) {
    return null;
  }

  const targetRoleReadiness = toTargetRoleReadiness(value.targetRoleReadiness);
  return {
    overallScore: asNumber(value.overallScore) ?? 0,
    categories: {
      technical,
      softSkills,
      industryKnowledge,
      portfolio,
    },
    improvementSuggestions: toSkillReadinessImprovementIds(value.improvementSuggestions),
    nextSteps: toSkillReadinessNextStepIds(value.nextSteps),
    targetRoleReadiness: targetRoleReadiness.length > 0 ? targetRoleReadiness : undefined,
  };
}

function createSkillMappingActions(context: SkillMappingContext) {
  const loadMappings = async (): Promise<void> => {
    const data = await readRequiredApiPayload(
      context.api.skills.mappings.get(),
      context.t("apiErrors.skills.fetchMappingsFailed"),
    );
    context.mappings.value = Array.isArray(data)
      ? data
          .map((entry) => toSkillMapping(entry))
          .filter((entry): entry is SkillMapping => entry !== null)
      : [];
  };

  const fetchMappings = (): Promise<void> => withLoadingState(context.loading, loadMappings);

  const createMapping = (mappingData: CreateMappingInput): Promise<void> =>
    withLoadingState(context.loading, async () => {
      await readRequiredApiPayload(
        context.api.skills.mappings.post(mappingData),
        context.t("apiErrors.skills.createMappingFailed"),
      );
      await loadMappings();
    });

  const updateMapping = (id: string, updates: UpdateMappingInput): Promise<void> =>
    withLoadingState(context.loading, async () => {
      await readRequiredApiPayload(
        context.api.skills.mappings({ id }).put(updates),
        context.t("apiErrors.skills.updateMappingFailed"),
      );
      await loadMappings();
    });

  const deleteMapping = (id: string): Promise<void> =>
    withLoadingState(context.loading, async () => {
      const { error } = await context.api.skills.mappings({ id }).delete();
      assertApiResponse(error, context.t("apiErrors.skills.deleteMappingFailed"));
      await loadMappings();
    });

  return {
    fetchMappings,
    createMapping,
    updateMapping,
    deleteMapping,
  };
}

function createSkillInsightActions(context: SkillMappingContext) {
  const fetchPathways = async () =>
    withLoadingState(context.loading, async () => {
      const data = await readRequiredApiPayload(
        context.api.skills.pathways.get(),
        context.t("apiErrors.skills.fetchPathwaysFailed"),
      );
      context.pathways.value = Array.isArray(data)
        ? data
            .map((entry) => toCareerPathway(entry))
            .filter((entry): entry is CareerPathway => entry !== null)
        : [];
    });

  const fetchReadiness = async () =>
    withLoadingState(context.loading, async () => {
      const data = await readRequiredApiPayload(
        context.api.skills.readiness.get(),
        context.t("apiErrors.skills.fetchReadinessFailed"),
      );
      context.readiness.value = toReadinessAssessment(data);
    });

  const aiAnalyze = async (skills: string[]) =>
    withLoadingState(context.loading, async () => {
      return readRequiredApiPayload(
        context.api.skills["ai-analyze"].post({
          gameExperience: { skills },
        }),
        context.t("apiErrors.skills.analyzeFailed"),
      );
    });

  const extractFromText = async (text: string) =>
    withLoadingState(context.loading, async () => {
      return readRequiredApiPayload(
        context.api.skills["ai-analyze"].post({
          resume: { experience: text },
        }),
        context.t("apiErrors.skills.extractFailed"),
      );
    });

  const compareWithJob = async (jobId: string) =>
    withLoadingState(context.loading, async () => {
      return readRequiredApiPayload(
        context.api.skills.readiness.get({ query: { jobId } }),
        context.t("apiErrors.skills.compareFailed"),
      );
    });

  return {
    fetchPathways,
    fetchReadiness,
    aiAnalyze,
    extractFromText,
    compareWithJob,
  };
}

/**
 * Skill mapping and pathway management composable.
 */
export function useSkillMapping() {
  const context: SkillMappingContext = {
    api: useApi(),
    t: useI18n().t,
    mappings: useState<SkillMapping[]>(STATE_KEYS.SKILLS_MAPPINGS, () => []),
    pathways: useState<CareerPathway[]>(STATE_KEYS.SKILLS_PATHWAYS, () => []),
    readiness: useState<ReadinessAssessment | null>(STATE_KEYS.SKILLS_READINESS, () => null),
    loading: useState(STATE_KEYS.SKILLS_LOADING, () => false),
  };

  return {
    mappings: readonly(context.mappings),
    pathways: readonly(context.pathways),
    readiness: readonly(context.readiness),
    loading: readonly(context.loading),
    ...createSkillMappingActions(context),
    ...createSkillInsightActions(context),
  };
}

import type { DailyChallenge, UserGamificationData } from "@bao/shared/types/gamification";
import type { DashboardStats } from "@bao/shared/types/search";
import { isRecord } from "@bao/shared/utils/type-guards";
import type {
  DailyChallengesResponse,
  DashboardActivity,
  DashboardChallengeViewModel,
  DashboardViewModel,
} from "~/components/dashboard/dashboard-page-contracts";
import { toUserProfile } from "~/composables/api-normalizer-user";
import { requireValue } from "~/composables/async-flow";
import { DASHBOARD_ACTIVITY_FALLBACK_KEY, DASHBOARD_ERROR_KEYS } from "~/constants/dashboard-copy";
import { DASHBOARD_RECENT_ACTIVITY_LIMIT } from "~/constants/dashboard-core";
import {
  resolveDashboardActivityActionLabelKey,
  resolveDashboardActivityType,
} from "~/constants/dashboard-pipeline";
import type { ApiEnvelope } from "~/types/client-api-contracts";
import { getErrorMessage } from "~/utils/errors";

/** Untrusted API payload entering a boundary decoder — narrowed by isRecord. */
type ApiPayload = Parameters<typeof isRecord>[0];

type TranslateFn = (key: string, values?: Record<string, string | number>) => string;

function resolveActivityDescription(action: string, t: TranslateFn): string {
  const actionLabelKey = resolveDashboardActivityActionLabelKey(action);
  if (actionLabelKey) {
    return t(`dashboard.activityActions.${actionLabelKey}`);
  }
  const activityType = resolveDashboardActivityType(action);
  return t(`dashboard.activityTypes.${activityType}`);
}

function mapDailyChallenge(challenge: DailyChallenge): DashboardChallengeViewModel {
  const goal = typeof challenge.goal === "number" && challenge.goal > 0 ? challenge.goal : 1;
  let progress = 0;
  if (typeof challenge.progress === "number") {
    progress = challenge.progress;
  } else if (challenge.completed) {
    progress = goal;
  }

  return {
    id: challenge.id,
    name: challenge.name,
    xpReward: challenge.xpReward,
    completed: challenge.completed,
    progress,
    goal,
  };
}

function pickDailyChallenge(
  challenges: readonly DailyChallenge[],
): DashboardChallengeViewModel | null {
  if (challenges.length === 0) {
    return null;
  }

  const currentChallenge = challenges.find((challenge) => !challenge.completed) ?? challenges[0];
  return currentChallenge ? mapDailyChallenge(currentChallenge) : null;
}

function getRecentActivity(
  progress: UserGamificationData | null,
  t: TranslateFn,
): DashboardActivity[] {
  const statsValue = progress?.stats;
  if (!isRecord(statsValue)) {
    return [];
  }

  const actionHistory = statsValue.actionHistory;
  if (!Array.isArray(actionHistory)) {
    return [];
  }

  return actionHistory
    .slice(-DASHBOARD_RECENT_ACTIVITY_LIMIT)
    .reverse()
    .map((entry): DashboardActivity | null => {
      if (!isRecord(entry)) {
        return null;
      }

      const action =
        typeof entry.action === "string" ? entry.action : t(DASHBOARD_ACTIVITY_FALLBACK_KEY);
      const timestampRaw = typeof entry.timestamp === "string" ? entry.timestamp : "";
      const timestamp = timestampRaw ? new Date(timestampRaw) : new Date();
      if (Number.isNaN(timestamp.getTime())) {
        return null;
      }

      return {
        type: resolveDashboardActivityType(action),
        description: resolveActivityDescription(action, t),
        timestamp,
      };
    })
    .filter((entry): entry is DashboardActivity => entry !== null);
}

async function requestData<T>(
  request: Promise<ApiEnvelope<T>>,
  fallbackMessage: string,
): Promise<T> {
  const response = await request;
  if (response.error) {
    throw new Error(getErrorMessage(response.error, fallbackMessage));
  }
  if (response.data == null) {
    throw new Error(fallbackMessage);
  }
  return response.data;
}

export async function fetchDashboardViewModel(
  api: ReturnType<typeof useApi>,
  t: TranslateFn,
): Promise<DashboardViewModel> {
  const [profile, stats, gamification, challengeResponse] = await Promise.all([
    requestData<ApiPayload>(
      api.user.profile.get(),
      t(DASHBOARD_ERROR_KEYS.profileLoadFallback),
    ).then((rawProfile) =>
      requireValue(toUserProfile(rawProfile), t(DASHBOARD_ERROR_KEYS.profileLoadFallback)),
    ),
    requestData<DashboardStats>(
      api.stats.dashboard.get(),
      t(DASHBOARD_ERROR_KEYS.metricsLoadFallback),
    ),
    requestData<UserGamificationData>(
      api.gamification.progress.get(),
      t(DASHBOARD_ERROR_KEYS.gamificationLoadFallback),
    ),
    requestData<DailyChallengesResponse>(
      api.gamification.challenges.get(),
      t(DASHBOARD_ERROR_KEYS.challengesLoadFallback),
    ),
  ]);

  return {
    profile,
    gamification,
    dailyChallenge: pickDailyChallenge(challengeResponse.challenges),
    recentActivity: getRecentActivity(gamification, t),
    metrics: {
      profileCompleteness: stats.profile.completeness,
      savedJobs: stats.jobs.saved,
      appliedJobs: stats.jobs.applied,
      resumeCount: stats.resumes.count,
      coverLetterCount: stats.coverLetters.count,
      portfolioProjectCount: stats.portfolio.projectCount,
      automationRuns: stats.automation.totalRuns,
      successfulAutomationRuns: stats.automation.successfulRuns,
      mappedSkillsCount: stats.skills.mappedCount,
      interviewSessionCount: stats.interviews.totalSessions,
    },
  };
}

export function isDashboardEmpty(viewModel: DashboardViewModel): boolean {
  return (
    viewModel.metrics.savedJobs === 0 &&
    viewModel.metrics.appliedJobs === 0 &&
    viewModel.metrics.resumeCount === 0 &&
    viewModel.metrics.coverLetterCount === 0 &&
    viewModel.metrics.automationRuns === 0 &&
    viewModel.metrics.mappedSkillsCount === 0 &&
    viewModel.metrics.interviewSessionCount === 0 &&
    viewModel.dailyChallenge === null &&
    viewModel.recentActivity.length === 0
  );
}

export function toFlowStats(viewModel: DashboardViewModel): DashboardStats {
  return {
    profile: {
      completeness: viewModel.metrics.profileCompleteness,
    },
    jobs: {
      saved: viewModel.metrics.savedJobs,
      applied: viewModel.metrics.appliedJobs,
      interviewing: 0,
      offered: 0,
    },
    resumes: {
      count: viewModel.metrics.resumeCount,
      lastUpdated: null,
    },
    coverLetters: {
      count: viewModel.metrics.coverLetterCount,
    },
    portfolio: {
      projectCount: viewModel.metrics.portfolioProjectCount,
    },
    interviews: {
      totalSessions: viewModel.metrics.interviewSessionCount,
      averageScore: null,
    },
    skills: {
      mappedCount: viewModel.metrics.mappedSkillsCount,
    },
    gamification: {
      level: viewModel.gamification?.level ?? 0,
      xp: viewModel.gamification?.xp ?? 0,
      achievements: viewModel.gamification?.achievements.length ?? 0,
      streak: viewModel.gamification?.currentStreak ?? 0,
    },
    ai: {
      chatMessages: 0,
      chatSessions: 0,
    },
    automation: {
      totalRuns: viewModel.metrics.automationRuns,
      successfulRuns: viewModel.metrics.successfulAutomationRuns,
      successRate: 0,
      todayRuns: 0,
      recentRuns: [],
    },
  };
}

import { buildCoverLetterExportEndpoint } from "@bao/shared/constants/endpoints";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { CoverLetterData } from "@bao/shared/types/cover-letter";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import type { ClientApi } from "~/types/client-api";
import { readRequiredApiPayload } from "~/utils/api-response";
import { toCoverLetterData } from "./api-normalizer-cover-letter";
import {
  type ClientApiRequestRuntime,
  downloadApiFile,
  useClientApiRequestRuntime,
} from "./api-request";
import { useApi } from "./useApi";

/** Untrusted API payload entering a boundary decoder — narrowed by isRecord. */
type ApiPayload = Parameters<typeof isRecord>[0];

interface CreateCoverLetterInput {
  company: string;
  position: string;
  jobInfo?: Record<string, string>;
  content?: CoverLetterData["content"];
  template?: CoverLetterData["template"];
}

type UpdateCoverLetterInput = Partial<CreateCoverLetterInput>;

export interface GenerateCoverLetterInput {
  company: string;
  position: string;
  resumeId?: string;
  template?: CoverLetterData["template"];
  save?: boolean;
  jobInfo?: Record<string, string>;
}

export type GenerateCoverLetterResult =
  | {
      message: string;
      content: CoverLetterData["content"];
    }
  | {
      message: string;
      coverLetter: CoverLetterData;
    };

interface CoverLetterContext {
  api: ClientApi;
  runtime: ClientApiRequestRuntime;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  coverLetters: ReturnType<typeof useState<CoverLetterData[]>>;
  currentLetter: ReturnType<typeof useState<CoverLetterData | null>>;
}

const toCoverLetterContent = (value: ApiPayload): CoverLetterData["content"] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const content: CoverLetterData["content"] = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "string") {
      content[key] = entry;
    }
  }

  return Object.keys(content).length > 0 ? content : null;
};

const toGenerateCoverLetterResult = (value: ApiPayload): GenerateCoverLetterResult | null => {
  if (!isRecord(value)) {
    return null;
  }

  const message = typeof value.message === "string" ? value.message : "";
  const content = toCoverLetterContent(value.content);
  if (content) {
    return { message, content };
  }

  const coverLetter = toCoverLetterData(value.coverLetter);
  if (!coverLetter) {
    return null;
  }

  return {
    message,
    coverLetter,
  };
};

async function fetchCoverLetters(context: CoverLetterContext): Promise<void> {
  context.loading.value = true;
  const data = await readRequiredApiPayload(
    context.api["cover-letters"].get(),
    context.t("coverLetterPage.toasts.fetchFailed"),
  );
  context.loading.value = false;

  const rows = Array.isArray(data) ? data : [];
  context.coverLetters.value = rows
    .map((row) => toCoverLetterData(row))
    .filter((row): row is CoverLetterData => row !== null);
}

async function getCoverLetter(
  context: CoverLetterContext,
  id: string,
): Promise<CoverLetterData | null> {
  context.loading.value = true;
  const data = await readRequiredApiPayload(
    context.api["cover-letters"]({ id }).get(),
    context.t("coverLetterDetailPage.toasts.loadFailed"),
  );
  context.loading.value = false;

  const normalized = toCoverLetterData(data);
  if (!normalized) {
    context.toast.error(context.t("coverLetterDetailPage.toasts.loadFailed"));
    return null;
  }

  context.currentLetter.value = normalized;
  return normalized;
}

async function createCoverLetter(
  context: CoverLetterContext,
  letterData: CreateCoverLetterInput,
): Promise<CoverLetterData | null> {
  context.loading.value = true;
  const data = await readRequiredApiPayload(
    context.api["cover-letters"].post(letterData),
    context.t("coverLetterPage.toasts.generateFailed"),
  );
  context.loading.value = false;

  const normalized = toCoverLetterData(data);
  if (!normalized) {
    context.toast.error(context.t("coverLetterPage.toasts.generateFailed"));
    return null;
  }

  await fetchCoverLetters(context);
  return normalized;
}

async function updateCoverLetter(
  context: CoverLetterContext,
  id: string,
  updates: UpdateCoverLetterInput,
): Promise<CoverLetterData | null> {
  context.loading.value = true;
  const data = await readRequiredApiPayload(
    context.api["cover-letters"]({ id }).put(updates),
    context.t("coverLetterDetailPage.toasts.saveFailed"),
  );
  context.loading.value = false;

  const normalized = toCoverLetterData(data);
  if (normalized) {
    context.currentLetter.value = normalized;
  }
  await fetchCoverLetters(context);
  return normalized;
}

async function deleteCoverLetter(context: CoverLetterContext, id: string): Promise<void> {
  context.loading.value = true;
  const { error } = await context.api["cover-letters"]({ id }).delete();
  if (error) {
    context.loading.value = false;
    throw new Error(context.t("coverLetterDetailPage.toasts.saveFailed"));
  }
  context.loading.value = false;

  if (context.currentLetter.value?.id === id) {
    context.currentLetter.value = null;
  }
  await fetchCoverLetters(context);
}

async function generateCoverLetter(
  context: CoverLetterContext,
  generationData: GenerateCoverLetterInput,
): Promise<GenerateCoverLetterResult | null> {
  context.loading.value = true;
  const data = await readRequiredApiPayload(
    context.api["cover-letters"].generate.post(generationData),
    context.t("coverLetterPage.toasts.generateFailed"),
  );
  context.loading.value = false;

  if (generationData.save) {
    await fetchCoverLetters(context);
  }
  return toGenerateCoverLetterResult(data);
}

async function exportDocument(
  context: CoverLetterContext,
  id: string,
  format?: string,
): Promise<void> {
  context.loading.value = true;
  // Binary download stays on downloadApiFile (Eden Treaty JSON envelope unsuitable for blobs).
  await downloadApiFile(
    context.runtime,
    buildCoverLetterExportEndpoint(id),
    {
      method: "POST",
      body: format ? { format } : {},
    },
    `cover-letter-${id}.${format === "docx" ? "docx" : "pdf"}`,
  );
  context.loading.value = false;
}

/**
 * Cover letter management composable — Eden Treaty for JSON CRUD/generate.
 */
export function useCoverLetter() {
  const context: CoverLetterContext = {
    api: useApi(),
    runtime: useClientApiRequestRuntime(),
    toast: useNuxtApp().$toast,
    t: useI18n().t,
    coverLetters: useState<CoverLetterData[]>(STATE_KEYS.COVERLETTERS_LIST, () => []),
    currentLetter: useState<CoverLetterData | null>(STATE_KEYS.COVERLETTER_CURRENT, () => null),
    loading: useState(STATE_KEYS.COVERLETTER_LOADING, () => false),
  };

  return {
    coverLetters: readonly(context.coverLetters),
    currentLetter: readonly(context.currentLetter),
    loading: readonly(context.loading),
    fetchCoverLetters: () => fetchCoverLetters(context),
    getCoverLetter: (id: string) => getCoverLetter(context, id),
    createCoverLetter: (letterData: CreateCoverLetterInput) =>
      createCoverLetter(context, letterData),
    updateCoverLetter: (id: string, updates: UpdateCoverLetterInput) =>
      updateCoverLetter(context, id, updates),
    deleteCoverLetter: (id: string) => deleteCoverLetter(context, id),
    generateCoverLetter: (generationData: GenerateCoverLetterInput) =>
      generateCoverLetter(context, generationData),
    exportDocument: (id: string, format?: string) => exportDocument(context, id, format),
  };
}

import type { RpaRunEvent, RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import type { AutomationRunUiState } from "@bao/shared/schemas/rpa-protocol.schema";
import { isRecord } from "@bao/shared/utils/type-guards";
import { getCurrentScope, onScopeDispose, type Ref, readonly, ref } from "vue";
import automationJobApplyCatalog from "~/locales/en-US/automation/jobApply";
import { PERCENT_MAX } from "~/constants/numeric-ui";
import { useAutomation } from "./useAutomation";
import {
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_TOO_MANY_REQUESTS,
  HTTP_STATUS_UNAUTHORIZED,
} from "@bao/shared/constants/http";

type ApiPayload = Parameters<typeof isRecord>[0];

const TERMINAL_STATUSES = new Set<RpaRunExecutionEnvelope["status"]>(["success", "error"]);
const PROGRESS_STATUS_TO_RUN_STATUS = {
  pending: "pending",
  running: "running",
  success: "running",
  error: "error",
} as const satisfies Record<
  Extract<RpaRunEvent, { eventType: "progress" }>["status"],
  RpaRunExecutionEnvelope["status"]
>;

type StreamError = {
  message: string;
  statusCode?: number;
};

type StreamStateRefs = {
  state: Ref<AutomationRunUiState>;
  run: Ref<RpaRunExecutionEnvelope | null>;
  events: Ref<RpaRunEvent[]>;
  streamError: Ref<StreamError | null>;
  isStreaming: Ref<boolean>;
  activeRunId: Ref<string>;
  lastSequenceByRunId: Ref<Record<string, number>>;
};

type StreamLifecycle = {
  requestToken: number;
  unsubscribe: (() => void) | null;
};

type EventApplyResult = {
  nextRun: RpaRunExecutionEnvelope;
  nextState: AutomationRunUiState;
  shouldStop: boolean;
};

interface StreamDependencies {
  refs: StreamStateRefs;
  lifecycle: StreamLifecycle;
  getRun: ReturnType<typeof useAutomation>["getRun"];
  subscribeToRun: ReturnType<typeof useAutomation>["subscribeToRun"];
  fallbackMessage: string;
}

interface UseAutomationRunStreamOptions {
  fallbackMessage?: string;
}

const toStreamError = (error: ApiPayload, fallbackMessage: string): StreamError => {
  if (!isRecord(error)) {
    return { message: fallbackMessage };
  }

  const message =
    typeof error.message === "string" && error.message.length > 0 ? error.message : fallbackMessage;
  let statusCode: number | undefined;
  if (typeof error.status === "number") {
    statusCode = error.status;
  } else if (typeof error.statusCode === "number") {
    statusCode = error.statusCode;
  }

  return { message, statusCode };
};

const toUiStateFromError = (error: StreamError): AutomationRunUiState => {
  if (error.statusCode === HTTP_STATUS_UNAUTHORIZED) {
    return "unauthorized";
  }
  if (
    !error.statusCode ||
    error.statusCode >= HTTP_STATUS_INTERNAL_SERVER_ERROR ||
    error.statusCode === HTTP_STATUS_TOO_MANY_REQUESTS
  ) {
    return "errorRetryable";
  }
  return "errorNonRetryable";
};

const toUiStateFromRun = (run: RpaRunExecutionEnvelope): AutomationRunUiState => {
  if (run.status === "success") {
    return "success";
  }
  if (run.status === "error") {
    return "errorNonRetryable";
  }
  if (run.status === "pending" || run.status === "running") {
    return "loading";
  }
  return "idle";
};

const computeProgressPercent = (step: number | null, totalSteps: number | null): number | null => {
  if (typeof step !== "number" || typeof totalSteps !== "number" || totalSteps <= 0) {
    return null;
  }
  return Math.max(0, Math.min(PERCENT_MAX, Math.round((step / totalSteps) * PERCENT_MAX)));
};

function createStreamStateRefs(): StreamStateRefs {
  return {
    state: ref<AutomationRunUiState>("idle"),
    run: ref<RpaRunExecutionEnvelope | null>(null),
    events: ref<RpaRunEvent[]>([]),
    streamError: ref<StreamError | null>(null),
    isStreaming: ref(false),
    activeRunId: ref(""),
    lastSequenceByRunId: ref<Record<string, number>>({}),
  };
}

function stopSubscription(lifecycle: StreamLifecycle, refs: StreamStateRefs): void {
  if (lifecycle.unsubscribe) {
    lifecycle.unsubscribe();
    lifecycle.unsubscribe = null;
  }
  refs.isStreaming.value = false;
}

function resetEventState(refs: StreamStateRefs): void {
  refs.events.value = [];
  refs.lastSequenceByRunId.value = {};
}

function shouldApplyEvent(refs: StreamStateRefs, event: RpaRunEvent): boolean {
  if (event.runId !== refs.activeRunId.value) {
    return false;
  }

  const currentSequence = refs.lastSequenceByRunId.value[event.runId];
  if (typeof currentSequence === "number" && event.sequence <= currentSequence) {
    return false;
  }

  refs.lastSequenceByRunId.value = {
    ...refs.lastSequenceByRunId.value,
    [event.runId]: event.sequence,
  };

  return true;
}

function applyProgressEvent(
  currentRun: RpaRunExecutionEnvelope,
  event: Extract<RpaRunEvent, { eventType: "progress" }>,
): EventApplyResult {
  const nextStep = typeof event.step === "number" ? event.step : currentRun.currentStep;
  const nextTotalSteps =
    typeof event.totalSteps === "number" ? event.totalSteps : currentRun.totalSteps;
  const nextProgress = computeProgressPercent(nextStep ?? null, nextTotalSteps ?? null);
  const mappedStatus = PROGRESS_STATUS_TO_RUN_STATUS[event.status];
  const nextStatus =
    currentRun.status === "running" && mappedStatus === "pending"
      ? currentRun.status
      : mappedStatus;

  return {
    nextRun: {
      ...currentRun,
      status: nextStatus,
      currentStep: nextStep ?? null,
      totalSteps: nextTotalSteps ?? null,
      progress: nextProgress ?? currentRun.progress,
      updatedAt: event.timestamp,
    },
    nextState: nextStatus === "error" ? "errorNonRetryable" : "loading",
    shouldStop: nextStatus === "error",
  };
}

function applyResultEvent(
  currentRun: RpaRunExecutionEnvelope,
  event: Extract<RpaRunEvent, { eventType: "result" }>,
): EventApplyResult {
  const success = event.result.success;
  const resultSteps = event.result.steps.length;
  const nextRun: RpaRunExecutionEnvelope = {
    ...currentRun,
    status: success ? "success" : "error",
    output: event.result,
    error: success ? null : event.result.error,
    screenshots:
      event.result.screenshots.length > 0 ? event.result.screenshots : currentRun.screenshots,
    progress: PERCENT_MAX,
    currentStep: resultSteps,
    totalSteps: resultSteps,
    completedAt: event.timestamp,
    updatedAt: event.timestamp,
  };

  return {
    nextRun,
    nextState: toUiStateFromRun(nextRun),
    shouldStop: true,
  };
}

function applyErrorEvent(
  currentRun: RpaRunExecutionEnvelope,
  event: Extract<RpaRunEvent, { eventType: "error" }>,
): EventApplyResult {
  return {
    nextRun: {
      ...currentRun,
      status: "error",
      error: event.error,
      completedAt: event.timestamp,
      updatedAt: event.timestamp,
    },
    nextState: "errorNonRetryable",
    shouldStop: true,
  };
}

function applyEvent(refs: StreamStateRefs, lifecycle: StreamLifecycle, event: RpaRunEvent): void {
  refs.events.value = [...refs.events.value, event];
  const currentRun = refs.run.value;
  if (!currentRun || currentRun.id !== event.runId) {
    return;
  }

  let next: ReturnType<typeof applyProgressEvent>;
  if (event.eventType === "progress") {
    next = applyProgressEvent(currentRun, event);
  } else if (event.eventType === "result") {
    next = applyResultEvent(currentRun, event);
  } else {
    next = applyErrorEvent(currentRun, event);
  }

  refs.run.value = next.nextRun;
  refs.state.value = next.nextState;
  if (next.shouldStop) {
    stopSubscription(lifecycle, refs);
  }
}

async function fetchInitialRun(
  getRun: ReturnType<typeof useAutomation>["getRun"],
  runId: string,
  fallbackMessage: string,
): Promise<{ ok: true; value: RpaRunExecutionEnvelope } | { ok: false; error: StreamError }> {
  return getRun(runId).then(
    (value: RpaRunExecutionEnvelope) => ({ ok: true as const, value }),
    (error: ApiPayload) => ({ ok: false as const, error: toStreamError(error, fallbackMessage) }),
  );
}

function subscribeForRun(dependencies: StreamDependencies, runId: string, token: number): void {
  dependencies.lifecycle.unsubscribe = dependencies.subscribeToRun(runId, (event) => {
    if (
      token === dependencies.lifecycle.requestToken &&
      shouldApplyEvent(dependencies.refs, event)
    ) {
      applyEvent(dependencies.refs, dependencies.lifecycle, event);
    }
  });
  dependencies.refs.isStreaming.value = true;
}

async function startStream(dependencies: StreamDependencies, runId: string): Promise<void> {
  const normalizedRunId = runId.trim();
  dependencies.lifecycle.requestToken += 1;
  const token = dependencies.lifecycle.requestToken;

  stopSubscription(dependencies.lifecycle, dependencies.refs);
  resetEventState(dependencies.refs);
  dependencies.refs.streamError.value = null;
  dependencies.refs.activeRunId.value = normalizedRunId;

  if (normalizedRunId.length === 0) {
    dependencies.refs.state.value = "empty";
    dependencies.refs.run.value = null;
    return;
  }

  dependencies.refs.state.value = "loading";
  const initialRun = await fetchInitialRun(
    dependencies.getRun,
    normalizedRunId,
    dependencies.fallbackMessage,
  );
  if (token !== dependencies.lifecycle.requestToken) {
    return;
  }
  if (!initialRun.ok) {
    dependencies.refs.run.value = null;
    dependencies.refs.streamError.value = initialRun.error;
    dependencies.refs.state.value = toUiStateFromError(initialRun.error);
    return;
  }

  dependencies.refs.run.value = initialRun.value;
  dependencies.refs.state.value = toUiStateFromRun(initialRun.value);
  if (!TERMINAL_STATUSES.has(initialRun.value.status)) {
    subscribeForRun(dependencies, normalizedRunId, token);
  }
}

function cancelStream(refs: StreamStateRefs, lifecycle: StreamLifecycle): void {
  lifecycle.requestToken += 1;
  stopSubscription(lifecycle, refs);
  if (refs.state.value === "loading") {
    refs.state.value = "idle";
  }
}

function cleanupStream(refs: StreamStateRefs, lifecycle: StreamLifecycle): void {
  lifecycle.requestToken += 1;
  stopSubscription(lifecycle, refs);
}

/**
 * Reactive automation run stream composable.
 * Owns fetch + websocket lifecycle and deterministic UI-state mapping.
 */
export function useAutomationRunStream(options: UseAutomationRunStreamOptions = {}) {
  const { getRun, subscribeToRun } = useAutomation();
  const refs = createStreamStateRefs();
  const lifecycle: StreamLifecycle = {
    requestToken: 0,
    unsubscribe: null,
  };
  const dependencies: StreamDependencies = {
    refs,
    lifecycle,
    getRun,
    subscribeToRun,
    fallbackMessage:
      options.fallbackMessage ??
      automationJobApplyCatalog.automation.jobApply.stream.startErrorFallback,
  };
  const start = (runId: string): Promise<void> => startStream(dependencies, runId);
  const retry = (): Promise<void> => start(refs.activeRunId.value);
  const cancel = (): void => cancelStream(refs, lifecycle);
  const cleanup = (): void => cleanupStream(refs, lifecycle);
  if (getCurrentScope()) {
    onScopeDispose(cleanup);
  }

  return {
    state: readonly(refs.state),
    run: readonly(refs.run),
    events: readonly(refs.events),
    streamError: readonly(refs.streamError),
    isStreaming: readonly(refs.isStreaming),
    start,
    retry,
    cancel,
  };
}

const CHAT_SCROLL_STICKY_THRESHOLD_PX = 96;

export const useAIChatPageScroll = (input: {
  readonly chatContainer: ReturnType<typeof useTemplateRef<HTMLElement>>;
  readonly composerRef: ReturnType<typeof useTemplateRef<HTMLTextAreaElement>>;
  readonly renderedMessageSignature: Readonly<Ref<string>>;
  readonly loading: Readonly<Ref<boolean>>;
  readonly streaming: Readonly<Ref<boolean>>;
}) => {
  const shouldStickToBottom = ref(true);

  const updateScrollStickiness = (): void => {
    const container = input.chatContainer.value;
    if (!container) {
      return;
    }

    const remainingScrollDistance =
      container.scrollHeight - container.scrollTop - container.clientHeight;
    shouldStickToBottom.value = remainingScrollDistance <= CHAT_SCROLL_STICKY_THRESHOLD_PX;
  };

  const scrollToBottom = (force = false): void => {
    requestAnimationFrame(() => {
      const container = input.chatContainer.value;
      if (!(container && (force || shouldStickToBottom.value))) {
        return;
      }

      container.scrollTop = container.scrollHeight;
      updateScrollStickiness();
    });
  };

  watch(input.renderedMessageSignature, () => {
    if (shouldStickToBottom.value || input.loading.value || input.streaming.value) {
      scrollToBottom(true);
    }
  });

  watch(input.streaming, (isStreaming) => {
    if (!isStreaming) {
      return;
    }

    shouldStickToBottom.value = true;
    scrollToBottom(true);
  });

  return {
    handleChatScroll: updateScrollStickiness,
    focusComposer: () => requestAnimationFrame(() => input.composerRef.value?.focus()),
    scrollToBottom,
    shouldStickToBottom,
  };
};

import type { BrandSettings, BrandThemePalette } from "@bao/shared/types/settings-contracts";
import { watchEffect } from "vue";

const BRAND_PREVIEW_STYLE_ELEMENT_ID = "bao-brand-preview-styles";

function paletteRules(selector: string, palette: BrandThemePalette, brand: BrandSettings): string {
  return `${selector} {
  --color-base-100: ${palette.base100};
  --color-base-200: ${palette.base200};
  --color-base-300: ${palette.base300};
  --color-base-content: ${palette.baseContent};
  --color-primary: ${palette.primary};
  --color-primary-content: ${palette.primaryContent};
  --color-secondary: ${palette.secondary};
  --color-secondary-content: ${palette.secondaryContent};
  --color-accent: ${palette.accent};
  --color-accent-content: ${palette.accentContent};
  --color-neutral: ${palette.neutral};
  --color-neutral-content: ${palette.neutralContent};
  --color-info: ${palette.info};
  --color-info-content: ${palette.infoContent};
  --color-success: ${palette.success};
  --color-success-content: ${palette.successContent};
  --color-warning: ${palette.warning};
  --color-warning-content: ${palette.warningContent};
  --color-error: ${palette.error};
  --color-error-content: ${palette.errorContent};
  --radius-selector: ${palette.radiusSelector};
  --radius-field: ${palette.radiusField};
  --radius-box: ${palette.radiusBox};
  --size-selector: ${palette.sizeSelector};
  --size-field: ${palette.sizeField};
  --border: ${palette.border};
  --depth: ${palette.depth};
  --noise: ${palette.noise};
  --brand-font-display: ${brand.typography.displayFontFamily};
  --brand-font-body: ${brand.typography.bodyFontFamily};
  --brand-font-mono: ${brand.typography.monoFontFamily};
  background-color: ${palette.base100};
  border-color: ${palette.secondary};
  color: ${palette.baseContent};
  font-family: var(--brand-font-body);
}`;
}

/**
 * Publishes brand preview rules into a document stylesheet so Vue templates
 * avoid `:style` bindings for dynamic brand colors.
 */
export function useBrandPreviewStyles(getBrand: () => BrandSettings): void {
  if (!import.meta.client) {
    return;
  }

  watchEffect((onCleanup) => {
    const brand = getBrand();
    let styleElement = document.getElementById(BRAND_PREVIEW_STYLE_ELEMENT_ID);
    if (!(styleElement instanceof HTMLStyleElement)) {
      styleElement = document.createElement("style");
      styleElement.id = BRAND_PREVIEW_STYLE_ELEMENT_ID;
      document.head.append(styleElement);
    }

    styleElement.textContent = `
.brand-swatch-light {
  background: linear-gradient(135deg, ${brand.lightTheme.base100} 0%, ${brand.lightTheme.base200} 50%, ${brand.lightTheme.primary} 100%);
}
.brand-swatch-dark {
  background: linear-gradient(135deg, ${brand.darkTheme.base100} 0%, ${brand.darkTheme.base200} 50%, ${brand.darkTheme.primary} 100%);
}
${paletteRules(".brand-preview-surface-light", brand.lightTheme, brand)}
${paletteRules(".brand-preview-surface-dark", brand.darkTheme, brand)}
`;

    onCleanup(() => {
      styleElement?.remove();
    });
  });
}

import type { GameStudio } from "@bao/shared/types/interview";
import { normalizeScrapePersonaEnrichment } from "@bao/shared/utils/scrape-enrichment";
import {
  asBoolean,
  asNumber,
  asString,
  asStringArray,
  isRecord,
} from "@bao/shared/utils/type-guards";
import { asEnum, normalizeStudioCulture } from "~/composables/api-normalizer-shared";

const STUDIO_CATEGORIES: readonly Exclude<GameStudio["category"], undefined>[] = [
  "AAA",
  "Indie",
  "Mobile",
  "VR/AR",
  "Platform",
  "Esports",
  "International",
];

export const toGameStudio = (value: unknown): GameStudio | null => {
  if (!isRecord(value)) return null;
  const id = asString(value.id);
  const name = asString(value.name);
  if (!(id && name)) return null;

  return {
