  };
}

export function useResumePageActions(
  input: ResumePageActionsInput,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;
  const { editor, mutations, progress, view } = createResumeActionModules(input, nuxtApp, t);

  async function handleExport(
    exportResume: (
      id: string,
      template?: ResumeTemplate,
      format?: "pdf" | "docx",
    ) => Promise<unknown>,
    format: "pdf" | "docx",
  ): Promise<void> {
    if (!input.selectedResumeId.value) {
      return;
    }
    const exportResult = await settlePromise(
      exportResume(input.selectedResumeId.value, undefined, format),
      t("resumePage.toasts.resumeExportFailed"),
    );
    if (!exportResult.ok) {
      $toast.error(getErrorMessage(exportResult.error, t("resumePage.toasts.resumeExportFailed")));
      return;
    }
    $toast.success(t("resumePage.toasts.resumeExported"));
  }

  return {
    aiEnhancementStepIndex: progress.aiEnhancementStepIndex,
    clearResumeFilters: (resumeSearchQuery: Ref<string>) =>
      view.clearResumeFilters(resumeSearchQuery),
    handleAIEnhance: () => editor.handleAIEnhance(),
    handleAIScore: () => editor.handleAIScore(),
    handleCompletionTabSelect: view.handleCompletionTabSelect,
    handleCreate: () => mutations.handleCreate(),
    handleDeleteResume: () => mutations.handleDeleteResume(),
    handleExport,
    handleSave: () => editor.handleSave(),
    selectResumeTab: view.selectResumeTab,
    updateEducation: (value: ResumeFormData["education"]) => view.updateEducation(value),
    updateExperience: (value: ResumeFormData["experience"]) => view.updateExperience(value),
    updateGaming: (value: ResumeFormData["gaming"]) => view.updateGaming(value),
    updatePersonalInfo: view.updatePersonalInfo,
    updateProjects: (value: ResumeFormData["projects"]) => view.updateProjects(value),
    updateSkills: (value: ResumeFormData["skills"]) => view.updateSkills(value),
  };
}

import { onUnmounted, watch } from "vue";
import { createInterviewSessionActions } from "~/composables/interview-session-actions";
import {
  buildInterviewSessionViewModel,
  createInterviewSessionDerivedState,
  createInterviewSessionState,
  registerInterviewSessionWatchers,
} from "~/composables/interview-session-page-state";
import { createInterviewSessionTimer } from "~/composables/interview-session-timer";
import { useInterviewRealtime } from "~/composables/useInterviewRealtime";

export function useInterviewSessionPage() {
  const state = createInterviewSessionState();
  const derived = createInterviewSessionDerivedState(state);
  const realtime = useInterviewRealtime();
  const timer = createInterviewSessionTimer({
    activeSession: derived.activeSession,
    t: state.t,
  });

  const submitViaWs = async (sessionId: string, content: string): Promise<boolean> => {
    const feedback = await realtime.submitViaWs(sessionId, content);
    return feedback !== null;
  };

  const actions = createInterviewSessionActions({
    canComplete: derived.canComplete,
    canSubmit: derived.canSubmit,
    completeSession: state.completeSession,
    completing: state.completing,
    currentQuestionIndex: derived.currentQuestionIndex,
    currentSessionLoadId: state.currentSessionLoadId,
    getSession: state.getSession,
    isLastQuestion: derived.isLastQuestion,
    response: state.response,
    router: state.router,
    sessionId: derived.sessionId,
    sessionLoadError: state.sessionLoadError,
    stt: state.stt,
    stopTimer: timer.stopTimer,
    submitViaWs,
    submitResponse: state.submitResponse,
    submitting: state.submitting,
    syncCompletedSessionTime: timer.syncCompletedSessionTime,
    startTimer: timer.startTimer,
    t: state.t,
    toast: state.toast,
  });

  registerInterviewSessionWatchers({
    actions,
    derived,
    response: state.response,
    stt: state.stt,
    timer,
    tts: state.tts,
  });

  watch(
    derived.sessionId,
    (sessionId) => {
      if (sessionId) {
        realtime.connect();
      }
    },
    { immediate: true },
  );

  onUnmounted(() => {
    timer.stopTimer();
    state.tts.cancel();
    state.stt.stopListening();
    realtime.disconnect();
  });
  return buildInterviewSessionViewModel({ actions, derived, state, timer });
}

import { resolveBrandSettings, THEME_NAMES } from "@bao/shared/constants/branding";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type {
  AppSettings,
  BrandSettings,
  BrandThemePalette,
} from "@bao/shared/types/settings-contracts";
import { computed, readonly } from "vue";
import { useNuxtState } from "./nuxtRuntime";
import { useTheme } from "./useTheme";

function toFontCssVars(brand: BrandSettings): Record<string, string> {
  return {
    "--brand-font-display": brand.typography.displayFontFamily,
    "--brand-font-body": brand.typography.bodyFontFamily,
    "--brand-font-mono": brand.typography.monoFontFamily,
  };
}

/**
 * Maps a brand palette to daisyUI v5 semantic color/size tokens for the active `data-theme`.
 */
function toDaisySemanticColorVars(palette: BrandThemePalette): Record<string, string> {
  return {
    "--color-base-100": palette.base100,
    "--color-base-200": palette.base200,
    "--color-base-300": palette.base300,
    "--color-base-content": palette.baseContent,
    "--color-primary": palette.primary,
    "--color-primary-content": palette.primaryContent,
    "--color-secondary": palette.secondary,
    "--color-secondary-content": palette.secondaryContent,
    "--color-accent": palette.accent,
    "--color-accent-content": palette.accentContent,
    "--color-neutral": palette.neutral,
    "--color-neutral-content": palette.neutralContent,
    "--color-info": palette.info,
    "--color-info-content": palette.infoContent,
    "--color-success": palette.success,
    "--color-success-content": palette.successContent,
    "--color-warning": palette.warning,
    "--color-warning-content": palette.warningContent,
    "--color-error": palette.error,
    "--color-error-content": palette.errorContent,
    "--radius-selector": palette.radiusSelector,
    "--radius-field": palette.radiusField,
    "--radius-box": palette.radiusBox,
    "--size-selector": palette.sizeSelector,
    "--size-field": palette.sizeField,
    "--border": palette.border,
    "--depth": palette.depth,
    "--noise": palette.noise,
  };
}

/**
 * Resolves persisted brand settings and derived CSS variables.
 * Document CSS application is owned exclusively by `plugins/brand-css.client.ts`.
 *
 * Reads the shared settings state key directly so it is safe outside Vue component
 * setup (Nuxt plugins) without pulling `useI18n` via `useSettings`.
 *
 * @returns White-label brand settings and CSS var map (read-only).
 */
export function useBrand() {
  const settings = useNuxtState<AppSettings | null>(STATE_KEYS.APP_SETTINGS, () => null);
  const { theme } = useTheme();

  const resolvedBrand = computed(() => resolveBrandSettings(settings.value?.brandSettings));
  const brandCssVars = computed(() => {
    const brand = resolvedBrand.value;
    const palette = theme.value === THEME_NAMES.dark ? brand.darkTheme : brand.lightTheme;
    return {
      ...toFontCssVars(brand),
      ...toDaisySemanticColorVars(palette),
    };
  });

  return {
    resolvedBrand: readonly(resolvedBrand),
    brandCssVars: readonly(brandCssVars),
  };
}

import type { InterviewMode } from "@bao/shared/types/interview";
import type { Ref } from "vue";
