import { AI_PROVIDER_DEFAULT } from "@bao/shared/constants/ai-provider";
import type { AIProviderType } from "@bao/shared/types/ai";
import { PERCENT_MAX } from "@bao/shared/constants/numeric";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import type {
  DashboardStats,
  ProviderConfig,
  ProviderConnectivityResult,
} from "~/types/ai-dashboard";
import {
  buildFallbackProviderRows,
  normalizeProviderRows,
  resolveProviderModelSelection,
} from "~/utils/ai-control-plane";

type ApiPayload = Parameters<typeof isRecord>[0];
const NUM_100 = 100;

export type DashboardBootstrap = {
  activeModel: string;
  activeProvider: AIProviderType;
  normalizedStats: DashboardStats;
  resolvedProviders: ProviderConfig[];
};

const asNumber = (value: ApiPayload): number | undefined =>
  typeof value === "number" && Number.isFinite(value) ? value : undefined;

function readNumberField(payload: Record<string, ApiPayload>, key: string): number | undefined {
  return asNumber(payload[key]);
}

function normalizeDashboardStats(
  usagePayload: ApiPayload,
  activeProvider: AIProviderType,
): DashboardStats {
  if (!isRecord(usagePayload)) {
    return {
      totalRequests: 0,
      successRate: 0,
      averageResponseTimeSeconds: 0,
      activeProvider,
      sessions: 0,
    };
  }

  const totalMessages = readNumberField(usagePayload, "totalMessages") ?? 0;
  const userMessages = readNumberField(usagePayload, "userMessages") ?? 0;
  const assistantMessages = readNumberField(usagePayload, "assistantMessages") ?? 0;
  const sessions = readNumberField(usagePayload, "sessions") ?? 0;
  let successRate = 0;
  if (userMessages > 0) {
    successRate = Math.round((assistantMessages / userMessages) * PERCENT_MAX);
  } else if (totalMessages > 0) {
    successRate = NUM_100;
  }

  return {
    totalRequests: totalMessages,
    successRate,
    averageResponseTimeSeconds: 0,
    activeProvider,
    sessions,
  };
}

function useAIDashboardDependencies() {
  const { t } = useI18n();
  const { settings, fetchSettings, testApiKey, chatRoutingPreference, localProviderState } =
    useSettings();
  const { $toast } = useNuxtApp();
  const api = useApi();

  return {
    api,
    chatRoutingPreference,
    fetchSettings,
    localProviderState,
    settings,
    t,
    testApiKey,
    toast: $toast,
  };
}

function useDashboardBootstrap(input: {
  api: ReturnType<typeof useApi>;
  fetchSettings: ReturnType<typeof useSettings>["fetchSettings"];
  settings: ReturnType<typeof useSettings>["settings"];
  chatRoutingPreference: ReturnType<typeof useSettings>["chatRoutingPreference"];
  t: ReturnType<typeof useI18n>["t"];
  resolveDefaultModel: (providerId: AIProviderType) => string;
}) {
  async function loadDashboardState(): Promise<DashboardBootstrap> {
    if (!input.settings.value) {
      await input.fetchSettings();
    }
    const [usageResult, modelsResult] = await Promise.all([
      input.api.ai.usage.get(),
      input.api.ai.models.get(),
    ]);

    if (usageResult.error) {
      throw new Error(input.t("aiDashboard.errors.usageLoadFailed"));
    }
    if (modelsResult.error) {
      throw new Error(input.t("aiDashboard.errors.modelsLoadFailed"));
    }

    const normalizedProviders = normalizeProviderRows(modelsResult.data, input.settings.value);
    const resolvedProviders =
      normalizedProviders.length > 0
        ? normalizedProviders
        : buildFallbackProviderRows(input.settings.value);
    const activeProvider = resolvedProviders.some(
      (provider) => provider.id === input.chatRoutingPreference.value.provider,
    )
      ? input.chatRoutingPreference.value.provider
      : (resolvedProviders[0]?.id ?? AI_PROVIDER_DEFAULT);
    const activeProviderModels =
      resolvedProviders.find((provider) => provider.id === activeProvider)?.models ?? [];

    return {
      resolvedProviders,
      activeProvider,
      activeModel:
        resolveProviderModelSelection(activeProvider, input.settings.value, activeProviderModels) ||
        input.resolveDefaultModel(activeProvider),
      normalizedStats: normalizeDashboardStats(usageResult.data, activeProvider),
    };
  }

  return useAsyncData("ai-dashboard-bootstrap", loadDashboardState, {
    server: true,
    lazy: false,
  });
}

export function createAIDashboardRuntime() {
  return {
    dependencies: useAIDashboardDependencies(),
    testingProvider: ref<AIProviderType | null>(null),
    testResults: reactive<Record<AIProviderType, ProviderConnectivityResult | null>>({
      local: null,
      gemini: null,
      openai: null,
      claude: null,
      huggingface: null,
    }),
  };
}

export function createAIDashboardBootstrapState(
  runtime: ReturnType<typeof createAIDashboardRuntime>,
  resolveDefaultModel: (providerId: AIProviderType) => string,
) {
  const {
    data: dashboardBootstrap,
    error: dashboardBootstrapError,
    refresh: refreshDashboardBootstrap,
    status: dashboardBootstrapStatus,
  } = useDashboardBootstrap({
    api: runtime.dependencies.api,
    fetchSettings: runtime.dependencies.fetchSettings,
    settings: runtime.dependencies.settings,
    chatRoutingPreference: runtime.dependencies.chatRoutingPreference,
    t: runtime.dependencies.t,
    resolveDefaultModel,
  });

  return {
    dashboardBootstrap,
    dashboardBootstrapError,
    dashboardBootstrapStatus,
    refreshDashboardBootstrap,
  };
}

import {
  AI_CHAT_ENTITY_ROUTE_PATHS,
  AI_CHAT_PAGE_PATH,
  AI_CHAT_ROUTE_QUERY_KEYS,
  inferAIChatDomainFromRoutePath,
} from "@bao/shared/constants/ai-chat";
import type {
  AIChatContext,
  AIChatContextEntity,
  AIChatContextEntityType,
  AIChatContextSource,
} from "@bao/shared/types/ai";
import type { GameStudio, InterviewSession } from "@bao/shared/types/interview";
import type { Job } from "@bao/shared/types/jobs";
import type { PortfolioData } from "@bao/shared/types/portfolio";
import type { ResumeData } from "@bao/shared/types/resume";
import type { LocationQueryValue } from "vue-router";

interface EntityContextInput {
  path: string;
  routeParams: Record<string, string>;
  routeQuery: Record<string, string>;
  jobs: readonly Job[];
  resumes: readonly ResumeData[];
  studio: GameStudio | null;
  interviewSessions: readonly InterviewSession[];
}

interface ContextBuilderInput {
  route: ReturnType<typeof useRoute>;
  jobs: ReturnType<typeof useState<Job[]>>;
  resumes: ReturnType<typeof useState<ResumeData[]>>;
  currentStudio: ReturnType<typeof useState<GameStudio | null>>;
  interviewSessions: ReturnType<typeof useState<InterviewSession[]>>;
  portfolioData: ReturnType<typeof useState<PortfolioData | null>>;
}

function resolveAIChatSource(path: string, source?: AIChatContextSource): AIChatContextSource {
  if (source) {
    return source;
  }
  return path.startsWith(AI_CHAT_PAGE_PATH) ? "chat-page" : "floating-widget";
}

function normalizeRouteParams(
  params: Record<string, string | string[] | null | undefined>,
): Record<string, string> {
  const normalized: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (Array.isArray(value)) {
      const [firstValue] = value;
      if (typeof firstValue === "string" && firstValue.length > 0) {
        normalized[key] = firstValue;
      }
      continue;
    }
    if (typeof value === "string" && value.length > 0) {
      normalized[key] = value;
    }
  }
  return normalized;
}

function normalizeRouteQuery(
  query: Record<string, LocationQueryValue | LocationQueryValue[]>,
): Record<string, string> {
  const normalized: Record<string, string> = {};
  for (const [key, value] of Object.entries(query)) {
    if (Array.isArray(value)) {
      const firstStringValue = value.find(
        (entry): entry is string => typeof entry === "string" && entry.length > 0,
      );
      if (firstStringValue) {
        normalized[key] = firstStringValue;
      }
      continue;
    }
    if (typeof value === "string" && value.length > 0) {
      normalized[key] = value;
    }
  }
  return normalized;
}

function toEntity(type: AIChatContextEntityType, id: string, label?: string): AIChatContextEntity {
  if (!label) {
    return { type, id };
  }
  return { type, id, label };
}

function buildInterviewSessionLabel(session: InterviewSession): string {
  const role =
    session.role?.trim() ||
    session.config.targetJob?.title?.trim() ||
    session.config.roleType.trim() ||
    "";
  const studio =
    session.studioName?.trim() ||
    session.config.targetJob?.company?.trim() ||
    session.studioId.trim() ||
    "";

  if (role.length > 0 && studio.length > 0) {
    return `${role} at ${studio}`;
  }

  return role || studio;
}

function resolveJobContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (!(input.path.startsWith(`${AI_CHAT_ENTITY_ROUTE_PATHS.jobs}/`) && routeId)) {
    return;
  }
  const selectedJob = input.jobs.find((job) => job.id === routeId);
  const selectedJobLabel = selectedJob ? `${selectedJob.title} at ${selectedJob.company}` : "";
  return toEntity("job", routeId, selectedJobLabel);
}

function resolveInterviewContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  const queryJobId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.jobId];
  if (!(input.path.startsWith(AI_CHAT_ENTITY_ROUTE_PATHS.interview) && queryJobId)) {
    return;
  }
  const selectedJob = input.jobs.find((job) => job.id === queryJobId);
  const selectedJobLabel = selectedJob ? `${selectedJob.title} at ${selectedJob.company}` : "";
  return toEntity("job", queryJobId, selectedJobLabel);
}

function resolveResumeContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  if (!input.path.startsWith(AI_CHAT_ENTITY_ROUTE_PATHS.resume)) {
    return;
  }
  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  const queryResumeId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.resumeId];
  const resolvedResumeId = routeId || queryResumeId;
  if (!resolvedResumeId) {
    return;
  }
  const selectedResume = input.resumes.find((resume) => resume.id === resolvedResumeId);
  return toEntity("resume", resolvedResumeId, selectedResume?.name ?? "");
}

function resolveStudioPathContextEntity(
  input: EntityContextInput,
): AIChatContextEntity | undefined {
  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (!(input.path.startsWith(`${AI_CHAT_ENTITY_ROUTE_PATHS.studios}/`) && routeId)) {
    return;
  }
  return toEntity("studio", routeId, input.studio?.name ?? "");
}

function resolveStudioQueryContextEntity(
  input: EntityContextInput,
): AIChatContextEntity | undefined {
  const queryStudioId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.studioId];
  if (!queryStudioId) {
    return;
  }
  return toEntity("studio", queryStudioId, input.studio?.name ?? "");
}

function resolveSessionContextEntity(input: EntityContextInput): AIChatContextEntity | undefined {
  const interviewSessionId = input.routeQuery[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (input.path.startsWith(AI_CHAT_ENTITY_ROUTE_PATHS.interviewSession) && interviewSessionId) {
    const interviewSession = input.interviewSessions.find(
      (session) => session.id === interviewSessionId,
    );
    return toEntity(
      "interview_session",
      interviewSessionId,
      interviewSession ? buildInterviewSessionLabel(interviewSession) : undefined,
    );
  }

  const routeId = input.routeParams[AI_CHAT_ROUTE_QUERY_KEYS.id];
  if (input.path.startsWith(`${AI_CHAT_ENTITY_ROUTE_PATHS.automationRuns}/`) && routeId) {
    return toEntity("automation_run", routeId);
  }
}

function resolveEntityContext(input: EntityContextInput): AIChatContextEntity | undefined {
  const resolvers = [
    resolveJobContextEntity,
    resolveInterviewContextEntity,
    resolveResumeContextEntity,
    resolveStudioPathContextEntity,
    resolveStudioQueryContextEntity,
    resolveSessionContextEntity,
  ] as const;

  for (const resolver of resolvers) {
    const entity = resolver(input);
    if (entity) {
      return entity;
    }
  }
}

export function createContextBuilder(input: ContextBuilderInput) {
  return (source?: AIChatContextSource): AIChatContext => {
    const routeParams = normalizeRouteParams(input.route.params);
    const routeQuery = normalizeRouteQuery(input.route.query);
    const routeName = typeof input.route.name === "string" ? input.route.name : "";
    const resolvedSource = resolveAIChatSource(input.route.path, source);
    const entityContext = resolveEntityContext({
      path: input.route.path,
      routeParams,
      routeQuery,
      jobs: input.jobs.value,
      resumes: input.resumes.value,
      studio: input.currentStudio.value,
      interviewSessions: input.interviewSessions.value,
    });

    const context: AIChatContext = {
      source: resolvedSource,
      domain: inferAIChatDomainFromRoutePath(input.route.path),
      route: {
        path: input.route.path,
        params: routeParams,
        query: routeQuery,
        ...(routeName ? { name: routeName } : {}),
      },
      state: {
        hasResumes: input.resumes.value.length > 0,
        resumeCount: input.resumes.value.length,
        hasJobs: input.jobs.value.length > 0,
        jobCount: input.jobs.value.length,
        hasStudios: input.currentStudio.value !== null,
        studioCount: input.currentStudio.value ? 1 : 0,
        hasInterviewSessions: input.interviewSessions.value.length > 0,
        interviewSessionCount: input.interviewSessions.value.length,
        hasPortfolioProjects: (input.portfolioData.value?.projects.length ?? 0) > 0,
        portfolioProjectCount: input.portfolioData.value?.projects.length ?? 0,
      },
    };

    return entityContext ? { ...context, entity: entityContext } : context;
  };
}

import { computed, type MaybeRefOrGetter, toValue } from "vue";
import { resolveFlowRecommendations } from "~/constants/flow-engine";
import type {
  FlowEngineInput,
  FlowRecommendation,
  FlowResolution,
  FlowStage,
} from "~/constants/flow-engine-types";

/**
 * Reactive interface around the global flow recommendation engine.
 *
 * @param input Reactive or static flow-engine input.
 * @returns Computed primary action, recommendations, stage, and next-step label.
 */
export function useFlowEngine(input: MaybeRefOrGetter<FlowEngineInput>) {
  const resolution = computed<FlowResolution>(() => resolveFlowRecommendations(toValue(input)));

  const primaryAction = computed<FlowRecommendation>(() => resolution.value.primaryAction);
  const recommendedActions = computed<readonly FlowRecommendation[]>(
    () => resolution.value.recommendedActions,
  );
  const nextStepLabel = computed<string>(() => resolution.value.nextStepLabel);
  const flowStage = computed<FlowStage>(() => resolution.value.flowStage);

  return {
    primaryAction,
    recommendedActions,
    nextStepLabel,
    flowStage,
  };
}

import { APP_ROUTES } from "@bao/shared/constants/routes";
import { useI18n } from "vue-i18n";
import {
  findNavigationItemById,
  normalizeRoutePath,
  resolveLongestMatchingNavItem,
} from "~/constants/navigation";

/**
 * Section breadcrumbs for the app navbar (Dashboard → section → workflow), driven by `NAVIGATION_ITEMS`.
 */
export function useNavbarBreadcrumbs() {
  const route = useRoute();
  const { t } = useI18n();

  const navbarBreadcrumbs = computed(() => {
    const normalized = normalizeRoutePath(route.path);
    if (normalized === "/") {
      return [{ label: t("nav.dashboard") }] as const;
    }

    const match = resolveLongestMatchingNavItem(route.path);
    if (!match) {
      return [
        { label: t("nav.dashboard"), to: APP_ROUTES.dashboard },
        { label: t("nav.breadcrumbUnknown") },
      ] as const;
    }

    if (normalizeRoutePath(match.to) === "/") {
      return [{ label: t("nav.dashboard") }] as const;
    }

    const crumbs: Array<{ label: string; to?: string }> = [
      { label: t("nav.dashboard"), to: APP_ROUTES.dashboard },
    ];

    if (match.parentId) {
      const parent = findNavigationItemById(match.parentId);
      if (parent) {
        crumbs.push({ label: t(parent.labelKey), to: parent.to });
      }
    }

    crumbs.push({ label: t(match.labelKey) });
    return crumbs;
  });

  return { navbarBreadcrumbs };
}

