import {
  PORTFOLIO_PROJECT_DESCRIPTION_MIN_LENGTH,
  PORTFOLIO_PROJECT_TITLE_MIN_LENGTH,
} from "@bao/shared/constants/portfolio";
import type { PortfolioMetadata, PortfolioProject } from "@bao/shared/types/portfolio";
import type { ComputedRef, Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import type { NuxtApp } from "#app";
import { settlePromise } from "~/composables/async-flow";
import type {
  PortfolioProjectForm,
  PortfolioProjectView,
  ProjectDirection,
} from "~/composables/portfolio-page-state";
import { getErrorMessage } from "~/utils/errors";

type PortfolioProjectPayload = {
  title: string;
  description: string;
  technologies: string[];
  featured: boolean;
  image?: string;
  liveUrl?: string;
};

type PortfolioPageActionsInput = {
  addProject: (payload: PortfolioProjectPayload) => Promise<unknown>;
  deleteProject: (id: string) => Promise<void>;
  deleteProjectState: {
    pendingDeleteProjectId: Ref<string | null>;
    closeDeleteProjectDialog: () => void;
    requestDeleteProjectConfirmation: (id: string) => void;
  };
  displayProjects: ComputedRef<readonly PortfolioProject[]>;
  editingProject: Ref<PortfolioProject | null>;
  exportPortfolio: (format?: "pdf" | "docx") => Promise<unknown>;
  newTech: Ref<string>;
  portfolioForm: PortfolioMetadata;
  projectForm: PortfolioProjectForm;
  projects: Ref<readonly PortfolioProjectView[]>;
  reorderProjects: (orderedIds: string[]) => Promise<unknown>;
  reorderingProjectId: Ref<string | null>;
  updatePortfolio: (metadata: Partial<PortfolioMetadata>) => Promise<unknown>;
  updateProject: (id: string, payload: PortfolioProjectPayload) => Promise<unknown>;
};

function createPortfolioProjectPayload(projectForm: PortfolioProjectForm): PortfolioProjectPayload {
  return {
    title: projectForm.title.trim(),
    description: projectForm.description.trim(),
    technologies: [...projectForm.technologies],
    featured: projectForm.featured,
    ...(projectForm.image.trim() ? { image: projectForm.image.trim() } : {}),
    ...(projectForm.liveUrl.trim() ? { liveUrl: projectForm.liveUrl.trim() } : {}),
  };
}

function usePortfolioProjectValidation(
  {
    editingProject,
    projectForm,
  }: Pick<PortfolioPageActionsInput, "editingProject" | "projectForm">,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;

  return {
    validateProjectForm(): boolean {
      if (projectForm.title.trim().length < PORTFOLIO_PROJECT_TITLE_MIN_LENGTH) {
        $toast.error(
          t("portfolioPage.toasts.projectTitleMinLength", {
            count: PORTFOLIO_PROJECT_TITLE_MIN_LENGTH,
          }),
        );
        return false;
      }

      if (projectForm.description.trim().length < PORTFOLIO_PROJECT_DESCRIPTION_MIN_LENGTH) {
        $toast.error(
          t("portfolioPage.toasts.projectDescriptionMinLength", {
            count: PORTFOLIO_PROJECT_DESCRIPTION_MIN_LENGTH,
          }),
        );
        return false;
      }

      if (editingProject.value && !editingProject.value.id) {
        $toast.error(t("portfolioPage.toasts.projectIdMissing"));
        return false;
      }

      return true;
    },
  };
}

function usePortfolioTechnologyActions(
  { newTech, projectForm }: Pick<PortfolioPageActionsInput, "newTech" | "projectForm">,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;

  return {
    addTechnology(): void {
      const nextTechnology = newTech.value.trim();
      if (!nextTechnology) {
        return;
      }

      const alreadyExists = projectForm.technologies.some(
        (technology) => technology.toLowerCase() === nextTechnology.toLowerCase(),
      );
      if (alreadyExists) {
        $toast.error(t("portfolioPage.toasts.technologyDuplicate"));
        return;
      }

      projectForm.technologies.push(nextTechnology);
      newTech.value = "";
    },
    removeTechnology(index: number): void {
      projectForm.technologies.splice(index, 1);
    },
  };
}

function usePortfolioProjectOrdering(
  {
    displayProjects,
    projects,
    reorderProjects,
    reorderingProjectId,
  }: Pick<
    PortfolioPageActionsInput,
    "displayProjects" | "projects" | "reorderProjects" | "reorderingProjectId"
  >,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;

  function projectIndexById(projectId: string | undefined): number {
    if (!projectId) {
      return -1;
    }
    return projects.value.findIndex((project) => project.id === projectId);
  }

  return {
    canMove(projectId: string | undefined, direction: ProjectDirection): boolean {
      const index = projectIndexById(projectId);
      if (index < 0) {
        return false;
      }
      if (direction === "up") {
        return index > 0;
      }
      return index < projects.value.length - 1;
    },
    async moveProject(projectId: string | undefined, direction: ProjectDirection): Promise<void> {
      if (!projectId) {
        return;
      }

      const index = projectIndexById(projectId);
      if (index < 0) {
        return;
      }

      const targetIndex = direction === "up" ? index - 1 : index + 1;
      if (targetIndex < 0 || targetIndex >= projects.value.length) {
        return;
      }

      const reordered = [...displayProjects.value];
      const movedProject = reordered.splice(index, 1)[0];
      if (!movedProject) {
        return;
      }
      reordered.splice(targetIndex, 0, movedProject);

      const orderedIds = reordered
        .map((project) => project.id)
        .filter((id): id is string => typeof id === "string" && id.trim().length > 0);

      reorderingProjectId.value = projectId;
      const reorderResult = await settlePromise(
        reorderProjects(orderedIds),
        t("portfolioPage.toasts.reorderFailed"),
      );
      reorderingProjectId.value = null;

      if (!reorderResult.ok) {
        $toast.error(getErrorMessage(reorderResult.error, t("portfolioPage.toasts.reorderFailed")));
        return;
      }

      $toast.success(t("portfolioPage.toasts.reordered"));
    },
  };
}

function usePortfolioMutationActions(
  input: PortfolioPageActionsInput,
  validation: ReturnType<typeof usePortfolioProjectValidation>,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  return {
    ...createPortfolioCrudActions(input, validation, nuxtApp, t),
    ...createPortfolioDeleteActions(input, nuxtApp, t),
  };
}

async function savePortfolioProject(
  input: PortfolioPageActionsInput,
  payload: PortfolioProjectPayload,
): Promise<"updated" | "added"> {
  if (input.editingProject.value?.id) {
    await input.updateProject(input.editingProject.value.id, payload);
    return "updated";
  }

  await input.addProject(payload);
  return "added";
}

function createPortfolioCrudActions(
  input: PortfolioPageActionsInput,
  validation: ReturnType<typeof usePortfolioProjectValidation>,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;

  return {
    async handleExport(format: "pdf" | "docx"): Promise<void> {
      const exportResult = await settlePromise(
        input.exportPortfolio(format),
        t("portfolioPage.toasts.exportFailed"),
      );
      if (!exportResult.ok) {
        $toast.error(getErrorMessage(exportResult.error, t("portfolioPage.toasts.exportFailed")));
        return;
      }

      $toast.success(t("portfolioPage.toasts.exported"));
    },

    async handleSavePortfolio(): Promise<void> {
      const savePortfolioResult = await settlePromise(
        input.updatePortfolio(input.portfolioForm),
        t("portfolioPage.toasts.saveFailed"),
      );
      if (!savePortfolioResult.ok) {
        $toast.error(
          getErrorMessage(savePortfolioResult.error, t("portfolioPage.toasts.saveFailed")),
        );
        return;
      }

      $toast.success(t("portfolioPage.toasts.saved"));
    },

    async handleSaveProject(clearProjectForm: () => void): Promise<boolean> {
      if (!validation.validateProjectForm()) {
        return false;
      }

      const saveProjectResult = await settlePromise(
        savePortfolioProject(input, createPortfolioProjectPayload(input.projectForm)),
        t("portfolioPage.toasts.projectSaveFailed"),
      );

      if (!saveProjectResult.ok) {
        $toast.error(
          getErrorMessage(saveProjectResult.error, t("portfolioPage.toasts.projectSaveFailed")),
        );
        return false;
      }

      clearProjectForm();
      $toast.success(
        saveProjectResult.value === "updated"
          ? t("portfolioPage.toasts.projectUpdated")
          : t("portfolioPage.toasts.projectAdded"),
      );
      return true;
    },
  };
}

function createPortfolioDeleteActions(
  input: PortfolioPageActionsInput,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;

  return {
    async handleDeleteProject(): Promise<void> {
      const id = input.deleteProjectState.pendingDeleteProjectId.value;
      if (!id) {
        return;
      }

      const deleteProjectResult = await settlePromise(
        input.deleteProject(id),
        t("portfolioPage.toasts.projectDeleteFailed"),
      );
      input.deleteProjectState.closeDeleteProjectDialog();

      if (!deleteProjectResult.ok) {
        $toast.error(
          getErrorMessage(deleteProjectResult.error, t("portfolioPage.toasts.projectDeleteFailed")),
        );
        return;
      }

      $toast.success(t("portfolioPage.toasts.projectDeleted"));
    },

    requestDeleteProject(id?: string): void {
      if (!id) {
        $toast.error(t("portfolioPage.toasts.projectIdMissing"));
        return;
      }

      input.deleteProjectState.requestDeleteProjectConfirmation(id);
    },
  };
}

export function usePortfolioPageActions(
  input: PortfolioPageActionsInput,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const validation = usePortfolioProjectValidation(
    { editingProject: input.editingProject, projectForm: input.projectForm },
    nuxtApp,
    t,
  );
  const technology = usePortfolioTechnologyActions(
    { newTech: input.newTech, projectForm: input.projectForm },
    nuxtApp,
    t,
  );
  const ordering = usePortfolioProjectOrdering(
    {
      displayProjects: input.displayProjects,
      projects: input.projects,
      reorderProjects: input.reorderProjects,
      reorderingProjectId: input.reorderingProjectId,
    },
    nuxtApp,
    t,
  );
  const mutations = usePortfolioMutationActions(input, validation, nuxtApp, t);

  function clearFilters(searchQuery: Ref<string>): void {
    searchQuery.value = "";
  }

  return {
    addTechnology: () => technology.addTechnology(),
    canMove: (projectId: string | undefined, direction: ProjectDirection) =>
      ordering.canMove(projectId, direction),
    clearFilters,
    handleDeleteProject: () => mutations.handleDeleteProject(),
    handleExport: (format: "pdf" | "docx") => mutations.handleExport(format),
    handleSavePortfolio: () => mutations.handleSavePortfolio(),
    handleSaveProject: (clearProjectForm: () => void) =>
      mutations.handleSaveProject(clearProjectForm),
    moveProject: (projectId: string | undefined, direction: ProjectDirection) =>
      ordering.moveProject(projectId, direction),
    removeTechnology: (index: number) => technology.removeTechnology(index),
    requestDeleteProject: (id?: string) => mutations.requestDeleteProject(id),
  };
}

import { beforeEach, describe, expect, it, vi } from "vitest";
import { ref } from "vue";
import { createFloatingChatWidgetPanelActions } from "./floating-chat-widget-actions";

const toast = {
  error: vi.fn(),
  success: vi.fn(),
  info: vi.fn(),
  warning: vi.fn(),
};
const t = (key: string) => key;
const inputRef = ref<HTMLTextAreaElement | null>(null);

describe("createFloatingChatWidgetPanelActions", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("loads speech settings only when opening the speech settings panel", async () => {
    const isOpen = ref(false);
    const isSpeechSettingsOpen = ref(false);
    const unreadCount = ref(0);
    const ensureSpeechConfigLoaded = vi.fn(() => Promise.resolve());

    const panelActions = createFloatingChatWidgetPanelActions({
      isOpen,
      isSpeechSettingsOpen,
      unreadCount,
      inputRef,
      ensureSpeechConfigLoaded,
      toast,
      t,
    });

    await panelActions.toggleSpeechSettings();
    expect(ensureSpeechConfigLoaded).toHaveBeenCalledTimes(1);
    expect(isSpeechSettingsOpen.value).toBe(true);

    await panelActions.toggleSpeechSettings();
    expect(ensureSpeechConfigLoaded).toHaveBeenCalledTimes(1);
    expect(isSpeechSettingsOpen.value).toBe(false);
  });

  it("keeps the speech settings panel closed and reports an error when loading fails", async () => {
    const isOpen = ref(false);
    const isSpeechSettingsOpen = ref(false);
    const unreadCount = ref(0);
    const ensureSpeechConfigLoaded = vi.fn(() => Promise.reject(new Error("settings unavailable")));

    const panelActions = createFloatingChatWidgetPanelActions({
      isOpen,
      isSpeechSettingsOpen,
      unreadCount,
      inputRef,
      ensureSpeechConfigLoaded,
      toast,
      t,
    });

    await panelActions.toggleSpeechSettings();

    expect(isSpeechSettingsOpen.value).toBe(false);
    expect(toast.error).toHaveBeenCalledWith("settings unavailable");
  });
});

import { APP_ROUTE_BUILDERS, APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import { useDebouncedValue } from "~/composables/useDebouncedValue";
import {
  STUDIO_INDEX_FILTER_DEBOUNCE_MS,
  STUDIO_INDEX_INITIAL_VISIBLE_COUNT,
  STUDIO_INDEX_VISIBLE_INCREMENT,
} from "~/constants/studios";
import { getErrorMessage } from "~/utils/errors";
import { buildInterviewStudioNavigation } from "~/utils/interview-navigation";
import { queryValueToString } from "~/utils/route-query";

function sortUniqueOptions(values: string[]): string[] {
  return [...new Set(values.filter((value) => value.trim().length > 0))].sort((left, right) =>
    left.localeCompare(right),
  );
}

function createStudiosIndexRuntime() {
  const { $toast } = useNuxtApp();
  const route = useRoute();
  const router = useRouter();
  const { t } = useI18n();
  const { studios, loading: studioLoading, fetchStudios } = useStudio();

  const pageError = ref<string | null>(null);
  const searchQuery = ref("");
  const showPreviewModal = ref(false);
  const previewStudioId = ref("");
  const visibleStudioCount = ref(STUDIO_INDEX_INITIAL_VISIBLE_COUNT);
  const filters = reactive({
    remoteWork: false,
    size: "",
    type: "",
  });

  return {
    fetchStudios,
    filters,
    pageError,
    previewStudioId,
    route,
    router,
    searchQuery,
    showPreviewModal,
    studioLoading,
    studios,
    t,
    toast: $toast,
    visibleStudioCount,
  };
}

function createStudiosIndexActions(input: ReturnType<typeof createStudiosIndexRuntime>) {
  const previewActions = createStudiosPreviewActions(input);

  function showErrorToast(message: string) {
    if (import.meta.client) {
      input.toast.error(message);
    }
  }

  async function loadStudios() {
    input.pageError.value = null;
    const studiosResult = await settlePromise(
      input.fetchStudios(),
      input.t("studiosIndex.errors.loadFailed"),
    );
    if (!studiosResult.ok) {
      input.pageError.value = getErrorMessage(
        studiosResult.error,
        input.t("studiosIndex.errors.loadFailed"),
      );
      showErrorToast(input.pageError.value);
    }
  }

  function clearFilters() {
    input.searchQuery.value = "";
    input.filters.type = "";
    input.filters.size = "";
    input.filters.remoteWork = false;
    input.visibleStudioCount.value = STUDIO_INDEX_INITIAL_VISIBLE_COUNT;
  }

  function showMoreStudios(filteredCount: number) {
    input.visibleStudioCount.value = Math.min(
      filteredCount,
      input.visibleStudioCount.value + STUDIO_INDEX_VISIBLE_INCREMENT,
    );
  }

  return {
    clearFilters,
    closeStudioPreview: previewActions.closeStudioPreview,
    loadStudios,
    openStudioPreview: previewActions.openStudioPreview,
    showMoreStudios,
    startInterview: previewActions.startInterview,
    viewStudio: previewActions.viewStudio,
  };
}

function createStudiosPreviewActions(input: ReturnType<typeof createStudiosIndexRuntime>) {
  async function setPreviewRouteStudioId(id: string | null): Promise<void> {
    const nextQuery = { ...input.route.query };
    if (id) {
      nextQuery[APP_ROUTE_QUERY_KEYS.studioId] = id;
    } else {
      delete nextQuery[APP_ROUTE_QUERY_KEYS.studioId];
    }
    await input.router.replace({ query: nextQuery });
  }

  async function openStudioPreview(id: string) {
    input.previewStudioId.value = id;
    input.showPreviewModal.value = true;
    await setPreviewRouteStudioId(id);
  }

  async function closeStudioPreview(routeStudioId: string) {
    input.showPreviewModal.value = false;
    input.previewStudioId.value = "";
    if (routeStudioId) {
      await setPreviewRouteStudioId(null);
    }
  }

  async function viewStudio(id: string, routeStudioId: string) {
    await closeStudioPreview(routeStudioId);
    await input.router.push(APP_ROUTE_BUILDERS.studioDetail(id));
  }

  async function startInterview(studioId: string, routeStudioId: string) {
    await closeStudioPreview(routeStudioId);
    await input.router.push(buildInterviewStudioNavigation(studioId));
  }

  return {
    closeStudioPreview,
    openStudioPreview,
    startInterview,
    viewStudio,
  };
}

function createStudiosIndexDerivedState(input: ReturnType<typeof createStudiosIndexRuntime>) {
  const debouncedSearchQuery = useDebouncedValue(
    input.searchQuery,
    STUDIO_INDEX_FILTER_DEBOUNCE_MS,
  );
  const filterOptions = createStudiosIndexFilterOptions(input.studios);
  const filterResults = createStudiosFilteredResults({
    debouncedSearchQuery,
    filters: input.filters,
    studios: input.studios,
  });
  const loading = computed(() => input.studioLoading.value);
  const totalStudios = computed(() => input.studios.value.length);
  const remoteFriendlyStudios = computed(
    () => input.studios.value.filter((studio) => studio.remoteWork).length,
  );
  const previewStudio = computed(
    () => input.studios.value.find((studio) => studio.id === input.previewStudioId.value) ?? null,
  );
  const routeStudioId = computed(() =>
    queryValueToString(input.route.query[APP_ROUTE_QUERY_KEYS.studioId]),
  );
  const visibleStudios = computed(() =>
    filterResults.filteredStudios.value.slice(0, input.visibleStudioCount.value),
  );
  const hasAdditionalStudios = computed(
    () => visibleStudios.value.length < filterResults.filteredStudios.value.length,
  );

  return {
    debouncedSearchQuery,
    filteredStudios: filterResults.filteredStudios,
    hasAdditionalStudios,
    loading,
    previewStudio,
    remoteFriendlyStudios,
    routeStudioId,
    studioSizeOptions: filterOptions.studioSizeOptions,
    studioTypeOptions: filterOptions.studioTypeOptions,
    totalStudios,
    visibleStudios,
  };
}

function createStudiosIndexFilterOptions(studios: ReturnType<typeof useStudio>["studios"]) {
  const studioTypeOptions = computed(() =>
    sortUniqueOptions(studios.value.map((studio) => studio.type)),
  );
  const studioSizeOptions = computed(() =>
    sortUniqueOptions(studios.value.map((studio) => studio.size)),
  );

  return {
    studioSizeOptions,
    studioTypeOptions,
  };
}

function createStudiosFilteredResults(input: {
  debouncedSearchQuery: Ref<string>;
  filters: {
    remoteWork: boolean;
    size: string;
    type: string;
  };
  studios: ReturnType<typeof useStudio>["studios"];
}) {
  const searchableStudios = computed(() =>
    input.studios.value.map((studio) => ({
      searchableText: `${studio.name} ${studio.description ?? ""} ${studio.location}`.toLowerCase(),
      studio,
    })),
  );
  const filteredStudios = computed(() =>
    filterStudios({
      entries: searchableStudios.value,
      filters: input.filters,
      query: input.debouncedSearchQuery.value,
    }),
  );

  return {
    filteredStudios,
  };
}

function filterStudios(input: {
  entries: Array<{
    searchableText: string;
    studio: ReturnType<typeof useStudio>["studios"]["value"][number];
  }>;
  filters: {
    remoteWork: boolean;
    size: string;
    type: string;
  };
  query: string;
}) {
  let result = input.entries;

  const query = input.query.trim().toLowerCase();
  if (query.length > 0) {
    result = result.filter((entry) => entry.searchableText.includes(query));
  }
  if (input.filters.type.length > 0) {
    result = result.filter((entry) => entry.studio.type === input.filters.type);
  }
  if (input.filters.size.length > 0) {
    result = result.filter((entry) => entry.studio.size === input.filters.size);
  }
  if (input.filters.remoteWork) {
    result = result.filter((entry) => entry.studio.remoteWork);
  }

  return result.map((entry) => entry.studio);
}

function registerStudiosIndexEffects(input: {
  derived: ReturnType<typeof createStudiosIndexDerivedState>;
  runtime: ReturnType<typeof createStudiosIndexRuntime>;
}) {
  watch(
    () => ({
      remoteWork: input.runtime.filters.remoteWork,
      search: input.derived.debouncedSearchQuery.value,
      size: input.runtime.filters.size,
      type: input.runtime.filters.type,
    }),
    () => {
      input.runtime.visibleStudioCount.value = STUDIO_INDEX_INITIAL_VISIBLE_COUNT;
    },
  );

  watch(input.derived.filteredStudios, (nextStudios) => {
    if (nextStudios.length < input.runtime.visibleStudioCount.value) {
      input.runtime.visibleStudioCount.value = nextStudios.length;
    }
  });

  watch(
    input.derived.routeStudioId,
    (studioId) => {
      if (!studioId) {
        input.runtime.showPreviewModal.value = false;
        input.runtime.previewStudioId.value = "";
        return;
      }

      input.runtime.previewStudioId.value = studioId;
      input.runtime.showPreviewModal.value = true;
    },
    { immediate: true },
  );
}

export function useStudiosIndexPage() {
  const runtime = createStudiosIndexRuntime();
  const actions = createStudiosIndexActions(runtime);
  const derived = createStudiosIndexDerivedState(runtime);
  registerStudiosIndexEffects({
    derived,
    runtime,
  });

  return {
    clearFilters: actions.clearFilters,
    closeStudioPreview: () => actions.closeStudioPreview(derived.routeStudioId.value),
    filteredStudios: derived.filteredStudios,
    filters: runtime.filters,
    hasAdditionalStudios: derived.hasAdditionalStudios,
    loadStudios: actions.loadStudios,
    loading: derived.loading,
    openStudioPreview: actions.openStudioPreview,
    pageError: runtime.pageError,
    previewStudio: derived.previewStudio,
    remoteFriendlyStudios: derived.remoteFriendlyStudios,
    searchQuery: runtime.searchQuery,
    showMoreStudios: () => actions.showMoreStudios(derived.filteredStudios.value.length),
    showPreviewModal: runtime.showPreviewModal,
    startInterview: (studioId: string) =>
      actions.startInterview(studioId, derived.routeStudioId.value),
    studioSizeOptions: derived.studioSizeOptions,
    studioTypeOptions: derived.studioTypeOptions,
    totalStudios: derived.totalStudios,
    viewStudio: (id: string) => actions.viewStudio(id, derived.routeStudioId.value),
    visibleStudios: derived.visibleStudios,
  };
}

