import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { UserProfile } from "@bao/shared/types/user";
import { readonly } from "vue";
import { useI18n } from "vue-i18n";
import { useState } from "#imports";
import { toUserProfile } from "./api-normalizer-user";
import { assertApiResponse, requireValue, withLoadingState } from "./async-flow";
import { useApi } from "./useApi";

type ApiClient = ReturnType<typeof useApi>;
type UpdateUserProfileInput = NonNullable<Parameters<ApiClient["user"]["profile"]["put"]>[0]>;

/**
 * User profile management composable.
 */
export function useUser() {
  const api = useApi();
  const { t } = useI18n();
  const profile = useState<UserProfile | null>(STATE_KEYS.USER_PROFILE, () => null);
  const loading = useState(STATE_KEYS.USER_LOADING, () => false);

  async function fetchProfile() {
    return withLoadingState(loading, async () => {
      const { data, error } = await api.user.profile.get();
      assertApiResponse(error, t("apiErrors.user.fetchProfileFailed"));
      const normalized = requireValue(toUserProfile(data), t("apiErrors.user.invalidPayload"));
      profile.value = normalized;
    });
  }

  async function updateProfile(updates: UpdateUserProfileInput) {
    return withLoadingState(loading, async () => {
      const { data, error } = await api.user.profile.put(updates);
      assertApiResponse(error, t("apiErrors.user.updateProfileFailed"));
      const normalized = requireValue(toUserProfile(data), t("apiErrors.user.invalidPayload"));
      profile.value = normalized;
    });
  }

  return {
    profile: readonly(profile),
    loading: readonly(loading),
    fetchProfile,
    updateProfile,
  };
}

import { WS_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { type RpaRunEvent, rpaRunEventSchema } from "@bao/shared/schemas/rpa-events.schema";
import { safeParseJson } from "@bao/shared/utils/json";
import type { ClientApiRequestRuntime } from "~/composables/api-request";
import { resolveWebSocketEndpoint } from "~/utils/endpoints";

/**
 * Subscribes to automation run events over WS_ENDPOINTS.automation.
 */
export function createAutomationRunSubscription(runtime: ClientApiRequestRuntime, wsBase: string) {
  return (runId: string, onEvent: (event: RpaRunEvent) => void): (() => void) => {
    const wsUrl = resolveWebSocketEndpoint(wsBase, runtime.requestUrl, WS_ENDPOINTS.automation);
    const ws = new WebSocket(wsUrl);

    ws.onopen = () => {
      ws.send(
        JSON.stringify({
          type: "subscribe",
          runId,
        }),
      );
    };

    ws.onmessage = (event) => {
      if (typeof event.data !== "string") {
        return;
      }
      const parsedPayload = safeParseJson(event.data);
      const parsedEvent = rpaRunEventSchema.safeParse(parsedPayload);
      if (parsedEvent.success) {
        onEvent(parsedEvent.data);
      }
    };

    return () => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: "unsubscribe",
            runId,
          }),
        );
      }
      ws.close();
    };
  };
}

import {
  type CareerPathway,
  type ReadinessAssessment,
  SKILL_READINESS_FEEDBACK_IDS,
  SKILL_READINESS_IMPROVEMENT_IDS,
  SKILL_READINESS_NEXT_STEP_IDS,
  type SkillReadinessFeedbackId,
  type SkillReadinessImprovementId,
  type SkillReadinessNextStepId,
} from "@bao/shared/types/skill-mapping";
import { isRecord } from "@bao/shared/utils/type-guards";

export interface SkillsPathwaysBootstrapData {
  readonly pathways: readonly CareerPathway[];
  readonly readiness: ReadinessAssessment;
}

export interface SkillsPathwaysGamificationProgress {
  readonly level?: number;
  readonly xp?: number;
}

const toSkillReadinessFeedbackId = (value: unknown): SkillReadinessFeedbackId | null => {
  if (typeof value !== "string") {
    return null;
  }
  return isSkillReadinessFeedbackId(value) ? value : null;
};

const isSkillReadinessFeedbackId = (value: string): value is SkillReadinessFeedbackId =>
  SKILL_READINESS_FEEDBACK_IDS.some((entry) => entry === value);

const isSkillReadinessImprovementId = (value: string): value is SkillReadinessImprovementId =>
  SKILL_READINESS_IMPROVEMENT_IDS.some((entry) => entry === value);

const isSkillReadinessNextStepId = (value: string): value is SkillReadinessNextStepId =>
  SKILL_READINESS_NEXT_STEP_IDS.some((entry) => entry === value);

const toCareerSalary = (value: unknown): CareerPathway["averageSalary"] => {
  if (!(isRecord(value) && typeof value.min === "number" && typeof value.max === "number")) {
    return;
  }

  return {
    min: value.min,
    max: value.max,
    currency: typeof value.currency === "string" ? value.currency : undefined,
  };
};

const toCareerStage = (value: unknown): CareerPathway["stages"][number] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const title = typeof value.title === "string" ? value.title : undefined;
  const duration = typeof value.duration === "string" ? value.duration : undefined;
  const description = typeof value.description === "string" ? value.description : undefined;
  if (!(title && duration && description)) {
    return null;
  }

  const stage: CareerPathway["stages"][number] = { title, duration, description };
  if (typeof value.completed === "boolean") {
    stage.completed = value.completed;
  }
  if (typeof value.current === "boolean") {
    stage.current = value.current;
  }
  if (Array.isArray(value.requirements)) {
    stage.requirements = value.requirements.filter(
      (entry): entry is string => typeof entry === "string",
    );
  }
  if (Array.isArray(value.outcomes)) {
    stage.outcomes = value.outcomes.filter((entry): entry is string => typeof entry === "string");
  }

  return stage;
};

const toCareerPathway = (value: unknown): CareerPathway | null => {
  if (!isRecord(value)) {
    return null;
  }

  const id = typeof value.id === "string" ? value.id : undefined;
  const title = typeof value.title === "string" ? value.title : undefined;
  const description = typeof value.description === "string" ? value.description : undefined;
  const estimatedTimeToEntry =
    typeof value.estimatedTimeToEntry === "string" ? value.estimatedTimeToEntry : undefined;
  if (!(id && title && description && estimatedTimeToEntry)) {
    return null;
  }

  const stages = Array.isArray(value.stages)
    ? value.stages
        .map((entry) => toCareerStage(entry))
        .filter((entry): entry is CareerPathway["stages"][number] => entry !== null)
    : [];
  const trend = typeof value.jobMarketTrend === "string" ? value.jobMarketTrend : undefined;

  return {
    id,
    title,
    description,
    detailedDescription:
      typeof value.detailedDescription === "string" ? value.detailedDescription : undefined,
    matchScore: typeof value.matchScore === "number" ? value.matchScore : 0,
    stages,
    requiredSkills: Array.isArray(value.requiredSkills)
      ? value.requiredSkills.filter((entry): entry is string => typeof entry === "string")
      : [],
    estimatedTimeToEntry,
    icon: typeof value.icon === "string" ? value.icon : undefined,
    averageSalary: toCareerSalary(value.averageSalary),
    jobMarketTrend:
      trend === "growing" || trend === "stable" || trend === "declining" ? trend : "stable",
  };
};

const toReadinessCategory = (
  value: unknown,
): ReadinessAssessment["categories"]["technical"] | null => {
  if (!(isRecord(value) && typeof value.score === "number")) {
    return null;
  }
  const feedbackId = toSkillReadinessFeedbackId(value.feedbackId);
  if (!feedbackId) {
    return null;
  }

  return {
    score: value.score,
    feedbackId,
    strengths: Array.isArray(value.strengths)
      ? value.strengths.filter((entry): entry is string => typeof entry === "string")
      : [],
    improvements: Array.isArray(value.improvements)
      ? value.improvements.filter(
          (entry): entry is SkillReadinessImprovementId =>
            typeof entry === "string" && isSkillReadinessImprovementId(entry),
        )
      : [],
  };
};

const toTargetRoleReadiness = (
  value: unknown,
): NonNullable<ReadinessAssessment["targetRoleReadiness"]> =>
  Array.isArray(value)
    ? value
        .map((entry) => toRoleReadiness(entry))
        .filter(
          (entry): entry is NonNullable<ReadinessAssessment["targetRoleReadiness"]>[number] =>
            entry !== null,
        )
    : [];

const toRoleReadiness = (
  entry: unknown,
): NonNullable<ReadinessAssessment["targetRoleReadiness"]>[number] | null => {
  if (!isRecord(entry)) {
    return null;
  }
  const roleId = typeof entry.roleId === "string" ? entry.roleId : undefined;
  const roleTitle = typeof entry.roleTitle === "string" ? entry.roleTitle : undefined;
  if (!(roleId && roleTitle)) {
    return null;
  }

  const readiness: NonNullable<ReadinessAssessment["targetRoleReadiness"]>[number] = {
    roleId,
    roleTitle,
    readinessScore: typeof entry.readinessScore === "number" ? entry.readinessScore : 0,
    missingSkills: Array.isArray(entry.missingSkills)
      ? entry.missingSkills.filter((skill): skill is string => typeof skill === "string")
      : [],
    matchingSkills: Array.isArray(entry.matchingSkills)
      ? entry.matchingSkills.filter((skill): skill is string => typeof skill === "string")
      : [],
    recommendedActions: Array.isArray(entry.recommendedActions)
      ? entry.recommendedActions.filter((action): action is string => typeof action === "string")
      : [],
  };
  if (typeof entry.timeToReady === "string") {
    readiness.timeToReady = entry.timeToReady;
  }
  return readiness;
};

const toReadinessAssessment = (value: unknown): ReadinessAssessment | null => {
  if (!(isRecord(value) && isRecord(value.categories))) {
    return null;
  }

  const categories = value.categories;
  const technical = toReadinessCategory(categories.technical);
  const softSkills = toReadinessCategory(categories.softSkills);
  const industryKnowledge = toReadinessCategory(categories.industryKnowledge);
  const portfolio = toReadinessCategory(categories.portfolio);
  if (!(technical && softSkills && industryKnowledge && portfolio)) {
    return null;
  }

  return {
    overallScore: typeof value.overallScore === "number" ? value.overallScore : 0,
    categories: {
      technical,
      softSkills,
      industryKnowledge,
      portfolio,
    },
    improvementSuggestions: Array.isArray(value.improvementSuggestions)
      ? value.improvementSuggestions.filter(
          (entry): entry is SkillReadinessImprovementId =>
            typeof entry === "string" && isSkillReadinessImprovementId(entry),
        )
      : [],
    nextSteps: Array.isArray(value.nextSteps)
      ? value.nextSteps.filter(
          (entry): entry is SkillReadinessNextStepId =>
            typeof entry === "string" && isSkillReadinessNextStepId(entry),
        )
      : [],
    targetRoleReadiness: toTargetRoleReadiness(value.targetRoleReadiness),
  };
};

export const toSkillsPathwaysBootstrapData = (
  value: unknown,
): SkillsPathwaysBootstrapData | null => {
  if (!(isRecord(value) && Array.isArray(value.pathways) && isRecord(value.readiness))) {
    return null;
  }

  const pathways = value.pathways
    .map((entry) => toCareerPathway(entry))
    .filter((entry): entry is CareerPathway => entry !== null);
  const readiness = toReadinessAssessment(value.readiness);
  if (!readiness) {
    return null;
  }

  return {
    pathways,
    readiness,
  };
};

export const toGamificationProgress = (
  value: unknown,
): SkillsPathwaysGamificationProgress | null => {
  if (!isRecord(value)) {
    return null;
  }
  const level = typeof value.level === "number" ? value.level : undefined;
  const xp = typeof value.xp === "number" ? value.xp : undefined;
  return level === undefined && xp === undefined ? null : { level, xp };
};

import { useNuxtApp as useNuxtAppInternal, useState as useStateInternal } from "nuxt/app";

/**
 * Internal Nuxt runtime boundary for composable consumers.
 */
export { useNuxtAppInternal as useNuxtRuntimeApp, useStateInternal as useNuxtState };

import { computed } from "vue";
import {
  API_DOCS_ASYNC_DATA_KEY,
  type ApiDocsTranslate,
  UNKNOWN_TAG_LABEL_KEY,
} from "~/composables/api-docs-page-contracts";
import { useApi } from "~/composables/useApi";
import type { ApiDocsUiState, ApiEndpointGroup, OpenApiSpec } from "~/types/api-docs";
import { buildApiEndpointGroups } from "~/utils/api-docs-endpoints";
import { readOpenApiSpec } from "~/utils/api-docs-openapi";
import { toApiDocsUiStateFromStatusCode, toErrorStatusCode } from "~/utils/api-docs-status";
import { requireApiResponsePayload } from "~/utils/api-response";

interface ApiDocsPageDataOptions {
  readonly t: ApiDocsTranslate;
}

export const useApiDocsPageData = ({ t }: ApiDocsPageDataOptions) => {
  const api = useApi();

  const fetchOpenApiSpec = async (): Promise<OpenApiSpec | null> => {
    const raw = requireApiResponsePayload(
      await api.docs.api.json.get(),
      t("apiDocs.state.errorNonRetryable"),
    );
    return readOpenApiSpec(raw);
  };

  const {
    data: parsedSpec,
    status: rawSpecStatus,
    error: rawSpecError,
    refresh: refreshSpec,
  } = useAsyncData<OpenApiSpec | null>(API_DOCS_ASYNC_DATA_KEY, fetchOpenApiSpec, {
    server: true,
    default: () => null,
  });

  const endpointGroups = computed<readonly ApiEndpointGroup[]>(() =>
    buildApiEndpointGroups(parsedSpec.value, t(UNKNOWN_TAG_LABEL_KEY)),
  );
  const endpointCount = computed(() => {
    const groups = endpointGroups.value;
    let total = 0;
    for (const group of groups) {
      total += group.endpoints.length;
    }
    return total;
  });
  const docsUiState = computed<ApiDocsUiState>(() => {
    if (rawSpecStatus.value === "pending") {
      return "loading";
    }
    if (rawSpecError.value) {
      return toApiDocsUiStateFromStatusCode(toErrorStatusCode(rawSpecError.value));
    }
    if (endpointCount.value === 0) {
      return "empty";
    }
    return "success";
  });

  return {
    docsUiState,
    endpointGroups,
    rawSpecError,
    refreshSpec,
  };
};

import {
  type AppDataTheme,
  normalizeAppDataTheme,
  THEME_NAMES,
} from "@bao/shared/constants/branding";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import { readonly } from "vue";
import { useCookie, useState } from "#imports";
const NUM_365 = 365;

/**
 * Theme toggle: daisyUI `corporate` (light) / `business` (dark), driven by `data-theme`.
 * Persists via cookie (SSOT with settings sync).
 */
export function useTheme() {
  const theme = useState<AppDataTheme>(STATE_KEYS.APP_THEME, () => THEME_NAMES.light);
  const themeCookie = useCookie<string | null>(THEME_NAMES.storageKey, {
    default: () => null,
    path: "/",
    sameSite: "lax",
    maxAge: 60 * 60 * 24 * NUM_365,
  });

  function setTheme(newTheme: AppDataTheme, options: { persist?: boolean } = {}) {
    theme.value = newTheme;
    if (import.meta.client) {
      document.documentElement.setAttribute("data-theme", newTheme);
    }
    if (options.persist !== false) {
      themeCookie.value = newTheme;
    }
  }

  function toggleTheme() {
    setTheme(theme.value === THEME_NAMES.light ? THEME_NAMES.dark : THEME_NAMES.light);
  }

  function initTheme(preferredTheme?: AppDataTheme) {
    // Settings are the persisted SSOT; cookie is a hydration cache only.
    // Never apply prefers-color-scheme here — that diverges SSR vs client first paint
    // (hydration mismatch on auth-shell / first visit without cookie).
    if (preferredTheme) {
      setTheme(preferredTheme, { persist: true });
      return;
    }

    const savedRaw = themeCookie.value;
    if (savedRaw) {
      const normalized = normalizeAppDataTheme(savedRaw);
      setTheme(normalized, { persist: normalized !== savedRaw });
    }
  }

  /**
   * Post-hydrate only: honor OS dark preference when user has no cookie yet.
   * Safe after hydration — does not run during setup/SSR.
   */
  function applySystemThemePreferenceIfUnset(): void {
    if (!import.meta.client) return;
    if (themeCookie.value) return;
    if (window.matchMedia("(prefers-color-scheme: dark)").matches) {
      setTheme(THEME_NAMES.dark, { persist: false });
    }
  }

  return {
    theme: readonly(theme),
    setTheme,
    toggleTheme,
    initTheme,
    applySystemThemePreferenceIfUnset,
  };
}

import { APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import { settlePromise } from "~/composables/async-flow";
import { getErrorMessage } from "~/utils/errors";
import type { InterviewHistoryPageContext } from "./interview-history-page-contracts";
import { normalizeInterviewHistoryQuerySession } from "./interview-history-page-state";

const createLoadSelectedSession = (context: InterviewHistoryPageContext) => {
  return async (nextSessionId: string | null): Promise<void> => {
    context.state.detailError.value = "";

    if (!nextSessionId) {
      context.state.selectedSessionId.value = null;
      context.state.selectedSession.value = null;
      return;
    }

    if (
      context.state.selectedSessionId.value === nextSessionId &&
      context.state.selectedSession.value
    ) {
      return;
    }

    context.state.selectedSessionId.value = nextSessionId;
    context.state.detailLoading.value = true;
    const sessionResult = await settlePromise(
      context.getSession(nextSessionId),
      context.t("interviewHistory.detailLoadErrorFallback"),
    );
    context.state.detailLoading.value = false;

    if (!sessionResult.ok) {
      context.state.detailError.value = getErrorMessage(
        sessionResult.error,
        context.t("interviewHistory.detailLoadErrorFallback"),
      );
      context.toast.error(context.state.detailError.value);
      context.state.selectedSession.value = null;
      return;
    }

    context.state.selectedSession.value = sessionResult.value;
    if (!context.state.selectedSession.value) {
      context.state.detailError.value = context.t("interviewHistory.sessionNotFound");
    }
  };
};

const createLoadInterviewSessions = (context: InterviewHistoryPageContext) => {
  return async (): Promise<void> => {
    context.state.sessionsError.value = "";
    const sessionsResult = await settlePromise(
      context.fetchSessions(),
      context.t("interviewHistory.fetchErrorFallback"),
    );
    if (!sessionsResult.ok) {
      context.state.sessionsError.value = getErrorMessage(
        sessionsResult.error,
        context.t("interviewHistory.fetchErrorFallback"),
      );
      context.toast.error(context.state.sessionsError.value);
    }
  };
};

export const createInterviewHistoryDetailActions = (context: InterviewHistoryPageContext) => {
  const loadSelectedSession = createLoadSelectedSession(context);
  const loadInterviewSessions = createLoadInterviewSessions(context);

  const viewSessionDetail = async (id: string): Promise<void> => {
    await context.router.replace({
      query: {
        ...context.route.query,
        [APP_ROUTE_QUERY_KEYS.sessionId]: id,
      },
    });
  };

  const closeDetail = async (): Promise<void> => {
    const nextQuery = { ...context.route.query };
    delete nextQuery[APP_ROUTE_QUERY_KEYS.sessionId];
    await context.router.replace({ query: nextQuery });
  };

  const retryDetail = async (): Promise<void> => {
    await loadSelectedSession(context.state.selectedSessionId.value);
  };

  return {
    loadInterviewSessions,
    loadSelectedSession,
    viewSessionDetail,
    closeDetail,
    retryDetail,
  };
};

export const useInterviewHistoryPageSessionSync = (
  context: InterviewHistoryPageContext,
  loadSelectedSession: (nextSessionId: string | null) => Promise<void>,
) => {
  watch(
    () => context.route.query[APP_ROUTE_QUERY_KEYS.sessionId],
    async (nextSessionQuery) => {
      await loadSelectedSession(normalizeInterviewHistoryQuerySession(nextSessionQuery));
    },
    { immediate: true },
  );
};

import { $fetch } from "ofetch";
import { useRequestURL, useRuntimeConfig } from "#imports";
import { getStoredApiKey } from "~/plugins/eden";
import { resolveApiEndpoint } from "~/utils/endpoints";

const CONTENT_DISPOSITION_ENCODED_FILENAME_PATTERN = /filename\*=UTF-8''([^;]+)/i;
const CONTENT_DISPOSITION_QUOTED_FILENAME_PATTERN = /filename="([^"]+)"/i;
const CONTENT_DISPOSITION_PLAIN_FILENAME_PATTERN = /filename=([^;]+)/i;

export interface ClientApiRequestRuntime {
  apiBase: string;
  requestUrl: URL;
}

export type ClientApiHttpMethod = "GET" | "POST" | "PUT" | "DELETE" | "PATCH" | "HEAD";

interface ClientApiRequestOptions {
  method?: ClientApiHttpMethod;
  body?: BodyInit | object | null;
  query?: Record<string, string | number | boolean | undefined>;
  headers?: Record<string, string>;
}

export const toClientApiHttpMethod = (method: string): ClientApiHttpMethod | null => {
  switch (method.trim().toUpperCase()) {
    case "GET":
      return "GET";
    case "POST":
      return "POST";
    case "PUT":
      return "PUT";
    case "DELETE":
      return "DELETE";
    case "PATCH":
      return "PATCH";
    case "HEAD":
      return "HEAD";
    default:
      return null;
  }
};

/**
 * Resolves the canonical client request runtime for direct API endpoint calls.
 */
export function useClientApiRequestRuntime(): ClientApiRequestRuntime {
  return {
    apiBase: String(useRuntimeConfig().public.apiBase || "/"),
    requestUrl: useRequestURL(),
  };
}

const buildAuthorizationHeaders = (): Record<string, string> => {
  const key = getStoredApiKey();
  return key ? { Authorization: `Bearer ${key}` } : {};
};

export const buildClientApiHeaders = (
  headers: Record<string, string> = {},
): Record<string, string> => ({
  ...buildAuthorizationHeaders(),
  ...headers,
});

function isBodyInitValue(value: BodyInit | object | null | undefined): value is BodyInit {
  return (
    typeof value === "string" ||
    value instanceof Blob ||
    value instanceof FormData ||
    value instanceof URLSearchParams ||
    value instanceof ArrayBuffer ||
    ArrayBuffer.isView(value) ||
    value instanceof ReadableStream
  );
}

function createRequestBody(body: BodyInit | object | null | undefined): BodyInit | undefined {
  if (body == null) {
    return;
  }

  if (isBodyInitValue(body)) {
    return body;
  }

  return JSON.stringify(body);
}

function resolveDownloadFilename(
  contentDisposition: string | null,
  fallbackFilename: string,
): string {
  if (!contentDisposition) {
    return fallbackFilename;
  }

  const encodedMatch = CONTENT_DISPOSITION_ENCODED_FILENAME_PATTERN.exec(contentDisposition);
  if (encodedMatch?.[1]) {
    return encodedMatch[1];
  }

  const quotedMatch = CONTENT_DISPOSITION_QUOTED_FILENAME_PATTERN.exec(contentDisposition);
  if (quotedMatch?.[1]) {
    return quotedMatch[1];
  }

  const plainMatch = CONTENT_DISPOSITION_PLAIN_FILENAME_PATTERN.exec(contentDisposition);
  return plainMatch?.[1]?.trim() || fallbackFilename;
}

function triggerFileDownload(blob: Blob, filename: string): void {
  if (!import.meta.client) {
    return;
  }
  const objectUrl = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = objectUrl;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(objectUrl);
}

export async function downloadApiFile(
  runtime: ClientApiRequestRuntime,
  endpoint: string,
  options: ClientApiRequestOptions,
  fallbackFilename: string,
): Promise<void> {
  const body = createRequestBody(options.body);
  const headers = buildClientApiHeaders(options.headers);
  const shouldSetJsonContentType =
    body !== undefined && !isBodyInitValue(options.body) && !("Content-Type" in headers);

  const response = await fetch(resolveApiEndpoint(runtime.apiBase, runtime.requestUrl, endpoint), {
    method: options.method ?? "GET",
    body,
    headers: shouldSetJsonContentType
      ? {
          ...headers,
          "Content-Type": "application/json",
        }
      : headers,
  });

  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`);
  }

  const blob = await response.blob();
  triggerFileDownload(
    blob,
    resolveDownloadFilename(response.headers.get("content-disposition"), fallbackFilename),
  );
}

/**
 * Executes a typed client API request against a canonical shared endpoint.
 */
export function requestApi<TResponse>(
  runtime: ClientApiRequestRuntime,
  endpoint: string,
  options: ClientApiRequestOptions = {},
): Promise<TResponse> {
  return $fetch<TResponse>(resolveApiEndpoint(runtime.apiBase, runtime.requestUrl, endpoint), {
    ...options,
    headers: buildClientApiHeaders(options.headers),
  });
}

/**
 * Executes a raw request against an already-resolved absolute API URL with canonical auth.
 */
export function requestResolvedApiRaw(
  absoluteUrl: string,
  options: ClientApiRequestOptions & { responseType?: "text" } = {},
) {
  return $fetch.raw(absoluteUrl, {
    ...options,
    headers: buildClientApiHeaders(options.headers),
    credentials: "include",
    responseType: options.responseType ?? "text",
  });
}

import { isRecord } from "@bao/shared/utils/type-guards";
import type { ComputedRef, Ref } from "vue";
import { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import { getErrorMessage } from "~/utils/errors";
import { PERCENT_MAX } from "@bao/shared/constants/numeric";

type AnalyticsByBreakdown = Record<string, number>;

type AnalyticsTechnology = {
  name: string;
  count: number;
};

type StudioAnalytics = {
  totalStudios: number;
  byType: AnalyticsByBreakdown;
  bySize: AnalyticsByBreakdown;
  remoteWorkStudios: number;
  topTechnologies: AnalyticsTechnology[];
};

type StudioAnalyticsLoadResult = {
  data: StudioAnalytics | null;
  errorMessage: string | null;
};

type StudioAnalyticsMetrics = {
  bySizeEntries: ComputedRef<[string, number][]>;
  byTypeEntries: ComputedRef<[string, number][]>;
  indieStudiosCount: ComputedRef<number>;
  onSiteOnlyCount: ComputedRef<number>;
  remoteWorkPercentage: ComputedRef<number>;
  remoteWorkStudios: ComputedRef<number>;
  topTechnologies: ComputedRef<AnalyticsTechnology[]>;
  totalStudios: ComputedRef<number>;
};

function toBreakdown(value: unknown): AnalyticsByBreakdown {
  if (!isRecord(value)) {
    return {};
  }

  const breakdown: AnalyticsByBreakdown = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "number") {
      breakdown[key] = entry;
    }
  }

  return breakdown;
}

function toTechnology(value: unknown): AnalyticsTechnology | null {
  if (!isRecord(value)) {
    return null;
  }

  const name = typeof value.name === "string" ? value.name : "";
  const count = typeof value.count === "number" ? value.count : 0;
  if (!name) {
    return null;
  }

  return { name, count };
}

function mapAnalyticsResponse(data: unknown): StudioAnalytics | null {
  if (!isRecord(data)) {
    return null;
  }

  return {
    totalStudios: typeof data.totalStudios === "number" ? data.totalStudios : 0,
    byType: toBreakdown(data.byType),
    bySize: toBreakdown(data.bySize),
    remoteWorkStudios: typeof data.remoteWorkStudios === "number" ? data.remoteWorkStudios : 0,
    topTechnologies: Array.isArray(data.topTechnologies)
      ? data.topTechnologies
          .map((technology) => toTechnology(technology))
          .filter((technology): technology is AnalyticsTechnology => technology !== null)
      : [],
  };
}

function createStudioAnalyticsMetrics(
  analytics: Ref<StudioAnalytics | null> | ComputedRef<StudioAnalytics | null>,
): StudioAnalyticsMetrics {
  const totalStudios = computed(() => analytics.value?.totalStudios ?? 0);
  const remoteWorkStudios = computed(() => analytics.value?.remoteWorkStudios ?? 0);
  const remoteWorkPercentage = computed(() => {
    if (totalStudios.value === 0) {
      return 0;
    }

    return Math.round((remoteWorkStudios.value / totalStudios.value) * PERCENT_MAX);
  });
  const byTypeEntries = computed(() => Object.entries(analytics.value?.byType ?? {}));
  const bySizeEntries = computed(() => Object.entries(analytics.value?.bySize ?? {}));
  const topTechnologies = computed(() => analytics.value?.topTechnologies ?? []);
  const indieStudiosCount = computed(() => analytics.value?.byType.Indie ?? 0);
  const onSiteOnlyCount = computed(() => Math.max(0, totalStudios.value - remoteWorkStudios.value));

  return {
    bySizeEntries,
    byTypeEntries,
    indieStudiosCount,
    onSiteOnlyCount,
    remoteWorkPercentage,
    remoteWorkStudios,
    topTechnologies,
    totalStudios,
  };
}

function getMaxCount(items: readonly AnalyticsTechnology[]): number {
  return Math.max(1, ...items.map((item) => item.count));
}

async function loadStudioAnalyticsData(
  api: ReturnType<typeof useApi>,
  loadFailedMessage: string,
): Promise<StudioAnalyticsLoadResult> {
  const analyticsResult = await settlePromise(api.studios.analytics.get(), loadFailedMessage);
  if (!analyticsResult.ok) {
    return {
      data: null,
      errorMessage: getErrorMessage(analyticsResult.error, loadFailedMessage),
    };
  }

  const { data, error } = analyticsResult.value;
  if (error) {
    return {
      data: null,
      errorMessage: getErrorMessage(error, loadFailedMessage),
    };
  }

  return {
    data: mapAnalyticsResponse(data),
    errorMessage: null,
  };
}

/**
 * Studio analytics page state. Payload must flow through `useAsyncData` `data`
 * so SSR HTML and client hydration share one owner (no orphan `ref(null)`).
 */
export function useStudioAnalyticsPage() {
  const { $toast } = useNuxtApp();
  const api = useApi();
  const { t } = useI18n();
  const loadFailedMessage = t("studioAnalytics.errors.loadFailed");

  const {
    data: analyticsPayload,
    pending: loading,
    refresh: refreshAnalytics,
    error: asyncError,
  } = useAsyncData(
    "studio-analytics",
    async () => {
      const result = await loadStudioAnalyticsData(api, loadFailedMessage);
      if (result.errorMessage && import.meta.client) {
        $toast.error(result.errorMessage);
      }
      return result;
    },
    { lazy: false, server: true },
  );

  const analytics = computed(() => analyticsPayload.value?.data ?? null);
  const pageError = computed(
    () =>
      analyticsPayload.value?.errorMessage ??
      (asyncError.value ? getErrorMessage(asyncError.value, loadFailedMessage) : null),
  );
  const metrics = createStudioAnalyticsMetrics(analytics);

  return {
    analytics,
    getMaxCount,
    loading,
    pageError,
    refreshAnalytics,
    ...metrics,
  };
}

import { DEFAULT_SPEECH_SETTINGS, SPEECH_PROVIDER_OPTIONS } from "@bao/shared/constants/settings";
import type { AutomationSettings } from "@bao/shared/types/settings-contracts";
import { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";
import { normalizeJobProviderSettings as normalizeSharedJobProviderSettings } from "@bao/shared/types/settings-normalization";
import {
  asBoolean,
  asJsonArray,
  asNumber,
  asString,
  isRecord,
} from "@bao/shared/utils/type-guards";
import {
  COMPANY_BOARD_ATS_TYPES,
  COMPANY_BOARD_TEMPLATE_KEYS,
  GAMING_PORTAL_IDS,
  SPEECH_AUDIO_FORMATS,
} from "~/composables/api-normalizer-settings-constants";
import { asEnum } from "~/composables/api-normalizer-shared";

const normalizeGreenhouseBoards = <T>(
  value: T,
): AutomationSettings["jobProviders"]["greenhouseBoards"] => {
  const boards = asJsonArray(value);
  if (!boards) {
    return DEFAULT_AUTOMATION_SETTINGS.jobProviders.greenhouseBoards;
  }
  const normalized: AutomationSettings["jobProviders"]["greenhouseBoards"] = [];
  for (const board of boards) {
    if (!isRecord(board)) {
      continue;
    }
    normalized.push({
      board: asString(board.board) ?? "",
      company: asString(board.company) ?? "",
      enabled: asBoolean(board.enabled) ?? false,
    });
  }
  return normalized;
};

const normalizeLeverCompanies = <T>(
  value: T,
): AutomationSettings["jobProviders"]["leverCompanies"] => {
  const companies = asJsonArray(value);
  if (!companies) {
    return DEFAULT_AUTOMATION_SETTINGS.jobProviders.leverCompanies;
  }
  const normalized: AutomationSettings["jobProviders"]["leverCompanies"] = [];
  for (const company of companies) {
    if (!isRecord(company)) {
      continue;
    }
    normalized.push({
      slug: asString(company.slug) ?? "",
      company: asString(company.company) ?? "",
      enabled: asBoolean(company.enabled) ?? false,
    });
  }
  return normalized;
};

const normalizeCompanyBoardTemplates = (
  value: unknown,
): AutomationSettings["jobProviders"]["companyBoardApiTemplates"] => {
  if (!isRecord(value)) return DEFAULT_AUTOMATION_SETTINGS.jobProviders.companyBoardApiTemplates;
  const templates = { ...DEFAULT_AUTOMATION_SETTINGS.jobProviders.companyBoardApiTemplates };
  for (const key of COMPANY_BOARD_TEMPLATE_KEYS) {
    const nextTemplate = asString(value[key]);
    if (nextTemplate) templates[key] = nextTemplate;
  }
  return templates;
};

const normalizeCompanyBoards = <T>(
  value: T,
): AutomationSettings["jobProviders"]["companyBoards"] => {
  const boards = asJsonArray(value);
  if (!boards) {
    return DEFAULT_AUTOMATION_SETTINGS.jobProviders.companyBoards;
  }
  const normalized: AutomationSettings["jobProviders"]["companyBoards"] = [];
  for (const board of boards) {
    if (!isRecord(board)) {
      continue;
    }
    normalized.push({
      name: asString(board.name) ?? "",
      token: asString(board.token) ?? "",
      type: asEnum(board.type, COMPANY_BOARD_ATS_TYPES) ?? "greenhouse",
      enabled: asBoolean(board.enabled) ?? false,
      priority: asNumber(board.priority) ?? 0,
    });
  }
  return normalized;
};

const normalizeGamingPortals = <T>(
  value: T,
): AutomationSettings["jobProviders"]["gamingPortals"] => {
  const portals = asJsonArray(value);
  if (!portals) {
    return DEFAULT_AUTOMATION_SETTINGS.jobProviders.gamingPortals;
  }

  const configuredPortals = portals.filter(isRecord);
  return DEFAULT_AUTOMATION_SETTINGS.jobProviders.gamingPortals.map((defaultPortal, index) => {
    const matchedPortal =
      configuredPortals.find(
        (portal) => asEnum(portal.id, GAMING_PORTAL_IDS) === defaultPortal.id,
      ) ?? configuredPortals[index];

    return {
      id: defaultPortal.id,
      name: asString(matchedPortal?.name) ?? defaultPortal.name,
      source: asString(matchedPortal?.source) ?? defaultPortal.source,
      fallbackUrl: asString(matchedPortal?.fallbackUrl) ?? defaultPortal.fallbackUrl,
      enabled: asBoolean(matchedPortal?.enabled) ?? defaultPortal.enabled,
    };
  });
};

const normalizeJobProviderSettings = (value: unknown): AutomationSettings["jobProviders"] => {
  if (!isRecord(value)) {
    return DEFAULT_AUTOMATION_SETTINGS.jobProviders;
  }

  return normalizeSharedJobProviderSettings({
    ...DEFAULT_AUTOMATION_SETTINGS.jobProviders,
    providerTimeoutMs:
      asNumber(value.providerTimeoutMs) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.providerTimeoutMs,
    companyBoardResultLimit:
      asNumber(value.companyBoardResultLimit) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.companyBoardResultLimit,
    gamingBoardResultLimit:
      asNumber(value.gamingBoardResultLimit) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.gamingBoardResultLimit,
    unknownLocationLabel:
      asString(value.unknownLocationLabel) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.unknownLocationLabel,
    unknownCompanyLabel:
      asString(value.unknownCompanyLabel) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.unknownCompanyLabel,
    hitmarkerEnabled:
      asBoolean(value.hitmarkerEnabled) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.hitmarkerEnabled,
    hitmarkerApiBaseUrl:
      asString(value.hitmarkerApiBaseUrl) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.hitmarkerApiBaseUrl,
    hitmarkerDefaultQuery:
      asString(value.hitmarkerDefaultQuery) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.hitmarkerDefaultQuery,
    hitmarkerDefaultLocation:
      asString(value.hitmarkerDefaultLocation) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.hitmarkerDefaultLocation,
    greenhouseApiBaseUrl:
      asString(value.greenhouseApiBaseUrl) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.greenhouseApiBaseUrl,
    greenhouseMaxPages:
      asNumber(value.greenhouseMaxPages) ??
      DEFAULT_AUTOMATION_SETTINGS.jobProviders.greenhouseMaxPages,
    greenhouseBoards: normalizeGreenhouseBoards(value.greenhouseBoards),
    leverApiBaseUrl:
      asString(value.leverApiBaseUrl) ?? DEFAULT_AUTOMATION_SETTINGS.jobProviders.leverApiBaseUrl,
    leverMaxPages:
      asNumber(value.leverMaxPages) ?? DEFAULT_AUTOMATION_SETTINGS.jobProviders.leverMaxPages,
    leverCompanies: normalizeLeverCompanies(value.leverCompanies),
    companyBoardApiTemplates: normalizeCompanyBoardTemplates(value.companyBoardApiTemplates),
    companyBoards: normalizeCompanyBoards(value.companyBoards),
    gamingPortals: normalizeGamingPortals(value.gamingPortals),
  });
};

const normalizeSpeechSettings = (value: unknown): AutomationSettings["speech"] => {
  if (!isRecord(value)) {
    return {
      locale: DEFAULT_SPEECH_SETTINGS.locale,
      stt: {
        provider: DEFAULT_SPEECH_SETTINGS.stt.provider,
        model: DEFAULT_SPEECH_SETTINGS.stt.model,
        endpoint: DEFAULT_SPEECH_SETTINGS.stt.endpoint,
      },
      tts: {
        provider: DEFAULT_SPEECH_SETTINGS.tts.provider,
        model: DEFAULT_SPEECH_SETTINGS.tts.model,
        endpoint: DEFAULT_SPEECH_SETTINGS.tts.endpoint,
        voice: DEFAULT_SPEECH_SETTINGS.tts.voice,
        format: DEFAULT_SPEECH_SETTINGS.tts.format,
      },
    };
  }

  const stt = isRecord(value.stt) ? value.stt : {};
  const tts = isRecord(value.tts) ? value.tts : {};
  const sttProvider =
    asEnum(stt.provider, SPEECH_PROVIDER_OPTIONS) ?? DEFAULT_SPEECH_SETTINGS.stt.provider;
  const ttsProvider =
    asEnum(tts.provider, SPEECH_PROVIDER_OPTIONS) ?? DEFAULT_SPEECH_SETTINGS.tts.provider;

  return {
    locale: asString(value.locale) ?? DEFAULT_SPEECH_SETTINGS.locale,
    stt: {
      provider: sttProvider,
      model: asString(stt.model) ?? DEFAULT_SPEECH_SETTINGS.stt.model,
      endpoint: asString(stt.endpoint) ?? DEFAULT_SPEECH_SETTINGS.stt.endpoint,
    },
    tts: {
      provider: ttsProvider,
      model: asString(tts.model) ?? DEFAULT_SPEECH_SETTINGS.tts.model,
      endpoint: asString(tts.endpoint) ?? DEFAULT_SPEECH_SETTINGS.tts.endpoint,
      voice: asString(tts.voice) ?? DEFAULT_SPEECH_SETTINGS.tts.voice,
      format: asEnum(tts.format, SPEECH_AUDIO_FORMATS) ?? DEFAULT_SPEECH_SETTINGS.tts.format,
    },
  };
};

export const normalizeAutomationSettings = (value: unknown): AutomationSettings | undefined => {
  if (!isRecord(value)) return;

  return {
    headless: asBoolean(value.headless) ?? DEFAULT_AUTOMATION_SETTINGS.headless,
    defaultTimeout: asNumber(value.defaultTimeout) ?? DEFAULT_AUTOMATION_SETTINGS.defaultTimeout,
    screenshotRetention:
      asNumber(value.screenshotRetention) ?? DEFAULT_AUTOMATION_SETTINGS.screenshotRetention,
    maxConcurrentRuns:
      asNumber(value.maxConcurrentRuns) ?? DEFAULT_AUTOMATION_SETTINGS.maxConcurrentRuns,
    defaultBrowser:
      value.defaultBrowser === "chromium" || value.defaultBrowser === "edge"
        ? value.defaultBrowser
        : DEFAULT_AUTOMATION_SETTINGS.defaultBrowser,
    enableSmartSelectors:
      asBoolean(value.enableSmartSelectors) ?? DEFAULT_AUTOMATION_SETTINGS.enableSmartSelectors,
    autoSaveScreenshots:
      asBoolean(value.autoSaveScreenshots) ?? DEFAULT_AUTOMATION_SETTINGS.autoSaveScreenshots,
    speech: normalizeSpeechSettings(value.speech),
    jobProviders: normalizeJobProviderSettings(value.jobProviders),
  };
};

