function toInterviewTargetJob(job: Job): InterviewTargetJob {
  return {
    id: job.id,
    title: job.title,
    company: job.company,
    location: job.location,
    description: job.description,
    requirements: job.requirements,
    technologies: job.technologies,
    source: job.source,
    postedDate: job.postedDate,
    url: job.url,
    enrichment: job.enrichment,
  };
}

function resolveSessionStudioId(
  selectedMode: InterviewMode,
  selectedJob: Job | null,
  studioId: string,
  resolveStudioIdForJob: (job: Job) => string,
): string {
  return selectedMode === "job" && selectedJob ? resolveStudioIdForJob(selectedJob) : studioId;
}

function createCandidateContext(
  selectedResumeId: string | undefined,
  selectedCoverLetterId: string | undefined,
  selectedPortfolioId: string | undefined,
): Record<string, string> {
  return {
    ...(selectedResumeId ? { resumeId: selectedResumeId } : {}),
    ...(selectedCoverLetterId ? { coverLetterId: selectedCoverLetterId } : {}),
    ...(selectedPortfolioId ? { portfolioId: selectedPortfolioId } : {}),
  };
}

function createSessionRequest(
  {
    selectedCoverLetterId,
    selectedJob,
    selectedMode,
    selectedPortfolioId,
    selectedResumeId,
    sessionConfig,
  }: InterviewHubSessionRequestInput,
  toTargetJob: (job: Job) => InterviewTargetJob,
): Record<string, unknown> {
  return {
    roleType: selectedJob.value?.title || sessionConfig.role,
    experienceLevel: sessionConfig.experienceLevel,
    questionCount: sessionConfig.questionCount,
    conversationStyle: sessionConfig.conversationStyle,
    includeTechnical: true,
    includeBehavioral: true,
    includeStudioSpecific: true,
    technologies: selectedJob.value?.technologies || [],
    enableVoiceMode: sessionConfig.enableVoiceMode,
    interviewMode: selectedMode.value,
    candidateContext: createCandidateContext(
      selectedResumeId.value,
      selectedCoverLetterId.value,
      selectedPortfolioId.value,
    ),
    ...(sessionConfig.enableVoiceMode ? { voiceSettings: sessionConfig.voiceSettings } : {}),
    ...(selectedJob.value ? { targetJob: toTargetJob(selectedJob.value) } : {}),
  };
}

import type { ComputedRef } from "vue";
const NUM_1000 = 1000;

interface TimedInterviewSession {
  endTime?: number | null;
  startTime: number;
  status: string;
}

type Translate = (key: string, params?: Record<string, string | number>) => string;

const SESSION_TIMER_INTERVAL_MS = 1000;
const SECONDS_PER_MINUTE = 60;
const DEFAULT_TIMER_VALUE = 0;
const TIMER_DISPLAY_DIGITS = 2;
const TIMER_DURATION_PREFIX = "PT";
const TIMER_MINUTE_SUFFIX = "M";
const TIMER_SECOND_SUFFIX = "S";

function estimateElapsedTime(
  fallbackSeconds: number,
  startTime: number | undefined,
  endTime?: number | null,
): number {
  if (!startTime) {
    return fallbackSeconds;
  }

  const start = Number.isFinite(startTime) ? startTime : fallbackSeconds;
  const end = typeof endTime === "number" && Number.isFinite(endTime) ? endTime : Date.now();
  const rawSeconds = Math.floor((end - start) / NUM_1000);
  return Math.max(0, rawSeconds);
}

export function createInterviewSessionTimer(input: {
  activeSession: ComputedRef<TimedInterviewSession | null>;
  t: Translate;
}) {
  const timeElapsed = ref(DEFAULT_TIMER_VALUE);
  const timer = ref<number | null>(null);

  const presentation = createInterviewTimerPresentation(timeElapsed, input.t);
  const controls = createInterviewTimerControls({
    activeSession: input.activeSession,
    timeElapsed,
    timer,
  });

  return {
    ...presentation,
    ...controls,
  };
}

function createInterviewTimerPresentation(timeElapsed: Ref<number>, t: Translate) {
  const elapsedMinutes = computed(() => Math.floor(timeElapsed.value / SECONDS_PER_MINUTE));
  const elapsedSeconds = computed(() => timeElapsed.value % SECONDS_PER_MINUTE);
  const formattedElapsedMinutes = computed(() =>
    String(elapsedMinutes.value).padStart(TIMER_DISPLAY_DIGITS, "0"),
  );
  const formattedElapsedSeconds = computed(() =>
    String(elapsedSeconds.value).padStart(TIMER_DISPLAY_DIGITS, "0"),
  );
  const elapsedTimeText = computed(
    () => `${formattedElapsedMinutes.value}:${formattedElapsedSeconds.value}`,
  );
  const elapsedTimeAriaLabel = computed(() =>
    t("interviewSession.timeAria", {
      minutes: elapsedMinutes.value,
      seconds: elapsedSeconds.value,
    }),
  );
  const elapsedTimeDuration = computed(
    () =>
      `${TIMER_DURATION_PREFIX}${elapsedMinutes.value}${TIMER_MINUTE_SUFFIX}${elapsedSeconds.value}${TIMER_SECOND_SUFFIX}`,
  );

  return {
    elapsedTimeAriaLabel,
    elapsedTimeDuration,
    elapsedTimeText,
  };
}

function createInterviewTimerControls(input: {
  activeSession: ComputedRef<TimedInterviewSession | null>;
  timeElapsed: Ref<number>;
  timer: Ref<number | null>;
}) {
  function stopTimer() {
    if (import.meta.client && input.timer.value) {
      window.clearInterval(input.timer.value);
      input.timer.value = null;
    }
  }

  function syncCompletedSessionTime(session: TimedInterviewSession) {
    input.timeElapsed.value = estimateElapsedTime(
      DEFAULT_TIMER_VALUE,
      session.startTime,
      session.endTime,
    );
  }

  function startTimer() {
    stopTimer();
    const session = input.activeSession.value;
    if (!session || session.status === "completed" || session.status === "cancelled") {
      return;
    }

    input.timeElapsed.value = estimateElapsedTime(DEFAULT_TIMER_VALUE, session.startTime);
    if (!import.meta.client) {
      return;
    }
    input.timer.value = window.setInterval(() => {
      const current = input.activeSession.value;
      if (!current) {
        stopTimer();
        return;
      }
      if (current.status === "completed" || current.status === "cancelled") {
        syncCompletedSessionTime(current);
        stopTimer();
        return;
      }
      input.timeElapsed.value = estimateElapsedTime(DEFAULT_TIMER_VALUE, current.startTime);
    }, SESSION_TIMER_INTERVAL_MS);
  }

  return {
    startTimer,
    stopTimer,
    syncCompletedSessionTime,
  };
}

import {
  type AutomationScrapeTarget,
  automationScrapeTargetToPortalId,
  isAutomationJobScrapeTarget,
} from "@bao/shared/constants/automation";
import type { Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import type { Router } from "vue-router";
import type { NuxtApp } from "#app";
import { settlePromise } from "~/composables/async-flow";
import { toIsoTimestamp } from "~/composables/schedule-timestamp";
import { useApi } from "~/composables/useApi";
import type { AutomationRunEnvelope, ScrapePendingAction } from "~/types/automation-scraper";
import { getErrorMessage } from "~/utils/errors";
import { buildInterviewJobNavigation } from "~/utils/interview-navigation";
import { isFailedScrapeRun, readScrapeOutputErrors } from "~/utils/scrape-run-output";

async function syncDirectScraperCatalog(target: AutomationScrapeTarget): Promise<void> {
  const api = useApi();
  if (target === "studios") {
    await api.scraper.studios.post();
    return;
  }
  if (!isAutomationJobScrapeTarget(target)) {
    return;
  }
  const portalId = automationScrapeTargetToPortalId(target);
  const portalRoute = api.scraper.jobs[portalId];
  if (portalRoute && typeof portalRoute.post === "function") {
    await portalRoute.post();
  }
}

type AutomationScraperActionsInput = {
  awardForAction: (action: "scraperStudios" | "scraperJobs") => Promise<{
    awarded: boolean;
    amount: number;
  }>;
  lastRunAt: Record<AutomationScrapeTarget, string | null>;
  latestRuns: Record<AutomationScrapeTarget, AutomationRunEnvelope | null>;
  pendingAction: Ref<ScrapePendingAction | null>;
  refreshCapabilityAudit: () => Promise<unknown>;
  refreshScraperJobs: () => Promise<unknown>;
  runMessages: Record<AutomationScrapeTarget, string>;
  runStates: Record<AutomationScrapeTarget, "idle" | "running" | "success" | "error">;
  scheduleScrape: (input: {
    target: AutomationScrapeTarget;
    runAt: string;
  }) => Promise<AutomationRunEnvelope>;
  scheduledRunAt: Record<AutomationScrapeTarget, string>;
  triggerScrape: (input: { target: AutomationScrapeTarget }) => Promise<AutomationRunEnvelope>;
};

type AutomationScraperRunStateStore = Pick<
  AutomationScraperActionsInput,
  "latestRuns" | "pendingAction" | "runMessages" | "runStates"
>;

type AutomationScraperSuccessStore = Pick<
  AutomationScraperActionsInput,
  "lastRunAt" | "latestRuns" | "runMessages" | "runStates"
>;

type AutomationScraperRefreshInput = Pick<
  AutomationScraperActionsInput,
  "refreshCapabilityAudit" | "refreshScraperJobs"
> & {
  target: AutomationScrapeTarget;
};

function createScheduleScrapeRun(input: AutomationScraperActionsInput, t: ComposerTranslation) {
  return async (target: AutomationScrapeTarget): Promise<void> => {
    const runAt = toIsoTimestamp(input.scheduledRunAt[target]);
    if (!runAt) {
      input.runStates[target] = "error";
      input.runMessages[target] = t("automation.scraper.schedule.invalidRunAt");
      return;
    }

    input.pendingAction.value = `${target}-schedule`;
    input.latestRuns[target] = null;
    const scheduleResult = await settlePromise(
      input.scheduleScrape({ target, runAt }),
      t("automation.scraper.errors.scheduleFailed"),
    );
    input.pendingAction.value = null;

    if (!scheduleResult.ok) {
      input.runStates[target] = "error";
      input.runMessages[target] = getErrorMessage(
        scheduleResult.error,
        t("automation.scraper.errors.scheduleFailed"),
      );
      return;
    }

    input.runStates[target] = "success";
    input.runMessages[target] = t("automation.scraper.schedule.createdMessage");
    input.latestRuns[target] = scheduleResult.value;
  };
}

function createRunScrapeTarget(
  input: AutomationScraperActionsInput,
  rewardResolver: ReturnType<typeof createPipelineRewardResolver>,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const { $toast } = nuxtApp;
  const runStateStore = {
    lastRunAt: input.lastRunAt,
    latestRuns: input.latestRuns,
    pendingAction: input.pendingAction,
    runMessages: input.runMessages,
    runStates: input.runStates,
  };

  return async (target: AutomationScrapeTarget): Promise<void> => {
    const failureKey = resolveRunFailureKey(target);
    prepareManualRun(target, runStateStore);
    const runResult = await settlePromise(input.triggerScrape({ target }), t(failureKey));
    input.pendingAction.value = null;

    if (!runResult.ok) {
      applyRunFailure({ error: runResult.error, failureKey, target }, runStateStore, t);
      return;
    }

    const completedRun = runResult.value;
    // Dual fabric: RPA run + Eden scraper portal sync for catalog freshness.
    await settlePromise(syncDirectScraperCatalog(target), t(failureKey));
    await refreshManualRunArtifacts({
      refreshCapabilityAudit: input.refreshCapabilityAudit,
      refreshScraperJobs: input.refreshScraperJobs,
      target,
    });
    const scrapeFailed = isFailedScrapeRun({
      aborted: completedRun.aborted,
      exitCode: completedRun.exitCode,
      output: completedRun.output,
      timedOut: completedRun.timedOut,
    });
    const reward = scrapeFailed ? null : await rewardResolver(resolveRewardAction(target));
    applyRunSuccess({ completedRun, reward, target }, runStateStore, t);
    if (reward) {
      $toast.success(t(resolveRewardToastKey(target), { xp: reward }));
    }
  };
}

export function useAutomationScraperActions(
  input: AutomationScraperActionsInput,
  router: Router,
  nuxtApp: Pick<NuxtApp, "$toast">,
  t: ComposerTranslation,
) {
  const rewardResolver = createPipelineRewardResolver(input.awardForAction, t);
  const scheduleScrapeRun = createScheduleScrapeRun(input, t);
  const runScrapeTarget = createRunScrapeTarget(input, rewardResolver, nuxtApp, t);

  function isPendingAction(target: AutomationScrapeTarget, action: "run" | "schedule"): boolean {
    return input.pendingAction.value === `${target}-${action}`;
  }

  async function startJobInterview(jobId: string): Promise<void> {
    await router.push(buildInterviewJobNavigation(jobId, "scraper"));
  }

  return {
    isPendingAction,
    runScrapeTarget,
    scheduleScrapeRun,
    startJobInterview,
  };
}

function resolveRunFailureKey(target: AutomationScrapeTarget): string {
  return target === "studios"
    ? "automation.scraper.errors.studioFailed"
    : "automation.scraper.errors.jobFailed";
}

function resolveRewardAction(target: AutomationScrapeTarget): "scraperStudios" | "scraperJobs" {
  return target === "studios" ? "scraperStudios" : "scraperJobs";
}

function resolveRewardToastKey(target: AutomationScrapeTarget): string {
  return target === "studios"
    ? "automation.scraper.toasts.studioReward"
    : "automation.scraper.toasts.jobReward";
}

function resolveCompletionMessageKey(target: AutomationScrapeTarget, hasReward: boolean): string {
  if (target === "studios") {
    return hasReward
      ? "automation.scraper.messages.studioCompletedWithXp"
      : "automation.scraper.messages.studioCompleted";
  }
  return hasReward
    ? "automation.scraper.messages.jobCompletedWithXp"
    : "automation.scraper.messages.jobCompleted";
}

function prepareManualRun(
  target: AutomationScrapeTarget,
  { latestRuns, pendingAction, runMessages, runStates }: AutomationScraperRunStateStore,
): void {
  runStates[target] = "running";
  runMessages[target] = "";
  latestRuns[target] = null;
  pendingAction.value = `${target}-run`;
}

function applyRunFailure(
  {
    error,
    failureKey,
    target,
  }: { error: unknown; failureKey: string; target: AutomationScrapeTarget },
  { runMessages, runStates }: Pick<AutomationScraperActionsInput, "runMessages" | "runStates">,
  t: ComposerTranslation,
): void {
  runStates[target] = "error";
  runMessages[target] = getErrorMessage(error, t(failureKey));
}

async function refreshManualRunArtifacts({
  refreshCapabilityAudit,
  refreshScraperJobs,
  target,
}: AutomationScraperRefreshInput): Promise<void> {
  if (target !== "studios") {
    await refreshScraperJobs();
  }
  await refreshCapabilityAudit();
}

function applyRunSuccess(
  {
    completedRun,
    reward,
    target,
  }: { completedRun: AutomationRunEnvelope; reward: number | null; target: AutomationScrapeTarget },
  { lastRunAt, latestRuns, runMessages, runStates }: AutomationScraperSuccessStore,
  t: ComposerTranslation,
): void {
  lastRunAt[target] = completedRun.completedAt ?? completedRun.updatedAt;
  latestRuns[target] = completedRun;

  const failed = isFailedScrapeRun({
    aborted: completedRun.aborted,
    exitCode: completedRun.exitCode,
    output: completedRun.output,
    timedOut: completedRun.timedOut,
  });
  if (failed) {
    runStates[target] = "error";
    const outputErrors = readScrapeOutputErrors(completedRun.output);
    const envelopeError = typeof completedRun.error === "string" ? completedRun.error : null;
    runMessages[target] = outputErrors[0] ?? envelopeError ?? t(resolveRunFailureKey(target));
    return;
  }

  runStates[target] = "success";
  const messageKey = resolveCompletionMessageKey(target, reward !== null);
  runMessages[target] = reward === null ? t(messageKey) : t(messageKey, { xp: reward });
}

function createPipelineRewardResolver(
  awardForAction: (action: "scraperStudios" | "scraperJobs") => Promise<{
    awarded: boolean;
    amount: number;
  }>,
  t: ComposerTranslation,
) {
  return async (action: "scraperStudios" | "scraperJobs"): Promise<number | null> => {
    const rewardResult = await settlePromise(
      awardForAction(action),
      t("automation.scraper.errors.rewardFailed"),
    );
    if (!rewardResult.ok) {
      return null;
    }
    return rewardResult.value.awarded ? rewardResult.value.amount : null;
  };
}

import type { DashboardStats } from "@bao/shared/types/search";
import type { Ref } from "vue";
import { computed } from "vue";
import {
  type AutomationHubCard,
  type AutomationHubCardId,
  type AutomationHubTranslate,
  BASE_AUTOMATION_CARDS,
  resolveOrderedCardIds,
} from "~/composables/automation-hub-page-contracts";
import { useFlowEngine } from "~/composables/useFlowEngine";
import type { DashboardPipelineStepViewModel } from "~/constants/dashboard-contracts";
import { resolveDashboardPipelineSteps } from "~/constants/dashboard-pipeline";
import { createFlowEngineInput } from "~/constants/flow-engine";
import type { FlowActionId } from "~/constants/flow-engine-types";
import {
  BADGE_SOFT_ERROR_CLASS,
  BADGE_SOFT_SUCCESS_CLASS,
  BADGE_SOFT_WARNING_CLASS,
} from "~/constants/layout-badges";

const createAutomationPipelineSteps = (stats: Readonly<Ref<DashboardStats | null>>) =>
  computed<readonly DashboardPipelineStepViewModel[]>(() => {
    const resolvedStats = stats.value;
    if (!resolvedStats) {
      return resolveDashboardPipelineSteps({
        savedJobs: 0,
        appliedJobs: 0,
        resumeCount: 0,
        coverLetterCount: 0,
        automationRuns: 0,
        successfulAutomationRuns: 0,
        mappedSkillsCount: 0,
        gamificationXp: 0,
      });
    }

    return resolveDashboardPipelineSteps({
      savedJobs: resolvedStats.jobs.saved,
      appliedJobs: resolvedStats.jobs.applied,
      resumeCount: resolvedStats.resumes.count,
      coverLetterCount: resolvedStats.coverLetters.count,
      automationRuns: resolvedStats.automation.totalRuns,
      successfulAutomationRuns: resolvedStats.automation.successfulRuns,
      mappedSkillsCount: resolvedStats.skills.mappedCount,
      gamificationXp: resolvedStats.gamification.xp,
    });
  });

const createAutomationCardPresentation = (
  primaryAction: Readonly<Ref<{ id: string }>>,
  recommendedActions: Readonly<Ref<readonly { id: string }[]>>,
) => {
  const prioritizedCardIds = computed<readonly AutomationHubCardId[]>(() => {
    const actionPriority = [primaryAction.value, ...recommendedActions.value]
      .map((action) => action.id)
      .filter(
        (actionId): actionId is FlowActionId =>
          actionId === "automationScraper" ||
          actionId === "automationApply" ||
          actionId === "automationRuns",
      );

    return resolveOrderedCardIds(actionPriority);
  });

  const orderedCards = computed<readonly AutomationHubCard[]>(() => {
    const remainingCards = [...BASE_AUTOMATION_CARDS];
    const prioritizedCards: AutomationHubCard[] = [];

    for (const cardId of prioritizedCardIds.value) {
      const index = remainingCards.findIndex((card) => card.id === cardId);
      if (index === -1) {
        continue;
      }
      const [card] = remainingCards.splice(index, 1);
      if (card) {
        prioritizedCards.push(card);
      }
    }

    return [...prioritizedCards, ...remainingCards];
  });

  const primaryCardId = computed<AutomationHubCardId | null>(() => {
    const currentPrimaryAction = primaryAction.value.id;
    if (currentPrimaryAction === "automationScraper") return "scraper";
    if (currentPrimaryAction === "automationApply") return "jobApply";
    if (currentPrimaryAction === "automationRuns") return "runHistory";
    return null;
  });

  const primaryCard = computed<AutomationHubCard | null>(() => {
    const currentPrimaryCardId = primaryCardId.value;
    if (!currentPrimaryCardId) {
      return orderedCards.value[0] ?? null;
    }

    const cards = orderedCards.value;
    for (const automationCard of cards) {
      if (automationCard.id === currentPrimaryCardId) {
        return automationCard;
      }
    }

    return null;
  });

  return {
    orderedCards,
    primaryCardId,
    primaryCard,
  };
};

const createAutomationCapabilityStatusPresentation = (t: AutomationHubTranslate) => ({
  capabilityStatusClass(value: boolean, issueCount = 0): string {
    if (value) {
      return BADGE_SOFT_SUCCESS_CLASS;
    }
    if (issueCount > 0) {
      return BADGE_SOFT_WARNING_CLASS;
    }
    return BADGE_SOFT_ERROR_CLASS;
  },
  capabilityStatusLabel(value: boolean, issueCount = 0): string {
    if (value) {
      return t("automation.hub.audit.available");
    }
    if (issueCount > 0) {
      return t("automation.hub.audit.needsConfig");
    }
    return t("automation.hub.audit.unavailable");
  },
});

export const createAutomationHubPagePresentation = (options: {
  readonly stats: Readonly<Ref<DashboardStats | null>>;
  readonly t: AutomationHubTranslate;
}) => {
  const pipelineSteps = createAutomationPipelineSteps(options.stats);
  const flowInput = computed(() => createFlowEngineInput(options.stats.value));
  const { primaryAction, recommendedActions, nextStepLabel } = useFlowEngine(flowInput);
  const nextPipelineStepLabel = computed(() => options.t(nextStepLabel.value));

  return {
    pipelineSteps,
    nextPipelineStepLabel,
    ...createAutomationCardPresentation(primaryAction, recommendedActions),
    ...createAutomationCapabilityStatusPresentation(options.t),
  };
};

