 * Options for speech model profile state management.
 */
export interface UseSpeechModelProfilesOptions {
  readonly locale: Ref<string>;
}

interface SaveSpeechConfigActionOptions {
  settings: ReturnType<typeof useSettings>["settings"];
  updateSettings: ReturnType<typeof useSettings>["updateSettings"];
  isSpeechConfigDirty: ComputedRef<boolean>;
  speechConfigSaving: Ref<boolean>;
  speechConfig: SpeechModelProfileState;
  locale: Ref<string>;
}

const resolveProviderModels = (
  kind: SpeechModelProfileKind,
  provider: SpeechProviderOption,
): readonly string[] => SPEECH_MODEL_OPTIONS[kind][provider];

const resolveDefaultModel = (
  kind: SpeechModelProfileKind,
  provider: SpeechProviderOption,
): string => {
  const configuredModels = resolveProviderModels(kind, provider);
  if (configuredModels.length === 0) {
    return kind === "stt" ? DEFAULT_SPEECH_SETTINGS.stt.model : DEFAULT_SPEECH_SETTINGS.tts.model;
  }
  return configuredModels[0] ?? "";
};

const createSpeechConfigState = (): SpeechModelProfileState => {
  const sttProvider = DEFAULT_SPEECH_SETTINGS.stt.provider;
  const ttsProvider = DEFAULT_SPEECH_SETTINGS.tts.provider;
  return reactive<SpeechModelProfileState>({
    sttProvider,
    sttModel: resolveDefaultModel("stt", sttProvider),
    ttsProvider,
    ttsModel: resolveDefaultModel("tts", ttsProvider),
  });
};

const createPersistedSpeechConfig = (
  settings: ReturnType<typeof useSettings>["settings"],
): ComputedRef<SpeechModelProfileState> =>
  computed<SpeechModelProfileState>(() => {
    const persistedSpeech =
      settings.value?.automationSettings?.speech ?? DEFAULT_AUTOMATION_SETTINGS.speech;
    return {
      sttProvider: persistedSpeech.stt.provider,
      sttModel: persistedSpeech.stt.model,
      ttsProvider: persistedSpeech.tts.provider,
      ttsModel: persistedSpeech.tts.model,
    };
  });

const createSpeechConfigDirtyState = (
  speechConfig: SpeechModelProfileState,
  persistedSpeechConfig: ComputedRef<SpeechModelProfileState>,
): ComputedRef<boolean> =>
  computed(
    () =>
      speechConfig.sttProvider !== persistedSpeechConfig.value.sttProvider ||
      speechConfig.sttModel.trim() !== persistedSpeechConfig.value.sttModel ||
      speechConfig.ttsProvider !== persistedSpeechConfig.value.ttsProvider ||
      speechConfig.ttsModel.trim() !== persistedSpeechConfig.value.ttsModel,
  );

const syncSpeechConfigFromSettings = (
  settings: ReturnType<typeof useSettings>["settings"],
  speechConfig: SpeechModelProfileState,
) => {
  watch(
    settings,
    (currentSettings) => {
      const persistedSpeech =
        currentSettings?.automationSettings?.speech ?? DEFAULT_AUTOMATION_SETTINGS.speech;
      speechConfig.sttProvider = persistedSpeech.stt.provider;
      speechConfig.sttModel = persistedSpeech.stt.model;
      speechConfig.ttsProvider = persistedSpeech.tts.provider;
      speechConfig.ttsModel = persistedSpeech.tts.model;
    },
    { immediate: true },
  );
};

const registerSttProviderWatcher = (speechConfig: SpeechModelProfileState) => {
  watch(
    () => speechConfig.sttProvider,
    (provider) => {
      const optionsForProvider = resolveProviderModels("stt", provider);
      if (optionsForProvider.includes(speechConfig.sttModel)) {
        return;
      }
      speechConfig.sttModel = resolveDefaultModel("stt", provider);
    },
  );
};

const registerTtsProviderWatcher = (speechConfig: SpeechModelProfileState) => {
  watch(
    () => speechConfig.ttsProvider,
    (provider) => {
      const optionsForProvider = resolveProviderModels("tts", provider);
      if (optionsForProvider.includes(speechConfig.ttsModel)) {
        return;
      }
      speechConfig.ttsModel = resolveDefaultModel("tts", provider);
    },
  );
};

const buildNextSpeechConfig = (
  settings: ReturnType<typeof useSettings>["settings"],
  speechConfig: SpeechModelProfileState,
  locale: string,
) => {
  const existingAutomationSettings =
    settings.value?.automationSettings ?? DEFAULT_AUTOMATION_SETTINGS;
  const sttModel = speechConfig.sttModel.trim();
  const ttsModel = speechConfig.ttsModel.trim();
  return {
    ...existingAutomationSettings.speech,
    locale: existingAutomationSettings.speech.locale || locale,
    stt: {
      ...existingAutomationSettings.speech.stt,
      provider: speechConfig.sttProvider,
      model: sttModel.length > 0 ? sttModel : resolveDefaultModel("stt", speechConfig.sttProvider),
    },
    tts: {
      ...existingAutomationSettings.speech.tts,
      provider: speechConfig.ttsProvider,
      model: ttsModel.length > 0 ? ttsModel : resolveDefaultModel("tts", speechConfig.ttsProvider),
    },
  };
};

const createEnsureSpeechConfigLoadedAction =
  (
    settings: ReturnType<typeof useSettings>["settings"],
    fetchSettings: ReturnType<typeof useSettings>["fetchSettings"],
  ) =>
  async (): Promise<void> => {
    if (settings.value) {
      return;
    }
    await fetchSettings();
  };

const createSaveSpeechConfigAction =
  (options: SaveSpeechConfigActionOptions) =>
  async (fallbackMessage: string): Promise<SpeechModelProfileSaveResult> => {
    if (!options.isSpeechConfigDirty.value || options.speechConfigSaving.value) {
      return { ok: true, saved: false };
    }

    const nextSpeechConfig = buildNextSpeechConfig(
      options.settings,
      options.speechConfig,
      options.locale.value,
    );
    options.speechConfigSaving.value = true;
    const saveSpeechResult = await settlePromise(
      options.updateSettings({
        automationSettings: {
          speech: nextSpeechConfig,
        },
      }),
      fallbackMessage,
    );
    options.speechConfigSaving.value = false;

    if (!saveSpeechResult.ok) {
      return {
        ok: false,
        saved: false,
        error: saveSpeechResult.error,
      };
    }
    return {
      ok: true,
      saved: true,
    };
  };

/**
 * Provides a single source of truth for persisted speech provider/model profile state.
 *
 * @param options Locale ref used as fallback speech locale when persisting settings.
 * @returns Reactive speech config, model options, dirty/saving flags, and save/load actions.
 */
export function useSpeechModelProfiles(options: UseSpeechModelProfilesOptions) {
  const { settings, fetchSettings, updateSettings } = useSettings();
  const speechConfigSaving = ref(false);
  const speechConfig = createSpeechConfigState();
  const sttModelOptions = computed(() => resolveProviderModels("stt", speechConfig.sttProvider));
  const ttsModelOptions = computed(() => resolveProviderModels("tts", speechConfig.ttsProvider));
  const persistedSpeechConfig = createPersistedSpeechConfig(settings);
  const isSpeechConfigDirty = createSpeechConfigDirtyState(speechConfig, persistedSpeechConfig);

  syncSpeechConfigFromSettings(settings, speechConfig);
  registerSttProviderWatcher(speechConfig);
  registerTtsProviderWatcher(speechConfig);

  return {
    speechProviderOptions: SPEECH_PROVIDER_OPTIONS,
    speechConfig,
    sttModelOptions,
    ttsModelOptions,
    speechConfigSaving,
    isSpeechConfigDirty,
    ensureSpeechConfigLoaded: createEnsureSpeechConfigLoadedAction(settings, fetchSettings),
    saveSpeechConfig: createSaveSpeechConfigAction({
      settings,
      updateSettings,
      isSpeechConfigDirty,
      speechConfigSaving,
      speechConfig,
      locale: options.locale,
    }),
  };
}

import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { isValidEmail } from "@bao/shared/utils/validation";
import { isRecord } from "@bao/shared/utils/type-guards";
import type { Ref } from "vue";
import type { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import { DATE_FORMAT_OPTIONS, toIsoTimestamp } from "~/composables/schedule-timestamp";
import { getErrorMessage } from "~/utils/errors";
import { formatDateWithLocale } from "~/utils/locale-format";

type ApiPayload = Parameters<typeof isRecord>[0];

export type EmailResponseTone = "professional" | "friendly" | "concise";

export interface EmailFormState {
  subject: string;
  message: string;
  sender: string;
  tone: EmailResponseTone;
  recipientEmail: string;
  deliverAfterGeneration: boolean;
  runAt: string;
}

export interface EmailActionResult {
  runId: string;
  reply: string;
  provider: string;
  model: string;
  delivered: boolean;
  recipientEmail?: string;
  deliveredAt?: string;
  messageId?: string;
}
export const EMAIL_TONE_OPTIONS: readonly EmailResponseTone[] = [
  "professional",
  "friendly",
  "concise",
] as const;

export { isRecord };

export const createEmailAutomationForm = () =>
  reactive<EmailFormState>({
    subject: "",
    message: "",
    sender: "",
    tone: "professional",
    recipientEmail: "",
    deliverAfterGeneration: false,
    runAt: "",
  });

export const createEmailAutomationResultState = () => ({
  pendingAction: ref<"generate" | "schedule" | null>(null),
  submitError: ref(""),
  lastResult: ref<EmailActionResult | null>(null),
  scheduledRun: ref<RpaRunExecutionEnvelope | null>(null),
});

export type EmailAutomationResultState = ReturnType<typeof createEmailAutomationResultState>;

export const createResolvedRecipientEmailComputed = (form: EmailFormState) =>
  computed(() => {
    const explicitRecipient = form.recipientEmail.trim();
    if (explicitRecipient.length > 0) {
      return explicitRecipient;
    }

    const sender = form.sender.trim();
    return isValidEmail(sender) ? sender : "";
  });
export const createToLocalizedDateTime =
  (localeValue: () => ApiPayload, fallbackLocaleValue: () => ApiPayload) =>
  (value: string): string =>
    formatDateWithLocale(value, localeValue(), fallbackLocaleValue(), DATE_FORMAT_OPTIONS) ?? value;

export const resetEmailAutomationResults = (
  submitError: Ref<string>,
  lastResult: Ref<EmailActionResult | null>,
  scheduledRun: Ref<RpaRunExecutionEnvelope | null>,
): void => {
  submitError.value = "";
  lastResult.value = null;
  scheduledRun.value = null;
};

export const createBaseEmailPayload = (
  form: EmailFormState,
  resolvedRecipientEmail: Readonly<Ref<string>>,
) => ({
  subject: form.subject.trim(),
  message: form.message.trim(),
  tone: form.tone,
  ...(form.sender.trim() ? { sender: form.sender.trim() } : {}),
  ...(resolvedRecipientEmail.value ? { recipientEmail: resolvedRecipientEmail.value } : {}),
  deliverAfterGeneration: form.deliverAfterGeneration,
});

export const createValidateDeliverySettings = (options: {
  t: ReturnType<typeof useI18n>["t"];
  form: EmailFormState;
  submitError: Ref<string>;
  emailDeliveryConfigured: Readonly<Ref<boolean>>;
  resolvedRecipientEmail: Readonly<Ref<string>>;
}) => {
  return (): boolean => {
    if (!options.form.deliverAfterGeneration) return true;
    if (!options.emailDeliveryConfigured.value) {
      options.submitError.value = options.t("automation.email.deliveryUnavailableDescription");
      return false;
    }
    if (!isValidEmail(options.resolvedRecipientEmail.value)) {
      options.submitError.value = options.t("automation.email.invalidRecipient");
      return false;
    }
    return true;
  };
};

export const createSubmitEmailResponse = (options: {
  t: ReturnType<typeof useI18n>["t"];
  form: EmailFormState;
  resultState: EmailAutomationResultState;
  resolvedRecipientEmail: Readonly<Ref<string>>;
  validateDeliverySettings: () => boolean;
  triggerEmailResponse: ReturnType<typeof useAutomation>["triggerEmailResponse"];
}) => {
  return async (): Promise<void> => {
    resetEmailAutomationResults(
      options.resultState.submitError,
      options.resultState.lastResult,
      options.resultState.scheduledRun,
    );

    if (!options.validateDeliverySettings()) {
      return;
    }

    options.resultState.pendingAction.value = "generate";
    const responseResult = await settlePromise(
      options.triggerEmailResponse(
        createBaseEmailPayload(options.form, options.resolvedRecipientEmail),
      ),
      options.t("automation.email.submitErrorFallback"),
    );
    options.resultState.pendingAction.value = null;

    if (!responseResult.ok) {
      options.resultState.submitError.value = getErrorMessage(
        responseResult.error,
        options.t("automation.email.submitErrorFallback"),
      );
      return;
    }

    const response = responseResult.value;
    options.resultState.lastResult.value = {
      runId: response.runId,
      reply: response.reply,
      provider: response.provider,
      model: response.model,
      delivered: response.delivered,
      recipientEmail: response.recipientEmail,
      deliveredAt: response.deliveredAt,
      messageId: response.messageId,
    };
  };
};

export const createSubmitScheduledEmailResponse = (options: {
  t: ReturnType<typeof useI18n>["t"];
  form: EmailFormState;
  resultState: EmailAutomationResultState;
  resolvedRecipientEmail: Readonly<Ref<string>>;
  validateDeliverySettings: () => boolean;
  scheduleEmailResponse: ReturnType<typeof useAutomation>["scheduleEmailResponse"];
}) => {
  return async (): Promise<void> => {
    resetEmailAutomationResults(
      options.resultState.submitError,
      options.resultState.lastResult,
      options.resultState.scheduledRun,
    );

    if (!options.validateDeliverySettings()) {
      return;
    }

    const runAt = toIsoTimestamp(options.form.runAt);
    if (!runAt) {
      options.resultState.submitError.value = options.t("automation.email.schedule.invalidRunAt");
      return;
    }

    options.resultState.pendingAction.value = "schedule";
    const scheduleResult = await settlePromise(
      options.scheduleEmailResponse({
        ...createBaseEmailPayload(options.form, options.resolvedRecipientEmail),
        runAt,
      }),
      options.t("automation.email.submitErrorFallback"),
    );
    options.resultState.pendingAction.value = null;

    if (!scheduleResult.ok) {
      options.resultState.submitError.value = getErrorMessage(
        scheduleResult.error,
        options.t("automation.email.submitErrorFallback"),
      );
      return;
    }

    options.resultState.scheduledRun.value = scheduleResult.value;
  };
};

import {
  createFloatingChatWidgetMessageActions,
  createFloatingChatWidgetPanelActions,
  createFloatingChatWidgetSpeechActions,
} from "./floating-chat-widget-actions";
import { createFloatingChatWidgetCoreState } from "./floating-chat-widget-core";
import {
  createFloatingChatWidgetDerivedState,
  createWidgetScrollHandlers,
  useFloatingChatWidgetLifecycle,
  useFloatingChatWidgetWatchers,
} from "./floating-chat-widget-derived";
import { createFloatingChatWidgetExposedState } from "./floating-chat-widget-exposed";

const createFloatingChatWidgetBehaviorState = (
  coreState: ReturnType<typeof createFloatingChatWidgetCoreState>,
) => {
  const derivedState = createFloatingChatWidgetDerivedState({
    messages: coreState.ai.messages,
    streaming: coreState.ai.streaming,
    streamingContent: coreState.ai.streamingContent,
    route: coreState.route,
    buildCurrentContext: coreState.ai.buildCurrentContext,
    t: coreState.t,
    voiceErrorMessageKey: coreState.voice.errorMessageKey,
  });
  const { scrollToBottom, handlePanelScroll } = createWidgetScrollHandlers(
    coreState.uiState.panelBodyRef,
    coreState.uiState.shouldStickToBottom,
  );
  const panelActions = createFloatingChatWidgetPanelActions({
    isOpen: coreState.uiState.isOpen,
    isSpeechSettingsOpen: coreState.uiState.isSpeechSettingsOpen,
    unreadCount: coreState.uiState.unreadCount,
    inputRef: coreState.uiState.inputRef,
    ensureSpeechConfigLoaded: coreState.speechProfiles.ensureSpeechConfigLoaded,
    toast: coreState.toast,
    t: coreState.t,
  });
  const messageActions = createFloatingChatWidgetMessageActions({
    draft: coreState.uiState.draft,
    loading: coreState.ai.loading,
    isVoiceListening: coreState.voice.isListening,
    stopListening: coreState.voice.stopListening,
    shouldStickToBottom: coreState.uiState.shouldStickToBottom,
    sendMessage: coreState.ai.sendMessage,
    inputRef: coreState.uiState.inputRef,
    scrollToBottom,
  });
  const speechActions = createFloatingChatWidgetSpeechActions({
    saveSpeechConfig: coreState.speechProfiles.saveSpeechConfig,
    toast: coreState.toast,
    t: coreState.t,
  });

  return {
    derivedState,
    panelActions,
    messageActions,
    speechActions,
    scrollToBottom,
    handlePanelScroll,
  };
};

const buildFloatingChatWidgetState = () => {
  const coreState = createFloatingChatWidgetCoreState();
  const behaviorState = createFloatingChatWidgetBehaviorState(coreState);

  return {
    ...coreState,
    ...behaviorState,
  };
};

export function useFloatingChatWidget() {
  const state = buildFloatingChatWidgetState();

  useFloatingChatWidgetWatchers({
    showWidget: state.derivedState.showWidget,
    messages: state.ai.messages,
    isOpen: state.uiState.isOpen,
    isSpeechSettingsOpen: state.uiState.isSpeechSettingsOpen,
    unreadCount: state.uiState.unreadCount,
    renderedMessageSignature: state.derivedState.renderedMessageSignature,
    shouldStickToBottom: state.uiState.shouldStickToBottom,
    streaming: state.ai.streaming,
    loading: state.ai.loading,
    inputRef: state.uiState.inputRef,
    scrollToBottom: state.scrollToBottom,
  });

  useFloatingChatWidgetLifecycle({
    handleFocusChatShortcut: state.panelActions.handleFocusChatShortcut,
  });

  return createFloatingChatWidgetExposedState(state);
}

import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type {
  Achievement,
  DailyChallenge,
  UserGamificationData,
} from "@bao/shared/types/gamification";
import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { asJsonArray, isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import { withLoadingState } from "./async-flow";
import { parseAchievementList, parseDailyChallengeList } from "./gamification-entity-normalizers";
import { readRequiredApiPayload } from "~/utils/api-response";
import { PERCENT_MAX } from "@bao/shared/constants/numeric";
const NUM_14 = 14;
const NUM_3 = 3;
const NUM_30 = 30;
const NUM_7 = 7;
const RATIO_1_0 = 1.0;
const RATIO_1_25 = 1.25;
const RATIO_1_5 = 1.5;
const RATIO_2_0 = 2.0;
const RATIO_3_0 = 3.0;

interface GamificationState {
  progress: ReturnType<typeof useState<UserGamificationData | null>>;
  achievements: ReturnType<typeof useState<Achievement[]>>;
  challenges: ReturnType<typeof useState<DailyChallenge[]>>;
  weeklyProgress: ReturnType<typeof useState<JsonObject | null>>;
  monthlyStats: ReturnType<typeof useState<JsonObject | null>>;
  loading: ReturnType<typeof useState<boolean>>;
}

interface GamificationContext extends GamificationState {
  api: ReturnType<typeof useApi>;
  t: ReturnType<typeof useI18n>["t"];
}

type GamificationStatKey = Exclude<keyof UserGamificationData["stats"], "actionHistory">;

const GAMIFICATION_STAT_KEYS: readonly GamificationStatKey[] = [
  "profileComplete",
  "skillsMapped",
  "portfolioItems",
  "jobApplications",
  "chatSessions",
  "resumesGenerated",
  "coverLettersGenerated",
  "savedJobs",
  "jobsSaved",
  "interviewScore",
  "dataExported",
  "earlyLogin",
  "totalTimeSpent",
  "featuresUsed",
  "dailyStreak",
  "weeklyProgress",
  "interviewsCompleted",
  "studiosExplored",
];

const toNumberWithDefault = <T>(value: T, fallback: number): number =>
  typeof value === "number" ? value : fallback;

const toOptionalNumber = <T>(value: T): number | undefined =>
  typeof value === "number" ? value : undefined;

const toOptionalString = <T>(value: T): string | undefined =>
  typeof value === "string" ? value : undefined;

const toStringArray = <T>(value: T): string[] => {
  const entries = asJsonArray(value);
  if (!entries) {
    return [];
  }
  return entries.filter((entry): entry is string => typeof entry === "string");
};

const normalizeStats = <T>(value: T): UserGamificationData["stats"] => {
  const stats: UserGamificationData["stats"] = {};
  if (!isRecord(value)) {
    return stats;
  }

  for (const key of GAMIFICATION_STAT_KEYS) {
    const statValue = value[key];
    if (typeof statValue === "number") {
      stats[key] = statValue;
    }
  }
  return stats;
};

const normalizeDailyChallenges = <T>(value: T): Record<string, string[]> => {
  if (!isRecord(value)) {
    return {};
  }

  const dailyChallenges: Record<string, string[]> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (Array.isArray(entry)) {
      dailyChallenges[key] = toStringArray(entry);
    }
  }
  return dailyChallenges;
};

const normalizeProgress = <T>(value: T): UserGamificationData | null => {
  if (!isRecord(value)) {
    return null;
  }

  return {
    xp: toNumberWithDefault(value.xp, 0),
    level: toNumberWithDefault(value.level, 1),
    achievements: toStringArray(value.achievements),
    dailyChallenges: normalizeDailyChallenges(value.dailyChallenges),
    longestStreak: toNumberWithDefault(value.longestStreak, 0),
    currentStreak: toNumberWithDefault(value.currentStreak, 0),
    lastActiveDate: toOptionalString(value.lastActiveDate),
    stats: normalizeStats(value.stats),
    xpForNextLevel: toOptionalNumber(value.xpForNextLevel),
    streak: toOptionalNumber(value.streak),
  };
};

const createGamificationState = (): GamificationState => ({
  progress: useState<UserGamificationData | null>(STATE_KEYS.GAMIFICATION_PROGRESS, () => null),
  achievements: useState<Achievement[]>(STATE_KEYS.GAMIFICATION_ACHIEVEMENTS, () => []),
  challenges: useState<DailyChallenge[]>(STATE_KEYS.GAMIFICATION_CHALLENGES, () => []),
  weeklyProgress: useState<JsonObject | null>(STATE_KEYS.GAMIFICATION_WEEKLY, () => null),
  monthlyStats: useState<JsonObject | null>(STATE_KEYS.GAMIFICATION_MONTHLY, () => null),
  loading: useState(STATE_KEYS.GAMIFICATION_LOADING, () => false),
});

const createFetchProgressAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.gamification.progress.get(),
      context.t("apiErrors.gamification.fetchProgressFailed"),
    );
    const normalized = normalizeProgress(data);
    if (normalized) {
      context.progress.value = normalized;
    }
  });

const createAwardXpAction =
  (context: GamificationContext, fetchProgress: () => Promise<void>) =>
  async (amount: number, reason: string) =>
    withLoadingState(context.loading, async () => {
      await readRequiredApiPayload(
        context.api.gamification["award-xp"].post({ amount, reason }),
        context.t("apiErrors.gamification.awardXPFailed"),
      );
      await fetchProgress();
    });

const createFetchAchievementsAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.gamification.achievements.get(),
      context.t("apiErrors.gamification.fetchAchievementsFailed"),
    );
    context.achievements.value = parseAchievementList(data);
  });

const createFetchChallengesAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.gamification.challenges.get(),
      context.t("apiErrors.gamification.fetchChallengesFailed"),
    );
    if (!isRecord(data)) {
      context.challenges.value = [];
      return;
    }
    context.challenges.value = parseDailyChallengeList(data.challenges);
  });

const createCompleteChallengeAction =
  (
    context: GamificationContext,
    fetchChallenges: () => Promise<void>,
    fetchProgress: () => Promise<void>,
  ) =>
  async (id: string) =>
    withLoadingState(context.loading, async () => {
      await readRequiredApiPayload(
        context.api.gamification.challenges({ id }).complete.post(),
        context.t("apiErrors.gamification.completeChallengeFailed"),
      );
      await fetchChallenges();
      await fetchProgress();
    });

const createFetchWeeklyProgressAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.gamification.weekly.get(),
      context.t("apiErrors.gamification.fetchWeeklyFailed"),
    );
    context.weeklyProgress.value = isRecord(data) ? data : null;
  });

const createFetchMonthlyStatsAction = (context: GamificationContext) => async () =>
  withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.gamification.monthly.get(),
      context.t("apiErrors.gamification.fetchMonthlyFailed"),
    );
    context.monthlyStats.value = isRecord(data) ? data : null;
  });

const createGamificationComputedState = (state: GamificationState) => {
  const level = computed(() => {
    const xp = state.progress.value?.xp || 0;
    return Math.floor(Math.sqrt(xp / PERCENT_MAX)) + 1;
  });

  const xpToNextLevel = computed(() => {
    const nextLevelXp = level.value ** 2 * PERCENT_MAX;
    const currentXp = state.progress.value?.xp || 0;
    return nextLevelXp - currentXp;
  });

  const currentStreak = computed(
    () => state.progress.value?.currentStreak || state.progress.value?.streak || 0,
  );

  const streakMultiplier = computed(() => {
    const streak = currentStreak.value;
    if (streak >= NUM_30) return RATIO_3_0;
    if (streak >= NUM_14) return RATIO_2_0;
    if (streak >= NUM_7) return RATIO_1_5;
    if (streak >= NUM_3) return RATIO_1_25;
    return RATIO_1_0;
  });

  const actionHistory = computed<JsonValue[]>(() => {
    const weeklyValue = state.weeklyProgress.value;
    if (!(isRecord(weeklyValue) && Array.isArray(weeklyValue.actionHistory))) {
      return [];
    }
    return asJsonArray(weeklyValue.actionHistory) ?? [];
  });

  return {
    level,
    xpToNextLevel,
    currentStreak,
    streakMultiplier,
    actionHistory,
  };
};

/**
 * Gamification system composable for XP, achievements, and challenges.
 */
export function useGamification() {
  const state = createGamificationState();
  const context: GamificationContext = {
    ...state,
    api: useApi(),
    t: useI18n().t,
  };

  const fetchProgress = createFetchProgressAction(context);
  const fetchChallenges = createFetchChallengesAction(context);
  const actions = {
    fetchProgress,
    awardXP: createAwardXpAction(context, fetchProgress),
    fetchAchievements: createFetchAchievementsAction(context),
    fetchChallenges,
    completeChallenge: createCompleteChallengeAction(context, fetchChallenges, fetchProgress),
    fetchWeeklyProgress: createFetchWeeklyProgressAction(context),
    fetchMonthlyStats: createFetchMonthlyStatsAction(context),
  };
  const computedState = createGamificationComputedState(state);

  return {
    progress: readonly(state.progress),
    achievements: readonly(state.achievements),
    challenges: readonly(state.challenges),
    weeklyProgress: readonly(state.weeklyProgress),
    monthlyStats: readonly(state.monthlyStats),
    loading: readonly(state.loading),
    ...computedState,
    ...actions,
  };
}

