import { type ComputedRef, computed } from "vue";

type Translator = (key: string, params?: Record<string, unknown>) => string;

const ENTITY_PROMPT_KEY_BY_TYPE: Record<AIChatContextEntityType, string> = {
  automation_run: "floatingChat.prompts.entity.automationRun",
  interview_session: "floatingChat.prompts.entity.interviewSession",
  job: "floatingChat.prompts.entity.job",
  resume: "floatingChat.prompts.entity.resume",
  studio: "floatingChat.prompts.entity.studio",
};

const ENTITY_TYPE_LABEL_KEY_BY_TYPE: Record<AIChatContextEntityType, string> = {
  automation_run: "floatingChat.entityTypes.automationRun",
  interview_session: "floatingChat.entityTypes.interviewSession",
  job: "floatingChat.entityTypes.job",
  resume: "floatingChat.entityTypes.resume",
  studio: "floatingChat.entityTypes.studio",
};

const buildStateChips = (context: AIChatContext, t: Translator): string[] => {
  const chips: string[] = [];

  if (context.state.resumeCount > 0) {
    chips.push(t("floatingChat.stateChips.resumes", { count: context.state.resumeCount }));
  }
  if (context.state.jobCount > 0) {
    chips.push(t("floatingChat.stateChips.jobs", { count: context.state.jobCount }));
  }
  if (context.state.studioCount > 0) {
    chips.push(t("floatingChat.stateChips.studios", { count: context.state.studioCount }));
  }
  if (context.state.interviewSessionCount > 0) {
    chips.push(
      t("floatingChat.stateChips.sessions", { count: context.state.interviewSessionCount }),
    );
  }
  if (context.state.portfolioProjectCount > 0) {
    chips.push(
      t("floatingChat.stateChips.projects", { count: context.state.portfolioProjectCount }),
    );
  }

  return chips;
};

const createCurrentContextLabel = (context: ComputedRef<AIChatContext>, t: Translator) =>
  computed(() => {
    const domain = context.value.domain ?? "general";
    return t(AI_CHAT_FLOATING_CONTEXT_DOMAIN_LABEL_KEYS[domain]);
  });

const createFocusedEntityLabel = (context: ComputedRef<AIChatContext>) =>
  computed(() => {
    const entity = context.value.entity;
    if (!entity) {
      return "";
    }

    return entity.label || entity.id;
  });

interface ContextChipBuilderInput {
  context: ComputedRef<AIChatContext>;
  focusedEntityLabel: ComputedRef<string>;
  t: Translator;
}

/**
 * User-facing chips only (entity + state). Surface/Route/Scope telemetry belongs
 * in aria labels / headers — not badge clutter on the floating panel.
 */
const createContextChips = ({ context, focusedEntityLabel, t }: ContextChipBuilderInput) =>
  computed(() => {
    const chips: string[] = [];
    const entity = context.value.entity;
    if (entity) {
      chips.push(
        t("floatingChat.entityChip", {
          type: t(ENTITY_TYPE_LABEL_KEY_BY_TYPE[entity.type]),
          entity: focusedEntityLabel.value,
        }),
      );
    }

    chips.push(...buildStateChips(context.value, t));
    return chips;
  });

const createContextualPrompts = (
  context: ComputedRef<AIChatContext>,
  t: Translator,
  currentContextLabel: ComputedRef<string>,
  focusedEntityLabel: ComputedRef<string>,
) =>
  computed(() => {
    const prompts: string[] = [];
    const entity = context.value.entity;
    const target = focusedEntityLabel.value || currentContextLabel.value;
    const domain = context.value.domain ?? "general";

    const pushPrompt = (key: string) => {
      prompts.push(t(key, { target }));
    };

    if (entity) {
      pushPrompt(AI_CHAT_FLOATING_FOCUSED_ENTITY_PROMPT_KEY);
      pushPrompt(ENTITY_PROMPT_KEY_BY_TYPE[entity.type]);
    }

    pushPrompt(AI_CHAT_FLOATING_CONTEXT_PROMPT_KEYS[domain]);
    pushPrompt(AI_CHAT_FLOATING_CONTEXT_PROMPT_KEYS.general);

    return [...new Set(prompts)];
  });

/**
 * Builds human-readable context labels, chips, and prompt suggestions for AI chat surfaces.
 *
 * @param context - Current typed AI chat context snapshot.
 * @param t - i18n translator used to render localized labels.
 * @returns Computed labels and chips shared by chat page and floating widget.
 */
export function useAIChatContextSummary(context: ComputedRef<AIChatContext>, t: Translator) {
  const currentContextLabel = createCurrentContextLabel(context, t);
  const focusedEntityLabel = createFocusedEntityLabel(context);
  const contextChips = createContextChips({
    context,
    focusedEntityLabel,
    t,
  });
  const contextualPrompts = createContextualPrompts(
    context,
    t,
    currentContextLabel,
    focusedEntityLabel,
  );

  return {
    contextChips,
    contextualPrompts,
    currentContextLabel,
    focusedEntityLabel,
  };
}

import { AI_PROVIDER_DEFAULT } from "@bao/shared/constants/ai-provider";
import type { AIProviderType } from "@bao/shared/types/ai";
import type { ComputedRef, Ref } from "vue";
import type { ProviderConfig } from "~/types/ai-dashboard";
import {
  resolveProviderMetadata,
  resolveProviderModelOptions,
  resolveProviderModelSelection,
} from "~/utils/ai-control-plane";

export function useAIDashboardSelection(
  settings: ReturnType<typeof useSettings>["settings"],
  providers: ComputedRef<ProviderConfig[]>,
) {
  const selectedProvider = ref<AIProviderType>(AI_PROVIDER_DEFAULT);
  const selectedModel = ref("");
  const selectedProviderModels = computed(() => {
    const matchingProvider = providers.value.find(
      (provider) => provider.id === selectedProvider.value,
    );
    return resolveProviderModelOptions(
      selectedProvider.value,
      settings.value,
      matchingProvider?.models ?? [],
    );
  });

  function resolveDefaultModel(providerId: AIProviderType): string {
    const matchingProvider = providers.value.find((provider) => provider.id === providerId);
    if (matchingProvider?.models[0]) {
      return matchingProvider.models[0];
    }

    const catalogEntry = resolveProviderMetadata(providerId);
    return catalogEntry?.modelHints[0] ?? "";
  }

  return {
    resolveDefaultModel,
    selectedModel,
    selectedProvider,
    selectedProviderModels,
  };
}

export function syncDashboardSelections(input: {
  dashboardBootstrap: Ref<
    { activeModel: string; activeProvider: AIProviderType } | null | undefined
  >;
  selectedProvider: Ref<AIProviderType>;
  selectedModel: Ref<string>;
  settings: ReturnType<typeof useSettings>["settings"];
  selectedProviderModels: ComputedRef<string[]>;
}) {
  watch(
    input.dashboardBootstrap,
    (value) => {
      if (!value) {
        return;
      }

      input.selectedProvider.value = value.activeProvider;
      input.selectedModel.value = value.activeModel;
    },
    { immediate: true },
  );

  watch(input.selectedProvider, (providerId) => {
    input.selectedModel.value = resolveProviderModelSelection(
      providerId,
      input.settings.value,
      input.selectedProviderModels.value,
    );
  });
}

import type { Achievement, DailyChallenge } from "@bao/shared/types/gamification";
import {
  asBoolean,
  asJsonArray,
  asNumber,
  asString,
  isRecord,
} from "@bao/shared/utils/type-guards";

export const toAchievement = <T>(value: T): Achievement | null => {
  if (!isRecord(value)) {
    return null;
  }
  const id = asString(value.id);
  const name = asString(value.name);
  const description = asString(value.description);
  const icon = asString(value.icon);
  const rawIconKind = asString(value.iconType);
  const rawCategory = asString(value.category);
  const rawRarity = asString(value.rarity);
  const xpReward = asNumber(value.xpReward);
  const unlocked = asBoolean(value.unlocked);
  if (!(id && name && description && icon && rawIconKind && rawCategory && rawRarity)) {
    return null;
  }
  if (xpReward === undefined || unlocked === undefined) {
    return null;
  }
  if (rawIconKind !== "emoji" && rawIconKind !== "custom") {
    return null;
  }
  if (
    rawCategory !== "progress" &&
    rawCategory !== "social" &&
    rawCategory !== "skill" &&
    rawCategory !== "special" &&
    rawCategory !== "milestone"
  ) {
    return null;
  }
  if (
    rawRarity !== "common" &&
    rawRarity !== "rare" &&
    rawRarity !== "epic" &&
    rawRarity !== "legendary"
  ) {
    return null;
  }
  const achievement: Achievement = {
    id,
    name,
    description,
    icon,
    iconType: rawIconKind,
    category: rawCategory,
    xpReward,
    requirements: {},
    unlocked,
    rarity: rawRarity,
  };
  const unlockedAt = asString(value.unlockedAt);
  if (unlockedAt) {
    achievement.unlockedAt = unlockedAt;
  }
  const hidden = asBoolean(value.hidden);
  if (hidden !== undefined) {
    achievement.hidden = hidden;
  }
  return achievement;
};

export const toDailyChallenge = <T>(value: T): DailyChallenge | null => {
  if (!isRecord(value)) {
    return null;
  }
  const id = asString(value.id);
  const name = asString(value.name);
  const description = asString(value.description);
  const icon = asString(value.icon);
  const rawIconKind = asString(value.iconType);
  const rawCategory = asString(value.category);
  const xpReward = asNumber(value.xpReward);
  const completed = asBoolean(value.completed);
  if (!(id && name && description && icon && rawIconKind && rawCategory)) {
    return null;
  }
  if (xpReward === undefined || completed === undefined) {
    return null;
  }
  if (rawIconKind !== "emoji" && rawIconKind !== "custom") {
    return null;
  }
  if (
    rawCategory !== "profile" &&
    rawCategory !== "job_search" &&
    rawCategory !== "skill_building" &&
    rawCategory !== "social" &&
    rawCategory !== "engagement"
  ) {
    return null;
  }
  const challenge: DailyChallenge = {
    id,
    name,
    description,
    icon,
    iconType: rawIconKind,
    category: rawCategory,
    xpReward,
    completed,
  };
  const validUntil = asString(value.validUntil);
  if (validUntil) {
    challenge.validUntil = validUntil;
  }
  const progress = asNumber(value.progress);
  if (progress !== undefined) {
    challenge.progress = progress;
  }
  const goal = asNumber(value.goal);
  if (goal !== undefined) {
    challenge.goal = goal;
  }
  return challenge;
};

export const parseAchievementList = <T>(value: T): Achievement[] => {
  const entries = asJsonArray(value) ?? [];
  const achievements: Achievement[] = [];
  for (const entry of entries) {
    const achievement = toAchievement(entry);
    if (achievement) {
      achievements.push(achievement);
    }
  }
  return achievements;
};

export const parseDailyChallengeList = <T>(value: T): DailyChallenge[] => {
  const entries = asJsonArray(value) ?? [];
  const challenges: DailyChallenge[] = [];
  for (const entry of entries) {
    const challenge = toDailyChallenge(entry);
    if (challenge) {
      challenges.push(challenge);
    }
  }
  return challenges;
};

import type {
  AutomationRunStatus,
  AutomationRunType,
  AutomationScrapeTarget,
  RpaCapabilityAuditReport,
} from "@bao/shared/constants/automation";
import type {
  EmailResponseRequest,
  EmailResponseResult,
} from "@bao/shared/schemas/automation-email.schema";
import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { settle } from "@bao/shared/utils/promise";
import type { AsyncData } from "nuxt/app";
import type { FetchError } from "ofetch";
import { type MaybeRef, toValue } from "vue";
import { useAsyncData } from "#imports";
import { assertApiResponse } from "~/composables/async-flow";
import type { ClientApi } from "~/types/client-api";

export interface JobApplyBody {
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
  customAnswers?: Record<string, string>;
}

export interface ScheduleJobApplyBody extends JobApplyBody {
  runAt: string;
}

export interface ScheduleEmailResponseBody extends EmailResponseRequest {
  runAt: string;
}

export interface ScheduleScrapeBody {
  target: AutomationScrapeTarget;
  runAt: string;
}

export interface RunScrapeBody {
  target: AutomationScrapeTarget;
}

export interface FetchRunsParams {
  type?: AutomationRunType;
  status?: AutomationRunStatus;
}

type RunListAsyncData = AsyncData<RpaRunExecutionEnvelope[] | undefined, FetchError | undefined>;
type RunAsyncData = AsyncData<RpaRunExecutionEnvelope | undefined, FetchError | undefined>;
type CapabilityAuditAsyncData = AsyncData<
  RpaCapabilityAuditReport | undefined,
  FetchError | undefined
>;

function asRunEnvelope(data: unknown): RpaRunExecutionEnvelope {
  return data as RpaRunExecutionEnvelope;
}

function asRunEnvelopeList(data: unknown): RpaRunExecutionEnvelope[] {
  return Array.isArray(data) ? (data as RpaRunExecutionEnvelope[]) : [];
}

function asCapabilityReport(data: unknown): RpaCapabilityAuditReport {
  return data as RpaCapabilityAuditReport;
}

export function createAutomationEdenMutations(api: ClientApi) {
  const triggerJobApply = async (body: JobApplyBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation["job-apply"].post(body);
    assertApiResponse(error, "automation.jobApply.triggerFailed");
    return asRunEnvelope(data);
  };

  const scheduleJobApply = async (body: ScheduleJobApplyBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation["job-apply"].schedule.post(body);
    assertApiResponse(error, "automation.jobApply.scheduleFailed");
    return asRunEnvelope(data);
  };

  const triggerEmailResponse = async (body: EmailResponseRequest): Promise<EmailResponseResult> => {
    const { data, error } = await api.automation["email-response"].post(body);
    assertApiResponse(error, "automation.emailResponse.triggerFailed");
    return data as EmailResponseResult;
  };

  const scheduleEmailResponse = async (
    body: ScheduleEmailResponseBody,
  ): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation["email-response"].schedule.post(body);
    assertApiResponse(error, "automation.emailResponse.scheduleFailed");
    return asRunEnvelope(data);
  };

  const triggerScrape = async (body: RunScrapeBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation.scrape.post(body);
    assertApiResponse(error, "automation.scrape.triggerFailed");
    return asRunEnvelope(data);
  };

  const scheduleScrape = async (body: ScheduleScrapeBody): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation.scrape.schedule.post(body);
    assertApiResponse(error, "automation.scrape.scheduleFailed");
    return asRunEnvelope(data);
  };

  return {
    triggerJobApply,
    scheduleJobApply,
    triggerEmailResponse,
    scheduleEmailResponse,
    triggerScrape,
    scheduleScrape,
  };
}

export function createAutomationEdenQueries(api: ClientApi) {
  const getVerifyContext = async (): Promise<{ resumeId: string } | null> => {
    const result = await settle(api.automation.verify.context.get());
    if (result.status !== "fulfilled") {
      return null;
    }
    const { data, error } = result.value;
    if (error || !data || typeof data.resumeId !== "string" || data.resumeId.length === 0) {
      return null;
    }
    return { resumeId: data.resumeId };
  };

  const getRun = async (id: string): Promise<RpaRunExecutionEnvelope> => {
    const { data, error } = await api.automation.runs({ id }).get();
    assertApiResponse(error, "automation.runs.fetchOneFailed");
    return asRunEnvelope(data);
  };

  const getRuns = async (params: FetchRunsParams = {}): Promise<RpaRunExecutionEnvelope[]> => {
    const { data, error } = await api.automation.runs.get({
      query: {
        type: params.type,
        status: params.status,
      },
    });
    assertApiResponse(error, "automation.runs.fetchListFailed");
    return asRunEnvelopeList(data);
  };

  const getRpaCapabilities = async (): Promise<RpaCapabilityAuditReport> => {
    const { data, error } = await api.automation.capabilities.get();
    assertApiResponse(error, "automation.capabilities.fetchFailed");
    return asCapabilityReport(data);
  };

  const fetchRuns = (params: MaybeRef<FetchRunsParams> = {}): RunListAsyncData =>
    useAsyncData("automation-runs-list", async () => getRuns(toValue(params)), {
      watch: [() => toValue(params)],
    }) as RunListAsyncData;

  const fetchRun = (id: string): RunAsyncData =>
    useAsyncData(`automation-run-${id}`, async () => getRun(id)) as RunAsyncData;

  const fetchRpaCapabilities = (): CapabilityAuditAsyncData =>
    useAsyncData("automation-rpa-capabilities", async () =>
      getRpaCapabilities(),
    ) as CapabilityAuditAsyncData;

  return {
    getVerifyContext,
    getRun,
    getRuns,
    getRpaCapabilities,
    fetchRuns,
    fetchRun,
    fetchRpaCapabilities,
  };
}

import {
  AI_CHAT_VOICE_AUTO_SPEAK_DEFAULT,
  AI_CHAT_VOICE_DEFAULT_ID,
  AI_CHAT_VOICE_ERROR_MESSAGE_KEYS,
  type AIChatVoiceErrorCode,
} from "@bao/shared/constants/ai-voice";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type { ChatMessage } from "@bao/shared/types/ai";
import type { Ref } from "vue";
import { computed, getCurrentScope, onScopeDispose, watch } from "vue";
import { resolveSpeechLocale } from "../utils/speech";
import { useNuxtState } from "./nuxtRuntime";
import { useSpeech } from "./useSpeech";

/**
 * Input and message refs needed to bind voice controls to a chat surface.
 */
export interface UseChatVoiceOptions {
  draft: Ref<string>;
  locale: Ref<string>;
  messages: Readonly<Ref<readonly ChatMessage[]>>;
}

interface VoiceWatchInput {
  speech: ReturnType<typeof useSpeech>;
  locale: Ref<string>;
  messages: Readonly<Ref<readonly ChatMessage[]>>;
  draft: Ref<string>;
  autoSpeakReplies: Ref<boolean>;
  selectedVoiceId: Ref<string>;
  voices: Readonly<Ref<readonly SpeechSynthesisVoice[]>>;
}

interface VoiceActionInput {
  speech: ReturnType<typeof useSpeech>;
  locale: Ref<string>;
  selectedVoiceId: Ref<string>;
  voices: Readonly<Ref<readonly SpeechSynthesisVoice[]>>;
  latestAssistantMessage: Readonly<Ref<string>>;
  canReplayAssistant: Readonly<Ref<boolean>>;
}

interface VoiceComputedState {
  autoSpeakReplies: Ref<boolean>;
  selectedVoiceId: Ref<string>;
  voices: Readonly<Ref<readonly SpeechSynthesisVoice[]>>;
  latestAssistantMessage: Readonly<Ref<string>>;
  canReplayAssistant: Readonly<Ref<boolean>>;
  errorMessageKey: Readonly<Ref<string>>;
  supportHintKey: Readonly<Ref<string>>;
}

interface SpeakVoiceInput {
  speech: ReturnType<typeof useSpeech>;
  text: string;
  locale: string;
  selectedVoiceId: string;
  voices: readonly SpeechSynthesisVoice[];
}

/**
 * Resolves the most recent assistant message with non-empty content.
 *
 * @param messages Chat message history.
 * @returns Latest assistant message content or empty string.
 */
function resolveLatestAssistantMessage(messages: readonly ChatMessage[]): string {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.role !== "assistant") {
      continue;
    }

    const trimmedContent = message.content.trim();
    if (trimmedContent.length > 0) {
      return trimmedContent;
    }
  }

  return "";
}

/**
 * Resolves the i18n key for a canonical speech error code.
 *
 * @param value Canonical voice error code.
 * @returns Translation key path or empty string.
 */
function resolveSpeechErrorMessageKey(value: AIChatVoiceErrorCode | null | undefined): string {
  if (value === null || value === undefined) {
    return "";
  }

  return AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[value];
}

/**
 * Resolves the i18n key for voice feature support hints.
 *
 * @param supportsRecognition Whether browser speech recognition is available.
 * @param supportsSynthesis Whether browser speech synthesis is available.
 * @returns Translation key path or empty string when all voice features are available.
 */
function resolveVoiceSupportHintKey(
  supportsRecognition: boolean,
  supportsSynthesis: boolean,
): string {
  if (supportsRecognition && supportsSynthesis) {
    return "";
  }

  if (!(supportsRecognition || supportsSynthesis)) {
    return "aiChatCommon.voice.unsupportedHint";
  }

  if (!supportsRecognition) {
    return "aiChatCommon.voice.recognitionUnsupportedHint";
  }

  return "aiChatCommon.voice.synthesisUnsupportedHint";
}

/**
 * Resolves a speech synthesis voice by ID.
 *
 * @param voiceId Persisted voice identifier.
 * @param voices Available browser voices.
 * @returns Matching browser voice when available.
 */
function resolveVoiceById(
  voiceId: string,
  voices: readonly SpeechSynthesisVoice[],
): SpeechSynthesisVoice | undefined {
  const trimmedVoiceId = voiceId.trim();
  if (trimmedVoiceId.length === 0) {
    return;
  }

  return voices.find((voice) => voice.voiceURI === trimmedVoiceId);
}

/**
 * Resolves a locale-matching fallback voice for synthesis.
 *
 * @param locale Current UI locale.
 * @param voices Available browser voices.
 * @returns Locale-aligned fallback voice.
 */
function resolveLocaleVoice(
  locale: string,
  voices: readonly SpeechSynthesisVoice[],
): SpeechSynthesisVoice | undefined {
  const normalizedLocale = resolveSpeechLocale(locale).toLowerCase();
  const [languagePrefix = ""] = normalizedLocale.split("-");
  const localePrefix = `${languagePrefix}-`;

  return (
    voices.find((voice) => voice.lang.toLowerCase() === normalizedLocale) ??
    voices.find((voice) => voice.lang.toLowerCase().startsWith(localePrefix)) ??
    voices.find((voice) => voice.default) ??
    voices.at(0)
  );
}

function resolveSelectedVoice(
  selectedVoiceId: string,
  locale: string,
  voices: readonly SpeechSynthesisVoice[],
): string {
  if (voices.length === 0) {
    return AI_CHAT_VOICE_DEFAULT_ID;
  }

  const selectedVoice = resolveVoiceById(selectedVoiceId, voices);
  if (selectedVoice) {
    return selectedVoiceId;
  }

  return resolveLocaleVoice(locale, voices)?.voiceURI ?? AI_CHAT_VOICE_DEFAULT_ID;
}

function speakWithSelectedVoice(input: SpeakVoiceInput): void {
  const selectedVoice = resolveVoiceById(input.selectedVoiceId, input.voices);
  input.speech.speak(input.text, {
    lang: resolveSpeechLocale(input.locale),
    ...(selectedVoice ? { voice: selectedVoice } : {}),
  });
}

function registerVoiceWatchers(input: VoiceWatchInput): void {
  watch(
    [input.voices, () => input.locale.value],
    ([availableVoices, localeValue]) => {
      input.selectedVoiceId.value = resolveSelectedVoice(
        input.selectedVoiceId.value,
        localeValue,
        availableVoices,
      );
    },
    { immediate: true },
  );

  watch(
    () => input.speech.fullTranscript.value,
    (transcriptValue) => {
      if (transcriptValue.length > 0) {
        input.draft.value = transcriptValue;
      }
    },
  );

  watch(
    () => input.messages.value.length,
    (nextLength, previousLength) => {
      if (!(input.speech.supportsSynthesis.value && input.autoSpeakReplies.value)) {
        return;
      }
      if (nextLength <= previousLength) {
        return;
      }
      const newestMessage = input.messages.value.at(-1);
      if (newestMessage?.role !== "assistant") {
        return;
      }
      const trimmedContent = newestMessage.content.trim();
      if (trimmedContent.length > 0) {
        speakWithSelectedVoice({
          speech: input.speech,
          text: trimmedContent,
          locale: input.locale.value,
          selectedVoiceId: input.selectedVoiceId.value,
          voices: input.voices.value,
        });
      }
    },
  );
}

function createVoiceActions(input: VoiceActionInput) {
  const startListening = (): boolean => {
    if (!input.speech.supportsRecognition.value) {
      return false;
    }
    return input.speech.startListening(resolveSpeechLocale(input.locale.value));
  };

  const stopListening = (): void => {
    input.speech.stopListening();
  };

  const toggleListening = (): boolean => {
    if (input.speech.isListening.value) {
      stopListening();
      return true;
    }
    return startListening();
  };

  const speakLatestAssistantMessage = (): boolean => {
    if (!input.canReplayAssistant.value) {
      return false;
    }
    speakWithSelectedVoice({
      speech: input.speech,
      text: input.latestAssistantMessage.value,
      locale: input.locale.value,
      selectedVoiceId: input.selectedVoiceId.value,
      voices: input.voices.value,
    });
    return true;
  };

  return {
    startListening,
    stopListening,
    toggleListening,
    speakLatestAssistantMessage,
  };
}

function createVoiceComputedState(
  options: UseChatVoiceOptions,
  speech: ReturnType<typeof useSpeech>,
): VoiceComputedState {
  const autoSpeakReplies = useNuxtState<boolean>(
    STATE_KEYS.AI_CHAT_AUTO_SPEAK,
    () => AI_CHAT_VOICE_AUTO_SPEAK_DEFAULT,
  );
  const selectedVoiceId = useNuxtState<string>(
    STATE_KEYS.AI_CHAT_VOICE_ID,
    () => AI_CHAT_VOICE_DEFAULT_ID,
  );
  const voices = computed(() => speech.voices.value);
  const latestAssistantMessage = computed(() =>
    resolveLatestAssistantMessage(options.messages.value),
  );
  const canReplayAssistant = computed(
    () => speech.supportsSynthesis.value && latestAssistantMessage.value.length > 0,
  );

  return {
    autoSpeakReplies,
    selectedVoiceId,
    voices,
    latestAssistantMessage,
    canReplayAssistant,
    errorMessageKey: computed(() => resolveSpeechErrorMessageKey(speech.error.value)),
    supportHintKey: computed(() =>
      resolveVoiceSupportHintKey(speech.supportsRecognition.value, speech.supportsSynthesis.value),
    ),
  };
}

/**
 * Voice controls shared by floating chat and full chat page.
 *
 * @param options Chat input and message refs.
 * @returns Reactive voice controls and status values.
 */
export function useChatVoice(options: UseChatVoiceOptions) {
  const speech = useSpeech();
  const state = createVoiceComputedState(options, speech);

  registerVoiceWatchers({
    speech,
    locale: options.locale,
    messages: options.messages,
    draft: options.draft,
    autoSpeakReplies: state.autoSpeakReplies,
    selectedVoiceId: state.selectedVoiceId,
    voices: state.voices,
  });
  const actions = createVoiceActions({
    speech,
    locale: options.locale,
    selectedVoiceId: state.selectedVoiceId,
    voices: state.voices,
    latestAssistantMessage: state.latestAssistantMessage,
    canReplayAssistant: state.canReplayAssistant,
  });

  const cleanup = () => {
    speech.stopListening();
    speech.stopSpeaking();
  };
  if (getCurrentScope()) {
    onScopeDispose(cleanup);
  }

  return {
    autoSpeakReplies: state.autoSpeakReplies,
    selectedVoiceId: state.selectedVoiceId,
    voices: state.voices,
    canReplayAssistant: state.canReplayAssistant,
    errorMessageKey: state.errorMessageKey,
    supportHintKey: state.supportHintKey,
    isListening: speech.isListening,
    isSpeaking: speech.isSpeaking,
    supportsRecognition: speech.supportsRecognition,
    supportsSynthesis: speech.supportsSynthesis,
    isSupported: speech.isSupported,
    ...actions,
  };
}

/**
 * Typed access boundary for the Eden Treaty `$api` instance.
 * All composables use this to access the Elysia server.
 */
import type { ClientApi } from "~/types/client-api";
import { useNuxtRuntimeApp } from "./nuxtRuntime";

/**
 * Returns the typed Eden API client exposed by the Nuxt plugin.
 *
 * @returns The Nuxt runtime `$api` instance.
 */
export function useApi(): ClientApi {
  const { $api } = useNuxtRuntimeApp();
  return $api;
}

import type { Ref } from "vue";
import { onScopeDispose, ref, watch } from "vue";

/**
 * Returns a debounced mirror of a source ref value.
 *
 * @param source Source reactive value to debounce.
 * @param delayMs Debounce duration in milliseconds.
 * @returns Debounced ref that updates after the provided delay.
 */
export function useDebouncedValue<T>(source: Readonly<Ref<T>>, delayMs: number): Ref<T> {
  const debouncedValue = ref(source.value) as Ref<T>;
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  watch(
    source,
    (nextValue) => {
      if (timeoutId !== null) {
        clearTimeout(timeoutId);
      }

      timeoutId = setTimeout(() => {
        debouncedValue.value = nextValue;
        timeoutId = null;
      }, delayMs);
    },
    { deep: true },
  );

  onScopeDispose(() => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
  });

  return debouncedValue;
}

import { ref } from "vue";

export function useDeleteConfirmation() {
  const showDeleteDialog = ref(false);
  const pendingDeleteId = ref<string | null>(null);

  function requestDelete(id: string): void {
    pendingDeleteId.value = id;
    showDeleteDialog.value = true;
  }

  function clearDeleteState(): void {
    pendingDeleteId.value = null;
  }

  function closeDeleteDialog(): void {
    clearDeleteState();
    showDeleteDialog.value = false;
  }

  return {
    showDeleteDialog,
    pendingDeleteId,
    requestDelete,
    clearDeleteState,
    closeDeleteDialog,
  };
}

import { ROUTE_GAMIFICATION_XP } from "@bao/shared/constants/gamification";
import type { SkillCategory, SkillMapping } from "@bao/shared/types/skill-mapping";
import type { Ref } from "vue";
import { toSkillMapping } from "~/composables/api-normalizer-skills";
import { settlePromise } from "~/composables/async-flow";
import {
  SKILLS_DEFAULT_CATEGORY,
  SKILLS_DEFAULT_CONFIDENCE,
  SKILLS_DEFAULT_DEMAND_LEVEL,
  SKILLS_GAMIFICATION_REASONS,
  SKILLS_GAMIFICATION_XP,
  SKILLS_MIN_GAME_EXPRESSION_LENGTH,
  SKILLS_MIN_TRANSFERABLE_SKILL_LENGTH,
  type SkillsGamificationReason,
} from "~/constants/skills";
import { getErrorMessage } from "~/utils/errors";

export interface NewSkillMappingFormState {
  gameExpression: string;
  transferableSkill: string;
  industryApplications: string[];
  confidence: number;
  category: SkillCategory;
}

type SkillsPageActionsInput = {
  api: ReturnType<typeof useApi>;
  toast: {
    error: (message: string) => void;
    success: (message: string) => void;
  };
  t: (key: string, params?: Record<string, string | number>) => string;
  awardXP: (amount: number, reason: string) => Promise<void>;
  fetchProgress: () => Promise<void>;
  mappings: Ref<SkillMapping[]>;
  loading: Ref<boolean>;
  analyzing: Ref<boolean>;
  pageError: Ref<string | null>;
  showAddModal: Ref<boolean>;
  pendingDeleteMappingId: Ref<string | null>;
  closeDeleteMappingDialog: () => void;
  newApplication: Ref<string>;
  newMapping: NewSkillMappingFormState;
};

const DEFAULT_SKILL_FORM_STATE = {
  gameExpression: "",
  transferableSkill: "",
  industryApplications: [],
  confidence: SKILLS_DEFAULT_CONFIDENCE,
  category: SKILLS_DEFAULT_CATEGORY,
} satisfies NewSkillMappingFormState;

function createSkillFormActions(
  newApplication: SkillsPageActionsInput["newApplication"],
  newMapping: SkillsPageActionsInput["newMapping"],
) {
  function resetForm(): void {
    newMapping.gameExpression = DEFAULT_SKILL_FORM_STATE.gameExpression;
    newMapping.transferableSkill = DEFAULT_SKILL_FORM_STATE.transferableSkill;
    newMapping.industryApplications = [...DEFAULT_SKILL_FORM_STATE.industryApplications];
    newMapping.confidence = DEFAULT_SKILL_FORM_STATE.confidence;
    newMapping.category = DEFAULT_SKILL_FORM_STATE.category;
    newApplication.value = "";
  }

  function addApplication(): void {
    const normalizedApplication = newApplication.value.trim();
    if (normalizedApplication.length === 0) {
      return;
    }

    newMapping.industryApplications.push(normalizedApplication);
    newApplication.value = "";
  }

  function removeApplication(index: number): void {
    newMapping.industryApplications.splice(index, 1);
  }

  return {
    addApplication,
    removeApplication,
    resetForm,
  };
}

function createFetchMappingsAction({
  api,
  toast,
  t,
  mappings,
  loading,
  pageError,
}: Pick<SkillsPageActionsInput, "api" | "toast" | "t" | "mappings" | "loading" | "pageError">) {
  async function fetchMappings(): Promise<void> {
    pageError.value = null;
    loading.value = true;
    const mappingsResult = await settlePromise(
      api.skills.mappings.get(),
      t("skillsPage.errors.fetchFailed"),
    );
    loading.value = false;

    if (!mappingsResult.ok) {
      pageError.value = getErrorMessage(mappingsResult.error, t("skillsPage.errors.fetchFailed"));
      toast.error(pageError.value);
      return;
    }

    const { data } = mappingsResult.value;
    mappings.value = Array.isArray(data)
      ? data
          .map((entry) => toSkillMapping(entry))
          .filter((entry): entry is SkillMapping => entry !== null)
      : [];
  }

  return { fetchMappings };
}

function createSkillsGamificationActions(
  input: Pick<SkillsPageActionsInput, "awardXP" | "fetchProgress" | "t">,
) {
  async function syncGamificationProgress(): Promise<void> {
    await settlePromise(input.fetchProgress(), input.t("skillsPage.errors.gamificationLoadFailed"));
  }

  async function tryAwardSkillXp(
    amount: number,
    reason: SkillsGamificationReason,
  ): Promise<boolean> {
    const awardResult = await settlePromise(
      input.awardXP(amount, reason),
      input.t("apiErrors.gamification.awardXPFailed"),
    );
    return awardResult.ok;
  }

  return {
    syncGamificationProgress,
    tryAwardSkillXp,
  };
}

function createSkillsMutationActions(
  input: Pick<
    SkillsPageActionsInput,
    | "api"
    | "toast"
    | "t"
    | "loading"
    | "analyzing"
    | "showAddModal"
    | "pendingDeleteMappingId"
    | "closeDeleteMappingDialog"
    | "newMapping"
  >,
  support: {
    fetchMappings: () => Promise<void>;
    resetForm: () => void;
    tryAwardSkillXp: (amount: number, reason: SkillsGamificationReason) => Promise<boolean>;
  },
) {
  const handleAddMapping = createAddMappingAction(input, support);
  const handleDeleteMapping = createDeleteMappingAction(input, support);
  const handleAIAnalyze = createAnalyzeSkillsAction(input, support);

  return {
    handleAddMapping,
    handleAIAnalyze,
    handleDeleteMapping,
  };
}

function createAddMappingAction(
  input: Pick<
    SkillsPageActionsInput,
    "api" | "toast" | "t" | "loading" | "showAddModal" | "newMapping"
  >,
  support: Pick<Parameters<typeof createSkillsMutationActions>[1], "fetchMappings" | "resetForm">,
) {
  return async function handleAddMapping(): Promise<void> {
    const normalizedGameExpression = input.newMapping.gameExpression.trim();
    if (normalizedGameExpression.length < SKILLS_MIN_GAME_EXPRESSION_LENGTH) {
      input.toast.error(input.t("skillsPage.errors.gameExpressionMinLength"));
      return;
    }

    const normalizedTransferableSkill = input.newMapping.transferableSkill.trim();
    if (normalizedTransferableSkill.length < SKILLS_MIN_TRANSFERABLE_SKILL_LENGTH) {
      input.toast.error(input.t("skillsPage.errors.transferableSkillMinLength"));
      return;
    }

    input.loading.value = true;
    const addMappingResult = await settlePromise(
      (async () => {
        await input.api.skills.mappings.post({
          gameExpression: normalizedGameExpression,
          transferableSkill: normalizedTransferableSkill,
          industryApplications: input.newMapping.industryApplications,
          confidence: input.newMapping.confidence,
          category: input.newMapping.category,
          demandLevel: SKILLS_DEFAULT_DEMAND_LEVEL,
        });
        await support.fetchMappings();
        input.showAddModal.value = false;
        support.resetForm();
      })(),
      input.t("skillsPage.errors.addFailed"),
    );
    input.loading.value = false;

    if (!addMappingResult.ok) {
      input.toast.error(
        getErrorMessage(addMappingResult.error, input.t("skillsPage.errors.addFailed")),
      );
      return;
    }

    input.toast.success(
      input.t("skillsPage.toasts.mappingAddedWithXp", {
        xp: ROUTE_GAMIFICATION_XP.skillsMapped,
      }),
    );
  };
}

function createDeleteMappingAction(
  input: Pick<
    SkillsPageActionsInput,
    "api" | "toast" | "t" | "loading" | "pendingDeleteMappingId" | "closeDeleteMappingDialog"
  >,
  support: Pick<Parameters<typeof createSkillsMutationActions>[1], "fetchMappings">,
) {
  return async function handleDeleteMapping(): Promise<void> {
    const id = input.pendingDeleteMappingId.value;
    if (!id) {
      return;
    }

    input.loading.value = true;
    const deleteResult = await settlePromise(
      (async () => {
        await input.api.skills.mappings({ id }).delete();
        await support.fetchMappings();
      })(),
      input.t("skillsPage.errors.deleteFailed"),
    );
    input.loading.value = false;
    input.closeDeleteMappingDialog();

    if (!deleteResult.ok) {
      input.toast.error(
        getErrorMessage(deleteResult.error, input.t("skillsPage.errors.deleteFailed")),
      );
      return;
    }

    input.toast.success(input.t("skillsPage.toasts.mappingDeleted"));
  };
}

function createAnalyzeSkillsAction(
  input: Pick<SkillsPageActionsInput, "api" | "toast" | "t" | "analyzing">,
  support: Pick<
    Parameters<typeof createSkillsMutationActions>[1],
    "fetchMappings" | "tryAwardSkillXp"
  >,
) {
  return async function handleAIAnalyze(): Promise<void> {
    input.analyzing.value = true;
    const analysisResult = await settlePromise(
      input.api.skills["ai-analyze"].post({}),
      input.t("skillsPage.errors.analysisFailed"),
    );
    input.analyzing.value = false;

    if (!analysisResult.ok) {
      input.toast.error(
        getErrorMessage(analysisResult.error, input.t("skillsPage.errors.analysisFailed")),
      );
      return;
    }

    if (!analysisResult.value.data) {
      return;
    }

    await support.fetchMappings();
    const awardedXp = await support.tryAwardSkillXp(
      SKILLS_GAMIFICATION_XP.aiAnalysisCompleted,
      SKILLS_GAMIFICATION_REASONS.aiAnalysisCompleted,
    );
    input.toast.success(
      awardedXp
        ? input.t("skillsPage.toasts.analysisCompletedWithXp", {
            xp: SKILLS_GAMIFICATION_XP.aiAnalysisCompleted,
          })
        : input.t("skillsPage.toasts.analysisCompleted"),
    );
  };
}

export function createSkillsPageActions(input: SkillsPageActionsInput) {
  const form = createSkillFormActions(input.newApplication, input.newMapping);
  const fetchActions = createFetchMappingsAction(input);
  const gamification = createSkillsGamificationActions(input);
  const mutations = createSkillsMutationActions(input, {
    fetchMappings: fetchActions.fetchMappings,
    resetForm: form.resetForm,
    tryAwardSkillXp: gamification.tryAwardSkillXp,
  });

  async function initializeSkillsPage(): Promise<void> {
    await Promise.all([fetchActions.fetchMappings(), gamification.syncGamificationProgress()]);
  }

  return {
    ...fetchActions,
    ...form,
    ...mutations,
    initializeSkillsPage,
  };
}

import { INTERVIEW_MIN_RESPONSE_LENGTH } from "@bao/shared/constants/interview";
import { APP_ROUTE_QUERY_KEYS } from "@bao/shared/constants/routes";
import { useI18n } from "vue-i18n";
import {
  type createInterviewSessionActions,
  normalizeSessionIdFromQuery,
  type InterviewSessionFlowState as SessionFlowState,
} from "~/composables/interview-session-actions";
import type { createInterviewSessionTimer } from "~/composables/interview-session-timer";
import { PERCENT_MAX } from "@bao/shared/constants/numeric";

export function createInterviewSessionState() {
  const route = useRoute();
  const router = useRouter();
  const { currentSession, loading, getSession, submitResponse, completeSession } = useInterview();
  const { $toast } = useNuxtApp();
  const { t } = useI18n();
  const { getAlertClass } = useScoreColor();

  const voiceSettings = computed(() => currentSession.value?.config?.voiceSettings);
  const tts = useTTS(voiceSettings);
  const stt = useSTT(voiceSettings);
  const currentSessionLoadId = ref(0);
  const sessionLoadError = ref("");
  const response = ref("");
  const submitting = ref(false);
  const completing = ref(false);
  return {
    completeSession,
    completing,
    currentSession,
    currentSessionLoadId,
    getAlertClass,
    getSession,
    loading,
    response,
    route,
    router,
    sessionLoadError,
    stt,
    submitResponse,
    submitting,
    t,
    targetJob: computed(() => currentSession.value?.config?.targetJob),
    toast: $toast,
    tts,
  };
}

function createInterviewSessionQuestions(
  activeSession: ComputedRef<ReturnType<typeof useInterview>["currentSession"]["value"] | null>,
  currentQuestionIndex: ComputedRef<number>,
) {
  const currentQuestion = computed(
    () => activeSession.value?.questions?.[Math.max(0, currentQuestionIndex.value)],
  );
  const hasCurrentQuestion = computed(() => Boolean(currentQuestion.value));
  const chatQuestions = computed<{ id: string; text: string }[]>(() => {
    const session = activeSession.value;
    return session
      ? session.questions.map((question) => ({ id: question.id, text: question.question }))
      : [];
  });
  const chatResponses = computed(() => {
    const session = activeSession.value;
    if (!session) {
      return [] as { questionId: string; text: string }[];
    }

    const responseByQuestion = new Map<string, string>();
    for (const sessionResponse of session.responses) {
      responseByQuestion.set(sessionResponse.questionId, sessionResponse.transcript);
    }

    return session.questions.flatMap((question) => {
      const responseText = responseByQuestion.get(question.id);
      return responseText ? [{ questionId: question.id, text: responseText }] : [];
    });
  });

  return {
    chatQuestions,
    chatResponses,
    currentQuestion,
    hasCurrentQuestion,
  };
}

function createInterviewSessionStatus(input: {
  activeSession: ComputedRef<ReturnType<typeof useInterview>["currentSession"]["value"] | null>;
  currentQuestionIndex: ComputedRef<number>;
  loading: Ref<boolean>;
  response: Ref<string>;
  sessionId: ComputedRef<string>;
  sessionLoadError: Ref<string>;
  stt: ReturnType<typeof useSTT>;
  submitting: Ref<boolean>;
  completing: Ref<boolean>;
  t: ReturnType<typeof useI18n>["t"];
  totalQuestions: ComputedRef<number>;
  hasCurrentQuestion: ComputedRef<boolean>;
}) {
  const activeSessionComplete = computed(() => input.activeSession.value?.status === "completed");
  const activeSessionReady = computed(
    () =>
      input.activeSession.value !== null &&
      input.activeSession.value.status !== "cancelled" &&
      input.activeSession.value.status !== "completed",
  );
  const isBusy = computed(
    () =>
      input.loading.value ||
      input.submitting.value ||
      input.completing.value ||
      input.stt.isListening.value,
  );
  const isLastQuestion = computed(
    () =>
      input.hasCurrentQuestion.value &&
      input.currentQuestionIndex.value >= input.totalQuestions.value - 1,
  );
  const completionState = computed<SessionFlowState>(() => {
    if (!input.sessionId.value) return "idle";
    if (input.sessionLoadError.value.length > 0) return "error";
    if (!input.activeSession.value) return input.loading.value ? "loading" : "error";
    if (activeSessionComplete.value) return "completed";
    if (input.completing.value) return "completing";
    if (input.submitting.value) return "submitting";
    return "ready";
  });
  const canSubmit = computed(
    () =>
      input.hasCurrentQuestion.value &&
      input.response.value.trim().length >= INTERVIEW_MIN_RESPONSE_LENGTH &&
      !isBusy.value &&
      activeSessionReady.value,
  );
  const canComplete = computed(
    () => input.activeSession.value !== null && !activeSessionComplete.value && !isBusy.value,
  );

  return {
    canComplete,
    canSubmit,
    completionState,
    isLastQuestion,
  };
}

export function createInterviewSessionDerivedState(
  input: ReturnType<typeof createInterviewSessionState>,
) {
  const sessionState = createInterviewSessionIdentity(input);
  const questionState = createInterviewSessionQuestions(
    sessionState.activeSession,
    sessionState.currentQuestionIndex,
  );
  const statusState = createInterviewSessionStatus({
    activeSession: sessionState.activeSession,
    completing: input.completing,
    currentQuestionIndex: sessionState.currentQuestionIndex,
    hasCurrentQuestion: questionState.hasCurrentQuestion,
    loading: input.loading,
    response: input.response,
    sessionId: sessionState.sessionId,
    sessionLoadError: input.sessionLoadError,
    stt: input.stt,
    submitting: input.submitting,
    t: input.t,
    totalQuestions: sessionState.totalQuestions,
  });
  const progressState = createInterviewSessionProgressState({
    activeSession: sessionState.activeSession,
    currentQuestionIndex: sessionState.currentQuestionIndex,
    isLastQuestion: statusState.isLastQuestion,
    t: input.t,
    totalQuestions: sessionState.totalQuestions,
  });

  return {
    ...questionState,
    ...progressState,
    activeSession: sessionState.activeSession,
    canComplete: statusState.canComplete,
    canSubmit: statusState.canSubmit,
    canUseVoice: sessionState.canUseVoice,
    completionState: statusState.completionState,
    currentQuestionIndex: sessionState.currentQuestionIndex,
    enableVoiceMode: sessionState.enableVoiceMode,
    isLastQuestion: statusState.isLastQuestion,
    sessionId: sessionState.sessionId,
    totalQuestions: sessionState.totalQuestions,
  };
}

function createInterviewSessionIdentity(input: ReturnType<typeof createInterviewSessionState>) {
  const sessionId = computed(() =>
    normalizeSessionIdFromQuery(input.route.query[APP_ROUTE_QUERY_KEYS.id]),
  );
  const activeSession = computed(() => {
    const id = sessionId.value;
    if (!id) {
      return null;
    }
    const session = input.currentSession.value;
    if (!session || session.id !== id) {
      return null;
    }
    return session;
  });
  const enableVoiceMode = computed(() => activeSession.value?.config?.enableVoiceMode ?? false);
  const totalQuestions = computed(() => activeSession.value?.questions.length ?? 0);
  const currentQuestionIndex = computed(() => activeSession.value?.currentQuestionIndex ?? 0);
  const canUseVoice = computed(() => enableVoiceMode.value && input.stt.isSupported.value);
  return {
    activeSession,
    canUseVoice,
    currentQuestionIndex,
    enableVoiceMode,
    sessionId,
    totalQuestions,
  };
}

function createInterviewSessionProgressState(input: {
  activeSession: ComputedRef<ReturnType<typeof useInterview>["currentSession"]["value"] | null>;
  currentQuestionIndex: ComputedRef<number>;
  isLastQuestion: ComputedRef<boolean>;
  t: ReturnType<typeof useI18n>["t"];
  totalQuestions: ComputedRef<number>;
}) {
  const progress = computed(() => {
    if (!(input.totalQuestions.value && input.activeSession.value)) {
      return 0;
    }
    const current = Math.min(input.currentQuestionIndex.value, input.totalQuestions.value - 1);
    return ((current + 1) / input.totalQuestions.value) * PERCENT_MAX;
  });
  const displayQuestionIndex = computed(() =>
    input.totalQuestions.value === 0
      ? 0
      : Math.min(input.currentQuestionIndex.value + 1, input.totalQuestions.value),
  );
  const submitButtonLabelKey = computed(() =>
    input.isLastQuestion.value
      ? "interviewSession.submitFinishButton"
      : "interviewSession.submitNextButton",
  );
  const chatSubmitHint = computed(() =>
    input.t("interviewSession.minResponseHint", { count: INTERVIEW_MIN_RESPONSE_LENGTH }),
  );
  const sessionProgressLabel = computed(() =>
    input.t("interviewSession.progressLabel", {
      current: displayQuestionIndex.value,
      total: input.totalQuestions.value,
    }),
  );

  return {
    chatSubmitHint,
    displayQuestionIndex,
    progress,
    sessionProgressLabel,
    submitButtonLabelKey,
  };
}

export function registerInterviewSessionWatchers(input: {
  actions: ReturnType<typeof createInterviewSessionActions>;
  derived: ReturnType<typeof createInterviewSessionDerivedState>;
  response: Ref<string>;
  stt: ReturnType<typeof useSTT>;
  timer: ReturnType<typeof createInterviewSessionTimer>;
  tts: ReturnType<typeof useTTS>;
}) {
  watch(
    () => input.derived.sessionId.value,
    async (nextSessionId) => {
      await input.actions.loadSession(nextSessionId);
    },
    { immediate: true },
  );
  watch(
    () => input.derived.activeSession.value?.status,
    (status) => {
      if (!status || status === "completed" || status === "cancelled") {
        input.timer.stopTimer();
        return;
      }
      if (status === "active" || status === "preparing" || status === "paused") {
        input.timer.startTimer();
      }
    },
  );
  watch(
    () => input.derived.currentQuestion.value?.question,
    (question) => {
      if (input.derived.enableVoiceMode.value && question && input.tts.isSupported.value) {
        input.tts.speak(question);
      }
    },
    { immediate: true },
  );
  watch(
    () => input.stt.fullTranscript.value,
    (transcript) => {
      if (input.derived.canUseVoice.value && transcript) {
        input.response.value = transcript;
      }
    },
  );
}

export function buildInterviewSessionViewModel(input: {
  actions: ReturnType<typeof createInterviewSessionActions>;
  derived: ReturnType<typeof createInterviewSessionDerivedState>;
  state: ReturnType<typeof createInterviewSessionState>;
  timer: ReturnType<typeof createInterviewSessionTimer>;
}) {
  return {
    activeSession: input.derived.activeSession,
    canComplete: input.derived.canComplete,
    canUseVoice: input.derived.canUseVoice,
    chatQuestions: input.derived.chatQuestions,
    chatResponses: input.derived.chatResponses,
    chatSubmitHint: input.derived.chatSubmitHint,
    completing: input.state.completing,
    completionState: input.derived.completionState,
    currentQuestion: input.derived.currentQuestion,
    currentQuestionIndex: input.derived.currentQuestionIndex,
    elapsedTimeAriaLabel: input.timer.elapsedTimeAriaLabel,
    elapsedTimeDuration: input.timer.elapsedTimeDuration,
    elapsedTimeText: input.timer.elapsedTimeText,
    getAlertClass: input.state.getAlertClass,
    goToHistory: input.actions.goToHistory,
    handleCompleteInterview: input.actions.handleCompleteInterview,
    handleSubmitResponse: input.actions.handleSubmitResponse,
    progress: input.derived.progress,
    response: input.state.response,
    retryLoadSession: input.actions.retryLoadSession,
    sessionId: input.derived.sessionId,
    sessionLoadError: input.state.sessionLoadError,
    sessionProgressLabel: input.derived.sessionProgressLabel,
    stt: input.state.stt,
    submitButtonLabelKey: input.derived.submitButtonLabelKey,
    submitting: input.state.submitting,
    targetJob: input.state.targetJob,
    tts: input.state.tts,
  };
}

import {
  AUTOMATION_RUN_STATUSES,
  type AutomationRunStatus,
} from "@bao/shared/constants/automation";
import type { RpaRunEvent, RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import { PERCENT_MAX } from "~/constants/numeric-ui";

const [RUN_STATUS_PENDING, RUN_STATUS_RUNNING, RUN_STATUS_SUCCESS, RUN_STATUS_ERROR] =
  AUTOMATION_RUN_STATUSES;

export const RUN_STATUS_ORDER: Record<AutomationRunStatus, number> = {
  [RUN_STATUS_RUNNING]: 0,
  [RUN_STATUS_PENDING]: 1,
  [RUN_STATUS_ERROR]: 2,
  [RUN_STATUS_SUCCESS]: 3,
};

export const isLiveRun = (run: RpaRunExecutionEnvelope): boolean =>
  run.status === RUN_STATUS_PENDING || run.status === RUN_STATUS_RUNNING;

const computeProgressFromSteps = (
  currentStep: number | null,
  totalSteps: number | null,
): number => {
  if (
    typeof currentStep !== "number" ||
    typeof totalSteps !== "number" ||
    totalSteps <= 0 ||
    !Number.isFinite(currentStep) ||
    !Number.isFinite(totalSteps)
  ) {
    return 0;
  }
  return Math.max(0, Math.min(PERCENT_MAX, Math.round((currentStep / totalSteps) * PERCENT_MAX)));
};

const mergeRunProgressEvent = (
  run: RpaRunExecutionEnvelope,
  event: Extract<RpaRunEvent, { eventType: "progress" }>,
): RpaRunExecutionEnvelope => {
  const currentStep = typeof event.step === "number" ? event.step : run.currentStep;
  const totalSteps = typeof event.totalSteps === "number" ? event.totalSteps : run.totalSteps;
  const progress =
    typeof run.progress === "number" && Number.isFinite(run.progress)
      ? run.progress
      : computeProgressFromSteps(currentStep ?? null, totalSteps ?? null);
  return {
    ...run,
    status: event.status,
    currentStep: currentStep ?? null,
    totalSteps: totalSteps ?? null,
    progress,
    updatedAt: event.timestamp,
  };
};

const mergeRunResultEvent = (
  run: RpaRunExecutionEnvelope,
  event: Extract<RpaRunEvent, { eventType: "result" }>,
): RpaRunExecutionEnvelope => {
  const outputSteps = event.result.steps.length;
  return {
    ...run,
    status: event.result.success ? RUN_STATUS_SUCCESS : RUN_STATUS_ERROR,
    output: event.result,
    error: event.result.success ? null : event.result.error,
    progress: PERCENT_MAX,
    currentStep: outputSteps,
    totalSteps: outputSteps,
    completedAt: event.timestamp,
    updatedAt: event.timestamp,
  };
};

export const mergeRunWithEvent = (
  run: RpaRunExecutionEnvelope,
  event: RpaRunEvent,
): RpaRunExecutionEnvelope => {
  if (event.eventType === "progress") {
    return mergeRunProgressEvent(run, event);
  }
  if (event.eventType === "result") {
    return mergeRunResultEvent(run, event);
  }
  return {
    ...run,
    status: RUN_STATUS_ERROR,
    error: event.error,
    completedAt: event.timestamp,
    updatedAt: event.timestamp,
  };
};

export const sortRunsByStatusThenCreated = (
  runs: readonly RpaRunExecutionEnvelope[],
): RpaRunExecutionEnvelope[] =>
  [...runs].sort((left, right) => {
    const statusDiff = RUN_STATUS_ORDER[left.status] - RUN_STATUS_ORDER[right.status];
    if (statusDiff !== 0) {
      return statusDiff;
    }
    const createdDiff = Date.parse(right.createdAt) - Date.parse(left.createdAt);
    if (Number.isFinite(createdDiff) && createdDiff !== 0) {
      return createdDiff;
    }
    return left.id.localeCompare(right.id);
  });

import { beforeEach, describe, expect, it, vi } from "vitest";
import { effectScope } from "vue";
import { useScrollSpy } from "./useScrollSpy";
const RATIO_0_3 = 0.3;
const RATIO_0_8 = 0.8;

class MockIntersectionObserver implements IntersectionObserver {
  static latest: MockIntersectionObserver | null = null;

  readonly root: Element | Document | null = null;
  readonly rootMargin: string;
  readonly scrollMargin: string = "0px";
  readonly thresholds: ReadonlyArray<number>;
  readonly takeRecords = vi.fn((): IntersectionObserverEntry[] => []);
  readonly disconnect = vi.fn((): void => undefined);
  readonly observe = vi.fn((target: Element): void => {
    this.targets.add(target);
  });
  readonly unobserve = vi.fn((target: Element): void => {
    this.targets.delete(target);
  });

  private readonly callback: IntersectionObserverCallback;
  private readonly targets = new Set<Element>();

  constructor(callback: IntersectionObserverCallback, options?: IntersectionObserverInit) {
    this.callback = callback;
    this.rootMargin = options?.rootMargin ?? "0px";
    this.thresholds = Array.isArray(options?.threshold)
      ? options.threshold
      : [typeof options?.threshold === "number" ? options.threshold : 0];
    MockIntersectionObserver.latest = this;
  }

  trigger(entries: readonly IntersectionObserverEntry[]): void {
    this.callback.call(undefined, [...entries], this);
  }
}

const createEntry = (target: Element, intersectionRatio: number): IntersectionObserverEntry => ({
  time: Date.now(),
  target,
  rootBounds: null,
  boundingClientRect: target.getBoundingClientRect(),
  intersectionRect: target.getBoundingClientRect(),
  isIntersecting: true,
  intersectionRatio,
});

const hasDomEnvironment = (): boolean =>
  typeof window !== "undefined" && typeof document !== "undefined";

beforeEach(() => {
  MockIntersectionObserver.latest = null;
  vi.restoreAllMocks();
  Object.defineProperty(globalThis, "IntersectionObserver", {
    configurable: true,
    writable: true,
    value: MockIntersectionObserver,
  });
});

function createScopedScrollSpy() {
  const scope = effectScope();
  const scrollSpy = scope.run(() => useScrollSpy());
  if (!scrollSpy) {
    throw new Error("Scroll spy did not initialize");
  }
  return { scope, scrollSpy };
}

function assertSyncsFromHash(): void {
  if (!hasDomEnvironment()) {
    return;
  }

  const { scope, scrollSpy } = createScopedScrollSpy();
  const replaceStateSpy = vi.spyOn(window.history, "replaceState");

  const section = document.createElement("section");
  section.id = "overview";
  const scrollIntoViewMock = vi.fn();
  const focusMock = vi.fn();
  section.scrollIntoView = scrollIntoViewMock;
  section.focus = focusMock;

  scrollSpy.setSectionRef("overview", section);
  const restored = scrollSpy.syncFromHash("#overview");

  expect(restored).toBe(true);
  expect(scrollSpy.activeSectionId.value).toBe("overview");
  expect(scrollIntoViewMock).toHaveBeenCalledWith({ behavior: "auto", block: "start" });
  expect(focusMock).not.toHaveBeenCalled();
  expect(replaceStateSpy).not.toHaveBeenCalled();

  scope.stop();
}

function assertUpdatesActiveSectionFromObserver(): void {
  if (!hasDomEnvironment()) {
    return;
  }

  const { scope, scrollSpy } = createScopedScrollSpy();
  const replaceStateSpy = vi.spyOn(window.history, "replaceState");

  const sectionOne = document.createElement("section");
  sectionOne.id = "one";
  const sectionTwo = document.createElement("section");
  sectionTwo.id = "two";
  scrollSpy.setSectionRef("one", sectionOne);
  scrollSpy.setSectionRef("two", sectionTwo);

  scrollSpy.startObserver();
  const observer = MockIntersectionObserver.latest;
  if (!observer) {
    throw new Error("Observer was not created");
  }

  observer.trigger([createEntry(sectionOne, RATIO_0_3), createEntry(sectionTwo, RATIO_0_8)]);

  expect(scrollSpy.activeSectionId.value).toBe("two");
  expect(replaceStateSpy).toHaveBeenCalledWith({}, "", "#two");

  scope.stop();
}

function assertDoesNotDuplicateHashUpdates(): void {
  if (!hasDomEnvironment()) {
    return;
  }

  const { scope, scrollSpy } = createScopedScrollSpy();
  const replaceStateSpy = vi.spyOn(window.history, "replaceState");

  const section = document.createElement("section");
  section.id = "same";
  section.scrollIntoView = vi.fn();
  section.focus = vi.fn();
  scrollSpy.setSectionRef("same", section);

  scrollSpy.scrollToSection("same", { smooth: false, focus: false, updateHash: true });
  scrollSpy.scrollToSection("same", { smooth: false, focus: false, updateHash: true });

  expect(replaceStateSpy).toHaveBeenCalledTimes(1);

  scope.stop();
}

describe("useScrollSpy", () => {
  it("syncs from hash and scrolls to registered section", assertSyncsFromHash);
  it(
    "updates active section from intersection observer events",
    assertUpdatesActiveSectionFromObserver,
  );
  it(
    "does not duplicate hash updates when the active section is unchanged",
    assertDoesNotDuplicateHashUpdates,
  );
});

import { getErrorMessage } from "~/utils/errors";

type AIChatTranslate = (key: string, params?: Record<string, unknown>) => string;

export const createAIChatPageActions = (input: {
  readonly input: Ref<string>;
  readonly loading: Readonly<Ref<boolean>>;
  readonly isVoiceListening: Readonly<Ref<boolean>>;
  readonly stopListening: () => void;
  readonly sendMessage: ReturnType<typeof useAI>["sendMessage"];
  readonly scrollToBottom: (force?: boolean) => void;
  readonly focusComposer: () => void;
  readonly shouldStickToBottom: Ref<boolean>;
  readonly saveSpeechConfig: ReturnType<typeof useSpeechModelProfiles>["saveSpeechConfig"];
  readonly toast: ReturnType<typeof useNuxtApp>["$toast"];
  readonly t: AIChatTranslate;
}) => {
  const handlePromptSelection = (prompt: string): void => {
    input.input.value = prompt;
    input.focusComposer();
  };

  const handleSendMessage = async (): Promise<void> => {
    if (!input.input.value.trim() || input.loading.value) return;

    if (input.isVoiceListening.value) {
      input.stopListening();
    }

    input.shouldStickToBottom.value = true;
    const content = input.input.value.trim();
    input.input.value = "";
    await input.sendMessage(content, { source: "chat-page" });
    input.scrollToBottom(true);
  };

  const handleComposerKeydown = async (event: KeyboardEvent): Promise<void> => {
    if (event.key !== "Enter" || event.shiftKey || event.isComposing) {
      return;
    }

    event.preventDefault();
    await handleSendMessage();
  };

  const handleSaveSpeechConfig = async (): Promise<void> => {
    const saveSpeechResult = await input.saveSpeechConfig(
      input.t("aiChatPage.voiceSettings.saveErrorFallback"),
    );
    if (!saveSpeechResult.ok) {
      input.toast.error(
        getErrorMessage(
          saveSpeechResult.error,
          input.t("aiChatPage.voiceSettings.saveErrorFallback"),
        ),
      );
      return;
    }

    if (!saveSpeechResult.saved) {
      return;
    }

    input.toast.success(input.t("aiChatPage.voiceSettings.saveSuccess"));
  };

  return {
    handlePromptSelection,
    handleSendMessage,
    handleComposerKeydown,
    handleSaveSpeechConfig,
  };
};

