import { APP_ROUTE_BUILDERS, APP_ROUTES } from "@bao/shared/constants/routes";
import { settle } from "@bao/shared/utils/promise";
import { isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import { assertApiResponse, withLoadingState } from "~/composables/async-flow";
import { useApi } from "~/composables/useApi";

export type WorkspaceSearchResult = {
  type: string;
  id: string;
  title: string;
  subtitle: string;
  snippet: string;
  relevance: number;
};

export type WorkspaceSearchSuggestion = {
  text: string;
  type: string;
};

const SEARCH_TYPE_ROUTE: Record<string, (id: string) => string> = {
  jobs: (id) => APP_ROUTE_BUILDERS.jobDetail(id),
  studios: (id) => APP_ROUTE_BUILDERS.studioDetail(id),
  resumes: (id) => APP_ROUTE_BUILDERS.resumeEditor(id),
  skills: () => APP_ROUTES.skills,
};

const AUTOCOMPLETE_MIN_PREFIX = 2;
const AUTOCOMPLETE_DEBOUNCE_MS = 180;

export function resolveWorkspaceSearchResultRoute(result: WorkspaceSearchResult): string {
  const builder = SEARCH_TYPE_ROUTE[result.type];
  if (!builder) {
    return APP_ROUTES.dashboard;
  }
  return builder(result.id);
}

function asString(value: unknown): string {
  return typeof value === "string" ? value : "";
}

function mapSearchResults(data: unknown): WorkspaceSearchResult[] {
  const resultsValue = isRecord(data) ? data.results : undefined;
  const nextResults: readonly unknown[] = Array.isArray(resultsValue) ? resultsValue : [];
  const mapped: WorkspaceSearchResult[] = [];
  for (const entry of nextResults) {
    if (!isRecord(entry)) {
      continue;
    }
    mapped.push({
      type: asString(entry.type),
      id: asString(entry.id),
      title: asString(entry.title),
      subtitle: asString(entry.subtitle),
      snippet: asString(entry.snippet),
      relevance: typeof entry.relevance === "number" ? entry.relevance : 0,
    });
  }
  return mapped;
}

function mapSuggestions(data: unknown): WorkspaceSearchSuggestion[] {
  if (!Array.isArray(data)) {
    return [];
  }
  const entries: readonly unknown[] = data;
  const mapped: WorkspaceSearchSuggestion[] = [];
  for (const entry of entries) {
    if (!isRecord(entry)) {
      continue;
    }
    mapped.push({
      text: asString(entry.text),
      type: asString(entry.type),
    });
  }
  return mapped;
}

function createWorkspaceSearchActions(input: {
  api: ReturnType<typeof useApi>;
  loading: Ref<boolean>;
  query: Ref<string>;
  results: Ref<WorkspaceSearchResult[]>;
  suggesting: Ref<boolean>;
  suggestions: Ref<WorkspaceSearchSuggestion[]>;
  t: ReturnType<typeof useI18n>["t"];
}) {
  let autocompleteTimer: ReturnType<typeof setTimeout> | undefined;

  const search = async (nextQuery = input.query.value): Promise<void> => {
    const trimmed = nextQuery.trim();
    input.query.value = trimmed;
    if (trimmed.length < AUTOCOMPLETE_MIN_PREFIX) {
      input.results.value = [];
      return;
    }
    await withLoadingState(input.loading, async () => {
      const { data, error } = await input.api.search.get({ query: { q: trimmed } });
      assertApiResponse(error, input.t("workspaceSearch.searchFailed"));
      input.results.value = mapSearchResults(data);
    });
  };

  const fetchAutocomplete = async (prefix = input.query.value): Promise<void> => {
    const trimmed = prefix.trim();
    if (trimmed.length < AUTOCOMPLETE_MIN_PREFIX) {
      input.suggestions.value = [];
      return;
    }
    input.suggesting.value = true;
    const settled = await settle(input.api.search.autocomplete.get({ query: { prefix: trimmed } }));
    input.suggesting.value = false;
    if (settled.status !== "fulfilled") {
      return;
    }
    const { data, error } = settled.value;
    assertApiResponse(error, input.t("workspaceSearch.autocompleteFailed"));
    input.suggestions.value = mapSuggestions(data);
  };

  const scheduleAutocomplete = (prefix = input.query.value): void => {
    if (autocompleteTimer) {
      clearTimeout(autocompleteTimer);
    }
    autocompleteTimer = setTimeout(() => {
      settle(fetchAutocomplete(prefix)).then(
        () => undefined,
        () => undefined,
      );
    }, AUTOCOMPLETE_DEBOUNCE_MS);
  };

  const applySuggestion = async (suggestion: WorkspaceSearchSuggestion): Promise<void> => {
    input.query.value = suggestion.text;
    input.suggestions.value = [];
    await search(suggestion.text);
  };

  const clear = (): void => {
    if (autocompleteTimer) {
      clearTimeout(autocompleteTimer);
      autocompleteTimer = undefined;
    }
    input.query.value = "";
    input.results.value = [];
    input.suggestions.value = [];
  };

  return {
    applySuggestion,
    clear,
    scheduleAutocomplete,
    search,
  };
}

export function useWorkspaceSearch() {
  const api = useApi();
  const { t } = useI18n();
  const query = ref("");
  const results = ref<WorkspaceSearchResult[]>([]);
  const suggestions = ref<WorkspaceSearchSuggestion[]>([]);
  const loading = ref(false);
  const suggesting = ref(false);
  const open = ref(false);
  const actions = createWorkspaceSearchActions({
    api,
    loading,
    query,
    results,
    suggesting,
    suggestions,
    t,
  });

  return {
    applySuggestion: actions.applySuggestion,
    clear: actions.clear,
    loading: readonly(loading),
    open,
    query,
    results: readonly(results),
    scheduleAutocomplete: actions.scheduleAutocomplete,
    suggesting: readonly(suggesting),
    suggestions: readonly(suggestions),
    search: actions.search,
  };
}

import { APP_ROUTES } from "@bao/shared/constants/routes";
import { settle } from "@bao/shared/utils/promise";
import { onMounted, onUnmounted, ref, useRoute, useRouter } from "#imports";
import type { NavigationItem } from "~/constants/navigation";
import { createClientLogger } from "~/utils/client-logger";

/**
 * Route shortcut metadata rendered in sidebar and handled globally.
 */
export interface KeyboardRouteShortcut {
  /** Navigation item id. */
  readonly id: NavigationItem["id"];
  /** Prefix key pressed first. */
  readonly prefix: "g";
  /** Route key pressed after the prefix key. */
  readonly key: string;
  /** Route destination path. */
  readonly to: string;
}

/**
 * Canonical keyboard shortcuts for route navigation.
 */
export const KEYBOARD_ROUTE_SHORTCUTS: readonly KeyboardRouteShortcut[] = [
  { id: "dashboard", prefix: "g", key: "d", to: APP_ROUTES.dashboard },
  { id: "jobs", prefix: "g", key: "j", to: APP_ROUTES.jobs },
  { id: "resume", prefix: "g", key: "r", to: APP_ROUTES.resume },
  { id: "interview", prefix: "g", key: "i", to: APP_ROUTES.interview },
  { id: "apiDocs", prefix: "g", key: "a", to: APP_ROUTES.apiDocs },
  { id: "settings", prefix: "g", key: "s", to: APP_ROUTES.settings },
] as const;

const SHORTCUT_PREFIX_TIMEOUT_MS = 900;

function isEditableTarget(target: EventTarget | null): boolean {
  return (
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    (target instanceof HTMLElement && target.isContentEditable)
  );
}

const shortcutLogger = createClientLogger("keyboard-shortcuts");

async function pushShortcutRoute(
  router: ReturnType<typeof useRouter>,
  targetRoute: string,
): Promise<void> {
  const navigationResult = await settle(router.push(targetRoute));
  if (navigationResult.status === "rejected") {
    shortcutLogger.debug("Shortcut navigation failed (duplicate or guard)", {
      targetRoute,
      err:
        navigationResult.reason instanceof Error
          ? navigationResult.reason.message
          : String(navigationResult.reason),
    });
  }
}

function isFocusChatShortcut(event: KeyboardEvent): boolean {
  return (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k";
}

function hasBlockedModifier(event: KeyboardEvent): boolean {
  return event.altKey || event.ctrlKey || event.metaKey;
}

function createKeyDownHandler(input: {
  route: ReturnType<typeof useRoute>;
  router: ReturnType<typeof useRouter>;
  routeBySuffixKey: ReadonlyMap<string, string>;
  pendingPrefix: ReturnType<typeof ref<KeyboardRouteShortcut["prefix"] | null>>;
  resetPrefix: () => void;
  armPrefix: () => void;
  focusChatShortcut: () => void;
}): (event: KeyboardEvent) => void {
  return (event: KeyboardEvent): void => {
    if (isFocusChatShortcut(event)) {
      event.preventDefault();
      input.focusChatShortcut();
      return;
    }

    if (isEditableTarget(event.target) || hasBlockedModifier(event)) {
      return;
    }

    const key = event.key.toLowerCase();
    if (input.pendingPrefix.value === "g") {
      const targetRoute = input.routeBySuffixKey.get(key);
      input.resetPrefix();
      if (targetRoute && input.route.path !== targetRoute) {
        event.preventDefault();
        pushShortcutRoute(input.router, targetRoute).then(undefined, () => undefined);
      }
      return;
    }

    if (key === "g") {
      input.armPrefix();
    }
  };
}

/**
 * Registers global keyboard shortcuts for power-user navigation.
 */
export function useKeyboardShortcuts() {
  const router = useRouter();
  const route = useRoute();
  const pendingPrefix = ref<KeyboardRouteShortcut["prefix"] | null>(null);
  let prefixTimer: ReturnType<typeof setTimeout> | null = null;
  const routeBySuffixKey = new Map(
    KEYBOARD_ROUTE_SHORTCUTS.map((shortcut) => [shortcut.key, shortcut.to]),
  );

  const resetPrefix = (): void => {
    pendingPrefix.value = null;
    if (prefixTimer) {
      clearTimeout(prefixTimer);
      prefixTimer = null;
    }
  };
  const armPrefix = (): void => {
    pendingPrefix.value = "g";
    if (prefixTimer) {
      clearTimeout(prefixTimer);
    }
    prefixTimer = setTimeout(resetPrefix, SHORTCUT_PREFIX_TIMEOUT_MS);
  };
  const focusChatShortcut = (): void => {
    window.dispatchEvent(new CustomEvent("bao:focus-chat"));
  };

  const onKeyDown = createKeyDownHandler({
    route,
    router,
    routeBySuffixKey,
    pendingPrefix,
    resetPrefix,
    armPrefix,
    focusChatShortcut,
  });

  onMounted(() => {
    window.addEventListener("keydown", onKeyDown);
  });
  onUnmounted(() => {
    window.removeEventListener("keydown", onKeyDown);
    resetPrefix();
  });
}

