function isSpeechRecognitionEvent(event: Event): event is SpeechRecognitionEvent {
  return "resultIndex" in event && "results" in event;
}

function isSpeechRecognitionErrorEvent(event: Event): event is SpeechRecognitionErrorEvent {
  return "error" in event;
}

function processRecognitionResults(event: SpeechRecognitionEvent): RecognitionUpdate {
  let finalTranscript = "";
  let currentInterimTranscript = "";
  let currentConfidence = 0;

  for (let index = event.resultIndex; index < event.results.length; index += 1) {
    const result = event.results[index];
    const firstAlternative = result?.[0];
    if (!firstAlternative) {
      continue;
    }
    if (result.isFinal) {
      finalTranscript += firstAlternative.transcript;
      currentConfidence = Math.max(currentConfidence, firstAlternative.confidence ?? 0);
      continue;
    }
    currentInterimTranscript += firstAlternative.transcript;
  }

  return {
    finalTranscript,
    interimTranscript: currentInterimTranscript,
    confidence: currentConfidence,
  };
}

function createRecognitionInstance(
  settings?: Ref<VoiceSettings | undefined>,
): SpeechRecognition | null {
  const speechRecognitionCtor = resolveSpeechRecognitionConstructor();
  if (!speechRecognitionCtor) {
    return null;
  }

  const recognition = new speechRecognitionCtor();
  recognition.continuous = true;
  recognition.interimResults = true;
  recognition.lang = resolveSpeechLocale(settings?.value?.language);
  return recognition;
}

function toFullTranscript(transcript: string, interimTranscript: string): string {
  const combined = transcript + (interimTranscript ? ` ${interimTranscript}` : "");
  return combined.trim();
}

function bindBrowserRecognitionHandlers(state: SttMutableState): void {
  const recognition = state.recognition;
  if (!recognition) {
    return;
  }
  recognition.addEventListener("result", (event: Event) => {
    if (!isSpeechRecognitionEvent(event)) {
      return;
    }
    const update = processRecognitionResults(event);
    if (update.finalTranscript.length > 0) {
      state.transcript.value += update.finalTranscript;
    }
    state.interimTranscript.value = update.interimTranscript;
    if (update.confidence > 0) {
      state.confidence.value = update.confidence;
    }
  });
  recognition.addEventListener("error", (event: Event) => {
    if (!isSpeechRecognitionErrorEvent(event)) {
      return;
    }
    state.error.value = `${event.error}: ${event.message ?? ""}`;
  });
  recognition.addEventListener("end", () => {
    state.isListening.value = false;
  });
}

function startServerSttListening(state: SttMutableState): boolean {
  if (state.isListening.value) {
    return true;
  }
  const micPromise = createMicrophoneRecorder()
    .then(
      (created) => {
        state.recorder = created;
        created.start();
        state.isListening.value = true;
      },
      () => {
        state.error.value = AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.audioCapture];
        state.isListening.value = false;
      },
    )
    .then(
      () => undefined,
      (error: Error) => {
        state.error.value = error instanceof Error ? error.message : AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.startFailed];
      },
    );
  state.micPromise = micPromise;
  return true;
}

function startBrowserSttListening(
  state: SttMutableState,
  locale: string | undefined,
  settings?: Ref<VoiceSettings | undefined>,
): boolean {
  if (!state.recognition) {
    state.error.value = AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.unsupportedRecognition];
    return false;
  }
  if (state.isListening.value) {
    return true;
  }
  state.recognition.lang = resolveSpeechLocale(locale ?? settings?.value?.language);
  state.recognition.start();
  state.isListening.value = true;
  return true;
}

function startSttListening(
  state: SttMutableState,
  locale: string | undefined,
  settings: Ref<VoiceSettings | undefined> | undefined,
  provider: ReturnType<typeof resolveSpeechSttProvider>,
): boolean {
  state.error.value = null;
  state.transcript.value = "";
  state.interimTranscript.value = "";
  state.confidence.value = 0;
  state.useServerStt = shouldUseServerStt(provider);
  if (state.useServerStt) {
    return startServerSttListening(state);
  }
  return startBrowserSttListening(state, locale, settings);
}

function stopServerSttListening(
  state: SttMutableState,
  options: ServerSttRequestOptions,
): void {
  const activeRecorder = state.recorder;
  state.recorder = null;
  if (!activeRecorder) {
    state.isListening.value = false;
    return;
  }
  const micPromise = activeRecorder
    .stop()
    .then((blob) => transcribeAudioViaServer(blob, options))
    .then(
      (result) => {
        if (result.ok) {
          state.transcript.value = result.text;
          state.interimTranscript.value = "";
          state.confidence.value = 1;
        } else {
          state.error.value = result.error;
        }
      },
      () => {
        state.error.value = AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.network];
      },
    )
    .then(() => {
      state.isListening.value = false;
    })
    .then(
      () => undefined,
      (error: Error) => {
        state.error.value = error instanceof Error ? error.message : AI_CHAT_VOICE_ERROR_MESSAGE_KEYS[AI_CHAT_VOICE_ERROR_CODES.network];
      },
    );
  state.micPromise = micPromise;
}

function stopSttListening(state: SttMutableState, options: ServerSttRequestOptions): void {
  if (state.useServerStt) {
    stopServerSttListening(state, options);
    return;
  }
  state.recognition?.stop();
  state.isListening.value = false;
}

/**
 * Speech-to-text composable.
 * Uses Whisper/server STT when automationSettings.speech.stt.provider is not browser;
 * otherwise falls back to Web Speech API.
 */
export function useSTT(settings?: Ref<VoiceSettings | undefined>) {
  const { settings: appSettings } = useSettings();
  const state: SttMutableState = {
    transcript: ref(""),
    interimTranscript: ref(""),
    isListening: ref(false),
    confidence: ref(0),
    error: ref<string | null>(null),
    recognition: null,
    recorder: null,
    useServerStt: false,
    micPromise: null,
  };

  const sttProvider = computed(() =>
    resolveSpeechSttProvider(appSettings.value?.automationSettings?.speech?.stt?.provider),
  );
  const getServerSttOptions = (): ServerSttRequestOptions => {
    const stt = appSettings.value?.automationSettings?.speech?.stt;
    return {
      provider: resolveSpeechSttProvider(stt?.provider),
      model: stt?.model?.trim() || "",
      endpoint: stt?.endpoint?.trim() || "",
    };
  };

  onMounted(() => {
    state.useServerStt = shouldUseServerStt(sttProvider.value);
    if (state.useServerStt) {
      return;
    }
    state.recognition = createRecognitionInstance(settings);
    bindBrowserRecognitionHandlers(state);
  });

  onUnmounted(() => {
    if (state.recognition) {
      state.recognition.stop();
      state.recognition = null;
    }
    state.recorder = null;
    state.isListening.value = false;
  });

  const fullTranscript = computed(() =>
    toFullTranscript(state.transcript.value, state.interimTranscript.value),
  );
  const isSupported = computed(
    () =>
      shouldUseServerStt(sttProvider.value) ||
      resolveSpeechRecognitionConstructor() !== null ||
      typeof navigator !== "undefined",
  );

  return {
    startListening: (locale?: string) =>
      startSttListening(state, locale, settings, sttProvider.value),
    stopListening: () => stopSttListening(state, getServerSttOptions()),
    transcript: readonly(state.transcript),
    interimTranscript: readonly(state.interimTranscript),
    fullTranscript,
    isListening: readonly(state.isListening),
    confidence: readonly(state.confidence),
    error: readonly(state.error),
    isSupported: readonly(isSupported),
  };
}

import { getGamificationPathwayIcon } from "@bao/shared/constants/gamification-icons";
import type {
  CareerPathway,
  ReadinessAssessment,
  SkillReadinessFeedbackId,
} from "@bao/shared/types/skill-mapping";
import {
  READINESS_CATEGORY_KEYS,
  READINESS_CATEGORY_LABEL_KEYS,
  type ReadinessCategoryKey,
  type ReadinessCategoryStat,
  type ReadinessImprovementItem,
  type ReadinessNextStepItem,
} from "~/composables/skills-pathways-page-contracts";
import {
  SKILLS_READINESS_THRESHOLD_HIGH,
  SKILLS_READINESS_THRESHOLD_MEDIUM,
} from "~/constants/skills";
import { PROGRESS_BAR_VARIANT_CLASS } from "~/constants/layout-tokens";
import { BADGE_VARIANT_CLASS } from "~/constants/layout-badges";

interface SkillsPathwaysPresentationOptions {
  readonly t: (key: string, params?: Record<string, string | number>) => string;
}

const getReadinessColor = (percentage: number): string => {
  if (percentage >= SKILLS_READINESS_THRESHOLD_HIGH) return PROGRESS_BAR_VARIANT_CLASS.success;
  if (percentage >= SKILLS_READINESS_THRESHOLD_MEDIUM) return PROGRESS_BAR_VARIANT_CLASS.warning;
  return PROGRESS_BAR_VARIANT_CLASS.error;
};

const getReadinessBadgeColor = (percentage: number): string => {
  if (percentage >= SKILLS_READINESS_THRESHOLD_HIGH) return BADGE_VARIANT_CLASS.success;
  if (percentage >= SKILLS_READINESS_THRESHOLD_MEDIUM) return BADGE_VARIANT_CLASS.warning;
  return BADGE_VARIANT_CLASS.error;
};

const sortPathways = (pathways: readonly CareerPathway[]): readonly CareerPathway[] =>
  [...pathways].sort((left, right) => right.matchScore - left.matchScore);

const createReadinessCategories = (
  readinessAssessment: ReadinessAssessment | null,
): readonly ReadinessCategoryStat[] => {
  if (!readinessAssessment) {
    return [];
  }

  return READINESS_CATEGORY_KEYS.map((key) => ({
    key,
    score: readinessAssessment.categories[key].score,
    feedbackId: readinessAssessment.categories[key].feedbackId,
  }));
};

const createSkillsPathwaysCopy = (t: SkillsPathwaysPresentationOptions["t"]) => {
  const getCategoryLabel = (key: ReadinessCategoryKey): string =>
    t(READINESS_CATEGORY_LABEL_KEYS[key]);
  const getCategoryFeedbackLabel = (
    categoryKey: ReadinessCategoryKey,
    feedbackId: SkillReadinessFeedbackId,
  ): string =>
    t(`skillsPathwaysPage.readiness.feedback.${feedbackId}`, {
      category: getCategoryLabel(categoryKey),
    });

  const getReadinessImprovementLabel = (item: ReadinessImprovementItem): string =>
    t(`skillsPathwaysPage.readiness.improvements.${item}`);

  const getReadinessNextStepLabel = (item: ReadinessNextStepItem): string =>
    t(`skillsPathwaysPage.readiness.nextStepItems.${item}`);

  const getPathwayIcon = (pathwayId: string): string => getGamificationPathwayIcon(pathwayId);
  return {
    getCategoryFeedbackLabel,
    getCategoryLabel,
    getPathwayIcon,
    getReadinessImprovementLabel,
    getReadinessNextStepLabel,
  };
};

export const createSkillsPathwaysPresentation = ({ t }: SkillsPathwaysPresentationOptions) => {
  const copy = createSkillsPathwaysCopy(t);

  return {
    createReadinessCategories,
    getCategoryFeedbackLabel: copy.getCategoryFeedbackLabel,
    getCategoryLabel: copy.getCategoryLabel,
    getPathwayIcon: copy.getPathwayIcon,
    getReadinessBadgeColor,
    getReadinessColor,
    getReadinessImprovementLabel: copy.getReadinessImprovementLabel,
    getReadinessNextStepLabel: copy.getReadinessNextStepLabel,
    sortPathways,
  };
};

import { APP_ROUTE_BUILDERS } from "@bao/shared/constants/routes";
import type { RpaRunExecutionEnvelope } from "@bao/shared/schemas/rpa-events.schema";
import type { useI18n } from "vue-i18n";
import { settlePromise } from "~/composables/async-flow";
import {
  buildJobApplyBody,
  type ScheduledJobApplyRequestBody,
  useAutomationJobApplyBootstrap,
  useAutomationJobApplyDependencies,
  useAutomationJobApplyForm,
} from "~/composables/automation-job-apply-page-form";
import {
  DATE_FORMAT_OPTIONS,
  resolveScheduledRunAt,
  toIsoTimestamp,
} from "~/composables/schedule-timestamp";
import type { useAutomationRunStream } from "~/composables/useAutomationRunStream";
import { getErrorMessage } from "~/utils/errors";
import { formatDateWithLocale } from "~/utils/locale-format";

function createAutomationJobApplyState(runStream: ReturnType<typeof useAutomationRunStream>) {
  const pending = ref(false);
  const submitError = ref("");
  const startedRunId = ref("");
  const scheduledRun = ref<RpaRunExecutionEnvelope | null>(null);
  const streamRun = computed(() => runStream.run.value);
  const streamState = computed(() => runStream.state.value);
  const streamEvents = computed(() => runStream.events.value);
  const streamError = computed(() => runStream.streamError.value);
  const activeRunId = computed<string>(() => streamRun.value?.id ?? startedRunId.value);
  const hasActiveRun = computed<boolean>(() => activeRunId.value.length > 0);

  return {
    activeRunId,
    hasActiveRun,
    pending,
    scheduledRun,
    startedRunId,
    streamError,
    streamEvents,
    streamRun,
    streamState,
    submitError,
  };
}

function createAutomationJobApplyPresentation(input: {
  fallbackLocale: Ref<unknown> | ComputedRef<unknown>;
  form: ReturnType<typeof useAutomationJobApplyForm>;
  locale: Ref<unknown> | ComputedRef<unknown>;
  state: ReturnType<typeof createAutomationJobApplyState>;
}) {
  const isSubmitDisabled = computed(
    () => input.state.pending.value || !input.form.jobUrl.value || !input.form.resumeId.value,
  );
  const isScheduleDisabled = computed(() => isSubmitDisabled.value || !input.form.runAt.value);

  const toLocalizedDateTime = (value: string): string => {
    const formatted = formatDateWithLocale(
      value,
      input.locale.value,
      input.fallbackLocale.value,
      DATE_FORMAT_OPTIONS,
    );
    return formatted ?? value;
  };

  return {
    isScheduleDisabled,
    isSubmitDisabled,
    toLocalizedDateTime,
  };
}

function createAutomationJobApplyActions(input: {
  form: ReturnType<typeof useAutomationJobApplyForm>;
  runStream: ReturnType<typeof useAutomationRunStream>;
  scheduleJobApply: ReturnType<typeof useAutomation>["scheduleJobApply"];
  state: ReturnType<typeof createAutomationJobApplyState>;
  t: ReturnType<typeof useI18n>["t"];
  triggerJobApply: ReturnType<typeof useAutomation>["triggerJobApply"];
}) {
  async function startRunStream(runId: string) {
    const streamStartResult = await settlePromise(
      input.runStream.start(runId),
      input.t("automation.jobApply.stream.startErrorFallback"),
    );
    if (!streamStartResult.ok) {
      input.state.submitError.value = getErrorMessage(
        streamStartResult.error,
        input.t("automation.jobApply.stream.startErrorFallback"),
      );
    }
  }

  function resetSubmissionState() {
    input.state.submitError.value = "";
    input.state.startedRunId.value = "";
    input.state.scheduledRun.value = null;
  }

  const runNowActions = createAutomationImmediateJobApplyAction({
    form: input.form,
    resetSubmissionState,
    startRunStream,
    state: input.state,
    t: input.t,
    triggerJobApply: input.triggerJobApply,
  });
  const scheduledActions = createAutomationScheduledJobApplyAction({
    form: input.form,
    resetSubmissionState,
    runStream: input.runStream,
    scheduleJobApply: input.scheduleJobApply,
    state: input.state,
    t: input.t,
  });

  return {
    submitJobApply: runNowActions.submitJobApply,
    submitScheduledJobApply: scheduledActions.submitScheduledJobApply,
  };
}

function createAutomationImmediateJobApplyAction(input: {
  form: ReturnType<typeof useAutomationJobApplyForm>;
  resetSubmissionState: () => void;
  startRunStream: (runId: string) => Promise<void>;
  state: ReturnType<typeof createAutomationJobApplyState>;
  t: ReturnType<typeof useI18n>["t"];
  triggerJobApply: ReturnType<typeof useAutomation>["triggerJobApply"];
}) {
  async function submitJobApply(): Promise<void> {
    input.resetSubmissionState();
    input.state.pending.value = true;

    const submitResult = await settlePromise(
      input.triggerJobApply(buildJobApplyBody(input.form)),
      input.t("automation.jobApply.submitErrorFallback"),
    );
    input.state.pending.value = false;

    if (!submitResult.ok) {
      input.state.submitError.value = getErrorMessage(
        submitResult.error,
        input.t("automation.jobApply.submitErrorFallback"),
      );
      return;
    }

    const startedRun = submitResult.value;
    input.state.startedRunId.value = startedRun.id;
    await input.startRunStream(startedRun.id);
  }

  return {
    submitJobApply,
  };
}

function createAutomationScheduledJobApplyAction(input: {
  form: ReturnType<typeof useAutomationJobApplyForm>;
  resetSubmissionState: () => void;
  runStream: ReturnType<typeof useAutomationRunStream>;
  scheduleJobApply: ReturnType<typeof useAutomation>["scheduleJobApply"];
  state: ReturnType<typeof createAutomationJobApplyState>;
  t: ReturnType<typeof useI18n>["t"];
}) {
  async function submitScheduledJobApply(): Promise<void> {
    input.resetSubmissionState();
    input.runStream.cancel();
    input.state.pending.value = true;

    const runAt = toIsoTimestamp(input.form.runAt.value);
    if (!runAt) {
      input.state.submitError.value = input.t("automation.jobApply.schedule.invalidRunAt");
      input.state.pending.value = false;
      return;
    }

    const body: ScheduledJobApplyRequestBody = {
      ...buildJobApplyBody(input.form),
      runAt,
    };

    const scheduledResult = await settlePromise(
      input.scheduleJobApply(body),
      input.t("automation.jobApply.submitErrorFallback"),
    );
    input.state.pending.value = false;

    if (!scheduledResult.ok) {
      input.state.submitError.value = getErrorMessage(
        scheduledResult.error,
        input.t("automation.jobApply.submitErrorFallback"),
      );
      return;
    }

    input.state.scheduledRun.value = scheduledResult.value;
  }

  return {
    submitScheduledJobApply,
  };
}

function registerAutomationJobApplyResumePrefill(input: {
  bootstrap: ReturnType<typeof useAutomationJobApplyBootstrap>;
  dependencies: ReturnType<typeof useAutomationJobApplyDependencies>;
  form: ReturnType<typeof useAutomationJobApplyForm>;
}): void {
  watch(
    input.bootstrap.resumesData,
    async (resumes) => {
      if (input.form.resumeId.value || !resumes || resumes.length === 0) {
        return;
      }
      const context = await input.dependencies.getVerifyContext();
      if (!context) {
        return;
      }
      if (resumes.some((resume) => resume.id === context.resumeId)) {
        input.form.resumeId.value = context.resumeId;
      }
    },
    { immediate: true },
  );
}

export function useAutomationJobApplyPage() {
  const dependencies = useAutomationJobApplyDependencies();
  const form = useAutomationJobApplyForm();
  const bootstrap = useAutomationJobApplyBootstrap({
    api: dependencies.api,
    t: dependencies.t,
  });
  const state = createAutomationJobApplyState(dependencies.runStream);
  const presentation = createAutomationJobApplyPresentation({
    fallbackLocale: dependencies.fallbackLocale,
    form,
    locale: dependencies.locale,
    state,
  });
  const actions = createAutomationJobApplyActions({
    form,
    runStream: dependencies.runStream,
    scheduleJobApply: dependencies.scheduleJobApply,
    state,
    t: dependencies.t,
    triggerJobApply: dependencies.triggerJobApply,
  });

  registerAutomationJobApplyResumePrefill({ bootstrap, dependencies, form });

  return {
    activeRunId: state.activeRunId,
    bootstrapError: bootstrap.bootstrapError,
    bootstrapPending: bootstrap.bootstrapPending,
    coverLetterId: form.coverLetterId,
    coverLettersData: bootstrap.coverLettersData,
    hasActiveRun: state.hasActiveRun,
    isScheduleDisabled: presentation.isScheduleDisabled,
    isSubmitDisabled: presentation.isSubmitDisabled,
    jobId: form.jobId,
    jobUrl: form.jobUrl,
    pending: state.pending,
    refreshBootstrap: bootstrap.refreshBootstrap,
    resolveScheduledRunAt,
    resumeId: form.resumeId,
    resumesData: bootstrap.resumesData,
    runAt: form.runAt,
    runDetailRoute: (id: string) => APP_ROUTE_BUILDERS.automationRunDetail(id),
    runStream: dependencies.runStream,
    scheduledRun: state.scheduledRun,
    startedRunId: state.startedRunId,
    streamError: state.streamError,
    streamEvents: state.streamEvents,
    streamRun: state.streamRun,
    streamState: state.streamState,
    submitError: state.submitError,
    submitJobApply: actions.submitJobApply,
    submitScheduledJobApply: actions.submitScheduledJobApply,
    toLocalizedDateTime: presentation.toLocalizedDateTime,
  };
}

import type { AIProviderType } from "@bao/shared/types/ai";
import { createAIDashboardActions } from "~/composables/ai-dashboard-actions";
