import type { ComputedRef, Ref, WatchSource } from "vue";
import { computed, ref, watch } from "vue";

const FIRST_PAGE = 1;
const MIN_PAGE_SIZE = 1;

function clampToRange(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

interface PaginationComputeds<T> {
  totalItems: ComputedRef<number>;
  totalPages: ComputedRef<number>;
  pageNumbers: ComputedRef<readonly number[]>;
  itemsForCurrentPage: ComputedRef<readonly T[]>;
  rangeStart: ComputedRef<number>;
  rangeEnd: ComputedRef<number>;
  hasMultiplePages: ComputedRef<boolean>;
}

function createPaginationComputeds<T>(
  items: ComputedRef<readonly T[]>,
  currentPage: Ref<number>,
  normalizedPageSize: number,
): PaginationComputeds<T> {
  const totalItems = computed(() => items.value.length);
  const totalPages = computed(() =>
    totalItems.value === 0 ? FIRST_PAGE : Math.ceil(totalItems.value / normalizedPageSize),
  );
  const pageNumbers = computed(() => {
    const length = totalPages.value;
    const pages: number[] = [];
    for (let pageNumber = FIRST_PAGE; pageNumber <= length; pageNumber += 1) {
      pages.push(pageNumber);
    }
    return pages;
  });
  const itemsForCurrentPage = computed(() => {
    const startIndex = (currentPage.value - FIRST_PAGE) * normalizedPageSize;
    return items.value.slice(startIndex, startIndex + normalizedPageSize);
  });
  const rangeStart = computed(() =>
    totalItems.value === 0 ? 0 : (currentPage.value - FIRST_PAGE) * normalizedPageSize + FIRST_PAGE,
  );
  const rangeEnd = computed(() =>
    totalItems.value === 0
      ? 0
      : Math.min(totalItems.value, rangeStart.value + normalizedPageSize - FIRST_PAGE),
  );

  return {
    totalItems,
    totalPages,
    pageNumbers,
    itemsForCurrentPage,
    rangeStart,
    rangeEnd,
    hasMultiplePages: computed(() => totalPages.value > FIRST_PAGE),
  };
}

function registerPaginationWatchers(
  currentPage: Ref<number>,
  totalPages: ComputedRef<number>,
  resetSources: readonly WatchSource[],
): void {
  watch(totalPages, (nextTotalPages) => {
    if (currentPage.value > nextTotalPages) {
      currentPage.value = nextTotalPages;
    }
  });

  if (resetSources.length > 0) {
    watch([...resetSources], () => {
      currentPage.value = FIRST_PAGE;
    });
  }
}

/**
 * Reactive pagination state derived from a computed item collection.
 */
export interface PaginationState<T> {
  currentPage: Ref<number>;
  totalPages: ComputedRef<number>;
  pageNumbers: ComputedRef<readonly number[]>;
  totalItems: ComputedRef<number>;
  rangeStart: ComputedRef<number>;
  rangeEnd: ComputedRef<number>;
  hasMultiplePages: ComputedRef<boolean>;
  items: ComputedRef<readonly T[]>;
  goToPage: (page: number) => void;
  goToPreviousPage: () => void;
  goToNextPage: () => void;
}

/**
 * Build deterministic pagination state for a computed list.
 *
 * @param items Reactive list source.
 * @param pageSize Number of items per page.
 * @param resetSources Reactive sources that reset to page 1 when changed.
 * @returns Reactive pagination values and navigation helpers.
 */
export function usePagination<T>(
  items: ComputedRef<readonly T[]>,
  pageSize: number,
  resetSources: readonly WatchSource[] = [],
): PaginationState<T> {
  const normalizedPageSize = Math.max(MIN_PAGE_SIZE, Math.trunc(pageSize));
  const currentPage = ref(FIRST_PAGE);
  const computedState = createPaginationComputeds(items, currentPage, normalizedPageSize);

  const goToPage = (page: number): void => {
    currentPage.value = clampToRange(page, FIRST_PAGE, computedState.totalPages.value);
  };
  const goToPreviousPage = (): void => {
    goToPage(currentPage.value - FIRST_PAGE);
  };
  const goToNextPage = (): void => {
    goToPage(currentPage.value + FIRST_PAGE);
  };

  registerPaginationWatchers(currentPage, computedState.totalPages, resetSources);

  return {
    currentPage,
    totalPages: computedState.totalPages,
    pageNumbers: computedState.pageNumbers,
    totalItems: computedState.totalItems,
    rangeStart: computedState.rangeStart,
    rangeEnd: computedState.rangeEnd,
    hasMultiplePages: computedState.hasMultiplePages,
    items: computedState.itemsForCurrentPage,
    goToPage,
    goToPreviousPage,
    goToNextPage,
  };
}

import { API_ENDPOINTS } from "@bao/shared/constants/endpoints";
import { STATE_KEYS } from "@bao/shared/constants/state-keys";
import type {
  PortfolioData,
  PortfolioMetadata,
  PortfolioProject,
} from "@bao/shared/types/portfolio";
import { useI18n } from "vue-i18n";
import { toPortfolioData } from "./api-normalizer-portfolio";
import {
  type ClientApiRequestRuntime,
  downloadApiFile,
  useClientApiRequestRuntime,
} from "./api-request";
import { assertApiResponse, withLoadingState } from "./async-flow";
import { readRequiredApiPayload } from "~/utils/api-response";

type ApiClient = ReturnType<typeof useApi>;
type UpdatePortfolioPayload = NonNullable<Parameters<ApiClient["portfolio"]["put"]>[0]>;
type CreateProjectPayload = NonNullable<Parameters<ApiClient["portfolio"]["projects"]["post"]>[0]>;
type ProjectRoute = ReturnType<ApiClient["portfolio"]["projects"]>;
type UpdateProjectPayload = NonNullable<Parameters<ProjectRoute["put"]>[0]>;

interface PortfolioContext {
  api: ApiClient;
  t: ReturnType<typeof useI18n>["t"];
  loading: ReturnType<typeof useState<boolean>>;
  portfolio: ReturnType<typeof useState<PortfolioData | null>>;
  projects: ReturnType<typeof useState<PortfolioProject[]>>;
  runtime: ClientApiRequestRuntime;
}

function hydratePortfolio(context: PortfolioContext, next: PortfolioData | null): void {
  context.portfolio.value = next;
  context.projects.value = next && Array.isArray(next.projects) ? next.projects : [];
}

async function fetchPortfolio(context: PortfolioContext): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.portfolio.get(),
      context.t("apiErrors.portfolio.fetchFailed"),
    );
    hydratePortfolio(context, toPortfolioData(data));
  });
}

async function updatePortfolio(
  context: PortfolioContext,
  updates: Partial<PortfolioMetadata>,
): Promise<PortfolioData | null> {
  return withLoadingState(context.loading, async () => {
    const payload: UpdatePortfolioPayload = { metadata: updates };
    const data = await readRequiredApiPayload(
      context.api.portfolio.put(payload),
      context.t("apiErrors.portfolio.updateFailed"),
    );
    const normalized = toPortfolioData(data);
    hydratePortfolio(context, normalized);
    return normalized;
  });
}

async function addProject(
  context: PortfolioContext,
  projectData: CreateProjectPayload,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await readRequiredApiPayload(
      context.api.portfolio.projects.post(projectData),
      context.t("apiErrors.portfolio.addProjectFailed"),
    );
    await fetchPortfolio(context);
  });
}

async function updateProject(
  context: PortfolioContext,
  id: string,
  updates: UpdateProjectPayload,
): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await readRequiredApiPayload(
      context.api.portfolio.projects({ id }).put(updates),
      context.t("apiErrors.portfolio.updateProjectFailed"),
    );
    await fetchPortfolio(context);
  });
}

async function deleteProject(context: PortfolioContext, id: string): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const { error } = await context.api.portfolio.projects({ id }).delete();
    assertApiResponse(error, context.t("apiErrors.portfolio.deleteProjectFailed"));
    await fetchPortfolio(context);
  });
}

async function reorderProjects(context: PortfolioContext, orderedIds: string[]): Promise<void> {
  return withLoadingState(context.loading, async () => {
    const data = await readRequiredApiPayload(
      context.api.portfolio.projects.reorder.post({ orderedIds }),
      context.t("apiErrors.portfolio.reorderFailed"),
    );
    const normalized = toPortfolioData(data);
    hydratePortfolio(context, normalized);
  });
}

async function exportPortfolio(context: PortfolioContext, format?: string): Promise<void> {
  return withLoadingState(context.loading, async () => {
    await downloadApiFile(
      context.runtime,
      `${API_ENDPOINTS.portfolio}/export`,
      {
        method: "POST",
        body: format ? { format } : {},
      },
      `portfolio.${format === "docx" ? "docx" : "pdf"}`,
    );
  });
}

/**
 * Portfolio management composable.
 */
export function usePortfolio() {
  const context: PortfolioContext = {
    api: useApi(),
    t: useI18n().t,
    portfolio: useState<PortfolioData | null>(STATE_KEYS.PORTFOLIO_DATA, () => null),
    projects: useState<PortfolioProject[]>(STATE_KEYS.PORTFOLIO_PROJECTS, () => []),
    loading: useState(STATE_KEYS.PORTFOLIO_LOADING, () => false),
    runtime: useClientApiRequestRuntime(),
  };

  return {
    portfolio: readonly(context.portfolio),
    projects: readonly(context.projects),
    loading: readonly(context.loading),
    fetchPortfolio: () => fetchPortfolio(context),
    updatePortfolio: (updates: Partial<PortfolioMetadata>) => updatePortfolio(context, updates),
    addProject: (projectData: CreateProjectPayload) => addProject(context, projectData),
    updateProject: (id: string, updates: UpdateProjectPayload) =>
      updateProject(context, id, updates),
    deleteProject: (id: string) => deleteProject(context, id),
    reorderProjects: (orderedIds: string[]) => reorderProjects(context, orderedIds),
    exportPortfolio: (format?: string) => exportPortfolio(context, format),
  };
}

import type {
  InterviewCandidateContext,
  InterviewConfig,
  InterviewConversationStyle,
  InterviewMode,
  InterviewSession,
  InterviewTargetJob,
} from "@bao/shared/types/interview";
import { normalizeScrapePersonaEnrichment } from "@bao/shared/utils/scrape-enrichment";
import {
  asBoolean,
  asNumber,
  asString,
  asStringArray,
  isRecord,
} from "@bao/shared/utils/type-guards";
const NUM_30 = 30;

const INTERVIEW_STATUS_VALUES = [
  "preparing",
  "active",
  "paused",
  "completed",
  "cancelled",
] as const;

const INTERVIEW_QUESTION_TYPES = [
  "behavioral",
  "technical",
  "studio-specific",
  "intro",
  "closing",
] as const;

const INTERVIEW_QUESTION_DIFFICULTIES = ["easy", "medium", "hard"] as const;

type InterviewStatus = InterviewSession["status"];
type InterviewQuestionType = InterviewSession["questions"][number]["type"];
type InterviewQuestionDifficulty = InterviewSession["questions"][number]["difficulty"];

const isOneOf = <T extends string>(values: readonly T[], value: unknown): value is T =>
  typeof value === "string" && values.some((entry) => entry === value);

const asInterviewStatus = (value: unknown): InterviewStatus =>
  isOneOf(INTERVIEW_STATUS_VALUES, value) ? value : "active";

const asQuestionType = (value: unknown): InterviewQuestionType =>
  isOneOf(INTERVIEW_QUESTION_TYPES, value) ? value : "behavioral";

const asQuestionDifficulty = (value: unknown): InterviewQuestionDifficulty =>
  isOneOf(INTERVIEW_QUESTION_DIFFICULTIES, value) ? value : "medium";

const asInterviewMode = (value: unknown): InterviewMode => (value === "job" ? "job" : "studio");
const asInterviewConversationStyle = (value: unknown): InterviewConversationStyle =>
  value === "structured" ? "structured" : "natural";

const asInterviewTargetJob = (value: unknown): InterviewTargetJob | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const id = asString(value.id);
  const title = asString(value.title);
  const company = asString(value.company);
  const location = asString(value.location);
  if (!(id && title && company && location)) {
    return;
  }

  return {
    id,
    title,
    company,
    location,
    description: asString(value.description),
    requirements: asStringArray(value.requirements),
    technologies: asStringArray(value.technologies),
    source: asString(value.source),
    postedDate: asString(value.postedDate),
    url: asString(value.url),
    enrichment: normalizeScrapePersonaEnrichment(value.enrichment),
  };
};

const asInterviewCandidateContext = (value: unknown): InterviewCandidateContext | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const resumeId = asString(value.resumeId);
  const coverLetterId = asString(value.coverLetterId);
  const portfolioId = asString(value.portfolioId);
  if (!(resumeId || coverLetterId || portfolioId)) {
    return;
  }

  return {
    ...(resumeId ? { resumeId } : {}),
    ...(coverLetterId ? { coverLetterId } : {}),
    ...(portfolioId ? { portfolioId } : {}),
  };
};

const toInterviewQuestion = (value: unknown): InterviewSession["questions"][number] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const id = asString(value.id);
  const question = asString(value.question);
  if (!(id && question)) {
    return null;
  }

  const nextQuestion: InterviewSession["questions"][number] = {
    id,
    type: asQuestionType(value.type),
    question,
    followUps: asStringArray(value.followUps),
    expectedDuration: asNumber(value.expectedDuration) ?? 60,
    difficulty: asQuestionDifficulty(value.difficulty),
    tags: asStringArray(value.tags),
  };
  const score = asNumber(value.score);
  const feedback = asString(value.feedback);
  const response = asString(value.response);
  if (score !== undefined) {
    nextQuestion.score = score;
  }
  if (feedback !== undefined) {
    nextQuestion.feedback = feedback;
  }
  if (response !== undefined) {
    nextQuestion.response = response;
  }
  return nextQuestion;
};

const toInterviewQuestions = (value: unknown): InterviewSession["questions"] =>
  Array.isArray(value)
    ? value
        .map((entry) => toInterviewQuestion(entry))
        .filter((entry): entry is InterviewSession["questions"][number] => entry !== null)
    : [];

const toResponseAnalysis = (
  value: unknown,
): InterviewSession["responses"][number]["aiAnalysis"] | undefined => {
  if (!isRecord(value)) {
    return;
  }
  return {
    score: asNumber(value.score) ?? 0,
    feedback: asString(value.feedback) ?? "",
    strengths: asStringArray(value.strengths),
    improvements: asStringArray(value.improvements),
  };
};

const toInterviewResponse = (value: unknown): InterviewSession["responses"][number] | null => {
  if (!isRecord(value)) {
    return null;
  }

  const questionId = asString(value.questionId);
  const transcript = asString(value.transcript);
  if (!(questionId && transcript)) {
    return null;
  }

  const response: InterviewSession["responses"][number] = {
    questionId,
    transcript,
    duration: asNumber(value.duration) ?? 0,
    timestamp: asNumber(value.timestamp) ?? Date.now(),
    confidence: asNumber(value.confidence) ?? 0,
  };
  const analysis = toResponseAnalysis(value.aiAnalysis);
  if (analysis) {
    response.aiAnalysis = analysis;
  }
  return response;
};

const toInterviewResponses = (value: unknown): InterviewSession["responses"] =>
  Array.isArray(value)
    ? value
        .map((entry) => toInterviewResponse(entry))
        .filter((entry): entry is InterviewSession["responses"][number] => entry !== null)
    : [];

const toVoiceSettings = (value: unknown): InterviewConfig["voiceSettings"] | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const rate = asNumber(value.rate);
  const pitch = asNumber(value.pitch);
  const volume = asNumber(value.volume);
  const language = asString(value.language);
  if (rate === undefined || pitch === undefined || volume === undefined || !language) {
    return;
  }

  return {
    microphoneId: asString(value.microphoneId),
    speakerId: asString(value.speakerId),
    voiceId: asString(value.voiceId),
    rate,
    pitch,
    volume,
    language,
  };
};

const toInterviewConfig = (value: unknown, questionCount: number): InterviewSession["config"] => {
  const configRecord = isRecord(value) ? value : {};
  const config: InterviewSession["config"] = {
    roleType: asString(configRecord.roleType) ?? "Generalist",
    roleCategory: asString(configRecord.roleCategory),
    experienceLevel: asString(configRecord.experienceLevel) ?? "mid",
    focusAreas: asStringArray(configRecord.focusAreas),
    duration: asNumber(configRecord.duration) ?? NUM_30,
    questionCount: asNumber(configRecord.questionCount) ?? questionCount,
    includeTechnical: asBoolean(configRecord.includeTechnical) ?? true,
    includeBehavioral: asBoolean(configRecord.includeBehavioral) ?? true,
    includeStudioSpecific: asBoolean(configRecord.includeStudioSpecific) ?? true,
    enableVoiceMode: asBoolean(configRecord.enableVoiceMode),
    technologies: asStringArray(configRecord.technologies),
    interviewMode: asInterviewMode(configRecord.interviewMode),
    conversationStyle: asInterviewConversationStyle(configRecord.conversationStyle),
  };

  const voiceSettings = toVoiceSettings(configRecord.voiceSettings);
  if (voiceSettings) {
    config.voiceSettings = voiceSettings;
  }

  const targetJob = asInterviewTargetJob(configRecord.targetJob);
  if (targetJob) {
    config.targetJob = targetJob;
  }
  const candidateContext = asInterviewCandidateContext(configRecord.candidateContext);
  if (candidateContext) {
    config.candidateContext = candidateContext;
  }

  return config;
};

const toFinalAnalysis = (value: unknown): InterviewSession["finalAnalysis"] | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const feedback = asString(value.feedback);
  const analysis: NonNullable<InterviewSession["finalAnalysis"]> = {
    overallScore: asNumber(value.overallScore) ?? 0,
    strengths: asStringArray(value.strengths),
    improvements: asStringArray(value.improvements),
    recommendations: asStringArray(value.recommendations),
  };
  if (feedback !== undefined) {
    analysis.feedback = feedback;
  }
  return analysis;
};

const toInterviewerPersona = (
  value: unknown,
): InterviewSession["interviewerPersona"] | undefined => {
  if (!isRecord(value)) {
    return;
  }

  return {
    name: asString(value.name) ?? "",
    role: asString(value.role) ?? "",
    studioName: asString(value.studioName) ?? "",
    background: asString(value.background) ?? "",
    style: asString(value.style) ?? "",
    experience: asString(value.experience) ?? "",
  };
};

export const toInterviewSession = (value: unknown): InterviewSession | null => {
  if (!isRecord(value)) {
    return null;
  }

  const id = asString(value.id);
  const studioId = asString(value.studioId);
  if (!(id && studioId)) {
    return null;
  }

  const questions = toInterviewQuestions(value.questions);
  const session: InterviewSession = {
    id,
    studioId,
    config: toInterviewConfig(value.config, questions.length),
    questions,
    currentQuestionIndex: asNumber(value.currentQuestionIndex) ?? 0,
    totalQuestions: asNumber(value.totalQuestions) ?? questions.length,
    startTime: asNumber(value.startTime) ?? Date.now(),
    endTime: asNumber(value.endTime),
    status: asInterviewStatus(value.status),
    responses: toInterviewResponses(value.responses),
    role: asString(value.role),
    studioName: asString(value.studioName),
    score: asNumber(value.score),
    duration: asString(value.duration),
    overallFeedback: asString(value.overallFeedback),
    totalResponses: asNumber(value.totalResponses),
    createdAt: asString(value.createdAt),
    updatedAt: asString(value.updatedAt),
  };

  const finalAnalysis = toFinalAnalysis(value.finalAnalysis);
  if (finalAnalysis) {
    session.finalAnalysis = finalAnalysis;
  }

  const interviewerPersona = toInterviewerPersona(value.interviewerPersona);
  if (interviewerPersona) {
    session.interviewerPersona = interviewerPersona;
  }
  return session;
};

export const toInterviewSessions = (value: unknown): InterviewSession[] =>
  Array.isArray(value)
    ? value
        .map((entry) => toInterviewSession(entry))
        .filter((entry): entry is InterviewSession => entry !== null)
    : [];

export const toNumericRecord = (value: unknown): Record<string, number> | null => {
  if (!isRecord(value)) {
    return null;
  }
  const normalized: Record<string, number> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "number" && Number.isFinite(entry)) {
      normalized[key] = entry;
    }
  }
  return normalized;
};

import type { ComponentPublicInstance, Ref } from "vue";
import { computed, nextTick, onBeforeUnmount, watch } from "vue";
import { useScrollSpy } from "~/composables/useScrollSpy";
import type { ApiDocsUiState, ApiEndpointGroup } from "~/types/api-docs";

interface ApiDocsPageNavigationOptions {
  readonly route: { readonly hash: string };
  readonly docsUiState: Readonly<Ref<ApiDocsUiState>>;
  readonly endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>;
}

const createActiveEndpointId = (
  activeSectionId: Readonly<Ref<string | undefined>>,
  endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>,
) =>
  computed(() => {
    if (activeSectionId.value && activeSectionId.value.length > 0) {
      return activeSectionId.value;
    }
    const firstGroup = endpointGroups.value[0];
    return firstGroup?.endpoints[0]?.id ?? "";
  });

const syncScrollSpyFromHash = (
  routeHash: string,
  endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>,
  syncFromHash: (hash: string) => boolean,
  scrollToSection: ReturnType<typeof useScrollSpy>["scrollToSection"],
): void => {
  if (!syncFromHash(routeHash)) {
    const firstEndpointId = endpointGroups.value[0]?.endpoints[0]?.id;
    if (firstEndpointId) {
      scrollToSection(firstEndpointId, {
        smooth: false,
        focus: false,
        updateHash: false,
      });
    }
  }
};

const createScrollToEndpoint =
  (scrollToSection: ReturnType<typeof useScrollSpy>["scrollToSection"]) =>
  (sectionId: string): void => {
    scrollToSection(sectionId, {
      smooth: true,
      focus: true,
      updateHash: true,
    });
  };

const createEndpointSectionRegistrar =
  (setSectionRef: ReturnType<typeof useScrollSpy>["setSectionRef"]) =>
  (endpointId: string) =>
  (element: Element | ComponentPublicInstance | null) => {
    setSectionRef(endpointId, element instanceof Element ? element : null);
  };

const registerApiDocsNavigationEffects = (input: {
  readonly docsUiState: Readonly<Ref<ApiDocsUiState>>;
  readonly endpointGroups: Readonly<Ref<readonly ApiEndpointGroup[]>>;
  readonly route: { readonly hash: string };
  readonly syncFromHash: ReturnType<typeof useScrollSpy>["syncFromHash"];
  readonly startObserver: ReturnType<typeof useScrollSpy>["startObserver"];
  readonly refreshObserver: ReturnType<typeof useScrollSpy>["refreshObserver"];
  readonly stopObserver: ReturnType<typeof useScrollSpy>["stopObserver"];
  readonly scrollToSection: ReturnType<typeof useScrollSpy>["scrollToSection"];
}) => {
  watch(
    [input.docsUiState, input.endpointGroups],
    async ([stateValue]) => {
      if (stateValue !== "success") {
        input.stopObserver();
        return;
      }

      await nextTick();
      input.startObserver();
      input.refreshObserver();
      syncScrollSpyFromHash(
        input.route.hash,
        input.endpointGroups,
        input.syncFromHash,
        input.scrollToSection,
      );
    },
    { immediate: true },
  );

  watch(
    () => input.route.hash,
    (nextHash) => {
      if (input.docsUiState.value !== "success") {
        return;
      }
      input.syncFromHash(nextHash);
    },
  );

  onBeforeUnmount(() => {
    input.stopObserver();
  });
};

export const useApiDocsPageNavigation = ({
  route,
  docsUiState,
  endpointGroups,
}: ApiDocsPageNavigationOptions) => {
  const scrollSpy = useScrollSpy();
  registerApiDocsNavigationEffects({
    docsUiState,
    endpointGroups,
    route,
    syncFromHash: scrollSpy.syncFromHash,
    startObserver: scrollSpy.startObserver,
    refreshObserver: scrollSpy.refreshObserver,
    stopObserver: scrollSpy.stopObserver,
    scrollToSection: scrollSpy.scrollToSection,
  });

  return {
    activeEndpointId: createActiveEndpointId(scrollSpy.activeSectionId, endpointGroups),
    scrollToEndpoint: createScrollToEndpoint(scrollSpy.scrollToSection),
    registerEndpointSectionRef: createEndpointSectionRegistrar(scrollSpy.setSectionRef),
  };
};

import { APP_ROUTES } from "@bao/shared/constants/routes";
import type { ReadinessAssessment } from "@bao/shared/types/skill-mapping";
import { computed, type Ref, watch } from "vue";
import { useI18n } from "vue-i18n";
import {
  type SkillsPathwaysBootstrapData,
  type SkillsPathwaysGamificationProgress,
  toGamificationProgress,
  toSkillsPathwaysBootstrapData,
} from "~/composables/skills-pathways-page-data";
import { createSkillsPathwaysPresentation } from "~/composables/skills-pathways-page-presentation";
import { SKILLS_READINESS_MAX, SKILLS_READINESS_MIN } from "~/constants/skills";
import { requireApiResponseData } from "~/utils/api-response";
import { getErrorMessage } from "~/utils/errors";

const useSkillsPathwaysBootstrap = (
  api: ReturnType<typeof useApi>,
  t: ReturnType<typeof useI18n>["t"],
) =>
  useAsyncData<SkillsPathwaysBootstrapData>(
    "skills-pathways-bootstrap",
    async () => {
      const [pathwaysData, readinessData] = await Promise.all([
        api.skills.pathways.get(),
        api.skills.readiness.get(),
      ]);
      const pathways = requireApiResponseData(
        pathwaysData,
        t("skillsPathwaysPage.errors.pathwaysLoadFailed"),
      );
      const readiness = requireApiResponseData(
        readinessData,
        t("skillsPathwaysPage.errors.readinessLoadFailed"),
      );
      const normalized = toSkillsPathwaysBootstrapData({ pathways, readiness });
      if (!normalized) {
        throw new Error(t("skillsPathwaysPage.errors.loadFailed"));
      }
      return normalized;
    },
    {
      lazy: false,
      server: true,
    },
  );

const useSkillsPathwaysGamification = (
  api: ReturnType<typeof useApi>,
  t: ReturnType<typeof useI18n>["t"],
) =>
  useAsyncData(
    "skills-pathways-gamification-progress",
    async () => {
      const response = await api.gamification.progress.get();
      const progress = requireApiResponseData(
        response,
        t("skillsPathwaysPage.errors.gamificationLoadFailed"),
      );
      const normalized = toGamificationProgress(progress);
      if (!normalized) {
        throw new Error(t("skillsPathwaysPage.errors.gamificationLoadFailed"));
      }
      return normalized;
    },
    {
      lazy: false,
      server: true,
    },
  );

const createSkillsPathwaysDerivedState = (options: {
  readonly data: Ref<SkillsPathwaysBootstrapData | null | undefined>;
  readonly gamificationProgress: Ref<SkillsPathwaysGamificationProgress | null | undefined>;
  readonly status: Ref<"idle" | "pending" | "success" | "error">;
  readonly gamificationStatus: Ref<"idle" | "pending" | "success" | "error">;
  readonly presentation: ReturnType<typeof createSkillsPathwaysPresentation>;
  readonly t: ReturnType<typeof useI18n>["t"];
}) => {
  const gamificationReady = computed(() => options.gamificationStatus.value === "success");
  const uiState = computed(() => {
    if (options.status.value === "pending" || options.status.value === "idle") return "loading";
    if (options.status.value === "error") return "error";
    return "success";
  });

  const breadcrumbs = computed(() => [
    { label: options.t("nav.skills"), to: APP_ROUTES.skills },
    { label: options.t("skillsPathwaysPage.title") },
  ]);
  const gamificationLevel = computed(() =>
    gamificationReady.value ? (options.gamificationProgress.value?.level ?? 1) : 0,
  );
  const gamificationXP = computed(() =>
    gamificationReady.value ? (options.gamificationProgress.value?.xp ?? 0) : 0,
  );

  const readinessAssessment = computed<ReadinessAssessment | null>(
    () => options.data.value?.readiness ?? null,
  );
  const sortedPathways = computed(() =>
    options.presentation.sortPathways(options.data.value?.pathways ?? []),
  );
  const readinessCategories = computed(() =>
    options.presentation.createReadinessCategories(readinessAssessment.value),
  );
  return {
    gamificationReady,
    uiState,
    breadcrumbs,
    gamificationLevel,
    gamificationXP,
    readinessAssessment,
    sortedPathways,
    readinessCategories,
  };
};

const registerSkillsPathwaysErrorToast = (
  error: Ref<unknown>,
  toast: ReturnType<typeof useNuxtApp>["$toast"],
  t: ReturnType<typeof useI18n>["t"],
) => {
  watch(
    () => error.value,
    (nextError) => {
      if (import.meta.client && nextError) {
        toast.error(getErrorMessage(nextError, t("skillsPathwaysPage.errors.loadFailed")));
      }
    },
  );
};

export const useSkillsPathwaysPage = () => {
  const api = useApi();
  const { $toast } = useNuxtApp();
  const { t } = useI18n();
  const presentation = createSkillsPathwaysPresentation({ t });
  const { data, status, error, refresh } = useSkillsPathwaysBootstrap(api, t);
  const {
    data: gamificationProgress,
    status: gamificationStatus,
    error: gamificationError,
    refresh: refreshGamificationProgress,
  } = useSkillsPathwaysGamification(api, t);
  const derived = createSkillsPathwaysDerivedState({
    data,
    gamificationProgress,
    status,
    gamificationStatus,
    presentation,
    t,
  });
  registerSkillsPathwaysErrorToast(error, $toast, t);

  const retryLoad = async (): Promise<void> => {
    await refresh();
  };

  return {
    t,
    uiState: derived.uiState,
    error,
    breadcrumbs: derived.breadcrumbs,
    gamificationStatus,
    gamificationError,
    gamificationReady: derived.gamificationReady,
    gamificationLevel: derived.gamificationLevel,
    gamificationXP: derived.gamificationXP,
    refreshGamificationProgress,
    readinessAssessment: derived.readinessAssessment,
    readinessCategories: derived.readinessCategories,
    sortedPathways: derived.sortedPathways,
    retryLoad,
    readinessMin: SKILLS_READINESS_MIN,
    readinessMax: SKILLS_READINESS_MAX,
    getCategoryLabel: presentation.getCategoryLabel,
    getCategoryFeedbackLabel: presentation.getCategoryFeedbackLabel,
    getReadinessImprovementLabel: presentation.getReadinessImprovementLabel,
    getReadinessNextStepLabel: presentation.getReadinessNextStepLabel,
    getReadinessColor: presentation.getReadinessColor,
    getReadinessBadgeColor: presentation.getReadinessBadgeColor,
    getPathwayIcon: presentation.getPathwayIcon,
  };
};

import { asJsonArray, isRecord } from "@bao/shared/utils/type-guards";
import { useI18n } from "vue-i18n";
import { useAutomationRunStream } from "~/composables/useAutomationRunStream";
