  function clearProjectForm(): void {
    projectForm.title = "";
    projectForm.description = "";
    projectForm.technologies = [];
    projectForm.image = "";
    projectForm.liveUrl = "";
    projectForm.featured = false;
    modalState.newTech.value = "";
  }
