import { AI_ROUTING_PURPOSE_IDS, type AIProviderType, type AIRouting } from "@bao/shared/types/ai";
import type { Ref } from "vue";
import { settlePromise } from "~/composables/async-flow";
import type { ProviderConnectivityResult } from "~/types/ai-dashboard";
import { getErrorMessage } from "~/utils/errors";

type ApiClient = ReturnType<typeof useApi>;
type TestApiKeyInput = NonNullable<Parameters<ApiClient["settings"]["test-api-key"]["post"]>[0]>;
type Translate = (key: string, params?: Record<string, string | number>) => string;
type ProviderTestMessageContext = {
  providerId: AIProviderType;
  valid: boolean;
  t: Translate;
};

const PROVIDER_TEST_MESSAGES = {
  local: {
    false: "aiDashboard.tests.localFailure",
    true: "aiDashboard.tests.localSuccess",
  },
  remote: {
    false: "aiDashboard.tests.connectionFailure",
    true: "aiDashboard.tests.connectionSuccess",
  },
} as const;

export function createDefaultRouting(provider: AIProviderType) {
  const [
    chat,
    interviewQuestions,
    interviewFeedback,
    resume,
    coverLetter,
    emailResponse,
    jobMatch,
    scrapeEnrichment,
    automationFieldMapping,
  ] = AI_ROUTING_PURPOSE_IDS;

  return {
    [chat]: { provider },
    [interviewQuestions]: { provider },
    [interviewFeedback]: { provider },
    [resume]: { provider },
    [coverLetter]: { provider },
    [emailResponse]: { provider },
    [jobMatch]: { provider },
    [scrapeEnrichment]: { provider },
    [automationFieldMapping]: { provider },
  } satisfies AIRouting;
}

function resolveProviderCredential(
  settings: ReturnType<typeof useSettings>["settings"],
  providerId: TestApiKeyInput["provider"],
): string {
  const currentSettings = settings.value;
  if (!currentSettings) return "";
  const credentialByProvider = {
    claude: currentSettings.claudeApiKey ?? "",
    gemini: currentSettings.geminiApiKey ?? "",
    huggingface: currentSettings.huggingfaceToken ?? "",
    openai: currentSettings.openaiApiKey ?? "",
  } as const;
  return credentialByProvider[providerId as keyof typeof credentialByProvider] ?? "";
}

function resolveTestMessage({ providerId, valid, t }: ProviderTestMessageContext): string {
  const messageGroup =
    providerId === "local" ? PROVIDER_TEST_MESSAGES.local : PROVIDER_TEST_MESSAGES.remote;
  return t(messageGroup[valid ? "true" : "false"]);
}

async function testProviderConnectivity(input: {
  providerId: AIProviderType;
  settings: ReturnType<typeof useSettings>["settings"];
  localProviderState: ReturnType<typeof useSettings>["localProviderState"];
  testApiKey: ReturnType<typeof useSettings>["testApiKey"];
  t: Translate;
}): Promise<ProviderConnectivityResult> {
  if (input.providerId === "local") {
    const result = await input.testApiKey(
      "local",
      input.localProviderState.value.endpoint,
      input.localProviderState.value.configuredModel || undefined,
    );
    return {
      valid: result.valid,
      message:
        result.message ||
        resolveTestMessage({ providerId: "local", valid: result.valid, t: input.t }),
    };
  }

  const providerCredential = resolveProviderCredential(input.settings, input.providerId);
  if (!providerCredential.trim()) {
    return {
      valid: false,
      message: input.t("aiDashboard.tests.missingCredential"),
    };
  }

  const result = await input.testApiKey(input.providerId, providerCredential);
  return {
    valid: result.valid,
    message:
      result.message ||
      resolveTestMessage({ providerId: input.providerId, valid: result.valid, t: input.t }),
  };
}

function createDashboardRefreshAction(input: {
  refreshDashboardBootstrap: () => Promise<void>;
  t: Translate;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
}) {
  return async function fetchProviderStats() {
    const refreshResult = await settlePromise(
      input.refreshDashboardBootstrap(),
      input.t("aiDashboard.toasts.loadFailed"),
    );
    if (!refreshResult.ok) {
      input.toast.error(
        getErrorMessage(refreshResult.error, input.t("aiDashboard.toasts.loadFailed")),
      );
    }
  };
}

function createProviderTestAction(input: {
  localProviderState: ReturnType<typeof useSettings>["localProviderState"];
  settings: ReturnType<typeof useSettings>["settings"];
  t: Translate;
  testApiKey: ReturnType<typeof useSettings>["testApiKey"];
  testResults: Record<AIProviderType, ProviderConnectivityResult | null>;
  testingProvider: Ref<AIProviderType | null>;
}) {
  return async function handleTestProvider(providerId: AIProviderType) {
    input.testingProvider.value = providerId;
    input.testResults[providerId] = null;

    const providerTestResult = await settlePromise(
      testProviderConnectivity({
        providerId,
        settings: input.settings,
        localProviderState: input.localProviderState,
        testApiKey: input.testApiKey,
        t: input.t,
      }),
      input.t("aiDashboard.tests.connectionFailure"),
    );
    input.testingProvider.value = null;

    if (!providerTestResult.ok) {
      input.testResults[providerId] = {
        valid: false,
        message: getErrorMessage(
          providerTestResult.error,
          input.t("aiDashboard.tests.connectionFailure"),
        ),
      };
      return;
    }

    input.testResults[providerId] = providerTestResult.value;
  };
}

function createDashboardPreferenceAction(
  input: {
    api: ReturnType<typeof useApi>;
    selectedModel: Ref<string>;
    selectedProvider: Ref<AIProviderType>;
    settings: ReturnType<typeof useSettings>["settings"];
    t: Translate;
    toast: ReturnType<typeof useNuxtApp>["$toast"];
  },
  fetchProviderStats: () => Promise<void>,
) {
  return async function handleSetPreference() {
    if (!(input.selectedProvider.value && input.selectedModel.value)) {
      return;
    }

    const preferenceResult = await settlePromise(
      (async () => {
        const { error } = await input.api.settings.put({
          aiRouting: {
            ...(input.settings.value?.aiRouting ??
              createDefaultRouting(input.selectedProvider.value)),
            chat: {
              provider: input.selectedProvider.value,
              ...(input.selectedModel.value ? { model: input.selectedModel.value } : {}),
            },
          },
          preferredProvider: input.selectedProvider.value,
          preferredModel: input.selectedModel.value || undefined,
        });
        if (error) {
          throw new Error(input.t("aiDashboard.errors.preferenceSaveFailed"));
        }
      })(),
      input.t("aiDashboard.toasts.preferenceSaveFailed"),
    );
    if (!preferenceResult.ok) {
      input.toast.error(
        getErrorMessage(preferenceResult.error, input.t("aiDashboard.toasts.preferenceSaveFailed")),
      );
      return;
    }

    input.toast.success(input.t("aiDashboard.toasts.preferenceSaved"));
    await fetchProviderStats();
  };
}

export function createAIDashboardActions(input: {
  api: ReturnType<typeof useApi>;
  localProviderState: ReturnType<typeof useSettings>["localProviderState"];
  refreshDashboardBootstrap: () => Promise<void>;
  selectedModel: Ref<string>;
  selectedProvider: Ref<AIProviderType>;
  settings: ReturnType<typeof useSettings>["settings"];
  t: Translate;
  testApiKey: ReturnType<typeof useSettings>["testApiKey"];
  testResults: Record<AIProviderType, ProviderConnectivityResult | null>;
  testingProvider: Ref<AIProviderType | null>;
  toast: ReturnType<typeof useNuxtApp>["$toast"];
}) {
  const fetchProviderStats = createDashboardRefreshAction(input);
  const handleTestProvider = createProviderTestAction(input);
  const handleSetPreference = createDashboardPreferenceAction(input, fetchProviderStats);

  return {
    fetchProviderStats,
    handleSetPreference,
    handleTestProvider,
  };
}

import { safeParseJson } from "@bao/shared/utils/json";
import type { Ref } from "vue";
import { computed, ref } from "vue";
import type { ApiDocsToast, ApiDocsTranslate } from "~/composables/api-docs-page-contracts";
import { createEndpointTesterActions } from "~/composables/api-docs-page-tester-actions";
import type { ApiEndpoint, ApiTesterState, FetchEndpointResultOk } from "~/types/api-docs";

interface ApiDocsPageTesterOptions {
  readonly t: ApiDocsTranslate;
  readonly apiBase: string;
  readonly requestUrl: URL;
  readonly toast: ApiDocsToast;
}

const createTesterStateLabel = (testerState: Readonly<Ref<ApiTesterState>>, t: ApiDocsTranslate) =>
  computed(() => {
    if (testerState.value === "idle") {
      return t("apiDocs.tester.steps.configure");
    }
    if (testerState.value === "success") {
      return t("apiDocs.tester.requestSuccessToast");
    }
    if (testerState.value === "loading") {
      return t("apiDocs.state.loading");
    }
    if (testerState.value === "empty") {
      return t("apiDocs.state.empty");
    }
    return t(`apiDocs.state.${testerState.value}`);
  });

const createFormattedResponseBody = (testerResponse: Readonly<Ref<FetchEndpointResultOk | null>>) =>
  computed(() => {
    const body = testerResponse.value?.body ?? "";
    if (!body.trim()) {
      return "";
    }
    const parsedBody = safeParseJson(body);
    if (parsedBody === null) {
      return body;
    }
    return JSON.stringify(parsedBody, null, 2);
  });

export const useApiDocsPageTester = ({
  t,
  apiBase,
  requestUrl,
  toast,
}: ApiDocsPageTesterOptions) => {
  const testerInvoker = ref<{ focus?: () => void } | null>(null);
  const testerDialogOpen = ref(false);
  const selectedEndpoint = ref<ApiEndpoint | null>(null);
  const testerState = ref<ApiTesterState>("idle");
  const testerErrorMessage = ref("");
  const testerResponse = ref<FetchEndpointResultOk | null>(null);
  const pathParameterValues = ref<Record<string, string>>({});
  const queryParameterValues = ref<Record<string, string>>({});
  const requestBodyValue = ref("");
  const actions = createEndpointTesterActions({
    t,
    apiBase,
    requestUrl,
    toast,
    testerInvoker,
    testerDialogOpen,
    selectedEndpoint,
    testerState,
    testerErrorMessage,
    testerResponse,
    pathParameterValues,
    queryParameterValues,
    requestBodyValue,
  });

  return {
    testerDialogOpen,
    selectedEndpoint,
    testerState,
    testerStateLabel: createTesterStateLabel(testerState, t),
    pathParameterValues,
    queryParameterValues,
    requestBodyValue,
    testerErrorMessage,
    testerResponse,
    formattedResponseBody: createFormattedResponseBody(testerResponse),
    openEndpointTester: (endpoint: ApiEndpoint, invoker: EventTarget | null) =>
      actions.openEndpointTester(endpoint, invoker),
    handleEndpointTesterClosed: () => actions.handleEndpointTesterClosed(),
    executeEndpointRequest: () => actions.executeEndpointRequest(),
  };
};

import { PORTFOLIO_PROJECT_LIST_PAGE_SIZE } from "@bao/shared/constants/portfolio";
import type { PortfolioMetadata } from "@bao/shared/types/portfolio";
import type { ComputedRef, Ref } from "vue";
import type { ComposerTranslation } from "vue-i18n";
import {
  normalizePortfolioProject,
  type PortfolioProjectView,
} from "~/composables/portfolio-page-state";

type PortfolioPageDerivedInput = {
  portfolioForm: PortfolioMetadata;
  projects: Ref<readonly PortfolioProjectView[]>;
  searchQuery: Ref<string>;
};

function usePortfolioProjectSearch(
  projects: Ref<readonly PortfolioProjectView[]>,
  searchQuery: Ref<string>,
  t: ComposerTranslation,
) {
  const displayProjects = computed(() =>
    projects.value.map((project) => normalizePortfolioProject(project)),
  );
  const filteredProjects = computed(() => {
    const query = searchQuery.value.trim().toLowerCase();
    if (!query) {
      return displayProjects.value;
    }

    return displayProjects.value.filter((project) => {
      const title = project.title.toLowerCase();
      const description = (project.description || "").toLowerCase();
      const technologies = (project.technologies || []).join(" ").toLowerCase();
      return title.includes(query) || description.includes(query) || technologies.includes(query);
    });
  });
  const projectPagination = usePagination(filteredProjects, PORTFOLIO_PROJECT_LIST_PAGE_SIZE, [
    searchQuery,
  ]);

  return {
    displayProjects,
    filteredProjects,
    hasFiltersApplied: computed(() => searchQuery.value.trim().length > 0),
    projectPageAria(page: number): string {
      return t("portfolioPage.pagination.pageAria", { page });
    },
    projectPagination,
    projectPaginationSummary: computed(() =>
      t("portfolioPage.pagination.summary", {
        start: projectPagination.rangeStart.value,
        end: projectPagination.rangeEnd.value,
        total: projectPagination.totalItems.value,
      }),
    ),
  };
}

function usePortfolioProjectTechnologySuggestions(
  displayProjects: ComputedRef<readonly ReturnType<typeof normalizePortfolioProject>[]>,
) {
  return computed(() => {
    const suggestions = new Set<string>();
    for (const project of displayProjects.value) {
      for (const technology of project.technologies || []) {
        const trimmed = technology.trim();
        if (trimmed.length > 0) {
          suggestions.add(trimmed);
        }
      }
    }

    return [...suggestions].sort((left, right) => left.localeCompare(right));
  });
}

export function usePortfolioPageDerived(
  { portfolioForm, projects, searchQuery }: PortfolioPageDerivedInput,
  t: ComposerTranslation,
) {
  const search = usePortfolioProjectSearch(projects, searchQuery, t);

  const featuredProjectCount = computed(
    () => projects.value.filter((project) => project.featured).length,
  );

  const hasMetadata = computed(
    () =>
      Boolean(portfolioForm.title?.trim()) ||
      Boolean(portfolioForm.bio?.trim()) ||
      Boolean(portfolioForm.email?.trim()) ||
      Boolean(portfolioForm.website?.trim()),
  );
  const projectTechnologySuggestions = usePortfolioProjectTechnologySuggestions(
    search.displayProjects,
  );

  return {
    displayProjects: search.displayProjects,
    featuredProjectCount,
    filteredProjects: search.filteredProjects,
    hasFiltersApplied: search.hasFiltersApplied,
    hasMetadata,
    projectPageAria: (page: number) => search.projectPageAria(page),
    projectPagination: search.projectPagination,
    projectPaginationSummary: search.projectPaginationSummary,
    projectTechnologySuggestions,
  };
}

import type { Ref } from "vue";
import type { useI18n } from "vue-i18n";
import { getErrorMessage } from "~/utils/errors";
import { settlePromise } from "./async-flow";
import type { useSpeechModelProfiles } from "./useSpeechModelProfiles";

type FocusableInputRef = {
  value: { focus: () => void } | null;
};

export const createFloatingChatWidgetPanelActions = (options: {
  isOpen: Ref<boolean>;
  isSpeechSettingsOpen: Ref<boolean>;
  unreadCount: Ref<number>;
  inputRef: FocusableInputRef;
  ensureSpeechConfigLoaded: ReturnType<typeof useSpeechModelProfiles>["ensureSpeechConfigLoaded"];
  toast: ReturnType<typeof useNuxtApp>["$toast"];
  t: ReturnType<typeof useI18n>["t"];
}) => {
  const toggleWidget = () => {
    options.isOpen.value = !options.isOpen.value;
  };

  const closeWidget = () => {
    options.isOpen.value = false;
  };

  const toggleSpeechSettings = async (): Promise<void> => {
    if (options.isSpeechSettingsOpen.value) {
      options.isSpeechSettingsOpen.value = false;
      return;
    }

    const loadSpeechConfigResult = await settlePromise(
      options.ensureSpeechConfigLoaded(),
      options.t("apiErrors.settings.fetchFailed"),
    );
    if (!loadSpeechConfigResult.ok) {
      options.toast.error(
        getErrorMessage(loadSpeechConfigResult.error, options.t("apiErrors.settings.fetchFailed")),
      );
      return;
    }

    options.isSpeechSettingsOpen.value = true;
  };

  const handleFocusChatShortcut = () => {
    options.isOpen.value = true;
    options.unreadCount.value = 0;
    requestAnimationFrame(() => {
      options.inputRef.value?.focus();
    });
  };

  return {
    toggleWidget,
    closeWidget,
    toggleSpeechSettings,
    handleFocusChatShortcut,
  };
};

export const createFloatingChatWidgetMessageActions = (options: {
  draft: Ref<string>;
  loading: ReturnType<typeof useAI>["loading"];
  isVoiceListening: Readonly<Ref<boolean>>;
  stopListening: () => void;
  shouldStickToBottom: Ref<boolean>;
  sendMessage: ReturnType<typeof useAI>["sendMessage"];
  inputRef: FocusableInputRef;
  scrollToBottom: (force?: boolean) => void;
}) => {
  const handleSendMessage = async () => {
    if (!options.draft.value.trim() || options.loading.value) return;

    if (options.isVoiceListening.value) {
      options.stopListening();
    }

    options.shouldStickToBottom.value = true;
    const content = options.draft.value.trim();
    options.draft.value = "";
    await options.sendMessage(content, { source: "floating-widget" });
    options.scrollToBottom(true);
  };

  const handlePromptInput = (prompt: string): void => {
    options.draft.value = prompt;
    requestAnimationFrame(() => {
      options.inputRef.value?.focus();
    });
  };

  const handleDraftKeydown = async (event: KeyboardEvent): Promise<void> => {
    if (event.key !== "Enter" || event.shiftKey || event.isComposing) {
      return;
    }

    event.preventDefault();
    await handleSendMessage();
  };

  return {
    handleSendMessage,
    handlePromptInput,
    handleDraftKeydown,
  };
};

export const createFloatingChatWidgetSpeechActions = (options: {
  saveSpeechConfig: ReturnType<typeof useSpeechModelProfiles>["saveSpeechConfig"];
  toast: ReturnType<typeof useNuxtApp>["$toast"];
  t: ReturnType<typeof useI18n>["t"];
}) => {
  const handleSaveSpeechConfig = async (): Promise<void> => {
    const saveSpeechResult = await options.saveSpeechConfig(
      options.t("floatingChat.voiceSettings.saveErrorFallback"),
    );
    if (!saveSpeechResult.ok) {
      options.toast.error(
        getErrorMessage(
          saveSpeechResult.error,
          options.t("floatingChat.voiceSettings.saveErrorFallback"),
        ),
      );
      return;
    }

    if (!saveSpeechResult.saved) {
      return;
    }

    options.toast.success(options.t("floatingChat.voiceSettings.saveSuccess"));
  };

  return {
    handleSaveSpeechConfig,
  };
};

