export const registerJobsPageEffects = (input: {
  currentPage: Ref<number>;
  localFilters: JobsFilterState;
  searchQuery: Ref<string>;
  totalPages: ComputedRef<number>;
}) => {
  watch(
    () => ({
      search: input.searchQuery.value,
      location: input.localFilters.location,
      remote: input.localFilters.remote,
      experienceLevel: input.localFilters.experienceLevel,
      studioType: input.localFilters.studioType,
      platform: input.localFilters.platform,
      genre: input.localFilters.genre,
    }),
    () => {
      input.currentPage.value = 1;
    },
  );

  watch(input.totalPages, (nextTotal) => {
    if (nextTotal <= 0) {
      input.currentPage.value = 1;
      return;
    }
    if (input.currentPage.value > nextTotal) {
      input.currentPage.value = nextTotal;
    }
  });
};

import { THEME_NAMES } from "@bao/shared/constants/branding";
import type { AppSettings } from "@bao/shared/types/settings-contracts";
import { computed, type Ref, watch } from "vue";
import { toAppSettings } from "../api-normalizer-settings";
import { createSettingsPageDerivedState } from "./derived";
import { createSettingsPageOptionState } from "./options";
import {
  type BrandRuntimeState,
  createSettingsPageBrandRuntimeState,
  createSettingsPageProfileRuntimeState,
  createSettingsPageProviderRuntimeState,
  createSettingsPageSaveRuntimeState,
  createSettingsPageServices,
  type ProfileRuntimeState,
  type ProviderRuntimeState,
  type SaveRuntimeState,
  type SettingsPageServices,
  syncSettingsState,
  useSettingsPageBootstrap,
} from "./runtime";

type SettingsPageBootstrapState = ReturnType<typeof useSettingsPageBootstrap>;
type SettingsPageOptionState = ReturnType<typeof createSettingsPageOptionState>;
type SettingsPageDerivedState = ReturnType<typeof createSettingsPageDerivedState>;
type UserProfileSnapshot = {
  name: string;
  email?: string | null;
  phone?: string | null;
  location?: string | null;
  website?: string | null;
  linkedin?: string | null;
  github?: string | null;
  summary?: string | null;
  currentRole?: string | null;
  currentCompany?: string | null;
  yearsExperience?: number | null;
  technicalSkills: readonly string[];
  softSkills: readonly string[];
};

type WatcherSetupOptions = {
  settings: Readonly<Ref<AppSettings | null>>;
  profile: Readonly<Ref<UserProfileSnapshot | null | undefined>>;
  providerState: ProviderRuntimeState;
  saveState: SaveRuntimeState;
  brandState: BrandRuntimeState;
  profileState: ProfileRuntimeState;
};

type SettingsPageStateResultOptions = {
  services: SettingsPageServices;
  settings: { value: AppSettings | null };
  optionState: SettingsPageOptionState;
  providerState: ProviderRuntimeState;
  saveState: SaveRuntimeState;
  brandState: BrandRuntimeState;
  profileState: ProfileRuntimeState;
  bootstrapState: SettingsPageBootstrapState;
  derivedState: SettingsPageDerivedState;
};

function syncProfileState(currentProfile: UserProfileSnapshot, profileState: ProfileRuntimeState) {
  profileState.profileForm.name = currentProfile.name || "";
  profileState.profileForm.email = currentProfile.email || "";
  profileState.profileForm.phone = currentProfile.phone || "";
  profileState.profileForm.location = currentProfile.location || "";
  profileState.profileForm.website = currentProfile.website || "";
  profileState.profileForm.linkedin = currentProfile.linkedin || "";
  profileState.profileForm.github = currentProfile.github || "";
  profileState.profileForm.summary = currentProfile.summary || "";
  profileState.profileForm.currentRole = currentProfile.currentRole || "";
  profileState.profileForm.currentCompany = currentProfile.currentCompany || "";
  profileState.profileForm.yearsExperience = currentProfile.yearsExperience || 0;
  profileState.profileForm.technicalSkillsText = currentProfile.technicalSkills.join(", ");
  profileState.profileForm.softSkillsText = currentProfile.softSkills.join(", ");
}

function setupSettingsPageWatchers(options: WatcherSetupOptions) {
  watch(
    options.settings,
    (currentSettings) => {
      if (currentSettings) {
        syncSettingsState(
          currentSettings,
          options.providerState,
          options.saveState,
          options.brandState,
        );
      }
    },
    { immediate: true },
  );

  watch(options.providerState.preferredProviderSelection, (provider) => {
    if (options.providerState.aiRoutingDraft.chat.provider !== provider) {
      options.providerState.aiRoutingDraft.chat.provider = provider;
    }
  });

  watch(
    () => options.providerState.aiRoutingDraft.chat.provider,
    (provider) => {
      if (options.providerState.preferredProviderSelection.value !== provider) {
        options.providerState.preferredProviderSelection.value = provider;
      }
    },
  );

  watch(
    options.profile,
    (currentProfile) => {
      if (currentProfile) {
        syncProfileState(currentProfile, options.profileState);
      }
    },
    { immediate: true },
  );
}

function buildSettingsPageStateResult(options: SettingsPageStateResultOptions) {
  return {
    t: options.services.t,
    settings: options.settings,
    profile: options.services.profile,
    resolvedBrand: options.services.resolvedBrand,
    theme: options.services.theme,
    setTheme: options.services.setTheme,
    toggleTheme: options.services.toggleTheme,
    THEME_NAMES,
    fetchSettings: options.services.fetchSettings,
    updateSettings: options.services.updateSettings,
    updateJobTaxonomy: options.services.updateJobTaxonomy,
    updateApiKeys: options.services.updateApiKeys,
    testApiKey: options.services.testApiKey,
    updateProfile: options.services.updateProfile,
    settingsLoading: options.services.settingsLoading,
    profileLoading: options.services.profileLoading,
    providerDiagnostics: options.services.providerDiagnostics,
    ...options.optionState,
    ...options.providerState,
    ...options.saveState,
    ...options.brandState,
    ...options.profileState,
    settingsBootstrapError: options.bootstrapState.error,
    settingsBootstrapStatus: options.bootstrapState.status,
    refreshSettingsBootstrap: options.bootstrapState.refresh,
    ...options.derivedState,
    $toast: options.services.$toast,
  };
}

export function useSettingsPageState() {
  const services = createSettingsPageServices();
  const settings = computed(() => toAppSettings(services.rawSettings.value));

  const optionState = createSettingsPageOptionState(services.t);
  const providerState = createSettingsPageProviderRuntimeState();
  const saveState = createSettingsPageSaveRuntimeState();
  const brandState = createSettingsPageBrandRuntimeState();
  const profileState = createSettingsPageProfileRuntimeState();
  const bootstrapState = useSettingsPageBootstrap(services);

  setupSettingsPageWatchers({
    settings,
    profile: services.profile,
    providerState,
    saveState,
    brandState,
    profileState,
  });

  const derivedState = createSettingsPageDerivedState({
    t: services.t,
    settings,
    emailTransportForm: saveState.emailTransportForm,
    aiRoutingDraft: providerState.aiRoutingDraft,
    apiKeys: providerState.apiKeys,
    brandForm: brandState.brandForm,
    brandDefaults: brandState.brandDefaults,
  });

  return buildSettingsPageStateResult({
    services,
    settings,
    optionState,
    providerState,
    saveState,
    brandState,
    profileState,
    bootstrapState,
    derivedState,
  });
}

export type SettingsPageState = Awaited<ReturnType<typeof useSettingsPageState>>;

import { resolveBrandSettings } from "@bao/shared/constants/branding";
import {
  brandContentSettingsSchema,
  brandThemePaletteSchema,
} from "@bao/shared/schemas/settings.schema";
import { AI_ROUTING_PURPOSE_IDS, type AIProviderType } from "@bao/shared/types/ai";
import type {
  AppSettings,
  BrandSettings,
  EmailTransportSettings,
} from "@bao/shared/types/settings-contracts";
import { isEmailTransportConfigured } from "@bao/shared/utils/email-transport";
import { parseJson } from "@bao/shared/utils/json";
import { computed } from "vue";
import { resolveLocalProviderState, resolveProviderModelOptions } from "~/utils/ai-control-plane";
import type { AIRoutingDraft, TranslateFn } from "./shared";

type DerivedStateInput = {
  t: TranslateFn;
  settings: {
    value: AppSettings | null;
  };
  emailTransportForm: EmailTransportSettings;
  aiRoutingDraft: AIRoutingDraft;
  apiKeys: {
    localModelEndpoint: string;
    localModelName: string;
  };
  brandForm: {
    name: string;
    assistantName: string;
    apiName: string;
    logoPath: string;
    faviconPath: string;
    fontStylesheetUrl: string;
    displayFontFamily: string;
    bodyFontFamily: string;
    monoFontFamily: string;
    tagline: string;
    defaultTitle: string;
    defaultDescription: string;
    lightThemeJson: string;
    darkThemeJson: string;
    contentOverridesJson: string;
  };
  brandDefaults: BrandSettings;
};

function createEmailDeliveryConfigured(input: DerivedStateInput) {
  return computed(() =>
    isEmailTransportConfigured(
      input.settings.value?.emailTransportSettings ?? input.emailTransportForm,
      input.settings.value?.hasEmailTransportPassword ?? false,
    ),
  );
}

function createLocalProviderDraftState(input: DerivedStateInput) {
  return computed(() =>
    resolveLocalProviderState({
      settings: input.settings.value,
      endpoint: input.apiKeys.localModelEndpoint,
      model: input.apiKeys.localModelName,
    }),
  );
}

function createAiRoutingSections(input: DerivedStateInput) {
  return computed(() =>
    AI_ROUTING_PURPOSE_IDS.map((purpose) => ({
      id: purpose,
      label: input.t(`settings.aiProviders.purposes.${purpose}.label`),
      description: input.t(`settings.aiProviders.purposes.${purpose}.description`),
    })),
  );
}

function resolveRoutingOptions(input: DerivedStateInput, provider: AIProviderType): string[] {
  return resolveProviderModelOptions(
    provider,
    input.settings.value,
    provider === "local" ? [input.apiKeys.localModelName] : [],
  );
}

function createRoutingModelOptions(input: DerivedStateInput) {
  return computed(() => ({
    chat: resolveRoutingOptions(input, input.aiRoutingDraft.chat.provider),
    interviewQuestions: resolveRoutingOptions(
      input,
      input.aiRoutingDraft.interviewQuestions.provider,
    ),
    interviewFeedback: resolveRoutingOptions(
      input,
      input.aiRoutingDraft.interviewFeedback.provider,
    ),
    resume: resolveRoutingOptions(input, input.aiRoutingDraft.resume.provider),
    coverLetter: resolveRoutingOptions(input, input.aiRoutingDraft.coverLetter.provider),
    emailResponse: resolveRoutingOptions(input, input.aiRoutingDraft.emailResponse.provider),
    jobMatch: resolveRoutingOptions(input, input.aiRoutingDraft.jobMatch.provider),
    scrapeEnrichment: resolveRoutingOptions(input, input.aiRoutingDraft.scrapeEnrichment.provider),
    automationFieldMapping: resolveRoutingOptions(
      input,
      input.aiRoutingDraft.automationFieldMapping.provider,
    ),
  }));
}

function createProviderConfiguredById(input: DerivedStateInput) {
  return computed(() => {
    const current = input.settings.value;
    if (!current) {
      return {
        local: false,
        gemini: false,
        openai: false,
        claude: false,
        huggingface: false,
      };
    }

    return {
      local: current.hasLocalKey ?? true,
      gemini: Boolean(current.hasGeminiKey),
      openai: Boolean(current.hasOpenaiKey),
      claude: Boolean(current.hasClaudeKey),
      huggingface: Boolean(current.hasHuggingfaceToken),
    };
  });
}

function parseBrandContentOverrides(input: DerivedStateInput): Record<string, string> {
  return (
    parseJson(
      input.brandForm.contentOverridesJson,
      brandContentSettingsSchema.shape.contentOverrides,
    ) ?? {}
  );
}

function createBrandDraft(input: DerivedStateInput) {
  return computed<BrandSettings>(() =>
    resolveBrandSettings({
      name: input.brandForm.name.trim() || input.brandDefaults.name,
      assistantName: input.brandForm.assistantName.trim() || input.brandDefaults.assistantName,
      apiName: input.brandForm.apiName.trim() || input.brandDefaults.apiName,
      logoPath: input.brandForm.logoPath.trim() || input.brandDefaults.logoPath,
      faviconPath: input.brandForm.faviconPath.trim() || input.brandDefaults.faviconPath,
      typography: {
        fontStylesheetUrl: input.brandForm.fontStylesheetUrl.trim(),
        displayFontFamily:
          input.brandForm.displayFontFamily.trim() ||
          input.brandDefaults.typography.displayFontFamily,
        bodyFontFamily:
          input.brandForm.bodyFontFamily.trim() || input.brandDefaults.typography.bodyFontFamily,
        monoFontFamily:
          input.brandForm.monoFontFamily.trim() || input.brandDefaults.typography.monoFontFamily,
      },
      lightTheme:
        parseJson(input.brandForm.lightThemeJson, brandThemePaletteSchema) ??
        input.brandDefaults.lightTheme,
      darkTheme:
        parseJson(input.brandForm.darkThemeJson, brandThemePaletteSchema) ??
        input.brandDefaults.darkTheme,
      content: {
        tagline: input.brandForm.tagline.trim() || input.brandDefaults.content.tagline,
        defaultTitle:
          input.brandForm.defaultTitle.trim() || input.brandDefaults.content.defaultTitle,
        defaultDescription:
          input.brandForm.defaultDescription.trim() ||
          input.brandDefaults.content.defaultDescription,
        contentOverrides: parseBrandContentOverrides(input),
      },
    }),
  );
}

export function createSettingsPageDerivedState(input: DerivedStateInput) {
  const brandDraft = createBrandDraft(input);

  return {
    emailDeliveryConfigured: createEmailDeliveryConfigured(input),
    showOllamaHotTip: computed(() => input.aiRoutingDraft.chat.provider === "local"),
    localProviderDraftState: createLocalProviderDraftState(input),
    aiRoutingSections: createAiRoutingSections(input),
    routingModelOptions: createRoutingModelOptions(input),
    providerConfiguredById: createProviderConfiguredById(input),
    parseBrandContentOverrides: () => parseBrandContentOverrides(input),
    brandDraft,
    brandOverrideCount: computed(
      () => Object.keys(brandDraft.value.content.contentOverrides).length,
    ),
  };
}

import { DEFAULT_APP_LANGUAGE } from "@bao/shared/constants/settings";
import {
  jobTaxonomyKeywordEntrySchema,
  studioClassificationRuleSchema,
} from "@bao/shared/schemas/jobs-taxonomy.schema";
import {
  companyBoardApiTemplatesSchema,
  companyBoardConfigSchema,
  gamingPortalConfigSchema,
  greenhouseBoardConfigSchema,
  leverCompanyConfigSchema,
} from "@bao/shared/schemas/settings.schema";
import { parseJson } from "@bao/shared/utils/json";
import { isValidEmail } from "@bao/shared/utils/validation";
import z from "zod";
import { buildBrandPayload } from "./save-brand-payload";
import { parseDelimitedList, runStatefulSave, runToastTask } from "./shared";
import type { SettingsPageState } from "./state";

type ProfilePayload = Parameters<SettingsPageState["updateProfile"]>[0];

const PROFILE_OPTIONAL_FIELDS = [
  ["phone", "phone"],
  ["location", "location"],
  ["website", "website"],
  ["linkedin", "linkedin"],
  ["github", "github"],
  ["summary", "summary"],
  ["currentRole", "currentRole"],
  ["currentCompany", "currentCompany"],
] as const satisfies readonly (readonly [
  keyof SettingsPageState["profileForm"],
  keyof ProfilePayload,
])[];

function buildProfilePayload(
  state: SettingsPageState,
  name: string,
  email: string,
): ProfilePayload {
  const payload: ProfilePayload = {
    name,
    technicalSkills: parseDelimitedList(state.profileForm.technicalSkillsText),
    softSkills: parseDelimitedList(state.profileForm.softSkillsText),
    email,
  };

  for (const [formField, payloadField] of PROFILE_OPTIONAL_FIELDS) {
    const value = state.profileForm[formField];
    if (typeof value === "string") {
      const trimmedValue = value.trim();
      if (trimmedValue.length > 0) {
        payload[payloadField] = trimmedValue;
      }
    }
  }

  if (Number.isFinite(state.profileForm.yearsExperience)) {
    payload.yearsExperience = state.profileForm.yearsExperience;
  }

  return payload;
}

function createHandleToggleTheme(state: SettingsPageState) {
  return async () => {
    const previousTheme = state.theme.value;
    const nextTheme =
      previousTheme === state.THEME_NAMES.light ? state.THEME_NAMES.dark : state.THEME_NAMES.light;
    // Preview locally; persist cookie only after settings SSOT save succeeds.
    state.setTheme(nextTheme, { persist: false });
    const savedTheme = await runToastTask(
      state.updateSettings({ theme: nextTheme }),
      state.t("settings.errors.failedToSaveTheme"),
      state.$toast,
    );
    if (savedTheme === null) {
      state.setTheme(previousTheme, { persist: false });
      return;
    }
    state.setTheme(nextTheme, { persist: true });
    state.$toast.success(state.t("settings.toasts.themeSaved"));
  };
}

function createHandleSavePreferences(state: SettingsPageState) {
  return () =>
    runStatefulSave({
      state: state.preferencesSaveState,
      task: state.updateSettings({
        language: state.preferencesLanguage.value || DEFAULT_APP_LANGUAGE,
        notifications: {
          achievements: state.notificationForm.achievements,
          dailyChallenges: state.notificationForm.dailyChallenges,
          levelUp: state.notificationForm.levelUp,
          jobAlerts: state.notificationForm.jobAlerts,
        },
      }),
      failureMessage: state.t("settings.errors.failedToSavePreferences"),
      successMessage: state.t("settings.toasts.preferencesSaved"),
      toast: state.$toast,
    });
}

function createHandleSaveProfile(state: SettingsPageState) {
  return async () => {
    const name = state.profileForm.name.trim();
    if (name.length < 2) {
      state.profileSaveState.value = "error";
      state.$toast.error(state.t("settings.errors.nameTooShort"));
      return;
    }

    const email = state.profileForm.email.trim();
    if (!isValidEmail(email)) {
      state.profileSaveState.value = "error";
      state.$toast.error(state.t("settings.errors.invalidEmail"));
      return;
    }

    await runStatefulSave({
      state: state.profileSaveState,
      task: state.updateProfile(buildProfilePayload(state, name, email)),
      failureMessage: state.t("settings.errors.failedToSaveProfile"),
      successMessage: state.t("settings.toasts.profileSaved"),
      toast: state.$toast,
    });
  };
}

function createHandleSaveBrand(state: SettingsPageState) {
  return async () => {
    const brandPayload = buildBrandPayload(state);
    if (!brandPayload) {
      state.brandSaveState.value = "error";
      return;
    }
    await runStatefulSave({
      state: state.brandSaveState,
      task: state.updateSettings({ brandSettings: brandPayload }),
      failureMessage: state.t("settings.brand.errors.failedToSave"),
      successMessage: state.t("settings.toasts.brandSaved"),
      toast: state.$toast,
    });
  };
}

function createHandleSaveAutomation(state: SettingsPageState) {
  return async () => {
    const savedAutomation = await runToastTask(
      state.updateSettings({ automationSettings: { ...state.automationForm } }),
      state.t("settings.errors.failedToSaveAutomation"),
      state.$toast,
    );
    if (savedAutomation !== null) state.$toast.success(state.t("settings.toasts.automationSaved"));
  };
}

function parseJobProviderCollections(state: SettingsPageState) {
  const greenhouseBoards = parseJson(
    state.jobProviderForm.greenhouseBoardsJson,
    z.array(greenhouseBoardConfigSchema),
  );
  const leverCompanies = parseJson(
    state.jobProviderForm.leverCompaniesJson,
    z.array(leverCompanyConfigSchema),
  );
  const companyBoards = parseJson(
    state.jobProviderForm.companyBoardsJson,
    z.array(companyBoardConfigSchema),
  );
  const companyBoardApiTemplates = parseJson(
    state.jobProviderForm.companyBoardApiTemplatesJson,
    companyBoardApiTemplatesSchema,
  );
  const gamingPortals = parseJson(
    state.jobProviderForm.gamingPortalsJson,
    z.array(gamingPortalConfigSchema),
  );
  if (
    !(
      greenhouseBoards &&
      leverCompanies &&
      companyBoards &&
      companyBoardApiTemplates &&
      gamingPortals
    )
  )
    return null;

  return {
    greenhouseBoards,
    leverCompanies,
    companyBoards,
    companyBoardApiTemplates,
    gamingPortals,
  };
}

function buildJobProvidersPayload(state: SettingsPageState) {
  const collections = parseJobProviderCollections(state);
  if (!collections) {
    return null;
  }

  return {
    providerTimeoutMs: state.jobProviderForm.providerTimeoutMs,
    companyBoardResultLimit: state.jobProviderForm.companyBoardResultLimit,
    gamingBoardResultLimit: state.jobProviderForm.gamingBoardResultLimit,
    unknownLocationLabel: state.jobProviderForm.unknownLocationLabel.trim(),
    unknownCompanyLabel: state.jobProviderForm.unknownCompanyLabel.trim(),
    hitmarkerEnabled: state.jobProviderForm.hitmarkerEnabled,
    hitmarkerApiBaseUrl: state.jobProviderForm.hitmarkerApiBaseUrl.trim(),
    hitmarkerDefaultQuery: state.jobProviderForm.hitmarkerDefaultQuery.trim(),
    hitmarkerDefaultLocation: state.jobProviderForm.hitmarkerDefaultLocation.trim(),
    greenhouseApiBaseUrl: state.jobProviderForm.greenhouseApiBaseUrl.trim(),
    greenhouseMaxPages: state.jobProviderForm.greenhouseMaxPages,
    greenhouseBoards: collections.greenhouseBoards,
    leverApiBaseUrl: state.jobProviderForm.leverApiBaseUrl.trim(),
    leverMaxPages: state.jobProviderForm.leverMaxPages,
    leverCompanies: collections.leverCompanies,
    companyBoardApiTemplates: collections.companyBoardApiTemplates,
    companyBoards: collections.companyBoards,
    gamingPortals: collections.gamingPortals,
  };
}

function createHandleSaveJobProviders(state: SettingsPageState) {
  return async () => {
    const payload = buildJobProvidersPayload(state);
    if (!payload) {
      state.jobProvidersSaveState.value = "error";
      state.$toast.error(state.t("settings.jobIntelligence.errors.invalidProviderConfig"));
      return;
    }
    await runStatefulSave({
      state: state.jobProvidersSaveState,
      task: state.updateSettings({
        automationSettings: { ...state.automationForm, jobProviders: payload },
      }),
      failureMessage: state.t("settings.jobIntelligence.errors.failedToSaveProviders"),
      successMessage: state.t("settings.jobIntelligence.toasts.providersSaved"),
      toast: state.$toast,
    });
  };
}

function buildJobTaxonomyPayload(state: SettingsPageState) {
  const keywords = parseJson(
    state.jobTaxonomyForm.keywordsJson,
    z.array(jobTaxonomyKeywordEntrySchema),
  );
  const studioRules = parseJson(
    state.jobTaxonomyForm.studioRulesJson,
    z.array(studioClassificationRuleSchema),
  );
  if (!(keywords && studioRules)) return null;

  return { keywords, studioRules };
}

function createHandleSaveJobTaxonomy(state: SettingsPageState) {
  return async () => {
    const payload = buildJobTaxonomyPayload(state);
    if (!payload) {
      state.jobTaxonomySaveState.value = "error";
      state.$toast.error(state.t("settings.jobIntelligence.errors.invalidTaxonomy"));
      return;
    }
    await runStatefulSave({
      state: state.jobTaxonomySaveState,
      task: state.updateJobTaxonomy(payload),
      failureMessage: state.t("settings.jobIntelligence.errors.failedToSaveTaxonomy"),
      successMessage: state.t("settings.jobIntelligence.toasts.taxonomySaved"),
      toast: state.$toast,
    });
  };
}

function createHandleSaveEmailDeliverySettings(state: SettingsPageState) {
  return async () => {
    const senderEmail = state.emailTransportForm.fromEmail.trim();
    if (senderEmail.length > 0 && !isValidEmail(senderEmail)) {
      state.$toast.error(state.t("settings.errors.invalidEmailDeliverySender"));
      return;
    }
    const savedEmailDelivery = await runToastTask(
      state.updateSettings({
        emailTransportSettings: {
          ...state.emailTransportForm,
          host: state.emailTransportForm.host.trim(),
          username: state.emailTransportForm.username.trim(),
          fromEmail: senderEmail,
          fromName: state.emailTransportForm.fromName.trim(),
        },
      }),
      state.t("settings.errors.failedToSaveEmailDelivery"),
      state.$toast,
    );
    if (savedEmailDelivery !== null)
      state.$toast.success(state.t("settings.toasts.emailDeliverySaved"));
