import { safeParseJson } from "@bao/shared/utils/json";
import { isRecord } from "@bao/shared/utils/type-guards";

export type JobApplyAutomationAction = {
  action: "job_apply";
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
};

const JOB_APPLY_ACTION_PATTERN = /\{"action"\s*:\s*"job_apply"[^{}]*\}/u;

/**
 * Extracts a confirmed job_apply automation payload from assistant chat text.
 * System prompt emits a JSON action block only after user confirmation.
 */
export function parseJobApplyAutomationAction(content: string): JobApplyAutomationAction | null {
  const match = content.match(JOB_APPLY_ACTION_PATTERN);
  if (!match?.[0]) {
    return null;
  }
  const parsed = safeParseJson(match[0]);
  if (!isRecord(parsed) || parsed.action !== "job_apply") {
    return null;
  }
  const jobUrl = typeof parsed.jobUrl === "string" ? parsed.jobUrl.trim() : "";
  const resumeId = typeof parsed.resumeId === "string" ? parsed.resumeId.trim() : "";
  if (!jobUrl || !resumeId) {
    return null;
  }
  const coverLetterId =
    typeof parsed.coverLetterId === "string" && parsed.coverLetterId.trim().length > 0
      ? parsed.coverLetterId.trim()
      : undefined;
  const jobId =
    typeof parsed.jobId === "string" && parsed.jobId.trim().length > 0
      ? parsed.jobId.trim()
      : undefined;
  return {
    action: "job_apply",
    jobUrl,
    resumeId,
    ...(coverLetterId ? { coverLetterId } : {}),
    ...(jobId ? { jobId } : {}),
  };
}

import type {
  ApiEndpoint,
  ApiEndpointGroup,
  OpenApiOperation,
  OpenApiParameter,
  OpenApiRequestBody,
  OpenApiSpec,
} from "~/types/api-docs";
import { isRecord } from "@bao/shared/utils/type-guards";
import {
  getOperationParameters,
  getPathParameters,
  readOpenApiRequestBody,
  readOpenApiResponses,
} from "~/utils/api-docs-openapi";
import {
  API_DOCS_HTTP_METHODS_ORDER,
  isApiHttpMethod,
  normalizeApiDocsPathForId,
} from "~/utils/api-docs-status";

type ApiPayload = Parameters<typeof isRecord>[0];

const dedupeCaseInsensitiveStrings = (values: readonly string[]): string[] => {
  const seen = new Set<string>();
  const output: string[] = [];
  for (const value of values) {
    const normalized = value.trim();
    if (!normalized) {
      continue;
    }

    const key = normalized.toLowerCase();
    if (seen.has(key)) {
      continue;
    }

    seen.add(key);
    output.push(normalized);
  }
  return output;
};

const collectPathParameters = (path: string): string[] => {
  const names: string[] = [];
  const pattern = /\{([^}]+)\}/gu;
  for (const match of path.matchAll(pattern)) {
    const value = match[1];
    if (typeof value === "string" && value.trim().length > 0) {
      names.push(value.trim());
    }
  }
  return names;
};

const collectParameters = (
  parameters: readonly OpenApiParameter[],
  inValue: OpenApiParameter["in"],
): OpenApiParameter[] => {
  const filtered = parameters.filter((parameter) => parameter.in === inValue);
  const unique = new Map<string, OpenApiParameter>();
  for (const parameter of filtered) {
    const key = `${parameter.in}:${parameter.name.toLowerCase()}`;
    if (!unique.has(key)) {
      unique.set(key, parameter);
    }
  }
  return Array.from(unique.values());
};

const getRequestBodyTemplate = (requestBody: OpenApiRequestBody | undefined): string => {
  const content = requestBody?.content;
  if (!content) {
    return "";
  }

  const jsonBody = content["application/json"];
  if (!(jsonBody && typeof jsonBody === "object")) {
    return "";
  }

  const firstExample =
    jsonBody.examples && typeof jsonBody.examples === "object"
      ? Object.values(jsonBody.examples)[0]
      : undefined;
  const candidate = jsonBody.example ?? firstExample?.value;
  return candidate === undefined ? "" : JSON.stringify(candidate, null, 2);
};

const readOpenApiOperation = (
  value: ApiPayload,
  pathParameters: readonly OpenApiParameter[],
): OpenApiOperation | null => {
  if (!isRecord(value)) {
    return null;
  }

  return {
    operationId: typeof value.operationId === "string" ? value.operationId : undefined,
    summary: typeof value.summary === "string" ? value.summary : undefined,
    description: typeof value.description === "string" ? value.description : undefined,
    tags: Array.isArray(value.tags)
      ? value.tags.filter((tag): tag is string => typeof tag === "string")
      : undefined,
    deprecated: typeof value.deprecated === "boolean" ? value.deprecated : undefined,
    parameters: getOperationParameters(value, pathParameters),
    requestBody: readOpenApiRequestBody(value.requestBody),
    responses: readOpenApiResponses(value.responses),
  };
};

const collectEndpointsForPath = (
  path: string,
  pathItem: ApiPayload,
  unknownTagLabel: string,
): ApiEndpoint[] => {
  if (!isRecord(pathItem)) {
    return [];
  }

  const pathParameters = getPathParameters(pathItem);
  const pathParameterNames = dedupeCaseInsensitiveStrings(collectPathParameters(path));
  const endpoints: ApiEndpoint[] = [];

  for (const method of API_DOCS_HTTP_METHODS_ORDER) {
    const operation = readOpenApiOperation(pathItem[method], pathParameters);
    if (!(operation && isApiHttpMethod(method))) {
      continue;
    }

    const endpointTags = dedupeCaseInsensitiveStrings(operation.tags ?? []);
    const groupLabel = endpointTags[0] ?? unknownTagLabel;
    endpoints.push({
      id: `${groupLabel.toLowerCase().replace(/\s+/gu, "-")}-${method}-${normalizeApiDocsPathForId(path)}`,
      path,
      method,
      operation,
      groupLabel,
      pathParameters: pathParameterNames,
      queryParameters: collectParameters(operation.parameters ?? [], "query"),
      requestBodyTemplate: getRequestBodyTemplate(operation.requestBody),
      requestBodyRequired: Boolean(operation.requestBody?.required),
    });
  }

  return endpoints;
};

export const buildApiEndpointGroups = (
  spec: OpenApiSpec | null,
  unknownTagLabel: string,
): ApiEndpointGroup[] => {
  if (!spec?.paths) {
    return [];
  }

  const grouped = new Map<string, ApiEndpoint[]>();
  for (const [path, pathItem] of Object.entries(spec.paths)) {
    for (const endpoint of collectEndpointsForPath(path, pathItem, unknownTagLabel)) {
      const groupEndpoints = grouped.get(endpoint.groupLabel);
      if (groupEndpoints) {
        groupEndpoints.push(endpoint);
        continue;
      }

      grouped.set(endpoint.groupLabel, [endpoint]);
    }
  }

  return Array.from(grouped.entries())
    .sort((left, right) => left[0].localeCompare(right[0]))
    .map(([label, endpoints]) => ({
      id: normalizeApiDocsPathForId(label),
      label,
      endpoints: endpoints.sort((left, right) => {
        const methodOrder =
          API_DOCS_HTTP_METHODS_ORDER.indexOf(left.method) -
          API_DOCS_HTTP_METHODS_ORDER.indexOf(right.method);
        return methodOrder !== 0 ? methodOrder : left.path.localeCompare(right.path);
      }),
    }));
};

export const resolveApiDocsPathWithParameters = (
  endpoint: ApiEndpoint,
  values: Record<string, string>,
): string | null => {
  let outputPath = endpoint.path;
  for (const name of endpoint.pathParameters) {
    const value = values[name]?.trim() ?? "";
    if (value.length === 0) {
      return null;
    }

    outputPath = outputPath.replace(`{${name}}`, encodeURIComponent(value));
  }
  return outputPath;
};

export const buildApiDocsQueryString = (
  queryParameters: readonly OpenApiParameter[],
  values: Record<string, string>,
): string => {
  const urlSearch = new URLSearchParams();
  for (const parameter of queryParameters) {
    const value = values[parameter.name]?.trim();
    if (!value) {
      continue;
    }
    urlSearch.append(parameter.name, value);
  }

  const serialized = urlSearch.toString();
  return serialized.length > 0 ? `?${serialized}` : "";
};

import { ref } from "vue";

type ClientLogLevel = "debug" | "info" | "warn" | "error";

type ClientLogger = {
  debug: (...values: unknown[]) => void;
  info: (...values: unknown[]) => void;
  warn: (...values: unknown[]) => void;
  error: (...values: unknown[]) => void;
};

const debugLogEnabled = ref(true);

/**
 * Create a client-side logger that avoids direct console output.
 */
export function createClientLogger(scope: string): ClientLogger {
  const emit = (level: ClientLogLevel, values: unknown[]) => {
    if (!(import.meta.client && debugLogEnabled.value)) {
      return;
    }

    window.dispatchEvent(
      new CustomEvent("baobuildbuddy:diagnostic", {
        detail: {
          scope,
          level,
          values,
          timestamp: Date.now(),
        },
      }),
    );
  };

  return {
    debug: (...values: unknown[]) => {
      emit("debug", values);
    },
    info: (...values: unknown[]) => {
      emit("info", values);
    },
    warn: (...values: unknown[]) => {
      emit("warn", values);
    },
    error: (...values: unknown[]) => {
      emit("error", values);
    },
  };
}

import type { ApiDocsUiState, ApiHttpMethod } from "~/types/api-docs";
import {
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_TOO_MANY_REQUESTS,
  HTTP_STATUS_UNAUTHORIZED,
} from "@bao/shared/constants/http";
import { isRecord } from "@bao/shared/utils/type-guards";

type ApiPayload = Parameters<typeof isRecord>[0];

export const API_DOCS_HTTP_METHODS_ORDER = [
  "get",
  "post",
  "put",
  "patch",
  "delete",
  "head",
  "options",
  "trace",
] as const satisfies readonly ApiHttpMethod[];

export const isApiHttpMethod = (value: string): value is ApiHttpMethod =>
  API_DOCS_HTTP_METHODS_ORDER.some((method) => method === value);

export const toErrorStatusCode = (error: ApiPayload): number | null => {
  if (!isRecord(error)) {
    return null;
  }

  const status = error.status;
  if (typeof status === "number") {
    return status;
  }

  const statusCode = error.statusCode;
  return typeof statusCode === "number" ? statusCode : null;
};

export const toApiDocsUiStateFromStatusCode = (statusCode: number | null): ApiDocsUiState => {
  if (statusCode === HTTP_STATUS_UNAUTHORIZED) {
    return "unauthorized";
  }

  if (
    statusCode === null ||
    statusCode >= HTTP_STATUS_INTERNAL_SERVER_ERROR ||
    statusCode === HTTP_STATUS_TOO_MANY_REQUESTS
  ) {
    return "errorRetryable";
  }

  return "errorNonRetryable";
};

export const normalizeApiDocsPathForId = (path: string): string =>
  path
    .toLowerCase()
    .replace(/[^a-z0-9]+/giu, "-")
    .replace(/(^-|-$)/gu, "") || "root";

export const getApiDocsParameterValueDefault = (value: ApiPayload): string => {
  if (typeof value === "string") {
    return value;
  }

  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  return "";
};

import {
  AI_PROVIDER_CATALOG,
  AI_PROVIDER_DEFAULT,
  AI_PROVIDER_DEFAULT_ORDER,
  type AIProviderMetadata,
  LOCAL_AI_DEFAULT_ENDPOINT,
  LOCAL_AI_RECOMMENDED_MODELS,
} from "@bao/shared/constants/ai-provider";
import type { AIProviderDiagnostic, AIProviderType, AIRoutingPurpose } from "@bao/shared/types/ai";
import type { AIProviderDiagnostics } from "@bao/shared/types/settings-contracts";
import { isRecord } from "@bao/shared/utils/type-guards";

type ApiPayload = Parameters<typeof isRecord>[0];

type AppSettingsSnapshot = {
  readonly preferredProvider?: string | null;
  readonly preferredModel?: string | null;
  readonly localModelName?: string | null;
  readonly localModelEndpoint?: string | null;
  readonly hasLocalKey?: boolean;
  readonly hasGeminiKey?: boolean;
  readonly hasOpenaiKey?: boolean;
  readonly hasClaudeKey?: boolean;
  readonly hasHuggingfaceToken?: boolean;
  readonly providerDiagnostics?: AIProviderDiagnostics | null;
  readonly aiRouting?: Partial<
    Record<
      AIRoutingPurpose,
      {
        readonly provider?: AIProviderType;
        readonly model?: string | null;
      }
    >
  > | null;
};

const providerCatalogById = new Map<AIProviderType, AIProviderMetadata>(
  AI_PROVIDER_CATALOG.map<[AIProviderType, AIProviderMetadata]>((provider) => [
    provider.id,
    provider,
  ]),
);

const isProviderId = (value: string): value is AIProviderType =>
  AI_PROVIDER_CATALOG.some((provider) => provider.id === value);

const resolveNonEmptyString = (value?: string | null): string => value?.trim() ?? "";

const uniqueNonEmptyStrings = (values: Iterable<string | null | undefined>): string[] => {
  const ordered = new Set<string>();
  for (const value of values) {
    const trimmed = resolveNonEmptyString(value);
    if (trimmed.length > 0) {
      ordered.add(trimmed);
    }
  }
  return [...ordered];
};

const resolvePreferredProviderId = (value?: string | null): AIProviderType => {
  const candidate = resolveNonEmptyString(value);
  return candidate && isProviderId(candidate) ? candidate : AI_PROVIDER_DEFAULT;
};

const asString = (value: ApiPayload): string | undefined =>
  typeof value === "string" ? value : undefined;

const asBoolean = (value: ApiPayload): boolean | undefined =>
  typeof value === "boolean" ? value : undefined;

const asStringArray = (value: ApiPayload): string[] =>
  Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === "string") : [];

const providerHealthValues = new Set(["healthy", "degraded", "down", "unconfigured"]);

const isProviderHealth = (value: string): value is AIProviderHealth =>
  providerHealthValues.has(value);

const hasExplicitOverride = (value: string | null | undefined): boolean =>
  value !== undefined && value !== null;

const resolveLocalConfiguredModel = (
  settings: AppSettingsSnapshot | null | undefined,
  model?: string | null,
): string =>
  hasExplicitOverride(model)
    ? resolveNonEmptyString(model)
    : resolveNonEmptyString(settings?.localModelName);

const resolveLocalEndpoint = (
  settings: AppSettingsSnapshot | null | undefined,
  endpoint?: string | null,
): string =>
  hasExplicitOverride(endpoint)
    ? resolveNonEmptyString(endpoint) || LOCAL_AI_DEFAULT_ENDPOINT
    : resolveNonEmptyString(settings?.localModelEndpoint) || LOCAL_AI_DEFAULT_ENDPOINT;

const resolveLocalDiagnosticCode = (
  diagnostics: AIProviderDiagnostic | undefined,
  testResult?: ClientProviderTestResult | null,
): AIProviderDiagnostic["code"] | "unconfigured" => {
  if (testResult) {
    return testResult.valid ? "healthy" : (testResult.diagnosticCode ?? "error");
  }
  return diagnostics?.code ?? "unconfigured";
};

const resolveLocalAvailableModels = (
  diagnostics: AIProviderDiagnostic | undefined,
  testResult?: ClientProviderTestResult | null,
): string[] =>
  uniqueNonEmptyStrings([
    testResult?.selectedModel,
    ...(testResult?.availableModels ?? []),
    diagnostics?.selectedModel,
    ...(diagnostics?.availableModels ?? []),
    ...LOCAL_AI_RECOMMENDED_MODELS,
  ]);

const resolveLocalSelectedModel = (
  configuredModel: string,
  availableModels: readonly string[],
  diagnostics: AIProviderDiagnostic | undefined,
  testResult?: ClientProviderTestResult | null,
): string =>
  configuredModel ||
  resolveNonEmptyString(testResult?.selectedModel) ||
  resolveNonEmptyString(diagnostics?.selectedModel) ||
  availableModels[0] ||
  "";

/**
 * Client-facing provider test result fields returned by the settings test endpoint.
 */
export interface ClientProviderTestResult {
  valid: boolean;
  diagnosticCode?: AIProviderDiagnostic["code"];
  message?: string;
  availableModels?: string[];
  selectedModel?: string;
}

/**
 * Normalized provider/model pair resolved from persisted AI routing settings.
 */
export interface AIRoutingPreferenceState {
  provider: AIProviderType;
  model: string;
}

/**
 * Canonical local-provider readiness and model-selection state for client surfaces.
 */
export interface LocalProviderState {
  endpoint: string;
  configuredModel: string;
  selectedModel: string;
  availableModels: string[];
  diagnosticCode: AIProviderDiagnostic["code"] | "unconfigured";
  message?: string;
  isHealthy: boolean;
}

/**
 * Canonical client-side provider health values rendered across AI surfaces.
 */
export type AIProviderHealth = "healthy" | "degraded" | "down" | "unconfigured";

/**
 * Canonical normalized provider row returned to AI dashboard and settings surfaces.
 */
export interface AIProviderRow {
  id: AIProviderType;
  iconId: AIProviderType;
  models: string[];
  available: boolean;
  health: AIProviderHealth;
}

/**
 * Looks up the canonical provider catalog row.
 */
export function resolveProviderMetadata(
  providerId: AIProviderType,
): AIProviderMetadata | undefined {
  return providerCatalogById.get(providerId);
}

/**
 * Returns a stable provider-diagnostics map from persisted settings.
 */
export function resolveProviderDiagnostics(
  settings?: AppSettingsSnapshot | null,
): AIProviderDiagnostics {
  return settings?.providerDiagnostics ?? {};
}

/**
 * Resolves whether the given provider is configured from the canonical settings payload.
 */
export function isProviderConfigured(
  settings: AppSettingsSnapshot | null | undefined,
  providerId: AIProviderType,
): boolean {
  if (!settings) {
    return false;
  }

  if (providerId === "local") {
    return settings.hasLocalKey ?? resolveNonEmptyString(settings.localModelEndpoint).length > 0;
  }
  if (providerId === "gemini") {
    return Boolean(settings.hasGeminiKey);
  }
  if (providerId === "openai") {
    return Boolean(settings.hasOpenaiKey);
  }
  if (providerId === "claude") {
    return Boolean(settings.hasClaudeKey);
  }
  return Boolean(settings.hasHuggingfaceToken);
}

/**
 * Resolves the canonical provider/model selection for one AI routing purpose.
 */
export function resolveAIRoutingPreference(
  settings: AppSettingsSnapshot | null | undefined,
  purpose: AIRoutingPurpose = "chat",
): AIRoutingPreferenceState {
  const preferredProvider = resolvePreferredProviderId(settings?.preferredProvider);
  const routedTarget = settings?.aiRouting?.[purpose];
  const provider = resolvePreferredProviderId(routedTarget?.provider ?? preferredProvider);
  const model =
    resolveNonEmptyString(routedTarget?.model) ||
    (purpose === "chat" ? resolveNonEmptyString(settings?.preferredModel) : "");

  return {
    provider,
    model,
  };
}

/**
 * Builds the ordered model-option list for one provider from diagnostics, routing, and catalog hints.
 */
export function resolveProviderModelOptions(
  providerId: AIProviderType,
  settings: AppSettingsSnapshot | null | undefined,
  extraModels: readonly string[] = [],
): string[] {
  const diagnostics = resolveProviderDiagnostics(settings)[providerId];
  const chatRouting = resolveAIRoutingPreference(settings, "chat");
  const catalogEntry = providerCatalogById.get(providerId);

  return uniqueNonEmptyStrings([
    ...(chatRouting.provider === providerId ? [chatRouting.model] : []),
    ...(settings?.preferredProvider === providerId ? [settings?.preferredModel] : []),
    diagnostics?.selectedModel,
    ...(diagnostics?.availableModels ?? []),
    ...extraModels,
    ...(catalogEntry?.modelHints ?? []),
  ]);
}

/**
 * Resolves the currently selected model for a provider from the canonical routing contract.
 */
export function resolveProviderModelSelection(
  providerId: AIProviderType,
  settings: AppSettingsSnapshot | null | undefined,
  extraModels: readonly string[] = [],
): string {
  const chatRouting = resolveAIRoutingPreference(settings, "chat");
  if (chatRouting.provider === providerId && chatRouting.model.length > 0) {
    return chatRouting.model;
  }

  return resolveProviderModelOptions(providerId, settings, extraModels)[0] ?? "";
}

const normalizeProviderRow = (
  row: ApiPayload,
  settings: AppSettingsSnapshot | null | undefined,
): AIProviderRow | null => {
  if (!isRecord(row)) {
    return null;
  }

  const rawId = asString(row.id);
  if (!(rawId && isProviderId(rawId))) {
    return null;
  }

  const catalogEntry = resolveProviderMetadata(rawId);
  if (!catalogEntry) {
    return null;
  }

  const available = asBoolean(row.available) ?? isProviderConfigured(settings, rawId);
  const rawHealth = asString(row.health);
  let health: AIProviderHealth = "unconfigured";
  if (rawHealth && isProviderHealth(rawHealth)) {
    health = rawHealth;
  } else if (available) {
    health = "healthy";
  }
  const models = asStringArray(row.models);

  return {
    id: rawId,
    iconId: catalogEntry.iconId,
    models: models.length > 0 ? models : [...catalogEntry.modelHints],
    available,
    health,
  };
};

/**
 * Normalizes provider rows from the canonical shared AI models payload shape.
 */
export function normalizeProviderRows(
  value: ApiPayload,
  settings: AppSettingsSnapshot | null | undefined,
): AIProviderRow[] {
  if (!isRecord(value)) {
    return [];
  }

  const rows = Array.isArray(value.providers) ? value.providers : [];
  return rows
    .map((row) => normalizeProviderRow(row, settings))
    .filter((provider): provider is AIProviderRow => provider !== null);
}

/**
 * Builds fallback provider rows when diagnostics are unavailable.
 */
export function buildFallbackProviderRows(
  settings: AppSettingsSnapshot | null | undefined,
): AIProviderRow[] {
  return AI_PROVIDER_DEFAULT_ORDER.map((providerId) => {
    const catalogEntry = resolveProviderMetadata(providerId);

    return {
      id: providerId,
      iconId: catalogEntry?.iconId ?? providerId,
      models: catalogEntry ? [...catalogEntry.modelHints] : [],
      available: isProviderConfigured(settings, providerId),
      health: isProviderConfigured(settings, providerId) ? "degraded" : "unconfigured",
    };
  });
}

/**
 * Resolves the local-provider endpoint, model, and diagnostics into one stable presentation state.
 */
export function resolveLocalProviderState(options: {
  settings?: AppSettingsSnapshot | null;
  endpoint?: string | null;
  model?: string | null;
  diagnostic?: AIProviderDiagnostic | null;
  testResult?: ClientProviderTestResult | null;
}): LocalProviderState {
  const diagnostics =
    options.diagnostic ?? resolveProviderDiagnostics(options.settings).local ?? undefined;
  const configuredModel = resolveLocalConfiguredModel(options.settings, options.model);
  const availableModels = resolveLocalAvailableModels(diagnostics, options.testResult);
  const selectedModel = resolveLocalSelectedModel(
    configuredModel,
    availableModels,
    diagnostics,
    options.testResult,
  );
  const diagnosticCode = resolveLocalDiagnosticCode(diagnostics, options.testResult);

  return {
    endpoint: resolveLocalEndpoint(options.settings, options.endpoint),
    configuredModel,
    selectedModel,
    availableModels,
    diagnosticCode,
    message: options.testResult?.message ?? diagnostics?.message,
    isHealthy: diagnosticCode === "healthy",
  };
}

import type { GamingPortalConfig } from "@bao/shared/types/settings";
import { safeParseJson } from "@bao/shared/utils/json";
import { isRecord } from "@bao/shared/utils/type-guards";

type ApiPayload = Parameters<typeof isRecord>[0];

const readString = (value: ApiPayload, fallback = ""): string =>
  typeof value === "string" ? value : fallback;

const readBoolean = (value: ApiPayload, fallback = false): boolean =>
  typeof value === "boolean" ? value : fallback;

/**
 * Parses the settings gaming-portals JSON textarea into typed portal rows.
 * Invalid JSON or non-array payloads return an empty list (caller keeps raw text).
 */
export function parseGamingPortalsJson(raw: string): GamingPortalConfig[] {
  const parsed = safeParseJson(raw);
  if (!Array.isArray(parsed)) {
    return [];
  }

  const portals: GamingPortalConfig[] = [];
  for (const entry of parsed) {
    if (!isRecord(entry)) {
      continue;
    }
    const id = readString(entry.id);
    if (!id) {
      continue;
    }
    portals.push({
      id: id as GamingPortalConfig["id"],
      name: readString(entry.name, id),
      source: readString(entry.source, id),
      fallbackUrl: readString(entry.fallbackUrl),
      enabled: readBoolean(entry.enabled),
    });
  }
  return portals;
}

/**
 * Serializes portal rows back to the settings JSON textarea format.
 */
export function serializeGamingPortalsJson(portals: readonly GamingPortalConfig[]): string {
  return JSON.stringify(portals, null, 2);
}

/**
 * Returns a new portal list with one portal's enabled flag flipped.
 */
export function setGamingPortalEnabled(
  portals: readonly GamingPortalConfig[],
  portalId: string,
  enabled: boolean,
): GamingPortalConfig[] {
  return portals.map((portal) =>
    portal.id === portalId
      ? {
          ...portal,
          enabled,
        }
      : portal,
  );
}

/**
 * Count of portals that are both enabled and have a fallback URL (matches RPA audit configured).
 */
export function countConfiguredGamingPortals(portals: readonly GamingPortalConfig[]): number {
  return portals.filter((portal) => portal.enabled && portal.fallbackUrl.trim().length > 0).length;
}

import { describe, expect, test } from "vitest";
import {
  queryValueToOptionalString,
  queryValueToString,
  resolveRouteSectionId,
} from "./route-query";

const isSection = (value: string): value is "a" | "b" => value === "a" || value === "b";

describe("route-query SSOT", () => {
  test("queryValueToString handles string, array, and empty", () => {
    expect(queryValueToString("profile")).toBe("profile");
    expect(queryValueToString(["profile", "other"])).toBe("profile");
    expect(queryValueToString([null])).toBe("");
    expect(queryValueToString(undefined)).toBe("");
    expect(queryValueToString(null)).toBe("");
  });

  test("queryValueToOptionalString nulls empty", () => {
    expect(queryValueToOptionalString("x")).toBe("x");
    expect(queryValueToOptionalString("")).toBeNull();
    expect(queryValueToOptionalString(undefined)).toBeNull();
  });

  test("resolveRouteSectionId uses allowlist + default", () => {
    expect(resolveRouteSectionId("b", isSection, "a")).toBe("b");
    expect(resolveRouteSectionId("z", isSection, "a")).toBe("a");
    expect(resolveRouteSectionId(["b"], isSection, "a")).toBe("b");
    expect(resolveRouteSectionId(undefined, isSection, "a")).toBe("a");
  });
});

import { API_ENDPOINT_PREFIX } from "@bao/shared/constants/endpoints";

const ABSOLUTE_HTTP_URL_PATTERN = /^https?:\/\//i;
const ABSOLUTE_WS_URL_PATTERN = /^wss?:\/\//i;
const TRAILING_SLASH_PATTERN = /\/$/u;
const HTTPS_PROTOCOL_PATTERN = /^https:/i;
const HTTP_PROTOCOL_PATTERN = /^http:/i;

/**
 * Resolves runtime API base from public config and current request URL.
 *
 * @param configuredBase Runtime-configured API base.
 * @param requestUrl Current request URL.
 * @returns Absolute, normalized base URL without trailing slash.
 */
export function resolveApiBase(configuredBase: string, requestUrl: URL): string {
  const baseUrl = ABSOLUTE_HTTP_URL_PATTERN.test(configuredBase)
    ? configuredBase
    : new URL(configuredBase, requestUrl).toString();
  return baseUrl.replace(TRAILING_SLASH_PATTERN, "");
}

/**
 * Resolves the route client base used by Eden Treaty.
 *
 * Treaty route helpers already include the canonical API endpoint prefix, so
 * the base must stop at the parent path or requests will drift to a duplicated
 * API segment.
 *
 * @param configuredBase Runtime-configured API base.
 * @param requestUrl Current request URL.
 * @returns Absolute route client base without a trailing slash.
 */
export function resolveApiRouteBase(configuredBase: string, requestUrl: URL): string {
  const resolvedBase = resolveApiBase(configuredBase, requestUrl);
  const parsedUrl = new URL(resolvedBase);
  const normalizedPath = parsedUrl.pathname.replace(TRAILING_SLASH_PATTERN, "");
  let routeBasePath = parsedUrl.pathname;
  if (normalizedPath === API_ENDPOINT_PREFIX) {
    routeBasePath = "/";
  } else if (normalizedPath.endsWith(API_ENDPOINT_PREFIX)) {
    routeBasePath = normalizedPath.slice(0, -API_ENDPOINT_PREFIX.length) || "/";
  }

  parsedUrl.pathname = routeBasePath;
  return parsedUrl.toString().replace(TRAILING_SLASH_PATTERN, "");
}

/**
 * Resolves an API endpoint URL against the configured runtime API base.
 *
 * When the base already ends in the API prefix, matching endpoint paths are de-duplicated.
 *
 * @param configuredBase Runtime-configured API base.
 * @param requestUrl Current request URL.
 * @param endpointPath Canonical endpoint path.
 * @returns Absolute endpoint URL.
 */
export function resolveApiEndpoint(
  configuredBase: string,
  requestUrl: URL,
  endpointPath: string,
): string {
  const resolvedBase = resolveApiBase(configuredBase, requestUrl);
  const normalizedPath = endpointPath.startsWith("/") ? endpointPath : `/${endpointPath}`;
  const resolvedBasePath = new URL(resolvedBase).pathname.replace(TRAILING_SLASH_PATTERN, "");
  const baseIncludesApiPrefix =
    resolvedBasePath === API_ENDPOINT_PREFIX || resolvedBasePath.endsWith(API_ENDPOINT_PREFIX);
  const targetPath =
    baseIncludesApiPrefix && normalizedPath.startsWith(`${API_ENDPOINT_PREFIX}/`)
      ? normalizedPath.slice(API_ENDPOINT_PREFIX.length)
      : normalizedPath;
  return `${resolvedBase}${targetPath}`;
}

/**
 * Resolves a WebSocket endpoint URL from runtime config and request context.
 *
 * @param configuredBase Runtime-configured WebSocket or API base.
 * @param requestUrl Current request URL.
 * @param endpointPath Canonical WebSocket endpoint path.
 * @returns Absolute WebSocket URL.
 */
export function resolveWebSocketEndpoint(
  configuredBase: string,
  requestUrl: URL,
  endpointPath: string,
): string {
  const resolvedBase = resolveApiBase(configuredBase, requestUrl);
  const normalizedBase = resolvedBase.endsWith("/") ? resolvedBase.slice(0, -1) : resolvedBase;
  let wsBase = normalizedBase;
  if (!ABSOLUTE_WS_URL_PATTERN.test(normalizedBase)) {
    if (requestUrl.protocol === "https:") {
      wsBase = normalizedBase
        .replace(HTTPS_PROTOCOL_PATTERN, "wss:")
        .replace(HTTP_PROTOCOL_PATTERN, "wss:");
    } else {
      wsBase = normalizedBase
        .replace(HTTPS_PROTOCOL_PATTERN, "ws:")
        .replace(HTTP_PROTOCOL_PATTERN, "ws:");
    }
  }
  const normalizedPath = endpointPath.startsWith("/") ? endpointPath : `/${endpointPath}`;
  return `${wsBase}${normalizedPath}`;
}

import type {
  OpenApiMediaType,
  OpenApiParameter,
  OpenApiRequestBody,
  OpenApiResponse,
  OpenApiSpec,
} from "~/types/api-docs";
import { isRecord } from "@bao/shared/utils/type-guards";

type ApiPayload = Parameters<typeof isRecord>[0];

const isOpenApiParameterIn = (value: ApiPayload): value is OpenApiParameter["in"] =>
  value === "path" || value === "query" || value === "header" || value === "cookie";

const toOpenApiMediaExamples = (
  value: ApiPayload,
): Record<string, { value?: ApiPayload }> | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const output: Record<string, { value?: ApiPayload }> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (!isRecord(entry)) {
      continue;
    }

    output[key] = entry.value !== undefined ? { value: entry.value } : {};
  }

  return Object.keys(output).length > 0 ? output : undefined;
};

const toOpenApiMediaType = (value: ApiPayload): OpenApiMediaType | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const parsed: OpenApiMediaType = {};
  if (value.example !== undefined) {
    parsed.example = value.example;
  }

  if (isRecord(value.schema)) {
    parsed.schema = value.schema;
  }

  const examples = toOpenApiMediaExamples(value.examples);
  if (examples) {
    parsed.examples = examples;
  }

  return Object.keys(parsed).length > 0 ? parsed : undefined;
};

const toOpenApiMediaTypeMap = (value: ApiPayload): Record<string, OpenApiMediaType> | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const output: Record<string, OpenApiMediaType> = {};
  for (const [key, entry] of Object.entries(value)) {
    const parsed = toOpenApiMediaType(entry);
    if (parsed) {
      output[key] = parsed;
    }
  }

  return Object.keys(output).length > 0 ? output : undefined;
};

const toOpenApiRequestBody = (value: ApiPayload): OpenApiRequestBody | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const requestBody: OpenApiRequestBody = {
    required: typeof value.required === "boolean" ? value.required : undefined,
  };
  const content = toOpenApiMediaTypeMap(value.content);
  if (content) {
    requestBody.content = content;
  }

  return requestBody.required !== undefined || requestBody.content ? requestBody : undefined;
};

const toOpenApiResponses = (value: ApiPayload): Record<string, OpenApiResponse> | undefined => {
  if (!isRecord(value)) {
    return;
  }

  const output: Record<string, OpenApiResponse> = {};
  for (const [statusCode, entry] of Object.entries(value)) {
    if (!isRecord(entry)) {
      continue;
    }

    const response: OpenApiResponse = {
      description: typeof entry.description === "string" ? entry.description : undefined,
    };
    const content = toOpenApiMediaTypeMap(entry.content);
    if (content) {
      response.content = content;
    }
    output[statusCode] = response;
  }

  return Object.keys(output).length > 0 ? output : undefined;
};

const toOpenApiPathMap = (value: ApiPayload): Record<string, Record<string, ApiPayload>> => {
  if (!isRecord(value)) {
    return {};
  }

  const output: Record<string, Record<string, ApiPayload>> = {};
  for (const [path, entry] of Object.entries(value)) {
    if (isRecord(entry)) {
      output[path] = entry;
    }
  }

  return output;
};

export const readOpenApiSpec = (value: ApiPayload): OpenApiSpec | null => {
  if (!isRecord(value)) {
    return null;
  }

  const infoRaw = isRecord(value.info) ? value.info : undefined;
  return {
    openapi: typeof value.openapi === "string" ? value.openapi : undefined,
    info: {
      title: typeof infoRaw?.title === "string" ? infoRaw.title : undefined,
      description: typeof infoRaw?.description === "string" ? infoRaw.description : undefined,
      version: typeof infoRaw?.version === "string" ? infoRaw.version : undefined,
    },
    paths: toOpenApiPathMap(value.paths),
  };
};

const dedupeParameters = (parameters: readonly OpenApiParameter[]): OpenApiParameter[] => {
  const unique = new Map<string, OpenApiParameter>();
  for (const parameter of parameters) {
    const key = `${parameter.in}:${parameter.name.toLowerCase()}`;
    if (!unique.has(key)) {
      unique.set(key, {
        ...parameter,
        name: parameter.name.trim(),
      });
    }
  }

  return Array.from(unique.values()).filter((parameter) => parameter.name.length > 0);
};

export const getPathParameters = (pathItem: Record<string, ApiPayload>): OpenApiParameter[] => {
  const rawParameters: ApiPayload[] = Array.isArray(pathItem.parameters) ? pathItem.parameters : [];
  const normalized = rawParameters
    .filter((parameter): parameter is OpenApiParameter => {
      if (!isRecord(parameter)) {
        return false;
      }

      if (typeof parameter.name !== "string") {
        return false;
      }

      return isOpenApiParameterIn(parameter.in);
    })
    .map((parameter) => ({
      ...parameter,
      name: parameter.name.trim(),
    }));

  return dedupeParameters(normalized);
};

export const getOperationParameters = (
  value: ApiPayload,
  pathParameters: readonly OpenApiParameter[],
): OpenApiParameter[] => {
  if (!isRecord(value)) {
    return [];
  }

  const parameters: ApiPayload[] = Array.isArray(value.parameters) ? value.parameters : [];
  const operationParameters = parameters.filter((parameter): parameter is OpenApiParameter => {
    if (!isRecord(parameter)) {
      return false;
    }

    if (typeof parameter.name !== "string") {
      return false;
    }

    return isOpenApiParameterIn(parameter.in);
  });

  return dedupeParameters([...pathParameters, ...operationParameters]);
};

export const readOpenApiRequestBody = (value: ApiPayload): OpenApiRequestBody | undefined =>
  toOpenApiRequestBody(value);

export const readOpenApiResponses = (
  value: ApiPayload,
): Record<string, OpenApiResponse> | undefined => toOpenApiResponses(value);

import { AI_CHAT_VOICE_DEFAULT_LOCALE } from "@bao/shared/constants/ai-voice";

/**
 * Resolves the browser speech recognition constructor when available.
 *
 * @returns SpeechRecognition constructor or null when unsupported.
 */
export function resolveSpeechRecognitionConstructor(): SpeechRecognitionConstructor | null {
  if (import.meta.server || typeof window === "undefined") {
    return null;
  }

  return window.SpeechRecognition ?? window.webkitSpeechRecognition ?? null;
}

/**
 * Resolves the browser speech synthesis instance when available.
 *
 * @returns SpeechSynthesis instance or null when unsupported.
 */
export function resolveSpeechSynthesis(): SpeechSynthesis | null {
  if (import.meta.server || typeof window === "undefined") {
    return null;
  }

  return typeof window.speechSynthesis === "undefined" ? null : window.speechSynthesis;
}

/**
 * Normalizes a locale for browser speech APIs with a safe fallback.
 *
 * @param locale Preferred locale from UI state.
 * @returns Locale accepted by speech APIs.
 */
export function resolveSpeechLocale(locale?: string | null): string {
  if (typeof locale !== "string") {
    return AI_CHAT_VOICE_DEFAULT_LOCALE;
  }

  const trimmedLocale = locale.trim();
  return trimmedLocale.length > 0 ? trimmedLocale : AI_CHAT_VOICE_DEFAULT_LOCALE;
}

const DEFAULT_LOCALE = "en-US";
const DATE_OPTION_KEYS = ["dateStyle", "weekday", "year", "month", "day", "era"] as const;
const SHARED_OPTION_KEYS = [
  "calendar",
  "formatMatcher",
  "localeMatcher",
  "numberingSystem",
  "timeZone",
] as const;
const TIME_OPTION_KEYS = [
  "timeStyle",
  "hour",
  "minute",
  "second",
  "fractionalSecondDigits",
  "hour12",
  "hourCycle",
  "dayPeriod",
  "timeZoneName",
] as const;

const isReadonlyUnknownArray = (value: unknown): value is readonly unknown[] =>
  Array.isArray(value);

function hasFormattingOption(
  options: Intl.DateTimeFormatOptions,
  keys: readonly (keyof Intl.DateTimeFormatOptions)[],
): boolean {
  return keys.some((key) => options[key] !== undefined);
}

function copyDefinedOptions(
  source: Intl.DateTimeFormatOptions,
  keys: readonly (keyof Intl.DateTimeFormatOptions)[],
): Intl.DateTimeFormatOptions {
  const target: Intl.DateTimeFormatOptions = {};
  for (const key of keys) {
    const value = source[key];
    if (value !== undefined) {
      Reflect.set(target, key, value);
    }
  }
  return target;
}

function buildDateOnlyOptions(options: Intl.DateTimeFormatOptions): Intl.DateTimeFormatOptions {
  return copyDefinedOptions(options, [...SHARED_OPTION_KEYS, ...DATE_OPTION_KEYS]);
}

function buildTimeOnlyOptions(options: Intl.DateTimeFormatOptions): Intl.DateTimeFormatOptions {
  return copyDefinedOptions(options, [...SHARED_OPTION_KEYS, ...TIME_OPTION_KEYS]);
}

/**
 * Resolves a deterministic locale from vue-i18n locale and fallback-locale values.
 */
export function resolvePreferredLocale(localeValue: unknown, fallbackLocaleValue: unknown): string {
  if (typeof localeValue === "string" && localeValue.length > 0) {
    return localeValue;
  }

  if (typeof fallbackLocaleValue === "string" && fallbackLocaleValue.length > 0) {
    return fallbackLocaleValue;
  }

  if (isReadonlyUnknownArray(fallbackLocaleValue)) {
    const firstLocale = fallbackLocaleValue.at(0);
    if (typeof firstLocale === "string" && firstLocale.length > 0) {
      return firstLocale;
    }
  }

  return DEFAULT_LOCALE;
}

/**
 * Formats a date-like value using the resolved locale. Returns `null` when the date is invalid.
 */
export function formatDateWithLocale(
  value: string | Date,
  localeValue: unknown,
  fallbackLocaleValue: unknown,
  options: Intl.DateTimeFormatOptions,
): string | null {
  const parsedDate = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsedDate.getTime())) {
    return null;
  }

  const locale = resolvePreferredLocale(localeValue, fallbackLocaleValue);
  const includesDate = hasFormattingOption(options, DATE_OPTION_KEYS);
  const includesTime = hasFormattingOption(options, TIME_OPTION_KEYS);

  if (includesDate && includesTime) {
    const formattedDate = new Intl.DateTimeFormat(locale, buildDateOnlyOptions(options)).format(
      parsedDate,
    );
    const formattedTime = new Intl.DateTimeFormat(locale, buildTimeOnlyOptions(options)).format(
      parsedDate,
    );

    return `${formattedDate} ${formattedTime}`;
  }

  return new Intl.DateTimeFormat(locale, options).format(parsedDate);
}

import { API_ENDPOINT_PREFIX } from "@bao/shared/constants/endpoints";

const ABSOLUTE_HTTP_URL_PATTERN = /^https?:\/\//iu;
const TRAILING_SLASH_PATTERN = /\/$/u;
const PROXY_WILDCARD_SUFFIX = "/**";

const trimTrailingSlash = (value: string): string => value.replace(TRAILING_SLASH_PATTERN, "");

export function normalizeApiProxyTarget(target: string): string | undefined {
  const trimmedTarget = target.trim();
  if (!(ABSOLUTE_HTTP_URL_PATTERN.test(trimmedTarget) && URL.canParse(trimmedTarget))) {
    return;
  }

  const resolvedTarget = new URL(trimmedTarget);
  const normalizedPath = trimTrailingSlash(resolvedTarget.pathname);
  let pathnameWithApiPrefix = `${normalizedPath}${API_ENDPOINT_PREFIX}`;
  if (normalizedPath.length === 0 || normalizedPath === "/") {
    pathnameWithApiPrefix = API_ENDPOINT_PREFIX;
  } else if (normalizedPath.endsWith(API_ENDPOINT_PREFIX)) {
    pathnameWithApiPrefix = normalizedPath;
  }

  resolvedTarget.pathname = pathnameWithApiPrefix;
  resolvedTarget.search = "";
  resolvedTarget.hash = "";
  return trimTrailingSlash(resolvedTarget.toString());
}

export function buildApiProxyWildcardTarget(target: string): string | undefined {
  const normalizedTarget = normalizeApiProxyTarget(target);
  return normalizedTarget ? `${normalizedTarget}${PROXY_WILDCARD_SUFFIX}` : undefined;
}

import {
  LOCAL_AI_DEFAULT_ENDPOINT,
  LOCAL_AI_DEFAULT_MODEL,
} from "@bao/shared/constants/ai-provider";
import {
  API_KEY_FIELD_BY_PROVIDER,
  CLOUD_PROVIDER_IDS,
} from "~/components/setup/setup-page-contracts";
import { settlePromise } from "~/composables/async-flow";
import { getErrorMessage } from "~/utils/errors";
import type {
  ProviderCredentialState,
  SetupCompletionInput,
  SetupPageActionsContext,
  SetupPageToastApi,
} from "~/utils/setup-page-action-contracts";

const createCompletionInput = (context: SetupPageActionsContext): SetupCompletionInput => ({
  providedApiKey: context.existingApiKey.value.trim(),
  setupToken: context.authSetupToken.value.trim(),
  storedApiKey: context.getStoredApiKey(),
  trimmedName: context.name.value.trim(),
  trimmedRole: context.currentRole.value.trim(),
});

const failSetupAction = (
  saving: SetupPageActionsContext["saving"],
  toast: SetupPageToastApi,
  message: string,
): false => {
  saving.value = false;
  toast.error(message);
  return false;
};

const ensureSetupApiKey = async (
  context: Pick<
    SetupPageActionsContext,
    "authStatus" | "checkAuthStatus" | "initAuth" | "saving" | "setStoredApiKey" | "t" | "toast"
  >,
  input: SetupCompletionInput,
): Promise<SetupPageActionsContext["authStatus"]["value"]> => {
  const nextAuthStatus = context.authStatus.value ?? (await context.checkAuthStatus());
  context.authStatus.value = nextAuthStatus;
  if (!nextAuthStatus.authRequired || input.storedApiKey) return nextAuthStatus;

  if (!nextAuthStatus.bootstrapRequired) {
    if (!input.providedApiKey) {
      failSetupAction(context.saving, context.toast, context.t("setup.auth.apiKeyRequiredError"));
      return null;
    }
    context.setStoredApiKey(input.providedApiKey);
    return nextAuthStatus;
  }

  if (!nextAuthStatus.setupTokenConfigured) {
    failSetupAction(
      context.saving,
      context.toast,
      context.t("setup.auth.bootstrapUnavailableDescription"),
    );
    return null;
  }
  if (!input.setupToken) {
    failSetupAction(context.saving, context.toast, context.t("setup.auth.setupTokenRequiredError"));
    return null;
  }

  const authInitResult = await settlePromise(
    context.initAuth(input.setupToken),
    context.t("apiErrors.auth.initFailed"),
  );
  if (!authInitResult.ok) {
    failSetupAction(
      context.saving,
      context.toast,
      getErrorMessage(authInitResult.error, context.t("apiErrors.auth.initFailed")),
    );
    return null;
  }

  const issuedApiKey = authInitResult.value.apiKey;
  if (typeof issuedApiKey !== "string" || issuedApiKey.length === 0) {
    failSetupAction(context.saving, context.toast, context.t("apiErrors.auth.initFailed"));
    return null;
  }

  context.setStoredApiKey(issuedApiKey);
  return nextAuthStatus;
};

const ensureProfileSaved = async (
  context: Pick<
    SetupPageActionsContext,
    "saving" | "setStoredApiKey" | "t" | "toast" | "updateProfile"
  >,
  input: SetupCompletionInput,
): Promise<boolean> => {
  if (!input.trimmedName) return true;

  const profileUpdateResult = await settlePromise(
    context.updateProfile({
      name: input.trimmedName,
      ...(input.trimmedRole ? { currentRole: input.trimmedRole } : {}),
    }),
    context.t("setup.completeErrorFallback"),
  );
  if (profileUpdateResult.ok) return true;

  if (!input.storedApiKey && input.providedApiKey.length > 0) {
    context.setStoredApiKey(null);
  }
  return failSetupAction(
    context.saving,
    context.toast,
    getErrorMessage(profileUpdateResult.error, context.t("setup.completeErrorFallback")),
  );
};

const hasStoredCloudCredentials = (
  providerCredentials: ProviderCredentialState,
  settings: SetupPageActionsContext["settings"],
): boolean =>
  CLOUD_PROVIDER_IDS.some((provider) => providerCredentials[provider].trim().length > 0) ||
  Boolean(settings.value?.hasGeminiKey) ||
  Boolean(settings.value?.hasOpenaiKey) ||
  Boolean(settings.value?.hasClaudeKey) ||
  Boolean(settings.value?.hasHuggingfaceToken);

const ensureProviderAvailability = async (
  context: Pick<
    SetupPageActionsContext,
    | "localProviderState"
    | "providerCredentials"
    | "providerLabels"
    | "saving"
    | "settings"
    | "t"
    | "testApiKey"
    | "testResults"
    | "toast"
  >,
): Promise<boolean> => {
  const localProviderCheck = await settlePromise(
    context.testApiKey(
      "local",
      context.localProviderState.value.endpoint,
      context.localProviderState.value.configuredModel || undefined,
    ),
    context.t("setup.providerTestErrorFallback"),
  );
  if (!localProviderCheck.ok) {
    return failSetupAction(
      context.saving,
      context.toast,
      getErrorMessage(localProviderCheck.error, context.t("setup.providerTestErrorFallback")),
    );
  }

  context.testResults.value.local = localProviderCheck.value;
  if (hasStoredCloudCredentials(context.providerCredentials, context.settings)) return true;
  if (localProviderCheck.value.valid) return true;

  return failSetupAction(
    context.saving,
    context.toast,
    localProviderCheck.value.message ||
      context.t("setup.providerTestFailed", { provider: context.providerLabels.value.local }),
  );
};

const persistProviderConfiguration = async (
  context: Pick<
    SetupPageActionsContext,
    | "localModelEndpoint"
    | "localModelName"
    | "providerCredentials"
    | "saving"
    | "t"
    | "toast"
    | "updateApiKeys"
  >,
): Promise<boolean> => {
  const update: Record<string, string> = {
    localModelEndpoint: context.localModelEndpoint.value.trim() || LOCAL_AI_DEFAULT_ENDPOINT,
    localModelName: context.localModelName.value.trim() || LOCAL_AI_DEFAULT_MODEL,
  };

  for (const provider of CLOUD_PROVIDER_IDS) {
    const credential = context.providerCredentials[provider].trim();
    if (credential) update[API_KEY_FIELD_BY_PROVIDER[provider]] = credential;
  }

  const apiKeyUpdateResult = await settlePromise(
    context.updateApiKeys(update),
    context.t("setup.completeErrorFallback"),
  );
  if (apiKeyUpdateResult.ok) {
    context.saving.value = false;
    return true;
  }

  return failSetupAction(
    context.saving,
    context.toast,
    getErrorMessage(apiKeyUpdateResult.error, context.t("setup.completeErrorFallback")),
  );
};

export const useSetupCompletion = (context: SetupPageActionsContext) => async (): Promise<void> => {
  context.saving.value = true;
  const input = createCompletionInput(context);
  const nextAuthStatus = await ensureSetupApiKey(context, input);
  if (!nextAuthStatus) return;
  if (nextAuthStatus.authRequired && !context.getStoredApiKey()) {
    failSetupAction(context.saving, context.toast, context.t("apiErrors.auth.initFailed"));
    return;
  }
  if (!(await ensureProfileSaved(context, input))) return;
  if (!(await ensureProviderAvailability(context))) return;
  if (!(await persistProviderConfiguration(context))) return;

  context.toast.success(context.t("setup.completeToast"));
  await context.router.push(context.postSetupFlowTarget.value);
};

