    query: {
      [APP_ROUTE_QUERY_KEYS.studioId]: studioId,
    },
  };
}

/**
 * Canonical route query decoding — one implementation for string/array query values.
 * All pages/composables that read `route.query[...]` must use these helpers (SSOT).
 */
import type { LocationQueryValue } from "vue-router";

export type RouteQueryValue =
  | LocationQueryValue
  | LocationQueryValue[]
  | readonly LocationQueryValue[]
  | undefined;

/** Decode a single query param to a string (first array element when multi). */
export function queryValueToString(value: RouteQueryValue): string {
  if (Array.isArray(value)) {
    const [firstValue] = value;
    return typeof firstValue === "string" ? firstValue : "";
  }
  return typeof value === "string" ? value : "";
}

/** Decode a single query param to string | null when empty/missing. */
export function queryValueToOptionalString(value: RouteQueryValue): string | null {
  const decoded = queryValueToString(value);
  return decoded.length > 0 ? decoded : null;
}

/**
 * Resolve a section query against an allowlist, falling back to the default.
 * Used by Settings / Automation hub / Scraper section rails.
 */
export function resolveRouteSectionId<T extends string>(
  value: RouteQueryValue,
  isValid: (candidate: string) => candidate is T,
  defaultSection: T,
): T {
  const candidate = queryValueToOptionalString(value);
  if (candidate && isValid(candidate)) {
    return candidate;
  }
  return defaultSection;
}

import { isRecord } from "@bao/shared/utils/type-guards";

/**
 * Unwraps canonical API envelopes while preserving raw array/object payloads.
 */
export function unwrapApiResponsePayload(response: unknown): unknown {
  if (isRecord(response) && "data" in response) {
    return response.data;
  }

  return response;
}

/**
 * Returns whether an API response uses the repo-standard error envelope.
 */
export function hasApiResponseError(response: unknown): boolean {
  return isRecord(response) && "error" in response && Boolean(response.error);
}

/**
 * Requires a valid API payload and throws with the supplied fallback message when invalid.
 */
export function requireApiResponsePayload(response: unknown, fallbackMessage: string): unknown {
  if (!(isRecord(response) || Array.isArray(response))) {
    throw new Error(fallbackMessage);
  }

  if (hasApiResponseError(response)) {
    throw new Error(fallbackMessage);
  }

  return unwrapApiResponsePayload(response);
}

/**
 * Typed Eden/data-envelope reader — single SSOT for page bootstrap helpers.
 * Prefer this over per-composable `readApiData` forks.
 */
export function requireApiResponseData<TData>(
  response: {
    data: TData;
    error?: unknown;
  },
  fallbackMessage: string,
  formatError: (error: unknown, fallback: string) => string = (_error, fallback) => fallback,
): TData {
  if (!(isRecord(response) && "data" in response)) {
    throw new Error(fallbackMessage);
  }
  if ("error" in response && response.error) {
    throw new Error(formatError(response.error, fallbackMessage));
  }
  return response.data;
}

/**
 * Async SSOT reader for composable Eden calls — prefer over local `readApiData` forks.
 */
export async function readRequiredApiPayload(
  request: Promise<unknown>,
  fallbackMessage: string,
): Promise<unknown> {
  const response = await request;
  return requireApiResponsePayload(response, fallbackMessage);
}

import { expect, it } from "vitest";
import {
  hasApiResponseError,
  readRequiredApiPayload,
  requireApiResponseData,
  requireApiResponsePayload,
  unwrapApiResponsePayload,
} from "./api-response";

it("unwraps repo-standard data envelopes", () => {
  expect(unwrapApiResponsePayload({ data: { id: "studio-1" } })).toEqual({ id: "studio-1" });
});

it("preserves raw array payloads", () => {
  expect(requireApiResponsePayload([{ id: "studio-1" }], "fallback")).toEqual([{ id: "studio-1" }]);
});

it("rejects repo-standard error envelopes", () => {
  expect(() => requireApiResponsePayload({ error: "failed" }, "fallback")).toThrow("fallback");
  expect(hasApiResponseError({ error: "failed" })).toBe(true);
});

it("rejects non-object payloads", () => {
  expect(() => requireApiResponsePayload("invalid", "fallback")).toThrow("fallback");
});

it("requireApiResponseData returns typed data and formats errors", () => {
  expect(requireApiResponseData({ data: { ok: true } }, "fallback")).toEqual({ ok: true });
  expect(() =>
    requireApiResponseData({ data: null, error: "boom" }, "fallback", (error, fallback) =>
      typeof error === "string" ? error : fallback,
    ),
  ).toThrow("boom");
});

it("readRequiredApiPayload rejects error envelopes", async () => {
  await expect(readRequiredApiPayload(Promise.resolve({ error: "nope" }), "fallback")).rejects.toThrow(
    "fallback",
  );
  await expect(readRequiredApiPayload(Promise.resolve({ data: [1, 2] }), "fallback")).resolves.toEqual([
    1, 2,
  ]);
});

