import type { AvailableLocale } from "~/constants/i18n-catalog";
import { I18N_MESSAGE_CATALOG } from "~/constants/i18n-catalog";

type MessageNode = Record<string, unknown>;

function cloneMessageNode<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function setByPath(target: MessageNode, path: string, value: string): void {
  const segments = path
    .split(".")
    .map((segment) => segment.trim())
    .filter((segment) => segment.length > 0);

  if (segments.length === 0) {
    return;
  }

  let cursor: MessageNode = target;
  for (const segment of segments.slice(0, -1)) {
    const next = cursor[segment];
    if (typeof next !== "object" || next === null || Array.isArray(next)) {
      cursor[segment] = {};
    }
    cursor = next as Record<string, unknown>;
  }

  const leafKey = segments[segments.length - 1];
  if (leafKey) {
    cursor[leafKey] = value;
  }
}

/**
 * Builds a locale catalog with brand copy overrides applied to dot-delimited message keys.
 *
 * @param locale Active locale key.
 * @param overrides White-label copy overrides keyed by locale-message path.
 * @returns Localized message tree with overrides applied.
 */
export function buildBrandedLocaleMessages(
  locale: AvailableLocale,
  overrides: Record<string, string>,
): MessageNode {
  const baseMessages: MessageNode = cloneMessageNode(I18N_MESSAGE_CATALOG[locale]);
  for (const [messageKey, messageValue] of Object.entries(overrides)) {
    setByPath(baseMessages, messageKey, messageValue);
  }
  return baseMessages;
}

import { isRecord } from "@bao/shared/utils/type-guards";

export type ApiGamificationAward = {
  readonly xpAwarded: number;
  readonly reason: string;
};

/**
 * Reads optional gamification award payloads attached to mutating API responses.
 */
export function readApiGamificationAward(payload: unknown): ApiGamificationAward | null {
  if (!isRecord(payload)) {
    return null;
  }
  const gamification = payload.gamification;
  if (!isRecord(gamification)) {
    return null;
  }
  const xpAwarded = gamification.xpAwarded;
  const reason = gamification.reason;
  if (typeof xpAwarded !== "number" || typeof reason !== "string") {
    return null;
  }
  if (!(Number.isFinite(xpAwarded) && xpAwarded > 0)) {
    return null;
  }
  return { xpAwarded, reason };
}

import type { CoverLetterData } from "@bao/shared/types/cover-letter";

const COVER_LETTER_PRIMARY_SECTION_KEYS = [
  "opening",
  "introduction",
  "body",
  "closing",
  "conclusion",
  "signature",
] as const;
const SECTION_SPLIT_PATTERN = /\n{2,}/u;

/**
 * Converts structured cover-letter content into readable multiline text for previews/editing.
 *
 * @param content Structured cover-letter content map.
 * @returns Concatenated plain-text content with paragraph spacing.
 */
export function coverLetterContentToPlainText(
  content: CoverLetterData["content"] | undefined,
): string {
  if (!content) return "";

  const sectionKeys = new Set<string>();
  const orderedSections: string[] = [];

  for (const key of COVER_LETTER_PRIMARY_SECTION_KEYS) {
    sectionKeys.add(key);
    const value = content[key];
    if (typeof value !== "string") continue;
    const trimmed = value.trim();
    if (trimmed.length > 0) {
      orderedSections.push(trimmed);
    }
  }

  const additionalSections = Object.entries(content).flatMap(([key, value]) => {
    if (sectionKeys.has(key) || typeof value !== "string") {
      return [];
    }

    const trimmedValue = value.trim();
    return trimmedValue.length > 0 ? [trimmedValue] : [];
  });

  if (additionalSections.length > 0) {
    orderedSections.push(...additionalSections);
  }

  return orderedSections.join("\n\n");
}

/**
 * Converts user-edited plain text into canonical structured cover-letter content.
 *
 * @param value Editable plain-text cover-letter input.
 * @returns Structured cover-letter content suitable for API payloads.
 */
/**
 * Counts non-empty cover-letter sections separated by blank lines.
 */
export function countCoverLetterSections(value: string): number {
  const trimmedValue = value.trim();
  if (trimmedValue.length === 0) {
    return 0;
  }
  return trimmedValue
    .split(SECTION_SPLIT_PATTERN)
    .map((section) => section.trim())
    .filter((section) => section.length > 0).length;
}

export function plainTextToCoverLetterContent(value: string): CoverLetterData["content"] {
  const trimmedValue = value.trim();
  if (trimmedValue.length === 0) return {};

  const sections = trimmedValue
    .split(SECTION_SPLIT_PATTERN)
    .map((section) => section.trim())
    .filter((section) => section.length > 0);

  if (sections.length === 1) {
    return {
      body: sections[0],
    };
  }

  if (sections.length === 2) {
    return {
      introduction: sections[0],
      body: sections[1],
    };
  }

  return {
    introduction: sections[0],
    body: sections.slice(1, -1).join("\n\n"),
    conclusion: sections[sections.length - 1],
  };
}

