export const gameGenreLabel = (t: Translate, value: string | undefined | null): string => {
  const normalizedValue = value?.trim() ?? "";
  if (normalizedValue.length === 0) {
    return "";
  }

  const key = findLabelKey(GAME_GENRE_LABEL_KEYS, normalizedValue);
  if (key !== null) {
    return t(key);
  }

  return normalizedValue;
};

import { API_ENDPOINT_PREFIX } from "@bao/shared/constants/endpoints";
import { resolveApiRouteBase } from "./endpoints";

const TRAILING_SLASHES_PATTERN = /\/+$/u;

function normalizeTreatyPath(pathname: string): string {
  const trimmedPath =
    pathname.length > 1 ? pathname.replace(TRAILING_SLASHES_PATTERN, "") : pathname;
  if (trimmedPath === API_ENDPOINT_PREFIX) {
    return "/";
  }

  return trimmedPath.endsWith(API_ENDPOINT_PREFIX)
    ? trimmedPath.slice(0, -API_ENDPOINT_PREFIX.length) || "/"
    : trimmedPath;
}

export function resolveTreatyBase(configuredBase: string, requestUrl: URL): string {
  const resolvedApiBase = resolveApiRouteBase(configuredBase, requestUrl);
  const treatyBase = new URL(resolvedApiBase);
  treatyBase.pathname = normalizeTreatyPath(treatyBase.pathname);

  const normalized = treatyBase.toString();
  return treatyBase.pathname === "/" && normalized.endsWith("/")
    ? normalized.slice(0, -1)
    : normalized;
}

import { safeParseJson } from "@bao/shared/utils/json";
import { isRecord } from "@bao/shared/utils/type-guards";
import type { JobProviderForm } from "~/components/settings/job-intelligence";
import { countConfiguredGamingPortals, parseGamingPortalsJson } from "~/utils/gaming-portals-form";

const countEnabledNamedEntries = (rawJson: string): number => {
  const parsed = safeParseJson(rawJson);
  if (!Array.isArray(parsed)) {
    return 0;
  }
  let count = 0;
  for (const entry of parsed) {
    if (!isRecord(entry)) {
      continue;
    }
    const enabled = entry.enabled === true;
    const hasIdentity =
      (typeof entry.token === "string" && entry.token.trim().length > 0) ||
      (typeof entry.slug === "string" && entry.slug.trim().length > 0) ||
      (typeof entry.id === "string" && entry.id.trim().length > 0) ||
      (typeof entry.name === "string" && entry.name.trim().length > 0);
    if (enabled && hasIdentity) {
      count += 1;
    }
  }
  return count;
};

/**
 * Counts job sources that are enabled with enough config to fetch.
 * Shared by Job Intelligence summary + providers workspace (SSOT).
 */
export function countActiveJobProviderSources(form: JobProviderForm): number {
  return (
    Number(form.hitmarkerEnabled) +
    Number(countEnabledNamedEntries(form.greenhouseBoardsJson) > 0) +
    Number(countEnabledNamedEntries(form.leverCompaniesJson) > 0) +
    countConfiguredGamingPortals(parseGamingPortalsJson(form.gamingPortalsJson))
  );
}

import { QueryClient, VueQueryPlugin } from "@tanstack/vue-query";

const NON_NEGATIVE_MIN = 0;
const QUERY_STALE_TIME_FALLBACK_MS = 60_000;
const QUERY_RETRY_FALLBACK = 1;
const QUERY_REFOCUS_FALLBACK = true;

function toNonNegativeNumber(value: unknown, fallback: number): number {
  const parsed = typeof value === "number" ? value : Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(NON_NEGATIVE_MIN, parsed);
}

function toBoolean(value: unknown, fallback: boolean): boolean {
  if (typeof value === "boolean") return value;
  if (typeof value === "string") {
    if (value.toLowerCase() === "true") return true;
    if (value.toLowerCase() === "false") return false;
  }
  return fallback;
}

export default defineNuxtPlugin((nuxtApp) => {
  const { public: publicConfig } = useRuntimeConfig();
  const staleTime = toNonNegativeNumber(
    publicConfig.queryStaleTimeMs,
    QUERY_STALE_TIME_FALLBACK_MS,
  );
  const retryCount = toNonNegativeNumber(publicConfig.queryRetryCount, QUERY_RETRY_FALLBACK);
  const refetchOnWindowFocus = toBoolean(publicConfig.queryRefetchOnFocus, QUERY_REFOCUS_FALLBACK);

  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        staleTime,
        refetchOnWindowFocus,
        retry: retryCount,
      },
    },
  });

  nuxtApp.vueApp.use(VueQueryPlugin, { queryClient });

  return {
    provide: {
      queryClient,
    },
  };
});

import { DEFAULT_APP_LANGUAGE } from "@bao/shared/constants/settings";
import { createI18n } from "vue-i18n";
import { type AvailableLocale, I18N_MESSAGE_CATALOG } from "~/constants/i18n-catalog";

const DEFAULT_LOCALE: AvailableLocale = DEFAULT_APP_LANGUAGE;
const ACCEPT_LANGUAGE_SEPARATOR = ",";
const ACCEPT_LANGUAGE_WEIGHT_SEPARATOR = ";";
const ACCEPT_LANGUAGE_QUALITY_PREFIX = "q=";
const ACCEPT_LANGUAGE_VARIANT_SEPARATOR = "-";
const ACCEPT_LANGUAGE_DEFAULT_QUALITY = 1;
const ACCEPT_LANGUAGE_MIN_QUALITY = 0;
const ACCEPT_LANGUAGE_MAX_QUALITY = 1;

interface LocaleResolutionInput {
  readonly cookieLocale: string | null | undefined;
  readonly acceptLanguageHeader: string | undefined;
  readonly browserLocale: string | undefined;
  readonly supportedLocales: readonly AvailableLocale[];
  readonly defaultLocale: AvailableLocale;
}

interface WeightedLocaleCandidate {
  readonly locale: string;
  readonly quality: number;
  readonly order: number;
}

const normalizeLocaleCandidate = (value: string): string =>
  value.trim().toLowerCase().replaceAll("_", ACCEPT_LANGUAGE_VARIANT_SEPARATOR);

const isAvailableLocale = (value: string): value is AvailableLocale =>
  Object.hasOwn(I18N_MESSAGE_CATALOG, value);

const parseSupportedLocales = (
  configuredLocales: readonly string[],
): readonly AvailableLocale[] => {
  const normalizedConfigured = new Set(configuredLocales.map(normalizeLocaleCandidate));
  const availableLocales = Object.keys(I18N_MESSAGE_CATALOG).filter(isAvailableLocale);
  const configuredAvailableLocales = availableLocales.filter((locale) =>
    normalizedConfigured.has(normalizeLocaleCandidate(locale)),
  );
  return configuredAvailableLocales.length > 0 ? configuredAvailableLocales : [DEFAULT_LOCALE];
};

const resolveFromCandidates = (
  candidates: readonly (string | null | undefined)[],
  supportedLocales: readonly AvailableLocale[],
): AvailableLocale | null => {
  const normalizedSupportedLocales = new Map(
    supportedLocales.map((locale) => [normalizeLocaleCandidate(locale), locale]),
  );

  for (const candidate of candidates) {
    if (!candidate) {
      continue;
    }

    const normalizedCandidate = normalizeLocaleCandidate(candidate);
    const directMatch = normalizedSupportedLocales.get(normalizedCandidate);
    if (directMatch) {
      return directMatch;
    }

    const baseLanguage = normalizedCandidate.split(ACCEPT_LANGUAGE_VARIANT_SEPARATOR)[0];
    const languageMatch = supportedLocales.find((locale) =>
      normalizeLocaleCandidate(locale).startsWith(
        `${baseLanguage}${ACCEPT_LANGUAGE_VARIANT_SEPARATOR}`,
      ),
    );
    if (languageMatch) {
      return languageMatch;
    }
  }

  return null;
};

const parseAcceptLanguageValues = (value: string | undefined): string[] => {
  if (!value) {
    return [];
  }

  const weightedCandidates = value
    .split(ACCEPT_LANGUAGE_SEPARATOR)
    .map((entry, order): WeightedLocaleCandidate | null => {
      const segments = entry
        .split(ACCEPT_LANGUAGE_WEIGHT_SEPARATOR)
        .map((segment) => segment.trim())
        .filter((segment) => segment.length > 0);
      const [localeSegment, ...qualitySegments] = segments;
      if (!localeSegment) {
        return null;
      }

      const qualitySegment = qualitySegments.find((segment) =>
        segment.toLowerCase().startsWith(ACCEPT_LANGUAGE_QUALITY_PREFIX),
      );
      const parsedQualityValue = qualitySegment
        ? Number.parseFloat(qualitySegment.slice(ACCEPT_LANGUAGE_QUALITY_PREFIX.length))
        : ACCEPT_LANGUAGE_DEFAULT_QUALITY;
      const quality = Number.isFinite(parsedQualityValue)
        ? Math.min(
            ACCEPT_LANGUAGE_MAX_QUALITY,
            Math.max(ACCEPT_LANGUAGE_MIN_QUALITY, parsedQualityValue),
          )
        : ACCEPT_LANGUAGE_DEFAULT_QUALITY;

      return {
        locale: localeSegment,
        quality,
        order,
      };
    })
    .filter((candidate): candidate is WeightedLocaleCandidate => candidate !== null)
    .sort((left, right) => right.quality - left.quality || left.order - right.order);

  return weightedCandidates.map((candidate) => candidate.locale);
};

const resolveInitialLocale = ({
  cookieLocale,
  acceptLanguageHeader,
  browserLocale,
  supportedLocales,
  defaultLocale,
}: LocaleResolutionInput): AvailableLocale => {
  const acceptLanguageLocales = parseAcceptLanguageValues(acceptLanguageHeader);
  const resolvedLocale = resolveFromCandidates(
    [cookieLocale, ...acceptLanguageLocales, browserLocale],
    supportedLocales,
  );
  return resolvedLocale ?? defaultLocale;
};

/**
 * Installs `vue-i18n` using SSR-safe locale resolution and shared runtime config.
 */
export default defineNuxtPlugin({
  name: "i18n",
  setup(nuxtApp) {
    const runtimeConfig = useRuntimeConfig();
    const i18nConfig = runtimeConfig.public.i18n;
    const supportedLocales = parseSupportedLocales(i18nConfig.supportedLocales);
    const defaultLocale =
      resolveFromCandidates([i18nConfig.defaultLocale], supportedLocales) ?? DEFAULT_LOCALE;
    const fallbackLocale =
      resolveFromCandidates([i18nConfig.fallbackLocale], supportedLocales) ?? defaultLocale;
    const localeCookie = useCookie<AvailableLocale>(i18nConfig.localeCookieKey, {
      sameSite: "lax",
      path: "/",
      default: () => defaultLocale,
    });
    const acceptLanguageHeader = import.meta.server
      ? useRequestHeaders(["accept-language"])["accept-language"]
      : undefined;
    const browserLocale = import.meta.client ? navigator.language : undefined;
    const initialLocale = resolveInitialLocale({
      cookieLocale: localeCookie.value,
      acceptLanguageHeader,
      browserLocale,
      supportedLocales,
      defaultLocale,
    });

    const i18n = createI18n({
      legacy: false,
      globalInjection: true,
      locale: initialLocale,
      fallbackLocale,
      messages: I18N_MESSAGE_CATALOG,
      missingWarn: false,
      fallbackWarn: false,
    });

    nuxtApp.vueApp.use(i18n);

    useHead(() => ({
      htmlAttrs: {
        lang: i18n.global.locale.value,
      },
    }));

    watch(
      () => i18n.global.locale.value,
      (nextLocale) => {
        localeCookie.value = nextLocale;
      },
      { immediate: true },
    );
  },
});

import { watchEffect } from "vue";

/**
 * Single owner for brand CSS variables on `documentElement`.
 * `useBrand()` is read-only for consumers; this plugin applies vars once.
 * Runs post-plugins; reads shared settings state (no `useI18n` / Eden dependency).
 */
export default defineNuxtPlugin({
  name: "brand-css",
  enforce: "post",
  setup() {
    const { brandCssVars } = useBrand();

    watchEffect((onCleanup) => {
      const nextVars = brandCssVars.value;
      const root = document.documentElement;
      const appliedEntries = Object.entries(nextVars).map(
        ([key, value]) => [key, typeof value === "string" ? value : String(value)] as const,
      );
      for (const [key, value] of appliedEntries) {
        root.style.setProperty(key, value);
      }
      onCleanup(() => {
        for (const [key] of appliedEntries) {
          root.style.removeProperty(key);
        }
      });
    });
  },
});

export default defineNuxtPlugin(() => {
  const { success, error, info, warning } = useToast();

  return {
    provide: {
      toast: {
        success,
        error,
        info,
        warning,
      },
    },
  };
});

import type { App } from "@bao/server/app";
import { AUTH_KEY_STORAGE_KEY } from "@bao/shared/constants/auth";
import { treaty } from "@elysiajs/eden";
import { tryUseNuxtApp } from "nuxt/app";
import type { Ref } from "vue";
import { assertClientApi } from "~/types/client-api";
import { resolveTreatyBase } from "~/utils/treaty-base";
import { HTTP_STATUS_UNAUTHORIZED } from "@bao/shared/constants/http";

const AUTH_KEY = AUTH_KEY_STORAGE_KEY;

type StoredApiKey = string | null;
type AuthKeyCookieRef = Ref<StoredApiKey> | null;

function getAuthKeyCookieRef() {
  return useCookie<StoredApiKey>(AUTH_KEY, {
    default: () => null,
    path: "/",
    sameSite: "strict",
    httpOnly: true,
    secure: true,
  });
}

function resolveAuthKeyCookieRef(): AuthKeyCookieRef {
  return tryUseNuxtApp() ? getAuthKeyCookieRef() : null;
}

function readStoredApiKey(cookieRef: AuthKeyCookieRef): string | null {
  return cookieRef?.value ?? null;
}

function writeStoredApiKey(cookieRef: AuthKeyCookieRef, apiKey: string | null): void {
  if (cookieRef) {
    cookieRef.value = apiKey;
  }
}

/**
 * Reads API key from the httpOnly auth cookie.
 *
 * @returns Stored API key when available.
 */
export function getStoredApiKey(): string | null {
  return readStoredApiKey(resolveAuthKeyCookieRef());
}

/**
 * Persists or clears API key in the httpOnly auth cookie.
 *
 * @param key API key value.
 */
export function setStoredApiKey(key: string | null): void {
  writeStoredApiKey(resolveAuthKeyCookieRef(), key);
}

export default defineNuxtPlugin({
  name: "eden",
  setup() {
    const config = useRuntimeConfig();
    const requestUrl = useRequestURL();
    const cookieRef = getAuthKeyCookieRef();

    const configuredBase = (config.public.apiBase || "/").toString();
    const treatyBase = resolveTreatyBase(configuredBase, requestUrl);

    const readApiKey = () => readStoredApiKey(cookieRef);
    const writeApiKey = (key: string | null) => writeStoredApiKey(cookieRef, key);

    const api = treaty<App>(treatyBase, {
      fetch: {
        credentials: "include",
      },
      headers: () => {
        const key = readApiKey();
        return key ? { Authorization: `Bearer ${key}` } : {};
      },
      onResponse: (response) => {
        if (response.status === HTTP_STATUS_UNAUTHORIZED) {
          writeApiKey(null);
        }
      },
    });

    assertClientApi(api.api);

    return {
      provide: {
        api: api.api, // enters the /api prefix group
        getStoredApiKey: readApiKey,
        setStoredApiKey: writeApiKey,
      },
    };
  },
});

import type { ToastApi, ToastOptions } from "~/composables/useToast";

const createNoopToast = (): ToastApi => {
  const noOp = (...args: [message: string, options?: ToastOptions]): string => {
    if (args.length > 2) {
      return "";
    }
    return "";
  };

  return {
    success: noOp,
    error: noOp,
    info: noOp,
    warning: noOp,
  };
};

/**
 * Provide a server-safe `$toast` contract during SSR and static prerender.
 */
export default defineNuxtPlugin(() => ({
  provide: {
    toast: createNoopToast(),
  },
}));

import { APP_ROUTES } from "@bao/shared/constants/routes";

export default defineNuxtRouteMiddleware(async (to) => {
  if (to.path === APP_ROUTES.setup) return;

  const auth = useAuth();
  const { authRequired } = await auth.checkAuthStatus();

  if (!authRequired) return;

  const apiKey = auth.getStoredApiKey();
  if (!apiKey) {
    return navigateTo(APP_ROUTES.setup);
  }
});

