  portfolio: string;
  experience: ResumeFormExperience[];
  education: ResumeFormEducation[];
  skills: string[];
  projects: ResumeFormProject[];
  gaming: {
    roles: string | string[];
    genres: string | string[];
    achievements: string | string[];
  };
}

export interface ResumeFormExperience {
  title: string;
  company: string;
  location: string;
  startDate: string;
  endDate: string;
  current: boolean;
  description: string;
}

export interface ResumeFormEducation {
  degree: string;
  school: string;
  location: string;
  graduationDate: string;
  gpa: string;
}

export interface ResumeFormProject {
  name: string;
  description: string;
  technologies: string[];
  url: string;
}

function toArray(val: string | string[]): string[] {
  if (Array.isArray(val)) return val;
  if (typeof val === "string") {
    return val
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
  }
  return [];
}

function buildPersonalInfo(form: Partial<ResumeFormData>): ResumePersonalInfo {
  return {
    ...(form.name ? { name: form.name } : {}),
    ...(form.email ? { email: form.email } : {}),
    ...(form.phone ? { phone: form.phone } : {}),
    ...(form.location ? { location: form.location } : {}),
    ...(form.linkedIn ? { linkedIn: form.linkedIn } : {}),
    ...(form.portfolio ? { portfolio: form.portfolio } : {}),
  };
}

function mapFormExperienceToResumeExperience(
  experience: ResumeFormExperience[] | undefined,
): ResumeExperienceItem[] {
  return (experience || []).map((exp) => ({
    title: exp.title,
    company: exp.company,
    startDate: exp.startDate,
    ...(!exp.current && exp.endDate ? { endDate: exp.endDate } : {}),
    ...(exp.location ? { location: exp.location } : {}),
    ...(exp.description ? { description: exp.description } : {}),
  }));
}

function mapFormEducationToResumeEducation(
  education: ResumeFormEducation[] | undefined,
): ResumeEducationItem[] {
  return (education || []).map((edu) => ({
    degree: edu.degree,
    school: edu.school,
    field: "",
    year: edu.graduationDate,
    ...(edu.gpa ? { gpa: edu.gpa } : {}),
  }));
}

function buildSkillsFromForm(skillsInput: string[] | undefined): ResumeSkills {
  return (skillsInput ?? []).length > 0 ? { technical: skillsInput } : {};
}

function mapFormProjectsToResumeProjects(
  projects: ResumeFormProject[] | undefined,
): ResumeProject[] {
  return (projects || []).map((project) => ({
    title: project.name,
    description: project.description,
    ...((project.technologies ?? []).length > 0
      ? { technologies: project.technologies }
      : {}),
    ...(project.url ? { link: project.url } : {}),
  }));
}

function buildGamingExperience(gaming: ResumeFormData["gaming"] | undefined): GamingExperience {
  if (!gaming) return {};

  const roles = toArray(gaming.roles);
  const genres = toArray(gaming.genres);
  const achievements = toArray(gaming.achievements);
  return {
    ...(roles.length > 0 ? { gameEngines: roles.join(", ") } : {}),
    ...(genres.length > 0 ? { genres: genres.join(", ") } : {}),
    ...(achievements.length > 0 ? { shippedTitles: achievements.join("; ") } : {}),
  };
}

function buildResumeData(input: {
  form: Partial<ResumeFormData>;
  personalInfo: ResumePersonalInfo;
  experience: ResumeExperienceItem[];
  education: ResumeEducationItem[];
  skills: ResumeSkills;
  projects: ResumeProject[];
  gamingExperience: GamingExperience;
}): Partial<ResumeData> {
  return {
    ...(Object.keys(input.personalInfo).length > 0 ? { personalInfo: input.personalInfo } : {}),
    ...(input.form.summary ? { summary: input.form.summary } : {}),
    ...(input.experience.length > 0 ? { experience: input.experience } : {}),
    ...(input.education.length > 0 ? { education: input.education } : {}),
    ...(Object.keys(input.skills).length > 0 ? { skills: input.skills } : {}),
    ...(input.projects.length > 0 ? { projects: input.projects } : {}),
    ...(Object.keys(input.gamingExperience).length > 0
      ? { gamingExperience: input.gamingExperience }
      : {}),
  };
}

function mapResumeExperienceToFormExperience(
  experience: ResumeExperienceItem[] | undefined,
): ResumeFormExperience[] {
  return (experience || []).map((exp) => ({
    title: exp.title,
    company: exp.company,
    location: exp.location || "",
    startDate: exp.startDate,
    endDate: exp.endDate || "",
    current: !exp.endDate,
    description: exp.description || "",
  }));
}

function mapResumeEducationToFormEducation(
  education: ResumeEducationItem[] | undefined,
): ResumeFormEducation[] {
  return (education || []).map((edu) => ({
    degree: edu.degree,
    school: edu.school,
    location: "",
    graduationDate: edu.year,
    gpa: edu.gpa || "",
  }));
}

function mapResumeProjectsToFormProjects(
  projects: ResumeProject[] | undefined,
): ResumeFormProject[] {
  return (projects || []).map((project) => ({
    name: project.title,
    description: project.description,
    technologies: project.technologies || [],
    url: project.link || "",
  }));
}

function splitDelimited(value: string | undefined, delimiter: string): string[] {
  return value ? value.split(delimiter).map((entry) => entry.trim()) : [];
}

/**
 * Convert form data to canonical ResumeData.
 */
export function formDataToResumeData(form: Partial<ResumeFormData>): Partial<ResumeData> {
  const personalInfo = buildPersonalInfo(form);
  const experience = mapFormExperienceToResumeExperience(form.experience);
  const education = mapFormEducationToResumeEducation(form.education);
  const skills = buildSkillsFromForm(form.skills);
  const projects = mapFormProjectsToResumeProjects(form.projects);
  const gamingExperience = buildGamingExperience(form.gaming);

  return buildResumeData({
    form,
    personalInfo,
    experience,
    education,
    skills,
    projects,
    gamingExperience,
  });
}

/**
 * Convert canonical ResumeData to form data.
 */
export function resumeDataToFormData(resume: Partial<ResumeData>): ResumeFormData {
  const pi = resume.personalInfo || {};
  return {
    name: pi.name || "",
    email: pi.email || "",
    phone: pi.phone || "",
    location: pi.location || "",
    summary: resume.summary || "",
    linkedIn: pi.linkedIn || "",
    portfolio: pi.portfolio || "",
    experience: mapResumeExperienceToFormExperience(resume.experience),
    education: mapResumeEducationToFormEducation(resume.education),
    skills: [...(resume.skills?.technical || []), ...(resume.skills?.soft || [])],
    projects: mapResumeProjectsToFormProjects(resume.projects),
    gaming: {
      roles: splitDelimited(resume.gamingExperience?.gameEngines, ","),
      genres: splitDelimited(resume.gamingExperience?.genres, ","),
      achievements: splitDelimited(resume.gamingExperience?.shippedTitles, ";"),
    },
  };
}

import { LOOPBACK_HOST, LOOPBACK_HOST_IPV4, LOOPBACK_HOST_IPV6 } from "../constants/runtime";

export type LocalAiEndpointValidationResult =
  | { readonly ok: true; readonly endpoint: string }
  | {
      readonly ok: false;
      readonly code: "INVALID_URL" | "DISALLOWED_PROTOCOL" | "DISALLOWED_HOST" | "CREDENTIALS";
    };

const ALLOWED_LOCAL_AI_HOSTS = new Set<string>([
  LOOPBACK_HOST,
  LOOPBACK_HOST_IPV4,
  LOOPBACK_HOST_IPV6,
]);

/**
 * Validates a local-inference endpoint for server-side fetch.
 * Default-deny: only loopback hosts may be probed (SSRF fail-closed).
 */
export const validateLocalAiEndpoint = (rawEndpoint: string): LocalAiEndpointValidationResult => {
  const trimmed = rawEndpoint.trim();
  if (!trimmed || !URL.canParse(trimmed)) {
    return { ok: false, code: "INVALID_URL" };
  }

  const parsed = new URL(trimmed);
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    return { ok: false, code: "DISALLOWED_PROTOCOL" };
  }

  if (parsed.username || parsed.password) {
    return { ok: false, code: "CREDENTIALS" };
  }

  const host = parsed.hostname.toLowerCase();
  if (!ALLOWED_LOCAL_AI_HOSTS.has(host)) {
    return { ok: false, code: "DISALLOWED_HOST" };
  }

  return { ok: true, endpoint: parsed.toString() };
};

/**
 * String utility helpers.
 */

/**
 * Escapes special regex characters in a string for use in RegExp constructors.
 */
export function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}

import type { DESKTOP_RELEASE_TARGETS } from "../constants/scripts";
import {
  DESKTOP_RELEASE_LINUX_ARM64_DEB_ARCH,
  DESKTOP_RELEASE_LINUX_ARM64_RPM_ARCH,
  DESKTOP_RELEASE_LINUX_ARM64_TARGET,
  DESKTOP_RELEASE_LINUX_X64_DEB_ARCH,
  DESKTOP_RELEASE_LINUX_X64_RPM_ARCH,
  DESKTOP_RELEASE_LINUX_X64_TARGET,
  DESKTOP_RELEASE_MACOS_AARCH64_ARCH,
  DESKTOP_RELEASE_MACOS_AARCH64_TARGET,
  DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH,
  DESKTOP_RELEASE_MACOS_UNIVERSAL_TARGET,
  DESKTOP_RELEASE_MACOS_X64_ARCH,
  DESKTOP_RELEASE_MACOS_X64_TARGET,
  DESKTOP_RELEASE_WINDOWS_ARCH,
  DESKTOP_RELEASE_WINDOWS_MSI_LANGUAGE,
  DESKTOP_RELEASE_WINDOWS_TARGET,
} from "../constants/scripts";
import { resolveDesktopRuntimeTargetInfo } from "./desktop-runtime-contract";

/**
 * Canonical desktop release staging targets.
 */
export type DesktopReleaseTarget = (typeof DESKTOP_RELEASE_TARGETS)[number];

/**
 * Minimum metadata required to build canonical desktop release artifact names.
 */
export type DesktopReleaseArtifactNaming = {
  readonly productName: string;
  readonly version: string;
};

/**
 * Supported macOS architecture labels for release artifact naming.
 */
export type DesktopReleaseMacosArchitecture =
  | typeof DESKTOP_RELEASE_MACOS_AARCH64_ARCH
  | typeof DESKTOP_RELEASE_MACOS_X64_ARCH
  | typeof DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH;

/**
 * Canonical desktop release artifact kinds produced by matching-host native builds.
 */
export type DesktopReleaseArtifactKind =
  | "appimage"
  | "deb"
  | "dmg"
  | "msi"
  | "portable"
  | "rpm"
  | "sig"
  | "setup";

/**
 * Optional profile-driven release variant toggles.
 */
export type DesktopReleaseArtifactProfile = {
  readonly includeLinuxAppImage: boolean;
  readonly includeLinuxSignatures: boolean;
  readonly includeWindowsMsi: boolean;
  readonly macosArchitectures: readonly DesktopReleaseMacosArchitecture[];
};

/**
 * Default profile for canonical release outputs.
 * Set `include*` fields to true (or `DESKTOP_RELEASE_*=true` in build/verify scripts) to opt in.
 *
 * Linux signatures require GPG signing infrastructure.
 * Windows MSI requires the WiX toolchain.
 * Enable these flags only when the build environment supports them.
 */
export const DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE: DesktopReleaseArtifactProfile = {
  includeLinuxAppImage: false,
  includeLinuxSignatures: false,
  includeWindowsMsi: false,
  macosArchitectures: [DESKTOP_RELEASE_MACOS_AARCH64_ARCH],
};

const DESKTOP_RELEASE_MACOS_ARCHITECTURE_ORDER: readonly DesktopReleaseMacosArchitecture[] = [
  DESKTOP_RELEASE_MACOS_AARCH64_ARCH,
  DESKTOP_RELEASE_MACOS_X64_ARCH,
  DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH,
];

/**
 * Canonical artifact entry within the assembled desktop release directory.
 */
export type DesktopReleaseArtifactSpec = {
  readonly fileName: string;
  readonly kind: DesktopReleaseArtifactKind;
  readonly relativePath: string;
  readonly target: DesktopReleaseTarget;
};

const dedupeMacosArchitectures = (
  architectures: readonly DesktopReleaseMacosArchitecture[],
): readonly DesktopReleaseMacosArchitecture[] => {
  const selectedArchitectures = new Set(architectures);
  return DESKTOP_RELEASE_MACOS_ARCHITECTURE_ORDER.filter((architecture) =>
    selectedArchitectures.has(architecture),
  );
};

/**
 * Resolves a partial release profile into the canonical artifact profile.
 */
export const normalizeDesktopReleaseArtifactProfile = (
  profile: Partial<DesktopReleaseArtifactProfile> = {},
): DesktopReleaseArtifactProfile => ({
  includeLinuxAppImage:
    profile.includeLinuxAppImage ?? DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.includeLinuxAppImage,
  includeLinuxSignatures:
    profile.includeLinuxSignatures ??
    DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.includeLinuxSignatures,
  includeWindowsMsi:
    profile.includeWindowsMsi ?? DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.includeWindowsMsi,
  macosArchitectures:
    profile.macosArchitectures === undefined || profile.macosArchitectures.length === 0
      ? DEFAULT_DESKTOP_RELEASE_ARTIFACT_PROFILE.macosArchitectures
      : dedupeMacosArchitectures(profile.macosArchitectures),
});

const createDesktopReleaseArtifactSpec = (
  target: DesktopReleaseTarget,
  fileName: string,
  kind: DesktopReleaseArtifactKind,
): DesktopReleaseArtifactSpec => ({
  fileName,
  kind,
  relativePath: `${target}/${fileName}`,
  target,
});

const isLinuxTarget = (target: DesktopReleaseTarget): target is "linux-x64" | "linux-arm64" =>
  target === "linux-x64" || target === "linux-arm64";

const buildLinuxAppImageSpecs = (
  metadata: DesktopReleaseArtifactNaming,
  target: "linux-x64" | "linux-arm64",
): readonly DesktopReleaseArtifactSpec[] => [
  createDesktopReleaseArtifactSpec(
    target,
    `${metadata.productName}_${metadata.version}_${
      target === "linux-x64"
        ? DESKTOP_RELEASE_LINUX_X64_DEB_ARCH
        : DESKTOP_RELEASE_LINUX_ARM64_DEB_ARCH
    }.AppImage`,
    "appimage",
  ),
];

const buildLinuxCoreSpecs = (
  metadata: DesktopReleaseArtifactNaming,
  target: DesktopReleaseTarget,
) =>
  target === "linux-x64"
    ? [
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_LINUX_X64_DEB_ARCH}.deb`,
          "deb",
        ),
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}-${metadata.version}-1.${DESKTOP_RELEASE_LINUX_X64_RPM_ARCH}.rpm`,
          "rpm",
        ),
      ]
    : [
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_LINUX_ARM64_DEB_ARCH}.deb`,
          "deb",
        ),
        createDesktopReleaseArtifactSpec(
          target,
          `${metadata.productName}-${metadata.version}-1.${DESKTOP_RELEASE_LINUX_ARM64_RPM_ARCH}.rpm`,
          "rpm",
        ),
      ];

const appendLinuxSignatures = (
  artifacts: readonly DesktopReleaseArtifactSpec[],
): readonly DesktopReleaseArtifactSpec[] =>
  artifacts.concat(
    artifacts.map((artifact) =>
      createDesktopReleaseArtifactSpec(artifact.target, `${artifact.fileName}.sig`, "sig"),
    ),
  );

const resolveMacosTargetForArchitecture = (
  architecture: DesktopReleaseMacosArchitecture,
): string => {
  if (architecture === DESKTOP_RELEASE_MACOS_X64_ARCH) {
    return DESKTOP_RELEASE_MACOS_X64_TARGET;
  }
  if (architecture === DESKTOP_RELEASE_MACOS_UNIVERSAL_ARCH) {
    return DESKTOP_RELEASE_MACOS_UNIVERSAL_TARGET;
  }
  return DESKTOP_RELEASE_MACOS_AARCH64_TARGET;
};

/**
 * Builds the target release config profile for a requested release target.
 */
export const resolveDesktopReleaseTauriTargetsFromProfile = (
  profile: DesktopReleaseArtifactProfile,
): readonly string[] => {
  const normalizedProfile = normalizeDesktopReleaseArtifactProfile(profile);
  const explicitTargets = [
    ...normalizedProfile.macosArchitectures.map(resolveMacosTargetForArchitecture),
    DESKTOP_RELEASE_WINDOWS_TARGET,
    DESKTOP_RELEASE_LINUX_X64_TARGET,
    DESKTOP_RELEASE_LINUX_ARM64_TARGET,
  ];
  return explicitTargets.filter(
    (target, index, targetCandidates) => targetCandidates.indexOf(target) === index,
  );
};

/**
 * Builds canonical assembled release artifact specs for a target.
 */
export const buildDesktopReleaseArtifactSpecs = (
  metadata: DesktopReleaseArtifactNaming,
  target: DesktopReleaseTarget,
  profile: Partial<DesktopReleaseArtifactProfile> = {},
): readonly DesktopReleaseArtifactSpec[] => {
  const normalizedProfile = normalizeDesktopReleaseArtifactProfile(profile);

  if (target === "macos") {
    return normalizedProfile.macosArchitectures.map((architecture) =>
      createDesktopReleaseArtifactSpec(
        target,
        `${metadata.productName}_${metadata.version}_${architecture}.dmg`,
        "dmg",
      ),
    );
  }

  if (isLinuxTarget(target)) {
    const linuxArtifacts = [...buildLinuxCoreSpecs(metadata, target)];
    if (normalizedProfile.includeLinuxAppImage && target === "linux-x64") {
      linuxArtifacts.push(...buildLinuxAppImageSpecs(metadata, target));
    }
    return normalizedProfile.includeLinuxSignatures
      ? appendLinuxSignatures(linuxArtifacts)
      : linuxArtifacts;
  }

  const windowsArtifacts = [
    createDesktopReleaseArtifactSpec(
      target,
      `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_WINDOWS_ARCH}-setup.exe`,
      "setup",
    ),
    createDesktopReleaseArtifactSpec(
      target,
      `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_WINDOWS_ARCH}-portable.zip`,
      "portable",
    ),
  ];

  if (normalizedProfile.includeWindowsMsi) {
    windowsArtifacts.push(
      createDesktopReleaseArtifactSpec(
        target,
        `${metadata.productName}_${metadata.version}_${DESKTOP_RELEASE_WINDOWS_ARCH}_${DESKTOP_RELEASE_WINDOWS_MSI_LANGUAGE}.msi`,
        "msi",
      ),
    );
  }

  return windowsArtifacts;
};

/**
 * Builds the canonical artifact file names for a target.
 */
export const buildDesktopReleaseArtifactFileNames = (
  metadata: DesktopReleaseArtifactNaming,
  target: DesktopReleaseTarget,
  profile: Partial<DesktopReleaseArtifactProfile> = {},
): readonly string[] =>
  buildDesktopReleaseArtifactSpecs(metadata, target, profile).map((artifact) => artifact.fileName);

/**
 * Builds the candidate Cargo release directories used by native Tauri builds for a target.
 */
export const buildDesktopReleaseDirectoryCandidates = (
  target: DesktopReleaseTarget,
  tauriTarget?: string,
): readonly string[] => {
  const targetInfo = resolveDesktopRuntimeTargetInfo(target);
  return ["target/release", `target/${tauriTarget ?? targetInfo.tauriTarget}/release`] as const;
};

/**
 * Builds the candidate Tauri bundle directories used by native Tauri builds for a target.
 */
export const buildDesktopBundleDirectoryCandidates = (
  target: DesktopReleaseTarget,
  tauriTarget?: string,
): readonly string[] =>
  buildDesktopReleaseDirectoryCandidates(target, tauriTarget).map(
    (releaseDirectory) => `${releaseDirectory}/bundle`,
  );

/**
 * Maps a profile-defined macOS architecture to a Tauri bundle build target.
 */
export const resolveMacosTargetFromProfileArchitecture = (
  architecture: DesktopReleaseMacosArchitecture,
): string => resolveMacosTargetForArchitecture(architecture);

/**
 * Shared type guards for runtime validation of boundary values.
 * Single source of truth — do not duplicate in composables or services.
 */
import type { JsonObject, JsonValue } from "./json";
import { safeParseJson } from "./json";

export const isRecord = <T>(v: T): v is T & JsonObject =>
  typeof v === "object" && v !== null && !Array.isArray(v);

export const asString = <T>(v: T): string | undefined =>
  typeof v === "string" && v.trim().length > 0 ? v : undefined;

export const asStringArray = <T>(v: T): string[] =>
  Array.isArray(v) ? v.filter((e): e is string => typeof e === "string") : [];

export const asNumber = <T>(v: T): number | undefined =>
  typeof v === "number" && !Number.isNaN(v) ? v : undefined;

export const asBoolean = <T>(v: T): boolean | undefined => (typeof v === "boolean" ? v : undefined);

export const asRecord = <T>(v: T): JsonObject | undefined => {
  if (typeof v !== "object" || v === null || Array.isArray(v)) {
    return undefined;
  }
  const parsed = safeParseJson(JSON.stringify(v));
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    return undefined;
  }
  return parsed;
};

export const asJsonArray = <T>(v: T): JsonValue[] | undefined => {
  if (!Array.isArray(v)) {
    return undefined;
  }
  const parsed = safeParseJson(JSON.stringify(v));
  return Array.isArray(parsed) ? parsed : undefined;
};

export const asUnknownArray = asJsonArray;

import { describe, expect, test } from "bun:test";
import { validateLocalAiEndpoint } from "./local-ai-endpoint";

describe("local AI endpoint validation", () => {
  test("allows loopback Ollama-style endpoints", () => {
    expect(validateLocalAiEndpoint("http://localhost:11434/v1")).toEqual({
      ok: true,
      endpoint: "http://localhost:11434/v1",
    });
    expect(validateLocalAiEndpoint("http://127.0.0.1:1234")).toEqual({
      ok: true,
      endpoint: "http://127.0.0.1:1234/",
    });
  });

  test("denies non-loopback and credentialed URLs", () => {
    const credentialed = new URL("http://localhost:11434/v1");
    credentialed.username = "probe-user";
    credentialed.password = "x";
    expect(validateLocalAiEndpoint("http://169.254.169.254/latest").ok).toEqual(false);
    expect(validateLocalAiEndpoint("http://metadata.google.internal/").ok).toEqual(false);
    expect(validateLocalAiEndpoint("http://example.com/v1").ok).toEqual(false);
    expect(validateLocalAiEndpoint(credentialed.toString()).ok).toEqual(false);
    expect(validateLocalAiEndpoint("file:///tmp/not-a-model").ok).toEqual(false);
  });
});

import type { EmailTransportSettings } from "../types/settings";
import { isValidEmail } from "./validation";
const NUM_120 = 120;
const NUM_65535 = 65_535;

/**
 * Returns whether a persisted outbound email transport configuration is complete enough to send mail.
 *
 * @param settings - Persisted transport settings.
 * @param hasPassword - Whether a secret password is stored alongside the public settings.
 * @returns `true` when the transport can be used for delivery.
 */
export function isEmailTransportConfigured(
  settings: EmailTransportSettings | null | undefined,
  hasPassword: boolean,
): boolean {
  if (!settings) {
    return false;
  }

  const host = settings.host.trim();
  const fromEmail = settings.fromEmail.trim();
  const username = settings.username.trim();
  const port = Math.trunc(settings.port);
  const timeout = Math.trunc(settings.connectionTimeoutSeconds);

  if (host.length === 0 || !isValidEmail(fromEmail)) {
    return false;
  }

  if (!Number.isFinite(port) || port < 1 || port > NUM_65535) {
    return false;
  }

  if (!Number.isFinite(timeout) || timeout < 1 || timeout > NUM_120) {
    return false;
  }

  if (username.length === 0) {
    return !hasPassword;
  }

  return hasPassword;
}

import { describe, expect, test } from "bun:test";
import {
  collectDefinedStringValues,
  formatExportDate,
  resolveResumeExportTemplate,
  toCoverLetterParagraphs,
} from "./export-contract";

describe("export contract", () => {
  test("collects only defined non-empty string values", () => {
    expect(collectDefinedStringValues(["alpha", undefined, "", " beta ", "   "])).toEqual([
      "alpha",
      " beta ",
    ]);
  });

  test("resolves the explicit resume template first", () => {
    expect(resolveResumeExportTemplate("creative", "modern")).toBe("creative");
    expect(resolveResumeExportTemplate(undefined, "modern")).toBe("modern");
    expect(resolveResumeExportTemplate("not-a-template", "modern")).toBe("modern");
    expect(resolveResumeExportTemplate("not-a-template", "also-invalid")).toBe("modern");
  });

  test("formats export dates with the shared locale contract", () => {
    expect(formatExportDate(new Date("2026-03-25T00:00:00.000Z"))).toBe("March 25, 2026");
  });

  test("normalizes canonical cover-letter content sections", () => {
    expect(
      toCoverLetterParagraphs({
        opening: "Intro",
        body: ["Impact one", "Impact two"],
        closing: "Close",
      }),
    ).toEqual(["Intro", "Impact one", "Impact two", "Close"]);
  });

  test("falls back to alternate cover-letter section names", () => {
    expect(
      toCoverLetterParagraphs({
        introduction: "Intro",
        main: ["Body"],
        conclusion: "Close",
      }),
    ).toEqual(["Intro", "Body", "Close"]);
  });

  test("preserves mixed cover-letter section naming without dropping intro or closing text", () => {
    expect(
      toCoverLetterParagraphs({
        introduction: "Intro",
        body: ["Body"],
        conclusion: "Close",
      }),
    ).toEqual(["Intro", "Body", "Close"]);
  });

  test("splits raw text cover letters into paragraphs", () => {
    expect(toCoverLetterParagraphs("First paragraph\n\nSecond paragraph")).toEqual([
      "First paragraph",
      "Second paragraph",
    ]);
  });
});

