/**
 * Canonical desktop runtime release targets.
 */
export type DesktopRuntimeReleaseTarget = (typeof DESKTOP_RELEASE_TARGETS)[number];

/**
 * Supported desktop runtime host platforms.
 */
export type DesktopRuntimeHostPlatform = Extract<NodeJS.Platform, "darwin" | "linux" | "win32">;

/**
 * Supported desktop runtime host architectures.
 */
export type DesktopRuntimeHostArch = "arm64" | "x64";

/**
 * Typed runtime manifest contract consumed by the desktop host and verification scripts.
 */
export const desktopRuntimeManifestSchema = z.object({
  serverExecutable: z.string().min(1),
  scriptRunnerExecutable: z.string().min(1),
  scriptRunnerEntrypoint: z.string().min(1).nullable(),
  webviewBootstrapperExecutable: z.string().min(1).nullable().optional(),
  scraperDir: z.string().min(1),
  serverHost: z.string().min(1),
  serverPort: z.number().int().positive(),
  corsOrigins: z.array(z.string().min(1)),
});

/**
 * Parsed desktop runtime manifest shape.
 */
export type DesktopRuntimeManifest = z.infer<typeof desktopRuntimeManifestSchema>;

/**
 * Canonical per-target runtime layout resolved from Tauri target metadata.
 */
export type DesktopRuntimeTargetInfo = {
  readonly target: DesktopRuntimeReleaseTarget;
  readonly tauriTarget: string;
  readonly hostPlatform: DesktopRuntimeHostPlatform;
  readonly hostArch: DesktopRuntimeHostArch;
  readonly serverExecutable: string;
  readonly scriptRunnerExecutable: string;
  readonly scriptRunnerEntrypoint: string;
  readonly scraperDir: string;
  readonly defaultWebviewBootstrapperExecutable: string | null;
};

const WINDOWS_EXECUTABLE_SUFFIX = ".exe" as const;

const appendWindowsExecutableSuffix = (relativePath: string): string =>
  `${relativePath}${WINDOWS_EXECUTABLE_SUFFIX}`;

const DESKTOP_RUNTIME_TARGET_INFO = {
  macos: {
    defaultWebviewBootstrapperExecutable: null,
    hostArch: "arm64",
    hostPlatform: "darwin",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: DESKTOP_RUNTIME_SCRIPT_RUNNER_PATH,
    serverExecutable: DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH,
    tauriTarget: DESKTOP_RELEASE_MACOS_AARCH64_TARGET,
  },
  windows: {
    defaultWebviewBootstrapperExecutable: appendWindowsExecutableSuffix(
      DESKTOP_RUNTIME_WEBVIEW_BOOTSTRAPPER_PATH,
    ),
    hostArch: "x64",
    hostPlatform: "win32",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: appendWindowsExecutableSuffix(DESKTOP_RUNTIME_SCRIPT_RUNNER_PATH),
    serverExecutable: appendWindowsExecutableSuffix(DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH),
    tauriTarget: DESKTOP_RELEASE_WINDOWS_TARGET,
  },
  "linux-x64": {
    defaultWebviewBootstrapperExecutable: null,
    hostArch: "x64",
    hostPlatform: "linux",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: DESKTOP_RUNTIME_LINUX_BUN_PATH,
    serverExecutable: DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH,
    tauriTarget: DESKTOP_RELEASE_LINUX_X64_TARGET,
  },
  "linux-arm64": {
    defaultWebviewBootstrapperExecutable: null,
    hostArch: "arm64",
    hostPlatform: "linux",
    scraperDir: DESKTOP_RUNTIME_SCRAPER_DIR,
    scriptRunnerEntrypoint: DESKTOP_RUNTIME_SCRIPT_RUNNER_ENTRYPOINT_PATH,
    scriptRunnerExecutable: DESKTOP_RUNTIME_LINUX_BUN_PATH,
    serverExecutable: DESKTOP_RUNTIME_SERVER_EXECUTABLE_PATH,
    tauriTarget: DESKTOP_RELEASE_LINUX_ARM64_TARGET,
  },
} as const satisfies Record<DesktopRuntimeReleaseTarget, Omit<DesktopRuntimeTargetInfo, "target">>;

/**
 * Resolves the canonical runtime layout for a release target.
 */
export const resolveDesktopRuntimeTargetInfo = (
  target: DesktopRuntimeReleaseTarget,
): DesktopRuntimeTargetInfo => ({
  target,
  ...DESKTOP_RUNTIME_TARGET_INFO[target],
});

/**
 * Resolves the canonical runtime layout from a Tauri target triple.
 */
export const resolveDesktopRuntimeTargetInfoFromTauriTarget = (
  tauriTarget: string,
): DesktopRuntimeTargetInfo => {
  const resolvedTarget = DESKTOP_RELEASE_TARGETS.find(
    (target) => DESKTOP_RUNTIME_TARGET_INFO[target].tauriTarget === tauriTarget,
  );
  if (!resolvedTarget) {
    throw new Error(`Unsupported desktop Tauri target: ${tauriTarget}`);
  }

  return resolveDesktopRuntimeTargetInfo(resolvedTarget);
};

/**
 * Resolves the canonical runtime layout from the current host platform.
 */
export const resolveDesktopRuntimeTargetInfoFromHost = (
  platform: NodeJS.Platform,
  arch: string,
): DesktopRuntimeTargetInfo => {
  if (platform === "darwin") {
    return resolveDesktopRuntimeTargetInfo("macos");
  }

  if (platform === "win32") {
    return resolveDesktopRuntimeTargetInfo("windows");
  }

  if (platform === "linux") {
    return resolveDesktopRuntimeTargetInfo(arch === "arm64" ? "linux-arm64" : "linux-x64");
  }

  throw new Error(`Unsupported desktop runtime host platform: ${platform}/${arch}`);
};

/**
 * Builds the canonical desktop runtime manifest for a target.
 */
export const buildDesktopRuntimeManifest = (
  target: DesktopRuntimeReleaseTarget,
  options: {
    readonly webviewBootstrapperExecutable?: string | null;
  } = {},
): DesktopRuntimeManifest => {
  const targetInfo = resolveDesktopRuntimeTargetInfo(target);

  return {
    corsOrigins: [...DESKTOP_RUNTIME_CORS_ORIGINS],
    scraperDir: targetInfo.scraperDir,
    scriptRunnerEntrypoint: targetInfo.scriptRunnerEntrypoint,
    scriptRunnerExecutable: targetInfo.scriptRunnerExecutable,
    serverExecutable: targetInfo.serverExecutable,
    serverHost: DESKTOP_RUNTIME_HOST,
    serverPort: DESKTOP_RUNTIME_SERVER_PORT,
    webviewBootstrapperExecutable:
      options.webviewBootstrapperExecutable ?? targetInfo.defaultWebviewBootstrapperExecutable,
  };
};

/**
 * Parses and normalizes a desktop runtime manifest payload.
 */
export const parseDesktopRuntimeManifest = (
  payload: unknown,
  sourceLabel: string,
): DesktopRuntimeManifest => {
  const parsedManifest = desktopRuntimeManifestSchema.safeParse(payload);
  if (!parsedManifest.success) {
    const flattenedErrors = parsedManifest.error.issues
      .map((issue) => `${issue.path.join(".") || "<root>"}: ${issue.message}`)
      .join("; ");
    throw new Error(`Invalid desktop runtime manifest at ${sourceLabel}: ${flattenedErrors}`);
  }

  return {
    ...parsedManifest.data,
    webviewBootstrapperExecutable: parsedManifest.data.webviewBootstrapperExecutable ?? null,
  };
};

/**
 * Returns field-level mismatches between two runtime manifests.
 */
export const getDesktopRuntimeManifestMismatches = (
  actualManifest: DesktopRuntimeManifest,
  expectedManifest: DesktopRuntimeManifest,
): readonly string[] => {
  const mismatches: string[] = [];

  if (actualManifest.serverExecutable !== expectedManifest.serverExecutable) {
    mismatches.push(
      `serverExecutable expected=${expectedManifest.serverExecutable} actual=${actualManifest.serverExecutable}`,
    );
  }
  if (actualManifest.scriptRunnerExecutable !== expectedManifest.scriptRunnerExecutable) {
    mismatches.push(
      `scriptRunnerExecutable expected=${expectedManifest.scriptRunnerExecutable} actual=${actualManifest.scriptRunnerExecutable}`,
    );
  }
  if (actualManifest.scriptRunnerEntrypoint !== expectedManifest.scriptRunnerEntrypoint) {
    mismatches.push(
      `scriptRunnerEntrypoint expected=${expectedManifest.scriptRunnerEntrypoint ?? "null"} actual=${actualManifest.scriptRunnerEntrypoint ?? "null"}`,
    );
  }
  if (
    actualManifest.webviewBootstrapperExecutable !== expectedManifest.webviewBootstrapperExecutable
  ) {
    mismatches.push(
      `webviewBootstrapperExecutable expected=${expectedManifest.webviewBootstrapperExecutable ?? "null"} actual=${actualManifest.webviewBootstrapperExecutable ?? "null"}`,
    );
  }
  if (actualManifest.scraperDir !== expectedManifest.scraperDir) {
    mismatches.push(
      `scraperDir expected=${expectedManifest.scraperDir} actual=${actualManifest.scraperDir}`,
    );
  }
  if (actualManifest.serverHost !== expectedManifest.serverHost) {
    mismatches.push(
      `serverHost expected=${expectedManifest.serverHost} actual=${actualManifest.serverHost}`,
    );
  }
  if (actualManifest.serverPort !== expectedManifest.serverPort) {
    mismatches.push(
      `serverPort expected=${expectedManifest.serverPort} actual=${actualManifest.serverPort}`,
    );
  }
  if (
    actualManifest.corsOrigins.length !== expectedManifest.corsOrigins.length ||
    actualManifest.corsOrigins.some(
      (origin, index) => origin !== expectedManifest.corsOrigins[index],
    )
  ) {
    mismatches.push(
      `corsOrigins expected=${expectedManifest.corsOrigins.join(",")} actual=${actualManifest.corsOrigins.join(",")}`,
    );
  }

  return mismatches;
};

/**
 * Lists files that must exist inside the runtime resource tree for a manifest.
 */
export const listDesktopRuntimeContractPaths = (
  manifest: DesktopRuntimeManifest,
  dependencyPackageNames: readonly string[],
): readonly string[] => {
  const manifestReferencedPaths = [
    "manifest.json",
    manifest.serverExecutable,
    manifest.scriptRunnerExecutable,
    manifest.scriptRunnerEntrypoint,
    manifest.webviewBootstrapperExecutable,
    `${manifest.scraperDir}/package.json`,
    ...dependencyPackageNames.map(
      (packageName) => `${manifest.scraperDir}/node_modules/${packageName}/package.json`,
    ),
  ];

  return manifestReferencedPaths.filter(
    (path): path is string => typeof path === "string" && path.length > 0,
  );
};

/**
 * Wraps a single Promise in Promise.allSettled and returns the first (and only) result.
 * Used for consistent error handling without try-catch.
 * Rejection reasons are normalized to Error at the boundary (throw-safe).
 */

export type SettledResult<T> =
  | { status: "fulfilled"; value: T }
  | { status: "rejected"; reason: Error };

export const settle = async <T>(operation: Promise<T>): Promise<SettledResult<T>> => {
  const outcomes = await Promise.allSettled([operation]);
  const result = outcomes[0];
  if (!result) {
    return { status: "rejected", reason: new Error("settle produced no outcome") };
  }
  if (result.status === "fulfilled") {
    return { status: "fulfilled", value: result.value };
  }

  const rejection: { reason?: Error | string | number | boolean | null | object } = result;
  const reason = rejection.reason;
  if (reason instanceof Error) {
    return { status: "rejected", reason };
  }
  if (typeof reason === "string") {
    return { status: "rejected", reason: new Error(reason) };
  }
  if (typeof reason === "number" || typeof reason === "boolean") {
    return { status: "rejected", reason: new Error(String(reason)) };
  }
  if (reason === null || reason === undefined) {
    return { status: "rejected", reason: new Error("null rejection") };
  }
  return { status: "rejected", reason: new Error("object rejection") };
};

import { AI_PROVIDER_IDS, type AIProviderType } from "../types/ai";
import type { ScrapePersonaEnrichment } from "../types/jobs";
import { asRecord, asString, asStringArray } from "./type-guards";

const SCRAPE_ENRICHMENT_LIST_LIMIT = 4;

const isAIProviderType = (value: string): value is AIProviderType =>
  AI_PROVIDER_IDS.some((provider) => provider === value);

/**
 * Normalizes unknown scrape-enrichment payloads into the shared contract.
 */
export function normalizeScrapePersonaEnrichment(
  value: unknown,
): ScrapePersonaEnrichment | undefined {
  const record = asRecord(value);
  if (!record) {
    return;
  }

  const summary = asString(record.summary);
  if (!summary) {
    return;
  }

  const normalized: ScrapePersonaEnrichment = {
    summary,
    hiringSignals: asStringArray(record.hiringSignals).slice(0, SCRAPE_ENRICHMENT_LIST_LIMIT),
    interviewFocusAreas: asStringArray(record.interviewFocusAreas).slice(
      0,
      SCRAPE_ENRICHMENT_LIST_LIMIT,
    ),
    candidatePitchAngles: asStringArray(record.candidatePitchAngles).slice(
      0,
      SCRAPE_ENRICHMENT_LIST_LIMIT,
    ),
  };

  const provider = asString(record.provider);
  const model = asString(record.model);
  const updatedAt = asString(record.updatedAt);

  if (provider && isAIProviderType(provider)) {
    normalized.provider = provider;
  }
  if (model) {
    normalized.model = model;
  }
  if (updatedAt) {
    normalized.updatedAt = updatedAt;
  }

  return normalized;
}

/**
 * Shared error message extraction. Single source of truth for server and client.
 * Handles Error, Eden/API error shapes (Record with message, value.message).
 */
import { API_ERROR_UNKNOWN } from "../constants/api-errors";
import { isRecord } from "./type-guards";

function toMessage(value: string | undefined): string | null {
  if (typeof value === "string" && value.trim().length > 0) {
    return value;
  }
  return null;
}

/**
 * Extracts a user-facing error message from boundary error values.
 * Supports Error instances, Eden API error shape (Record with message/value.message).
 *
 * @param error - Boundary error value (Error, API response, etc.)
 * @param fallback - Fallback when no message can be extracted. Defaults to API_ERROR_UNKNOWN.
 */
export function toErrorMessage<T>(error: T, fallback?: string): string {
  const resolvedFallback = fallback ?? API_ERROR_UNKNOWN;

  if (error instanceof Error) {
    return toMessage(error.message) ?? resolvedFallback;
  }

  if (typeof error === "string") {
    return toMessage(error) ?? resolvedFallback;
  }

  if (!isRecord(error)) {
    return resolvedFallback;
  }

  const direct = toMessage(typeof error.message === "string" ? error.message : undefined);
  if (direct) {
    return direct;
  }

  const nested = error.value;
  if (!isRecord(nested)) {
    return resolvedFallback;
  }

  return (
    toMessage(typeof nested.message === "string" ? nested.message : undefined) ?? resolvedFallback
  );
}

import { describe, expect, test } from "bun:test";
import {
  buildAutomationProcessEnv,
  CURSOR_SANDBOX_BROWSER_CACHE_MARKER,
  isPollutedPlaywrightBrowsersPath,
  resolvePlaywrightBrowsersPath,
  resolvePlaywrightHostPlatformOverride,
} from "./playwright-browsers-path";

const SANDBOX_CACHE_PATH = `var/folders/x/${CURSOR_SANDBOX_BROWSER_CACHE_MARKER}/abc/playwright`;
const MISSING_CACHE_PATH = "tmp/bao_missing_playwright_cache_path";
const HOST_DEFAULT_PATH = "tmp/bao_host_ms_playwright";

const pathExists =
  (existing: ReadonlySet<string>) =>
  (browsersPath: string): boolean =>
    existing.has(browsersPath);

describe("playwright browsers path sanitization: detects cursor-sandbox browser caches as polluted", () => {
  test("detects cursor-sandbox browser caches as polluted", () => {
    expect(isPollutedPlaywrightBrowsersPath(SANDBOX_CACHE_PATH, () => true)).toBe(true);
  });
});

describe("playwright browsers path sanitization: detects missing browser cache paths as polluted", () => {
  test("detects missing browser cache paths as polluted", () => {
    expect(isPollutedPlaywrightBrowsersPath(MISSING_CACHE_PATH, () => false)).toBe(true);
  });
});

describe("playwright browsers path sanitization: rewrites polluted browsers path when host cache exists", () => {
  test("rewrites polluted browsers path when host cache exists", () => {
    const env = buildAutomationProcessEnv(
      {
        PLAYWRIGHT_BROWSERS_PATH: SANDBOX_CACHE_PATH,
      },
      {
        pathExists: pathExists(new Set([HOST_DEFAULT_PATH])),
        hostDefaultPath: HOST_DEFAULT_PATH,
      },
    );

    expect(env.PLAYWRIGHT_BROWSERS_PATH).toBe(HOST_DEFAULT_PATH);
  });
});

describe("playwright browsers path sanitization: unsets polluted browsers path when host cache is missing", () => {
  test("unsets polluted browsers path when host cache is missing", () => {
    const resolution = resolvePlaywrightBrowsersPath(SANDBOX_CACHE_PATH, {
      pathExists: () => false,
      hostDefaultPath: HOST_DEFAULT_PATH,
    });
    expect(resolution).toEqual({ action: "unset" });
  });
});

describe("playwright browsers path sanitization: derives mac arm64 host platform without reading os.cpus", () => {
  test("derives mac arm64 host platform without reading os.cpus", () => {
    expect(resolvePlaywrightHostPlatformOverride("darwin", "arm64", "25.4.0")).toBe("mac15-arm64");
  });
});

describe("playwright browsers path sanitization: leaves non-mac platforms without a host override", () => {
  test("leaves non-mac platforms without a host override", () => {
    expect(resolvePlaywrightHostPlatformOverride("linux", "x64", "6.8.0")).toBeNull();
  });
});

describe("playwright browsers path sanitization: injects host platform override into automation child env", () => {
  test("injects host platform override into automation child env", () => {
    const env = buildAutomationProcessEnv(
      {},
      {
        pathExists: () => true,
        hostDefaultPath: HOST_DEFAULT_PATH,
      },
      "mac15-arm64",
    );
    expect(env.PLAYWRIGHT_HOST_PLATFORM_OVERRIDE).toBe("mac15-arm64");
  });
});

describe("playwright browsers path sanitization: preserves an existing host platform override", () => {
  test("preserves an existing host platform override", () => {
    const env = buildAutomationProcessEnv(
      {
        PLAYWRIGHT_HOST_PLATFORM_OVERRIDE: "mac14-arm64",
      },
      {
        pathExists: () => true,
        hostDefaultPath: HOST_DEFAULT_PATH,
      },
      "mac15-arm64",
    );
    expect(env.PLAYWRIGHT_HOST_PLATFORM_OVERRIDE).toBe("mac14-arm64");
  });
});

describe("playwright browsers path sanitization: rewrites polluted browsers path and injects host override together", () => {
  test("rewrites polluted browsers path and injects host override together", () => {
    const env = buildAutomationProcessEnv(
      {
        PLAYWRIGHT_BROWSERS_PATH: SANDBOX_CACHE_PATH,
      },
      {
        pathExists: pathExists(new Set([HOST_DEFAULT_PATH])),
        hostDefaultPath: HOST_DEFAULT_PATH,
      },
      "mac15-arm64",
    );
    expect(env.PLAYWRIGHT_BROWSERS_PATH).toBe(HOST_DEFAULT_PATH);
    expect(env.PLAYWRIGHT_HOST_PLATFORM_OVERRIDE).toBe("mac15-arm64");
  });
});

describe("playwright browsers path sanitization: skips host override injection when resolver returns null", () => {
  test("skips host override injection when resolver returns null", () => {
    const env = buildAutomationProcessEnv(
      {},
      {
        pathExists: () => true,
        hostDefaultPath: HOST_DEFAULT_PATH,
      },
      null,
    );
    expect(env.PLAYWRIGHT_HOST_PLATFORM_OVERRIDE).toBeUndefined();
  });
});

