export const AUTOMATION_SCRAPE_TARGET_DETAILS = {
  studios: {
    action: "scrape_studios",
    routeSegment: "studios",
    kind: "studios",
  },
  jobs_hitmarker: {
    action: "scrape_jobs_hitmarker",
    routeSegment: "hitmarker",
