const RATIO_0_8 = 0.8;

export class InterviewService {
  async startSession(
    studioId: string,
    rawConfig?: InterviewConfigInput,
  ): Promise<InterviewSession> {
    const config = normalizeConfig(rawConfig || {});
    const studio = await resolveStudioContext(studioId);
    const questionSet = await generateQuestions(config, studio);

    const id = generateId();
    const now = Date.now();
    const nowIso = new Date(now).toISOString();
    const persistedConfig = toPersistedRecord(config);

    await db.insert(interviewSessions).values({
      id,
      studioId: studio.id,
      config: persistedConfig,
      questions: questionSet,
      responses: [],
      finalAnalysis: null,
      status: "active",
      startTime: now,
      endTime: null,
      createdAt: nowIso,
      updatedAt: nowIso,
    });

    return toInterviewSession({
      id,
      studioId: studio.id,
      config: persistedConfig,
      questions: questionSet,
      responses: [],
      finalAnalysis: null,
      status: "active",
      startTime: now,
      endTime: null,
      createdAt: nowIso,
      updatedAt: nowIso,
    });
  }

  async getSessions(): Promise<InterviewSession[]> {
    const sessions = await db
      .select()
      .from(interviewSessions)
      .orderBy(desc(interviewSessions.createdAt));
    return Promise.all(sessions.map((session) => toInterviewSession(session)));
  }

  async getSession(id: string): Promise<InterviewSession | null> {
    const rows = await db.select().from(interviewSessions).where(eq(interviewSessions.id, id));
    const row = rows[0];
    return row ? toInterviewSession(row) : null;
  }

  private selectQuestionForResponse(
    session: InterviewSession,
    response: InterviewResponse,
  ): InterviewQuestion | null {
    return (
      session.questions.find((entry) => entry.id === response.questionId) ??
      session.questions[session.currentQuestionIndex] ??
      session.questions[session.questions.length - 1] ??
      null
    );
  }

  private buildAnalyzedResponse(
    response: InterviewResponse,
    questionId: string,
    analysis: NonNullable<InterviewResponse["aiAnalysis"]>,
  ): InterviewResponse {
    return {
      ...response,
      questionId,
      duration: Math.max(1, response.duration),
      transcript: response.transcript.trim(),
      timestamp: response.timestamp || Date.now(),
      confidence: Math.max(0, Math.min(1, response.confidence || RATIO_0_8)),
      aiAnalysis: analysis,
    };
  }

  private async persistSessionResponses(options: {
    sessionId: string;
    responses: InterviewResponse[];
    questions: InterviewQuestion[];
    endTime: number | null;
    nowIso: string;
  }): Promise<InterviewSession["status"]> {
    const status: InterviewSession["status"] =
      options.responses.length >= options.questions.length ? "completed" : "active";

    await db
      .update(interviewSessions)
      .set({
        responses: options.responses,
        questions: options.questions,
        status,
        endTime: status === "completed" ? Date.now() : options.endTime,
        updatedAt: options.nowIso,
      })
      .where(eq(interviewSessions.id, options.sessionId));

    return status;
  }

  private async persistFinalAnalysis(sessionId: string, nowIso: string): Promise<void> {
    const finalized = await this.getSession(sessionId);
    if (!finalized) {
      return;
    }

    const studioContext = await resolveStudioContext(finalized.studioId);
    const finalAnalysis = await generateFinalAnalysis(finalized, studioContext);

    await db
      .update(interviewSessions)
      .set({
        finalAnalysis: toPersistedRecord(finalAnalysis),
        updatedAt: nowIso,
      })
      .where(eq(interviewSessions.id, sessionId));
  }

  async addResponse(
    sessionId: string,
    response: InterviewResponse,
  ): Promise<InterviewSession | null> {
    const session = await this.getSession(sessionId);
    if (!session || session.status === "completed") {
      return session;
    }

    const question = this.selectQuestionForResponse(session, response);
    if (!question) {
      return session;
    }

    const studioContext = await resolveStudioContext(session.studioId);
    const analysis = await generateResponseFeedback(
      session,
      studioContext,
      question,
      response.transcript,
    );
    const nowIso = new Date().toISOString();
    const responseWithAnalysis = this.buildAnalyzedResponse(response, question.id, analysis);
    const responses = [...session.responses, responseWithAnalysis];
    const shouldGenerateFollowUp =
      session.config.conversationStyle === "natural" &&
      responses.length < session.config.questionCount;
    const followUpQuestion = shouldGenerateFollowUp
      ? await generateNextNaturalQuestion(session, studioContext, responseWithAnalysis, question)
      : null;
    const questions =
      followUpQuestion && !session.questions.some((entry) => entry.id === followUpQuestion.id)
        ? [...session.questions, followUpQuestion]
        : session.questions;
    const status = await this.persistSessionResponses({
      sessionId,
      responses,
      questions,
      endTime: session.endTime ?? null,
      nowIso,
    });

    if (status === "completed") {
      await this.persistFinalAnalysis(sessionId, nowIso);
    }

    return this.getSession(sessionId);
  }

  async completeSession(id: string): Promise<InterviewSession | null> {
    const session = await this.getSession(id);
    if (!session) {
      return null;
    }
    if (session.status === "completed") {
      return session;
    }

    const studioContext = await resolveStudioContext(session.studioId);
    const finalAnalysis = await generateFinalAnalysis(session, studioContext);
    const now = new Date().toISOString();

    await db
      .update(interviewSessions)
      .set({
        status: "completed",
        endTime: Date.now(),
        finalAnalysis: toPersistedRecord(finalAnalysis),
        updatedAt: now,
      })
      .where(eq(interviewSessions.id, id));

    return this.getSession(id);
  }

  async getStats(): Promise<{
    totalInterviews: number;
    completedInterviews: number;
    averageScore: number;
    strongestAreas: string[];
    improvementAreas: string[];
    totalTimeSpent: number;
    favoriteStudios: string[];
  }> {
    return calculateInterviewStats(await this.getSessions());
  }
}

export const interviewService = new InterviewService();

import { MS_PER_DAY } from "@bao/shared/constants/time";
import type {
  Achievement,
  DailyChallenge,
  GamificationStats,
} from "@bao/shared/types/gamification";
import { isRecord } from "@bao/shared/utils/type-guards";
import {
  type ActionHistoryEntry,
  DAILY_CHALLENGE_DEFINITIONS,
  GAMIFICATION_STAT_KEYS,
  type NumericGamificationStats,
  WEEK_DAYS,
  type WeeklyDaySummary,
  type WeeklyProgressResult,
} from "./gamification-definitions";
import { PERCENT_MAX } from "@bao/shared/constants/numeric";
const NUM_14 = 14;
const NUM_3 = 3;
const NUM_30 = 30;
const NUM_7 = 7;
const RATIO_1_0 = 1.0;
const RATIO_1_25 = 1.25;
const RATIO_1_5 = 1.5;
const RATIO_2_0 = 2.0;
const RATIO_3_0 = 3.0;

export function typeSafeStats(
  stats: Partial<GamificationStats> | null | undefined,
): Partial<GamificationStats> & { actionHistory: ActionHistoryEntry[] } {
  return {
    ...toNumericStats(stats),
    actionHistory: toActionHistory(stats),
  };
}

export function toNumericStats(
  stats: Partial<GamificationStats> | null | undefined,
): NumericGamificationStats {
  if (!stats || typeof stats !== "object") {
    return {};
  }

  const normalized: NumericGamificationStats = {};
  for (const key of GAMIFICATION_STAT_KEYS) {
    const value = stats[key];
    if (typeof value === "number" && Number.isFinite(value)) {
      normalized[key] = value;
    }
  }
  return normalized;
}

export function toActionHistory<T>(stats: T): ActionHistoryEntry[] {
  if (!isRecord(stats)) {
    return [];
  }

  const rawHistory = stats.actionHistory;
  if (!Array.isArray(rawHistory)) {
    return [];
  }

  const entries: ActionHistoryEntry[] = [];
  for (const entry of rawHistory) {
    if (!isRecord(entry)) {
      continue;
    }
    if (typeof entry.action !== "string") {
      continue;
    }
    if (typeof entry.xpGained !== "number") {
      continue;
    }
    if (typeof entry.timestamp !== "string") {
      continue;
    }
    entries.push({
      action: entry.action,
      xpGained: entry.xpGained,
      timestamp: entry.timestamp,
    });
  }
  return entries;
}

export function getNumericStat(stats: NumericGamificationStats, key: string): number {
  const value = stats[key];
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

const STREAK_MULTIPLIER_STEPS = [
  [NUM_30, RATIO_3_0],
  [NUM_14, RATIO_2_0],
  [NUM_7, RATIO_1_5],
  [NUM_3, RATIO_1_25],
] as const;

export function getStreakMultiplier(currentStreak: number): number {
  return STREAK_MULTIPLIER_STEPS.find(([threshold]) => currentStreak >= threshold)?.[1] ?? RATIO_1_0;
}

export function areAchievementRequirementsMet(
  achievement: Achievement,
  pendingStats: NumericGamificationStats,
  existingStats: NumericGamificationStats,
): boolean {
  for (const [key, requiredValue] of Object.entries(achievement.requirements)) {
    const pendingValue = getNumericStat(pendingStats, key);
    const existingValue = getNumericStat(existingStats, key);
    const statValue = pendingValue || existingValue;
    if (statValue < requiredValue) {
      return false;
    }
  }
  return true;
}

export function getDefinedChallenges(): DailyChallenge[] {
  return DAILY_CHALLENGE_DEFINITIONS.map((challenge) => ({ ...challenge }));
}

export function filterActionsByDate(
  actions: ActionHistoryEntry[],
  start: Date,
  end: Date,
): ActionHistoryEntry[] {
  return actions.filter((action) => {
    const timestamp = new Date(action.timestamp);
    return timestamp >= start && timestamp <= end;
  });
}

export function groupActionsByDate(
  actions: ActionHistoryEntry[],
): Map<string, { actions: number; xpEarned: number }> {
  const dayMap = new Map<string, { actions: number; xpEarned: number }>();
  for (const action of actions) {
    const day = action.timestamp.split("T")[0];
    const existing = dayMap.get(day) || { actions: 0, xpEarned: 0 };
    dayMap.set(day, {
      actions: existing.actions + 1,
      xpEarned: existing.xpEarned + (action.xpGained || 0),
    });
  }
  return dayMap;
}

export function groupCategoriesByAction(actions: ActionHistoryEntry[]): Map<string, number> {
  const categoryCount = new Map<string, number>();
  for (const action of actions) {
    const category = action.action?.split(":")[0] || "general";
    categoryCount.set(category, (categoryCount.get(category) || 0) + 1);
  }
  return categoryCount;
}

export function buildWeeklyDaySummaries(
  now: Date,
  dayMap: Map<string, { actions: number; xpEarned: number }>,
): WeeklyDaySummary[] {
  const days: WeeklyDaySummary[] = [];
  for (let offset = WEEK_DAYS - 1; offset >= 0; offset--) {
    const date = new Date(now.getTime() - offset * MS_PER_DAY).toISOString().split("T")[0];
    const dayData = dayMap.get(date) || { actions: 0, xpEarned: 0 };
    days.push({ date, ...dayData });
  }
  return days;
}

export function resolveTopCategory(categoryCount: Map<string, number>): string {
  let topCategory = "general";
  let topCount = 0;
  for (const [category, count] of categoryCount) {
    if (count > topCount) {
      topCategory = category;
      topCount = count;
    }
  }
  return topCategory;
}

export function countCompletedChallenges(
  dailyChallenges: Record<string, string[]>,
  start: Date,
  end: Date,
): number {
  return Object.entries(dailyChallenges).reduce((total, [dateKey, completed]) => {
    const date = new Date(dateKey);
    return date >= start && date <= end && Array.isArray(completed)
      ? total + completed.length
      : total;
  }, 0);
}

export function buildWeeklyProgress(
  stats: Partial<GamificationStats> | null | undefined,
  dailyChallenges: Record<string, string[]>,
): WeeklyProgressResult {
  const now = new Date();
  const weekAgo = new Date(now.getTime() - WEEK_DAYS * MS_PER_DAY);
  const actionHistory = typeSafeStats(stats).actionHistory;
  const weekActions = filterActionsByDate(actionHistory, weekAgo, now);
  const dayMap = groupActionsByDate(weekActions);
  const categoryCount = groupCategoriesByAction(weekActions);

  return {
    challengesCompleted: countCompletedChallenges(dailyChallenges, weekAgo, now),
    xpEarned: weekActions.reduce((sum, action) => sum + (action.xpGained || 0), 0),
    actionsCount: weekActions.length,
    days: buildWeeklyDaySummaries(now, dayMap),
    topCategory: resolveTopCategory(categoryCount),
  };
}

export function buildMonthlyStats(input: {
  currentStreak: number;
  dailyChallenges: Record<string, string[]>;
  stats: Partial<GamificationStats> | null | undefined;
}) {
  const actionHistory = typeSafeStats(input.stats).actionHistory;
  const now = new Date();
  const monthAgo = new Date(now.getTime() - NUM_30 * MS_PER_DAY);
  const monthActions = filterActionsByDate(actionHistory, monthAgo, now);
  const totalXP = monthActions.reduce((sum, action) => sum + (action.xpGained || 0), 0);

  return {
    totalXP,
    levelsGained: Math.floor(totalXP / PERCENT_MAX),
    achievementsUnlocked: monthActions.filter((action) =>
      action.action?.startsWith("Achievement unlocked:"),
    ).length,
    challengesCompleted: countCompletedChallenges(input.dailyChallenges, monthAgo, now),
    actionsCount: monthActions.length,
    streakDays: Math.min(input.currentStreak, NUM_30),
  };
}

export function appendActionHistoryEntry(
  actionHistory: ActionHistoryEntry[],
  entry: ActionHistoryEntry,
  maxEntries: number,
): ActionHistoryEntry[] {
  const updated = [...actionHistory, entry];
  if (updated.length <= maxEntries) {
    return updated;
  }
  return updated.slice(updated.length - maxEntries);
}

