import type { ResumeData } from "@bao/shared/types/resume";
import { resolveResumeExportTemplate } from "@bao/shared/utils/export-contract";
import { Document, Packer } from "docx";
import { buildResumeSections } from "./docx-export-resume-sections";

export async function exportResumeDocxDocument(
  resume: ResumeData,
  templateName?: string,
): Promise<Uint8Array> {
  const resolvedTemplate = resolveResumeExportTemplate(templateName, resume.template);
  const config =
    RESUME_EXPORT_THEME_CONFIGS[resolvedTemplate]?.docx ??
    RESUME_EXPORT_THEME_CONFIGS[RESUME_TEMPLATE_DEFAULT].docx;
  const doc = new Document({
    sections: [{ children: buildResumeSections(resume, config) }],
  });
  const buffer = await Packer.toBuffer(doc);
  return new Uint8Array(buffer);
}

import {
  SCORE_DEVELOPING_THRESHOLD,
  SCORE_PASS_THRESHOLD,
  SCORE_WARNING_THRESHOLD,
} from "@bao/shared/constants/score-thresholds";
import type {
  ReadinessAssessment,
  SkillMapping,
  SkillReadinessFeedbackId,
  SkillReadinessImprovementId,
  SkillReadinessNextStepId,
} from "@bao/shared/types/skill-mapping";
import { PERCENT_MAX } from "@bao/shared/constants/numeric";
const NUM_100 = 100;
const NUM_20 = 20;
const NUM_3 = 3;
const NUM_50 = 50;
const NUM_70 = 70;
const RATIO_0_2 = 0.2;
const RATIO_0_25 = 0.25;
const RATIO_0_3 = 0.3;

type ReadinessMetrics = {
  technicalSkills: SkillMapping[];
  softSkills: SkillMapping[];
  technicalScore: number;
  softSkillsScore: number;
  industryScore: number;
  portfolioScore: number;
  overallScore: number;
};

const buildEmptyReadinessAssessment = (): ReadinessAssessment => ({
  overallScore: 0,
  categories: {
    technical: { score: 0, feedbackId: "empty" },
    softSkills: { score: 0, feedbackId: "empty" },
    industryKnowledge: { score: 0, feedbackId: "empty" },
    portfolio: { score: 0, feedbackId: "empty" },
  },
  improvementSuggestions: ["imp_tech_map", "imp_evidence_add", "imp_portfolio_build"],
  nextSteps: ["step_map_skills_5", "step_explore_categories", "step_setup_profile"],
});

const calculateCategoryScore = (skills: SkillMapping[]): number => {
  if (skills.length === 0) return 0;
  const averageConfidence =
    skills.reduce((sum, skill) => sum + skill.confidence, 0) / skills.length;
  const countBonus = Math.min(NUM_20, skills.length * 2);
  return Math.min(PERCENT_MAX, Math.round(averageConfidence + countBonus));
};

const calculateReadinessMetrics = (mappings: SkillMapping[]): ReadinessMetrics => {
  const technicalSkills = mappings.filter(
    (mapping) => mapping.category === "technical" || mapping.category === "analytical",
  );
  const softSkills = mappings.filter(
    (mapping) =>
      mapping.category === "leadership" ||
      mapping.category === "communication" ||
      mapping.category === "community",
  );
  const technicalScore = calculateCategoryScore(technicalSkills);
  const softSkillsScore = calculateCategoryScore(softSkills);
  const industryScore = Math.min(
    NUM_100,
    mappings.flatMap((mapping) => mapping.industryApplications).length * 10,
  );
  const portfolioScore = Math.min(
    NUM_100,
    mappings.reduce((sum, mapping) => sum + mapping.evidence.length, 0) * NUM_20,
  );
  const overallScore = Math.round(
    technicalScore * RATIO_0_3 + softSkillsScore * RATIO_0_25 + industryScore * RATIO_0_2 + portfolioScore * RATIO_0_25,
  );

  return {
    technicalSkills,
    softSkills,
    technicalScore,
    softSkillsScore,
    industryScore,
    portfolioScore,
    overallScore,
  };
};

const getCategoryFeedback = (score: number): SkillReadinessFeedbackId => {
  if (score >= SCORE_PASS_THRESHOLD) return "excellent";
  if (score >= SCORE_WARNING_THRESHOLD) return "good";
  if (score >= SCORE_DEVELOPING_THRESHOLD) return "developing";
  return "early";
};

const getTechnicalImprovements = (score: number): SkillReadinessImprovementId[] =>
  score >= NUM_70 ? [] : ["imp_tech_map", "imp_conf_up"];

const getSoftSkillImprovements = (score: number): SkillReadinessImprovementId[] =>
  score >= NUM_70 ? [] : ["imp_lead_comm", "imp_team_examples"];

const getIndustryImprovements = (score: number): SkillReadinessImprovementId[] =>
  score >= NUM_70 ? [] : ["imp_industry_research", "imp_role_link"];

const getPortfolioImprovements = (score: number): SkillReadinessImprovementId[] =>
  score >= NUM_70 ? [] : ["imp_evidence_add", "imp_portfolio_build", "imp_achievements_doc"];

const getImprovementSuggestions = (
  overall: number,
  technical: number,
  soft: number,
  portfolio: number,
): SkillReadinessImprovementId[] => {
  const suggestions: SkillReadinessImprovementId[] = [];

  if (technical < SCORE_WARNING_THRESHOLD) suggestions.push("imp_transfer_strengthen");
  if (soft < SCORE_WARNING_THRESHOLD) suggestions.push("imp_leadership_highlight");
  if (portfolio < SCORE_WARNING_THRESHOLD) suggestions.push("imp_evidence_add");
  if (overall < NUM_50) suggestions.push("imp_coverage_broaden");

  if (suggestions.length === 0) {
    suggestions.push("imp_examples_refine", "imp_certs_pursue", "imp_network_pro");
  }

  return suggestions;
};

const getNextSteps = (overall: number): SkillReadinessNextStepId[] => {
  if (overall >= SCORE_PASS_THRESHOLD) {
    return [
      "step_apply_roles",
      "step_network_industry",
      "step_prepare_interviews",
      "step_polish_linkedin",
    ];
  }
  if (overall >= SCORE_WARNING_THRESHOLD) {
    return [
      "step_complete_portfolio",
      "step_map_skills_15",
      "step_evidence_top",
      "step_research_targets",
    ];
  }
  if (overall >= SCORE_DEVELOPING_THRESHOLD) {
    return [
      "step_map_skills_10",
      "step_start_portfolio",
      "step_evidence_abilities",
      "step_explore_pathways",
    ];
  }
  return [
    "step_map_skills_5",
    "step_explore_categories",
    "step_learn_careers",
    "step_setup_profile",
  ];
};

const buildReadinessAssessment = (metrics: ReadinessMetrics): ReadinessAssessment => ({
  overallScore: metrics.overallScore,
  categories: {
    technical: {
      score: metrics.technicalScore,
      feedbackId: getCategoryFeedback(metrics.technicalScore),
      strengths: metrics.technicalSkills.slice(0, NUM_3).map((mapping) => mapping.transferableSkill),
      improvements: getTechnicalImprovements(metrics.technicalScore),
    },
    softSkills: {
      score: metrics.softSkillsScore,
      feedbackId: getCategoryFeedback(metrics.softSkillsScore),
      strengths: metrics.softSkills.slice(0, NUM_3).map((mapping) => mapping.transferableSkill),
      improvements: getSoftSkillImprovements(metrics.softSkillsScore),
    },
    industryKnowledge: {
      score: metrics.industryScore,
      feedbackId: getCategoryFeedback(metrics.industryScore),
      improvements: getIndustryImprovements(metrics.industryScore),
    },
    portfolio: {
      score: metrics.portfolioScore,
      feedbackId: getCategoryFeedback(metrics.portfolioScore),
      improvements: getPortfolioImprovements(metrics.portfolioScore),
    },
  },
  improvementSuggestions: getImprovementSuggestions(
    metrics.overallScore,
    metrics.technicalScore,
    metrics.softSkillsScore,
    metrics.portfolioScore,
  ),
  nextSteps: getNextSteps(metrics.overallScore),
});

export const buildSkillReadinessAssessment = (mappings: SkillMapping[]): ReadinessAssessment =>
  mappings.length === 0
    ? buildEmptyReadinessAssessment()
    : buildReadinessAssessment(calculateReadinessMetrics(mappings));

import { MS_PER_DAY } from "@bao/shared/constants/time";
import type { DailyChallenge } from "@bao/shared/types/gamification";
import { getDefinedChallenges } from "./gamification-progress";

export function buildDailyChallengesView(
  dailyChallenges: Record<string, string[]>,
  now: Date,
): DailyChallenge[] {
  const today = now.toISOString().split("T")[0];
  const todaysChallenges = dailyChallenges[today] || [];

  if (todaysChallenges.length > 0) {
    return getDefinedChallenges().map((challenge) => ({
      ...challenge,
      completed: todaysChallenges.includes(challenge.id),
    }));
  }

  return getDefinedChallenges().map((challenge) => ({
    ...challenge,
    completed: false,
    validUntil: new Date(now.getTime() + MS_PER_DAY).toISOString(),
  }));
}

export function completeChallengeState(input: {
  challengeId: string;
  dailyChallenges: Record<string, string[]>;
  now: Date;
}): { challenge: DailyChallenge; updatedChallenges: Record<string, string[]> } | null {
  const today = input.now.toISOString().split("T")[0];
  const todaysChallenges = input.dailyChallenges[today] || [];

  if (todaysChallenges.includes(input.challengeId)) {
    return null;
  }

  const challenge = getDefinedChallenges().find((candidate) => candidate.id === input.challengeId);
  if (!challenge) {
    return null;
  }

  return {
    challenge,
    updatedChallenges: {
      ...input.dailyChallenges,
      [today]: [...todaysChallenges, input.challengeId],
    },
  };
}

import { MS_PER_DAY } from "@bao/shared/constants/time";
import { getLevelForXP } from "@bao/shared/constants/xp-levels";
import type {
  Achievement,
  DailyChallenge,
  GamificationStats,
  LevelUpResult,
  UserGamificationData,
} from "@bao/shared/types/gamification";
import { settle } from "@bao/shared/utils/promise";
import { createServerLogger } from "../utils/logger";
import { buildAchievementStatuses, findUnlockableAchievements } from "./gamification-achievements";
import { buildDailyChallengesView, completeChallengeState } from "./gamification-challenges";
import { GAMIFICATION_DEFAULT_ID, type WeeklyProgressResult } from "./gamification-definitions";
import {
  buildMonthlyStats,
  buildWeeklyProgress,
  getNumericStat,
  getStreakMultiplier,
  toNumericStats,
  typeSafeStats,
} from "./gamification-progress";
import {
  getOrCreateGamificationProgress,
  persistAchievements,
  persistAwardedXP,
  persistDailyChallenges,
  persistStats,
  persistStreak,
} from "./gamification-storage";

const gamificationLogger = createServerLogger("gamification");

export class GamificationService {
  private readonly DEFAULT_ID = GAMIFICATION_DEFAULT_ID;

  async getProgress(): Promise<UserGamificationData> {
    return await getOrCreateGamificationProgress(this.DEFAULT_ID);
  }

  async awardXP(amount: number, reason: string): Promise<LevelUpResult | null> {
    const progress = await this.getProgress();
    const multiplier = getStreakMultiplier(progress.currentStreak);
    const adjustedAmount = Math.round(amount * multiplier);
    const oldLevelData = getLevelForXP(progress.xp);
    const newXP = progress.xp + adjustedAmount;
    const newLevelData = getLevelForXP(newXP);
    const now = new Date().toISOString();

    await this.updateStreak();
    await persistAwardedXP({
      actionEntry: {
        action: reason,
        xpGained: adjustedAmount,
        multiplier,
        timestamp: now,
      },
      id: this.DEFAULT_ID,
      newLevel: newLevelData.level,
      newXP,
      stats: typeSafeStats(progress.stats),
    });

    if (newLevelData.level <= progress.level) {
      return null;
    }

    return {
      xpGained: adjustedAmount,
      oldLevel: progress.level,
      newLevel: newLevelData.level,
      oldTitle: oldLevelData.title,
      newTitle: newLevelData.title,
      unlockedFeatures: newLevelData.features || [],
      bonusXP: adjustedAmount - amount,
    };
  }

  async getAchievements(): Promise<Achievement[]> {
    const progress = await this.getProgress();
    return buildAchievementStatuses(progress.achievements);
  }

  async checkAchievements(stats: Partial<GamificationStats>): Promise<Achievement[]> {
    const progress = await this.getProgress();
    const unlockable = findUnlockableAchievements({
      achievements: await this.getAchievements(),
      existingStats: toNumericStats(progress.stats),
      pendingStats: toNumericStats(stats),
    });

    if (unlockable.length === 0) {
      return [];
    }

    const now = new Date().toISOString();
    const unlockedIds = Array.from(
      new Set([...progress.achievements, ...unlockable.map((achievement) => achievement.id)]),
    );
    await persistAchievements({
      achievements: unlockedIds,
      id: this.DEFAULT_ID,
      updatedAt: now,
    });

    await this.awardAchievementsSequentially(unlockable, 0);
    return unlockable.map((achievement) => ({ ...achievement, unlocked: true, unlockedAt: now }));
  }

  private async awardAchievementsSequentially(
    achievements: Achievement[],
    index: number,
  ): Promise<void> {
    if (index >= achievements.length) {
      return;
    }

    const achievement = achievements[index];
    await this.awardXP(achievement.xpReward, `Achievement unlocked: ${achievement.name}`);
    await this.awardAchievementsSequentially(achievements, index + 1);
  }

  async getDailyChallenges(): Promise<DailyChallenge[]> {
    const progress = await this.getProgress();
    return buildDailyChallengesView(progress.dailyChallenges, new Date());
  }

  async completeChallenge(challengeId: string): Promise<boolean> {
    const progress = await this.getProgress();
    const now = new Date();
    const completedChallenge = completeChallengeState({
      challengeId,
      dailyChallenges: progress.dailyChallenges,
      now,
    });

    if (!completedChallenge) {
      return false;
    }

    await persistDailyChallenges({
      dailyChallenges: completedChallenge.updatedChallenges,
      id: this.DEFAULT_ID,
      updatedAt: now.toISOString(),
    });
    await this.awardXP(
      completedChallenge.challenge.xpReward,
      `Daily challenge completed: ${completedChallenge.challenge.name}`,
    );

    return true;
  }

  async updateStreak(): Promise<void> {
    const progress = await this.getProgress();
    const today = new Date().toISOString().split("T")[0];
    const lastActive = progress.lastActiveDate?.split("T")[0];

    if (!lastActive || lastActive === today) {
      return;
    }

    const yesterday = new Date(Date.now() - MS_PER_DAY).toISOString().split("T")[0];
    const currentStreak = lastActive === yesterday ? progress.currentStreak + 1 : 1;
    const longestStreak = Math.max(progress.longestStreak, currentStreak);
    const now = new Date().toISOString();

    await persistStreak({
      currentStreak,
      id: this.DEFAULT_ID,
      lastActiveDate: now,
      longestStreak,
      updatedAt: now,
    });
  }

  async getWeeklyProgress(): Promise<WeeklyProgressResult> {
    const progress = await this.getProgress();
    return buildWeeklyProgress(progress.stats, progress.dailyChallenges);
  }

  async getMonthlyStats(): Promise<{
    totalXP: number;
    levelsGained: number;
    achievementsUnlocked: number;
    challengesCompleted: number;
    actionsCount: number;
    streakDays: number;
  }> {
    const progress = await this.getProgress();
    return buildMonthlyStats({
      currentStreak: progress.currentStreak,
      dailyChallenges: progress.dailyChallenges,
      stats: progress.stats,
    });
  }

  async trackAction(
    statKey: keyof GamificationStats,
    xpAmount: number,
    reason: string,
  ): Promise<{ readonly xpAwarded: number; readonly reason: string }> {
    const progress = await this.getProgress();
    const currentStats = toNumericStats(progress.stats);
    const updatedStats: Partial<GamificationStats> = {
      ...currentStats,
      [statKey]: getNumericStat(currentStats, statKey) + 1,
    };

    const now = new Date().toISOString();
    await persistStats({
      id: this.DEFAULT_ID,
      stats: updatedStats,
      updatedAt: now,
    });

    await this.awardXP(xpAmount, reason);
    await this.checkAchievements(updatedStats);
    return { xpAwarded: xpAmount, reason };
  }

  trackActionFireAndForget(
    statKey: keyof GamificationStats,
    xpAmount: number,
    reason: string,
  ): void {
    settle(this.trackAction(statKey, xpAmount, reason)).then(
      (result) => {
        if (result.status === "rejected") {
          gamificationLogger.error("trackAction failed", {
            statKey,
            reason,
            err: result.reason instanceof Error ? result.reason.message : String(result.reason),
          });
        }
      },
      () => undefined,
    );
  }
}

export const gamificationService = new GamificationService();

