  DOCX_COVER_LETTER_FONT_BODY_PT,
  DOCX_COVER_LETTER_FONT_HEADER_PT,
} from "./docx-export-contracts";

function buildCoverLetterHeader(userProfile: CoverLetterUserProfile): Paragraph[] {
  const children = [
    new Paragraph({
      children: [
        new TextRun({
          text: userProfile.name,
          bold: true,
          size: DOCX_COVER_LETTER_FONT_HEADER_PT * 2,
          color: COVER_LETTER_DOCX_PRIMARY_COLOR,
          font: COVER_LETTER_DOCX_FONT_FAMILY,
        }),
      ],
      spacing: { after: 60 },
    }),
  ];

  const contactParts = collectDefinedStringValues([
    userProfile.email,
    userProfile.phone,
    userProfile.location,
  ]);
  if (contactParts.length > 0) {
    children.push(
      new Paragraph({
        children: [
          new TextRun({
            text: contactParts.join(" | "),
            size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
            color: COVER_LETTER_DOCX_MUTED_COLOR,
            font: COVER_LETTER_DOCX_FONT_FAMILY,
          }),
        ],
        spacing: { after: 140 },
      }),
    );
  }

  children.push(
    new Paragraph({
      children: [
        new TextRun({
          text: formatExportDate(new Date()),
          size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
          color: COVER_LETTER_DOCX_MUTED_COLOR,
          font: COVER_LETTER_DOCX_FONT_FAMILY,
        }),
      ],
      spacing: { after: 200 },
    }),
  );

  return children;
}

function buildCoverLetterRecipientBlock(coverLetter: CoverLetterPayload): Paragraph[] {
  return [
    new Paragraph({
      children: [
        new TextRun({
          text: coverLetter.company,
          bold: true,
          size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
          color: COVER_LETTER_DOCX_PRIMARY_COLOR,
          font: COVER_LETTER_DOCX_FONT_FAMILY,
        }),
      ],
    }),
    new Paragraph({
      children: [
        new TextRun({
          text: `Re: ${coverLetter.position}`,
          italics: true,
          size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
          color: COVER_LETTER_DOCX_ACCENT_COLOR,
          font: COVER_LETTER_DOCX_FONT_FAMILY,
        }),
      ],
      spacing: { after: 140 },
    }),
    createDivider(COVER_LETTER_DOCX_LINE_COLOR),
  ];
}

function buildCoverLetterBodyParagraphs(content: unknown): Paragraph[] {
  return toCoverLetterParagraphs(content).map(
    (paragraph) =>
      new Paragraph({
        children: [
          new TextRun({
            text: paragraph,
            size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
            color: COVER_LETTER_DOCX_TEXT_COLOR,
            font: COVER_LETTER_DOCX_FONT_FAMILY,
          }),
        ],
        spacing: { after: 160 },
      }),
  );
}

function buildCoverLetterSignature(userProfile: CoverLetterUserProfile): Paragraph[] {
  return [
    new Paragraph({
      children: [
        new TextRun({
          text: COVER_LETTER_DEFAULT_SIGNATURE,
          size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
          color: COVER_LETTER_DOCX_TEXT_COLOR,
          font: COVER_LETTER_DOCX_FONT_FAMILY,
        }),
      ],
      spacing: { before: 200, after: 40 },
    }),
    new Paragraph({
      children: [
        new TextRun({
          text: userProfile.name,
          bold: true,
          size: DOCX_COVER_LETTER_FONT_BODY_PT * 2,
          color: COVER_LETTER_DOCX_TEXT_COLOR,
          font: COVER_LETTER_DOCX_FONT_FAMILY,
        }),
      ],
    }),
  ];
}

export async function exportCoverLetterDocxDocument(
  coverLetter: CoverLetterPayload,
  userProfile: CoverLetterUserProfile,
): Promise<Uint8Array> {
  const doc = new Document({
    sections: [
      {
        children: [
          ...buildCoverLetterHeader(userProfile),
          ...buildCoverLetterRecipientBlock(coverLetter),
          ...buildCoverLetterBodyParagraphs(coverLetter.content),
          ...buildCoverLetterSignature(userProfile),
        ],
      },
    ],
  });
  const buffer = await Packer.toBuffer(doc);
  return new Uint8Array(buffer);
}

import type { InterviewSession } from "@bao/shared/types/interview";
import { resolveStudioContext } from "./interview-service-context";
import type { DBInterviewSession } from "./interview-service-contracts";
import {
  normalizeFinalAnalysis,
  normalizeInterviewSessionStatus,
  normalizeQuestions,
  normalizeResponses,
  normalizeSessionConfig,
} from "./interview-service-normalizers";
import { buildInterviewerPersona } from "./interview-service-prompt-context";

export async function toInterviewSession(row: DBInterviewSession): Promise<InterviewSession> {
  const config = normalizeSessionConfig(row);
  const studio = await resolveStudioContext(row.studioId);
  const questions = normalizeQuestions(row.questions);
  const responses = normalizeResponses(row.responses);
  const finalAnalysis = normalizeFinalAnalysis(row.finalAnalysis);

  return {
    id: row.id,
    studioId: row.studioId,
    config,
    questions,
    currentQuestionIndex: Math.min(responses.length, questions.length),
    totalQuestions: questions.length,
    startTime: row.startTime || Date.now(),
    status: normalizeInterviewSessionStatus(row.status),
    responses,
    interviewerPersona: buildInterviewerPersona(studio, config),
    ...(row.endTime ? { endTime: row.endTime } : {}),
    ...(finalAnalysis ? { finalAnalysis } : {}),
  };
}

