    x: context.margin,
    y: context.yPosition,
    size: 9,
    font: context.boldFont,
    color: PORTFOLIO_PDF_COLORS.accent,
  });
  context.yPosition -= NUM_13;

  context.page.drawText(`${index + 1}. ${project.title}`, {
    x: context.margin,
