  if (!project.featured) {
    return;
  }

  context.page.drawText("* FEATURED", {
    x: context.margin,
    y: context.yPosition,
    size: 9,
    font: context.boldFont,
    color: PORTFOLIO_PDF_COLORS.featured,
  });
