  ensurePortfolioSpace(context, NUM_25);
  context.page.drawText(links.join(" | "), {
    x: context.margin,
    y: context.yPosition,
    size: 9,
    font: context.font,
    color: PORTFOLIO_PDF_COLORS.accent,
