  DOCX_RESUME_FONT_HEADER_PT,
  type DocxTemplateConfig,
} from "./docx-export-contracts";
import {
  buildEducationItem,
  buildExperienceItem,
  buildGamingExperienceSection,
  buildProjectItem,
  buildSkillsSection,
} from "./docx-export-resume-content";
import { buildResumeHeader } from "./docx-export-resume-header";

function buildSummarySection(resume: ResumeData, config: DocxTemplateConfig): Paragraph[] {
  if (!resume.summary) {
    return [];
  }

  return [
    createSectionHeading(
      "Summary",
      config.primaryColorHex,
      DOCX_RESUME_FONT_HEADER_PT,
      config.fontFamily,
    ),
    new Paragraph({
      children: [
        new TextRun({
          text: resume.summary,
          size: DOCX_RESUME_FONT_BODY_PT * 2,
          font: config.fontFamily,
        }),
      ],
      spacing: { after: 120 },
    }),
  ];
}

function buildRepeatableSection(
  title: string,
  config: DocxTemplateConfig,
  items: Paragraph[],
): Paragraph[] {
  if (items.length === 0) {
    return [];
  }

  return [
    createSectionHeading(
      title,
      config.primaryColorHex,
      DOCX_RESUME_FONT_HEADER_PT,
      config.fontFamily,
    ),
    ...items,
  ];
}

export function buildResumeSections(resume: ResumeData, config: DocxTemplateConfig): Paragraph[] {
  const experienceItems =
    resume.experience?.flatMap((item) => buildExperienceItem(item, config)) ?? [];
  const educationItems =
    resume.education?.flatMap((item) => buildEducationItem(item, config)) ?? [];
  const skillItems = resume.skills ? buildSkillsSection(resume.skills, config) : [];
  const projectItems =
    resume.projects?.flatMap((project) => buildProjectItem(project, config)) ?? [];
  const gamingItems = resume.gamingExperience
    ? buildGamingExperienceSection(resume.gamingExperience, config)
    : [];

  return [
    ...(resume.personalInfo ? buildResumeHeader(resume.personalInfo, config) : []),
    createDivider(config.primaryColorHex),
    ...buildSummarySection(resume, config),
    ...buildRepeatableSection("Experience", config, experienceItems),
    ...buildRepeatableSection("Education", config, educationItems),
    ...buildRepeatableSection("Skills", config, skillItems),
    ...buildRepeatableSection("Projects", config, projectItems),
    ...buildRepeatableSection("Gaming Experience", config, gamingItems),
  ];
}

import {
  API_ERROR_CREATE_PROJECT,
  API_ERROR_INVALID_PROJECT_ID_REORDER,
} from "@bao/shared/constants/api-errors";
import type { PortfolioData, PortfolioProject } from "@bao/shared/types/portfolio";
import type {
  CreatePortfolioProjectPayload,
  PortfolioUpdatePayload,
  UpdatePortfolioProjectPayload,
} from "./portfolio-service-contracts";
import { toPortfolioData } from "./portfolio-service-normalizers";
import {
  createProject,
  deleteProjectById,
  getOrCreateDefaultPortfolioRecord,
  getPortfolioRecord,
  getProjectById,
  getProjectsForPortfolio,
  reorderPortfolioProjects,
  serializePortfolioMetadata,
  updatePortfolioMetadata,
  updateProjectById,
} from "./portfolio-service-storage";

export class PortfolioService {
  /**
   * Get the full portfolio contract (header + projects).
   */
  async getPortfolio(): Promise<PortfolioData> {
    const portfolio = (await getPortfolioRecord()) ?? (await getOrCreateDefaultPortfolioRecord());
    const projects = await this.getProjects(portfolio.id);
    return toPortfolioData(portfolio, projects);
  }

  /**
   * Update portfolio metadata
   */
  async updatePortfolio(data: PortfolioUpdatePayload): Promise<PortfolioData> {
    const portfolio = await getOrCreateDefaultPortfolioRecord();
    await updatePortfolioMetadata(
      portfolio.id,
      serializePortfolioMetadata(data.metadata),
      new Date().toISOString(),
    );

    const updated = await getOrCreateDefaultPortfolioRecord();
    const projects = await this.getProjects(portfolio.id);
    return toPortfolioData(updated, projects);
  }

  /**
   * Get all projects for a portfolio
   */
  async getProjects(portfolioId: string): Promise<PortfolioProject[]> {
    return getProjectsForPortfolio(portfolioId);
  }

  /**
   * Add a new project to a portfolio
   */
  async addProject(
    portfolioId: string,
    data: CreatePortfolioProjectPayload,
  ): Promise<PortfolioProject> {
    const id = await createProject(portfolioId, data);
    const created = await this.getProject(id);
    if (!created) {
      throw new Error(API_ERROR_CREATE_PROJECT);
    }

    return created;
  }

  /**
   * Get a single project by ID
   */
  async getProject(id: string): Promise<PortfolioProject | null> {
    return getProjectById(id);
  }

  /**
   * Update a project
   */
  async updateProject(
    id: string,
    data: UpdatePortfolioProjectPayload,
  ): Promise<PortfolioProject | null> {
    const updated = await updateProjectById(id, data);
    if (!updated) {
      return null;
    }
    return this.getProject(id);
  }

  /**
   * Delete a project
   */
  async deleteProject(id: string): Promise<boolean> {
    return deleteProjectById(id);
  }

  /**
   * Reorder projects by updating their sortOrder
   */
  async reorderProjects(portfolioId: string, orderedIds: string[]): Promise<boolean> {
    const result = await reorderPortfolioProjects(portfolioId, orderedIds);
    if (!result.valid) {
      throw new Error(API_ERROR_INVALID_PROJECT_ID_REORDER);
    }
    return result.valid;
  }

  /**
   * Fetch the canonical portfolio payload used by API responses.
   */
  async getPortfolioById(portfolioId: string): Promise<PortfolioData | null> {
    const portfolio = await getPortfolioRecord(portfolioId);
    if (!portfolio) {
      return null;
    }

    const projects = await this.getProjects(portfolio.id);
    return toPortfolioData(portfolio, projects);
  }

  /**
   * Fetch or create the default portfolio and return the full portfolio payload.
   */
  async getPortfolioPayload(): Promise<PortfolioData> {
    const portfolio = await getOrCreateDefaultPortfolioRecord();
    const projects = await this.getProjects(portfolio.id);
    return toPortfolioData(portfolio, projects);
  }
}

export const portfolioService = new PortfolioService();

import { STATISTICS_AUTOMATION_RUNS_LIMIT } from "@bao/shared/constants/statistics";
import type {
  AutomationStats,
  CareerProgress,
  DashboardStats,
  WeeklyActivity,
} from "@bao/shared/types/search";
import { DEFAULT_PROFILE_ID } from "@bao/shared/types/settings-defaults";
import { isRecord } from "@bao/shared/utils/type-guards";
import { count, desc, eq } from "drizzle-orm";
import { db } from "../db/client";
import { automationRuns } from "../db/schema/automation-runs";
import { chatHistory } from "../db/schema/chat-history";
import { coverLetters } from "../db/schema/cover-letters";
import { gamification } from "../db/schema/gamification";
import { interviewSessions } from "../db/schema/interviews";
import { applications, savedJobs } from "../db/schema/jobs";
import { portfolioProjects } from "../db/schema/portfolios";
import { resumes } from "../db/schema/resumes";
import { skillMappings } from "../db/schema/skill-mappings";
import { userProfile } from "../db/schema/user";
import {
  buildCareerProgress,
  buildWeeklyActivity,
  parseActionHistory,
} from "./statistics-service-activity";
import { PERCENT_MAX } from "@bao/shared/constants/numeric";
const NUM_5 = 5;

export class StatisticsService {
  private async runBestEffort(operation: () => Promise<void>): Promise<void> {
    await operation().then(
      () => undefined,
      () => undefined,
    );
  }

  async getDashboardStats(): Promise<DashboardStats> {
    const profileCompleteness = await this.getProfileCompleteness();
    const jobStats = await this.getJobStats();
    const resumeStats = await this.getResumeStats();
    const clCount = await this.getCoverLetterCount();
    const projectCount = await this.getPortfolioProjectCount();
    const interviewStats = await this.getInterviewStats();
    const mappedCount = await this.getMappedSkillCount();
    const aiStats = await this.getAiStats();
    const gamStats = await this.getGamificationStats();
    const autoStats = await this.getAutomationStats();

    return {
      profile: { completeness: profileCompleteness },
      jobs: jobStats,
      resumes: resumeStats,
      coverLetters: { count: clCount },
      portfolio: { projectCount },
      interviews: interviewStats,
      skills: { mappedCount },
      ai: aiStats,
      gamification: gamStats,
      automation: autoStats,
    };
  }

  private async getProfileCompleteness(): Promise<number> {
    let profileCompleteness = 0;
    await this.runBestEffort(async () => {
      const profileRows = await db
        .select()
        .from(userProfile)
        .where(eq(userProfile.id, DEFAULT_PROFILE_ID));
      const profile = profileRows[0];
      if (!profile) {
        return;
      }
      const fields = [
        profile.name,
        profile.email,
        profile.location,
        profile.summary,
        profile.currentRole,
      ];
      const filled = fields.filter((field) => field && String(field).trim().length > 0).length;
      profileCompleteness = Math.round((filled / fields.length) * PERCENT_MAX);
    });
    return profileCompleteness;
  }

  private async getJobStats(): Promise<DashboardStats["jobs"]> {
    const jobStats: DashboardStats["jobs"] = {
      saved: 0,
      applied: 0,
      interviewing: 0,
      offered: 0,
    };
    await this.runBestEffort(async () => {
      const savedCount = await db.select({ count: count() }).from(savedJobs);
      jobStats.saved = savedCount[0]?.count || 0;
      const applicationRows = await db.select().from(applications);
      for (const app of applicationRows) {
        const status = app.status?.toLowerCase() || "";
        if (status === "applied") jobStats.applied++;
        else if (status === "interviewing") jobStats.interviewing++;
        else if (status === "offered") jobStats.offered++;
      }
    });
    return jobStats;
  }

  private async getResumeStats(): Promise<DashboardStats["resumes"]> {
    const resumeStats: DashboardStats["resumes"] = {
      count: 0,
      lastUpdated: null,
    };
    await this.runBestEffort(async () => {
      const resumeCount = await db.select({ count: count() }).from(resumes);
      resumeStats.count = resumeCount[0]?.count || 0;
    });
    return resumeStats;
  }

  private async getCoverLetterCount(): Promise<number> {
    let countValue = 0;
    await this.runBestEffort(async () => {
      const result = await db.select({ count: count() }).from(coverLetters);
      countValue = result[0]?.count || 0;
    });
    return countValue;
  }

  private async getPortfolioProjectCount(): Promise<number> {
    let projectCount = 0;
    await this.runBestEffort(async () => {
      const result = await db.select({ count: count() }).from(portfolioProjects);
      projectCount = result[0]?.count || 0;
    });
    return projectCount;
  }

  private async getInterviewStats(): Promise<DashboardStats["interviews"]> {
    const interviewStats: DashboardStats["interviews"] = {
      totalSessions: 0,
      averageScore: null,
    };
    await this.runBestEffort(async () => {
      const result = await db.select({ count: count() }).from(interviewSessions);
      interviewStats.totalSessions = result[0]?.count || 0;
    });
    return interviewStats;
  }

  private async getMappedSkillCount(): Promise<number> {
    let mappedCount = 0;
    await this.runBestEffort(async () => {
      const result = await db.select({ count: count() }).from(skillMappings);
      mappedCount = result[0]?.count || 0;
    });
    return mappedCount;
  }

  private async getAiStats(): Promise<DashboardStats["ai"]> {
    const aiStats: DashboardStats["ai"] = {
      chatMessages: 0,
      chatSessions: 0,
    };
    await this.runBestEffort(async () => {
      const messageCount = await db.select({ count: count() }).from(chatHistory);
      aiStats.chatMessages = messageCount[0]?.count || 0;
    });
    return aiStats;
  }

  private async getGamificationStats(): Promise<DashboardStats["gamification"]> {
    const gamStats: DashboardStats["gamification"] = {
      level: 1,
      xp: 0,
      achievements: 0,
      streak: 0,
    };
    await this.runBestEffort(async () => {
      const gamRows = await db
        .select()
        .from(gamification)
        .where(eq(gamification.id, DEFAULT_PROFILE_ID));
      const gamificationRow = gamRows[0];
      if (!gamificationRow) {
        return;
      }
      gamStats.level = gamificationRow.level || 1;
      gamStats.xp = gamificationRow.xp || 0;
      gamStats.achievements = Array.isArray(gamificationRow.achievements)
        ? gamificationRow.achievements.length
        : 0;
      gamStats.streak = gamificationRow.currentStreak || 0;
    });
    return gamStats;
  }

  private async getAutomationStats(): Promise<AutomationStats> {
    const automationStats: AutomationStats = {
      totalRuns: 0,
      successfulRuns: 0,
      successRate: 0,
      todayRuns: 0,
      recentRuns: [],
    };
    await this.runBestEffort(async () => {
      const allRuns = await db
        .select()
        .from(automationRuns)
        .orderBy(desc(automationRuns.createdAt))
        .limit(STATISTICS_AUTOMATION_RUNS_LIMIT);
      automationStats.totalRuns = allRuns.length;
      automationStats.successfulRuns = allRuns.filter((run) => run.status === "success").length;
      automationStats.successRate =
        automationStats.totalRuns > 0
          ? Math.round((automationStats.successfulRuns / automationStats.totalRuns) * PERCENT_MAX)
          : 0;
      const today = new Date().toISOString().split("T")[0];
      automationStats.todayRuns = allRuns.filter((run) => run.createdAt?.startsWith(today)).length;
      automationStats.recentRuns = allRuns.slice(0, NUM_5).map((run) => ({
        id: run.id,
        type: run.type,
        status: run.status,
        createdAt: run.createdAt,
      }));
    });
    return automationStats;
  }

  async getWeeklyActivity(): Promise<WeeklyActivity> {
    const gamRows = await db
      .select()
      .from(gamification)
      .where(eq(gamification.id, DEFAULT_PROFILE_ID));
    const stats = gamRows[0]?.stats;
    const actionHistory = isRecord(stats) ? parseActionHistory(stats.actionHistory) : [];
    return buildWeeklyActivity(actionHistory);
  }

  async getCareerProgress(): Promise<CareerProgress> {
    let mappedSkills = 0;
    await this.runBestEffort(async () => {
      const skillResult = await db.select({ count: count() }).from(skillMappings);
      mappedSkills = skillResult[0]?.count || 0;
    });

    let applicationStatuses: string[] = [];
    await this.runBestEffort(async () => {
      const allApps = await db.select().from(applications);
      applicationStatuses = allApps.map((application) => application.status || "");
    });

    return buildCareerProgress(mappedSkills, applicationStatuses);
  }
}

export const statisticsService = new StatisticsService();

import { AI_OPERATION_TIMEOUT_MS } from "@bao/shared/constants/interview";

export async function withAiOperationTimeout<T>(
  operation: () => Promise<T>,
  timeoutMs = AI_OPERATION_TIMEOUT_MS,
): Promise<T | null> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return Promise.race([
    operation(),
    new Promise<T>((_, reject) => {
      timer = setTimeout(() => {
        reject(new Error(`AI operation timed out after ${timeoutMs}ms`));
      }, timeoutMs);
    }),
  ])
    .then(
      (value) => value,
      () => null,
    )
    .finally(() => {
      if (timer) {
        clearTimeout(timer);
      }
    });
}

