import type { SkillMapping } from "@bao/shared/types/skill-mapping";
import { generateId } from "@bao/shared/utils/validation";
import { eq } from "drizzle-orm";
import { db } from "../db/client";
import { skillMappings } from "../db/schema/skill-mappings";
const NUM_50 = 50;

export type SkillMappingInsert = Omit<SkillMapping, "id">;
export type SkillMappingUpdate = Partial<SkillMapping>;
type SkillMappingRow = typeof skillMappings.$inferSelect;

const toSkillMappingInsert = (data: SkillMappingInsert, now: string, id: string) => ({
  id,
  gameExpression: data.gameExpression,
  transferableSkill: data.transferableSkill,
  industryApplications: data.industryApplications || [],
  evidence: data.evidence || [],
  confidence: data.confidence || NUM_50,
  category: data.category,
  demandLevel: data.demandLevel,
  aiGenerated: data.aiGenerated,
  createdAt: now,
  updatedAt: now,
});

const toSkillMappingUpdate = (
  data: SkillMappingUpdate,
  now: string,
): Partial<typeof skillMappings.$inferInsert> => {
  return {
    updatedAt: now,
    ...(data.gameExpression !== undefined ? { gameExpression: data.gameExpression } : {}),
    ...(data.transferableSkill !== undefined ? { transferableSkill: data.transferableSkill } : {}),
    ...(data.industryApplications !== undefined
      ? { industryApplications: data.industryApplications }
      : {}),
    ...(data.evidence !== undefined ? { evidence: data.evidence } : {}),
    ...(data.confidence !== undefined ? { confidence: data.confidence } : {}),
    ...(data.category !== undefined ? { category: data.category } : {}),
    ...(data.demandLevel !== undefined ? { demandLevel: data.demandLevel } : {}),
    ...(data.aiGenerated !== undefined ? { aiGenerated: data.aiGenerated } : {}),
  };
};

export async function listSkillMappingRows(): Promise<SkillMappingRow[]> {
  return db.select().from(skillMappings);
}

export async function readSkillMappingRow(id: string): Promise<SkillMappingRow | null> {
  const results = await db.select().from(skillMappings).where(eq(skillMappings.id, id));
  return results[0] ?? null;
}

export async function createSkillMappingRow(data: SkillMappingInsert): Promise<string> {
  const id = generateId();
  const now = new Date().toISOString();
  await db.insert(skillMappings).values(toSkillMappingInsert(data, now, id));
  return id;
}

export async function updateSkillMappingRow(id: string, data: SkillMappingUpdate): Promise<void> {
  const now = new Date().toISOString();
  await db
    .update(skillMappings)
    .set(toSkillMappingUpdate(data, now))
    .where(eq(skillMappings.id, id));
}

export async function deleteSkillMappingRow(id: string): Promise<void> {
  await db.delete(skillMappings).where(eq(skillMappings.id, id));
}

import type { ResumeData } from "@bao/shared/types/resume";
import { PDFDocument } from "pdf-lib";
import { renderResumeHeader, renderResumeSummary } from "./export-service-resume-header";
import { createResumeContext, resolveResumePdfTemplate } from "./export-service-resume-layout";
import {
  renderResumeEducation,
  renderResumeGamingExperience,
  renderResumeSkills,
} from "./export-service-resume-profile";
import { renderResumeExperience, renderResumeProjects } from "./export-service-resume-work";
const NUM_3 = 3;

export async function exportResumePdf(
  resume: ResumeData,
  templateName?: string,
): Promise<Uint8Array> {
  const template = resolveResumePdfTemplate(templateName, resume.template);
  const context = await createResumeContext(template);
  renderResumeHeader(context, resume);
  renderResumeSummary(context, resume);
  renderResumeExperience(context, resume);
  renderResumeEducation(context, resume);
  renderResumeSkills(context, resume);
  renderResumeProjects(context, resume);
  renderResumeGamingExperience(context, resume);
  return context.pdfDoc.save();
}

export async function optimizeResumePdfForOnePage(
  resume: ResumeData,
  templateName?: string,
): Promise<Uint8Array> {
  let pdfBytes = await exportResumePdf(resume, templateName);
  let pdfDoc = await PDFDocument.load(pdfBytes);
  if (pdfDoc.getPageCount() <= 1) return pdfBytes;

  const optimized: ResumeData = structuredClone(resume);
  const optimizedProjects = optimized.projects;
  if (
    Array.isArray(optimizedProjects) &&
    optimizedProjects.length > 0 &&
    pdfDoc.getPageCount() > 1
  ) {
    optimized.projects = optimizedProjects.slice(0, 2);
    pdfBytes = await exportResumePdf(optimized, templateName);
    pdfDoc = await PDFDocument.load(pdfBytes);
  }

  if (pdfDoc.getPageCount() > 1 && optimized.gamingExperience) {
    optimized.gamingExperience = undefined;
    pdfBytes = await exportResumePdf(optimized, templateName);
    pdfDoc = await PDFDocument.load(pdfBytes);
  }

  if (pdfDoc.getPageCount() > 1 && optimized.projects) {
    optimized.projects = undefined;
    pdfBytes = await exportResumePdf(optimized, templateName);
    pdfDoc = await PDFDocument.load(pdfBytes);
  }

  if (pdfDoc.getPageCount() > 1 && optimized.experience) {
    for (const experience of optimized.experience) {
      const achievements = experience.achievements;
      if (Array.isArray(achievements) && achievements.length > NUM_3) {
        experience.achievements = achievements.slice(0, NUM_3);
      }
    }
    pdfBytes = await exportResumePdf(optimized, templateName);
  }

  return pdfBytes;
}

import { API_ERROR_UNSUPPORTED_RESUME_TEMPLATE } from "@bao/shared/constants/api-errors";
import {
  A4_PAGE_HEIGHT,
  A4_PAGE_WIDTH,
  RESUME_BODY_LINE_GAP,
  RESUME_EXPORT_THEME_CONFIGS,
  RESUME_SECTION_HEADER_SPACING,
  RESUME_SECTION_SPACE,
} from "@bao/shared/constants/export-layout";
import { RESUME_TEMPLATE_DEFAULT, type ResumeTemplate } from "@bao/shared/constants/resume";
import { resolveResumeExportTemplate } from "@bao/shared/utils/export-contract";
import { PDFDocument, StandardFonts } from "pdf-lib";
import {
  addA4Page,
  type ResumeRenderContext,
  type ResumeTemplateDefinition,
  toPdfColor,
  type WrappedTextOptions,
} from "./export-service-contracts";
const RATIO_0_5 = 0.5;

export function resolveResumePdfTemplate(
  requestedTemplate: string | undefined,
  resumeTemplate: ResumeTemplate | undefined,
): ResumeTemplateDefinition {
  const resolvedTemplate = resolveResumeExportTemplate(requestedTemplate, resumeTemplate);
  const template =
    RESUME_EXPORT_THEME_CONFIGS[resolvedTemplate]?.pdf ??
    RESUME_EXPORT_THEME_CONFIGS[RESUME_TEMPLATE_DEFAULT]?.pdf;
  if (!template) {
    throw new Error(`${API_ERROR_UNSUPPORTED_RESUME_TEMPLATE}: ${resolvedTemplate}`);
  }
  return template;
}

export function applyResumeBackground(context: ResumeRenderContext, page = context.page): void {
  if (context.background.r >= RATIO_0_5) {
    return;
  }

  page.drawRectangle({
    x: 0,
    y: 0,
    width: A4_PAGE_WIDTH,
    height: A4_PAGE_HEIGHT,
    color: toPdfColor(context.background),
  });
}

export function ensureResumeSpace(context: ResumeRenderContext, requiredSpace: number): void {
  if (context.yPosition - requiredSpace >= context.margin) {
    return;
  }

  context.page = addA4Page(context.pdfDoc);
  applyResumeBackground(context, context.page);
  context.yPosition = context.height - context.margin;
}

export function drawResumeWrappedLine(
  context: ResumeRenderContext,
  options: WrappedTextOptions,
  line: string,
): void {
  const lineGap = options.lineGap ?? RESUME_BODY_LINE_GAP;
  ensureResumeSpace(context, options.size + lineGap);
  context.page.drawText(line, {
    x: options.x,
    y: context.yPosition,
    size: options.size,
    font: options.font,
    color: options.color,
  });
  context.yPosition -= options.size + lineGap;
}

export function drawResumeWrappedText(
  context: ResumeRenderContext,
  options: WrappedTextOptions,
): void {
  const words = options.text.split(" ");
  let line = "";

  for (const word of words) {
    const testLine = `${line}${word} `;
    const testWidth = options.font.widthOfTextAtSize(testLine, options.size);
    if (testWidth > options.maxWidth && line.length > 0) {
      drawResumeWrappedLine(context, options, line.trim());
      line = `${word} `;
      continue;
    }
    line = testLine;
  }

  if (line.trim().length > 0) {
    drawResumeWrappedLine(context, options, line.trim());
  }
}

export async function createResumeContext(
  template: ResumeTemplateDefinition,
): Promise<ResumeRenderContext> {
  const pdfDoc = await PDFDocument.create();
  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const boldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const page = addA4Page(pdfDoc);
  const { width, height } = page.getSize();

  const context: ResumeRenderContext = {
    pdfDoc,
    page,
    width,
    height,
    margin: template.spacing.margins.left,
    yPosition: height - template.spacing.margins.left,
    fonts: template.fonts,
    layout: template.layout,
    palette: {
      primary: toPdfColor(template.colors.primary),
      text: toPdfColor(template.colors.text),
      line: toPdfColor(template.colors.secondary),
      accent: toPdfColor(template.colors.accent),
    },
    background: template.colors.background,
    font,
    boldFont,
  };

  applyResumeBackground(context);
  return context;
}

export function renderResumeSectionHeader(context: ResumeRenderContext, title: string): void {
  ensureResumeSpace(context, RESUME_SECTION_SPACE);
  context.page.drawText(title, {
    x: context.margin,
    y: context.yPosition,
    size: context.fonts.header,
    font: context.boldFont,
    color: context.palette.primary,
  });
  context.yPosition -= RESUME_SECTION_HEADER_SPACING;
}

