const SUMMARY_HIGHLIGHT_SPLIT_PATTERN = /[;,]/u;

function extractSummaryValue(summary: string, label: string): string {
  const matcher = new RegExp(`^- ${label}:\\s*(.+)$`, "im");
  return summary.match(matcher)?.[1]?.trim() ?? "";
}

function extractSummaryHighlights(summary: string, label: string, maxItems = 3): string[] {
  return extractSummaryValue(summary, label)
    .split(SUMMARY_HIGHLIGHT_SPLIT_PATTERN)
    .map((value) => value.trim())
    .filter((value) => value.length > 0 && value !== DEFAULT_UNSPECIFIED_LABEL)
    .slice(0, maxItems);
}

function buildFallbackInterviewContext(
  studio: StudioContext,
  config: InterviewConfig,
  candidateContext: CandidateInterviewContext,
): FallbackInterviewContext {
  const targetJob = config.targetJob;
  const interviewEntity =
    config.interviewMode === "job" && targetJob?.company ? targetJob.company : studio.name;
  const roleTarget = targetJob?.title || config.roleType;
  const technicalHighlights =
    targetJob?.technologies?.filter((value) => value.trim().length > 0) ??
    extractSummaryHighlights(candidateContext.resumeSummary, "Technical skills");

  return {
    interviewEntity,
    roleTarget,
    primaryTechnology:
      technicalHighlights.find((value) => value.length > 0) ?? "your strongest technical stack",
    experienceHighlight:
      extractSummaryHighlights(candidateContext.resumeSummary, "Experience highlights", 1)[0] ??
      extractSummaryHighlights(candidateContext.profileSummary, "Current role", 1)[0] ??
      "recent game-industry delivery work",
    projectHighlight:
      extractSummaryHighlights(candidateContext.resumeSummary, "Project highlights", 1)[0] ??
      extractSummaryHighlights(candidateContext.portfolioSummary, "Featured work", 1)[0] ??
      "a player-facing system you shipped",
    focusArea:
      targetJob?.enrichment?.interviewFocusAreas?.[0] ??
      studio.enrichment?.interviewFocusAreas?.[0] ??
      "cross-functional delivery",
    hiringSignal:
      targetJob?.enrichment?.hiringSignals?.[0] ??
      studio.enrichment?.hiringSignals?.[0] ??
      "shipping velocity and collaborative execution",
    pitchAngle:
      targetJob?.enrichment?.candidatePitchAngles?.[0] ??
      studio.enrichment?.candidatePitchAngles?.[0] ??
      "measurable player impact and ownership",
  };
}

function buildFallbackQuestionText(
  seed: Omit<InterviewQuestion, "id">,
  context: FallbackInterviewContext,
): { question: string; followUps: string[]; tags: string[] } {
  switch (seed.type) {
    case "intro":
      return {
        question: `Your background highlights ${context.experienceHighlight}. How does that prepare you for the ${context.roleTarget} role at ${context.interviewEntity}?`,
        followUps: [
          `Which result from ${context.projectHighlight} is most relevant to ${context.interviewEntity}?`,
          "How did you validate the outcome with teammates, stakeholders, or players?",
          "What tradeoff from that work would you handle differently now?",
        ],
        tags: [...seed.tags, "candidate-context", "role-context"],
      };
    case "behavioral":
      return {
        question: `Tell me about a time you aligned design, QA, or production partners to deliver ${context.focusArea} work with a clear outcome.`,
        followUps: [
          "What disagreement or constraint made the collaboration difficult?",
          "How did you keep the team aligned when priorities shifted?",
          "What evidence told you the collaboration was successful?",
        ],
        tags: [...seed.tags, "candidate-context", "collaboration"],
      };
    case "studio-specific":
      return {
        question: `${context.interviewEntity} is signaling ${context.hiringSignal}. How would you ramp up in your first 30 days and show that ${context.pitchAngle}?`,
        followUps: [
          `Which stakeholder would you meet first to support ${context.focusArea}?`,
          "What deliverable would you aim to own by the end of your first sprint?",
          "How would you tailor your communication to this studio context?",
        ],
        tags: [...seed.tags, "studio-context", "scrape-enrichment"],
      };
    case "technical":
      return {
        question: `Walk me through a system from ${context.projectHighlight} where you used ${context.primaryTechnology} in a way that would transfer directly to the ${context.roleTarget} scope at ${context.interviewEntity}.`,
        followUps: [
          `What constraints shaped your use of ${context.primaryTechnology}?`,
          "What telemetry, QA checks, or player signals told you the solution was healthy?",
          "How would you scale that approach for a larger team or live-service environment?",
        ],
        tags: [...seed.tags, "candidate-context", "technical-context"],
      };
    case "closing":
      return {
        question: `What is the strongest evidence from your resume, cover letter, or portfolio that you are ready for ${context.roleTarget} at ${context.interviewEntity} right now?`,
        followUps: [
          "Which accomplishment best proves that claim?",
          "How does that evidence connect to this studio's priorities?",
          "What would you aim to deliver in your first 30 days?",
        ],
        tags: [...seed.tags, "candidate-context", "closing"],
      };
    default: {
      const _exhaustive: never = seed.type;
      return {
        question: `How would you contribute as ${context.roleTarget} at ${context.interviewEntity}?`,
        followUps: ["What evidence supports that?"],
        tags: [...seed.tags, "fallback", String(_exhaustive)],
      };
    }
  }
}

export function buildFallbackQuestions(
  config: InterviewConfig,
  studio: StudioContext,
  candidateContext: CandidateInterviewContext,
): InterviewQuestion[] {
  const filtered = FALLBACK_INTERVIEW_QUESTIONS.filter((question) => {
    if (question.type === "technical") {
      return Boolean(config.includeTechnical);
    }
    if (question.type === "behavioral") {
      return Boolean(config.includeBehavioral);
    }
    if (question.type === "studio-specific") {
      return Boolean(config.includeStudioSpecific);
    }
    return true;
  });

  const normalizedQuestionCount = Math.max(1, config.questionCount);
  const pool = filtered.length > 0 ? filtered : FALLBACK_INTERVIEW_QUESTIONS;
  const context = buildFallbackInterviewContext(studio, config, candidateContext);
  const questions: InterviewQuestion[] = [];

  while (questions.length < normalizedQuestionCount) {
    const seed = pool[questions.length % pool.length];
    const contextualized = buildFallbackQuestionText(seed, context);
    questions.push({
      ...seed,
      id: `fallback-${questions.length + 1}`,
      question: contextualized.question,
      followUps: contextualized.followUps,
      tags: contextualized.tags,
    });
  }

  return questions.slice(0, normalizedQuestionCount);
}

export function buildFallbackNaturalQuestion(
  session: { config: InterviewConfig; responses: InterviewResponse[] },
  studio: StudioContext,
  candidateContext: CandidateInterviewContext,
): InterviewQuestion | null {
  const nextFallback = buildFallbackQuestions(session.config, studio, candidateContext)[
    session.responses.length
  ];

  if (!nextFallback) {
    return null;
  }

  return {
    ...nextFallback,
    id: `natural-fallback-${session.responses.length + 1}`,
  };
}

import { COVER_LETTER_DEFAULT_SIGNATURE } from "@bao/shared/constants/cover-letter";
import {
  COVER_LETTER_LINE_HEIGHT,
  COVER_LETTER_MARGIN,
  COVER_LETTER_PARAGRAPH_GAP,
  COVER_LETTER_PARAGRAPH_SIZE,
} from "@bao/shared/constants/export-layout";
import {
  collectDefinedStringValues,
  formatExportDate,
  toCoverLetterParagraphs,
} from "@bao/shared/utils/export-contract";
import { PDFDocument, StandardFonts } from "pdf-lib";
import {
  addA4Page,
  COVER_LETTER_PDF_COLORS,
  type CoverLetterPayload,
  type CoverLetterRenderContext,
  type CoverLetterUserProfile,
} from "./export-service-contracts";
const NUM_15 = 15;
const NUM_18 = 18;
const NUM_25 = 25;
const NUM_28 = 28;
const NUM_35 = 35;

async function createCoverLetterContext(): Promise<CoverLetterRenderContext> {
  const pdfDoc = await PDFDocument.create();
  const font = await pdfDoc.embedFont(StandardFonts.TimesRoman);
  const boldFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
  const page = addA4Page(pdfDoc);
  const { width, height } = page.getSize();

  return {
    pdfDoc,
    page,
    width,
    height,
    margin: COVER_LETTER_MARGIN,
    yPosition: height - COVER_LETTER_MARGIN,
    font,
    boldFont,
  };
}

function drawCoverLetterDivider(context: CoverLetterRenderContext): void {
  context.page.drawLine({
    start: { x: context.margin, y: context.yPosition },
    end: { x: context.width - context.margin, y: context.yPosition },
    thickness: 1,
    color: COVER_LETTER_PDF_COLORS.line,
  });
  context.yPosition -= 24;
}

function ensureCoverLetterSpace(context: CoverLetterRenderContext, requiredSpace: number): void {
  if (context.yPosition - requiredSpace >= context.margin) {
    return;
  }

  context.page = addA4Page(context.pdfDoc);
  context.yPosition = context.height - context.margin;
}

function renderCoverLetterSender(
  context: CoverLetterRenderContext,
  userProfile: CoverLetterUserProfile,
): void {
  context.page.drawText(userProfile.name, {
    x: context.margin,
    y: context.yPosition,
    size: 24,
    font: context.boldFont,
    color: COVER_LETTER_PDF_COLORS.primary,
  });
  context.yPosition -= 24;

  const contactLine = collectDefinedStringValues([
    userProfile.email,
    userProfile.phone,
    userProfile.location,
  ]).join(" | ");
  if (!contactLine) {
    return;
  }

  context.page.drawText(contactLine, {
    x: context.margin,
    y: context.yPosition,
    size: 9,
    font: context.font,
    color: COVER_LETTER_PDF_COLORS.muted,
  });
  context.yPosition -= NUM_28;
}

function renderCoverLetterDate(context: CoverLetterRenderContext, date: Date): void {
  context.page.drawText(formatExportDate(date), {
    x: context.margin,
    y: context.yPosition,
    size: 10,
    font: context.font,
    color: COVER_LETTER_PDF_COLORS.muted,
  });
  context.yPosition -= 24;
}

function renderCoverLetterRecipient(
  context: CoverLetterRenderContext,
  coverLetter: CoverLetterPayload,
): void {
  context.page.drawText(coverLetter.company, {
    x: context.margin,
    y: context.yPosition,
    size: 11,
    font: context.boldFont,
    color: COVER_LETTER_PDF_COLORS.primary,
  });
  context.yPosition -= NUM_15;

  context.page.drawText(`RE: ${coverLetter.position}`, {
    x: context.margin,
    y: context.yPosition,
    size: 10,
    font: context.font,
    color: COVER_LETTER_PDF_COLORS.accent,
  });
  context.yPosition -= NUM_18;
  drawCoverLetterDivider(context);
}

function drawCoverLetterLine(context: CoverLetterRenderContext, line: string): void {
  ensureCoverLetterSpace(context, COVER_LETTER_LINE_HEIGHT);
  context.page.drawText(line, {
    x: context.margin,
    y: context.yPosition,
    size: COVER_LETTER_PARAGRAPH_SIZE,
    font: context.font,
    color: COVER_LETTER_PDF_COLORS.text,
  });
  context.yPosition -= COVER_LETTER_LINE_HEIGHT;
}

function drawCoverLetterParagraph(context: CoverLetterRenderContext, paragraph: string): void {
  const words = paragraph.split(" ");
  let line = "";

  for (const word of words) {
    const testLine = `${line}${word} `;
    const lineWidth = context.font.widthOfTextAtSize(testLine, COVER_LETTER_PARAGRAPH_SIZE);
    if (lineWidth > context.width - context.margin * 2 && line.length > 0) {
      drawCoverLetterLine(context, line.trim());
      line = `${word} `;
      continue;
    }
    line = testLine;
  }

  if (line.trim().length > 0) {
    drawCoverLetterLine(context, line.trim());
  }
  context.yPosition -= COVER_LETTER_PARAGRAPH_GAP;
}

function renderCoverLetterBody(context: CoverLetterRenderContext, content: unknown): void {
  for (const paragraph of toCoverLetterParagraphs(content)) {
    drawCoverLetterParagraph(context, paragraph);
  }
}

function renderCoverLetterClosing(context: CoverLetterRenderContext, signerName: string): void {
  context.yPosition -= 10;
  ensureCoverLetterSpace(context, NUM_35);

  context.page.drawText(COVER_LETTER_DEFAULT_SIGNATURE, {
    x: context.margin,
    y: context.yPosition,
    size: 11,
    font: context.font,
    color: COVER_LETTER_PDF_COLORS.muted,
  });
  context.yPosition -= NUM_25;

  context.page.drawText(signerName, {
    x: context.margin,
    y: context.yPosition,
    size: 11,
    font: context.boldFont,
    color: COVER_LETTER_PDF_COLORS.text,
  });
}

export async function exportCoverLetterPdf(
  coverLetter: CoverLetterPayload,
  userProfile: CoverLetterUserProfile,
): Promise<Uint8Array> {
  const context = await createCoverLetterContext();
  renderCoverLetterSender(context, userProfile);
  renderCoverLetterDate(context, new Date());
  renderCoverLetterRecipient(context, coverLetter);
  renderCoverLetterBody(context, coverLetter.content);
  renderCoverLetterClosing(context, userProfile.name);
  return context.pdfDoc.save();
}

