import { API_ERROR_APPLICATION_NOT_FOUND } from "@bao/shared/constants/api-errors";
import type { Job } from "@bao/shared/types/jobs";
import { desc, eq } from "drizzle-orm";
import { db } from "../../db/client";
import { applications, jobs } from "../../db/schema/jobs";
import { dbRowToJob } from "./job-aggregator-mappers";

export const applyToJob = async (jobId: string, notes?: string): Promise<string> => {
  const applicationId = crypto.randomUUID();
  const appliedDate = new Date().toISOString();

  await db.insert(applications).values({
    id: applicationId,
    jobId,
    status: "applied",
    appliedDate,
    notes: notes || "",
    timeline: [
      {
        id: crypto.randomUUID(),
        type: "applied",
        date: appliedDate,
        description: "Application submitted",
      },
    ],
  });

  return applicationId;
};

export const getApplications = async (): Promise<
  Array<typeof applications.$inferSelect & { job: Job }>
> => {
  const result = await db
    .select({
      application: applications,
      job: jobs,
    })
    .from(applications)
    .innerJoin(jobs, eq(applications.jobId, jobs.id))
    .orderBy(desc(applications.appliedDate));

  return result.map((row) => ({
    ...row.application,
    job: dbRowToJob(row.job),
  }));
};

export const updateApplicationStatus = async (
  applicationId: string,
  status: string,
  note?: string,
): Promise<void> => {
  const app = await db
    .select()
    .from(applications)
    .where(eq(applications.id, applicationId))
    .limit(1);

  if (app.length === 0) {
    throw new Error(API_ERROR_APPLICATION_NOT_FOUND);
  }

  const timeline = app[0].timeline || [];
  const normalizedStatus = status.trim() || "applied";
  timeline.push({
    id: crypto.randomUUID(),
    type: normalizedStatus,
    date: new Date().toISOString(),
    description: note || `Status changed to ${normalizedStatus}`,
  });

  await db
    .update(applications)
    .set({
      status,
      timeline,
      updatedAt: new Date().toISOString(),
    })
    .where(eq(applications.id, applicationId));
};

/**
 * Job deduplication service
 * Uses content-based hashing to identify duplicate job postings
 */

import { API_ERROR_CANNOT_MERGE_EMPTY_JOBS } from "@bao/shared/constants/api-errors";
import type { RawJob } from "./providers/provider-interface";

/**
 * Generate a content hash for a job posting
 * Uses title + company + location to create a unique identifier
 */
export function generateContentHash(
  job: RawJob | { title: string; company: string; location: string },
): string {
  // Normalize the content for consistent hashing
  const normalizedTitle = job.title.toLowerCase().trim().replace(/\s+/g, " ");
  const normalizedCompany = job.company.toLowerCase().trim().replace(/\s+/g, " ");
  const normalizedLocation = job.location.toLowerCase().trim().replace(/\s+/g, " ");

  const content = `${normalizedTitle}|${normalizedCompany}|${normalizedLocation}`;

  // Use Bun's native crypto hasher
  const hasher = new Bun.CryptoHasher("sha256");
  hasher.update(content);

  return hasher.digest("hex");
}

/**
 * Remove duplicate jobs based on content hash
 * Keeps the first occurrence of each unique job
 */
export function deduplicateJobs<T extends RawJob>(jobs: T[]): T[] {
  const seen = new Set<string>();
  const unique: T[] = [];

  for (const job of jobs) {
    const hash = generateContentHash(job);

    if (!seen.has(hash)) {
      seen.add(hash);
      unique.push(job);
    }
  }

  return unique;
}

/**
 * Find duplicate jobs across multiple sources
 * Returns a map of content hash to array of matching jobs
 */
export function findDuplicates(jobs: RawJob[]): Map<string, RawJob[]> {
  const hashMap = new Map<string, RawJob[]>();

  for (const job of jobs) {
    const hash = generateContentHash(job);
    const existing = hashMap.get(hash) || [];
    existing.push(job);
    hashMap.set(hash, existing);
  }

  const duplicates = new Map<string, RawJob[]>();
  for (const [hash, matches] of hashMap.entries()) {
    if (matches.length > 1) {
      duplicates.set(hash, matches);
    }
  }

  return duplicates;
}

function mergeJobValues(merged: RawJob, job: RawJob): void {
  if (!merged.description && job.description) {
    merged.description = job.description;
  }

  for (const [key, value] of Object.entries(job)) {
    if (value && !merged[key]) {
      merged[key] = value;
    }
  }
}

/**
 * Merge duplicate job postings by combining their metadata
 * Prefers non-empty values and combines arrays
 */
export function mergeJobs(jobs: RawJob[]): RawJob {
  if (jobs.length === 0) {
    throw new Error(API_ERROR_CANNOT_MERGE_EMPTY_JOBS);
  }

  if (jobs.length === 1) {
    return jobs[0];
  }

  const merged: RawJob = { ...jobs[0] };

  const sources = new Set<string>();
  const urls = new Set<string>();

  for (const job of jobs) {
    if (job.source) sources.add(job.source);
    if (job.url) urls.add(job.url);
    mergeJobValues(merged, job);
  }

  merged.sources = Array.from(sources);
  merged.alternativeUrls = Array.from(urls);

  return merged;
}

import { DEFAULT_JOB_TAXONOMY_SETTINGS } from "@bao/shared/constants/jobs-taxonomy";
import { jobTaxonomySettingsSchema } from "@bao/shared/schemas/jobs-taxonomy.schema";
import type {
  JobTaxonomyKeywordEntry,
  JobTaxonomySettings,
  StudioClassificationRule,
} from "@bao/shared/types/jobs-taxonomy";
import { asc } from "drizzle-orm";
import { db } from "../../db/client";
import { jobTaxonomyKeywords, studioClassificationRules } from "../../db/schema/job-taxonomy";

const mapKeywordRow = (row: typeof jobTaxonomyKeywords.$inferSelect): JobTaxonomyKeywordEntry => ({
  id: row.id,
  category: row.category,
  label: row.label,
  synonyms: Array.isArray(row.synonyms) ? row.synonyms : [],
  sortOrder: row.sortOrder,
  enabled: row.enabled,
});

const mapStudioRuleRow = (
  row: typeof studioClassificationRules.$inferSelect,
): StudioClassificationRule => ({
  id: row.id,
  studioType: row.studioType,
  keyword: row.keyword,
  sortOrder: row.sortOrder,
  enabled: row.enabled,
});

const insertKeywordRow = (
  entry: JobTaxonomyKeywordEntry,
): typeof jobTaxonomyKeywords.$inferInsert => ({
  id: entry.id,
  category: entry.category,
  label: entry.label,
  synonyms: entry.synonyms,
  sortOrder: entry.sortOrder,
  enabled: entry.enabled,
  updatedAt: new Date().toISOString(),
});

const insertStudioRuleRow = (
  entry: StudioClassificationRule,
): typeof studioClassificationRules.$inferInsert => ({
  id: entry.id,
  studioType: entry.studioType,
  keyword: entry.keyword,
  sortOrder: entry.sortOrder,
  enabled: entry.enabled,
  updatedAt: new Date().toISOString(),
});

const seedDefaults = async (): Promise<void> => {
  await db.transaction(async (tx) => {
    await tx
      .insert(jobTaxonomyKeywords)
      .values(DEFAULT_JOB_TAXONOMY_SETTINGS.keywords.map(insertKeywordRow));
    await tx
      .insert(studioClassificationRules)
      .values(DEFAULT_JOB_TAXONOMY_SETTINGS.studioRules.map(insertStudioRuleRow));
  });
};

const ensureJobTaxonomyRows = async (): Promise<void> => {
  const [keywordRows, studioRuleRows] = await Promise.all([
    db.select({ id: jobTaxonomyKeywords.id }).from(jobTaxonomyKeywords).limit(1),
    db.select({ id: studioClassificationRules.id }).from(studioClassificationRules).limit(1),
  ]);

  if (keywordRows.length === 0 && studioRuleRows.length === 0) {
    await seedDefaults();
  }
};

export const readJobTaxonomy = async (): Promise<JobTaxonomySettings> => {
  await ensureJobTaxonomyRows();

  const [keywordRows, studioRuleRows] = await Promise.all([
    db
      .select()
      .from(jobTaxonomyKeywords)
      .orderBy(asc(jobTaxonomyKeywords.category), asc(jobTaxonomyKeywords.sortOrder)),
    db
      .select()
      .from(studioClassificationRules)
      .orderBy(asc(studioClassificationRules.studioType), asc(studioClassificationRules.sortOrder)),
  ]);

  const parsed = jobTaxonomySettingsSchema.safeParse({
    keywords: keywordRows.map(mapKeywordRow),
    studioRules: studioRuleRows.map(mapStudioRuleRow),
  });

  return parsed.success ? parsed.data : DEFAULT_JOB_TAXONOMY_SETTINGS;
};

export const replaceJobTaxonomy = async (
  taxonomy: JobTaxonomySettings,
): Promise<JobTaxonomySettings> => {
  const parsed = jobTaxonomySettingsSchema.safeParse(taxonomy);
  const nextTaxonomy = parsed.success ? parsed.data : DEFAULT_JOB_TAXONOMY_SETTINGS;

  await db.transaction(async (tx) => {
    await tx.delete(jobTaxonomyKeywords);
    await tx.delete(studioClassificationRules);

    if (nextTaxonomy.keywords.length > 0) {
      await tx.insert(jobTaxonomyKeywords).values(nextTaxonomy.keywords.map(insertKeywordRow));
    }
    if (nextTaxonomy.studioRules.length > 0) {
      await tx
        .insert(studioClassificationRules)
        .values(nextTaxonomy.studioRules.map(insertStudioRuleRow));
    }
  });

  return nextTaxonomy;
};

import type { JobTaxonomySettings } from "@bao/shared/types/jobs-taxonomy";
