};

import type { Job, SalaryRange } from "@bao/shared/types/jobs";
import type { jobs } from "../../db/schema/jobs";
import { generateContentHash } from "./deduplication";
import {
  detectExperienceLevel,
  detectHybrid,
  detectJobType,
  detectRemote,
  detectStudioType,
  extractGenres,
  extractPlatforms,
  extractRequirements,
  extractTechnologies,
  generateTags,
  normalizeExperienceLevel,
  normalizeGameGenres,
  normalizeJobType,
  normalizePlatforms,
  normalizeStudioType,
} from "./job-aggregator-taxonomy";
import type { RawJob } from "./providers/provider-interface";

const normalizeSalary = (value: Record<string, unknown> | null): Job["salary"] | undefined => {
  if (!value) {
    return;
  }

  if (typeof value.label === "string" && value.label.trim().length > 0) {
    return value.label;
  }

  const min = typeof value.min === "number" ? value.min : undefined;
  const max = typeof value.max === "number" ? value.max : undefined;
  if (min !== undefined && max !== undefined) {
    const normalized: SalaryRange = {
      min,
      max,
      currency: typeof value.currency === "string" ? value.currency : undefined,
      frequency:
        value.frequency === "yearly" ||
        value.frequency === "monthly" ||
        value.frequency === "hourly"
          ? value.frequency
          : undefined,
    };
    return normalized;
  }
};

const applyOptionalRowFields = (job: Job, row: typeof jobs.$inferSelect): Job => ({
  ...job,
  hybrid: row.hybrid ?? undefined,
  requirements: Array.isArray(row.requirements) ? row.requirements : undefined,
  technologies: Array.isArray(row.technologies) ? row.technologies : undefined,
  experienceLevel: normalizeExperienceLevel(row.experienceLevel),
  url: row.url ?? undefined,
  source: row.source ?? undefined,
  contentHash: row.contentHash ?? undefined,
  tags: Array.isArray(row.tags) ? row.tags : undefined,
  companyLogo: row.companyLogo ?? undefined,
  applicationUrl: row.applicationUrl ?? undefined,
});

export const rawJobToInsert = async (raw: RawJob): Promise<typeof jobs.$inferInsert> => {
  const contentHash = generateContentHash(raw);
  const applyUrl = typeof raw.applyUrl === "string" && raw.applyUrl.trim() ? raw.applyUrl : null;
  const [remote, hybrid, requirements, technologies, studioType, gameGenres, platforms, tags] =
    await Promise.all([
      detectRemote(raw.location),
      detectHybrid(raw.location),
      extractRequirements(raw.description),
      extractTechnologies(raw.description),
      detectStudioType(raw.company),
      extractGenres(raw.description),
      extractPlatforms(raw.description),
      generateTags(raw),
    ]);

  return {
    id: crypto.randomUUID(),
    title: raw.title,
    company: raw.company,
    location: raw.location,
    remote,
    hybrid,
    description: raw.description || "",
    requirements,
    technologies,
    experienceLevel: detectExperienceLevel(raw.title),
    type: detectJobType(raw.title),
    postedDate: raw.postedDate || new Date().toISOString(),
    url: raw.url,
    source: raw.source || "unknown",
    contentHash,
    studioType,
    gameGenres,
    platforms,
    tags,
    applicationUrl: applyUrl || raw.url,
  };
};

export const dbRowToJob = (row: typeof jobs.$inferSelect): Job => {
  const baseJob: Job = {
    id: row.id,
    title: row.title,
    company: row.company,
    location: row.location,
    remote: row.remote ?? false,
    salary: normalizeSalary(row.salary),
    description: row.description ?? "",
    type: normalizeJobType(row.type),
    postedDate: row.postedDate || new Date().toISOString(),
    studioType: normalizeStudioType(row.studioType),
    gameGenres: normalizeGameGenres(row.gameGenres),
    platforms: normalizePlatforms(row.platforms),
  };

  return applyOptionalRowFields(baseJob, row);
};

import {
  API_ERROR_INVALID_AUTOMATION_CONFIG,
  API_ERROR_MISSING_JOB_PROVIDERS,
  API_ERROR_MISSING_SETTINGS_ROW,
} from "@bao/shared/constants/api-errors";
import {
  automationSettingsSchema,
  jobProviderSettingsSchema,
} from "@bao/shared/schemas/settings.schema";
import type { JobProviderSettings } from "@bao/shared/types/settings-contracts";
import { DEFAULT_SETTINGS_ID } from "@bao/shared/types/settings-defaults";
import { normalizeJobProviderSettings } from "@bao/shared/types/settings-normalization";
import { eq } from "drizzle-orm";
import { db } from "../../../db/client";
import { settings } from "../../../db/schema/settings";

/**
 * Loads persisted job-provider runtime settings from the settings table.
 */
export async function loadJobProviderSettings(): Promise<JobProviderSettings> {
  const rows = await db
    .select({ automationSettings: settings.automationSettings })
    .from(settings)
    .where(eq(settings.id, DEFAULT_SETTINGS_ID))
    .limit(1);

  if (rows.length === 0) {
    throw new Error(API_ERROR_MISSING_SETTINGS_ROW);
  }

  const automationParsed = automationSettingsSchema.safeParse(rows[0]?.automationSettings);
  if (!automationParsed.success) {
    throw new Error(API_ERROR_INVALID_AUTOMATION_CONFIG);
  }

  const jobProviderParsed = jobProviderSettingsSchema.safeParse(automationParsed.data.jobProviders);

  if (!jobProviderParsed.success) {
    throw new Error(API_ERROR_MISSING_JOB_PROVIDERS);
  }

  return normalizeJobProviderSettings(jobProviderParsed.data);
}

import type { GamingPortalConfig, GamingPortalId } from "@bao/shared/types/settings-contracts";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { safeParseJson } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { generateId } from "@bao/shared/utils/validation";
import { createServerLogger } from "../../../utils/logger";
import { type ScrapedJob, scraperService } from "../../scraper-service";
import type { JobFilters, JobProvider, RawJob } from "./provider-interface";
import { loadJobProviderSettings } from "./provider-settings";

interface HitmarkerJob extends Record<string, unknown> {
  id?: string;
  title?: string;
  company?: string | { name?: string };
  location?: string;
  description?: string;
  url?: string;
  slug?: string;
  created_at?: string;
}

type HitmarkerResponse = HitmarkerJob[] | { jobs?: HitmarkerJob[]; data?: HitmarkerJob[] };

type PortalScrapeMethod = (sourceUrl?: string) => Promise<ScrapedJob[]>;

const WHITESPACE_PATTERN = /\s+/g;
const NON_HASH_SAFE_PATTERN = /[^a-z0-9-_]/g;
const REMOTE_LOCATION_PATTERN = /remote/i;

const PORTAL_SCRAPE_METHOD_BY_ID: Record<GamingPortalId, PortalScrapeMethod> = {
  hitmarker: () => scraperService.scrapeHitmarkerJobsRaw(),
  grackle: () => scraperService.scrapeGrackleJobsRaw(),
  workwithindies: () => scraperService.scrapeWorkWithIndiesJobsRaw(),
  remotegamejobs: () => scraperService.scrapeRemoteGameJobsRaw(),
  gamesjobsdirect: () => scraperService.scrapeGamesJobsDirectRaw(),
  pocketgamer: () => scraperService.scrapePocketGamerJobsRaw(),
};
const gamingProviderLogger = createServerLogger("gaming-providers");

const logProviderFailure = (providerName: string, reason: string, details?: unknown): RawJob[] => {
  gamingProviderLogger.error("Job provider fetch failed", {
    providerName,
    reason,
    details,
  });
  return [];
};

const logProviderSkip = (providerName: string, reason: string, details?: unknown): RawJob[] => {
  gamingProviderLogger.info("Job provider fetch skipped", {
    providerName,
    reason,
    details,
  });
  return [];
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isHitmarkerJob = (value: unknown): value is HitmarkerJob => isRecord(value);

const isHitmarkerResponse = (value: unknown): value is HitmarkerResponse =>
  (Array.isArray(value) && value.every(isHitmarkerJob)) ||
  (isRecord(value) &&
    ((Array.isArray(value.jobs) && value.jobs.every(isHitmarkerJob)) ||
      (Array.isArray(value.data) && value.data.every(isHitmarkerJob))));

const resolveHitmarkerJobs = (payload: HitmarkerResponse): HitmarkerJob[] =>
  Array.isArray(payload) ? payload : (payload.jobs ?? payload.data ?? []);

const resolveCompanyName = (company: HitmarkerJob["company"], fallback: string): string => {
  if (typeof company === "string" && company.length > 0) {
    return company;
  }

  if (typeof company === "object" && company !== null && typeof company.name === "string") {
    return company.name;
  }

  return fallback;
};

const resolveHitmarkerContentHash = (job: HitmarkerJob): string => {
  const source = job.id ?? job.slug ?? job.url ?? job.title ?? generateId();
  const value = String(source)
    .trim()
    .toLowerCase()
    .replace(WHITESPACE_PATTERN, "-")
    .replace(NON_HASH_SAFE_PATTERN, "");

  return `hm-${value || generateId()}`;
};

const resolvePortalConfig = (
  portals: GamingPortalConfig[],
  portalId: GamingPortalId,
): GamingPortalConfig | null => portals.find((portal) => portal.id === portalId) ?? null;

const loadHitmarkerProviderSettings = async (providerName: string) => {
  const providerSettingsResult = await settle(loadJobProviderSettings());
  if (providerSettingsResult.status === "rejected") {
    return {
      ok: false as const,
      jobs: logProviderFailure(providerName, "settings_unavailable", {
        error: toErrorMessage(providerSettingsResult.reason),
      }),
    };
  }

  const providerSettings = providerSettingsResult.value;
  if (!providerSettings.hitmarkerEnabled) {
    return {
      ok: false as const,
      jobs: logProviderSkip(providerName, "provider_disabled"),
    };
  }

  return {
    ok: true as const,
    providerSettings,
  };
};

const fetchHitmarkerPayload = async (
  providerName: string,
  providerSettings: Awaited<ReturnType<typeof loadJobProviderSettings>>,
  filters?: JobFilters,
) => {
  const query = filters?.query || providerSettings.hitmarkerDefaultQuery;
  const requestUrl = new URL(providerSettings.hitmarkerApiBaseUrl);
  requestUrl.searchParams.set("search", query);
  requestUrl.searchParams.set("limit", String(providerSettings.gamingBoardResultLimit));
  const responseResult = await settle(
    fetch(requestUrl.toString(), {
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(providerSettings.providerTimeoutMs),
    }),
  );
  if (responseResult.status === "rejected") {
    return {
      ok: false as const,
      jobs: logProviderFailure(providerName, "request_failed", {
        error: toErrorMessage(responseResult.reason),
        requestUrl: requestUrl.toString(),
      }),
    };
  }
  const response = responseResult.value;
  if (!response.ok) {
    return {
      ok: false as const,
      jobs: logProviderFailure(providerName, "response_not_ok", {
        requestUrl: requestUrl.toString(),
        status: response.status,
      }),
    };
  }

  const rawText = await response.text();
  const parsed = safeParseJson(rawText);
  if (parsed === null) {
    return {
      ok: false as const,
      jobs: logProviderFailure(providerName, "invalid_json", {
        requestUrl: requestUrl.toString(),
      }),
    };
  }
  if (!isHitmarkerResponse(parsed)) {
    return {
      ok: false as const,
      jobs: logProviderFailure(providerName, "invalid_payload", {
        requestUrl: requestUrl.toString(),
      }),
    };
  }

  return {
    ok: true as const,
    jobs: resolveHitmarkerJobs(parsed),
    hitmarkerOrigin: new URL(providerSettings.hitmarkerApiBaseUrl).origin,
  };
};

const mapHitmarkerJobs = (
  jobs: HitmarkerJob[],
  providerSettings: Awaited<ReturnType<typeof loadJobProviderSettings>>,
  hitmarkerOrigin: string,
): RawJob[] =>
  jobs.slice(0, providerSettings.gamingBoardResultLimit).map((job) => {
    const location = job.location || providerSettings.hitmarkerDefaultLocation;

    return {
      id: generateId(),
      title: job.title || "",
      company: resolveCompanyName(job.company, providerSettings.unknownCompanyLabel),
      location,
      remote: REMOTE_LOCATION_PATTERN.test(location),
      description: job.description || "",
      url: job.url || `${hitmarkerOrigin}/jobs/${job.slug || job.id || generateId()}`,
      source: "hitmarker",
      postedDate: job.created_at || new Date().toISOString(),
      contentHash: resolveHitmarkerContentHash(job),
    };
  });

/**
 * Provider for Hitmarker gaming jobs.
 */
export class HitmarkerProvider implements JobProvider {
  name = "Hitmarker";
  type = "gaming-board";
  enabled = true;

  async fetchJobs(filters?: JobFilters): Promise<RawJob[]> {
    const providerSettingsResult = await loadHitmarkerProviderSettings(this.name);
    if (!providerSettingsResult.ok) {
      return providerSettingsResult.jobs;
    }
    const payloadResult = await fetchHitmarkerPayload(
      this.name,
      providerSettingsResult.providerSettings,
      filters,
    );
    if (!payloadResult.ok) {
      return payloadResult.jobs;
    }

    return mapHitmarkerJobs(
      payloadResult.jobs,
      providerSettingsResult.providerSettings,
      payloadResult.hitmarkerOrigin,
    );
  }
}

/**
 * Provider for RPA-backed gaming job portals.
 */
export class GamingPortalProvider implements JobProvider {
  name: string;
  type = "gaming-board";
  enabled = true;
  private readonly portalId: GamingPortalId;

  constructor(portalId: GamingPortalId) {
    this.portalId = portalId;
    this.name = portalId;
  }

  async fetchJobs(): Promise<RawJob[]> {
    const providerSettingsResult = await settle(loadJobProviderSettings());
    if (providerSettingsResult.status === "rejected") {
      return logProviderFailure(this.name, "settings_unavailable", {
        error: toErrorMessage(providerSettingsResult.reason),
      });
    }
    const providerSettings = providerSettingsResult.value;
    const portalConfig = resolvePortalConfig(providerSettings.gamingPortals, this.portalId);
    if (!portalConfig?.enabled) {
      return logProviderSkip(this.portalId, "portal_disabled", {
        portalId: this.portalId,
      });
    }

    this.name = portalConfig.name;

    const scrapeMethod = PORTAL_SCRAPE_METHOD_BY_ID[this.portalId];
    const scrapeResult = await settle(scrapeMethod(portalConfig.fallbackUrl));
    if (scrapeResult.status === "rejected") {
      return logProviderFailure(this.name, "scrape_failed", {
        error: toErrorMessage(scrapeResult.reason),
        portalId: this.portalId,
      });
    }
    const scraped = scrapeResult.value;
    return scraped.slice(0, providerSettings.gamingBoardResultLimit).map((job) => ({
      id: generateId(),
      title: job.title,
      company: job.company,
      location: job.location,
      remote: Boolean(job.remote),
      description: job.description || "",
      url: job.url || portalConfig.fallbackUrl,
      source: job.source || portalConfig.source,
      postedDate: job.postedDate || new Date().toISOString(),
      contentHash: job.contentHash,
    }));
  }
}

