const NUM_100 = 100;
/**
 * Greenhouse ATS provider.
 */

import { safeParseJson } from "@bao/shared/utils/json";
import { JOB_AGGREGATOR_USER_AGENT, type JobProvider, type RawJob } from "./provider-interface";
import { loadJobProviderSettings } from "./provider-settings";

interface GreenhouseJob {
  id: number;
  title: string;
  absolute_url: string;
  location?: {
    name?: string;
  };
  updated_at: string;
  metadata?: Array<{
    name: string;
    value: string | string[];
  }>;
  content?: string;
  departments?: Array<{
    name: string;
  }>;
}

interface GreenhouseResponse {
  jobs: GreenhouseJob[];
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isGreenhouseJob = (value: unknown): value is GreenhouseJob => {
  if (!isRecord(value)) {
    return false;
  }

  return (
    typeof value.id === "number" &&
    typeof value.title === "string" &&
    typeof value.absolute_url === "string" &&
    typeof value.updated_at === "string"
  );
};

const isGreenhouseResponse = (value: unknown): value is GreenhouseResponse =>
  isRecord(value) && Array.isArray(value.jobs) && value.jobs.every(isGreenhouseJob);

type GreenhouseFetchStatus =
  | {
      ok: true;
      jobs: GreenhouseJob[];
    }
  | {
      ok: false;
    };

type JobProviderSettings = Awaited<ReturnType<typeof loadJobProviderSettings>>;

type GreenhouseBoardContext = {
  board: string;
  company: string;
  providerSettings: JobProviderSettings;
  query?: string;
};

type GreenhouseBoardPageState = {
  page: number;
  accumulatedJobs: RawJob[];
};

/**
 * Provider for Greenhouse-hosted boards configured in settings.
 */
export class GreenhouseProvider implements JobProvider {
  name = "Greenhouse";

  async fetchJobs(filters?: { query?: string }): Promise<RawJob[]> {
    const query = filters?.query;
    const providerSettings = await loadJobProviderSettings();
    const activeBoards = providerSettings.greenhouseBoards.filter((board) => board.enabled);
    const allJobs: RawJob[] = [];

    await Promise.allSettled(
      activeBoards.map(async (board) => {
        const jobs = await this.fetchBoardJobs(board.board, board.company, providerSettings, query);
        allJobs.push(...jobs);
      }),
    );

    return allJobs;
  }

  private async fetchBoardJobs(
    board: string,
    company: string,
    providerSettings: JobProviderSettings,
    query?: string,
  ): Promise<RawJob[]> {
    return this.fetchBoardJobsPage(
      { board, company, providerSettings, query },
      { page: 1, accumulatedJobs: [] },
    );
  }

  private async fetchBoardJobsPage(
    context: GreenhouseBoardContext,
    state: GreenhouseBoardPageState,
  ): Promise<RawJob[]> {
    const { board, company, providerSettings, query } = context;
    const { page, accumulatedJobs } = state;

    if (page > providerSettings.greenhouseMaxPages) {
      return accumulatedJobs;
    }

    const fetchStatus = await this.fetchGreenhousePage(board, page, providerSettings);
    if (!fetchStatus.ok) {
      return accumulatedJobs;
    }
    if (fetchStatus.jobs.length === 0) {
      return accumulatedJobs;
    }

    const pageJobs = this.filterMappedJobs(fetchStatus.jobs, company, board, query);
    const nextJobs = [...accumulatedJobs, ...pageJobs];
    if (fetchStatus.jobs.length < NUM_100) {
      return nextJobs;
    }
    return this.fetchBoardJobsPage(context, { page: page + 1, accumulatedJobs: nextJobs });
  }

  private async fetchGreenhousePage(
    board: string,
    page: number,
    providerSettings: JobProviderSettings,
  ): Promise<GreenhouseFetchStatus> {
    const url = `${providerSettings.greenhouseApiBaseUrl}/${board}/jobs?content=true&page=${page}`;
    const response = await fetch(url, {
      headers: {
        Accept: "application/json",
        "User-Agent": JOB_AGGREGATOR_USER_AGENT,
      },
      signal: AbortSignal.timeout(providerSettings.providerTimeoutMs),
    });
    if (!response.ok) {
      return { ok: false };
    }
    const rawText = await response.text();
    const parsed = safeParseJson(rawText);
    if (parsed === null || !isGreenhouseResponse(parsed)) {
      return { ok: false };
    }
    return { ok: true, jobs: parsed.jobs };
  }

  private filterMappedJobs(
    jobs: GreenhouseJob[],
    company: string,
    board: string,
    query?: string,
  ): RawJob[] {
    const queryLower = query?.toLowerCase();
    return jobs
      .map((job) => this.mapJob(job, company, board))
      .filter((rawJob) => {
        if (!queryLower) {
          return true;
        }
        const searchText = `${rawJob.title} ${rawJob.description}`.toLowerCase();
        return searchText.includes(queryLower);
      });
  }

  private mapJob(job: GreenhouseJob, company: string, board: string): RawJob {
    const departments = job.departments?.map((department) => department.name).join(", ") || "";

    return {
      title: job.title,
      company,
      location: job.location?.name || "",
      description: job.content || "",
      url: job.absolute_url,
      postedDate: job.updated_at,
      source: "Greenhouse",
      board,
      departments,
      greenhouseId: String(job.id),
      metadata: job.metadata,
    };
  }
}

const NUM_100 = 100;
/**
 * Lever ATS provider.
 */

import { safeParseJson } from "@bao/shared/utils/json";
import { JOB_AGGREGATOR_USER_AGENT, type JobProvider, type RawJob } from "./provider-interface";
import { loadJobProviderSettings } from "./provider-settings";

interface LeverJob {
  id: string;
  text: string;
  categories: {
    commitment?: string;
    department?: string;
    team?: string;
    location?: string;
  };
  description: string;
  descriptionPlain: string;
  hostedUrl: string;
  applyUrl: string;
  createdAt: number;
  workplaceType?: string;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isLeverCategories = (value: unknown): value is LeverJob["categories"] =>
  isRecord(value) &&
  (value.commitment === undefined || typeof value.commitment === "string") &&
  (value.department === undefined || typeof value.department === "string") &&
  (value.team === undefined || typeof value.team === "string") &&
  (value.location === undefined || typeof value.location === "string");

const isLeverJob = (value: unknown): value is LeverJob => {
  if (!(isRecord(value) && isLeverCategories(value.categories))) {
    return false;
  }

  return (
    typeof value.id === "string" &&
    typeof value.text === "string" &&
    typeof value.description === "string" &&
    typeof value.descriptionPlain === "string" &&
    typeof value.hostedUrl === "string" &&
    typeof value.applyUrl === "string" &&
    typeof value.createdAt === "number" &&
    (value.workplaceType === undefined || typeof value.workplaceType === "string")
  );
};

const parseLeverJobs = (value: unknown): LeverJob[] => {
  if (!Array.isArray(value)) {
    return [];
  }

  const jobs: LeverJob[] = [];
  for (const item of value) {
    if (!isLeverJob(item)) {
      return [];
    }
    jobs.push(item);
  }
  return jobs;
};

type JobProviderSettings = Awaited<ReturnType<typeof loadJobProviderSettings>>;

type LeverCompanyContext = {
  companySlug: string;
  companyName: string;
  providerSettings: JobProviderSettings;
  query?: string;
};

type LeverCompanyPageState = {
  page: number;
  offset: number | undefined;
  accumulatedJobs: RawJob[];
};

/**
 * Provider for Lever-hosted companies configured in settings.
 */
export class LeverProvider implements JobProvider {
  name = "Lever";

  async fetchJobs(filters?: { query?: string }): Promise<RawJob[]> {
    const query = filters?.query;
    const providerSettings = await loadJobProviderSettings();
    const activeCompanies = providerSettings.leverCompanies.filter((company) => company.enabled);
    const allJobs: RawJob[] = [];

    await Promise.allSettled(
      activeCompanies.map(async (company) => {
        const jobs = await this.fetchCompanyJobs(
          company.slug,
          company.company,
          providerSettings,
          query,
        );
        allJobs.push(...jobs);
      }),
    );

    return allJobs;
  }

  private async fetchCompanyJobs(
    companySlug: string,
    companyName: string,
    providerSettings: JobProviderSettings,
    query?: string,
  ): Promise<RawJob[]> {
    return this.fetchCompanyJobsPage(
      { companySlug, companyName, providerSettings, query },
      {
        page: 0,
        offset: undefined,
        accumulatedJobs: [],
      },
    );
  }

  private async fetchCompanyJobsPage(
    context: LeverCompanyContext,
    state: LeverCompanyPageState,
  ): Promise<RawJob[]> {
    const { companySlug, companyName, providerSettings, query } = context;
    const { page, offset, accumulatedJobs } = state;

    if (page >= providerSettings.leverMaxPages) {
      return accumulatedJobs;
    }

    const data = await this.fetchLeverPage(companySlug, providerSettings, query, offset);
    if (!data || data.length === 0) {
      return accumulatedJobs;
    }

    const queryLower = query?.toLowerCase();
    const pageJobs = data
      .map((job) => this.mapJob(job, companySlug, companyName))
      .filter((rawJob) => {
        if (!queryLower) {
          return true;
        }
        const searchText = `${rawJob.title} ${rawJob.description}`.toLowerCase();
        return searchText.includes(queryLower);
      });
    const nextJobs = [...accumulatedJobs, ...pageJobs];
    if (data.length < NUM_100) {
      return nextJobs;
    }

    const nextOffset = (offset ?? 0) + data.length;
    return this.fetchCompanyJobsPage(context, {
      page: page + 1,
      offset: nextOffset,
      accumulatedJobs: nextJobs,
    });
  }

  private async fetchLeverPage(
    companySlug: string,
    providerSettings: JobProviderSettings,
    query: string | undefined,
    offset: number | undefined,
  ): Promise<LeverJob[] | null> {
    let requestUrl = `${providerSettings.leverApiBaseUrl}/${companySlug}?mode=json`;
    if (offset !== undefined) {
      requestUrl += `&offset=${offset}`;
    }
    if (query) {
      requestUrl += `&team=${encodeURIComponent(query)}`;
    }

    const response = await fetch(requestUrl, {
      headers: {
        Accept: "application/json",
        "User-Agent": JOB_AGGREGATOR_USER_AGENT,
      },
      signal: AbortSignal.timeout(providerSettings.providerTimeoutMs),
    });
    if (!response.ok) {
      return null;
    }

    const rawText = await response.text();
    const parsed = safeParseJson(rawText);
    if (parsed === null) {
      return [];
    }
    return parseLeverJobs(parsed);
  }

  private mapJob(job: LeverJob, companySlug: string, companyName: string): RawJob {
    const location = job.categories.location || "";

    return {
      title: job.text,
      company: companyName,
      location,
      description: job.descriptionPlain || job.description,
      url: job.hostedUrl,
      postedDate: new Date(job.createdAt).toISOString(),
      source: "Lever",
      companySlug,
      department: job.categories.department || "",
      team: job.categories.team || "",
      commitment: job.categories.commitment || "",
      workplaceType: job.workplaceType,
      leverId: job.id,
      applyUrl: job.applyUrl,
    };
  }
}

import type { CompanyBoardConfig, JobProviderSettings } from "@bao/shared/types/settings-contracts";
import { safeParseJson } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { generateId } from "@bao/shared/utils/validation";
import {
  type ATSResponse,
  isAtsResponse,
  resolveBoardUrl,
  resolveHashFragment,
  resolveJobs,
  resolveLocation,
  toISODate,
} from "./company-board-support";
import type { JobProvider, RawJob } from "./provider-interface";
import { loadJobProviderSettings } from "./provider-settings";

const REMOTE_PATTERN = /remote/i;

/**
 * Provider that normalizes a single ATS board payload into `RawJob[]`.
 */
export class CompanyBoardProvider implements JobProvider {
  name: string;
  type = "company-board";
  enabled = true;
  private readonly config: CompanyBoardConfig;

  constructor(config: CompanyBoardConfig) {
    this.config = config;
    this.name = config.name;
    this.enabled = config.enabled;
  }

  async fetchJobs(): Promise<RawJob[]> {
    const providerSettings = await loadJobProviderSettings();
    return this.fetchJobsWithSettings(providerSettings);
  }

  async fetchJobsWithSettings(providerSettings: JobProviderSettings): Promise<RawJob[]> {
    if (!this.config.enabled) {
      return [];
    }

    const url = resolveBoardUrl(this.config.type, this.config.token, providerSettings);
    const responseResult = await settle(
      fetch(url, {
        headers: { Accept: "application/json" },
        signal: AbortSignal.timeout(providerSettings.providerTimeoutMs),
      }),
    );
    if (responseResult.status === "rejected") {
      return [];
    }
    const response = responseResult.value;
    if (!response.ok) {
      return [];
    }

    const rawText = await response.text();
    const parsed = safeParseJson(rawText);
    if (parsed === null) {
      return [];
    }
    if (!isAtsResponse(parsed)) {
      return [];
    }
    return this.parseJobs(parsed, providerSettings);
  }

  private parseJobs(data: ATSResponse, providerSettings: JobProviderSettings): RawJob[] {
    switch (this.config.type) {
      case "greenhouse":
        return this.parseGreenhouseJobs(data, providerSettings);
      case "lever":
        return this.parseLeverJobs(data, providerSettings);
      case "smartrecruiters":
        return this.parseSmartRecruitersJobs(data, providerSettings);
      default:
        return this.parseGenericJobs(data, providerSettings);
    }
  }

  private parseGreenhouseJobs(data: ATSResponse, providerSettings: JobProviderSettings): RawJob[] {
    const jobs = resolveJobs(data, ["jobs"]);

    return jobs.slice(0, providerSettings.companyBoardResultLimit).map((job) => {
      const location =
        resolveLocation(job.location) ||
        job.offices?.[0]?.name ||
        providerSettings.unknownLocationLabel;

      return {
        id: generateId(),
        title: job.title || "",
        company: this.config.name,
        location,
        remote: REMOTE_PATTERN.test(location),
        description: job.content || "",
        url: job.absolute_url || "",
        source: `greenhouse:${this.config.token}`,
        postedDate: toISODate(job.updated_at || job.created_at),
        contentHash: `gh-${this.config.token}-${resolveHashFragment(job)}`,
      };
    });
  }

  private parseLeverJobs(data: ATSResponse, providerSettings: JobProviderSettings): RawJob[] {
    const jobs = resolveJobs(data, ["data", "jobs", "results"]);

    return jobs.slice(0, providerSettings.companyBoardResultLimit).map((job) => {
      const location =
        job.categories?.location ||
        resolveLocation(job.location) ||
        providerSettings.unknownLocationLabel;

      return {
        id: generateId(),
        title: job.text || "",
        company: this.config.name,
        location,
        remote: REMOTE_PATTERN.test(location),
        description: job.descriptionPlain || job.description || "",
        url: job.hostedUrl || job.url || "",
        source: `lever:${this.config.token}`,
        postedDate: toISODate(job.createdAt),
        contentHash: `lv-${this.config.token}-${resolveHashFragment(job)}`,
      };
    });
  }

  private parseSmartRecruitersJobs(
    data: ATSResponse,
    providerSettings: JobProviderSettings,
  ): RawJob[] {
    const jobs = resolveJobs(data, ["content", "postings"]);

    return jobs.slice(0, providerSettings.companyBoardResultLimit).map((job) => {
      const location = resolveLocation(job.location) || providerSettings.unknownLocationLabel;

      return {
        id: generateId(),
        title: job.name || job.title || "",
        company: this.config.name,
        location,
        remote: REMOTE_PATTERN.test(location),
        description: job.description || job.content || "",
        url: job.applyUrl || job.ref || job.url || "",
        source: `smartrecruiters:${this.config.token}`,
        postedDate: toISODate(job.releasedDate),
        contentHash: `sr-${this.config.token}-${resolveHashFragment(job)}`,
      };
    });
  }

  private parseGenericJobs(data: ATSResponse, providerSettings: JobProviderSettings): RawJob[] {
    const jobs = resolveJobs(data, ["jobs", "results", "data", "content", "postings"]);

    return jobs.slice(0, providerSettings.companyBoardResultLimit).map((job) => {
      const location = resolveLocation(job.location) || providerSettings.unknownLocationLabel;
      const remoteProbe =
        typeof job.location === "string" ? job.location : JSON.stringify(job.location ?? "");

      return {
        id: generateId(),
        title: job.title || job.name || job.text || "",
        company: this.config.name,
        location,
        remote: REMOTE_PATTERN.test(remoteProbe),
        description: job.description || job.content || "",
        url: job.url || job.absolute_url || job.hostedUrl || "",
        source: `${this.config.type}:${this.config.token}`,
        postedDate: toISODate(job.created_at || job.createdAt || job.releasedDate),
        contentHash: `${this.config.type.slice(0, 2)}-${this.config.token}-${resolveHashFragment(job)}`,
      };
    });
  }
}

/**
 * Provider that fetches all configured company-board ATS sources.
 */
export class CompanyBoardsProvider implements JobProvider {
  name = "Company Boards";
  type = "company-board";
  enabled = true;

  async fetchJobs(): Promise<RawJob[]> {
    const providerSettings = await loadJobProviderSettings();
    const boards = [...providerSettings.companyBoards]
      .filter((board) => board.enabled)
      .sort((left, right) => right.priority - left.priority);

    if (boards.length === 0) {
      return [];
    }

    const results = await Promise.allSettled(
      boards.map((board) =>
        new CompanyBoardProvider(board).fetchJobsWithSettings(providerSettings),
      ),
    );

    const jobs: RawJob[] = [];
    for (const result of results) {
      if (result.status === "fulfilled") {
        jobs.push(...result.value);
      }
    }

    return jobs;
  }
}

/**
 * Provider interface for job aggregation
 */
import { APP_BRAND } from "@bao/shared/constants/branding";

export const JOB_AGGREGATOR_VERSION = "1.0";
export const JOB_AGGREGATOR_USER_AGENT = `${APP_BRAND.name}-JobAggregator/${JOB_AGGREGATOR_VERSION}`;

export interface JobProviderConfig {
  name: string;
  baseUrl: string;
  enabled: boolean;
}

export interface Job {
