import type { SmartFieldAnalysisContext } from "./smart-field-mapper-contracts";
const NUM_3 = 3;

const FIELD_CONTEXT_ITEM_LIMIT = 6;
const FIELD_CONTEXT_TEXT_LIMIT = 280;
const FIELD_CONTEXT_SECTION_LIMIT = 4;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const getRecord = (value: unknown, key: string): Record<string, unknown> | null => {
  if (!isRecord(value)) {
    return null;
  }
  const entry = value[key];
  return isRecord(entry) ? entry : null;
};

const getTrimmedString = (value: unknown): string =>
  typeof value === "string" ? value.trim() : "";

const truncateText = (value: string): string =>
  value.length > FIELD_CONTEXT_TEXT_LIMIT
    ? `${value.slice(0, FIELD_CONTEXT_TEXT_LIMIT)}...`
    : value;

const uniqueNonEmptyStrings = (value: unknown): string[] => {
  if (!Array.isArray(value)) {
    return [];
  }

  return Array.from(
    new Set(
      value
        .filter((entry): entry is string => typeof entry === "string")
        .map((entry) => entry.trim())
        .filter((entry) => entry.length > 0),
    ),
  );
};

const getResumeHighlights = (resume: Record<string, unknown>): string[] => {
  const experience = Array.isArray(resume.experience) ? resume.experience : [];
  const highlights: string[] = [];

  for (const entry of experience) {
    if (!(isRecord(entry) && highlights.length < FIELD_CONTEXT_ITEM_LIMIT)) {
      continue;
    }

    const title = getTrimmedString(entry.title);
    const company = getTrimmedString(entry.company);
    const description = truncateText(getTrimmedString(entry.description));
    const achievements = uniqueNonEmptyStrings(entry.achievements).slice(0, 2);
    const parts = [title, company, description, ...achievements].filter((part) => part.length > 0);
    if (parts.length > 0) {
      highlights.push(parts.join(" | "));
    }
  }

  return highlights;
};

const getProjectHighlights = (resume: Record<string, unknown>): string[] => {
  const projects = Array.isArray(resume.projects) ? resume.projects : [];
  const highlights: string[] = [];

  for (const entry of projects) {
    if (!(isRecord(entry) && highlights.length < FIELD_CONTEXT_SECTION_LIMIT)) {
      continue;
    }

    const title = getTrimmedString(entry.title);
    const description = truncateText(getTrimmedString(entry.description));
    const technologies = uniqueNonEmptyStrings(entry.technologies).slice(0, NUM_3).join(", ");
    const parts = [title, description, technologies].filter((part) => part.length > 0);
    if (parts.length > 0) {
      highlights.push(parts.join(" | "));
    }
  }

  return highlights;
};

export const getCandidateContextSummary = (context: SmartFieldAnalysisContext): string => {
  const personalInfo = getRecord(context.resume, "personalInfo");
  const skills = getRecord(context.resume, "skills");
  const coverLetterContent = getRecord(context.coverLetter ?? null, "content");
  const coverLetterSections = [
    getTrimmedString(coverLetterContent?.opening),
    getTrimmedString(coverLetterContent?.body),
    getTrimmedString(coverLetterContent?.closing),
    getTrimmedString(coverLetterContent?.introduction),
    getTrimmedString(coverLetterContent?.main),
    getTrimmedString(coverLetterContent?.conclusion),
  ]
    .filter((entry) => entry.length > 0)
    .slice(0, FIELD_CONTEXT_SECTION_LIMIT)
    .map((entry) => truncateText(entry));

  const candidateProfile = {
    personalInfo: {
      name: getTrimmedString(personalInfo?.name),
      email: getTrimmedString(personalInfo?.email),
      phone: getTrimmedString(personalInfo?.phone),
      location: getTrimmedString(personalInfo?.location),
      website: getTrimmedString(personalInfo?.website),
      linkedIn: getTrimmedString(personalInfo?.linkedIn),
      github: getTrimmedString(personalInfo?.github),
      portfolio: getTrimmedString(personalInfo?.portfolio),
    },
    summary: truncateText(getTrimmedString(context.resume.summary)),
    experienceHighlights: getResumeHighlights(context.resume),
    projectHighlights: getProjectHighlights(context.resume),
    skills: {
      technical: uniqueNonEmptyStrings(skills?.technical).slice(0, FIELD_CONTEXT_ITEM_LIMIT),
      soft: uniqueNonEmptyStrings(skills?.soft).slice(0, FIELD_CONTEXT_ITEM_LIMIT),
      gaming: uniqueNonEmptyStrings(skills?.gaming).slice(0, FIELD_CONTEXT_ITEM_LIMIT),
    },
    coverLetterHighlights: coverLetterSections,
    existingAnswers: context.existingAnswers,
  };

  return JSON.stringify(candidateProfile, null, 2);
};

import { isAbsolute, resolve, sep } from "node:path";
import {
  automationScriptEntryById,
  automationScriptIdSchema,
} from "@bao/shared/schemas/automation-scripts.schema";
import { RPA_PROTOCOL_VERSION } from "@bao/shared/schemas/rpa-protocol.schema";
import { config } from "../../config/env";
import {
  buildAutomationProcessEnv,
  readAutomationScriptRunnerConfig,
  SCRAPER_DIR,
} from "../../config/paths";
import type {
  AutomationScriptExecutionResult,
  RunAutomationScriptOptions,
} from "./rpa-runner-contracts";

const DEFAULT_KILL_SIGNAL = "SIGKILL";
const NDJSON_LINE_SPLIT_PATTERN = /\r?\n/gu;

type ExecutionAbortState = {
  timedOut: boolean;
  aborted: boolean;
};

const toSafeTimeoutMs = (value: number | undefined, defaultTimeoutMs: number): number => {
  if (typeof value === "number" && Number.isFinite(value) && value > 0) {
    return Math.trunc(value);
  }
  return defaultTimeoutMs;
};

const pushBoundedLine = (target: string[], value: string, limit: number): void => {
  const normalized = value.trim();
  if (normalized.length === 0) {
    return;
  }
  target.push(normalized);
  if (target.length > limit) {
    target.shift();
  }
};

const emitNonEmptyLines = (lines: string[], onLine: (line: string) => void): void => {
  for (const line of lines) {
    const normalized = line.trim();
    if (normalized.length > 0) {
      onLine(normalized);
    }
  }
};

const appendDecodedChunk = (
  decoder: TextDecoder,
  pending: string,
  value: Uint8Array,
  onLine: (line: string) => void,
): string => {
  const decoded = decoder.decode(value, { stream: true });
  const lines = `${pending}${decoded}`.split(NDJSON_LINE_SPLIT_PATTERN);
  const nextPending = lines.pop() ?? "";
  emitNonEmptyLines(lines, onLine);
  return nextPending;
};

const readNdjsonLines = async (
  stream: ReadableStream<Uint8Array>,
  onLine: (line: string) => void,
): Promise<void> => {
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let pending = "";

  const flushPending = (): void => {
    const trailing = `${pending}${decoder.decode()}`.trim();
    if (trailing.length > 0) {
      onLine(trailing);
    }
    pending = "";
  };

  const readLoop = (): Promise<void> =>
    reader.read().then(
      ({ done, value }) => {
        if (done) {
          flushPending();
          return Promise.resolve();
        }

        if (value && value.length > 0) {
          pending = appendDecodedChunk(decoder, pending, value, onLine);
        }

        return readLoop();
      },
      () => Promise.resolve(),
    );

  return readLoop();
};

const createExecutionAbortState = (): ExecutionAbortState => ({
  timedOut: false,
  aborted: false,
});

const createProcessSignal = (
  timeoutSignal: AbortSignal,
  externalSignal: AbortSignal | undefined,
  state: ExecutionAbortState,
): AbortSignal => {
  timeoutSignal.addEventListener(
    "abort",
    () => {
      state.timedOut = true;
    },
    { once: true },
  );

  if (!externalSignal) {
    return timeoutSignal;
  }
  externalSignal.addEventListener(
    "abort",
    () => {
      state.aborted = true;
    },
    { once: true },
  );
  return AbortSignal.any([externalSignal, timeoutSignal]);
};

const isPathWithinScraperDir = (resolvedPath: string): boolean => {
  const normalizedScraperDir = resolve(SCRAPER_DIR);
  const normalizedPath = resolve(resolvedPath);
  return (
    normalizedPath === normalizedScraperDir ||
    normalizedPath.startsWith(`${normalizedScraperDir}${sep}`)
  );
};

const resolveAutomationScriptPath = (options: RunAutomationScriptOptions): string => {
  const scriptPath = options.scriptPath?.trim();
  if (scriptPath && scriptPath.length > 0) {
    const resolvedPath = isAbsolute(scriptPath) ? scriptPath : resolve(SCRAPER_DIR, scriptPath);
    if (!isPathWithinScraperDir(resolvedPath)) {
      return resolve(SCRAPER_DIR, "__missing-script__.ts");
    }
    return resolvedPath;
  }

  const parsedScriptId = automationScriptIdSchema.safeParse(options.scriptId);
  if (!parsedScriptId.success) {
    return resolve(SCRAPER_DIR, "__missing-script__.ts");
  }

  return resolve(SCRAPER_DIR, automationScriptEntryById[parsedScriptId.data]);
};

const resolveAutomationCommand = (scriptPath: string): string[] => {
  const { executablePath, entrypointPath } = readAutomationScriptRunnerConfig();
  if (executablePath) {
    return entrypointPath
      ? [executablePath, entrypointPath, SCRAPER_DIR, scriptPath]
      : [executablePath, SCRAPER_DIR, scriptPath];
  }

  return [process.execPath, scriptPath];
};

const spawnAutomationProcess = (
  scriptPath: string,
  signal: AbortSignal,
  killSignal: number | string | undefined,
): ReturnType<typeof Bun.spawn> =>
  Bun.spawn(resolveAutomationCommand(scriptPath), {
    cwd: SCRAPER_DIR,
    stdin: "pipe",
    stdout: "pipe",
    stderr: "pipe",
    env: buildAutomationProcessEnv(),
    signal,
    killSignal: killSignal ?? DEFAULT_KILL_SIGNAL,
  });

type AutomationSpawnStdin = ReturnType<typeof Bun.spawn>["stdin"];

const writeProcessPayload = async (
  stream: AutomationSpawnStdin,
  payload: string,
): Promise<void> => {
  if (typeof stream !== "object" || stream === null) {
    return;
  }
  if (!("write" in stream && "end" in stream)) {
    return;
  }
  if (typeof stream.write !== "function" || typeof stream.end !== "function") {
    return;
  }
  await stream.write(payload);
  await stream.end();
};

const isReadableBinaryStream = (
  stream: number | ReadableStream<Uint8Array> | undefined,
): stream is ReadableStream<Uint8Array> => stream instanceof ReadableStream;

const createClosedBinaryStream = (): ReadableStream<Uint8Array> =>
  new ReadableStream<Uint8Array>({
    start(controller) {
      controller.close();
    },
  });

const resolveReadableBinaryStream = (
  stream: number | ReadableStream<Uint8Array> | undefined,
): ReadableStream<Uint8Array> =>
  isReadableBinaryStream(stream) ? stream : createClosedBinaryStream();

const buildScriptPayload = (options: RunAutomationScriptOptions): string =>
  JSON.stringify({
    ...options.scriptInput,
    runId: options.runId,
    outputDir: options.outputDir ?? null,
    protocolVersion: RPA_PROTOCOL_VERSION,
  });

/**
 * Executes a Bun-based automation script with bounded IO capture and cancellation.
 */
export async function runAutomationScript(
  options: RunAutomationScriptOptions,
): Promise<AutomationScriptExecutionResult> {
  const timeoutMs = toSafeTimeoutMs(options.timeoutMs, config.automationScriptTimeoutMs);
  const stdoutLimit = options.stdoutLineLimit ?? config.automationStdioBufferLimit;
  const stderrLimit = options.stderrLineLimit ?? config.automationStdioBufferLimit;
  const scriptPath = resolveAutomationScriptPath(options);
  const startedAt = Date.now();
  const stdoutLines: string[] = [];
  const stderrLines: string[] = [];
  const abortState = createExecutionAbortState();

  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const signal = createProcessSignal(timeoutSignal, options.signal, abortState);
  const proc = spawnAutomationProcess(scriptPath, signal, options.killSignal);
  await writeProcessPayload(proc.stdin, buildScriptPayload(options));

  const stdoutTask = readNdjsonLines(resolveReadableBinaryStream(proc.stdout), (line) => {
    pushBoundedLine(stdoutLines, line, stdoutLimit);
    options.onStdoutLine?.(line);
  });
  const stderrTask = readNdjsonLines(resolveReadableBinaryStream(proc.stderr), (line) => {
    pushBoundedLine(stderrLines, line, stderrLimit);
    options.onStderrLine?.(line);
  });

  const [, , exitCode] = await Promise.all([stdoutTask, stderrTask, proc.exited]);
  const executionMs = Date.now() - startedAt;

  return {
    exitCode,
    timedOut: abortState.timedOut,
    aborted: abortState.aborted,
    executionMs,
    stdoutLines,
    stderrLines,
  };
}

import { createServerLogger } from "../../utils/logger";
import type { AutofillAnalysisOptions } from "./automation-service-contracts";
import { tryLoadAIService } from "./automation-settings-support";
import {
  type SmartFieldAnalysisContext,
  type SmartFieldAnalysisResult,
  smartFieldMapper,
} from "./smart-field-mapper";

const automationPreparationLogger = createServerLogger("automation-job-apply-preparation");

export const SMART_FIELD_CORE_KEYS = [
  "fullName",
  "email",
  "phone",
  "resume",
  "coverLetter",
  "submit",
] as const;

export const normalizeGeneratedFieldAnswers = (
  fieldAnswers: Record<string, string>,
): Record<string, string> => {
  const reservedFieldKeys = new Set<string>(SMART_FIELD_CORE_KEYS);
  const normalizedAnswers: Record<string, string> = {};

  for (const [key, value] of Object.entries(fieldAnswers)) {
    const normalizedKey = key.trim();
    const normalizedValue = value.trim();
    if (
      normalizedKey.length === 0 ||
      normalizedValue.length === 0 ||
      reservedFieldKeys.has(normalizedKey)
    ) {
      continue;
    }

    normalizedAnswers[normalizedKey] = normalizedValue;
  }

  return normalizedAnswers;
};

const createEmptyAutofillAnalysis = (): SmartFieldAnalysisResult => ({
  selectorMap: {},
  fieldAnswers: {},
});

const buildSmartFieldAnalysisContext = (
  options: Pick<AutofillAnalysisOptions, "resume" | "coverLetter" | "existingAnswers">,
): SmartFieldAnalysisContext => ({
  resume: Object.fromEntries(Object.entries(options.resume)),
  coverLetter: options.coverLetter ? { content: options.coverLetter.content || {} } : null,
  existingAnswers: options.existingAnswers,
});

export const resolveAutofillAnalysis = async (
  options: AutofillAnalysisOptions,
): Promise<SmartFieldAnalysisResult> => {
  if (!options.automationSettings.enableSmartSelectors) {
    automationPreparationLogger.debug("Smart field mapping skipped: enableSmartSelectors is off");
    return createEmptyAutofillAnalysis();
  }

  const aiService = await tryLoadAIService();
  if (!aiService) {
    automationPreparationLogger.debug("Smart field mapping skipped: AI service unavailable");
    return createEmptyAutofillAnalysis();
  }

  const result = await smartFieldMapper.analyze(
    options.jobUrl,
    [...SMART_FIELD_CORE_KEYS],
    buildSmartFieldAnalysisContext(options),
    aiService,
  );
  const isEmpty =
    Object.keys(result.selectorMap).length === 0 && Object.keys(result.fieldAnswers).length === 0;
  if (isEmpty) {
    automationPreparationLogger.debug("Smart field mapping returned empty result", {
      jobUrl: options.jobUrl,
    });
  }
  return result;
};

