import type {
  EmailDeliveryResult,
  EmailGenerationResult,
  EmailResponseRuntime,
} from "./automation-email-response-contracts";

export const failEmailResponseRun = async (
  runId: string,
  error: unknown,
  runtime: Pick<EmailResponseRuntime, "broadcastProgressEvent" | "createProgressEvent">,
  partialResult?: EmailGenerationResult,
): Promise<never> => {
  const message = toErrorMessage(
    error,
    partialResult ? API_ERROR_EMAIL_DELIVERY_FAILED : API_ERROR_GENERATE_EMAIL_RESPONSE,
  );
  const completedAt = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      status: "error",
      output: {
        success: false,
        error: message,
        ...(partialResult
          ? {
              reply: partialResult.reply,
              provider: partialResult.provider,
              model: partialResult.model,
              delivered: false,
            }
          : {}),
      },
      error: message,
      progress: AUTOMATION_FINISHED_PROGRESS,
      currentStep: partialResult ? 2 : 1,
      totalSteps: partialResult ? 2 : 1,
      completedAt,
      updatedAt: completedAt,
    })
    .where(eq(automationRuns.id, runId));
  runtime.broadcastProgressEvent(
    runtime.createProgressEvent({
      runId,
      action: "email_response",
      status: "error",
      message,
      step: partialResult ? 2 : 1,
      totalSteps: partialResult ? 2 : 1,
    }),
  );
  throw error instanceof Error ? error : new Error(message);
};

export const markEmailResponseDraftGenerated = async (
  runId: string,
  result: EmailGenerationResult,
  runtime: Pick<EmailResponseRuntime, "broadcastProgressEvent" | "createProgressEvent">,
  recipientEmail?: string,
): Promise<void> => {
  const updatedAt = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      output: {
        success: true,
        reply: result.reply,
        provider: result.provider,
        model: result.model,
        delivered: false,
        ...(recipientEmail ? { recipientEmail } : {}),
      },
      progress: Math.round(AUTOMATION_FINISHED_PROGRESS / 2),
      currentStep: 1,
      totalSteps: 2,
      updatedAt,
    })
    .where(eq(automationRuns.id, runId));
  runtime.broadcastProgressEvent(
    runtime.createProgressEvent({
      runId,
      action: "email_response",
      status: "running",
      message: API_MESSAGE_EMAIL_RESPONSE_GENERATED,
      step: 1,
      totalSteps: 2,
    }),
  );
};

export const completeEmailResponseRun = async (
  runId: string,
  result: {
    reply: string;
    provider: string;
    model: string;
    delivery: EmailDeliveryResult;
  },
  runtime: Pick<EmailResponseRuntime, "broadcastProgressEvent" | "createProgressEvent">,
): Promise<void> => {
  const completedAt = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      status: "success",
      output: {
        success: true,
        reply: result.reply,
        provider: result.provider,
        model: result.model,
        delivered: result.delivery.delivered,
        ...(result.delivery.recipientEmail
          ? { recipientEmail: result.delivery.recipientEmail }
          : {}),
        ...(result.delivery.deliveredAt ? { deliveredAt: result.delivery.deliveredAt } : {}),
        ...(result.delivery.messageId ? { messageId: result.delivery.messageId } : {}),
      },
      error: null,
      progress: AUTOMATION_FINISHED_PROGRESS,
      currentStep: result.delivery.delivered ? 2 : 1,
      totalSteps: result.delivery.delivered ? 2 : 1,
      completedAt,
      updatedAt: completedAt,
    })
    .where(eq(automationRuns.id, runId));
  runtime.broadcastProgressEvent(
    runtime.createProgressEvent({
      runId,
      action: "email_response",
      status: "success",
      message: result.delivery.delivered
        ? API_MESSAGE_EMAIL_RESPONSE_DELIVERED
        : API_MESSAGE_EMAIL_RESPONSE_GENERATED,
      step: result.delivery.delivered ? 2 : 1,
      totalSteps: result.delivery.delivered ? 2 : 1,
    }),
  );
};

import { join } from "node:path";
import type { ResumeData } from "@bao/shared/types/resume";
import { settle } from "@bao/shared/utils/promise";
import { exportService } from "../export-service";

const collectResumeHeaderLines = (resume: ResumeData): string[] => {
  const lines: string[] = [];
  const personalInfo = resume.personalInfo;

  if (resume.name) {
    lines.push(resume.name);
  }
  if (personalInfo?.name && personalInfo.name !== resume.name) {
    lines.push(personalInfo.name);
  }

  const contactLines = [
    personalInfo?.email,
    personalInfo?.phone,
    personalInfo?.location,
    personalInfo?.website,
    personalInfo?.linkedIn,
    personalInfo?.github,
    personalInfo?.portfolio,
  ].filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0);
  if (contactLines.length > 0) {
    lines.push(contactLines.join(" | "));
  }

  return lines;
};

const appendSection = (lines: string[], title: string, entries: string[]): void => {
  if (entries.length === 0) {
    return;
  }

  lines.push("", title, ...entries);
};

const collectResumeExperienceLines = (resume: ResumeData): string[] => {
  const lines: string[] = [];

  for (const experience of resume.experience ?? []) {
    const headerParts = [experience.title, experience.company].filter(
      (entry): entry is string => typeof entry === "string" && entry.trim().length > 0,
    );
    if (headerParts.length > 0) {
      lines.push(headerParts.join(" - "));
    }
    if (experience.description?.trim()) {
      lines.push(experience.description.trim());
    }
    for (const achievement of experience.achievements ?? []) {
      if (achievement.trim().length > 0) {
        lines.push(`- ${achievement.trim()}`);
      }
    }
  }

  return lines;
};

const collectResumeEducationLines = (resume: ResumeData): string[] => {
  const lines: string[] = [];

  for (const education of resume.education ?? []) {
    const headerParts = [education.degree, education.field, education.school].filter(
      (entry): entry is string => typeof entry === "string" && entry.trim().length > 0,
    );
    if (headerParts.length > 0) {
      lines.push(headerParts.join(" - "));
    }
  }

  return lines;
};

const collectResumeSkillSections = (
  resume: ResumeData,
): Array<{ title: string; lines: string[] }> => {
  const skillSections = [
    ["Technical Skills", resume.skills?.technical],
    ["Soft Skills", resume.skills?.soft],
    ["Gaming Skills", resume.skills?.gaming],
  ] as const;

  return skillSections.reduce<Array<{ title: string; lines: string[] }>>(
    (sections, [title, values]) => {
      if (Array.isArray(values) && values.length > 0) {
        sections.push({ title, lines: [values.join(", ")] });
      }
      return sections;
    },
    [],
  );
};

const serializeResumeUploadFallback = (resume: ResumeData): string => {
  const lines = collectResumeHeaderLines(resume);
  appendSection(lines, "Summary", resume.summary?.trim() ? [resume.summary.trim()] : []);
  appendSection(lines, "Experience", collectResumeExperienceLines(resume));
  appendSection(lines, "Education", collectResumeEducationLines(resume));
  for (const section of collectResumeSkillSections(resume)) {
    appendSection(lines, section.title, section.lines);
  }
  return lines.join("\n").trim();
};

export const createResumeUploadArtifact = async (
  runArtifactDir: string,
  resume: ResumeData,
): Promise<string | undefined> => {
  const pdfResult = await settle(exportService.exportResumePDF(resume, resume.template));
  if (pdfResult.status === "fulfilled") {
    const pdfPath = join(runArtifactDir, "resume.pdf");
    const writePdfResult = await settle(Bun.write(pdfPath, pdfResult.value));
    if (writePdfResult.status === "fulfilled") {
      return pdfPath;
    }
  }

  const fallbackResumePath = join(runArtifactDir, "resume.txt");
  const fallbackResume = serializeResumeUploadFallback(resume);
  const writeFallbackResult = await settle(Bun.write(fallbackResumePath, fallbackResume));
  if (writeFallbackResult.status === "fulfilled") {
    return fallbackResumePath;
  }
};

import {
  API_ERROR_CUSTOM_ANSWERS_KEY_EXCEEDS,
  API_ERROR_CUSTOM_ANSWERS_KEYS,
  API_ERROR_CUSTOM_ANSWERS_MAX_COUNT,
  API_ERROR_CUSTOM_ANSWERS_OBJECT,
  API_ERROR_CUSTOM_ANSWERS_VALUE_EXCEEDS,
  API_ERROR_CUSTOM_ANSWERS_VALUE_MUST_BE_STRING,
  API_ERROR_JOB_URL_ABSOLUTE,
  API_ERROR_JOB_URL_DISALLOWED_HOST,
  API_ERROR_JOB_URL_EXCEEDS_LENGTH,
  API_ERROR_JOB_URL_HTTP_ONLY,
  API_ERROR_JOB_URL_NO_CREDENTIALS,
  API_ERROR_JOB_URL_REQUIRED,
} from "@bao/shared/constants/api-errors";
import {
  AUTOMATION_MAX_CUSTOM_ANSWER_COUNT,
  AUTOMATION_MAX_CUSTOM_ANSWER_KEY_LENGTH,
  AUTOMATION_MAX_CUSTOM_ANSWER_VALUE_LENGTH,
  AUTOMATION_MAX_JOB_URL_LENGTH,
} from "@bao/shared/constants/automation-limits";
import { DECIMAL_RADIX } from "@bao/shared/constants/client-config";
import { DEFAULT_HOST, LOOPBACK_HOST_IPV4 } from "@bao/shared/constants/runtime";
import { config } from "../../config/env";
const NUM_127 = 127;
const NUM_168 = 168;
const NUM_169 = 169;
const NUM_192 = 192;
const NUM_254 = 254;
const NUM_255 = 255;
const NUM_4 = 4;

/** Re-export shared limits for consumers that import from this module. */
export const MAX_JOB_URL_LENGTH = AUTOMATION_MAX_JOB_URL_LENGTH;
export const MAX_CUSTOM_ANSWER_KEY_LENGTH = AUTOMATION_MAX_CUSTOM_ANSWER_KEY_LENGTH;
export const MAX_CUSTOM_ANSWER_VALUE_LENGTH = AUTOMATION_MAX_CUSTOM_ANSWER_VALUE_LENGTH;
export const MAX_CUSTOM_ANSWER_COUNT = AUTOMATION_MAX_CUSTOM_ANSWER_COUNT;

const DISALLOWED_IPV4_PREFIXES = [
  [NUM_127, 0],
  [10, 0],
  [NUM_169, NUM_254],
  [NUM_192, NUM_168],
];

const IP_SEGMENT_REGEX = /^\d+$/;
const IPV6_SEGMENT_REGEX = /^[0-9a-f:.]+$/i;

const DISALLOWED_HOST_PATTERNS = [
  /^localhost$/i,
  /^localhost\.localdomain$/i,
  /^127\./,
  /^10\./,
  /^172\.(1[6-9]|2\d|3[01])\./,
  /^192\.168\./,
  /^169\.254\./,
  /^::1$/i,
  /^fc[0-9a-f]+/i,
  /^fd[0-9a-f]+/i,
  /^fe80/i,
  /\.localhost$/i,
  /\.internal$/i,
];

const DISALLOWED_IPV6_PREFIX_PATTERN = /^(fc|fd|fe80)/i;

/**
 * Bypass SSRF guards when the process explicitly opts into private hosts.
 * Used by local fixture / integration runs; default remains deny.
 */
const allowAutomationPrivateHostsOptIn = (): boolean => config.allowAutomationPrivateHosts;

/**
 * Validate and normalize an automation URL while blocking unsafe host targets.
 */
export function sanitizeAndValidateJobUrl(rawJobUrl: string): string {
  const jobUrl = rawJobUrl.trim();
  if (!jobUrl) {
    throw new Error(API_ERROR_JOB_URL_REQUIRED);
  }

  if (jobUrl.length > AUTOMATION_MAX_JOB_URL_LENGTH) {
    throw new Error(
      API_ERROR_JOB_URL_EXCEEDS_LENGTH.replace("__MAX__", String(AUTOMATION_MAX_JOB_URL_LENGTH)),
    );
  }

  if (!URL.canParse(jobUrl)) {
    throw new Error(API_ERROR_JOB_URL_ABSOLUTE);
  }
  const parsedUrl = new URL(jobUrl);

  if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") {
    throw new Error(API_ERROR_JOB_URL_HTTP_ONLY);
  }

  if (parsedUrl.username || parsedUrl.password) {
    throw new Error(API_ERROR_JOB_URL_NO_CREDENTIALS);
  }

  const host = parsedUrl.hostname.toLowerCase();
  if (isDisallowedAutomationHost(host)) {
    throw new Error(API_ERROR_JOB_URL_DISALLOWED_HOST);
  }

  return parsedUrl.toString();
}

/**
 * Normalize custom answers payload by enforcing strict typing and length limits.
 */
export function sanitizeCustomAnswers(
  customAnswers: Record<string, unknown> | undefined,
): Record<string, string> {
  if (!customAnswers) {
    return {};
  }

  if (typeof customAnswers !== "object" || Array.isArray(customAnswers)) {
    throw new Error(API_ERROR_CUSTOM_ANSWERS_OBJECT);
  }

  const entries = Object.entries(customAnswers);
  if (entries.length > MAX_CUSTOM_ANSWER_COUNT) {
    throw new Error(
      API_ERROR_CUSTOM_ANSWERS_MAX_COUNT.replace("__MAX__", String(MAX_CUSTOM_ANSWER_COUNT)),
    );
  }

  const normalized: Record<string, string> = {};
  for (const [rawKey, rawValue] of entries) {
    const key = rawKey.trim();
    if (!key) {
      throw new Error(API_ERROR_CUSTOM_ANSWERS_KEYS);
    }
    if (key.length > MAX_CUSTOM_ANSWER_KEY_LENGTH) {
      throw new Error(
        API_ERROR_CUSTOM_ANSWERS_KEY_EXCEEDS.replace(
          "__MAX__",
          String(MAX_CUSTOM_ANSWER_KEY_LENGTH),
        ),
      );
    }

    if (typeof rawValue !== "string") {
      throw new Error(API_ERROR_CUSTOM_ANSWERS_VALUE_MUST_BE_STRING.replace("__KEY__", key));
    }

    const value = rawValue.trim();
    if (value.length > MAX_CUSTOM_ANSWER_VALUE_LENGTH) {
      throw new Error(
        API_ERROR_CUSTOM_ANSWERS_VALUE_EXCEEDS.replace("__KEY__", key).replace(
          "__MAX__",
          String(MAX_CUSTOM_ANSWER_VALUE_LENGTH),
        ),
      );
    }

    normalized[key] = value;
  }

  return normalized;
}

function isDisallowedAutomationHost(hostname: string): boolean {
  if (!hostname) {
    return true;
  }

  if (allowAutomationPrivateHostsOptIn()) {
    return false;
  }

  if (hostname === LOOPBACK_HOST_IPV4 || hostname === DEFAULT_HOST) {
    return true;
  }

  if (DISALLOWED_HOST_PATTERNS.some((pattern) => pattern.test(hostname))) {
    return true;
  }

  if (isIpv4Address(hostname)) {
    return isDisallowedIpv4(hostname);
  }

  if (isIpv6Address(hostname)) {
    return isDisallowedIpv6(hostname);
  }

  return false;
}

function isDisallowedIpv4(hostname: string): boolean {
  const segments = hostname.split(".").map((segment) => Number.parseInt(segment, DECIMAL_RADIX));
  const [first, second] = segments;
  if (Number.isNaN(first) || Number.isNaN(second)) {
    return false;
  }

  return DISALLOWED_IPV4_PREFIXES.some(
    ([disallowedFirst, disallowedSecond]) =>
      first === disallowedFirst && (disallowedSecond === 0 ? true : second === disallowedSecond),
  );
}

function isIpv4Address(hostname: string): boolean {
  const segments = hostname.split(".");
  if (segments.length !== NUM_4) {
    return false;
  }

  for (const segment of segments) {
    if (!IP_SEGMENT_REGEX.test(segment)) {
      return false;
    }

    const parsed = Number.parseInt(segment, DECIMAL_RADIX);
    if (Number.isNaN(parsed) || parsed < 0 || parsed > NUM_255) {
      return false;
    }
  }

  return true;
}

function isIpv6Address(hostname: string): boolean {
  return hostname.includes(":") && IPV6_SEGMENT_REGEX.test(hostname);
}

function isDisallowedIpv6(hostname: string): boolean {
  return hostname === "::1" || DISALLOWED_IPV6_PREFIX_PATTERN.test(hostname);
}

import {
  AUTOMATION_MAX_CONCURRENT_RUNS,
  AUTOMATION_MAX_SCHEDULE_LEAD_TIME_MS,
} from "@bao/shared/constants/automation-limits";
import {
  automationSettingsSchema,
  emailTransportSettingsSchema,
} from "@bao/shared/schemas/settings.schema";
import type { AutomationSettings } from "@bao/shared/types/settings-contracts";
import {
  DEFAULT_AUTOMATION_SETTINGS,
  DEFAULT_EMAIL_TRANSPORT_SETTINGS,
} from "@bao/shared/types/settings-defaults";
import { isEmailTransportConfigured } from "@bao/shared/utils/email-transport";
import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { DEFAULT_SETTINGS_ID, settings } from "../../db/schema/settings";
import { decryptProviderKeys } from "../../utils/settings-decrypt";
import { AIService } from "../ai/ai-service";
import type { EmailTransportRuntimeConfig } from "../email-delivery-service";
import { AutomationValidationError } from "./automation-errors";

const MIN_CONCURRENT_RUNS = 1;
const MIN_SCHEDULE_LEAD_TIME_MS = 1_000;

export const loadAutomationSettings = async (): Promise<AutomationSettings> => {
  const settingsQueryResult = await settle(
    db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID)).limit(1),
  );
  if (settingsQueryResult.status === "rejected") {
    return DEFAULT_AUTOMATION_SETTINGS;
  }

  const rows = settingsQueryResult.value;
  if (rows.length > 0 && rows[0].automationSettings) {
    const parsedSettings = automationSettingsSchema.safeParse(rows[0].automationSettings);
    if (parsedSettings.success) {
      return parsedSettings.data;
    }
  }

  return DEFAULT_AUTOMATION_SETTINGS;
};

export const resolveMaxConcurrentRuns = (settingsValue: AutomationSettings): number => {
  const configured = Number.isFinite(settingsValue.maxConcurrentRuns)
    ? Math.trunc(settingsValue.maxConcurrentRuns)
    : DEFAULT_AUTOMATION_SETTINGS.maxConcurrentRuns;

  return Math.min(Math.max(MIN_CONCURRENT_RUNS, configured), AUTOMATION_MAX_CONCURRENT_RUNS);
};

export const tryLoadAIService = async (): Promise<AIService | null> => {
  const settingsQueryResult = await settle(
    db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID)).limit(1),
  );
  if (settingsQueryResult.status === "rejected") {
    return null;
  }

  const [row] = settingsQueryResult.value;
  return AIService.fromSettings({ ...row, ...decryptProviderKeys(row) });
};

export const loadEmailTransportConfig = async (
  missingSettingsMessage: string,
): Promise<EmailTransportRuntimeConfig> => {
  const settingsQueryResult = await settle(
    db.select().from(settings).where(eq(settings.id, DEFAULT_SETTINGS_ID)).limit(1),
  );
  if (settingsQueryResult.status === "rejected") {
    throw new Error(missingSettingsMessage);
  }

  const [row] = settingsQueryResult.value;
  const parsedTransportSettings = emailTransportSettingsSchema.safeParse(
    row?.emailTransportSettings ?? DEFAULT_EMAIL_TRANSPORT_SETTINGS,
  );

  if (!parsedTransportSettings.success) {
    throw new Error(missingSettingsMessage);
  }

  const hasPassword = Boolean(row?.emailTransportPassword);
  if (!isEmailTransportConfigured(parsedTransportSettings.data, hasPassword)) {
    throw new Error(missingSettingsMessage);
  }

  return {
    ...parsedTransportSettings.data,
    password: row?.emailTransportPassword ?? null,
  };
};

export const normalizeScheduledRunAt = (runAt: string): string => {
  const parsedRunAt = new Date(runAt);
  const targetMs = parsedRunAt.getTime();
  if (Number.isNaN(targetMs)) {
    throw new AutomationValidationError("runAt must be a valid ISO timestamp");
  }

  const leadTimeMs = targetMs - Date.now();
  if (leadTimeMs < MIN_SCHEDULE_LEAD_TIME_MS) {
    throw new AutomationValidationError("runAt must be at least 1 second in the future");
  }
  if (leadTimeMs > AUTOMATION_MAX_SCHEDULE_LEAD_TIME_MS) {
    throw new AutomationValidationError("runAt must be within 30 days");
  }

  return parsedRunAt.toISOString();
};

import {
  API_ERROR_EMPTY_EMAIL_RESPONSE,
  API_ERROR_NO_AI_PROVIDER_EMAIL,
} from "@bao/shared/constants/api-errors";
import { settle } from "@bao/shared/utils/promise";
import { emailResponsePrompt } from "../ai/prompts-career";
import { emailDeliveryService } from "../email-delivery-service";
import type {
  EmailDeliveryResult,
  EmailGenerationResult,
  EmailResponsePayload,
  EmailResponseRuntime,
} from "./automation-email-response-contracts";

export const generateEmailResponse = async (
  normalized: EmailResponsePayload,
  loadAIService: EmailResponseRuntime["loadAIService"],
): Promise<EmailGenerationResult> => {
  const aiService = await loadAIService();
  if (!aiService) {
    throw new Error(API_ERROR_NO_AI_PROVIDER_EMAIL);
  }

  const aiResultOutcome = await settle(
    aiService.generate(
      emailResponsePrompt(
        normalized.subject,
        normalized.message,
        normalized.tone,
        normalized.sender,
      ),
      { purpose: "emailResponse" },
    ),
  );
  if (aiResultOutcome.status === "rejected") {
    throw aiResultOutcome.reason;
  }

  const aiResult = aiResultOutcome.value;
  const reply = aiResult.content.trim();
  if (reply.length === 0) {
    throw new Error(API_ERROR_EMPTY_EMAIL_RESPONSE);
  }

  return { reply, provider: aiResult.provider, model: aiResult.model };
};

export const deliverGeneratedEmail = async (
  normalized: EmailResponsePayload,
  reply: string,
  loadEmailTransportConfig: EmailResponseRuntime["loadEmailTransportConfig"],
): Promise<EmailDeliveryResult> => {
  if (!normalized.recipientEmail) {
    throw new Error("recipientEmail is required for email delivery");
  }

  const deliveryConfig = await loadEmailTransportConfig();
  const deliveryResult = await emailDeliveryService.send(deliveryConfig, {
    recipientEmail: normalized.recipientEmail,
    subject: normalized.subject,
    body: reply,
  });

  return {
    delivered: true,
    recipientEmail: deliveryResult.recipientEmail,
    deliveredAt: deliveryResult.deliveredAt,
    messageId: deliveryResult.messageId,
  };
};

import { API_ERROR_NETWORK_REQUEST_FAILED } from "@bao/shared/constants/api-errors";
import { HTTP_STATUS_INTERNAL_SERVER_ERROR, HTTP_STATUS_TOO_MANY_REQUESTS } from "@bao/shared/constants/http";
import { config } from "../../config/env";
import type { FetchPageResult } from "./smart-field-mapper-contracts";

export const wait = (delayMs: number): Promise<void> =>
  new Promise((resolve) => {
    const timer = setTimeout(() => resolve(), delayMs);
    if (
      typeof timer === "object" &&
      timer !== null &&
      "unref" in timer &&
      typeof timer.unref === "function"
    ) {
      timer.unref();
    }
  });

const isRetryableFetchFailure = (result: FetchPageResult): boolean => {
  if (result.ok) {
    return false;
  }
  if (typeof result.statusCode !== "number") {
    return true;
  }
  return result.statusCode === HTTP_STATUS_TOO_MANY_REQUESTS || result.statusCode >= HTTP_STATUS_INTERNAL_SERVER_ERROR;
};

const fetchPage = (url: string): Promise<FetchPageResult> =>
  fetch(url, {
    signal: AbortSignal.timeout(config.smartFieldMapperFetchTimeoutMs),
    headers: {
      "User-Agent": config.smartFieldMapperUserAgent,
    },
  }).then(
    async (response) => {
      if (!response.ok) {
        return {
          ok: false,
          statusCode: response.status,
          message: `HTTP ${response.status}`,
        } satisfies FetchPageResult;
      }

      return {
        ok: true,
        html: await response.text(),
      } satisfies FetchPageResult;
    },
    () =>
      ({
        ok: false,
        message: API_ERROR_NETWORK_REQUEST_FAILED,
      }) satisfies FetchPageResult,
  );

export const fetchPageWithRetry = (params: {
  url: string;
  attemptsRemaining: number;
  delayMs: number;
}): Promise<FetchPageResult> =>
  fetchPage(params.url).then(async (result) => {
    if (!isRetryableFetchFailure(result) || params.attemptsRemaining <= 1) {
      return result;
    }

    await wait(params.delayMs);
    return fetchPageWithRetry({
      ...params,
      attemptsRemaining: params.attemptsRemaining - 1,
      delayMs: params.delayMs * 2,
    });
  });

