import { AUTOMATION_MAX_EMAIL_MESSAGE_LENGTH } from "@bao/shared/constants/automation-limits";
import { SCHEMA_MAX_LENGTH_SHORT } from "@bao/shared/constants/schema-limits";
import type {
  EmailResponseRequest,
  EmailResponseTone,
} from "@bao/shared/schemas/automation-email.schema";
import { isValidEmail } from "@bao/shared/utils/validation";
import { AutomationValidationError } from "./automation-errors";
import type { EmailResponseExecutionPayload } from "./automation-run-inputs";

const MAX_EMAIL_SUBJECT_LENGTH = SCHEMA_MAX_LENGTH_SHORT;
const MAX_EMAIL_SENDER_LENGTH = SCHEMA_MAX_LENGTH_SHORT;

export const DEFAULT_EMAIL_RESPONSE_TONE: EmailResponseTone = "professional";

const EMAIL_RESPONSE_TONES: readonly EmailResponseTone[] = [
  "professional",
  "friendly",
  "concise",
] as const;

export const isEmailResponseTone = (value: string): value is EmailResponseTone =>
  EMAIL_RESPONSE_TONES.some((tone) => tone === value);

const validateEmailResponseTextLengths = (
  subject: string,
  message: string,
  sender?: string,
): void => {
  if (subject.length === 0 || subject.length > MAX_EMAIL_SUBJECT_LENGTH) {
    throw new AutomationValidationError(
      `subject is required and must be <= ${MAX_EMAIL_SUBJECT_LENGTH} characters`,
    );
  }

  if (message.length === 0 || message.length > AUTOMATION_MAX_EMAIL_MESSAGE_LENGTH) {
    throw new AutomationValidationError(
      `message is required and must be <= ${AUTOMATION_MAX_EMAIL_MESSAGE_LENGTH} characters`,
    );
  }

  if (sender && sender.length > MAX_EMAIL_SENDER_LENGTH) {
    throw new AutomationValidationError(`sender must be <= ${MAX_EMAIL_SENDER_LENGTH} characters`);
  }
};

const resolveRecipientEmail = (
  sender: string | undefined,
  explicitRecipient: string | undefined,
  deliverAfterGeneration: boolean,
): string | undefined => {
  if (explicitRecipient && !isValidEmail(explicitRecipient)) {
    throw new AutomationValidationError("recipientEmail must be a valid email address");
  }

  const inferredRecipient = sender && isValidEmail(sender) ? sender : undefined;
  const recipientEmail = explicitRecipient || inferredRecipient;
  if (deliverAfterGeneration && !recipientEmail) {
    throw new AutomationValidationError("recipientEmail is required when delivery is enabled");
  }

  return recipientEmail;
};

const normalizeTone = (toneValue: EmailResponseRequest["tone"]): EmailResponseTone => {
  const normalizedTone = toneValue?.trim();
  if (normalizedTone && isEmailResponseTone(normalizedTone)) {
    return normalizedTone;
  }

  return DEFAULT_EMAIL_RESPONSE_TONE;
};

export const normalizeEmailResponsePayload = (
  payload: EmailResponseRequest,
): EmailResponseExecutionPayload => {
  const subject = payload.subject?.trim() ?? "";
  const message = payload.message?.trim() ?? "";
  const sender = payload.sender?.trim();
  const explicitRecipient = payload.recipientEmail?.trim();
  const deliverAfterGeneration = payload.deliverAfterGeneration === true;

  validateEmailResponseTextLengths(subject, message, sender);

  const recipientEmail = resolveRecipientEmail(sender, explicitRecipient, deliverAfterGeneration);
  const tone = normalizeTone(payload.tone);

  return {
    subject,
    message,
    tone,
    deliverAfterGeneration,
    ...(sender ? { sender } : {}),
    ...(recipientEmail ? { recipientEmail } : {}),
  };
};

import {
  AI_DEFAULT_TEMPERATURE_STRUCTURED,
  AI_MAX_TOKENS_FIELD_MAPPER,
} from "@bao/shared/constants/ai-generation";
import { safeParseJson } from "@bao/shared/utils/json";
import { config } from "../../config/env";
import { formFieldAnalysisPrompt } from "../ai/prompts-automation";
import {
  EMPTY_FIELD_ANALYSIS_RESULT,
  type FieldMapperAIClient,
  fieldAnalysisSchema,
  type SmartFieldAnalysisResult,
  selectorMapSchema,
} from "./smart-field-mapper-contracts";
import { wait } from "./smart-field-mapper-fetch";

const parseFieldAnalysisResponse = (content: string): SmartFieldAnalysisResult => {
  const cleaned = content
    .replace(/```json\n?/gu, "")
    .replace(/```\n?/gu, "")
    .trim();
  const parsedValue = safeParseJson(cleaned);
  const parsedAnalysis = fieldAnalysisSchema.safeParse(parsedValue);
  if (parsedAnalysis.success) {
    return parsedAnalysis.data;
  }

  const parsedSelectors = selectorMapSchema.safeParse(parsedValue);
  if (parsedSelectors.success) {
    return {
      selectorMap: parsedSelectors.data,
      fieldAnswers: {},
    };
  }

  return EMPTY_FIELD_ANALYSIS_RESULT;
};

export const stripToFormElements = (html: string): string => {
  const formElementRegex =
    /<(?:form|input|textarea|select|option|label|button|fieldset|legend)\b[^>]*(?:\/>|>(?:[\s\S]*?)<\/(?:form|input|textarea|select|option|label|button|fieldset|legend)>|>)/giu;

  const matches = html.match(formElementRegex);
  if (!matches) {
    return "";
  }

  let result = "";
  for (const match of matches) {
    if (result.length + match.length > config.smartFieldMapperMaxFormHtmlChars) {
      break;
    }
    result += `${match}\n`;
  }

  return result.trim();
};

export const generateFieldAnalysisWithRetry = (params: {
  aiService: FieldMapperAIClient;
  strippedHtml: string;
  fieldsNeeded: string[];
  candidateContext: string;
  attemptsRemaining: number;
  delayMs: number;
}): Promise<SmartFieldAnalysisResult> => {
  const prompt = formFieldAnalysisPrompt(
    params.strippedHtml,
    params.fieldsNeeded,
    params.candidateContext,
  );

  return params.aiService
    .generate(prompt, {
      purpose: "automationFieldMapping",
      temperature: AI_DEFAULT_TEMPERATURE_STRUCTURED,
      maxTokens: AI_MAX_TOKENS_FIELD_MAPPER,
    })
    .then(
      async (response) => {
        if (response.error || !response.content) {
          if (params.attemptsRemaining > 1) {
            await wait(params.delayMs);
            return generateFieldAnalysisWithRetry({
              ...params,
              attemptsRemaining: params.attemptsRemaining - 1,
              delayMs: params.delayMs * 2,
            });
          }
          return EMPTY_FIELD_ANALYSIS_RESULT;
        }

        const parsedAnalysis = parseFieldAnalysisResponse(response.content);
        if (
          Object.keys(parsedAnalysis.selectorMap).length > 0 ||
          Object.keys(parsedAnalysis.fieldAnswers).length > 0
        ) {
          return parsedAnalysis;
        }

        if (params.attemptsRemaining > 1) {
          await wait(params.delayMs);
          return generateFieldAnalysisWithRetry({
            ...params,
            attemptsRemaining: params.attemptsRemaining - 1,
            delayMs: params.delayMs * 2,
          });
        }

        return EMPTY_FIELD_ANALYSIS_RESULT;
      },
      async () => {
        if (params.attemptsRemaining > 1) {
          await wait(params.delayMs);
          return generateFieldAnalysisWithRetry({
            ...params,
            attemptsRemaining: params.attemptsRemaining - 1,
            delayMs: params.delayMs * 2,
          });
        }
        return EMPTY_FIELD_ANALYSIS_RESULT;
      },
    );
};

import type { AutomationScrapeTarget } from "@bao/shared/constants/automation";
import { SCHEMA_MAX_ITEMS_BOARDS } from "@bao/shared/constants/schema-limits";
import type { EmailResponseRequest } from "@bao/shared/schemas/automation-email.schema";
import { generateId } from "@bao/shared/utils/validation";
import { and, count, eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { normalizeEmailResponsePayload } from "./automation-email-response-payload";
import { AutomationConcurrencyLimitError } from "./automation-errors";
import {
  assertJobApplyDependencies,
  normalizeJobApplyPayload,
} from "./automation-job-apply-preparation";
import {
  buildAuditInput,
  buildEmailResponseInput,
  buildScheduledJobApplyInput,
  buildScrapeInput,
  type JobApplyPayload,
  normalizeScrapeTarget,
  resolveScrapeAction,
} from "./automation-run-inputs";
import type { CreateProgressEvent } from "./automation-service-contracts";
import {
  loadAutomationSettings,
  normalizeScheduledRunAt,
  resolveMaxConcurrentRuns,
} from "./automation-settings-support";

const DEFAULT_PROGRESS = 0;
const SCHEDULED_ACTION_EMAIL_RESPONSE = "email_response";
const MAX_RECOVERABLE_SCHEDULED_RUNS = SCHEMA_MAX_ITEMS_BOARDS;

type ScheduledRunQueue = (runId: string, runAt: string) => void;

interface AutomationRunCreatorOptions {
  createProgressEvent: CreateProgressEvent;
  queueScheduledRun: ScheduledRunQueue;
}

export class AutomationRunCreator {
  static readonly maxRecoverableScheduledRuns = MAX_RECOVERABLE_SCHEDULED_RUNS;

  constructor(private readonly options: AutomationRunCreatorOptions) {}

  async createJobApplyRun(
    payload: JobApplyPayload,
    runOptions: { includeActionInPayload?: boolean } = {},
  ): Promise<string> {
    const normalized = normalizeJobApplyPayload(payload);
    const settingsSnapshot = await loadAutomationSettings();
    const maxConcurrentRuns = resolveMaxConcurrentRuns(settingsSnapshot);

    await assertJobApplyDependencies(normalized);

    const now = new Date().toISOString();

    return db.transaction(async (tx) => {
      const runningRows = await tx
        .select({ count: count() })
        .from(automationRuns)
        .where(and(eq(automationRuns.status, "running"), eq(automationRuns.type, "job_apply")));

      const runningCount = runningRows[0]?.count || 0;
      if (runningCount >= maxConcurrentRuns) {
        throw new AutomationConcurrencyLimitError(runningCount, maxConcurrentRuns);
      }

      const runId = generateId();
      await tx.insert(automationRuns).values({
        id: runId,
        type: "job_apply",
        status: "running",
        jobId: normalized.jobId || null,
        userId: null,
        input: buildAuditInput(normalized, runOptions.includeActionInPayload ?? false),
        progress: DEFAULT_PROGRESS,
        currentStep: null,
        totalSteps: null,
        exitCode: null,
        timedOut: false,
        aborted: false,
        executionMs: null,
        startedAt: now,
        createdAt: now,
        updatedAt: now,
      });

      return runId;
    });
  }

  async createScheduledJobApplyRun(
    payload: JobApplyPayload,
    runAt: string,
  ): Promise<{ runId: string; scheduledFor: string }> {
    const normalized = normalizeJobApplyPayload(payload);
    const scheduledFor = normalizeScheduledRunAt(runAt);
    await assertJobApplyDependencies(normalized);

    const now = new Date().toISOString();
    const runId = generateId();
    const scheduleInput = buildScheduledJobApplyInput(normalized, scheduledFor);

    await db.insert(automationRuns).values({
      id: runId,
      type: "job_apply",
      status: "pending",
      jobId: normalized.jobId || null,
      userId: null,
      input: scheduleInput,
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: null,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    this.options.queueScheduledRun(runId, scheduledFor);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: "job_apply",
        status: "pending",
        message: `Scheduled for ${scheduledFor}`,
      }),
    );

    return { runId, scheduledFor };
  }

  async createScheduledEmailResponseRun(
    payload: EmailResponseRequest,
    runAt: string,
  ): Promise<{ runId: string; scheduledFor: string }> {
    const normalized = normalizeEmailResponsePayload(payload);
    const scheduledFor = normalizeScheduledRunAt(runAt);
    const now = new Date().toISOString();
    const runId = generateId();

    await db.insert(automationRuns).values({
      id: runId,
      type: "email",
      status: "pending",
      jobId: null,
      userId: null,
      input: buildEmailResponseInput(normalized, {
        includeAction: true,
        scheduledFor,
      }),
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    this.options.queueScheduledRun(runId, scheduledFor);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: SCHEDULED_ACTION_EMAIL_RESPONSE,
        status: "pending",
        message: `Scheduled for ${scheduledFor}`,
      }),
    );

    return { runId, scheduledFor };
  }

  async createScheduledScrapeRun(
    target: AutomationScrapeTarget,
    runAt: string,
  ): Promise<{ runId: string; scheduledFor: string }> {
    const normalizedTarget = normalizeScrapeTarget(target);
    const scheduledFor = normalizeScheduledRunAt(runAt);
    const now = new Date().toISOString();
    const runId = generateId();

    await db.insert(automationRuns).values({
      id: runId,
      type: "scrape",
      status: "pending",
      jobId: null,
      userId: null,
      input: buildScrapeInput(
        {
          target: normalizedTarget,
        },
        {
          includeAction: true,
          scheduledFor,
        },
      ),
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    this.options.queueScheduledRun(runId, scheduledFor);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: resolveScrapeAction(normalizedTarget),
        status: "pending",
        message: `Scheduled for ${scheduledFor}`,
      }),
    );

    return { runId, scheduledFor };
  }

  async createScrapeRun(target: AutomationScrapeTarget): Promise<string> {
    const normalizedTarget = normalizeScrapeTarget(target);
    const now = new Date().toISOString();
    const runId = generateId();

    await db.insert(automationRuns).values({
      id: runId,
      type: "scrape",
      status: "pending",
      jobId: null,
      userId: null,
      input: buildScrapeInput(
        {
          target: normalizedTarget,
        },
        {
          includeAction: false,
        },
      ),
      progress: DEFAULT_PROGRESS,
      currentStep: null,
      totalSteps: null,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: null,
      createdAt: now,
      updatedAt: now,
    });

    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: resolveScrapeAction(normalizedTarget),
        status: "pending",
        message: `Queued ${normalizedTarget} scrape`,
      }),
    );

    return runId;
  }
}

