import {
  AUTOMATION_SCRAPE_JOB_TARGETS,
  type AutomationScrapePortalId,
  automationScrapeTargetToPortalId,
  buildRpaCapabilityIdFromScrapeTarget,
  type RpaCapabilityAuditEntry,
  type RpaCapabilityAuditReport,
  type RpaCapabilityAuditSummary,
  type RpaCapabilityIssue,
} from "@bao/shared/constants/automation";
import { settle } from "@bao/shared/utils/promise";
import { loadJobProviderSettings } from "../jobs/providers/provider-settings";

interface ScrapePortalAuditConfig {
  name: string;
  enabled: boolean;
  fallbackUrl: string;
}

interface ScrapePortalAuditSnapshot {
  portalConfigById: Map<AutomationScrapePortalId, ScrapePortalAuditConfig>;
  sharedSettingsIssue: RpaCapabilityIssue | null;
}

const createJobApplyCapabilityAuditEntry = (): RpaCapabilityAuditEntry => ({
  id: "job_apply",
  category: "job_apply",
  name: "Job Apply",
  target: null,
  implemented: true,
  configured: true,
  enabled: true,
  manualRunAvailable: true,
  scheduledRunAvailable: true,
  runHistoryAvailable: true,
  liveUpdatesAvailable: true,
  issues: [],
});

const createStudioScrapeCapabilityAuditEntry = (): RpaCapabilityAuditEntry => ({
  id: buildRpaCapabilityIdFromScrapeTarget("studios"),
  category: "scrape",
  name: "Studios",
  target: "studios",
  implemented: true,
  configured: true,
  enabled: true,
  manualRunAvailable: true,
  scheduledRunAvailable: true,
  runHistoryAvailable: true,
  liveUpdatesAvailable: true,
  issues: [],
});

const summarizeRpaCapabilities = (
  capabilities: readonly RpaCapabilityAuditEntry[],
): RpaCapabilityAuditSummary =>
  capabilities.reduce<RpaCapabilityAuditSummary>(
    (accumulator, capability) => ({
      total: accumulator.total + 1,
      configured: accumulator.configured + (capability.configured ? 1 : 0),
      manualRunAvailable: accumulator.manualRunAvailable + (capability.manualRunAvailable ? 1 : 0),
      scheduledRunAvailable:
        accumulator.scheduledRunAvailable + (capability.scheduledRunAvailable ? 1 : 0),
      runHistoryAvailable:
        accumulator.runHistoryAvailable + (capability.runHistoryAvailable ? 1 : 0),
      liveUpdatesAvailable:
        accumulator.liveUpdatesAvailable + (capability.liveUpdatesAvailable ? 1 : 0),
    }),
    {
      total: 0,
      configured: 0,
      manualRunAvailable: 0,
      scheduledRunAvailable: 0,
      runHistoryAvailable: 0,
      liveUpdatesAvailable: 0,
    },
  );

const loadScrapePortalAuditSnapshot = async (): Promise<ScrapePortalAuditSnapshot> => {
  const providerSettingsResult = await settle(loadJobProviderSettings());
  const portalConfigById = new Map<AutomationScrapePortalId, ScrapePortalAuditConfig>();
  const sharedSettingsIssue =
    providerSettingsResult.status === "rejected"
      ? ({ code: "provider_settings_unavailable" } satisfies RpaCapabilityIssue)
      : null;

  if (providerSettingsResult.status === "fulfilled") {
    for (const portal of providerSettingsResult.value.gamingPortals) {
      portalConfigById.set(portal.id, {
        name: portal.name,
        enabled: portal.enabled,
        fallbackUrl: portal.fallbackUrl,
      });
    }
  }

  return {
    portalConfigById,
    sharedSettingsIssue,
  };
};

const buildScrapeCapabilityIssues = (
  configuredPortal: ScrapePortalAuditConfig | null,
  portalId: AutomationScrapePortalId,
  sharedSettingsIssue: RpaCapabilityIssue | null,
): RpaCapabilityIssue[] => {
  if (sharedSettingsIssue) {
    return [sharedSettingsIssue];
  }

  if (!configuredPortal) {
    return [{ code: "portal_configuration_missing", portalId }];
  }

  const issues: RpaCapabilityIssue[] = [];
  if (!configuredPortal.enabled) {
    issues.push({
      code: "portal_disabled",
      portalId,
      portalName: configuredPortal.name,
    });
  }
  if (configuredPortal.fallbackUrl.trim().length === 0) {
    issues.push({
      code: "portal_fallback_url_missing",
      portalId,
      portalName: configuredPortal.name,
    });
  }
  return issues;
};

const buildJobScrapeCapabilityAuditEntry = (
  target: (typeof AUTOMATION_SCRAPE_JOB_TARGETS)[number],
  auditSnapshot: ScrapePortalAuditSnapshot,
): RpaCapabilityAuditEntry => {
  const portalId = automationScrapeTargetToPortalId(target);
  const configuredPortal = auditSnapshot.portalConfigById.get(portalId) ?? null;
  const issues = buildScrapeCapabilityIssues(
    configuredPortal,
    portalId,
    auditSnapshot.sharedSettingsIssue,
  );
  const enabled = configuredPortal?.enabled === true;
  const configured = Boolean(
    configuredPortal?.enabled && configuredPortal.fallbackUrl.trim().length > 0,
  );

  return {
    id: buildRpaCapabilityIdFromScrapeTarget(target),
    category: "scrape",
    name: configuredPortal?.name ?? portalId,
    target,
    implemented: true,
    configured,
    enabled,
    manualRunAvailable: true,
    scheduledRunAvailable: true,
    runHistoryAvailable: true,
    liveUpdatesAvailable: true,
    issues,
  };
};

export const createRpaCapabilityAuditReport = async (): Promise<RpaCapabilityAuditReport> => {
  const auditSnapshot = await loadScrapePortalAuditSnapshot();
  const capabilities: RpaCapabilityAuditEntry[] = [
    createJobApplyCapabilityAuditEntry(),
    createStudioScrapeCapabilityAuditEntry(),
    ...AUTOMATION_SCRAPE_JOB_TARGETS.map((target) =>
      buildJobScrapeCapabilityAuditEntry(target, auditSnapshot),
    ),
  ];

  return {
    generatedAt: new Date().toISOString(),
    summary: summarizeRpaCapabilities(capabilities),
    capabilities,
  };
};

import {
  AUTOMATION_SCRAPE_TARGETS,
  type AutomationScrapeTarget,
  automationScrapeTargetToAction,
} from "@bao/shared/constants/automation";
import type { EmailResponseTone } from "@bao/shared/schemas/automation-email.schema";
import type { JsonObject } from "@bao/shared/utils/json";
import { AutomationValidationError } from "./automation-errors";

export interface JobApplyPayload {
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
  customAnswers?: Record<string, string>;
}

export interface JobApplyExecutionPayload {
  jobUrl: string;
  resumeId: string;
  coverLetterId?: string;
  jobId?: string;
  customAnswers: Record<string, string>;
}

export interface EmailResponseExecutionPayload {
  subject: string;
  message: string;
  sender?: string;
  tone: EmailResponseTone;
  recipientEmail?: string;
  deliverAfterGeneration: boolean;
}

export interface ScheduledRunMetadata {
  runAt: string;
}

export interface ScrapeExecutionPayload {
  target: AutomationScrapeTarget;
}

const isScrapeTarget = (value: string): value is AutomationScrapeTarget =>
  AUTOMATION_SCRAPE_TARGETS.some((target) => target === value);

const withScheduleMetadata = (input: JsonObject, runAt: string): JsonObject => ({
  ...input,
  schedule: { runAt },
});

const parseCustomAnswers = (input: JsonObject | null): Record<string, string> => {
  if (!input) {
    return {};
  }

  const value = input.customAnswers;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  const parsedAnswers: Record<string, string> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "string" && entry.length > 0) {
      parsedAnswers[key] = entry;
    }
  }
  return parsedAnswers;
};

export const buildAuditInput = (
  payload: JobApplyExecutionPayload,
  includeAction: boolean,
): JsonObject => {
  const auditInput: JsonObject = {
    jobUrl: payload.jobUrl,
    resumeId: payload.resumeId,
    jobId: payload.jobId ?? null,
    customAnswers: payload.customAnswers,
  };

  if (payload.coverLetterId) {
    auditInput.coverLetterId = payload.coverLetterId;
  }

  if (includeAction) {
    auditInput.action = "job_apply";
  }

  return auditInput;
};

export const parseScheduledRunMetadata = (
  input: JsonObject | null,
): ScheduledRunMetadata | null => {
  if (!input) {
    return null;
  }

  const scheduleValue = input.schedule;
  if (!scheduleValue || typeof scheduleValue !== "object" || Array.isArray(scheduleValue)) {
    return null;
  }

  if (!("runAt" in scheduleValue)) {
    return null;
  }

  const runAt = scheduleValue.runAt;
  if (typeof runAt !== "string" || runAt.trim().length === 0) {
    return null;
  }

  return { runAt: runAt.trim() };
};

export const parseScheduledJobApplyPayload = (input: JsonObject | null): JobApplyPayload | null => {
  if (!input) {
    return null;
  }

  const jobUrl = typeof input.jobUrl === "string" ? input.jobUrl.trim() : "";
  const resumeId = typeof input.resumeId === "string" ? input.resumeId.trim() : "";
  if (jobUrl.length === 0 || resumeId.length === 0) {
    return null;
  }

  const payload: JobApplyPayload = {
    jobUrl,
    resumeId,
  };

  if (typeof input.coverLetterId === "string" && input.coverLetterId.trim().length > 0) {
    payload.coverLetterId = input.coverLetterId.trim();
  }
  if (typeof input.jobId === "string" && input.jobId.trim().length > 0) {
    payload.jobId = input.jobId.trim();
  }

  const customAnswers = parseCustomAnswers(input);
  if (Object.keys(customAnswers).length > 0) {
    payload.customAnswers = customAnswers;
  }

  return payload;
};

export const buildScheduledJobApplyInput = (
  payload: JobApplyExecutionPayload,
  scheduledFor: string,
): JsonObject => withScheduleMetadata(buildAuditInput(payload, true), scheduledFor);

export const buildEmailResponseInput = (
  normalized: EmailResponseExecutionPayload,
  options: { includeAction: boolean; scheduledFor?: string },
): JsonObject => {
  const baseInput: JsonObject = {
    subject: normalized.subject,
    message: normalized.message,
    tone: normalized.tone,
    deliverAfterGeneration: normalized.deliverAfterGeneration,
    ...(normalized.sender ? { sender: normalized.sender } : {}),
    ...(normalized.recipientEmail ? { recipientEmail: normalized.recipientEmail } : {}),
    ...(options.includeAction ? { action: "email_response" } : {}),
  };

  return options.scheduledFor ? withScheduleMetadata(baseInput, options.scheduledFor) : baseInput;
};

export const parseScheduledEmailResponsePayload = (
  input: JsonObject | null,
  options: {
    defaultTone: EmailResponseTone;
    isEmailResponseTone: (value: string) => value is EmailResponseTone;
  },
): EmailResponseExecutionPayload | null => {
  if (!input) {
    return null;
  }

  const subject = typeof input.subject === "string" ? input.subject.trim() : "";
  const message = typeof input.message === "string" ? input.message.trim() : "";
  if (subject.length === 0 || message.length === 0) {
    return null;
  }

  const toneCandidate = typeof input.tone === "string" ? input.tone.trim() : "";
  const tone = options.isEmailResponseTone(toneCandidate) ? toneCandidate : options.defaultTone;

  return {
    subject,
    message,
    tone,
    deliverAfterGeneration: input.deliverAfterGeneration === true,
    ...(typeof input.sender === "string" && input.sender.trim().length > 0
      ? { sender: input.sender.trim() }
      : {}),
    ...(typeof input.recipientEmail === "string" && input.recipientEmail.trim().length > 0
      ? { recipientEmail: input.recipientEmail.trim() }
      : {}),
  };
};

export const resolveScrapeAction = (target: AutomationScrapeTarget): string =>
  automationScrapeTargetToAction(target);

export const normalizeScrapeTarget = (target: string): AutomationScrapeTarget => {
  const normalized = target.trim();
  if (!isScrapeTarget(normalized)) {
    throw new AutomationValidationError("target must be a supported scrape target");
  }
  return normalized;
};

export const buildScrapeInput = (
  payload: ScrapeExecutionPayload,
  options: { includeAction: boolean; scheduledFor?: string },
): JsonObject => {
  const baseInput: JsonObject = {
    target: payload.target,
    ...(options.includeAction ? { action: resolveScrapeAction(payload.target) } : {}),
  };

  return options.scheduledFor ? withScheduleMetadata(baseInput, options.scheduledFor) : baseInput;
};

export const parseScheduledScrapePayload = (
  input: JsonObject | null,
): ScrapeExecutionPayload | null => {
  if (!input || typeof input.target !== "string") {
    return null;
  }

  const normalized = input.target.trim();
  if (!isScrapeTarget(normalized)) {
    return null;
  }

  return {
    target: normalized,
  };
};

import {
  API_ERROR_SCRAPE_JOBS_FAILED,
  API_ERROR_SCRAPE_STUDIOS_FAILED,
} from "@bao/shared/constants/api-errors";
import {
  type AutomationScrapeTarget,
  isAutomationJobScrapeTarget,
  type RpaCapabilityAuditReport,
} from "@bao/shared/constants/automation";
import { AUTOMATION_FINISHED_PROGRESS } from "@bao/shared/constants/automation-limits";
import { jsonObjectSchema } from "@bao/shared/schemas/json.schema";
import type { ScraperOperationResult } from "@bao/shared/types/jobs";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import type { JsonObject } from "@bao/shared/utils/json";
import { safeParseJson } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { scraperService } from "../scraper-service";
import {
  buildScrapeInput,
  normalizeScrapeTarget,
  resolveScrapeAction,
} from "./automation-run-inputs";
import { markRunFailed } from "./automation-run-persistence";
import { createRpaCapabilityAuditReport } from "./automation-scrape-audit";
import type { CreateProgressEvent } from "./automation-service-contracts";
import { loadAutomationSettings } from "./automation-settings-support";

const DEFAULT_PROGRESS = 0;

const toJsonRecord = (value: object): JsonObject => {
  const parsed = safeParseJson(JSON.stringify(value));
  const objectResult = jsonObjectSchema.safeParse(parsed);
  return objectResult.success ? objectResult.data : {};
};

const executeScrapeTarget = (target: AutomationScrapeTarget): Promise<ScraperOperationResult> => {
  if (!isAutomationJobScrapeTarget(target)) {
    return scraperService.scrapeStudios();
  }

  return scraperService.scrapeJobsForTarget(target);
};

const markScrapeRunStarted = async (
  runId: string,
  target: AutomationScrapeTarget,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const now = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      status: "running",
      input: buildScrapeInput({ target }, { includeAction: false }),
      progress: DEFAULT_PROGRESS,
      currentStep: 0,
      totalSteps: 1,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt: now,
      completedAt: null,
      updatedAt: now,
    })
    .where(eq(automationRuns.id, runId));

  broadcastAutomationEvent(
    createProgressEvent({
      runId,
      action: resolveScrapeAction(target),
      status: "running",
      message: `Running ${target} scrape`,
      step: 0,
      totalSteps: 1,
    }),
  );
};

const failScrapeRun = async (params: {
  runId: string;
  target: AutomationScrapeTarget;
  reason: Error;
  executionMs: number;
  createProgressEvent: CreateProgressEvent;
}): Promise<void> => {
  const automationSettings = await loadAutomationSettings();
  const errorMessage = toErrorMessage(
    params.reason,
    params.target === "studios" ? API_ERROR_SCRAPE_STUDIOS_FAILED : API_ERROR_SCRAPE_JOBS_FAILED,
  );
  await markRunFailed(params.runId, errorMessage, automationSettings, {
    exitCode: 1,
    timedOut: false,
    aborted: false,
    executionMs: params.executionMs,
    errorEnvelope: null,
  });
  broadcastAutomationEvent(
    params.createProgressEvent({
      runId: params.runId,
      action: resolveScrapeAction(params.target),
      status: "error",
      message: errorMessage,
      step: 1,
      totalSteps: 1,
    }),
  );
};

const completeScrapeRun = async (params: {
  runId: string;
  target: AutomationScrapeTarget;
  result: ScraperOperationResult;
  executionMs: number;
  createProgressEvent: CreateProgressEvent;
}): Promise<void> => {
  const completedAt = new Date().toISOString();
  const output = toJsonRecord({
    target: params.target,
    scraped: params.result.scraped,
    upserted: params.result.upserted,
    errors: params.result.errors,
    enrichment: params.result.enrichment,
  });

  await db
    .update(automationRuns)
    .set({
      status: "success",
      output,
      error: null,
      progress: AUTOMATION_FINISHED_PROGRESS,
      currentStep: 1,
      totalSteps: 1,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: params.executionMs,
      completedAt,
      updatedAt: completedAt,
    })
    .where(eq(automationRuns.id, params.runId));

  broadcastAutomationEvent(
    params.createProgressEvent({
      runId: params.runId,
      action: resolveScrapeAction(params.target),
      status: "success",
      message:
        `${params.target} scrape completed (` +
        `${params.result.scraped} scraped, ` +
        `${params.result.upserted} upserted, ` +
        `${params.result.enrichment.enrichedRecords} enriched)`,
      step: 1,
      totalSteps: 1,
    }),
  );
};

export const executeScrapeRun = async (
  runId: string,
  target: AutomationScrapeTarget,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const normalizedTarget = normalizeScrapeTarget(target);
  const startedAt = Date.now();
  await markScrapeRunStarted(runId, normalizedTarget, createProgressEvent);
  const scrapeResult = await settle(executeScrapeTarget(normalizedTarget));

  if (scrapeResult.status === "rejected") {
    await failScrapeRun({
      runId,
      target: normalizedTarget,
      reason: scrapeResult.reason,
      executionMs: Date.now() - startedAt,
      createProgressEvent,
    });
    return;
  }

  await completeScrapeRun({
    runId,
    target: normalizedTarget,
    result: scrapeResult.value,
    executionMs: Date.now() - startedAt,
    createProgressEvent,
  });
};

export const getRpaCapabilityAudit = async (): Promise<RpaCapabilityAuditReport> =>
  createRpaCapabilityAuditReport();

import { API_ERROR_EMAIL_DELIVERY_SETTINGS_MISSING } from "@bao/shared/constants/api-errors";
import { AUTOMATION_SCHEDULE_RETRY_DELAY_MS } from "@bao/shared/constants/automation-limits";
import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { executeEmailResponseRun, markEmailResponseRunStarted } from "./automation-email-response";
import {
  DEFAULT_EMAIL_RESPONSE_TONE,
  isEmailResponseTone,
} from "./automation-email-response-payload";
import { AutomationConcurrencyLimitError } from "./automation-errors";
import { normalizeJobApplyPayload } from "./automation-job-apply-preparation";
import {
  buildScheduledJobApplyInput,
  type JobApplyPayload,
  parseScheduledEmailResponsePayload,
  parseScheduledJobApplyPayload,
  parseScheduledScrapePayload,
} from "./automation-run-inputs";
import { markRunFailed } from "./automation-run-persistence";
import { executeScrapeRun } from "./automation-scrape-run";
import type { AutomationRunRow, CreateProgressEvent } from "./automation-service-contracts";
import {
  loadAutomationSettings,
  loadEmailTransportConfig,
  tryLoadAIService,
} from "./automation-settings-support";

const SCHEDULED_ACTION_JOB_APPLY = "job_apply";

const asJsonRecord = (value: JsonValue | null | undefined): JsonObject | null =>
  value && typeof value === "object" && !Array.isArray(value) ? value : null;

type ScheduledRunQueue = (runId: string, runAt: string) => void;
type ReadRunRow = (runId: string) => Promise<AutomationRunRow | null>;
type RunJobApply = (runId: string, payload: JobApplyPayload) => Promise<void>;

interface AutomationScheduledRunExecutorOptions {
  createProgressEvent: CreateProgressEvent;
  queueScheduledRun: ScheduledRunQueue;
  readRunRow: ReadRunRow;
  runJobApply: RunJobApply;
}

export class AutomationScheduledRunExecutor {
  constructor(private readonly options: AutomationScheduledRunExecutorOptions) {}

  async execute(runId: string): Promise<void> {
    const row = await this.options.readRunRow(runId);
    if (row?.status !== "pending") {
      return;
    }

    if (row.type === "job_apply") {
      await this.executeJobApply(row);
      return;
    }

    if (row.type === "email") {
      await this.executeEmail(row);
      return;
    }

    if (row.type === "scrape") {
      await this.executeScrape(row);
    }
  }

  private async failValidation(runId: string, errorMessage: string): Promise<void> {
    const automationSettings = await loadAutomationSettings();
    await markRunFailed(runId, errorMessage, automationSettings);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: "automation",
        status: "error",
        message: errorMessage,
      }),
    );
  }

  private async executeJobApply(row: AutomationRunRow): Promise<void> {
    const payload = parseScheduledJobApplyPayload(asJsonRecord(row.input));
    if (!payload) {
      await this.failValidation(row.id, "Scheduled job-apply payload is invalid");
      return;
    }

    const executionResult = await settle(this.options.runJobApply(row.id, payload));
    if (executionResult.status === "fulfilled") {
      return;
    }

    if (executionResult.reason instanceof AutomationConcurrencyLimitError) {
      await this.requeueJobApplyRun(row.id, payload);
      return;
    }

    throw executionResult.reason;
  }

  private async requeueJobApplyRun(runId: string, payload: JobApplyPayload): Promise<void> {
    const nextRunAt = new Date(Date.now() + AUTOMATION_SCHEDULE_RETRY_DELAY_MS).toISOString();
    const normalizedPayload = normalizeJobApplyPayload(payload);

    await db
      .update(automationRuns)
      .set({
        input: buildScheduledJobApplyInput(normalizedPayload, nextRunAt),
        status: "pending",
        updatedAt: new Date().toISOString(),
      })
      .where(eq(automationRuns.id, runId));

    this.options.queueScheduledRun(runId, nextRunAt);
    broadcastAutomationEvent(
      this.options.createProgressEvent({
        runId,
        action: SCHEDULED_ACTION_JOB_APPLY,
        status: "pending",
        message: `Concurrency limit reached, retrying at ${nextRunAt}`,
      }),
    );
  }

  private async executeEmail(row: AutomationRunRow): Promise<void> {
    const payload = parseScheduledEmailResponsePayload(asJsonRecord(row.input), {
      defaultTone: DEFAULT_EMAIL_RESPONSE_TONE,
      isEmailResponseTone,
    });
    if (!payload) {
      await this.failValidation(row.id, "Scheduled email payload is invalid");
      return;
    }

    await markEmailResponseRunStarted(row.id, payload);
    await executeEmailResponseRun(row.id, payload, {
      loadAIService: tryLoadAIService,
      loadEmailTransportConfig: () =>
        loadEmailTransportConfig(API_ERROR_EMAIL_DELIVERY_SETTINGS_MISSING),
      createProgressEvent: this.options.createProgressEvent,
      broadcastProgressEvent: broadcastAutomationEvent,
    });
  }

  private async executeScrape(row: AutomationRunRow): Promise<void> {
    const payload = parseScheduledScrapePayload(asJsonRecord(row.input));
    if (!payload) {
      await this.failValidation(row.id, "Scheduled scrape payload is invalid");
      return;
    }

    await executeScrapeRun(row.id, payload.target, this.options.createProgressEvent);
  }
}

import type { JsonObject, JsonValue } from "@bao/shared/utils/json";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { createServerLogger } from "../../utils/logger";
import { parseScheduledRunMetadata } from "./automation-run-inputs";
import type { AutomationRunRow } from "./automation-service-contracts";

const automationSchedulerLogger = createServerLogger("automation-run-scheduler");

type SchedulerTimer = ReturnType<typeof setTimeout>;

const asJsonRecord = (value: JsonValue | null | undefined): JsonObject | null =>
  value && typeof value === "object" && !Array.isArray(value) ? value : null;

export class AutomationRunScheduler {
  private readonly scheduledRunTimers = new Map<string, SchedulerTimer>();
  private recoveryInFlight = false;

  constructor(private readonly executeScheduledRun: (runId: string) => Promise<void>) {}

  queue(runId: string, runAt: string): void {
    this.clear(runId);

    const delayMs = Math.max(0, new Date(runAt).getTime() - Date.now());
    const timer = setTimeout(() => {
      this.scheduledRunTimers.delete(runId);
      this.executeScheduledRun(runId).then(
        () => undefined,
        (error) => {
          automationSchedulerLogger.error(
            "[automation] scheduled run execution failed",
            error instanceof Error ? error.message : String(error),
          );
        },
      );
    }, delayMs);
    if (
      typeof timer === "object" &&
      timer !== null &&
      "unref" in timer &&
      typeof timer.unref === "function"
    ) {
      timer.unref();
    }

    this.scheduledRunTimers.set(runId, timer);
  }

  clear(runId: string): void {
    const timer = this.scheduledRunTimers.get(runId);
    if (!timer) {
      return;
    }

    clearTimeout(timer);
    this.scheduledRunTimers.delete(runId);
  }

  async restorePendingRuns(limit: number): Promise<void> {
    if (this.recoveryInFlight) {
      return;
    }

    this.recoveryInFlight = true;
    const pendingRows = await db
      .select()
      .from(automationRuns)
      .where(eq(automationRuns.status, "pending"))
      .limit(limit);

    for (const row of pendingRows satisfies AutomationRunRow[]) {
      const metadata = parseScheduledRunMetadata(asJsonRecord(row.input));
      if (!metadata) {
        automationSchedulerLogger.warn(
          `[automation] skipping pending run without schedule metadata: ${row.id}`,
        );
        continue;
      }

      this.queue(row.id, metadata.runAt);
    }

    this.recoveryInFlight = false;
  }
}

import type { ErrorEnvelope } from "@bao/shared/schemas/error-envelope.schema";
import {
  type RpaRunEvent,
  type RpaRunResult,
  rpaRunEventSchema,
} from "@bao/shared/schemas/rpa-events.schema";
import { DEFAULT_AUTOMATION_SETTINGS } from "@bao/shared/types/settings-defaults";
import { safeParseJson } from "@bao/shared/utils/json";
import { config } from "../../config/env";
import type {
  AutomationScriptExecutionResult,
  RpaScriptExecutionResult,
  RunRpaScriptOptions,
} from "./rpa-runner-contracts";
import { buildErrorEnvelope } from "./rpa-runner-contracts";
import { runAutomationScript } from "./rpa-runner-process";

const MAX_PROTOCOL_ERROR_LINES = 20;

type ParsedProtocolLine =
  | {
      ok: true;
      event: RpaRunEvent;
    }
  | {
      ok: false;
      reason: "invalid_json" | "invalid_event";
    };

type ProtocolCaptureState = {
  events: RpaRunEvent[];
  protocolErrors: string[];
  terminalResult: RpaRunResult | null;
  terminalError: ErrorEnvelope | null;
};

const pushBoundedLine = (target: string[], value: string, limit: number): void => {
  const normalized = value.trim();
  if (normalized.length === 0) {
    return;
  }
  target.push(normalized);
  if (target.length > limit) {
    target.shift();
  }
};

const isLikelyJsonLine = (line: string): boolean => {
  const normalized = line.trim();
  return normalized.startsWith("{") && normalized.endsWith("}");
};

const parseProtocolLine = (line: string): ParsedProtocolLine => {
  const parsedJson = safeParseJson(line);
  if (parsedJson === null) {
    return {
      ok: false,
      reason: "invalid_json",
    };
  }

  const parsedEvent = rpaRunEventSchema.safeParse(parsedJson);
  if (!parsedEvent.success) {
    return {
      ok: false,
      reason: "invalid_event",
    };
  }

  return {
    ok: true,
    event: parsedEvent.data,
  };
};

const createProtocolCaptureState = (): ProtocolCaptureState => ({
  events: [],
  protocolErrors: [],
  terminalResult: null,
  terminalError: null,
});

const pushProtocolError = (
  state: ProtocolCaptureState,
  source: "stdout" | "stderr",
  line: string,
  reason: string,
): void => {
  pushBoundedLine(state.protocolErrors, `${source}:${reason}:${line}`, MAX_PROTOCOL_ERROR_LINES);
};

const handleStdoutLine = (
  line: string,
  state: ProtocolCaptureState,
  onEvent: ((event: RpaRunEvent) => void) | undefined,
): void => {
  if (!isLikelyJsonLine(line)) {
    pushProtocolError(state, "stdout", line, "non_json_line");
    return;
  }
  const parsedLine = parseProtocolLine(line);
  if (!parsedLine.ok) {
    pushProtocolError(state, "stdout", line, parsedLine.reason);
    return;
  }

  const event = parsedLine.event;
  if (event.eventType === "progress") {
    pushProtocolError(state, "stdout", line, "unexpected_progress_event");
    return;
  }
  state.events.push(event);
  onEvent?.(event);
  if (event.eventType === "result") {
    state.terminalResult = event.result;
  } else if (event.eventType === "error") {
    state.terminalError = event.error;
  }
};

const handleStderrLine = (
  line: string,
  state: ProtocolCaptureState,
  onEvent: ((event: RpaRunEvent) => void) | undefined,
): void => {
  if (!isLikelyJsonLine(line)) {
    return;
  }
  const parsedLine = parseProtocolLine(line);
  if (!parsedLine.ok) {
    pushProtocolError(state, "stderr", line, parsedLine.reason);
    return;
  }
  if (parsedLine.event.eventType !== "progress") {
    pushProtocolError(state, "stderr", line, "unexpected_non_progress_event");
    return;
  }
  state.events.push(parsedLine.event);
  onEvent?.(parsedLine.event);
};

const resolveTerminalError = (
  state: ProtocolCaptureState,
  processResult: AutomationScriptExecutionResult,
  timeoutMs: number | undefined,
): ErrorEnvelope | null => {
  let terminalError = state.terminalError;
  if (processResult.timedOut) {
    terminalError = buildErrorEnvelope("AUTOMATION_TIMEOUT", "Automation script timed out", {
      timeoutMs: timeoutMs ?? config.automationScriptTimeoutMs,
    });
  }
  if (!terminalError && processResult.aborted) {
    terminalError = buildErrorEnvelope(
      "AUTOMATION_CANCELLED",
      "Automation script execution was cancelled",
    );
  }
  if (!terminalError && processResult.exitCode !== 0) {
    terminalError = buildErrorEnvelope(
      "AUTOMATION_RUNTIME_ERROR",
      "Automation script exited with an error",
      {
        exitCode: processResult.exitCode,
        stderrTail: processResult.stderrLines,
        stdoutTail: processResult.stdoutLines,
      },
    );
  }
  if (!terminalError && state.protocolErrors.length > 0) {
    terminalError = buildErrorEnvelope(
      "SCRIPT_PROTOCOL_ERROR",
      "Automation script emitted malformed protocol lines",
      {
        protocolErrors: state.protocolErrors,
        stdoutTail: processResult.stdoutLines,
        stderrTail: processResult.stderrLines,
      },
    );
  }
  if (!(terminalError || state.terminalResult)) {
    terminalError = buildErrorEnvelope(
      "SCRIPT_OUTPUT_INVALID",
      "Automation script did not emit a terminal result event",
      { stdoutTail: processResult.stdoutLines },
    );
  }
  return terminalError;
};

/**
 * Runs an RPA script and validates protocol events using shared schemas.
 */
export async function runRpaScript(
  options: RunRpaScriptOptions,
): Promise<RpaScriptExecutionResult> {
  const state = createProtocolCaptureState();

  const processResult = await runAutomationScript({
    scriptId: options.scriptId,
    scriptPath: options.scriptPath,
    scriptInput: {
      ...options.scriptInput,
      settings: options.automationSettings ?? DEFAULT_AUTOMATION_SETTINGS,
    },
    runId: options.executionContext.runId,
    timeoutMs: options.executionContext.timeoutMs,
    signal: options.executionContext.signal,
    outputDir: options.executionContext.outputDir,
    onStdoutLine: (line) => {
      handleStdoutLine(line, state, options.onEvent);
    },
    onStderrLine: (line) => {
      handleStderrLine(line, state, options.onEvent);
    },
  });

  const terminalError = resolveTerminalError(
    state,
    processResult,
    options.executionContext.timeoutMs,
  );

  return {
    result: state.terminalResult,
    error: terminalError,
    events: state.events,
    exitCode: processResult.exitCode,
    timedOut: processResult.timedOut,
    aborted: processResult.aborted,
    executionMs: processResult.executionMs,
    stdoutLines: processResult.stdoutLines,
    stderrLines: processResult.stderrLines,
  };
}

