  markRunCompleted,
  markRunFailed,
  normalizeExecutionResult,
} from "./automation-run-persistence";
import type {
  CreateProgressEvent,
  JobApplyExecutionTracking,
  JobApplyRunPreparation,
} from "./automation-service-contracts";
import type { RpaScriptExecutionResult } from "./rpa-runner-contracts";
import { runRpaScript } from "./rpa-runner-protocol";
import { MS_PER_SECOND } from "@bao/shared/constants/time";

const logger = createServerLogger("automation-job-apply-execution");

type FailureReason = Error | string;

export const createExecutionTracking = (): JobApplyExecutionTracking => ({
  exitCode: null,
  timedOut: false,
  aborted: false,
  executionMs: null,
  errorEnvelope: null,
  terminalPersisted: false,
});

export const markJobApplyRunStarted = async (runId: string): Promise<void> => {
  const startedAt = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      startedAt,
      status: "running",
      progress: 0,
      exitCode: null,
      timedOut: false,
      aborted: false,
      executionMs: null,
      completedAt: null,
      updatedAt: startedAt,
    })
    .where(eq(automationRuns.id, runId));
};

const runJobApplyScript = async (
  preparation: JobApplyRunPreparation,
  tracking: JobApplyExecutionTracking,
): Promise<RpaScriptExecutionResult> => {
  const execution = await runRpaScript({
    scriptId: "job-apply",
    scriptInput: {
      jobUrl: preparation.normalized.jobUrl,
      resume: preparation.resume,
      ...(preparation.resumeFilePath ? { resumeFilePath: preparation.resumeFilePath } : {}),
      coverLetter: preparation.coverLetter
        ? { content: preparation.coverLetter.content || {} }
        : null,
      customAnswers: preparation.normalized.customAnswers,
      selectorMap: preparation.selectorMap,
    },
    executionContext: {
      runId: preparation.runId,
      timeoutMs:
        Number.isFinite(preparation.automationSettings.defaultTimeout) &&
        preparation.automationSettings.defaultTimeout > 0
          ? Math.trunc(preparation.automationSettings.defaultTimeout * MS_PER_SECOND)
          : config.automationScriptTimeoutMs,
      outputDir: preparation.runArtifactDir,
    },
    automationSettings: preparation.automationSettings,
    onEvent: preparation.progressHandler,
  });

  tracking.exitCode = execution.exitCode;
  tracking.timedOut = execution.timedOut;
  tracking.aborted = execution.aborted;
  tracking.executionMs = execution.executionMs;
  tracking.errorEnvelope = execution.error;

  if (execution.error) {
    throw new Error(execution.error.message);
  }

  return execution;
};

const finalizeJobApplySuccess = async (
  preparation: JobApplyRunPreparation,
  tracking: JobApplyExecutionTracking,
  execution: RpaScriptExecutionResult,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const normalizedResult = await normalizeExecutionResult(
    preparation.runId,
    execution,
    API_ERROR_RUN_ID_INVALID,
  );
  await markRunCompleted(
    preparation.runId,
    normalizedResult,
    preparation.automationSettings,
    execution,
  );
  tracking.terminalPersisted = true;

  if (!normalizedResult.success) {
    throw new Error(normalizedResult.error || API_ERROR_JOB_APPLICATION_AUTOMATION_FAILED);
  }

  broadcastAutomationEvent(
    createProgressEvent({
      runId: preparation.runId,
      action: "completed",
      status: "success",
      message: API_MESSAGE_JOB_APPLICATION_AUTOMATION_COMPLETED,
    }),
  );

  const awardXpResult = await settle(
    gamificationService.awardXP(ROUTE_GAMIFICATION_XP.automationCompleted, "automation_success"),
  );
  if (awardXpResult.status === "rejected") {
    logger.warn("XP award failed after job apply automation", {
      err: String(awardXpResult.reason),
    });
  }
};

export const executePreparedJobApplyRun = async (
  preparation: JobApplyRunPreparation,
  tracking: JobApplyExecutionTracking,
  createProgressEvent: CreateProgressEvent,
): Promise<void> => {
  const execution = await runJobApplyScript(preparation, tracking);
  await finalizeJobApplySuccess(preparation, tracking, execution, createProgressEvent);
};

export const handleJobApplyExecutionFailure = async (params: {
  runId: string;
  automationSettings: AutomationSettings;
  tracking: JobApplyExecutionTracking;
  reason: FailureReason;
  createProgressEvent: CreateProgressEvent;
}): Promise<never> => {
  const message = toErrorMessage(params.reason, API_ERROR_JOB_APPLICATION_AUTOMATION_FAILED);
  if (!params.tracking.terminalPersisted) {
    await markRunFailed(params.runId, message, params.automationSettings, {
      exitCode: params.tracking.exitCode,
      timedOut: params.tracking.timedOut,
      aborted: params.tracking.aborted,
      executionMs: params.tracking.executionMs,
      errorEnvelope: params.tracking.errorEnvelope,
    });
  }
  broadcastAutomationEvent(
    params.createProgressEvent({
      runId: params.runId,
      action: "automation",
      status: "error",
      message,
    }),
  );
  throw params.reason instanceof Error ? params.reason : new Error(message);
};

import { settle } from "@bao/shared/utils/promise";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import type {
  EmailDeliveryResult,
  EmailExecutionResult,
  EmailResponseRuntime,
} from "./automation-email-response-contracts";
import { deliverGeneratedEmail, generateEmailResponse } from "./automation-email-response-delivery";
import {
  completeEmailResponseRun,
  failEmailResponseRun,
  markEmailResponseDraftGenerated,
} from "./automation-email-response-updates";
import type { EmailResponseExecutionPayload } from "./automation-run-inputs";
import { buildEmailResponseInput } from "./automation-run-inputs";

export const createEmailResponseRun = async (
  runId: string,
  normalized: EmailResponseExecutionPayload,
  options: { status: "running" | "pending"; scheduledFor?: string } = { status: "running" },
): Promise<void> => {
  const now = new Date().toISOString();
  const totalSteps = normalized.deliverAfterGeneration ? 2 : 1;
  await db.insert(automationRuns).values({
    id: runId,
    type: "email",
    status: options.status,
    jobId: null,
    userId: null,
    input: buildEmailResponseInput(normalized, {
      includeAction: options.status === "pending",
      scheduledFor: options.scheduledFor,
    }),
    progress: 0,
    currentStep: options.status === "running" ? 0 : null,
    totalSteps: options.status === "running" ? totalSteps : null,
    exitCode: 0,
    timedOut: false,
    aborted: false,
    executionMs: null,
    startedAt: options.status === "running" ? now : null,
    createdAt: now,
    updatedAt: now,
  });
};

export const markEmailResponseRunStarted = async (
  runId: string,
  normalized: EmailResponseExecutionPayload,
): Promise<void> => {
  const totalSteps = normalized.deliverAfterGeneration ? 2 : 1;
  const startedAt = new Date().toISOString();
  await db
    .update(automationRuns)
    .set({
      status: "running",
      input: buildEmailResponseInput(normalized, { includeAction: false }),
      progress: 0,
      currentStep: 0,
      totalSteps,
      exitCode: 0,
      timedOut: false,
      aborted: false,
      executionMs: null,
      startedAt,
      completedAt: null,
      updatedAt: startedAt,
    })
    .where(eq(automationRuns.id, runId));
};

export const executeEmailResponseRun = async (
  runId: string,
  normalized: EmailResponseExecutionPayload,
  runtime: EmailResponseRuntime,
): Promise<EmailExecutionResult> => {
  const responseResult = await settle(generateEmailResponse(normalized, runtime.loadAIService));
  if (responseResult.status === "rejected") {
    return failEmailResponseRun(runId, responseResult.reason, runtime);
  }

  if (normalized.deliverAfterGeneration) {
    await markEmailResponseDraftGenerated(
      runId,
      responseResult.value,
      runtime,
      normalized.recipientEmail,
    );
  }

  const noDelivery: EmailDeliveryResult = {
    delivered: false,
    ...(normalized.recipientEmail ? { recipientEmail: normalized.recipientEmail } : {}),
  };
  const deliveryResult: PromiseSettledResult<EmailDeliveryResult> =
    normalized.deliverAfterGeneration
      ? await settle(
          deliverGeneratedEmail(
            normalized,
            responseResult.value.reply,
            runtime.loadEmailTransportConfig,
          ),
        )
      : await settle(Promise.resolve(noDelivery));

  if (deliveryResult.status === "rejected") {
    return failEmailResponseRun(runId, deliveryResult.reason, runtime, responseResult.value);
  }

  await completeEmailResponseRun(
    runId,
    {
      ...responseResult.value,
      delivery: deliveryResult.value,
    },
    runtime,
  );
  return {
    runId,
    status: "success",
    ...responseResult.value,
    delivered: deliveryResult.value.delivered,
    ...(deliveryResult.value.recipientEmail
      ? { recipientEmail: deliveryResult.value.recipientEmail }
      : {}),
    ...(deliveryResult.value.deliveredAt ? { deliveredAt: deliveryResult.value.deliveredAt } : {}),
    ...(deliveryResult.value.messageId ? { messageId: deliveryResult.value.messageId } : {}),
  };
};

import { type RpaRunEvent, rpaProgressEventSchema } from "@bao/shared/schemas/rpa-events.schema";
import { RPA_PROTOCOL_VERSION } from "@bao/shared/schemas/rpa-protocol.schema";
import { createServerLogger } from "../../utils/logger";
import { broadcastAutomationEvent } from "../../ws/automation.ws";
import { persistProgress } from "./automation-run-persistence";
import type { ProgressEventParams } from "./automation-service-contracts";

const automationProgressLogger = createServerLogger("automation-progress-events");

export class AutomationProgressEvents {
  private readonly runEventSequences = new Map<string, number>();

  private nextRunEventSequence(runId: string): number {
    const current = this.runEventSequences.get(runId) ?? 0;
    this.runEventSequences.set(runId, current + 1);
    return current;
  }

  createProgressEvent(params: ProgressEventParams): RpaRunEvent {
    const event = {
      protocolVersion: RPA_PROTOCOL_VERSION,
      runId: params.runId,
      sequence: this.nextRunEventSequence(params.runId),
      timestamp: new Date().toISOString(),
      eventType: "progress",
      action: params.action,
      status: params.status,
      ...(params.message ? { message: params.message } : {}),
      ...(typeof params.step === "number" ? { step: params.step } : {}),
      ...(typeof params.totalSteps === "number" ? { totalSteps: params.totalSteps } : {}),
    } as const;

    const parsed = rpaProgressEventSchema.safeParse(event);
    if (!parsed.success) {
      automationProgressLogger.warn("Invalid progress event shape", {
        params,
        error: parsed.error.flatten(),
      });
      const fallbackEvent: RpaRunEvent = {
        ...event,
        action: "validation_error",
        status: "error",
      };
      return fallbackEvent;
    }
    return parsed.data;
  }

  createProgressHandler(onProgress?: (event: RpaRunEvent) => void): (event: RpaRunEvent) => void {
    return (event: RpaRunEvent): void => {
      if (event.eventType !== "progress") {
        return;
      }

      const normalizedEvent = {
        ...event,
        sequence: this.nextRunEventSequence(event.runId),
        timestamp: new Date().toISOString(),
      } satisfies RpaRunEvent;

      persistProgress(normalizedEvent).then(
        () => undefined,
        (error) => {
          automationProgressLogger.error(
            "Failed to persist progress event",
            error instanceof Error ? error.message : String(error),
          );
        },
      );
      broadcastAutomationEvent(normalizedEvent);
      onProgress?.(normalizedEvent);
    };
  }
}

import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { rmSync } from "node:fs";
import { join } from "node:path";
import { generateId } from "@bao/shared/utils/validation";
import { SCRAPER_DIR } from "../../config/paths";
import { runRpaScript } from "./rpa-runner-protocol";
const NUM_100 = 100;
const NUM_5000 = 5_000;

const TEST_SCRIPT_NAME = "rpa_runner_contract_test.ts";
const TEST_SCRIPT_PATH = join(SCRAPER_DIR, TEST_SCRIPT_NAME);

beforeAll(async () => {
  await Bun.write(
    TEST_SCRIPT_PATH,
    `const payload = JSON.parse((await Bun.stdin.text()) || "{}");
const runId = typeof payload.runId === "string" && payload.runId.length > 0 ? payload.runId : "run-missing";
const protocolVersion =
  typeof payload.protocolVersion === "string" && payload.protocolVersion.length > 0
    ? payload.protocolVersion
    : "1.0";
const mode = typeof payload.mode === "string" ? payload.mode : "success";

if (mode === "success") {
  process.stderr.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 0,
      timestamp: "2026-02-23T00:00:00+00:00",
      eventType: "progress",
      action: "fill_form",
      status: "running",
      step: 1,
      totalSteps: 2,
    })}\\n\`,
  );
  process.stdout.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 1,
      timestamp: "2026-02-23T00:00:01+00:00",
      eventType: "result",
      result: {
        success: true,
        error: null,
        screenshots: [],
        artifacts: [],
        steps: [{ action: "fill_form", status: "ok" }],
      },
    })}\\n\`,
  );
  process.exit(0);
}

if (mode === "malformed") {
  process.stdout.write("not-json\\n");
  process.exit(0);
}

if (mode === "stdout_progress") {
  process.stdout.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 0,
      timestamp: "2026-02-23T00:00:00+00:00",
      eventType: "progress",
      action: "wrong_stream",
      status: "running",
    })}\\n\`,
  );
  process.exit(0);
}

if (mode === "timeout") {
  await Bun.sleep(2_000);
  process.exit(0);
}

if (mode === "browser_missing" || mode === "browser_crash" || mode === "browser_polluted") {
  const failureMode =
    mode === "browser_missing"
      ? "BROWSER_EXECUTABLE_MISSING"
      : mode === "browser_crash"
        ? "BROWSER_PROCESS_CRASHED"
        : "BROWSER_PATH_POLLUTED";
  const causeMessage =
    mode === "browser_missing"
      ? "browserType.launch: Executable doesn't exist at /tmp/chromium"
      : mode === "browser_crash"
        ? "browserType.launch: Target closed (Received signal SIGSEGV)"
        : "browserType.launch: Failed to launch browser from cursor-sandbox-cache";
  process.stdout.write(
    \`\${JSON.stringify({
      protocolVersion,
      runId,
      sequence: 0,
      timestamp: "2026-02-23T00:00:02+00:00",
      eventType: "error",
      error: {
        code: "AUTOMATION_RUNTIME_ERROR",
        message: \`Unable to launch automation browser (\${failureMode}).\`,
        source: "@bao/scraper",
        details: {
          failureMode,
          causeMessage,
          stage: "launch",
        },
      },
    })}\\n\`,
  );
  process.exit(1);
}

process.stderr.write("runtime failure\\n");
process.exit(1);
`,
  );
});

afterAll(() => {
  rmSync(TEST_SCRIPT_PATH, { force: true });
});

const createExecutionContext = (timeoutMs: number): { runId: string; timeoutMs: number } => ({
  runId: generateId(),
  timeoutMs,
});

const registerSuccessCase = (): void => {
  test("parses NDJSON protocol progress/result events", async () => {
    const context = createExecutionContext(NUM_5000);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "success",
      },
      executionContext: context,
    });

    expect(execution.error).toBeNull();
    expect(execution.result?.success).toBe(true);
    expect(execution.events.length).toBe(2);
    expect(execution.events[0]?.eventType).toBe("progress");
    expect(execution.events[1]?.eventType).toBe("result");
  });
};

const registerMalformedPayloadCase = (): void => {
  test("returns protocol error for malformed terminal payload", async () => {
    const context = createExecutionContext(NUM_5000);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "malformed",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.error?.code).toBe("SCRIPT_PROTOCOL_ERROR");
  });
};

const registerRuntimeFailureCase = (): void => {
  test("returns runtime error when script exits non-zero", async () => {
    const context = createExecutionContext(NUM_5000);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "runtime",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");
    expect(execution.exitCode).not.toBe(0);
  });
};

const registerUnexpectedProgressCase = (): void => {
  test("returns protocol error when stdout emits unexpected progress events", async () => {
    const context = createExecutionContext(NUM_5000);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "stdout_progress",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.error?.code).toBe("SCRIPT_PROTOCOL_ERROR");
  });
};

const registerTimeoutCase = (): void => {
  test("returns timeout error when process exceeds timeout", async () => {
    const context = createExecutionContext(NUM_100);
    const execution = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: {
        mode: "timeout",
      },
      executionContext: context,
    });

    expect(execution.result).toBeNull();
    expect(execution.timedOut).toBe(true);
    expect(execution.error?.code).toBe("AUTOMATION_TIMEOUT");
  });
};

const registerBrowserLaunchFailureDifferentiationCase = (): void => {
  test("surfaces distinct browser launch failure modes through protocol error details", async () => {
    const missing = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: { mode: "browser_missing" },
      executionContext: createExecutionContext(NUM_5000),
    });
    const crashed = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: { mode: "browser_crash" },
      executionContext: createExecutionContext(NUM_5000),
    });
    const polluted = await runRpaScript({
      scriptPath: TEST_SCRIPT_NAME,
      scriptInput: { mode: "browser_polluted" },
      executionContext: createExecutionContext(NUM_5000),
    });

    expect(missing.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");
    expect(crashed.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");
    expect(polluted.error?.code).toBe("AUTOMATION_RUNTIME_ERROR");

    expect(missing.error?.details?.failureMode).toBe("BROWSER_EXECUTABLE_MISSING");
    expect(crashed.error?.details?.failureMode).toBe("BROWSER_PROCESS_CRASHED");
    expect(polluted.error?.details?.failureMode).toBe("BROWSER_PATH_POLLUTED");

    expect(missing.error?.details?.failureMode).not.toBe(crashed.error?.details?.failureMode);
    expect(crashed.error?.details?.failureMode).not.toBe(polluted.error?.details?.failureMode);
    expect(polluted.error?.details?.failureMode).not.toBe(missing.error?.details?.failureMode);

    expect(String(missing.error?.details?.causeMessage)).toContain("Executable doesn't exist");
    expect(String(crashed.error?.details?.causeMessage)).toContain("SIGSEGV");
    expect(String(polluted.error?.details?.causeMessage)).toContain("cursor-sandbox-cache");

    expect(missing.error?.message).toContain("BROWSER_EXECUTABLE_MISSING");
    expect(crashed.error?.message).toContain("BROWSER_PROCESS_CRASHED");
    expect(polluted.error?.message).toContain("BROWSER_PATH_POLLUTED");
  });
};

describe("runRpaScript", () => {
  registerSuccessCase();
  registerMalformedPayloadCase();
  registerRuntimeFailureCase();
  registerUnexpectedProgressCase();
  registerTimeoutCase();
  registerBrowserLaunchFailureDifferentiationCase();
});

import {
  AI_PROVIDER_CATALOG,
  AI_PROVIDER_DEFAULT,
  AI_PROVIDER_ID_LIST,
  normalizeAIRouting,
} from "@bao/shared/constants/ai-provider";
import { API_MESSAGE_AI_NO_PROVIDERS } from "@bao/shared/constants/api-messages";
import type { AIProviderDiagnostic, AIProviderStatus, AIProviderType } from "@bao/shared/types/ai";
import type { AIProviderDiagnostics } from "@bao/shared/types/settings-contracts";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import type { settings as settingsTable } from "../../db/schema/settings";
import { decryptProviderKeys } from "../../utils/settings-decrypt";
import { AIService } from "./ai-service";

type SettingsRow = typeof settingsTable.$inferSelect;

const resolveKnownProvider = (value?: string | null): (typeof AI_PROVIDER_ID_LIST)[number] =>
  AI_PROVIDER_ID_LIST.find((provider) => provider === value) ?? AI_PROVIDER_DEFAULT;

interface AIControlPlaneProviderRow {
  id: (typeof AI_PROVIDER_CATALOG)[number]["id"];
  nameKey: string;
  descriptionKey: string;
  iconId: (typeof AI_PROVIDER_CATALOG)[number]["iconId"];
  models: string[];
  available: boolean;
  health: "healthy" | "degraded" | "down" | "unconfigured";
  selectedModel?: string;
  diagnosticCode?: AIProviderStatus["diagnosticCode"];
  availableModels?: readonly string[];
  error?: string;
}

/**
 * Shared AI control-plane payload consumed by settings and provider-discovery routes.
 */
export interface AIControlPlaneState {
  aiRouting: ReturnType<typeof normalizeAIRouting>;
  configuredProviders: ReturnType<AIService["getConfiguredProviders"]>;
  error?: string;
  preferredModel: string | null;
  preferredProvider: SettingsRow["preferredProvider"];
  providerDiagnostics?: AIProviderDiagnostics;
  providers: AIControlPlaneProviderRow[];
}

const toProviderDiagnosticEntry = (status: AIProviderStatus): AIProviderDiagnostic => ({
  provider: status.provider,
  code: status.diagnosticCode ?? (status.available ? "healthy" : "error"),
  checkedAt: new Date(status.lastCheck ?? Date.now()).toISOString(),
  endpoint: status.endpoint,
  selectedModel: status.selectedModel,
  availableModels: status.availableModels,
  message: status.error,
});

const buildProviderDiagnostics = (providerStatuses: AIProviderStatus[]): AIProviderDiagnostics => {
  const statusByProvider = new Map(
    providerStatuses.map((status) => [status.provider, status] as const),
  );

  return Object.fromEntries(
    AI_PROVIDER_CATALOG.map((provider) => {
      const status = statusByProvider.get(provider.id);
      return [
        provider.id,
        status
          ? toProviderDiagnosticEntry(status)
          : {
              provider: provider.id,
              code: "unconfigured",
              checkedAt: new Date(0).toISOString(),
            },
      ];
    }),
  );
};

const hasConfiguredProvider = (row: SettingsRow, providerId: AIProviderType): boolean => {
  if (providerId === "local") {
    return typeof row.localModelEndpoint === "string" && row.localModelEndpoint.trim().length > 0;
  }
  if (providerId === "gemini") {
    return typeof row.geminiApiKey === "string" && row.geminiApiKey.trim().length > 0;
  }
  if (providerId === "openai") {
    return typeof row.openaiApiKey === "string" && row.openaiApiKey.trim().length > 0;
  }
  if (providerId === "claude") {
    return typeof row.claudeApiKey === "string" && row.claudeApiKey.trim().length > 0;
  }
  return typeof row.huggingfaceToken === "string" && row.huggingfaceToken.trim().length > 0;
};

const resolveFallbackSelectedModel = (
  row: SettingsRow,
  providerId: AIProviderType,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): string | undefined => {
  if (providerId === "local") {
    return row.localModelName ?? aiRouting.chat.model;
  }
  if (aiRouting.chat.provider === providerId) {
    return aiRouting.chat.model ?? row.preferredModel ?? undefined;
  }
};

const resolveFallbackModels = (
  row: SettingsRow,
  providerId: AIProviderType,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): string[] => {
  const catalogProvider = AI_PROVIDER_CATALOG.find((provider) => provider.id === providerId);
  const selectedModel = resolveFallbackSelectedModel(row, providerId, aiRouting);
  return selectedModel
    ? [
        selectedModel,
        ...(catalogProvider?.modelHints.filter((hint) => hint !== selectedModel) ?? []),
      ]
    : [...(catalogProvider?.modelHints ?? [])];
};

const buildFallbackProviderRows = (
  row: SettingsRow,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): AIControlPlaneProviderRow[] =>
  AI_PROVIDER_CATALOG.map((provider) => {
    const configured = hasConfiguredProvider(row, provider.id);
    const selectedModel = resolveFallbackSelectedModel(row, provider.id, aiRouting);

    return {
      id: provider.id,
      nameKey: provider.nameKey,
      descriptionKey: provider.descriptionKey,
      iconId: provider.iconId,
      models: resolveFallbackModels(row, provider.id, aiRouting),
      available: false,
      health: configured ? "degraded" : "unconfigured",
      selectedModel,
      ...(provider.id === "local" &&
      typeof row.localModelEndpoint === "string" &&
      row.localModelEndpoint.trim().length > 0
        ? {
            availableModels: [row.localModelName].filter((value): value is string =>
              Boolean(value),
            ),
          }
        : {}),
    };
  });

const buildFallbackProviderDiagnostics = (
  row: SettingsRow,
  aiRouting: ReturnType<typeof normalizeAIRouting>,
  error: string,
): AIProviderDiagnostics => {
  const checkedAt = new Date().toISOString();

  return Object.fromEntries(
    AI_PROVIDER_CATALOG.map((provider) => {
      const configured = hasConfiguredProvider(row, provider.id);
      const selectedModel = resolveFallbackSelectedModel(row, provider.id, aiRouting);
      const localEndpoint =
        provider.id === "local" &&
        typeof row.localModelEndpoint === "string" &&
        row.localModelEndpoint.trim().length > 0
          ? row.localModelEndpoint.trim()
          : undefined;

      return [
        provider.id,
        {
          provider: provider.id,
          code: configured ? "error" : "unconfigured",
          checkedAt,
          selectedModel,
          ...(localEndpoint ? { endpoint: localEndpoint } : {}),
          ...(configured ? { message: error } : {}),
        } satisfies AIProviderDiagnostic,
      ];
    }),
  );
};

const resolveConfiguredProvidersFromRow = (
  row: SettingsRow,
): ReturnType<AIService["getConfiguredProviders"]> =>
  AI_PROVIDER_CATALOG.filter((provider) => hasConfiguredProvider(row, provider.id)).map(
    (provider) => provider.id,
  );

const buildFallbackControlPlaneState = (row: SettingsRow, error: string): AIControlPlaneState => {
  const aiRouting = normalizeAIRouting(
    row.aiRouting,
    resolveKnownProvider(row.preferredProvider),
    row.preferredModel,
  );

  return {
    aiRouting,
    configuredProviders: resolveConfiguredProvidersFromRow(row),
    preferredProvider: aiRouting.chat.provider,
    preferredModel: aiRouting.chat.model ?? row.preferredModel,
    providers: buildFallbackProviderRows(row, aiRouting),
    providerDiagnostics: buildFallbackProviderDiagnostics(row, aiRouting, error),
    ...(error ? { error } : {}),
  };
};

const buildProviderRows = (
  providerStatuses: AIProviderStatus[],
  aiRouting: ReturnType<typeof normalizeAIRouting>,
): AIControlPlaneProviderRow[] => {
  const statusByProvider = new Map(
    providerStatuses.map((status) => [status.provider, status] as const),
  );

  return AI_PROVIDER_CATALOG.map((provider) => {
    const status = statusByProvider.get(provider.id);
    const selectedModel = status?.selectedModel ?? aiRouting.chat.model;
    const models = selectedModel
      ? [selectedModel, ...provider.modelHints.filter((hint) => hint !== selectedModel)]
      : [...provider.modelHints];

    return {
      id: provider.id,
      nameKey: provider.nameKey,
      descriptionKey: provider.descriptionKey,
      iconId: provider.iconId,
      models,
      available: status?.available ?? false,
      health: status?.health ?? "unconfigured",
      selectedModel,
      diagnosticCode: status?.diagnosticCode,
      availableModels: status?.availableModels,
      error: status?.error,
    };
  });
};

/**
 * Builds the canonical AI control-plane state from one persisted settings row.
 */
export async function buildAIControlPlaneState(
  settingsRow: SettingsRow,
): Promise<AIControlPlaneState> {
  const decryptedKeys = decryptProviderKeys(settingsRow);
  const row = { ...settingsRow, ...decryptedKeys };
  const aiRouting = normalizeAIRouting(
    row.aiRouting,
    resolveKnownProvider(row.preferredProvider),
    row.preferredModel,
  );
  const aiServiceResult = await settle(Promise.resolve(AIService.fromSettings(row)));
  if (aiServiceResult.status !== "fulfilled") {
    return buildFallbackControlPlaneState(
      row,
      toErrorMessage(aiServiceResult.reason, API_MESSAGE_AI_NO_PROVIDERS),
    );
  }

  const aiService = aiServiceResult.value;
  const providerStatusesResult = await settle(aiService.getAvailableProviders());
  if (providerStatusesResult.status !== "fulfilled") {
    return buildFallbackControlPlaneState(
      row,
      toErrorMessage(providerStatusesResult.reason, API_MESSAGE_AI_NO_PROVIDERS),
    );
  }

  const providerStatuses = providerStatusesResult.value;

  return {
    aiRouting,
    configuredProviders: aiService.getConfiguredProviders(),
    preferredProvider: aiRouting.chat.provider,
    preferredModel: aiRouting.chat.model ?? row.preferredModel,
    providerDiagnostics: buildProviderDiagnostics(providerStatuses),
    providers: buildProviderRows(providerStatuses, aiRouting),
  };
}

