import Anthropic from "@anthropic-ai/sdk";
import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import type { AIResponse, GenerateOptions } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { BaseAIProvider } from "./provider-interface";
const NUM_4096 = 4096;
const RATIO_0_7 = 0.7;

/**
 * Anthropic Claude AI Provider
 */
export class ClaudeProvider extends BaseAIProvider {
  name = "claude" as const;
  model: string;
  private client: Anthropic;

  constructor(apiKey: string, model = "claude-sonnet-4-5-20250929") {
    super(apiKey);
    this.model = model;
    this.client = new Anthropic({ apiKey });
  }

  private resolveModel(options?: GenerateOptions): string {
    return typeof options?.model === "string" && options.model.trim().length > 0
      ? options.model.trim()
      : this.model;
  }

  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const startTime = Date.now();
    const model = this.resolveModel(options);
    const responseResult = await settle(
      this.client.messages.create({
        model,
        max_tokens: options?.maxTokens ?? NUM_4096,
        temperature: options?.temperature ?? RATIO_0_7,
        system: options?.systemPrompt,
        messages: [
          {
            role: "user",
            content: prompt,
          },
        ],
      }),
    );
    if (responseResult.status === "rejected") {
      return {
        id: this.generateId(),
        provider: this.name,
        model,
        content: "",
        error: toErrorMessage(responseResult.reason),
        timing: this.createTimingMetrics(startTime),
      };
    }
    const response = responseResult.value;
    const text = response.content
      .filter((block): block is Anthropic.TextBlock => block.type === "text")
      .map((block) => block.text)
      .join("");

    return {
      id: this.generateId(),
      provider: this.name,
      model,
      content: text,
      usage: {
        inputTokens: response.usage.input_tokens,
        outputTokens: response.usage.output_tokens,
      },
      timing: this.createTimingMetrics(startTime),
    };
  }

  async *stream(prompt: string, options?: GenerateOptions): AsyncGenerator<string> {
    const model = this.resolveModel(options);
    const streamResult = await settle(
      Promise.resolve(
        this.client.messages.stream({
          model,
          max_tokens: options?.maxTokens ?? NUM_4096,
          temperature: options?.temperature ?? RATIO_0_7,
          system: options?.systemPrompt,
          messages: [
            {
              role: "user",
              content: prompt,
            },
          ],
        }),
      ),
    );
    if (streamResult.status === "rejected") {
      throw new Error(`${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(streamResult.reason)}`);
    }
    const stream = streamResult.value;

    const iterator = stream[Symbol.asyncIterator]();
    const emitTextEvents = async function* (): AsyncGenerator<string> {
      const nextEventResult = await settle(iterator.next());
      if (nextEventResult.status === "rejected") {
        throw new Error(
          `${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(nextEventResult.reason)}`,
        );
      }
      const nextEvent = nextEventResult.value;
      if (nextEvent.done) {
        return;
      }
      const event = nextEvent.value;
      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
        yield event.delta.text;
      }
      yield* emitTextEvents();
    };

    yield* emitTextEvents();
  }

  async isAvailable(): Promise<boolean> {
    // Make a minimal request to verify API key
    const model = this.model;
    return (
      (
        await settle(
          this.client.messages.create({
            model,
            max_tokens: 10,
            messages: [{ role: "user", content: "test" }],
          }),
        )
      ).status === "fulfilled"
    );
  }
}

import {
  AI_CHAT_CONTEXT_AUTOMATION_RUNS_LIMIT,
  AI_CHAT_CONTEXT_AVAILABLE_RESUMES_LIMIT,
  AI_CHAT_CONTEXT_INTERVIEW_SESSIONS_LIMIT,
  AI_CHAT_CONTEXT_PORTFOLIO_PROJECTS_LIMIT,
  AI_CHAT_CONTEXT_SAVED_JOBS_LIMIT,
  AI_CHAT_CONTEXT_SKILL_MAPPINGS_LIMIT,
  AI_CHAT_HISTORY_FETCH_LIMIT,
} from "@bao/shared/constants/ai-chat";
import { resolveBrandSettings } from "@bao/shared/constants/branding";
import type { AIChatContextDomain, ChatMessage } from "@bao/shared/types/ai";
import type { BrandSettings } from "@bao/shared/types/settings-contracts";
import { DEFAULT_PROFILE_ID } from "@bao/shared/types/settings-defaults";
import { settle } from "@bao/shared/utils/promise";
import { desc, eq } from "drizzle-orm";
import { db } from "../../db/client";
import { automationRuns } from "../../db/schema/automation-runs";
import { chatHistory } from "../../db/schema/chat-history";
import { interviewSessions } from "../../db/schema/interviews";
import { jobs, savedJobs } from "../../db/schema/jobs";
import { portfolioProjects } from "../../db/schema/portfolios";
import { resumes } from "../../db/schema/resumes";
import { skillMappings } from "../../db/schema/skill-mappings";
import { userProfile } from "../../db/schema/user";
import { getContextManagerFollowUps } from "./context-manager-followups";
import { buildDomainSystemPrompts, GAMING_INDUSTRY_CONTEXT } from "./prompts-system";

interface ConversationContext {
  systemPrompt: string;
  messages: Array<Pick<ChatMessage, "role" | "content">>;
}

const AUTOMATION_DOMAIN_PATTERN =
  /\b(automate|automation|rpa|auto[- ]?apply|fill.*form|run.*bot|bot.*apply)\b/i;
const RESUME_DOMAIN_PATTERN = /\b(resume|cv|bullet|experience|education|summary)\b/;
const JOB_SEARCH_DOMAIN_PATTERN = /\b(job|apply|salary|remote|position|company|hiring|opening)\b/;
const INTERVIEW_DOMAIN_PATTERN = /\b(interview|question|answer|practice|mock|prepare)\b/;
const PORTFOLIO_DOMAIN_PATTERN = /\b(portfolio|project|showcase|demo|sample)\b/;
const SKILLS_DOMAIN_PATTERN = /\b(skill|mapping|transfer|learn|career\s*path|gap)\b/;
const DOMAIN_PATTERN_ORDER: Array<[AIChatContextDomain, RegExp]> = [
  ["automation", AUTOMATION_DOMAIN_PATTERN],
  ["resume", RESUME_DOMAIN_PATTERN],
  ["job_search", JOB_SEARCH_DOMAIN_PATTERN],
  ["interview", INTERVIEW_DOMAIN_PATTERN],
  ["portfolio", PORTFOLIO_DOMAIN_PATTERN],
  ["skills", SKILLS_DOMAIN_PATTERN],
];

export class ConversationContextManager {
  private isChatRole(value: string): value is ChatMessage["role"] {
    return value === "user" || value === "assistant" || value === "system";
  }

  /**
   * Auto-detect domain from message content
   */
  inferDomain(message: string): AIChatContextDomain {
    const lower = message.toLowerCase();
    return DOMAIN_PATTERN_ORDER.find(([, pattern]) => pattern.test(lower))?.[0] ?? "general";
  }

  /**
   * Build full context for AI call with conversation history and domain-specific data
   */
  async buildContext(
    sessionId: string,
    currentMessage: string,
    preferredDomain?: AIChatContextDomain,
    runtimeBrand?: BrandSettings | null,
  ): Promise<ConversationContext> {
    const domain = preferredDomain ?? this.inferDomain(currentMessage);
    const messages = await this.loadConversationMessages(sessionId, currentMessage);
    const profile = await this.loadDefaultProfile();
    const domainContext = await this.loadDomainContext(domain);
    const systemPrompt = this.buildSystemPrompt(
      domain,
      profile,
      domainContext,
      runtimeBrand ?? resolveBrandSettings(undefined),
    );
    return { systemPrompt, messages };
  }

  /**
   * Loads recent conversation history and appends the current user message once.
   */
  private async loadConversationMessages(
    sessionId: string,
    currentMessage: string,
  ): Promise<Array<Pick<ChatMessage, "role" | "content">>> {
    const history = await db
      .select()
      .from(chatHistory)
      .where(eq(chatHistory.sessionId, sessionId))
      .orderBy(desc(chatHistory.timestamp))
      .limit(AI_CHAT_HISTORY_FETCH_LIMIT);

    const messages: Array<Pick<ChatMessage, "role" | "content">> = history
      .reverse()
      .flatMap((msg) =>
        this.isChatRole(msg.role)
          ? [
              {
                role: msg.role,
                content: msg.content,
              },
            ]
          : [],
      );

    const lastMessage = messages[messages.length - 1];
    const hasCurrentMessageAtTail =
      lastMessage?.role === "user" && lastMessage.content === currentMessage;
    if (!hasCurrentMessageAtTail) {
      messages.push({ role: "user", content: currentMessage });
    }

    return messages;
  }

  /**
   * Loads the default user profile row when available.
   */
  private async loadDefaultProfile() {
    const profileRows = await db
      .select()
      .from(userProfile)
      .where(eq(userProfile.id, DEFAULT_PROFILE_ID));
    return profileRows[0] ?? null;
  }

  /**
   * Builds the final system prompt from the selected domain and user context.
   */
  private buildSystemPrompt(
    domain: AIChatContextDomain,
    profile: typeof userProfile.$inferSelect | null,
    domainContext: string | null,
    runtimeBrand: BrandSettings,
  ): string {
    const domainSystemPrompts = buildDomainSystemPrompts(runtimeBrand);
    const userContext = profile
      ? `\n\nUser Context:\nName: ${profile.name || "Not set"}\nCurrent Role: ${profile.currentRole || "Not set"}\nYears Experience: ${profile.yearsExperience || "Not set"}\nLocation: ${profile.location || "Not set"}`
      : "";
    const relevantData = domainContext ? `\n\nRelevant Data:\n${domainContext}` : "";
    return `${domainSystemPrompts[domain] || domainSystemPrompts.general}${userContext}${relevantData}\n\n${GAMING_INDUSTRY_CONTEXT}`;
  }

  /**
   * Load domain-specific data from DB
   */
  private async loadDomainContext(domain: AIChatContextDomain): Promise<string | null> {
    const loader = this.getDomainContextLoader(domain);
    if (!loader) {
      return null;
    }
    const contextResult = await settle(loader());

    if (contextResult.status === "rejected") {
      return null;
    }

    return contextResult.value;
  }

  private getDomainContextLoader(
    domain: AIChatContextDomain,
  ): (() => Promise<string | null>) | null {
    const loaders = {
      automation: () => this.loadAutomationContext(),
      interview: () => this.loadInterviewContext(),
      job_search: () => this.loadJobSearchContext(),
      portfolio: () => this.loadPortfolioContext(),
      resume: () => this.loadResumeContext(),
      skills: () => this.loadSkillsContext(),
    } as const;
    return domain === "general" ? null : loaders[domain];
  }

  private async loadResumeContext(): Promise<string | null> {
    const defaultResume = await db.select().from(resumes).limit(1);
    if (defaultResume.length === 0) {
      return null;
    }
    const resume = defaultResume[0];
    return `User's Resume: "${resume.name}"\nSummary: ${resume.summary || "Not set"}\nSkills: ${JSON.stringify(resume.skills || {})}`;
  }

  private async loadJobSearchContext(): Promise<string | null> {
    const saved = await db
      .select({ title: jobs.title, company: jobs.company })
      .from(savedJobs)
      .leftJoin(jobs, eq(savedJobs.jobId, jobs.id))
      .limit(AI_CHAT_CONTEXT_SAVED_JOBS_LIMIT);
    if (saved.length === 0) {
      return null;
    }
    return `Saved Jobs:\n${saved.map((entry) => `- ${entry.title} at ${entry.company}`).join("\n")}`;
  }

  private async loadInterviewContext(): Promise<string | null> {
    const sessions = await db
      .select()
      .from(interviewSessions)
      .orderBy(desc(interviewSessions.createdAt))
      .limit(AI_CHAT_CONTEXT_INTERVIEW_SESSIONS_LIMIT);
    if (sessions.length === 0) {
      return null;
    }
    return `Recent Interview Sessions: ${sessions.length} completed`;
  }

  private async loadPortfolioContext(): Promise<string | null> {
    const projects = await db
      .select()
      .from(portfolioProjects)
      .limit(AI_CHAT_CONTEXT_PORTFOLIO_PROJECTS_LIMIT);
    if (projects.length === 0) {
      return null;
    }
    return `Portfolio Projects:\n${projects.map((project) => `- ${project.title}: ${project.technologies?.join(", ") || "No tech listed"}`).join("\n")}`;
  }

  private async loadSkillsContext(): Promise<string | null> {
    const mappings = await db
      .select()
      .from(skillMappings)
      .limit(AI_CHAT_CONTEXT_SKILL_MAPPINGS_LIMIT);
    if (mappings.length === 0) {
      return null;
    }
    return `Skill Mappings:\n${mappings.map((mapping) => `- ${mapping.gameExpression} → ${mapping.transferableSkill}`).join("\n")}`;
  }

  private async loadAutomationContext(): Promise<string | null> {
    const recentRuns = await db
      .select()
      .from(automationRuns)
      .orderBy(desc(automationRuns.createdAt))
      .limit(AI_CHAT_CONTEXT_AUTOMATION_RUNS_LIMIT);
    const availableResumes = await db
      .select()
      .from(resumes)
      .limit(AI_CHAT_CONTEXT_AVAILABLE_RESUMES_LIMIT);
    const runLines = recentRuns.map(
      (run) =>
        `- [${run.status}] ${run.type} (${run.createdAt})${run.error ? ` Error: ${run.error}` : ""}`,
    );
    const resumeLines = availableResumes.map((resume) => `- "${resume.name}" (ID: ${resume.id})`);
    const parts = [
      ...(runLines.length > 0
        ? [`Recent Automation Runs (${recentRuns.length}):`, ...runLines]
        : []),
      ...(resumeLines.length > 0 ? ["\nAvailable Resumes:", ...resumeLines] : []),
    ];
    return parts.length > 0 ? parts.join("\n") : null;
  }

  /**
   * Generate follow-up suggestions based on domain and last response
   */
  generateFollowUps(domain: AIChatContextDomain): string[] {
    return getContextManagerFollowUps(domain);
  }
}

export const contextManager = new ConversationContextManager();

import { DECIMAL_RADIX } from "@bao/shared/constants/client-config";
const NUM_3 = 3;

const TEST_AI_MAX_QUESTION_COUNT = 12;
const EXACT_QUESTION_COUNT_PATTERN = /exactly\s+(\d+)\s+questions/i;
const GENERATE_QUESTION_COUNT_PATTERN = /generate\s+(\d+)\s+interview questions/i;
const SUMMARY_BULLET_PATTERN_TEMPLATE = String.raw`^-\s+%LABEL%:\s*(.+)$`;
const PROMPT_HIGHLIGHT_SPLIT_PATTERN = /[;,]/u;

type DeterministicInterviewQuestionType =
  | "intro"
  | "behavioral"
  | "technical"
  | "studio-specific"
  | "closing";

type DeterministicInterviewPromptContext = {
  studio: string;
  role: string;
  company: string;
  experienceHighlight: string;
  projectHighlight: string;
  technicalHighlight: string;
  focusArea: string;
  hiringSignal: string;
  pitchAngle: string;
};

const parseQuestionCount = (prompt: string): number => {
  const exactMatch = prompt.match(EXACT_QUESTION_COUNT_PATTERN);
  const generateMatch = prompt.match(GENERATE_QUESTION_COUNT_PATTERN);
  const matchedValue = exactMatch?.[1] ?? generateMatch?.[1];
  const parsed = matchedValue ? Number.parseInt(matchedValue, DECIMAL_RADIX) : Number.NaN;
  if (!Number.isFinite(parsed) || parsed < 1) {
    return NUM_3;
  }
  return Math.min(parsed, TEST_AI_MAX_QUESTION_COUNT);
};

const parseIncludeFlag = (prompt: string, label: string, fallback: boolean): boolean => {
  const matcher = new RegExp(`${label}\\s*=\\s*(true|false)`, "i");
  const matched = prompt.match(matcher)?.[1];
  if (matched === "true") return true;
  if (matched === "false") return false;
  return fallback;
};

const escapePattern = (value: string): string =>
  value.replaceAll(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);

const extractPromptLineValue = (prompt: string, label: string): string => {
  const matcher = new RegExp(`^${escapePattern(label)}:\\s*(.+)$`, "im");
  return prompt.match(matcher)?.[1]?.trim() ?? "";
};

const extractPromptBulletValue = (prompt: string, label: string): string => {
  const pattern = SUMMARY_BULLET_PATTERN_TEMPLATE.replace("%LABEL%", escapePattern(label));
  return prompt.match(new RegExp(pattern, "im"))?.[1]?.trim() ?? "";
};

const extractPromptHighlights = (value: string): string[] =>
  value
    .split(PROMPT_HIGHLIGHT_SPLIT_PATTERN)
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0 && entry.toLowerCase() !== "not specified")
    .slice(0, NUM_3);

const buildPromptContext = (prompt: string): DeterministicInterviewPromptContext => {
  const studio =
    extractPromptLineValue(prompt, "Studio") || extractPromptBulletValue(prompt, "Name");
  const role =
    extractPromptLineValue(prompt, "Role") || extractPromptBulletValue(prompt, "Job title");
  const company = extractPromptBulletValue(prompt, "Company") || studio;
  const experienceHighlights = extractPromptHighlights(
    extractPromptBulletValue(prompt, "Experience highlights") ||
      extractPromptBulletValue(prompt, "Current role"),
  );
  const projectHighlights = extractPromptHighlights(
    extractPromptBulletValue(prompt, "Project highlights") ||
      extractPromptBulletValue(prompt, "Featured work"),
  );
  const technicalHighlights = extractPromptHighlights(
    extractPromptBulletValue(prompt, "Technical skills") ||
      extractPromptBulletValue(prompt, "Technologies"),
  );
  const focusAreas = extractPromptHighlights(
    extractPromptBulletValue(prompt, "Interview focus areas"),
  );
  const hiringSignals = extractPromptHighlights(extractPromptBulletValue(prompt, "Hiring signals"));
  const candidatePitchAngles = extractPromptHighlights(
    extractPromptBulletValue(prompt, "Candidate pitch angles"),
  );

  return {
    studio,
    role,
    company,
    experienceHighlight: experienceHighlights[0] ?? "recent game-industry delivery work",
    projectHighlight: projectHighlights[0] ?? "a player-facing system you shipped",
    technicalHighlight: technicalHighlights[0] ?? "your strongest technical stack",
    focusArea: focusAreas[0] ?? "cross-functional delivery",
    hiringSignal: hiringSignals[0] ?? "shipping velocity and collaborative execution",
    pitchAngle: candidatePitchAngles[0] ?? "player impact, ownership, and measurable outcomes",
  };
};

const buildQuestionText = (
  type: DeterministicInterviewQuestionType,
  context: DeterministicInterviewPromptContext,
): string => {
  switch (type) {
    case "intro":
      return `Your background highlights ${context.experienceHighlight}. How does that prepare you for the ${context.role} role at ${context.company}?`;
    case "behavioral":
      return `Tell me about a time you aligned design, production, or QA partners to deliver ${context.focusArea} work with clear player impact.`;
    case "technical":
      return `Walk me through a system from ${context.projectHighlight} where you used ${context.technicalHighlight} in a way that would transfer directly to the ${context.role} scope at ${context.company}.`;
    case "studio-specific":
      return `This opportunity signals ${context.hiringSignal}. How would you ramp up in your first 30 days and prove the ${context.pitchAngle} angle is real?`;
    case "closing":
      return `What is the strongest evidence from your resume, cover letter, or portfolio that you are ready for ${context.role} at ${context.company} right now?`;
    default: {
      const unreachable: never = type;
      return `How would you contribute as ${context.role} at ${context.company}? (${String(unreachable)})`;
    }
  }
};

const buildFollowUps = (
  type: DeterministicInterviewQuestionType,
  context: DeterministicInterviewPromptContext,
): string[] => {
  switch (type) {
    case "intro":
      return [
        `Which result from ${context.projectHighlight} is most relevant to ${context.company}?`,
        "How did you validate the outcome with teammates or players?",
      ];
    case "behavioral":
      return [
        "What disagreement or tradeoff made the collaboration difficult?",
        "How did you know the partnership was working?",
      ];
    case "technical":
      return [
        `What constraints shaped your use of ${context.technicalHighlight}?`,
        "What telemetry or quality checks told you the solution was healthy?",
      ];
    case "studio-specific":
      return [
        `Which stakeholder would you meet first to support ${context.focusArea}?`,
        "What deliverable would you aim to own by the end of the first sprint?",
      ];
    case "closing":
      return [
        "Which accomplishment best proves that claim?",
        "Why does this studio context fit where you want to grow next?",
      ];
    default: {
      const unreachable: never = type;
      return [`What else should we cover for ${context.role}? (${String(unreachable)})`];
    }
  }
};

export const buildDeterministicQuestionSet = (prompt: string): string => {
  const questionCount = parseQuestionCount(prompt);
  const includeTechnical = parseIncludeFlag(prompt, "technical", true);
  const includeBehavioral = parseIncludeFlag(prompt, "behavioral", true);
  const includeStudioSpecific = parseIncludeFlag(prompt, "studio-specific", true);
  const promptContext = buildPromptContext(prompt);
  const candidateTypes: DeterministicInterviewQuestionType[] = ["intro"];
  if (includeBehavioral) {
    candidateTypes.push("behavioral");
  }
  if (includeTechnical) {
    candidateTypes.push("technical");
  }
  if (includeStudioSpecific) {
    candidateTypes.push("studio-specific");
  }
  candidateTypes.push("closing");

  const questions = [];
  for (let index = 0; index < questionCount; index += 1) {
    const position = index + 1;
    const type = candidateTypes[index % candidateTypes.length] ?? "behavioral";
    questions.push({
      id: `test-q${position}`,
      question: buildQuestionText(type, promptContext),
      type,
      followUps: buildFollowUps(type, promptContext),
      expectedDuration: 90,
      difficulty: type === "technical" ? "hard" : "medium",
      tags: ["deterministic", "test"],
    });
  }

  return JSON.stringify(questions);
};

