import { API_ERROR_AI_STREAMING_FAILED } from "@bao/shared/constants/api-errors";
import type { AIResponse, GenerateOptions } from "@bao/shared/types/ai";
import { toErrorMessage } from "@bao/shared/utils/error-helpers";
import { settle } from "@bao/shared/utils/promise";
import { type GenerativeModel, GoogleGenerativeAI } from "@google/generative-ai";
import { BaseAIProvider } from "./provider-interface";
const NUM_2048 = 2048;
const NUM_40 = 40;
const RATIO_0_7 = 0.7;
const RATIO_0_95 = 0.95;

/**
 * Google Gemini AI Provider
 */
export class GeminiProvider extends BaseAIProvider {
  name = "gemini" as const;
  model: string;
  private client: GoogleGenerativeAI;
  private generativeModel: GenerativeModel;

  constructor(apiKey: string, model = "gemini-2.0-flash-exp") {
    super(apiKey);
    this.model = model;
    this.client = new GoogleGenerativeAI(apiKey);
    this.generativeModel = this.client.getGenerativeModel({ model: this.model });
  }

  private resolveModel(options?: GenerateOptions): string {
    return typeof options?.model === "string" && options.model.trim().length > 0
      ? options.model.trim()
      : this.model;
  }

  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const startTime = Date.now();
    const model = this.resolveModel(options);
    const generativeModel =
      model === this.model ? this.generativeModel : this.client.getGenerativeModel({ model });
    const generationConfig = {
      temperature: options?.temperature ?? RATIO_0_7,
      maxOutputTokens: options?.maxTokens ?? NUM_2048,
      topP: options?.topP ?? RATIO_0_95,
      topK: options?.topK ?? NUM_40,
    };

    let fullPrompt = prompt;
    if (options?.systemPrompt) {
      fullPrompt = `${options.systemPrompt}\n\n${prompt}`;
    }

    const resultResponse = await settle(
      generativeModel.generateContent({
        contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
        generationConfig,
      }),
    );
    if (resultResponse.status === "rejected") {
      return {
        id: this.generateId(),
        provider: this.name,
        model,
        content: "",
        error: toErrorMessage(resultResponse.reason),
        timing: this.createTimingMetrics(startTime),
      };
    }

    const response = resultResponse.value.response;
    const text = response.text();
    const usage = response.usageMetadata
      ? {
          inputTokens: response.usageMetadata.promptTokenCount || 0,
          outputTokens: response.usageMetadata.candidatesTokenCount || 0,
        }
      : undefined;

    return {
      id: this.generateId(),
      provider: this.name,
      model,
      content: text,
      usage,
      timing: this.createTimingMetrics(startTime),
    };
  }

  async *stream(prompt: string, options?: GenerateOptions): AsyncGenerator<string> {
    const model = this.resolveModel(options);
    const generativeModel =
      model === this.model ? this.generativeModel : this.client.getGenerativeModel({ model });
    const generationConfig = {
      temperature: options?.temperature ?? RATIO_0_7,
      maxOutputTokens: options?.maxTokens ?? NUM_2048,
      topP: options?.topP ?? RATIO_0_95,
      topK: options?.topK ?? NUM_40,
    };

    let fullPrompt = prompt;
    if (options?.systemPrompt) {
      fullPrompt = `${options.systemPrompt}\n\n${prompt}`;
    }

    const streamResult = await settle(
      generativeModel.generateContentStream({
        contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
        generationConfig,
      }),
    );
    if (streamResult.status === "rejected") {
      throw new Error(`${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(streamResult.reason)}`);
    }
    const result = streamResult.value;

    const iterator = result.stream[Symbol.asyncIterator]();
    const emitTextChunks = async function* (): AsyncGenerator<string> {
      const nextChunkResult = await settle(iterator.next());
      if (nextChunkResult.status === "rejected") {
        throw new Error(
          `${API_ERROR_AI_STREAMING_FAILED}: ${toErrorMessage(nextChunkResult.reason)}`,
        );
      }
      const nextChunk = nextChunkResult.value;
      if (nextChunk.done) {
        return;
      }
      const text = nextChunk.value.text();
      if (text) {
        yield text;
      }
      yield* emitTextChunks();
    };

    yield* emitTextChunks();
  }

  async isAvailable(): Promise<boolean> {
    // Try to list models to verify API key and connectivity
    return (
      (await settle(Promise.resolve(this.client.getGenerativeModel({ model: "gemini-pro" }))))
        .status === "fulfilled"
    );
  }
}

import { expect, spyOn, test } from "bun:test";
import { HUGGING_FACE_DEFAULT_MODEL } from "@bao/shared/constants/ai-provider";
import { API_ERROR_ALL_PROVIDERS_GENERATE_FAILED } from "@bao/shared/constants/api-errors";
import type { AIProviderConfig, AIRouting } from "@bao/shared/types/ai";
import { settle } from "@bao/shared/utils/promise";
import { AIService } from "./ai-service";
import { LocalProvider } from "./local-provider";

const createFailoverConfigs = (): AIProviderConfig[] => [
  {
    provider: "local",
    enabled: true,
    baseUrl: "http://localhost:11434/v1",
    model: "local-model",
  },
  {
    provider: "huggingface",
    enabled: true,
    apiKey: "hf_test_token",
    model: HUGGING_FACE_DEFAULT_MODEL,
  },
];

const createFailoverRouting = (): AIRouting => ({
  chat: { provider: "local", model: "auto-router" },
  interviewQuestions: { provider: "local" },
  interviewFeedback: { provider: "local" },
  resume: { provider: "local" },
  coverLetter: { provider: "local" },
  emailResponse: { provider: "local" },
  jobMatch: { provider: "local" },
  scrapeEnrichment: { provider: "local" },
  automationFieldMapping: { provider: "local" },
});

test("generate fails over to the first healthy provider with a concrete provider model", async () => {
  const service = new AIService(createFailoverConfigs(), "local", createFailoverRouting());

  const localProvider = service.getProvider("local");
  const huggingfaceProvider = service.getProvider("huggingface");

  expect(localProvider).toBeTruthy();
  expect(huggingfaceProvider).toBeTruthy();

  if (!(localProvider && huggingfaceProvider)) {
    return;
  }

  spyOn(LocalProvider, "inspectEndpoint").mockResolvedValue({
    provider: "local",
    checkedAt: "2026-03-31T00:00:00.000Z",
    code: "unreachable",
    message: "Endpoint did not respond",
    endpoint: "http://localhost:11434/v1",
  });
  spyOn(huggingfaceProvider, "isAvailable").mockResolvedValue(true);

  let receivedProvider: string | undefined;
  let receivedModel: string | undefined;
  const generateSpy = spyOn(huggingfaceProvider, "generate");
  generateSpy.mockImplementation((_prompt, options) => {
    receivedProvider = options?.provider;
    receivedModel = options?.model;
    return Promise.resolve({
      id: "test-response",
      provider: "huggingface",
      model: options?.model ?? "",
      content: "ok",
    });
  });

  const response = await service.generate("hello", {
    provider: "local",
    model: "auto-router",
  });

  expect(generateSpy).toHaveBeenCalledTimes(1);
  expect(response.provider).toBe("huggingface");
  expect(response.model).toBe(HUGGING_FACE_DEFAULT_MODEL);
  expect(receivedProvider).toBe("huggingface");
  expect(receivedModel).toBe(HUGGING_FACE_DEFAULT_MODEL);
});

test("generate throws when every provider in the failover order fails", async () => {
  const service = new AIService(createFailoverConfigs(), "local", createFailoverRouting());

  const localProvider = service.getProvider("local");
  const huggingfaceProvider = service.getProvider("huggingface");

  expect(localProvider).toBeTruthy();
  expect(huggingfaceProvider).toBeTruthy();

  if (!(localProvider && huggingfaceProvider)) {
    return;
  }

  spyOn(LocalProvider, "inspectEndpoint").mockResolvedValue({
    provider: "local",
    checkedAt: "2026-03-31T00:00:00.000Z",
    code: "healthy",
    message: "Endpoint healthy",
    endpoint: "http://localhost:11434/v1",
    selectedModel: "local-model",
    availableModels: ["local-model"],
  });
  spyOn(localProvider, "isAvailable").mockResolvedValue(true);
  spyOn(huggingfaceProvider, "isAvailable").mockResolvedValue(true);
  spyOn(localProvider, "generate").mockResolvedValue({
    id: "local-failed",
    provider: "local",
    model: "local-model",
    content: "",
    error: "local generate failed",
  });
  spyOn(huggingfaceProvider, "generate").mockResolvedValue({
    id: "hf-failed",
    provider: "huggingface",
    model: HUGGING_FACE_DEFAULT_MODEL,
    content: "",
    error: "huggingface generate failed",
  });

  const result = await settle(service.generate("hello"));
  expect(result.status).toBe("rejected");
  if (result.status !== "rejected") {
    throw new Error("Expected generate to reject when all providers fail");
  }
  expect(result.reason).toBeInstanceOf(Error);
  expect(String(result.reason)).toBe(`Error: ${API_ERROR_ALL_PROVIDERS_GENERATE_FAILED}`);
  expect(String(result.reason)).not.toContain("local generate failed");
  expect(String(result.reason)).not.toContain("huggingface generate failed");
  expect(String(result.reason)).not.toContain("hf_test_token");
});

import {
  AI_PROVIDER_DEFAULT_ORDER,
  HUGGING_FACE_DEFAULT_MODEL,
  LOCAL_AI_AUTO_DETECT_MODEL,
  normalizeAIRouting,
} from "@bao/shared/constants/ai-provider";
import type { AIProviderConfig, AIProviderType, AIRouting } from "@bao/shared/types/ai";
import { normalizeLocalModelEndpoint } from "@bao/shared/types/settings-normalization";
import {
  DeterministicTestProvider,
  TEST_AI_MODEL_NAME,
  TEST_AI_PROVIDER_NAME,
} from "./ai-deterministic-provider";
import { ClaudeProvider } from "./claude-provider";
import { GeminiProvider } from "./gemini-provider";
import { HuggingFaceProvider } from "./huggingface-provider";
import { LocalProvider } from "./local-provider";
import { OpenAIProvider } from "./openai-provider";
import type { AIProvider } from "./provider-interface";

export type AIServiceSettings = {
  geminiApiKey?: string | null;
  claudeApiKey?: string | null;
  openaiApiKey?: string | null;
  huggingfaceToken?: string | null;
  localModelEndpoint?: string | null;
  localModelName?: string | null;
  aiRouting?: AIRouting | null;
  preferredProvider?: string | null;
  preferredModel?: string | null;
};

export const appendOptionalProviderConfig = (
  configs: AIProviderConfig[],
  provider: Exclude<AIProviderType, "local" | "huggingface">,
  apiKey?: string | null,
): void => {
  if (!apiKey) {
    return;
  }

  configs.push({
    provider,
    apiKey,
    enabled: true,
  });
};

export const buildProviderConfigs = (settings?: AIServiceSettings): AIProviderConfig[] => {
  const localModelEndpoint = normalizeLocalModelEndpoint(settings?.localModelEndpoint);
  const localModelName =
    typeof settings?.localModelName === "string" && settings.localModelName.trim()
      ? settings.localModelName.trim()
      : null;

  const configs: AIProviderConfig[] = [
    {
      provider: "local",
      enabled: true,
      ...(localModelEndpoint ? { baseUrl: localModelEndpoint } : {}),
      ...(localModelName ? { model: localModelName } : {}),
    },
  ];

  appendOptionalProviderConfig(configs, "gemini", settings?.geminiApiKey);
  appendOptionalProviderConfig(configs, "claude", settings?.claudeApiKey);
  appendOptionalProviderConfig(configs, "openai", settings?.openaiApiKey);
  if (
    typeof settings?.huggingfaceToken === "string" &&
    settings.huggingfaceToken.trim().length > 0
  ) {
    configs.push({
      provider: "huggingface",
      enabled: true,
      apiKey: settings.huggingfaceToken.trim(),
      model: HUGGING_FACE_DEFAULT_MODEL,
    });
  }

  return configs;
};

export const resolvePreferredProvider = (preferredProvider?: string | null): AIProviderType => {
  if (!preferredProvider) {
    return AI_PROVIDER_DEFAULT_ORDER[0];
  }

  const matchedProvider = AI_PROVIDER_DEFAULT_ORDER.find(
    (provider) => provider === preferredProvider,
  );
  return matchedProvider ?? AI_PROVIDER_DEFAULT_ORDER[0];
};

export const canCreateLocalProvider = (config: AIProviderConfig): boolean =>
  config.provider === "local" &&
  typeof config.baseUrl === "string" &&
  config.baseUrl.trim().length > 0 &&
  URL.canParse(config.baseUrl);

export const isConfiguredProviderConfig = (config: AIProviderConfig): boolean => {
  if (config.provider === "local") {
    return canCreateLocalProvider(config);
  }

  return typeof config.apiKey === "string" && config.apiKey.trim().length > 0;
};

export const createProvider = (config: AIProviderConfig): AIProvider | null => {
  switch (config.provider) {
    case "gemini":
      return config.apiKey ? new GeminiProvider(config.apiKey, config.model) : null;
    case "claude":
      return config.apiKey ? new ClaudeProvider(config.apiKey, config.model) : null;
    case "openai":
      return config.apiKey ? new OpenAIProvider(config.apiKey, config.model) : null;
    case "huggingface":
      return config.apiKey ? new HuggingFaceProvider(config.apiKey, config.model) : null;
    case "local":
      if (!canCreateLocalProvider(config)) {
        return null;
      }
      return new LocalProvider(config.baseUrl, config.model || LOCAL_AI_AUTO_DETECT_MODEL);
    default:
      return null;
  }
};

export const createDeterministicServiceState = () => ({
  providerFailoverOrder: [TEST_AI_PROVIDER_NAME] as const satisfies AIProviderType[],
  preferredProvider: TEST_AI_PROVIDER_NAME,
  providers: new Map<AIProviderType, AIProvider>([
    [TEST_AI_PROVIDER_NAME, new DeterministicTestProvider()],
  ]),
  routing: normalizeAIRouting(undefined, TEST_AI_PROVIDER_NAME, TEST_AI_MODEL_NAME),
});

import {
  AI_PROVIDER_DEFAULT,
  AI_PROVIDER_DEFAULT_ORDER,
  DEFAULT_AI_ROUTING,
  LOCAL_AI_AUTO_DETECT_MODEL,
  normalizeAIRouting,
} from "@bao/shared/constants/ai-provider";
import type {
  AIProviderConfig,
  AIProviderStatus,
  AIProviderType,
  AIResponse,
  AIRouting,
  GenerateOptions,
} from "@bao/shared/types/ai";
import { settle } from "@bao/shared/utils/promise";
import { isTestRuntime } from "../../config/env";
import { TEST_AI_PROVIDER_NAME } from "./ai-deterministic-provider";
import {
  buildProviderConfigs,
  createDeterministicServiceState,
  createProvider,
  resolvePreferredProvider,
} from "./ai-provider-config";
import { detectLocalProviders, getProviderStatuses } from "./ai-provider-diagnostics";
import {
  buildGenerateFailure,
  buildStreamFailure,
  generateWithProviderFailover,
  mergePromptWithContext,
  streamWithProviderFailover,
  toProviderOptions,
} from "./ai-provider-failover";
import {
  buildProviderFailoverOrder,
  buildProviderOrder,
  initializeProviders,
  rebuildProviderFailoverOrderFromProviders,
  resolveRoutingTarget,
} from "./ai-provider-state";
import type { AIProvider } from "./provider-interface";

type AIServiceSettings = Parameters<typeof buildProviderConfigs>[0];

/**
 * Multi-provider AI service with ordered failover across configured providers.
 */
export class AIService {
  private providers: Map<AIProviderType, AIProvider> = new Map();
  private preferredProvider?: AIProviderType;
  private routing: AIRouting = DEFAULT_AI_ROUTING;
  private providerFailoverOrder: AIProviderType[] = [];

  constructor(
    configs: AIProviderConfig[],
    preferredProvider?: AIProviderType,
    routing?: AIRouting,
  ) {
    this.preferredProvider = preferredProvider;
    this.routing = normalizeAIRouting(routing, preferredProvider ?? AI_PROVIDER_DEFAULT);
    this.providers = initializeProviders(configs);
    this.providerFailoverOrder = buildProviderFailoverOrder(configs, this.preferredProvider);
  }

  /**
   * Create an AIService from a settings DB row.
   * Converts the flat settings config into AIProviderConfig[] format.
   * Used by WebSocket handlers, route handlers, and services.
   */
  static fromSettings(settings?: AIServiceSettings): AIService {
    if (isTestRuntime) {
      return AIService.createDeterministicTestService();
    }

    const configs = buildProviderConfigs(settings);
    const preferredProvider = resolvePreferredProvider(
      settings?.aiRouting?.chat?.provider ?? settings?.preferredProvider,
    );
    const routing = normalizeAIRouting(
      settings?.aiRouting,
      preferredProvider,
      settings?.preferredModel,
    );
    return new AIService(configs, preferredProvider, routing);
  }

  private static createDeterministicTestService(): AIService {
    const service = new AIService([], TEST_AI_PROVIDER_NAME, DEFAULT_AI_ROUTING);
    const deterministicState = createDeterministicServiceState();
    service.providers = deterministicState.providers;
    service.providerFailoverOrder = [...deterministicState.providerFailoverOrder];
    service.preferredProvider = deterministicState.preferredProvider;
    service.routing = deterministicState.routing;
    return service;
  }

  private refreshProviderFailoverOrder(): void {
    this.providerFailoverOrder = rebuildProviderFailoverOrderFromProviders(
      this.providers,
      this.preferredProvider,
    );
  }

  private async resolveHealthyProviderOrder(options?: GenerateOptions): Promise<AIProviderType[]> {
    const baseOrder = buildProviderOrder(
      this.providerFailoverOrder,
      this.routing,
      this.preferredProvider,
      options,
    );
    const availabilityResult = await settle(this.getAvailableProviders());
    if (availabilityResult.status === "rejected") {
      return baseOrder;
    }

    const healthyProviders = new Set(
      availabilityResult.value
        .filter((status) => status.available)
        .map((status) => status.provider),
    );
    if (healthyProviders.size === 0) {
      return baseOrder;
    }

    const healthyOrder = baseOrder.filter((provider) => healthyProviders.has(provider));
    return healthyOrder.length > 0 ? healthyOrder : baseOrder;
  }

  /**
   * Get a specific provider by name
   */
  getProvider(name?: AIProviderType): AIProvider | null {
    if (name) {
      return this.providers.get(name) || null;
    }

    if (this.preferredProvider && this.providers.has(this.preferredProvider)) {
      return this.providers.get(this.preferredProvider) || null;
    }

    return this.providers.values().next().value || null;
  }

  /**
   * Generate a response with ordered provider failover. Throws when every provider fails.
   */
  async generate(prompt: string, options?: GenerateOptions): Promise<AIResponse> {
    const contextualPrompt = mergePromptWithContext(prompt, options);
    const routingTarget = resolveRoutingTarget(this.routing, this.preferredProvider, options);
    const providerOrder = await this.resolveHealthyProviderOrder(options);
    const providerOptions = toProviderOptions(routingTarget, options);
    const failoverResult = await generateWithProviderFailover({
      providers: this.providers,
      providerOrder,
      routingTarget,
      contextualPrompt,
      providerOptions,
    });
    if (!failoverResult.success) {
      throw buildGenerateFailure(failoverResult.errors);
    }
    return failoverResult.data;
  }

  /**
   * Stream a response with ordered provider failover. Throws when every provider fails.
   */
  async *stream(
    prompt: string,
    options?: GenerateOptions,
  ): AsyncGenerator<{ chunk: string; provider: AIProviderType }> {
    const contextualPrompt = mergePromptWithContext(prompt, options);
    const routingTarget = resolveRoutingTarget(this.routing, this.preferredProvider, options);
    const providerOrder = await this.resolveHealthyProviderOrder(options);
    const providerOptions = toProviderOptions(routingTarget, options);
    const streamResult = yield* streamWithProviderFailover({
      providers: this.providers,
      providerOrder,
      routingTarget,
      contextualPrompt,
      providerOptions,
    });
    if (streamResult.streamed) {
      return;
    }
    throw buildStreamFailure(streamResult.errors);
  }

  /**
   * Get status of all providers
   */
  async getAvailableProviders(): Promise<AIProviderStatus[]> {
    return getProviderStatuses(this.providers, (providerType) => this.getActiveModel(providerType));
  }

  /**
   * Detect local AI providers (RamaLama, Ollama)
   */
  async detectLocalProviders(): Promise<
    Array<{
      baseUrl: string;
      name: string;
      available: boolean;
      availableModels?: readonly string[];
      diagnosticCode?: AIProviderStatus["diagnosticCode"];
      message?: string;
    }>
  > {
    return detectLocalProviders();
  }

  /**
   * Update preferred provider
   */
  setPreferredProvider(provider: AIProviderType): void {
    if (this.providers.has(provider)) {
      this.preferredProvider = provider;
      this.refreshProviderFailoverOrder();
    }
  }

  /**
   * Add a new provider at runtime
   */
  addProvider(config: AIProviderConfig): boolean {
    const provider = createProvider(config);
    if (!provider) {
      return false;
    }

    this.providers.set(config.provider, provider);
    this.refreshProviderFailoverOrder();
    return true;
  }

  /**
   * Remove a provider
   */
  removeProvider(provider: AIProviderType): boolean {
    const deleted = this.providers.delete(provider);

    if (deleted) {
      this.providerFailoverOrder = this.providerFailoverOrder.filter((p) => p !== provider);

      if (this.preferredProvider === provider) {
        this.preferredProvider = this.providerFailoverOrder[0];
        if (!this.preferredProvider) {
          this.preferredProvider = AI_PROVIDER_DEFAULT_ORDER[0];
        }
      }

      this.refreshProviderFailoverOrder();
    }

    return deleted;
  }

  /**
   * Get list of configured providers
   */
  getConfiguredProviders(): AIProviderType[] {
    return Array.from(this.providers.keys());
  }

  /**
   * Get the current provider failover order
   */
  getProviderFailoverOrder(): AIProviderType[] {
    return [...this.providerFailoverOrder];
  }

  /**
   * Get the current purpose-aware routing table.
   */
  getRouting(): AIRouting {
    return normalizeAIRouting(this.routing, this.preferredProvider ?? AI_PROVIDER_DEFAULT);
  }

  /**
   * Get the active model name for a given provider (detected or configured).
   */
  getActiveModel(providerType: AIProviderType): string | null {
    const provider = this.providers.get(providerType);
    if (!provider) return null;
    const model = provider.model;
    return model && model !== LOCAL_AI_AUTO_DETECT_MODEL ? model : null;
  }
}

import {
  API_ERROR_SPEECH_STT_ENDPOINT_INVALID,
  API_ERROR_SPEECH_STT_NOT_CONFIGURED,
  API_ERROR_SPEECH_TRANSCRIBE,
} from "@bao/shared/constants/api-errors";
import type { SpeechProviderOption } from "@bao/shared/constants/settings";
import { safeParseJson } from "@bao/shared/utils/json";
import { validateLocalAiEndpoint } from "@bao/shared/utils/local-ai-endpoint";
import { settle } from "@bao/shared/utils/promise";
import { isRecord } from "@bao/shared/utils/type-guards";
import { eq } from "drizzle-orm";
import { db } from "../../db/client";
import { DEFAULT_SETTINGS_ID, settings } from "../../db/schema/settings";
import { decryptProviderKeys } from "../../utils/settings-decrypt";
import { loadAutomationSettings } from "../automation/automation-settings-support";
const NUM_1024 = 1024;
const NUM_120000 = 120_000;
const NUM_180 = 180;
const NUM_8 = 8;

const MAX_AUDIO_BYTES = NUM_8 * NUM_1024 * NUM_1024;
const TRAILING_SLASH_RE = /\/$/u;

export type SpeechTranscribeInput = {
  readonly audioBase64: string;
  readonly mimeType: string;
  readonly filename?: string;
  readonly provider?: string;
  readonly model?: string;
  readonly endpoint?: string;
};

export type SpeechTranscribeResult =
  | {
      readonly ok: true;
      readonly text: string;
      readonly provider: SpeechProviderOption;
      readonly model: string;
    }
  | { readonly ok: false; readonly error: string; readonly status: 400 | 422 | 502 };

const SERVER_STT_PROVIDERS = ["local", "openai", "huggingface", "custom"] as const satisfies readonly SpeechProviderOption[];

const resolveServerSttProvider = (value: string): SpeechProviderOption | null => {
  for (const option of SERVER_STT_PROVIDERS) {
    if (option === value) {
      return option;
    }
  }
  return null;
};

const BASE64_PAYLOAD_RE = /^[A-Za-z0-9+/]+=*$/;

const resolveTranscriptionFilename = (filename: string | undefined, mimeType: string): string => {
  const trimmed = filename?.trim();
  if (trimmed) {
    return trimmed;
  }
  if (mimeType.includes("wav")) {
    return "recording.wav";
  }
  if (mimeType.includes("mp3")) {
    return "recording.mp3";
  }
  return "recording.webm";
};

const decodeAudio = (audioBase64: string): Uint8Array | null => {
  const trimmed = audioBase64.trim();
  if (trimmed.length === 0 || !BASE64_PAYLOAD_RE.test(trimmed)) {
    return null;
  }
  return Uint8Array.from(Buffer.from(trimmed, "base64"));
};

const resolveUpstreamAuth = async (
  provider: SpeechProviderOption,
): Promise<{ readonly apiKey: string | null }> => {
  const rows = await db
    .select()
    .from(settings)
    .where(eq(settings.id, DEFAULT_SETTINGS_ID))
    .limit(1);
  const row = rows[0];
  if (!row) {
    return { apiKey: null };
  }
  const decrypted = decryptProviderKeys(row);
  if (provider === "openai") {
    return { apiKey: decrypted.openaiApiKey ?? null };
  }
  if (provider === "huggingface") {
    return { apiKey: decrypted.huggingfaceToken ?? null };
  }
  return { apiKey: null };
};

const resolveTranscriptionUrl = (
  provider: SpeechProviderOption,
  endpoint: string,
): { readonly ok: true; readonly url: string } | { readonly ok: false; readonly error: string } => {
  const trimmed = endpoint.trim();
  if (provider === "openai") {
    const base =
      trimmed.length > 0 ? trimmed.replace(TRAILING_SLASH_RE, "") : "https://api.openai.com/v1";
    return { ok: true, url: `${base}/audio/transcriptions` };
  }
  if (provider === "huggingface") {
    if (trimmed.length === 0) {
      return { ok: false, error: API_ERROR_SPEECH_STT_ENDPOINT_INVALID };
    }
    return { ok: true, url: trimmed };
  }
  if (provider === "local" || provider === "custom") {
    const validated = validateLocalAiEndpoint(trimmed);
    if (!validated.ok) {
      return { ok: false, error: API_ERROR_SPEECH_STT_ENDPOINT_INVALID };
    }
    const base = validated.endpoint.replace(TRAILING_SLASH_RE, "");
    const withV1 = base.endsWith("/v1") ? base : `${base}/v1`;
    return { ok: true, url: `${withV1}/audio/transcriptions` };
  }
  return { ok: false, error: API_ERROR_SPEECH_STT_NOT_CONFIGURED };
};

const postOpenAiTranscription = async (input: {
  readonly url: string;
  readonly apiKey: string | null;
  readonly bytes: Uint8Array;
  readonly mimeType: string;
  readonly filename: string;
  readonly model: string;
}): Promise<
  { readonly ok: true; readonly text: string } | { readonly ok: false; readonly error: string }
> => {
  const form = new FormData();
  form.append(
    "file",
    new File([Buffer.from(input.bytes)], input.filename, { type: input.mimeType }),
  );
  form.append("model", input.model);
  const headers: Record<string, string> = {};
  if (input.apiKey) {
    headers.Authorization = `Bearer ${input.apiKey}`;
  }
  const responseResult = await settle(
    fetch(input.url, {
      method: "POST",
      headers,
      body: form,
      signal: AbortSignal.timeout(NUM_120000),
    }),
  );
  if (responseResult.status === "rejected") {
    return { ok: false, error: API_ERROR_SPEECH_TRANSCRIBE };
  }
  const response = responseResult.value;
  const bodyText = await response.text();
  if (!response.ok) {
    return { ok: false, error: `${API_ERROR_SPEECH_TRANSCRIBE}: ${bodyText.slice(0, NUM_180)}` };
  }
  const parsed = safeParseJson(bodyText);
  if (!isRecord(parsed) || typeof parsed.text !== "string") {
    return { ok: false, error: API_ERROR_SPEECH_TRANSCRIBE };
  }
  const text = parsed.text.trim();
  if (text.length === 0) {
    return { ok: false, error: API_ERROR_SPEECH_TRANSCRIBE };
  }
  return { ok: true, text };
};

export const transcribeSpeechAudio = async (
  input: SpeechTranscribeInput,
): Promise<SpeechTranscribeResult> => {
  const automation = await loadAutomationSettings();
  const provider = resolveServerSttProvider(
    input.provider?.trim() || automation.speech.stt.provider,
  );
  if (!provider) {
    return { ok: false, error: API_ERROR_SPEECH_STT_NOT_CONFIGURED, status: 422 };
  }
  const model = input.model?.trim() || automation.speech.stt.model;
  const endpoint = input.endpoint?.trim() || automation.speech.stt.endpoint;

  const bytes = decodeAudio(input.audioBase64);
  if (!bytes || bytes.byteLength === 0) {
    return { ok: false, error: "Audio payload is empty or invalid base64", status: 400 };
  }
  if (bytes.byteLength > MAX_AUDIO_BYTES) {
    return { ok: false, error: "Audio payload exceeds 8MB limit", status: 400 };
  }

  const urlResult = resolveTranscriptionUrl(provider, endpoint);
  if (!urlResult.ok) {
    return { ok: false, error: urlResult.error, status: 422 };
  }

  const auth = await resolveUpstreamAuth(provider);
  const filename = resolveTranscriptionFilename(input.filename, input.mimeType);

  const upstream = await postOpenAiTranscription({
    url: urlResult.url,
    apiKey: auth.apiKey,
    bytes,
    mimeType: input.mimeType || "audio/webm",
    filename,
    model,
  });
  if (!upstream.ok) {
    return { ok: false, error: upstream.error, status: 502 };
  }
  return { ok: true, text: upstream.text, provider, model };
};

import {
