import {
  INTERVIEW_DEFAULT_EXPERIENCE_LEVEL,
  INTERVIEW_DEFAULT_FOCUS_AREAS,
  INTERVIEW_DEFAULT_QUESTION_COUNT,
  INTERVIEW_DEFAULT_ROLE_CATEGORY,
  INTERVIEW_DEFAULT_ROLE_TYPE,
  INTERVIEW_DEFAULT_VOICE_SETTINGS,
} from "@bao/shared/constants/interview";
import type {
  InterviewCandidateContext,
  InterviewConversationStyle,
  InterviewTargetJob,
  VoiceSettings,
} from "@bao/shared/types/interview";
import { asString, asStringArray } from "@bao/shared/utils/type-guards";
import type { CreateSessionConfigInput, SubmitResponseBody } from "./interview-route-contracts";

const asNonNegativeInt = (value: number | undefined): number | undefined => {
  if (typeof value === "number" && Number.isInteger(value) && value >= 0) {
    return value;
  }
};

const asStringArrayTrimmed = (value: unknown): string[] =>
  asStringArray(value)
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);

function applyStringFields<T extends object>(
  target: T,
  fields: Array<[string, string | undefined]>,
): T {
  for (const [key, value] of fields) {
    if (value) {
      Object.assign(target, { [key]: value });
    }
  }
  return target;
}

const parseTargetJob = (
  value: CreateSessionConfigInput["targetJob"],
): InterviewTargetJob | undefined => {
  if (!value) return;
  const id = asString(value.id);
  const title = asString(value.title);
  const company = asString(value.company);
  const location = asString(value.location);
  if (!(id && title && company && location)) {
    return;
  }

  const targetJob: InterviewTargetJob = { id, title, company, location };
  const requirements = asStringArrayTrimmed(value.requirements);
  const technologies = asStringArrayTrimmed(value.technologies);
  const description = asString(value.description);
  const source = asString(value.source);
  const postedDate = asString(value.postedDate);
  const url = asString(value.url);

  applyStringFields(targetJob, [["description", description]]);
  if (requirements.length > 0) targetJob.requirements = requirements;
  if (technologies.length > 0) targetJob.technologies = technologies;
  applyStringFields(targetJob, [
    ["source", source],
    ["postedDate", postedDate],
    ["url", url],
  ]);

  return targetJob;
};

const normalizeVoiceSettings = (
  value: CreateSessionConfigInput["voiceSettings"],
): VoiceSettings | undefined => {
  if (!value) {
    return;
  }

  const normalized: VoiceSettings = {
    rate: typeof value.rate === "number" ? value.rate : INTERVIEW_DEFAULT_VOICE_SETTINGS.rate,
    pitch: typeof value.pitch === "number" ? value.pitch : INTERVIEW_DEFAULT_VOICE_SETTINGS.pitch,
    volume:
      typeof value.volume === "number" ? value.volume : INTERVIEW_DEFAULT_VOICE_SETTINGS.volume,
    language: asString(value.language) || INTERVIEW_DEFAULT_VOICE_SETTINGS.language,
  };
  const microphoneId = asString(value.microphoneId);
  const speakerId = asString(value.speakerId);
  const voiceId = asString(value.voiceId);

  applyStringFields(normalized, [
    ["microphoneId", microphoneId],
    ["speakerId", speakerId],
    ["voiceId", voiceId],
  ]);

  return normalized;
};

const parseCandidateContext = (
  value: CreateSessionConfigInput["candidateContext"],
): InterviewCandidateContext | undefined => {
  if (!value) {
    return;
  }

  const resumeId = asString(value.resumeId);
  const coverLetterId = asString(value.coverLetterId);
  const portfolioId = asString(value.portfolioId);
  if (!(resumeId || coverLetterId || portfolioId)) {
    return;
  }

  const context: InterviewCandidateContext = {};
  applyStringFields(context, [
    ["resumeId", resumeId],
    ["coverLetterId", coverLetterId],
    ["portfolioId", portfolioId],
  ]);
  return context;
};

const parseConversationStyle = (
  value: CreateSessionConfigInput["conversationStyle"],
): InterviewConversationStyle | undefined => {
  if (value === "structured") return "structured";
  if (value === "natural") return "natural";
};

export const sessionConfigFromUi = (config: CreateSessionConfigInput): CreateSessionConfigInput => {
  const targetJob = parseTargetJob(config.targetJob);
  const roleTypeFromJob = asString(targetJob?.title);
  const focusAreas = asStringArrayTrimmed(config.focusAreas);

  return {
    roleType: asString(config.roleType) || roleTypeFromJob || INTERVIEW_DEFAULT_ROLE_TYPE,
    roleCategory: asString(config.roleCategory) || INTERVIEW_DEFAULT_ROLE_CATEGORY,
    experienceLevel: asString(config.experienceLevel) || INTERVIEW_DEFAULT_EXPERIENCE_LEVEL,
    focusAreas: focusAreas.length > 0 ? focusAreas : [...INTERVIEW_DEFAULT_FOCUS_AREAS],
    duration: config.duration,
    questionCount: asNonNegativeInt(config.questionCount) ?? INTERVIEW_DEFAULT_QUESTION_COUNT,
    includeTechnical: config.includeTechnical,
    includeBehavioral: config.includeBehavioral,
    includeStudioSpecific: config.includeStudioSpecific,
    enableVoiceMode: config.enableVoiceMode,
    technologies: asStringArrayTrimmed(config.technologies),
    voiceSettings: normalizeVoiceSettings(config.voiceSettings),
    interviewMode: config.interviewMode === "job" ? "job" : "studio",
    conversationStyle: parseConversationStyle(config.conversationStyle),
    targetJob,
    candidateContext: parseCandidateContext(config.candidateContext),
  };
};

export const parseResponsePayload = (body: SubmitResponseBody) => {
  const response = asString(body.response);
  if (!response) {
    return null;
  }

  const questionId = asString(body.questionId);
  const questionIndex = asNonNegativeInt(body.questionIndex);
  return {
    questionId: questionId ?? `index:${questionIndex ?? 0}`,
    questionIndex,
    response,
  };
};

import { API_ENDPOINTS, toApiChildPath, toApiScopedPath } from "@bao/shared/constants/endpoints";
import { HTTP_STATUS_OK } from "@bao/shared/constants/http";
import { Elysia } from "elysia";
import { searchService } from "../services/search-service";
import {
  type SearchType,
  searchAllResponses,
  searchAutocompleteQuery,
  searchAutocompleteResponses,
  searchQuery,
  searchTypes,
} from "./search-route-contracts";

const searchTypeSet = new Set<string>(searchTypes);

const parseSearchTypes = (value: string | undefined): SearchType[] | undefined => {
  if (!value) {
    return;
  }

  const parsedTypes = value
    .split(",")
    .map((type) => type.trim())
    .filter((type): type is SearchType => searchTypeSet.has(type));

  return parsedTypes.length > 0 ? parsedTypes : undefined;
};

export const searchRoutes = new Elysia({
  prefix: toApiScopedPath(API_ENDPOINTS.searchBase),
})
  .get(
    toApiChildPath(API_ENDPOINTS.searchBase, API_ENDPOINTS.search),
    {
      detail: { tags: ["Search"] },
      query: searchQuery,
      response: searchAllResponses,
    },
    async ({ query, status }) => {
      const q = query.q || "";
      if (q.length < 2) {
        return status(HTTP_STATUS_OK, {
          query: q,
          results: [],
          counts: { jobs: 0, studios: 0, skills: 0, resumes: 0 },
          totalTime: 0,
        });
      }
      const types = parseSearchTypes(query.types);
      return status(HTTP_STATUS_OK, await searchService.searchAll(q, types));
    },
  )
  .get(
    toApiChildPath(API_ENDPOINTS.searchBase, API_ENDPOINTS.searchAutocomplete),
    {
      detail: { tags: ["Search"] },
      query: searchAutocompleteQuery,
      response: searchAutocompleteResponses,
    },
    async ({ query, status }) => {
      const prefix = query.prefix || "";
      return status(HTTP_STATUS_OK, await searchService.autocomplete(prefix));
    },
  );

import { AI_PROVIDER_TEST_STRATEGY_BY_ID } from "@bao/shared/constants/ai-provider";
import { API_ERROR_UNKNOWN, API_ERROR_UNKNOWN_PROVIDER } from "@bao/shared/constants/api-errors";
import { normalizeAppDataTheme, resolveBrandSettings } from "@bao/shared/constants/branding";
import type { AIProviderType } from "@bao/shared/types/ai";
import {
  normalizeAutomationSettings,
  normalizeLocalModelEndpoint,
} from "@bao/shared/types/settings-normalization";
import { validateLocalAiEndpoint } from "@bao/shared/utils/local-ai-endpoint";
import { settle } from "@bao/shared/utils/promise";
import type { settings as settingsTable } from "../db/schema/settings";
import { buildAIControlPlaneState } from "../services/ai/control-plane";
import { LocalProvider } from "../services/ai/local-provider";
import { getJobTaxonomy } from "../services/jobs/job-taxonomy-service";
import { decryptProviderKey, isEncryptionAvailable } from "../utils/crypto";
import { createServerLogger } from "../utils/logger";

const settingsProviderLogger = createServerLogger("settings-provider-test");

const KEY_MASK_VISIBLE_CHARS = 4;

const maybeDecrypt = (value: string): string => {
  if (!value.startsWith("enc:")) return value;
  if (!isEncryptionAvailable()) return "";
  return decryptProviderKey(value);
};
type SettingsRow = typeof settingsTable.$inferSelect;

export const buildSettingsResponse = async (row: SettingsRow) => {
  const { emailTransportPassword, ...publicRow } = row;
  const [controlPlane, jobTaxonomy] = await Promise.all([
    buildAIControlPlaneState(row),
    getJobTaxonomy(),
  ]);
  const automationSettings = row.automationSettings
    ? normalizeAutomationSettings(row.automationSettings)
    : row.automationSettings;

  return {
    ...publicRow,
    automationSettings,
    localModelEndpoint: normalizeLocalModelEndpoint(row.localModelEndpoint),
    aiRouting: controlPlane.aiRouting,
    providerDiagnostics: controlPlane.providerDiagnostics,
    preferredProvider: controlPlane.preferredProvider,
    preferredModel: controlPlane.preferredModel,
    theme: normalizeAppDataTheme(row.theme),
    brandSettings: resolveBrandSettings(row.brandSettings),
    geminiApiKey: row.geminiApiKey
      ? `***${maybeDecrypt(row.geminiApiKey).slice(-KEY_MASK_VISIBLE_CHARS)}`
      : null,
    openaiApiKey: row.openaiApiKey
      ? `***${maybeDecrypt(row.openaiApiKey).slice(-KEY_MASK_VISIBLE_CHARS)}`
      : null,
    claudeApiKey: row.claudeApiKey
      ? `***${maybeDecrypt(row.claudeApiKey).slice(-KEY_MASK_VISIBLE_CHARS)}`
      : null,
    huggingfaceToken: row.huggingfaceToken
      ? `***${maybeDecrypt(row.huggingfaceToken).slice(-KEY_MASK_VISIBLE_CHARS)}`
      : null,
    hasGeminiKey: Boolean(row.geminiApiKey),
    hasOpenaiKey: Boolean(row.openaiApiKey),
    hasClaudeKey: Boolean(row.claudeApiKey),
    hasHuggingfaceToken: Boolean(row.huggingfaceToken),
    hasEmailTransportPassword: Boolean(emailTransportPassword),
    hasLocalKey: Boolean(row.localModelEndpoint),
    jobTaxonomy,
  };
};

const resolveProviderStrategy = (provider: AIProviderType) => {
  switch (provider) {
    case "gemini":
      return AI_PROVIDER_TEST_STRATEGY_BY_ID.gemini;
    case "openai":
      return AI_PROVIDER_TEST_STRATEGY_BY_ID.openai;
    case "claude":
      return AI_PROVIDER_TEST_STRATEGY_BY_ID.claude;
    case "huggingface":
      return AI_PROVIDER_TEST_STRATEGY_BY_ID.huggingface;
    default:
      return null;
  }
};

export const testProviderConnection = async (body: {
  provider: AIProviderType;
  key: string;
  model?: string;
}) => {
  if (body.provider === "local") {
    const validated = validateLocalAiEndpoint(body.key);
    if (!validated.ok) {
      return {
        valid: false,
        provider: body.provider,
        diagnosticCode: "error" as const,
        message: `Local AI endpoint rejected (${validated.code})`,
      };
    }
    const diagnostics = await LocalProvider.inspectEndpoint(validated.endpoint, body.model);
    return {
      valid: diagnostics.code === "healthy",
      provider: body.provider,
      diagnosticCode: diagnostics.code,
      message: diagnostics.message,
      availableModels: diagnostics.availableModels,
      selectedModel: diagnostics.selectedModel,
    };
  }

  const strategy = resolveProviderStrategy(body.provider);
  if (!strategy) {
    return {
      valid: false,
      provider: body.provider,
      error: API_ERROR_UNKNOWN_PROVIDER,
    };
  }

  const responseResult = await settle(
    fetch(strategy.buildUrl(body.key), strategy.buildInit(body.key)),
  );
  if (responseResult.status === "rejected") {
    settingsProviderLogger.error("Provider connection test failed", {
      provider: body.provider,
      reason:
        responseResult.reason instanceof Error ? responseResult.reason.message : API_ERROR_UNKNOWN,
    });
    return {
      valid: false,
      provider: body.provider,
      diagnosticCode: "error" as const,
      message: API_ERROR_UNKNOWN,
    };
  }

  const valid = strategy.isSuccess(responseResult.value.status);
  return {
    valid,
    provider: body.provider,
    diagnosticCode: valid ? ("healthy" as const) : ("error" as const),
    message: valid ? undefined : `HTTP ${responseResult.value.status}`,
  };
};

import {
  API_ERROR_INTERVIEW_QUESTION_UNRESOLVED,
  API_ERROR_INTERVIEW_RESPONSE_REQUIRED,
  API_ERROR_INTERVIEW_SESSION_NOT_FOUND,
} from "@bao/shared/constants/api-errors";
import {
  API_MESSAGE_INTERVIEW_COMPLETED,
  API_MESSAGE_INTERVIEW_SESSION_CREATED,
  API_MESSAGE_RESPONSE_RECORDED,
} from "@bao/shared/constants/api-messages";
import { ROUTE_GAMIFICATION_XP } from "@bao/shared/constants/gamification";
import {
  HTTP_STATUS_BAD_REQUEST,
  HTTP_STATUS_CREATED,
  HTTP_STATUS_NOT_FOUND,
  HTTP_STATUS_OK,
} from "@bao/shared/constants/http";
import { INTERVIEW_FALLBACK_STUDIO_ID } from "@bao/shared/constants/interview";
import type { InterviewResponse, InterviewSession } from "@bao/shared/types/interview";
import { asString } from "@bao/shared/utils/type-guards";
import { gamificationService } from "../services/gamification-service";
import { interviewService } from "../services/interview-service";
import { parseResponsePayload, sessionConfigFromUi } from "./interview-route-config";
import type { CreateSessionConfigInput, SubmitResponseBody } from "./interview-route-contracts";
import { sessionWithDerivedFields } from "./interview-route-presentation";
const NUM_150 = 150;

const buildDefaultResponse = (questionId: string, answer: string): InterviewResponse => ({
  questionId,
  transcript: answer,
  duration: Math.max(1, answer.length * NUM_150),
  timestamp: Date.now(),
  confidence: 0.8,
});

const resolveQuestionId = (
  session: InterviewSession,
  payload: ReturnType<typeof parseResponsePayload>,
) => {
  if (!payload) return null;
  if (payload.questionId && payload.questionId !== "index:0") {
    return payload.questionId;
  }

  const fallbackIndex = payload.questionIndex ?? session.currentQuestionIndex;
  return session.questions[fallbackIndex]?.id;
};

export const createInterviewSession = async (
  studioId: string | undefined,
  config: CreateSessionConfigInput | undefined,
) => {
  const normalizedConfig = sessionConfigFromUi(config ?? {});
  const resolvedStudioId = asString(studioId) || INTERVIEW_FALLBACK_STUDIO_ID;
  const created = await interviewService.startSession(resolvedStudioId, normalizedConfig);
  const response = await sessionWithDerivedFields(created);
  return {
    status: HTTP_STATUS_CREATED,
    body: {
      ...response,
      message: API_MESSAGE_INTERVIEW_SESSION_CREATED,
    },
  };
};

export const getInterviewSession = async (id: string) => {
  const session = await interviewService.getSession(id);
  if (!session) {
    return {
      status: HTTP_STATUS_NOT_FOUND as typeof HTTP_STATUS_NOT_FOUND,
      body: { error: API_ERROR_INTERVIEW_SESSION_NOT_FOUND },
    };
  }
  return {
    status: HTTP_STATUS_OK as typeof HTTP_STATUS_OK,
    body: await sessionWithDerivedFields(session),
  };
};

export const submitInterviewResponse = async (id: string, body: SubmitResponseBody) => {
  const session = await interviewService.getSession(id);
  if (!session) {
    return {
      status: HTTP_STATUS_NOT_FOUND as typeof HTTP_STATUS_NOT_FOUND,
      body: { error: API_ERROR_INTERVIEW_SESSION_NOT_FOUND },
    };
  }

  const payload = parseResponsePayload(body);
  if (!payload) {
    return {
      status: HTTP_STATUS_BAD_REQUEST as typeof HTTP_STATUS_BAD_REQUEST,
      body: { error: API_ERROR_INTERVIEW_RESPONSE_REQUIRED },
    };
  }

  const resolvedQuestionId = resolveQuestionId(session, payload);
  if (!resolvedQuestionId) {
    return {
      status: HTTP_STATUS_BAD_REQUEST as typeof HTTP_STATUS_BAD_REQUEST,
      body: { error: API_ERROR_INTERVIEW_QUESTION_UNRESOLVED },
    };
  }

  const response = buildDefaultResponse(resolvedQuestionId, payload.response);
  const updated = await interviewService.addResponse(id, response);
  if (!updated) {
    return {
      status: HTTP_STATUS_NOT_FOUND as typeof HTTP_STATUS_NOT_FOUND,
      body: { error: API_ERROR_INTERVIEW_SESSION_NOT_FOUND },
    };
  }

  return {
    status: HTTP_STATUS_OK as typeof HTTP_STATUS_OK,
    body: {
      ...(await sessionWithDerivedFields(updated)),
      message: API_MESSAGE_RESPONSE_RECORDED,
    },
  };
};

export const completeInterviewSession = async (id: string) => {
  const completed = await interviewService.completeSession(id);
  if (!completed) {
    return {
      status: HTTP_STATUS_NOT_FOUND as typeof HTTP_STATUS_NOT_FOUND,
      body: { error: API_ERROR_INTERVIEW_SESSION_NOT_FOUND },
    };
  }

  gamificationService.trackActionFireAndForget(
    "interviewsCompleted",
    ROUTE_GAMIFICATION_XP.interviewsCompleted,
    "interview_completed",
  );

  return {
    status: HTTP_STATUS_OK as typeof HTTP_STATUS_OK,
    body: {
      ...(await sessionWithDerivedFields(completed)),
      message: API_MESSAGE_INTERVIEW_COMPLETED,
    },
  };
};

