describe("toGeneratedCoverLetterContent", () => {
  testParsesFencedJsonResponses();
  testParsesPlainLineSegments();
  testParsesJsonLikeQuotedSegments();
  testParsesReasoningStyleDraftSections();
  testStripsReasoningTails();
