const BASE64URL_PADDING_PATTERN = /[=]+$/u;

const encodeBase64Url = (bytes: Uint8Array): string =>
  btoa(String.fromCharCode(...bytes))
    .replace(/\+/gu, "-")
    .replace(/\//gu, "_")
    .replace(BASE64URL_PADDING_PATTERN, "");

const resolveSetupToken = (
  request: Request,
  body: { readonly setupToken?: string },
): string | null => {
  const bodyToken = body.setupToken?.trim();
  if (bodyToken && bodyToken.length > 0) {
    return bodyToken;
  }

  const headerToken = request.headers.get(AUTH_SETUP_TOKEN_HEADER)?.trim();
  return headerToken && headerToken.length > 0 ? headerToken : null;
};

function generateApiKey(): string {
  const bytes = new Uint8Array(AUTH_KEY_RANDOM_BYTES);
  crypto.getRandomValues(bytes);
  return `${AUTH_KEY_PREFIX}${encodeBase64Url(bytes)}`;
}

async function insertAuditLog(
  event: string,
  actor: string,
  detail: string,
  ip?: string,
): Promise<void> {
  await db.insert(auditLog).values({
    event,
    actor,
    detail,
    ip: ip ?? null,
  });
}

export const authRoutes = new Elysia({
  prefix: toApiScopedPath(API_ENDPOINTS.authBase),
})
  .get(
    toApiChildPath(API_ENDPOINTS.authBase, API_ENDPOINTS.authStatus),
    {
      // no inline detail for rotate,revoke routes
      response: authStatusResponses,
    },
    async ({ status }) => {
      if (config.disableAuth) {
        return status(HTTP_STATUS_OK, {
          configured: false,
          authRequired: false,
          bootstrapRequired: false,
          setupTokenConfigured: false,
        });
      }
      const rows = await db.select().from(auth).where(eq(auth.id, DEFAULT_PROFILE_ID));
      const hasKey = Boolean(rows[0]?.apiKeyHash);
      return status(HTTP_STATUS_OK, {
        authRequired: true,
        configured: hasKey,
        bootstrapRequired: !hasKey,
        setupTokenConfigured: config.authSetupToken !== null,
      });
    },
  )
  .get(
    toApiChildPath(API_ENDPOINTS.authBase, API_ENDPOINTS.authConfigured),
    {
      // no inline detail for rotate,revoke routes
      response: authConfiguredResponses,
    },
    async ({ status }) => {
      if (config.disableAuth) {
        return status(HTTP_STATUS_OK, { configured: false });
      }
      const rows = await db.select().from(auth).where(eq(auth.id, DEFAULT_PROFILE_ID));
      const hasKey = Boolean(rows[0]?.apiKeyHash);
      return status(HTTP_STATUS_OK, { configured: hasKey });
    },
  )
  .use(
    new Elysia()
      .use(
        rateLimit({
          scoping: "scoped",
          duration: RATE_LIMIT_AUTH_BOOTSTRAP_DURATION_MS,
          max: RATE_LIMIT_AUTH_BOOTSTRAP_MAX_REQUESTS,
          generator: (request) => resolveRateLimitClientKey(request),
        }),
      )
      .post(
        toApiChildPath(API_ENDPOINTS.authBase, API_ENDPOINTS.authInit),
        {
          // no inline detail for rotate,revoke routes
          body: authBootstrapBody,
          response: authInitResponses,
        },
        async ({ body, request, status }) => {
          if (config.disableAuth) {
            return status(HTTP_STATUS_OK, {
              configured: false,
              message: API_MESSAGE_AUTH_DISABLED,
            });
          }

          const rows = await db.select().from(auth).where(eq(auth.id, DEFAULT_PROFILE_ID));
          const existingHash = rows[0]?.apiKeyHash;

          if (existingHash) {
            return status(HTTP_STATUS_OK, {
              configured: true,
              message: API_MESSAGE_API_KEY_ALREADY_CONFIGURED,
            });
          }

          const expectedSetupToken = config.authSetupToken;
          if (!expectedSetupToken) {
            return status(HTTP_STATUS_FORBIDDEN, {
              error: API_ERROR_AUTH_SETUP_TOKEN_UNAVAILABLE,
            });
          }

          const providedSetupToken = resolveSetupToken(request, body);
          if (!providedSetupToken) {
            return status(HTTP_STATUS_BAD_REQUEST, {
              error: API_ERROR_AUTH_SETUP_TOKEN_REQUIRED,
            });
          }

          const providedSetupTokenBytes = Buffer.from(providedSetupToken, "utf8");
          const expectedSetupTokenBytes = Buffer.from(expectedSetupToken, "utf8");
          if (
            providedSetupTokenBytes.length !== expectedSetupTokenBytes.length ||
            !timingSafeEqual(providedSetupTokenBytes, expectedSetupTokenBytes)
          ) {
            return status(HTTP_STATUS_FORBIDDEN, {
              error: API_ERROR_AUTH_SETUP_TOKEN_INVALID,
            });
          }

          const rawApiKey = generateApiKey();
          const keyHash = hashApiKey(rawApiKey);
          const now = new Date().toISOString();

          await db
            .insert(auth)
            .values({
              id: DEFAULT_PROFILE_ID,
              apiKeyHash: keyHash,
              apiKeyCreatedAt: now,
              apiKeyExpiresAt: null,
              apiKeyRevokedAt: null,
            })
            .onConflictDoUpdate({
              target: auth.id,
              set: {
                apiKeyHash: keyHash,
                apiKeyCreatedAt: now,
                apiKeyExpiresAt: null,
                apiKeyRevokedAt: null,
              },
            });

          await insertAuditLog("api_key_created", "system", "first_run_bootstrap");

          return status(HTTP_STATUS_OK, {
            configured: true,
            apiKey: rawApiKey,
            message: API_MESSAGE_SAVE_API_KEY_ONCE,
          });
        },
      )
      .post(
        toApiChildPath(API_ENDPOINTS.authBase, API_ENDPOINTS.authRotate),
        {
          // no inline detail for rotate,revoke routes
        },
        async ({ request, status }) => {
          const authFailure = await authenticateApiKey(request);
          if (authFailure) {
            return status(authFailure.status, { error: authFailure.error });
          }

          const rows = await db.select().from(auth).where(eq(auth.id, DEFAULT_PROFILE_ID));
          const row = rows[0];
          if (!row?.apiKeyHash) {
            return status(HTTP_STATUS_NOT_FOUND, {
              error: "No API key configured to rotate",
            });
          }

          const newRawKey = generateApiKey();
          const newHash = hashApiKey(newRawKey);
          const now = new Date().toISOString();

          await db
            .update(auth)
            .set({
              apiKeyHash: newHash,
              apiKeyCreatedAt: now,
              apiKeyExpiresAt: null,
              apiKeyRevokedAt: null,
            })
            .where(eq(auth.id, DEFAULT_PROFILE_ID));

          await insertAuditLog("api_key_rotated", "admin", "manual_rotation");

          return status(HTTP_STATUS_OK, {
            configured: true,
            apiKey: newRawKey,
            message: "API key rotated. Save this new key — it will not be shown again.",
          });
        },
      )
      .post(
        toApiChildPath(API_ENDPOINTS.authBase, API_ENDPOINTS.authRevoke),
        {
          // no inline detail for rotate,revoke routes
        },
        async ({ request, status }) => {
          const authFailure = await authenticateApiKey(request);
          if (authFailure) {
            return status(authFailure.status, { error: authFailure.error });
          }

          const rows = await db.select().from(auth).where(eq(auth.id, DEFAULT_PROFILE_ID));
          const row = rows[0];
          if (!row?.apiKeyHash) {
            return status(HTTP_STATUS_NOT_FOUND, {
              error: "No API key configured to revoke",
            });
          }

          const now = new Date().toISOString();
          await db
            .update(auth)
            .set({ apiKeyRevokedAt: now })
            .where(eq(auth.id, DEFAULT_PROFILE_ID));

          await insertAuditLog("api_key_revoked", "admin", "manual_revocation");

          return status(HTTP_STATUS_OK, {
            revoked: true,
            message: "API key has been revoked.",
          });
        },
      ),
  );

import {
  API_ERROR_SKILL_MAPPING_ALREADY_DELETED,
  API_ERROR_SKILL_MAPPING_NOT_FOUND,
} from "@bao/shared/constants/api-errors";
import { API_MESSAGE_SKILL_MAPPING_DELETED } from "@bao/shared/constants/api-messages";
import { API_ENDPOINTS, toApiScopedPath } from "@bao/shared/constants/endpoints";
import {
  HTTP_STATUS_CREATED,
  HTTP_STATUS_GONE,
  HTTP_STATUS_INTERNAL_SERVER_ERROR,
  HTTP_STATUS_NOT_FOUND,
  HTTP_STATUS_OK,
} from "@bao/shared/constants/http";
import { Elysia } from "elysia";
import { skillMappingService } from "../services/skill-mapping-service";
import { skillAnalysisRateLimit } from "../utils/rate-limit";
import { analyzeSkillMappingsSafely } from "./skill-mapping-route-analysis";
import {
  type SkillMappingRouteSetState,
  skillAnalysisBodySchema,
  skillAnalysisResponses,
  skillMappingCreateBodySchema,
  skillMappingCreateResponses,
  skillMappingDeleteResponses,
  skillMappingIdParamsSchema,
  skillMappingsListResponses,
  skillMappingsQuerySchema,
  skillMappingUpdateBodySchema,
  skillMappingUpdateResponses,
  skillPathwaysResponses,
  skillReadinessQuerySchema,
  skillReadinessResponses,
} from "./skill-mapping-route-contracts";
import {
  createSkillMappingFromBody,
  deleteSkillMappingById,
  getSkillReadiness,
  listSkillMappings,
  updateSkillMappingFromBody,
} from "./skill-mapping-route-support";

export const skillMappingRoutes = new Elysia({
  prefix: toApiScopedPath(API_ENDPOINTS.skillsBase),
})
  .use(skillAnalysisRateLimit)
  .get(
    "/mappings",
    {
      detail: { tags: ["Skill Mapping"] },
      query: skillMappingsQuerySchema,
      response: skillMappingsListResponses,
    },
    async ({ query, status }) => status(HTTP_STATUS_OK, await listSkillMappings(query)),
  )
  .post(
    "/mappings",
    {
      detail: { tags: ["Skill Mapping"] },
      body: skillMappingCreateBodySchema,
      response: skillMappingCreateResponses,
    },
    async ({ body, status }) => {
      const result = await createSkillMappingFromBody(body);
      return status(HTTP_STATUS_CREATED, result.mapping);
    },
  )
  .put(
    "/mappings/:id",
    {
      detail: { tags: ["Skill Mapping"] },
      params: skillMappingIdParamsSchema,
      body: skillMappingUpdateBodySchema,
      response: skillMappingUpdateResponses,
    },
    async ({ params, body, status }) => {
      const state: SkillMappingRouteSetState = {};
      const result = await updateSkillMappingFromBody(params.id, body, state);
      if ("error" in result) {
        return status(HTTP_STATUS_NOT_FOUND, result);
      }
      return status(HTTP_STATUS_OK, result);
    },
  )
  .delete(
    "/mappings/:id",
    {
      detail: { tags: ["Skill Mapping"] },
      params: skillMappingIdParamsSchema,
      response: skillMappingDeleteResponses,
    },
    async ({ params, status }) => {
      const state: SkillMappingRouteSetState = {};
      const result = await deleteSkillMappingById(params.id, state);
      if (result.kind === "not-found") {
        return status(HTTP_STATUS_NOT_FOUND, { error: API_ERROR_SKILL_MAPPING_NOT_FOUND });
      }
      if (result.kind === "gone") {
        return status(HTTP_STATUS_GONE, {
          error: API_ERROR_SKILL_MAPPING_ALREADY_DELETED,
          id: params.id,
        });
      }
      return status(HTTP_STATUS_OK, { message: API_MESSAGE_SKILL_MAPPING_DELETED, id: params.id });
    },
  )
  .get(
    "/pathways",
    {
      detail: { tags: ["Skill Mapping"] },
      response: skillPathwaysResponses,
    },
    async ({ status }) => status(HTTP_STATUS_OK, await skillMappingService.getPathways()),
  )
  .get(
    "/readiness",
    {
      detail: { tags: ["Skill Mapping"] },
      query: skillReadinessQuerySchema,
      response: skillReadinessResponses,
    },
    async ({ query, status }) => status(HTTP_STATUS_OK, await getSkillReadiness(query.jobId)),
  )
  .post(
    "/ai-analyze",
    {
      detail: { tags: ["Skill Mapping"] },
      body: skillAnalysisBodySchema,
      response: skillAnalysisResponses,
    },
    async ({ body, status }) => {
      const state: SkillMappingRouteSetState = {};
      const result = await analyzeSkillMappingsSafely(body, state);
      if (state.status === HTTP_STATUS_INTERNAL_SERVER_ERROR) {
        return status(HTTP_STATUS_INTERNAL_SERVER_ERROR, result);
      }
      return status(HTTP_STATUS_OK, result);
    },
  );

