`;

const buildJobApplyFixtureHtml = (
  origin: string,
  options: JobApplyFixtureServerOptions,
): string => `<!doctype html>
<html lang="en">
  <body>
    <form action="${origin}/submit" method="post" enctype="multipart/form-data">
      <label for="candidate-name">Full name</label>
