import { Database } from "bun:sqlite";
import { afterEach, describe, expect, test } from "bun:test";
import { automationSettingsSchema } from "@bao/shared/schemas/settings.schema";
import { DEFAULT_PROFILE_ID, DEFAULT_SETTINGS_ID } from "@bao/shared/types/settings-defaults";
import { initializeDatabase } from "./init";

const transientDatabases: Database[] = [];

const createTransientDatabase = (): Database => {
  const sqlite = new Database(":memory:");
  transientDatabases.push(sqlite);
  return sqlite;
};

afterEach(() => {
  for (const sqlite of transientDatabases.splice(0)) {
    sqlite.close();
  }
});

describe("initializeDatabase", () => {
  test("creates singleton rows with valid default automation settings", () => {
    const sqlite = createTransientDatabase();

    initializeDatabase(sqlite);

    const settingsRow = sqlite
      .query("SELECT id, automation_settings FROM settings WHERE id = ? LIMIT 1")
      .get(DEFAULT_SETTINGS_ID) as
      | {
          id: string;
          automation_settings: string;
        }
      | undefined;
    const authRow = sqlite
      .query("SELECT id FROM auth WHERE id = ? LIMIT 1")
      .get(DEFAULT_PROFILE_ID) as { id: string } | undefined;
    const gamificationRow = sqlite
      .query("SELECT id FROM gamification WHERE id = ? LIMIT 1")
      .get(DEFAULT_PROFILE_ID) as { id: string } | undefined;
    const userProfileRow = sqlite
      .query("SELECT id FROM user_profile WHERE id = ? LIMIT 1")
      .get(DEFAULT_PROFILE_ID) as { id: string } | undefined;

    expect(settingsRow?.id).toBe(DEFAULT_SETTINGS_ID);
    expect(authRow?.id).toBe(DEFAULT_PROFILE_ID);
    expect(gamificationRow?.id).toBe(DEFAULT_PROFILE_ID);
    expect(userProfileRow?.id).toBe(DEFAULT_PROFILE_ID);

    const parsedAutomationSettings = automationSettingsSchema.safeParse(
      settingsRow ? JSON.parse(settingsRow.automation_settings) : undefined,
    );
    expect(parsedAutomationSettings.success).toBe(true);
    if (!parsedAutomationSettings.success) {
      return;
    }

    expect(parsedAutomationSettings.data.jobProviders).toBeDefined();
    expect(parsedAutomationSettings.data.jobProviders?.hitmarkerEnabled).toBe(true);
    const hitmarkerPortal = parsedAutomationSettings.data.jobProviders?.gamingPortals?.find(
      (portal) => portal.id === "hitmarker",
    );
    expect(hitmarkerPortal?.enabled).toBe(true);
  });
});

import type { Database } from "bun:sqlite";
import {
  AUTH_REQUIRED_COLUMNS,
  AUTH_TABLE_NAME,
  AUTOMATION_RUNS_REQUIRED_COLUMNS,
  AUTOMATION_RUNS_TABLE_NAME,
  JOBS_REQUIRED_COLUMNS,
  JOBS_TABLE_NAME,
  SETTINGS_REQUIRED_COLUMNS,
  SETTINGS_TABLE_NAME,
  STUDIOS_REQUIRED_COLUMNS,
  STUDIOS_TABLE_NAME,
} from "./init-constants";
import { DEFAULT_PROFILE_ID, DEFAULT_SETTINGS_ID } from "./init-schema";

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const ensureSingletonRows = (sqlite: Database): void => {
  sqlite.exec(`INSERT OR IGNORE INTO settings (id) VALUES ('${DEFAULT_SETTINGS_ID}')`);
  sqlite.exec(`INSERT OR IGNORE INTO auth (id) VALUES ('${DEFAULT_PROFILE_ID}')`);
  sqlite.exec(`INSERT OR IGNORE INTO gamification (id) VALUES ('${DEFAULT_PROFILE_ID}')`);
  sqlite.exec(`INSERT OR IGNORE INTO user_profile (id) VALUES ('${DEFAULT_PROFILE_ID}')`);
};

const readTableColumnNames = (sqlite: Database, tableName: string): Set<string> => {
  const rows = sqlite.query(`PRAGMA table_info(${tableName})`).all();
  const names = new Set<string>();

  for (const row of rows) {
    if (!isRecord(row)) {
      continue;
    }
    const name = row.name;
    if (typeof name === "string" && name.length > 0) {
      names.add(name);
    }
  }

  return names;
};

const ensureColumns = (
  sqlite: Database,
  tableName: string,
  requiredColumns: Record<string, string>,
): void => {
  const existingColumns = readTableColumnNames(sqlite, tableName);

  for (const [columnName, columnDefinition] of Object.entries(requiredColumns)) {
    if (existingColumns.has(columnName)) {
      continue;
    }
    sqlite.exec(`ALTER TABLE ${tableName} ADD COLUMN ${columnName} ${columnDefinition}`);
  }
};

export const ensureDatabaseMigrations = (sqlite: Database): void => {
  ensureColumns(sqlite, AUTH_TABLE_NAME, AUTH_REQUIRED_COLUMNS);
  ensureColumns(sqlite, AUTOMATION_RUNS_TABLE_NAME, AUTOMATION_RUNS_REQUIRED_COLUMNS);
  ensureColumns(sqlite, SETTINGS_TABLE_NAME, SETTINGS_REQUIRED_COLUMNS);
  ensureColumns(sqlite, JOBS_TABLE_NAME, JOBS_REQUIRED_COLUMNS);
  ensureColumns(sqlite, STUDIOS_TABLE_NAME, STUDIOS_REQUIRED_COLUMNS);
  ensureSingletonRows(sqlite);
};

