    .insert(auth)
    .values({
      id: DEFAULT_PROFILE_ID,
      apiKeyHash: keyHash,
      apiKeyCreatedAt: new Date().toISOString(),
      apiKeyExpiresAt: null,
      apiKeyRevokedAt: null,
    })
    .onConflictDoUpdate({
      target: auth.id,
      set: {
