    packageName: "playwright",
    requiredInstalled: "1.61.1",
    requiredPrefix: "1.6",
    resolveFromPackage: ".",
  },
] as const;

export type ResolvedPackageVersion = {
  packageName: string;
  installedVersion: string;
  packageJsonPath: string;
};

export const readPackageVersionFromJson = (
  packageName: string,
  packageJsonContent: string,
): string | null => {
  const parsed: unknown = JSON.parse(packageJsonContent);
  if (
    typeof parsed !== "object" ||
    parsed === null ||
    !("version" in parsed) ||
    typeof parsed.version !== "string"
  ) {
    return null;
  }
  if (!("name" in parsed) || parsed.name !== packageName) {
    return null;
  }
  return parsed.version;
};

export const collectStackVersionViolations = (
  pins: readonly StackVersionPin[],
  resolved: ReadonlyArray<ResolvedPackageVersion | { packageName: string; error: string }>,
  rootOverrides: Readonly<Record<string, string>>,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  const byName = new Map(resolved.map((entry) => [entry.packageName, entry]));

  for (const pin of pins) {
    const override = rootOverrides[pin.packageName];
    if (override && override !== pin.requiredInstalled) {
      violations.push({
        filePath: "package.json",
        line: 1,
        message: `Root override for "${pin.packageName}" is "${override}" but STACK pin requires "${pin.requiredInstalled}".`,
      });
    }

    const entry = byName.get(pin.packageName);
    if (!entry) {
      violations.push({
        filePath: pin.resolveFromPackage,
        line: 1,
        message: `Missing resolved install for "${pin.packageName}".`,
      });
      continue;
    }
    if ("error" in entry) {
      violations.push({
        filePath: pin.resolveFromPackage,
        line: 1,
        message: `Failed to resolve "${pin.packageName}": ${entry.error}`,
      });
      continue;
    }
    if (entry.installedVersion !== pin.requiredInstalled) {
      violations.push({
        filePath: entry.packageJsonPath,
        line: 1,
        message: `Installed "${pin.packageName}@${entry.installedVersion}" drifts from STACK pin "${pin.requiredInstalled}".`,
      });
    }
    if (pin.requiredPrefix && !entry.installedVersion.startsWith(pin.requiredPrefix)) {
      violations.push({
        filePath: entry.packageJsonPath,
        line: 1,
        message: `Installed "${pin.packageName}@${entry.installedVersion}" must start with "${pin.requiredPrefix}" (Elysia 2 / OpenAPI 2 contract).`,
      });
    }
  }

  return violations;
};

const resolveInstalledPackage = async (
  rootDir: string,
  pin: StackVersionPin,
): Promise<ResolvedPackageVersion | { packageName: string; error: string }> => {
  const fromPackageDir = join(rootDir, pin.resolveFromPackage);
  const resolveResult = await settle(
    Promise.resolve().then(() =>
      Bun.resolveSync(`${pin.packageName}/package.json`, fromPackageDir),
    ),
  );
  if (resolveResult.status === "rejected") {
    return {
      packageName: pin.packageName,
      error: resolveResult.reason.message,
    };
  }
  const resolvedPath = resolveResult.value;
  const content = await Bun.file(resolvedPath).text();
  const version = readPackageVersionFromJson(pin.packageName, content);
  if (!version) {
    return {
      packageName: pin.packageName,
      error: `package.json at ${resolvedPath} missing name/version for ${pin.packageName}`,
    };
  }
  return {
    packageName: pin.packageName,
    installedVersion: version,
    packageJsonPath: resolvedPath
      .replace(/\\/gu, "/")
      .replace(`${rootDir.replace(/\\/gu, "/")}/`, ""),
  };
};

export const collectWorkspaceStackVersionViolations = async (
  rootDir: string = process.cwd(),
): Promise<ValidationViolation[]> => {
  const rootPackageJson = JSON.parse(await Bun.file(join(rootDir, "package.json")).text()) as {
    overrides?: Record<string, string>;
  };
  const overrides = rootPackageJson.overrides ?? {};
  const resolved = await Promise.all(
    STACK_VERSION_PINS.map((pin) => resolveInstalledPackage(rootDir, pin)),
  );
  return collectStackVersionViolations(STACK_VERSION_PINS, resolved, overrides);
};

if (import.meta.main) {
  await reportViolations(
    "Stack version pin validation failed:",
    await collectWorkspaceStackVersionViolations(),
    "Stack version pin validation passed (installed == STACK-CONTRACT pins).",
  );
}

const NUM_80 = 80;
/**
 * Ban raw inset panel / nested surface literals in Vue surfaces.
 * Use INSET_PANEL_CLASS / INSET_PANEL_MUTED_CLASS / INSET_LIST_CLASS / FIELDSET_PANEL_CLASS.
 *
 * Product SSOT is TS/CSS tokens (STACK-CONTRACT) — not .bao archives.
 */
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts"]);

const ALLOW_PATH_MARKERS = [
  "packages/client/constants/layout-shell.ts",
  "packages/client/constants/layout.ts",
  "packages/client/constants/layout-tokens.ts",
  "packages/client/constants/ui-layout.ts",
  "packages/client/constants/chat.ts",
] as const;

/** Full inset panel chrome (solid nest inside glass). */
const BANNED_INSET_PANEL =
  /(["'`])(?:(?!\1)[^\\]|\\.)*rounded-box\s+border\s+border-base-300\s+bg-base-(?:100|200)(?:(?!\1)[^\\]|\\.)*\1/gu;

/** daisyUI list + inset chrome. */
const BANNED_INSET_LIST =
  /(["'`])(?:(?!\1)[^\\]|\\.)*list\s+rounded-box\s+border\s+border-base-300\s+bg-base-100(?:(?!\1)[^\\]|\\.)*\1/gu;

/** Fieldset panel chrome. */
const BANNED_FIELDSET_PANEL =
  /(["'`])(?:(?!\1)[^\\]|\\.)*fieldset(?:(?!\1)[^\\]|\\.)*rounded-box\s+border\s+border-base-300\s+bg-base-100(?:(?!\1)[^\\]|\\.)*\1/gu;

const HTML_COMMENT_PATTERN = /<!--[\s\S]*?-->/gu;
const BLOCK_COMMENT_PATTERN = /\/\*[\s\S]*?\*\//gu;
const LINE_COMMENT_PATTERN = /\/\/[^\n\r]*/gu;

const stripComments = (content: string): string =>
  content
    .replace(HTML_COMMENT_PATTERN, "")
    .replace(BLOCK_COMMENT_PATTERN, "")
    .replace(LINE_COMMENT_PATTERN, "");

const isAllowlisted = (filePath: string): boolean =>
  ALLOW_PATH_MARKERS.some((marker) => filePath.endsWith(marker) || filePath.includes(marker));

const MAX_MATCH_CHARS = 220;

export const collectInsetPanelSsotViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isAllowlisted(filePath)) {
    return [];
  }
  const violations: ValidationViolation[] = [];
  const stripped = stripComments(content);

  const pushMatches = (pattern: RegExp, message: string): void => {
    pattern.lastIndex = 0;
    for (const match of stripped.matchAll(pattern)) {
      const quoted = match[0] ?? "";
      if (quoted.length > MAX_MATCH_CHARS) {
        continue;
      }
      if (
        quoted.includes("INSET_PANEL") ||
        quoted.includes("INSET_LIST") ||
        quoted.includes("FIELDSET_PANEL")
      ) {
        continue;
      }
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `${message} (${quoted.slice(0, NUM_80)}…)`,
      });
    }
  };

  pushMatches(
    BANNED_INSET_PANEL,
    "raw inset panel literal; use INSET_PANEL_CLASS or INSET_PANEL_MUTED_CLASS",
  );
  pushMatches(BANNED_INSET_LIST, "raw inset list literal; use INSET_LIST_CLASS");
  pushMatches(BANNED_FIELDSET_PANEL, "raw fieldset panel literal; use FIELDSET_PANEL_CLASS");

  return violations;
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const entries = await collectProjectFileEntries({
    scanRoots: [...scanRoots],
    allowedExtensions: [...sourceExtensions],
  });
  return entries.flatMap((entry) =>
    collectInsetPanelSsotViolationsForContent(entry.filePath, entry.content),
  );
};

if (import.meta.main) {
