const NUM_240 = 240;
const NUM_360 = 360;
const NUM_40 = 40;
const NUM_44 = 44;
const RATIO_0_5 = 0.5;
/**
 * DOM signal collectors for browser-visual-smoke (line/complexity split).
 */
import type { Page } from "playwright";
import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import { settle } from "../packages/shared/src/utils/promise";

export type PageSignals = {
  readonly h1: string | null;
  readonly mainCount: number;
  readonly bodySnippet: string;
  readonly dockActive: readonly { href: string | null; label: string }[];
  readonly tables: readonly { width: number; visible: boolean }[];
  readonly underTouch: readonly { label: string; h: number; under: boolean }[];
  readonly setupXpConflict: boolean;
  readonly floatingChatVisible: boolean;
  readonly dockHasAiChat: boolean;
};

const collectLandmarkSignals = async (page: Page) =>
  page.evaluate(() => {
    const collapse = (value: string): string => value.replace(/\s+/gu, " ").trim();
    const h1 = document.querySelector("h1");
    return {
      h1: h1?.textContent ? collapse(h1.textContent) : null,
      mainCount: document.querySelectorAll("main").length,
      bodySnippet: collapse(document.body?.innerText ?? "").slice(0, NUM_240),
      dockActive: Array.from(
        document.querySelectorAll('nav.dock a[aria-current="page"], nav.dock a.dock-active'),
      ).map((el) => ({
        href: el.getAttribute("href"),
        label: collapse(el.getAttribute("aria-label") ?? el.textContent ?? ""),
      })),
      tables: Array.from(document.querySelectorAll("table.table")).map((table) => {
        const rect = table.getBoundingClientRect();
        return { width: rect.width, visible: rect.width > 0 && rect.height > 0 };
      }),
    };
  });

const collectTouchSignals = async (page: Page) =>
  page.evaluate(() => {
    const collapse = (value: string): string => value.replace(/\s+/gu, " ").trim();
    const underTouch = Array.from(
      document.querySelectorAll(
        "nav.dock a, .menu a.min-h-11, .menu a.h-11, .menu button.min-h-11",
      ),
    )
      .map((el) => {
        const rect = el.getBoundingClientRect();
        const style = getComputedStyle(el);
        if (
          rect.width <= 0 ||
          rect.height <= 0 ||
          style.visibility === "hidden" ||
          style.display === "none"
        ) {
          return null;
        }
        const details = el.closest("details");
        if (details && !details.open) return null;
        return {
          label: collapse(el.getAttribute("aria-label") ?? el.textContent ?? "").slice(0, NUM_40),
          h: rect.height,
          under: rect.height + RATIO_0_5 < NUM_44,
        };
      })
      .filter((row): row is { label: string; h: number; under: boolean } => Boolean(row?.under));
    return { underTouch };
  });

const collectChatChromeSignals = async (page: Page) =>
  page.evaluate((aiRoutePrefix: string) => {
    const collapse = (value: string): string => value.replace(/\s+/gu, " ").trim();
    const isLevelLabel = (value: string): boolean => {
      if (!value.startsWith("Level ")) return false;
      const digits = value.slice("Level ".length);
      return digits.length > 0 && [...digits].every((char) => char >= "0" && char <= "9");
    };
    const setupCtaVisible = Array.from(document.querySelectorAll("a.btn, button.btn")).some(
      (el) => {
        const rect = el.getBoundingClientRect();
        return (
          rect.width > 0 &&
          rect.height > 0 &&
          collapse(el.textContent ?? "")
            .toLowerCase()
            .includes("complete setup")
        );
      },
    );
    const levelLabelVisible = Array.from(document.querySelectorAll("p, span, h2, h3, div")).some(
      (el) => {
        if (el.childElementCount > 2) return false;
        const rect = el.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0 && isLevelLabel(collapse(el.textContent ?? ""));
      },
    );
    const floatingChatVisible = [...document.querySelectorAll("button, a")].some((el) => {
      const rect = el.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) return false;
      const aria = (el.getAttribute("aria-label") ?? "").toLowerCase();
      return aria.includes("floating chat") || aria.includes("show floating chat");
    });
    const dockHasAiChat = [...document.querySelectorAll("nav.dock a")].some((a) => {
      const href = a.getAttribute("href") ?? "";
      return href === aiRoutePrefix || href.startsWith(`${aiRoutePrefix}/`);
    });
    return {
      setupXpConflict: setupCtaVisible && levelLabelVisible,
      floatingChatVisible,
      dockHasAiChat,
    };
  }, APP_ROUTES.ai);

const collectPageSignalsOnce = async (page: Page): Promise<PageSignals> => {
  const landmarks = await collectLandmarkSignals(page);
  const touch = await collectTouchSignals(page);
  const chat = await collectChatChromeSignals(page);
  return {
    h1: landmarks.h1,
    mainCount: landmarks.mainCount,
    bodySnippet: landmarks.bodySnippet,
    dockActive: landmarks.dockActive,
    tables: landmarks.tables,
    underTouch: touch.underTouch,
    setupXpConflict: chat.setupXpConflict,
    floatingChatVisible: chat.floatingChatVisible,
    dockHasAiChat: chat.dockHasAiChat,
  };
};

export const collectPageSignals = async (page: Page): Promise<PageSignals> => {
  // HMR/soft-nav can destroy evaluate mid-flight — settle + single retry after ready.
  const first = await settle(collectPageSignalsOnce(page));
  if (first.status === "fulfilled") {
    return first.value;
  }
  await settle(page.waitForLoadState("domcontentloaded", { timeout: 15_000 }));
  const second = await settle(collectPageSignalsOnce(page));
  if (second.status === "fulfilled") {
    return second.value;
  }
  throw first.reason instanceof Error
    ? first.reason
    : new Error(String(first.reason ?? "collectPageSignals failed"));
};

export const isMobileAiOrAutomationRoute = (route: string): boolean =>
  route === APP_ROUTES.ai ||
  route.startsWith(`${APP_ROUTES.ai}/`) ||
  route === APP_ROUTES.automation ||
  route.startsWith(`${APP_ROUTES.automation}/`);

const scoreMobileSignals = (route: string, signals: PageSignals): string | null => {
  if (isMobileAiOrAutomationRoute(route) && signals.dockActive.length === 0) {
    return `dock orphan on ${route} — expected aria-current/dock-active`;
  }
  if (
    route === APP_ROUTES.automationRuns &&
    signals.tables.some((table) => table.visible && table.width > NUM_360)
  ) {
    const maxWidth = Math.max(
      0,
      ...signals.tables.filter((table) => table.visible).map((table) => table.width),
    );
    return `automation runs table still wide @320 (max visible ${String(maxWidth)}px)`;
  }
  if (signals.underTouch.length > 0) {
    return `touch target under 44px: ${signals.underTouch[0]?.label ?? "unknown"} (${String(
      signals.underTouch[0]?.h ?? 0,
    )}px)`;
  }
  if (signals.floatingChatVisible && signals.dockHasAiChat) {
    return "dual chat chrome: floating FAB + dock AI Chat below lg";
  }
  return null;
};

export const scoreSmokeRoute = (
  viewportName: string,
  route: string,
  title: string,
  signals: PageSignals,
  pageErrors: readonly string[],
): string | null => {
  if (signals.mainCount !== 1) {
    return `expected 1 main landmark, got ${String(signals.mainCount)}`;
  }
  if (!signals.h1 || signals.h1.length === 0) return "missing h1";
  if (title.trim().length === 0) return "empty title";
  if (pageErrors.length > 0) return `pageerror: ${pageErrors[0] ?? "unknown"}`;
  if (route === APP_ROUTES.dashboard && signals.setupXpConflict) {
    return "dashboard Setup CTA vs Level/XP gamification contradiction";
  }
  if (viewportName === "mobile") {
    return scoreMobileSignals(route, signals);
  }
  return null;
};

import enUS from "../packages/client/locales/en-US";
import { writeError, writeOutput } from "./utils/cli-output";
import { getLineFromOffset, shouldIgnorePath } from "./utils/validation-helpers";

type Violation = {
  filePath: string;
  line: number;
  message: string;
};

type TemplateBlock = {
  content: string;
  offset: number;
};

type TemplateTag = {
  markup: string;
  offset: number;
};

type TemplateTextSegment = {
  text: string;
  offset: number;
};

type LocalePathFrame = {
  pathValue: string;
  node: unknown;
};

type TemplateTextScanState = {
  inTag: boolean;
  inInterpolation: boolean;
  quote: "'" | '"' | null;
  textStart: number;
  index: number;
};

type TemplateCharacterWindow = {
  char: string;
  nextChar: string;
};

const projectRoot = process.cwd();
const sourceRoots = ["packages/client", "packages/shared/src"] as const;
const sourceExtensions = new Set([".vue", ".ts", ".tsx", ".js", ".mjs", ".cjs"]);

const translationCallPattern = /(?:\b\$?t)\(\s*(['"`])([^'"`]+)\1/gu;
const staticAttributePattern =
  /(?<![:\w-])(aria-label|aria-description|aria-placeholder|placeholder|title|alt|data-tip)\s*=\s*("([^"]*)"|'([^']*)')/gu;
const boundAttributeLiteralPattern =
  /(?:\s|<)(?::|v-bind:)(aria-label|aria-description|aria-placeholder|placeholder|title|alt|data-tip)\s*=\s*("([^"]*)"|'([^']*)')/gu;
const templateInterpolationPattern = /\{\{[\s\S]*?\}\}/gu;
const whitespacePattern = /\s+/gu;
const localeKeyFormatPattern = /^[a-zA-Z0-9_.-]+$/u;
const punctuationOnlyPattern = /^[\d\s+./,:;!?()[\]{}<>=_%|*&'"`~-]+$/u;
const humanTextPattern = /\p{L}/u;
const templateOpenToken = "{{";
const templateCloseToken = "}}";
const tagOpenToken = "<";
const tagCloseToken = ">";
const closingTagPrefix = "</";
const declarationTagPrefix = "<!";

const hasSourceExtension = (pathValue: string): boolean => {
  for (const extension of sourceExtensions) {
    if (pathValue.endsWith(extension)) {
      return true;
    }
  }
  return false;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const createChildPath = (pathValue: string, child: string | number): string =>
  pathValue.length > 0 ? `${pathValue}.${child}` : `${child}`;

const collectChildLocaleFrames = (frame: LocalePathFrame, stack: LocalePathFrame[]): void => {
  if (Array.isArray(frame.node)) {
    for (let index = frame.node.length - 1; index >= 0; index -= 1) {
      stack.push({
        pathValue: createChildPath(frame.pathValue, index),
        node: frame.node[index],
      });
    }
    return;
  }

  if (!isRecord(frame.node)) {
    return;
  }

  const entries = Object.entries(frame.node);
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const [key, childNode] = entries[index];
    stack.push({
      pathValue: createChildPath(frame.pathValue, key),
      node: childNode,
    });
  }
};

const collectLocalePaths = (value: unknown): Set<string> => {
  const keys = new Set<string>();
  const stack: LocalePathFrame[] = [{ pathValue: "", node: value }];

  while (stack.length > 0) {
    const frame = stack.pop();
    if (!frame) {
      continue;
    }

    if (frame.pathValue.length > 0) {
      keys.add(frame.pathValue);
    }

    if (typeof frame.node !== "string") {
      collectChildLocaleFrames(frame, stack);
    }
  }
  return keys;
};

const scanSourceRoot = async (sourceRoot: (typeof sourceRoots)[number]): Promise<string[]> => {
  const glob = new Bun.Glob(`${sourceRoot}/**/*`);
  const relativeFilePaths = await Array.fromAsync(glob.scan({ cwd: projectRoot, onlyFiles: true }));

  return relativeFilePaths.flatMap((relativeFilePath) => {
    const normalizedPath = relativeFilePath.replace(/\\/gu, "/");
    if (shouldIgnorePath(normalizedPath) || !hasSourceExtension(normalizedPath)) {
      return [];
    }
    return [normalizedPath];
  });
};

const collectSourceFiles = async (): Promise<string[]> => {
  const perRootFiles = await Promise.all(
    sourceRoots.map((sourceRoot) => scanSourceRoot(sourceRoot)),
  );
  return perRootFiles.flat();
};

const localizedDomainOutputPatterns: Array<{ pattern: RegExp; label: string }> = [
  { pattern: /\{\{\s*job\.experienceLevel\s*\}\}/gu, label: "job.experienceLevel" },
  { pattern: /\{\{\s*job\.studioType\s*\}\}/gu, label: "job.studioType" },
  { pattern: /\{\{\s*job\.platforms?\s*\}\}/gu, label: "job.platforms" },
  { pattern: /\{\{\s*job\.gameGenres?\s*\}\}/gu, label: "job.gameGenres" },
  { pattern: /\{\{\s*studio\.type\s*\}\}/gu, label: "studio.type" },
  { pattern: /\{\{\s*studio\.size\s*\}\}/gu, label: "studio.size" },
  { pattern: /<option\b[^>]*>\s*\{\{\s*type\s*\}\}\s*<\/option>/gu, label: "studio type option" },
  { pattern: /<option\b[^>]*>\s*\{\{\s*size\s*\}\}\s*<\/option>/gu, label: "studio size option" },
];

const collectLocalizedDomainOutputViolations = (
  filePath: string,
  fileContent: string,
): Violation[] => {
  const violations: Violation[] = [];

  for (const { pattern, label } of localizedDomainOutputPatterns) {
    for (const match of fileContent.matchAll(pattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(fileContent, match.index ?? 0),
        message: `${label} must be localized with a shared label resolver instead of raw output.`,
      });
    }
  }

  return violations;
};

const extractTemplateBlocks = (fileContent: string): TemplateBlock[] => {
  const blocks: TemplateBlock[] = [];
  const openTagPattern = /<template\b[^>]*>/giu;
  let openMatch = openTagPattern.exec(fileContent);

  while (openMatch) {
    const openTag = openMatch[0];
    const startOffset = (openMatch.index ?? 0) + openTag.length;
    const closeOffset = fileContent.indexOf("</template>", startOffset);
    if (closeOffset === -1) {
      break;
    }
    blocks.push({
      content: fileContent.slice(startOffset, closeOffset),
      offset: startOffset,
    });
    openTagPattern.lastIndex = closeOffset + "</template>".length;
    openMatch = openTagPattern.exec(fileContent);
  }

  return blocks;
};

const isQuoteCharacter = (char: string): char is "'" | '"' => char === "'" || char === '"';

const isTemplateTagCandidate = (markup: string): boolean =>
  !(markup.startsWith(closingTagPrefix) || markup.startsWith(declarationTagPrefix));

const findTagCloseOffset = (templateContent: string, openOffset: number): number => {
  const contentLength = templateContent.length;
  let cursor = openOffset + 1;
  let quote: "'" | '"' | null = null;

  while (cursor < contentLength) {
    const char = templateContent[cursor];
    if (quote) {
      if (char === quote) {
        quote = null;
      }
      cursor += 1;
      continue;
    }

    if (isQuoteCharacter(char)) {
      quote = char;
      cursor += 1;
      continue;
    }

    if (char === tagCloseToken) {
      return cursor;
    }

    cursor += 1;
  }

  return -1;
};

const collectTemplateTags = (templateContent: string): TemplateTag[] => {
  const tags: TemplateTag[] = [];
  const contentLength = templateContent.length;
  let index = 0;

  while (index < contentLength) {
    const openOffset = templateContent.indexOf(tagOpenToken, index);
    if (openOffset === -1) {
      break;
    }

    const closeOffset = findTagCloseOffset(templateContent, openOffset);
    if (closeOffset === -1) {
      break;
    }

    const markup = templateContent.slice(openOffset, closeOffset + 1);
    if (isTemplateTagCandidate(markup)) {
      tags.push({
        markup,
        offset: openOffset,
      });
    }

    index = closeOffset + 1;
  }

  return tags;
};

const appendTextSegment = (
  segments: TemplateTextSegment[],
  templateContent: string,
  textStart: number,
  textEnd: number,
): void => {
  if (textEnd <= textStart) {
    return;
  }

  segments.push({
    text: templateContent.slice(textStart, textEnd),
    offset: textStart,
  });
};

const isTokenPair = (char: string, nextChar: string, token: string): boolean =>
  char === token[0] && nextChar === token[1];

const advanceTagState = (state: TemplateTextScanState, char: string): void => {
  if (state.quote) {
    if (char === state.quote) {
      state.quote = null;
    }
    return;
  }

  if (isQuoteCharacter(char)) {
    state.quote = char;
    return;
  }

  if (char === tagCloseToken) {
    state.inTag = false;
    state.textStart = state.index + 1;
  }
};

const advanceTextState = (
  state: TemplateTextScanState,
  segments: TemplateTextSegment[],
  templateContent: string,
  charWindow: TemplateCharacterWindow,
): number => {
  const { char, nextChar } = charWindow;
  if (state.inInterpolation) {
    if (isTokenPair(char, nextChar, templateCloseToken)) {
      state.inInterpolation = false;
      return 2;
    }
    return 1;
  }

  if (isTokenPair(char, nextChar, templateOpenToken)) {
    state.inInterpolation = true;
    return 2;
  }

  if (char === tagOpenToken) {
    appendTextSegment(segments, templateContent, state.textStart, state.index);
    state.inTag = true;
  }

  return 1;
};

const collectTemplateTextSegments = (templateContent: string): TemplateTextSegment[] => {
  const segments: TemplateTextSegment[] = [];
  const state: TemplateTextScanState = {
    inTag: false,
    inInterpolation: false,
    quote: null,
    textStart: 0,
    index: 0,
  };

  while (state.index < templateContent.length) {
    const char = templateContent[state.index];
    const nextChar =
      state.index + 1 < templateContent.length ? templateContent[state.index + 1] : "";

    if (state.inTag) {
      advanceTagState(state, char);
      state.index += 1;
      continue;
    }

    const offsetDelta = advanceTextState(state, segments, templateContent, { char, nextChar });
    state.index += offsetDelta;
  }

  if (!state.inTag) {
    appendTextSegment(segments, templateContent, state.textStart, templateContent.length);
  }

  return segments;
};

const hasHumanText = (value: string): boolean => humanTextPattern.test(value);

const normalizeTemplateText = (value: string): string =>
  value.replace(templateInterpolationPattern, " ").replace(whitespacePattern, " ").trim();

const isIgnoredTemplateText = (value: string): boolean => {
  if (value.length === 0) {
    return true;
  }
  if (punctuationOnlyPattern.test(value)) {
    return true;
  }
  if (value === "&nbsp;") {
    return true;
  }
  return false;
};

const collectMissingTranslationKeyViolations = (
  filePath: string,
  fileContent: string,
  localeKeys: Set<string>,
): Violation[] => {
  const violations: Violation[] = [];

  for (const match of fileContent.matchAll(translationCallPattern)) {
    const key = match[2]?.trim() ?? "";
    if (!localeKeyFormatPattern.test(key)) {
      continue;
    }
    if (localeKeys.has(key)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, match.index ?? 0),
      message: `Missing translation key in en-US locale: "${key}"`,
    });
  }

  return violations;
};

const isQuotedLiteralExpression = (expression: string): boolean => {
  const opensWithSingleQuote = expression.startsWith("'");
  const closesWithSingleQuote = expression.endsWith("'");
  const opensWithDoubleQuote = expression.startsWith('"');
  const closesWithDoubleQuote = expression.endsWith('"');
  const opensWithBacktick = expression.startsWith("`");
  const closesWithBacktick = expression.endsWith("`");

  return (
    (opensWithSingleQuote && closesWithSingleQuote) ||
    (opensWithDoubleQuote && closesWithDoubleQuote) ||
    (opensWithBacktick && closesWithBacktick && !expression.includes("${"))
  );
};

const collectStaticAttributeViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
  tag: TemplateTag,
): Violation[] => {
  const violations: Violation[] = [];
  for (const match of tag.markup.matchAll(staticAttributePattern)) {
    const attributeName = match[1] ?? "";
    const value = (match[3] ?? match[4] ?? "").trim();
    if (value.length === 0 || !hasHumanText(value)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, block.offset + tag.offset + (match.index ?? 0)),
      message: `Static template attribute "${attributeName}" contains user-visible text. Use i18n binding (for example :${attributeName}="t('...')").`,
    });
  }
  return violations;
};

const collectBoundLiteralAttributeViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
  tag: TemplateTag,
): Violation[] => {
  const violations: Violation[] = [];
  for (const match of tag.markup.matchAll(boundAttributeLiteralPattern)) {
    const attributeName = match[1] ?? "";
    const expression = (match[3] ?? match[4] ?? "").trim();
    if (expression.length < 2 || !isQuotedLiteralExpression(expression)) {
      continue;
    }

    const literalValue = expression.slice(1, -1).trim();
    if (literalValue.length === 0 || !hasHumanText(literalValue)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, block.offset + tag.offset + (match.index ?? 0)),
      message:
        `Bound template attribute "${attributeName}" uses a literal string expression. ` +
        `Use i18n binding (for example :${attributeName}="t('...')").`,
    });
  }
  return violations;
};

const collectAttributeViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
  tag: TemplateTag,
): Violation[] => [
  ...collectStaticAttributeViolations(filePath, fileContent, block, tag),
  ...collectBoundLiteralAttributeViolations(filePath, fileContent, block, tag),
];

const collectTextViolations = (
  filePath: string,
  fileContent: string,
  block: TemplateBlock,
): Violation[] => {
  const violations: Violation[] = [];
  for (const segment of collectTemplateTextSegments(block.content)) {
    const normalizedText = normalizeTemplateText(segment.text);
    if (isIgnoredTemplateText(normalizedText) || !hasHumanText(normalizedText)) {
      continue;
    }

    violations.push({
      filePath,
      line: getLineFromOffset(fileContent, block.offset + segment.offset),
      message: `Static template text "${normalizedText}" detected. Use translation keys with t('...') for user-visible copy.`,
    });
  }
  return violations;
};

const collectStaticTemplateViolations = (filePath: string, fileContent: string): Violation[] =>
  extractTemplateBlocks(fileContent).flatMap((block) => {
    const attributeViolations = collectTemplateTags(block.content).flatMap((tag) =>
      collectAttributeViolations(filePath, fileContent, block, tag),
    );
    const textViolations = collectTextViolations(filePath, fileContent, block);
    return [...attributeViolations, ...textViolations];
  });

const collectViolations = async (): Promise<Violation[]> => {
  const localeKeys = collectLocalePaths(enUS);
  const files = await collectSourceFiles();
  const violationGroups = await Promise.all(
    files.map(async (filePath) => {
      const fileContent = await Bun.file(filePath).text();
      const fileViolations = collectMissingTranslationKeyViolations(
        filePath,
        fileContent,
        localeKeys,
      );
      if (filePath.endsWith(".vue")) {
        fileViolations.push(...collectStaticTemplateViolations(filePath, fileContent));
        fileViolations.push(...collectLocalizedDomainOutputViolations(filePath, fileContent));
      }
      return fileViolations;
    }),
  );

  return violationGroups.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();

  if (violations.length === 0) {
    await writeOutput(
      "UI i18n validation passed: no missing translation keys or static UI text/attributes detected.",
    );
    return;
  }

  await writeError(
    "UI i18n validation failed. Replace static user-visible copy with i18n keys and ensure all keys exist in en-US locale:",
  );
  const lines = violations.map(
    (violation) => `- ${violation.filePath}:${violation.line} ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }
  process.exit(1);
};

await main();

import { describe, expect, test } from "bun:test";
import { collectViolations } from "./validate-i18n-parity";

describe("validate-i18n-parity", () => {
  test("raw critical + coverage ratchet passes on current catalogs", () => {
    const violations = collectViolations();
    expect(violations).toEqual([]);
  });
});

import { isControlPrimitiveOwner } from "./ui-control-primitive-owners";
import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue"]);

const isSsotPrimitive = (filePath: string): boolean =>
  isUiSsotAuthority(filePath) || isControlPrimitiveOwner(filePath);

const CARD_GLASS_LITERAL_PATTERN =
  /card\s+card-border\s+card-glass(?:\s+glass-(?:interactive|strong|modal))?/gu;
/** Bare card-glass / card-glass-strong class tokens outside SSOT authority. */
const BARE_CARD_GLASS_CLASS_PATTERN = /\bcard-glass(?:-strong|-modal)?\b/gu;
const HARDCODED_LOADING_LABEL_PATTERN = /\blabel\s*=\s*["']Loading["']/gu;
const RAW_DESCRIPTION_CLASS_PATTERN = /description-class\s*=\s*["']text-(?:muted|secondary)["']/gu;
const SURFACE_GLASS_CONSTANT_REFERENCE_PATTERN =
  /SURFACE_GLASS_CARD_(?:STRONG_)?(?:MODAL_)?CLASS\b/u;
/** Canonical card owner — only this SFC may bind SURFACE_GLASS_CARD_*CLASS. */
const UI_GLASS_CARD_PRIMITIVE_PATH = "packages/client/components/ui/UiGlassCard.vue";
const SURFACE_GLASS_CARD_CLASS_TOKEN_PATTERN = /\bSURFACE_GLASS_CARD_(?:STRONG_|MODAL_)?CLASS\b/gu;
const SURFACE_GLASS_CARD_CLASS_IMPORT_PATTERN =
  /import\s*\{[^}]*\bSURFACE_GLASS_CARD_(?:STRONG_|MODAL_)?CLASS\b[^}]*\}\s*from\s*["'][^"']*constants\/layout(?:\/[^"']*)?["']/u;
const IMPORT_STATEMENT_PATTERN = /\bimport\b/u;
const UI_GLASS_CARD_COMPONENT_REFERENCE = /<UiGlassCard\b/u;
const LOADING_SPINNER_LITERAL_PATTERN = /loading\s+loading-spinner\b/gu;
const LOADING_SPINNER_PRIMITIVE_REFERENCE = /LoadingSpinner\b/u;

const TABLE_LITERAL_PATTERN = /<table\b[^>]*>/gu;
const TABLE_WITHOUT_BASE_CLASS_PATTERN = /<table\b[^>]*class\s*=\s*["'][^"']*\btable\b[^"']*["']/u;
const PROGRESS_LITERAL_PATTERN = /<progress\b[^>]*>/gu;
const PROGRESS_WITHOUT_BASE_CLASS_PATTERN =
  /<progress\b[^>]*class\s*=\s*["'][^"']*\bprogress\b[^"']*["']/u;
const RADIAL_PROGRESS_LITERAL_PATTERN =
  /<[^>]*class\s*=\s*["'][^"']*\bradial-progress\b[^"']*["'][^>]*>/gu;

const EMPTY_STATE_REFERENCE_PATTERN = /<EmptyState\b/u;
const LOADING_SKELETON_REFERENCE_PATTERN = /<LoadingSkeleton\b/u;
const BOOTSTRAP_ERROR_ALERT_REFERENCE_PATTERN = /<BootstrapErrorAlert\b/u;

// Hoisted: UI state contract detection — used inside collectStatePrimitiveGapViolations.
const UI_STATE_NAME_PATTERN = /\buiState\b/u;
const LOADING_SKELETON_TAG_PATTERN = /<LoadingSkeleton\b/u;
const BOOTSTRAP_ERROR_ALERT_TAG_PATTERN = /<BootstrapErrorAlert\b/u;
// Hoisted: literal emptiness / loading / error signals in pages.
const IS_EMPTY_LITERAL_PATTERN = /\bisEmpty\b/u;
const LOADING_LITERAL_PATTERN = /['"]loading['"]/u;
const ERROR_LITERAL_PATTERN = /['"]error['"]/u;
// Hoisted: ARIA progressbar role detection on radial-progress tags.
const PROGRESSBAR_ROLE_PATTERN = /\brole\s*=\s*["']progressbar["']/u;

const collectCardGlassLiteralViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  if (filePath === UI_GLASS_CARD_PRIMITIVE_PATH) return [];
  const violations: ValidationViolation[] = [];
  CARD_GLASS_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(CARD_GLASS_LITERAL_PATTERN)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Inline card-glass literal "${match[0]}" bypasses UiGlassCard and SURFACE_GLASS_CARD_CLASS. Use <UiGlassCard> (variant prop for material strength).`,
    });
  }
  BARE_CARD_GLASS_CLASS_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(BARE_CARD_GLASS_CLASS_PATTERN)) {
    // Skip tokens that already matched the longer card card-border card-glass pattern above.
    const line = getLineFromOffset(content, match.index ?? 0);
    if (violations.some((v) => v.filePath === filePath && v.line === line)) {
      continue;
    }
    violations.push({
      filePath,
      line,
      message: `Bare "${match[0]}" class bypasses UiGlassCard / SURFACE_GLASS_* SSOT. Use <UiGlassCard>.`,
    });
  }
  return violations;
};

const collectHardcodedLoadingLabelViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const violations: ValidationViolation[] = [];
  HARDCODED_LOADING_LABEL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(HARDCODED_LOADING_LABEL_PATTERN)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Hardcoded LoadingSpinner label "Loading" bypasses i18n. Use :label="t('common.loading')".`,
    });
  }
  return violations;
};

const collectRawDescriptionClassViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (!filePath.startsWith("packages/client/pages/")) return [];
  const violations: ValidationViolation[] = [];
  RAW_DESCRIPTION_CLASS_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(RAW_DESCRIPTION_CLASS_PATTERN)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Raw description-class="${match[0].includes("muted") ? "text-muted" : "text-secondary"}" bypasses PAGE_HEADER_DESCRIPTION_* SSOT. Omit description-class or use PAGE_HEADER_DESCRIPTION_MEASURE_CLASS.`,
    });
  }
  return violations;
};

/**
 * Ban raw SURFACE_GLASS_CARD_*CLASS bindings outside the UiGlassCard owner.
 * Bespoke card shells fragment density, hover, stagger, and selected/disabled states.
 */
const collectSurfaceGlassCardConstantViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (filePath === UI_GLASS_CARD_PRIMITIVE_PATH) return [];
  if (isSsotPrimitive(filePath) && !filePath.endsWith(".vue")) return [];
  const violations: ValidationViolation[] = [];
  if (!SURFACE_GLASS_CARD_CLASS_IMPORT_PATTERN.test(content)) {
    SURFACE_GLASS_CARD_CLASS_TOKEN_PATTERN.lastIndex = 0;
    for (const match of content.matchAll(SURFACE_GLASS_CARD_CLASS_TOKEN_PATTERN)) {
      const matchOffset = match.index ?? 0;
      const lineStart = content.lastIndexOf("\n", matchOffset) + 1;
      const lineEnd = content.indexOf("\n", matchOffset);
      const line = content.slice(lineStart, lineEnd === -1 ? undefined : lineEnd);
      if (IMPORT_STATEMENT_PATTERN.test(line)) {
        continue;
      }
      violations.push({
        filePath,
        line: getLineFromOffset(content, matchOffset),
        message: `Raw ${match[0]} bypasses the UiGlassCard primitive. Replace the surface shell with <UiGlassCard> (variant / selected / disabled / staggerIndex / extraClass).`,
      });
    }
  }
  return violations;
};

/** Pages that render card grids must consume UiGlassCard at least once when they declare card lists. */
const PAGE_CARD_GRID_HINT_PATTERN =
  /\b(paginatedJobs|statCards|recommendations|orderedCards|projects|resumes)\b/u;
const collectPageUiGlassCardGapViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (!filePath.startsWith("packages/client/pages/")) return [];
  if (!PAGE_CARD_GRID_HINT_PATTERN.test(content)) return [];
  if (UI_GLASS_CARD_COMPONENT_REFERENCE.test(content)) return [];
  // Child components may own cards — only flag when page itself binds glass surfaces.
  if (
    !SURFACE_GLASS_CONSTANT_REFERENCE_PATTERN.test(content) &&
    !CARD_GLASS_LITERAL_PATTERN.test(content)
  ) {
    return [];
  }
  return [
    {
      filePath,
      line: 1,
      message:
        "Page models a card grid but does not consume <UiGlassCard>. Card surfaces must use the canonical glass card primitive.",
    },
  ];
};

const collectLoadingSpinnerLiteralViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const violations: ValidationViolation[] = [];
  LOADING_SPINNER_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(LOADING_SPINNER_LITERAL_PATTERN)) {
    if (LOADING_SPINNER_PRIMITIVE_REFERENCE.test(content)) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Inline spinner "${match[0]}" bypasses the canonical loading primitive. Use LoadingSkeleton (variant="lines") or extract a LoadingSpinner.vue primitive and consume it.`,
    });
  }
  return violations;
};

const collectTablePrimitiveViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  const violations: ValidationViolation[] = [];
  TABLE_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(TABLE_LITERAL_PATTERN)) {
    if (!TABLE_WITHOUT_BASE_CLASS_PATTERN.test(match[0])) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Raw HTML <table> must opt into the daisyUI table primitive (class="table").`,
      });
    }
  }
  PROGRESS_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(PROGRESS_LITERAL_PATTERN)) {
    if (!PROGRESS_WITHOUT_BASE_CLASS_PATTERN.test(match[0])) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Raw <progress> must opt into the daisyUI progress primitive (class="progress").`,
      });
    }
  }
  RADIAL_PROGRESS_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(RADIAL_PROGRESS_LITERAL_PATTERN)) {
    if (!PROGRESSBAR_ROLE_PATTERN.test(match[0])) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `daisyUI radial-progress requires role="progressbar".`,
      });
    }
  }
  return violations;
};

const collectStatePrimitiveGapViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isSsotPrimitive(filePath)) return [];
  if (!filePath.startsWith("packages/client/pages/")) return [];
  const hasUiStateContract =
    UI_STATE_NAME_PATTERN.test(content) ||
    LOADING_SKELETON_TAG_PATTERN.test(content) ||
    BOOTSTRAP_ERROR_ALERT_TAG_PATTERN.test(content);
  if (!hasUiStateContract) return [];
  const violations: ValidationViolation[] = [];
  if (!EMPTY_STATE_REFERENCE_PATTERN.test(content) && IS_EMPTY_LITERAL_PATTERN.test(content)) {
    violations.push({
      filePath,
      line: 1,
      message: `Page models emptiness (isEmpty) but does not consume the EmptyState primitive. Pages must not hand-roll empty states.`,
    });
  }
  if (!LOADING_SKELETON_REFERENCE_PATTERN.test(content) && LOADING_LITERAL_PATTERN.test(content)) {
    violations.push({
      filePath,
      line: 1,
      message: `Page models a loading state but does not consume the LoadingSkeleton primitive. Pages must not hand-roll loading states.`,
    });
  }
  if (
    !BOOTSTRAP_ERROR_ALERT_REFERENCE_PATTERN.test(content) &&
    ERROR_LITERAL_PATTERN.test(content)
  ) {
    violations.push({
      filePath,
      line: 1,
      message: `Page models an error state but does not consume the BootstrapErrorAlert primitive. Pages must not hand-roll error states.`,
    });
  }
  return violations;
};

