const NUM_10000 = 10_000;
const NUM_120 = 120;
const NUM_120000 = 120_000;
const NUM_240 = 240;
const NUM_3 = 3;
const NUM_36 = 36;
const NUM_8 = 8;
/**
 * Live LLM + Whisper probes and settings seed for product demo.
 */
import {
  FAKE_AUDIO_WAV,
  LOCAL_ENDPOINT,
  RE_BAO_DEMO_DETERMINISTIC,
  RE_BUILD_DETERMINISTIC_CONTENT,
  RE_DETERMINISTIC_AI,
