import {
  collectProjectFileEntries,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

/**
 * Layout token identifiers that must be explicitly imported when referenced in SFCs.
 * Nuxt auto-import is not reliable for constants used only in templates under SSR.
 */
export const REQUIRED_LAYOUT_TOKEN_IMPORTS = [
  "STACK_SPACE_Y_TOKEN_CLASS",
  "TYPOGRAPHY_SCALE_CLASS",
  "FLEX_GAP_TOKEN_CLASS",
  "PADDING_TOKEN_CLASS",
  "MARGIN_TOKEN_CLASS",
  "SURFACE_GLASS_CARD_CLASS",
  "ICON_SIZE_CLASS",
] as const;

const LAYOUT_TOKENS_DIRECT_IMPORT_PATTERN = /from\s+["']~\/constants\/layout-tokens["']/gu;

const isLayoutTokenOwner = (filePath: string): boolean =>
  filePath === "packages/client/constants/layout.ts" ||
  filePath === "packages/client/constants/layout-shell.ts" ||
  filePath === "packages/client/constants/layout-tokens.ts" ||
  filePath.endsWith("/validate-layout-token-imports.ts") ||
  filePath.endsWith("/validate-layout-token-imports.test.ts") ||
  filePath.includes("/tests/");

export const collectDirectLayoutTokensImportViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isLayoutTokenOwner(filePath)) return [];
  if (!filePath.startsWith("packages/client/")) return [];
  if (!LAYOUT_TOKENS_DIRECT_IMPORT_PATTERN.test(content)) return [];
  return [
    {
      filePath,
      line: 1,
      message: `Direct import from ~/constants/layout-tokens bypasses public layout SSOT. Import tokens from ~/constants/layout only.`,
    },
  ];
};

export const collectMissingLayoutTokenImportViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (!filePath.endsWith(".vue")) {
    return [];
  }

  const violations: ValidationViolation[] = [
    ...collectDirectLayoutTokensImportViolationsForContent(filePath, content),
  ];
  for (const tokenName of REQUIRED_LAYOUT_TOKEN_IMPORTS) {
    const usagePattern = new RegExp(`\\b${tokenName}\\b`, "u");
    if (!usagePattern.test(content)) {
      continue;
    }
    const importPattern = new RegExp(`import\\s*\\{[^}]*\\b${tokenName}\\b[^}]*\\}`, "u");
    if (importPattern.test(content)) {
      continue;
    }
    violations.push({
      filePath,
      line: 1,
      message: `Template/script references ${tokenName} without importing it from ~/constants/layout (SSR will crash with undefined token).`,
    });
  }
  return violations;
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots: ["packages/client"],
    allowedExtensions: new Set([".vue"]),
  });
  return files.flatMap(({ filePath, content }) =>
    collectMissingLayoutTokenImportViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Layout token import validation failed:",
    await collectViolations(),
    "Layout token import validation passed.",
  );
}

import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

/**
 * Ban inert navigation stubs (brutalise UI012 gap): href="#", javascript:void.
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts"]);
const hrefHashPattern = /\bhref\s*=\s*(["'])#\1/gu;
const javascriptVoidPattern = /javascript\s*:\s*void/giu;

export const collectHrefHashStubViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  hrefHashPattern.lastIndex = 0;
  for (const match of content.matchAll(hrefHashPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: 'href="#" is a dead navigation stub. Use a real route constant or button+handler.',
    });
  }
  javascriptVoidPattern.lastIndex = 0;
  for (const match of content.matchAll(javascriptVoidPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: "javascript:void handlers are forbidden dead stubs.",
    });
  }
  return violations;
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots: [...scanRoots],
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectHrefHashStubViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Href-hash stub validation failed:",
    await collectViolations(),
    "Href-hash stub validation passed.",
  );
}

import { mkdir, rm, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { chromium } from "playwright";
import { APP_ROUTE_QUERY_KEYS, APP_ROUTES } from "../packages/shared/src/constants/routes";
import { writeError, writeOutput } from "./utils/cli-output";

type JsonRecord = Record<string, unknown>;

type ViewportSize = {
  readonly width: number;
  readonly height: number;
};

type ScreenshotOptions = {
  readonly path: string;
  readonly fullPage: boolean;
};

type PageSignalSnapshot = {
  readonly heading: string | null;
  readonly alerts: readonly string[];
  readonly bodyText: string;
};

type PageInstance = {
  goto(
    url: string,
    options: { readonly waitUntil: "domcontentloaded"; readonly timeout: number },
  ): Promise<void>;
  waitForLoadState(
    state: "domcontentloaded" | "load",
    options: { readonly timeout: number },
  ): Promise<void>;
  title(): Promise<string>;
  evaluate<Result>(handler: () => Result): Promise<Result>;
  screenshot(options: ScreenshotOptions): Promise<Uint8Array>;
};

type BrowserInstance = {
  newPage(options: { readonly viewport: ViewportSize }): Promise<PageInstance>;
  close(): Promise<void>;
};

type PageProofRouteSpec = {
  readonly slug: string;
  readonly route: string;
};

type PageProofReportItem = {
  readonly slug: string;
  readonly route: string;
  readonly url: string;
  readonly screenshotPath: string;
  readonly title: string;
  readonly h1: string | null;
  readonly alerts: readonly string[];
  readonly flaggedKeywords: readonly string[];
};

type CapturePageProofReportInput = {
  readonly browser: BrowserInstance;
  readonly clientBase: string;
  readonly outputDirectory: string;
  readonly remainingSpecs: readonly PageProofRouteSpec[];
  readonly captured?: readonly PageProofReportItem[];
};

type ResolvedPageIdentifiers = {
  readonly resumeId: string;
  readonly jobId: string;
  readonly studioId: string;
  readonly coverLetterId: string;
  readonly scrapeRunId: string;
  readonly interviewSessionId: string;
};

const DEFAULT_API_BASE = "http://127.0.0.1:3000";
const DEFAULT_CLIENT_BASE = "http://localhost:3001";
const DEFAULT_VIEWPORT = {
  width: 1440,
  height: 1600,
} as const satisfies ViewportSize;
const DEFAULT_WAIT_AFTER_NAVIGATION_MS = 3_000;
const DEFAULT_NAVIGATION_TIMEOUT_MS = 60_000;
const DEFAULT_SETTLE_POLL_INTERVAL_MS = 500;
const DEFAULT_SETTLE_TIMEOUT_MS = 12_000;
const FLAGGED_KEYWORDS = ["failed", "error", "could not", "unable", "not found"] as const;
const TRAILING_SLASH_PATTERN = /\/$/u;
const COLLECTION_RESPONSE_KEYS = [
  "items",
  "data",
  "jobs",
  "resumes",
  "studios",
  "coverLetters",
] as const;
const isRecord = (value: unknown): value is JsonRecord =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isString = (value: unknown): value is string => typeof value === "string";

const isPageProofRouteSpec = (value: unknown): value is PageProofRouteSpec =>
  isRecord(value) && isString(value.slug) && isString(value.route);

const normalizeText = (value: string): string => value.replace(/\s+/gu, " ").trim();

const resolveFlagValue = (flagName: string): string | null => {
  const flagIndex = process.argv.indexOf(flagName);
  const rawValue = flagIndex >= 0 ? process.argv[flagIndex + 1] : null;
  return rawValue && !rawValue.startsWith("--") ? rawValue : null;
};

const resolveOutputDirectory = (): string => {
  const explicit = resolveFlagValue("--output-dir");
  if (explicit) {
    return resolve(process.cwd(), explicit);
  }

  const date = new Date().toISOString().slice(0, 10);
  return join("/tmp", `bao-page-proof-${date}`);
};

const resolveClientBase = (): string =>
  (
    resolveFlagValue("--client-base") ??
    process.env.PAGE_PROOF_CLIENT_BASE ??
    DEFAULT_CLIENT_BASE
  ).replace(TRAILING_SLASH_PATTERN, "");

const resolveApiBase = (): string =>
  (resolveFlagValue("--api-base") ?? process.env.PAGE_PROOF_API_BASE ?? DEFAULT_API_BASE).replace(
    TRAILING_SLASH_PATTERN,
    "",
  );

const fetchJson = async (url: string): Promise<unknown> => {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: ${response.status} ${response.statusText}`);
  }
  return response.json();
};

const readCollectionRecordArray = (value: JsonRecord): readonly unknown[] => {
  for (const key of COLLECTION_RESPONSE_KEYS) {
    const candidate = value[key];
    if (Array.isArray(candidate)) {
      return candidate;
    }
  }

  return [];
};

const readArrayCandidate = (value: unknown): readonly unknown[] => {
  if (Array.isArray(value)) {
    return value;
  }

  return isRecord(value) ? readCollectionRecordArray(value) : [];
};

const readEntityId = (value: unknown): string | null =>
  isRecord(value) && isString(value.id) && value.id.length > 0 ? value.id : null;

const requireEntityId = (label: string, value: unknown): string => {
  const resolved = readEntityId(value);
  if (resolved) {
    return resolved;
  }
  throw new Error(`Unable to resolve ${label} for page proof.`);
};

const findSuccessfulScrapeRunId = (value: unknown): string => {
  const candidate = readArrayCandidate(value).find(
    (item) =>
      isRecord(item) &&
      item.type === "scrape" &&
      item.status === "success" &&
      isString(item.id) &&
      item.id.length > 0,
  );
  return requireEntityId("scrape run id", candidate);
};

const findInterviewSessionId = (value: unknown): string => {
  const candidate = readArrayCandidate(value)[0];
  return requireEntityId("interview session id", candidate);
};

const resolvePageIdentifiers = async (apiBase: string): Promise<ResolvedPageIdentifiers> => {
  const [resumes, jobs, studios, coverLetters, runs, interviewSessions] = await Promise.all([
    fetchJson(`${apiBase}/api/resumes`),
    fetchJson(`${apiBase}/api/jobs?limit=5`),
    fetchJson(`${apiBase}/api/studios`),
    fetchJson(`${apiBase}/api/cover-letters`),
    fetchJson(`${apiBase}/api/automation/runs?limit=20`),
    fetchJson(`${apiBase}/api/interview/sessions`),
  ]);

  const resumeId = requireEntityId("resume id", readArrayCandidate(resumes)[0]);
  const jobId = requireEntityId("job id", readArrayCandidate(jobs)[0]);
  const studioId = requireEntityId("studio id", readArrayCandidate(studios)[0]);
  const coverLetterId = requireEntityId("cover letter id", readArrayCandidate(coverLetters)[0]);
  const scrapeRunId = findSuccessfulScrapeRunId(runs);
  const interviewSessionId = findInterviewSessionId(interviewSessions);

  return {
    resumeId,
    jobId,
    studioId,
    coverLetterId,
    scrapeRunId,
    interviewSessionId,
  };
};

const buildRouteSpecs = (ids: ResolvedPageIdentifiers): readonly PageProofRouteSpec[] => {
  const routes = [
    { slug: "dashboard", route: APP_ROUTES.dashboard },
    { slug: "jobs-index", route: APP_ROUTES.jobs },
    { slug: "jobs-detail", route: `${APP_ROUTES.jobs}/${ids.jobId}` },
    { slug: "resume-index", route: APP_ROUTES.resume },
    { slug: "resume-build", route: `${APP_ROUTES.resume}/build` },
    { slug: "resume-preview", route: `${APP_ROUTES.resume}/preview?id=${ids.resumeId}` },
    { slug: "cover-letter-index", route: APP_ROUTES.coverLetter },
    { slug: "cover-letter-detail", route: `${APP_ROUTES.coverLetter}/${ids.coverLetterId}` },
    { slug: "portfolio-index", route: APP_ROUTES.portfolio },
    { slug: "portfolio-preview", route: `${APP_ROUTES.portfolio}/preview` },
    { slug: "interview-index", route: APP_ROUTES.interview },
    { slug: "interview-history", route: `${APP_ROUTES.interview}/history` },
    {
      slug: "interview-session",
      route: `${APP_ROUTES.interview}/session?${APP_ROUTE_QUERY_KEYS.id}=${ids.interviewSessionId}`,
    },
    { slug: "skills-index", route: APP_ROUTES.skills },
    { slug: "skills-pathways", route: `${APP_ROUTES.skills}/pathways` },
    { slug: "studios-index", route: APP_ROUTES.studios },
    { slug: "studios-detail", route: `${APP_ROUTES.studios}/${ids.studioId}` },
    { slug: "studios-analytics", route: `${APP_ROUTES.studios}/analytics` },
    { slug: "ai-chat", route: APP_ROUTES.aiChat },
    { slug: "ai-dashboard", route: APP_ROUTES.aiDashboard },
    { slug: "automation-index", route: APP_ROUTES.automation },
    { slug: "automation-job-apply", route: APP_ROUTES.automationJobApply },
    { slug: "automation-scraper", route: APP_ROUTES.automationScraper },
    { slug: "automation-email", route: APP_ROUTES.automationEmail },
    { slug: "automation-runs", route: APP_ROUTES.automationRuns },
    { slug: "automation-run-detail", route: `${APP_ROUTES.automationRuns}/${ids.scrapeRunId}` },
    { slug: "docs-api", route: APP_ROUTES.apiDocs },
    { slug: "gamification", route: APP_ROUTES.gamification },
    { slug: "settings", route: APP_ROUTES.settings },
    { slug: "setup", route: APP_ROUTES.setup },
  ] satisfies readonly unknown[];

  return routes.filter(isPageProofRouteSpec);
};

const capturePageSignals = async (page: PageInstance): Promise<PageSignalSnapshot> =>
  page.evaluate(() => {
    const collectTexts = (selector: string): readonly string[] =>
      Array.from(document.querySelectorAll(selector))
        .map((node) => node.textContent?.replace(/\s+/gu, " ").trim() ?? "")
        .filter((value) => value.length > 0);

    const headingText =
      [...collectTexts("main h1"), ...collectTexts("h1")]
        .sort((left, right) => right.length - left.length)
        .at(0) ?? "";
    const bodyText = document.body.textContent?.replace(/\s+/gu, " ").trim() ?? "";

    return {
      heading: headingText.length > 0 ? headingText : null,
      alerts: collectTexts('[role="alert"], .alert, [data-page-state="error"]'),
      bodyText,
    };
  });

const pageStillLoading = async (page: PageInstance): Promise<boolean> =>
  page.evaluate(() => {
    const skeletonCount = document.querySelectorAll(".skeleton").length;
    const loadingIndicatorCount = document.querySelectorAll(".loading").length;
    const mainText =
      document.querySelector("main")?.textContent?.replace(/\s+/gu, " ").trim() ?? "";

    if (skeletonCount > 0) {
      return true;
    }

    if (loadingIndicatorCount === 0) {
      return false;
    }

    return mainText.length === 0;
  });

const waitForSettledIteration = async (page: PageInstance, waitedMs: number): Promise<void> => {
  if (waitedMs >= DEFAULT_SETTLE_TIMEOUT_MS) {
    return;
  }

  const stillLoading = await pageStillLoading(page);
  if (!stillLoading) {
    return;
  }

  await page.waitForLoadState("domcontentloaded", {
    timeout: DEFAULT_SETTLE_POLL_INTERVAL_MS,
  });
  return waitForSettledIteration(page, waitedMs + DEFAULT_SETTLE_POLL_INTERVAL_MS);
};

const waitForPageToSettle = async (page: PageInstance): Promise<void> => {
  await page.waitForLoadState("load", {
    timeout: DEFAULT_WAIT_AFTER_NAVIGATION_MS,
  });
  return waitForSettledIteration(page, 0);
};

const capturePageProof = async (
  browser: BrowserInstance,
  clientBase: string,
  outputDirectory: string,
  spec: PageProofRouteSpec,
): Promise<PageProofReportItem> => {
  const page = await browser.newPage({ viewport: DEFAULT_VIEWPORT });
  const url = `${clientBase}${spec.route}`;
  await page.goto(url, {
    waitUntil: "domcontentloaded",
    timeout: DEFAULT_NAVIGATION_TIMEOUT_MS,
  });
  await waitForPageToSettle(page);

  const title = normalizeText(await page.title());
  const snapshot = await capturePageSignals(page);
  const screenshotPath = join(outputDirectory, `${spec.slug}.png`);
  await page.screenshot({
    path: screenshotPath,
    fullPage: true,
  });

  const loweredAlertText = snapshot.alerts.join(" ").toLowerCase();
  const flaggedKeywords = FLAGGED_KEYWORDS.filter((keyword) => loweredAlertText.includes(keyword));

  return {
    slug: spec.slug,
    route: spec.route,
    url,
    screenshotPath,
    title,
    h1: snapshot.heading,
    alerts: snapshot.alerts,
    flaggedKeywords,
  };
};

const buildMarkdownReport = (report: readonly PageProofReportItem[]): string => {
  const lines = [
    "# Page Proof Report",
    "",
    `Generated at ${new Date().toISOString()}`,
    "",
    "| Slug | Route | Title | H1 | Alerts | Flagged keywords | Screenshot |",
    "|------|-------|-------|----|--------|------------------|------------|",
  ];

  for (const item of report) {
    lines.push(
      `| ${item.slug} | ${item.route} | ${item.title || "n/a"} | ${item.h1 || "n/a"} | ${item.alerts.length} | ${
        item.flaggedKeywords.length > 0 ? item.flaggedKeywords.join(", ") : "none"
      } | ${item.screenshotPath} |`,
    );
  }

  return `${lines.join("\n")}\n`;
};

const capturePageProofReport = async (
  input: CapturePageProofReportInput,
): Promise<readonly PageProofReportItem[]> => {
  const { browser, clientBase, outputDirectory, remainingSpecs, captured = [] } = input;
  const [nextSpec, ...nextSpecs] = remainingSpecs;
  if (!nextSpec) {
    return captured;
  }

  const nextItem = await capturePageProof(browser, clientBase, outputDirectory, nextSpec);
  return capturePageProofReport({
    browser,
    clientBase,
    outputDirectory,
    remainingSpecs: nextSpecs,
    captured: [...captured, nextItem],
  });
};

const main = async (): Promise<void> => {
  const apiBase = resolveApiBase();
  const clientBase = resolveClientBase();
  const outputDirectory = resolveOutputDirectory();
  await writeOutput(`page-proof: writing screenshots to ${outputDirectory}`);
  await rm(outputDirectory, { recursive: true, force: true });
  await mkdir(outputDirectory, { recursive: true });

  const ids = await resolvePageIdentifiers(apiBase);
  const routeSpecs = buildRouteSpecs(ids);
  const browser = await chromium.launch({ headless: true });
  const report = await capturePageProofReport({
    browser,
    clientBase,
    outputDirectory,
    remainingSpecs: routeSpecs,
  });
  await browser.close();

  const jsonPath = join(outputDirectory, "report.json");
  const markdownPath = join(outputDirectory, "report.md");
  await writeFile(jsonPath, `${JSON.stringify(report, null, 2)}\n`);
  await writeFile(markdownPath, buildMarkdownReport(report));
  await writeOutput(`page-proof: captured ${report.length} routes`);
  await writeOutput(`page-proof: report.json -> ${jsonPath}`);
  await writeOutput(`page-proof: report.md -> ${markdownPath}`);
};

await main().then(undefined, async (error: unknown) => {
  const message =
    error instanceof Error ? error.message : `Unknown page proof failure: ${String(error)}`;
  await writeError(`page-proof: ${message}`);
  process.exitCode = 1;
});

import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

/**
 * Inline `style="..."` attributes are forbidden in Vue templates.
 * They bypass the layout/CSS SSOT token system, defeat theming, and create
 * per-component bespoke styling (design.md §8 / AGENTS.md UI/UX standards).
 *
 * This gate catches real `style="..."` attributes on element tags. It excludes
 * Vue event/handler bindings like `@update:conversation-style="..."` which
 * contain the substring `style=` but are not inline style attributes.
 *
 * Script/DOM style writes (`.style.*`, `setAttribute("style", ...)`) are also
 * banned except for the brand CSS variable allowlist below.
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts", ".tsx", ".js", ".mjs", ".cjs"]);

const BRAND_STYLE_DOM_ALLOWLIST = new Set([
  "packages/client/plugins/brand-css.client.ts",
  "packages/client/composables/useBrandPreviewStyles.ts",
]);

// Match a real inline style attribute: `<tag ... style="..."` or `<tag ... style='...'`.
// Must be preceded by whitespace + attribute name boundary, and the value is
// quoted. This excludes `@update:conversation-style="..."` (preceded by `-`
// not whitespace) and `:style="..."` (Vue dynamic binding — handled by the
// dynamic binding gate separately, but also banned here).
const inlineStyleAttributePattern = /\sstyle\s*=\s*(?:"[^"]*"|'[^']*'|`[^`]*`)/gu;
const dynamicStyleBindingPattern = /:style\s*=\s*(?:"[^"]*"|'[^']*'|`[^`]*`)/gu;
const stylePropertyWritePattern = /\.style\./gu;
const setAttributeStylePattern = /setAttribute\s*\(\s*(["'])style\1/gu;

const extractTemplateBlocks = (content: string): string => {
  const templateStart = content.indexOf("<template>");
  if (templateStart < 0) return "";
  const templateEnd = content.lastIndexOf("</template>");
  if (templateEnd <= templateStart) return content.slice(templateStart);
  return content.slice(templateStart, templateEnd + "</template>".length);
};

export const collectInlineStyleViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  const template = extractTemplateBlocks(content);

  if (template.length > 0) {
    inlineStyleAttributePattern.lastIndex = 0;
    for (const match of template.matchAll(inlineStyleAttributePattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Inline style attribute "style=..." is forbidden. Use SSOT tokens from constants/layout.ts or assets/css/main.css glass-* primitives.`,
      });
    }

    dynamicStyleBindingPattern.lastIndex = 0;
    for (const match of template.matchAll(dynamicStyleBindingPattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Dynamic :style binding is forbidden. Use :class with SSOT class constants from constants/layout.ts. Inline styles bypass the glassmorphic token system.`,
      });
    }
  }

  if (!BRAND_STYLE_DOM_ALLOWLIST.has(filePath)) {
    stylePropertyWritePattern.lastIndex = 0;
    for (const match of content.matchAll(stylePropertyWritePattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message:
          "DOM style property write (`.style.`) is forbidden outside brand CSS allowlist. Use SSOT class tokens or brand-css.client.ts / useBrandPreviewStyles.ts.",
      });
    }

    setAttributeStylePattern.lastIndex = 0;
    for (const match of content.matchAll(setAttributeStylePattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message:
          'setAttribute("style", ...) is forbidden outside brand CSS allowlist. Use SSOT class tokens.',
      });
    }
  }

  return violations;
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectInlineStyleViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Inline style validation failed:",
    await collectViolations(),
    "Inline style validation passed.",
  );
}

#!/usr/bin/env bun
/**
 * Authentic brutalise full scan of REAL on-disk source.
 * Builds complete file manifest, calls brutalise MCP HTTP endpoint.
 * No excludePatterns, exact bytes.
 */

import { collectBrutaliseScanFiles } from "./brutalise-scan-files";

const BRUTALISE_URL = "https://brutalise-production.up.railway.app/mcp";

const root = process.cwd();
const allFiles = await collectBrutaliseScanFiles(root);

const mcpRequest = {
  jsonrpc: "2.0",
  id: 1,
  method: "tools/call",
  params: {
    name: "brutal_full_gate",
    arguments: {
      targetDir: root,
      files: allFiles,
    },
  },
};

const response = await fetch(BRUTALISE_URL, {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
  },
  body: JSON.stringify(mcpRequest),
});

const rawBody = await response.text();
process.stdout.write(`${rawBody}\n`);

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import enUSCatalog from "../packages/client/locales/en-US/catalog";
import esESCatalog from "../packages/client/locales/es-ES/catalog";
import frFRCatalog from "../packages/client/locales/fr-FR/catalog";
import jaJPCatalog from "../packages/client/locales/ja-JP/catalog";
import { safeParseJson, type JsonValue } from "../packages/shared/src/utils/json";
import { reportViolations, type ValidationViolation } from "./utils/validation-helpers";
import { PERCENT_MAX } from "./constants/numeric-literals";
const RATIO_0_05 = 0.05;

/**
 * Locale parity gate (HARDENED):
 * 1. Compares **raw override catalogs** (not merged modules with English fallback).
 * 2. Critical namespaces must be 100% present in every locale catalog.
 * 3. Coverage % must meet-or-beat floors in scripts/i18n-coverage-floors.json (ratchet).
 *
 * Contract: docs/ssot-ledger/contract-escalation-i18n-raw.md (+ STACK-CONTRACT).
 */

type LocaleModule = Record<string, unknown>;

const CRITICAL_NAMESPACES_PATH = "scripts/i18n-critical-namespaces.json";
const COVERAGE_FLOORS_PATH = "scripts/i18n-coverage-floors.json";

const locales: Array<{ filePath: string; localeId: string; value: LocaleModule }> = [
  { filePath: "packages/client/locales/es-ES/catalog.ts", localeId: "es-ES", value: esESCatalog },
  { filePath: "packages/client/locales/fr-FR/catalog.ts", localeId: "fr-FR", value: frFRCatalog },
  { filePath: "packages/client/locales/ja-JP/catalog.ts", localeId: "ja-JP", value: jaJPCatalog },
];

const collectPaths = (value: unknown, prefix: string = ""): string[] => {
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return prefix.length > 0 ? [prefix] : [];
  }
  if (Array.isArray(value)) {
    return value.flatMap((entry, index) =>
      collectPaths(entry, prefix.length > 0 ? `${prefix}.${index}` : `${index}`),
    );
  }
  if (typeof value !== "object" || value === null) {
    return prefix.length > 0 ? [prefix] : [];
  }

  return Object.entries(value).flatMap(([key, nestedValue]) =>
    collectPaths(nestedValue, prefix.length > 0 ? `${prefix}.${key}` : key),
  );
};

const loadCriticalPrefixes = (): string[] => {
  const parsed = safeParseJson(
    readFileSync(resolve(process.cwd(), CRITICAL_NAMESPACES_PATH), "utf-8"),
  );
  if (!Array.isArray(parsed)) {
    throw new Error(`${CRITICAL_NAMESPACES_PATH} must be a JSON array of key prefixes`);
  }
  return parsed.filter((entry): entry is string => typeof entry === "string");
};

type CoverageFloors = {
  readonly floors: Record<string, number>;
};

const isCoverageFloors = (value: JsonValue): value is CoverageFloors => {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const floors = value.floors;
  if (typeof floors !== "object" || floors === null || Array.isArray(floors)) {
    return false;
  }
  return Object.values(floors).every((entry) => typeof entry === "number");
};

const loadCoverageFloors = (): CoverageFloors => {
  const parsed = safeParseJson(
    readFileSync(resolve(process.cwd(), COVERAGE_FLOORS_PATH), "utf-8"),
  );
  if (!isCoverageFloors(parsed)) {
    throw new Error(`${COVERAGE_FLOORS_PATH} must declare floors: Record<localeId, number>`);
  }
  return parsed;
};

const referenceKeys = new Set(collectPaths(enUSCatalog));
const criticalPrefixes = loadCriticalPrefixes();
const criticalReferenceKeys = [...referenceKeys].filter((key) =>
  criticalPrefixes.some((prefix) => key === prefix || key.startsWith(`${prefix}.`)),
);

const isCriticalKey = (key: string): boolean =>
  criticalPrefixes.some((prefix) => key === prefix || key.startsWith(`${prefix}.`));

const collectCoverageViolations = (
  filePath: string,
  localeId: string,
  localeKeys: Set<string>,
  floors: CoverageFloors,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  const coveragePct = Number(((localeKeys.size / referenceKeys.size) * PERCENT_MAX).toFixed(1));
  const floor = floors.floors[localeId];
  if (typeof floor !== "number") {
    violations.push({
      filePath: COVERAGE_FLOORS_PATH,
      line: 1,
      message: `Missing coverage floor for locale "${localeId}".`,
    });
  } else if (coveragePct + RATIO_0_05 < floor) {
    violations.push({
      filePath,
      line: 1,
      message: `Raw catalog coverage ${coveragePct}% is below ratchet floor ${floor}% for ${localeId}.`,
    });
  }
  return violations;
};

const collectMissingCriticalKeyViolations = (
  filePath: string,
  localeKeys: Set<string>,
): ValidationViolation[] =>
  criticalReferenceKeys
    .filter((key) => !localeKeys.has(key))
    .map((key) => ({
      filePath,
      line: 1,
      message: `Missing critical raw locale key "${key}" required by en-US catalog.`,
    }));

const collectOrphanKeyViolations = (
  filePath: string,
  localeKeys: Set<string>,
): ValidationViolation[] =>
  [...localeKeys]
    .filter((key) => !referenceKeys.has(key))
    .map((key) => ({
      filePath,
      line: 1,
      message: `Orphan locale key "${key}" is not present in en-US catalog.`,
    }));

const collectViolations = (): ValidationViolation[] => {
  const floors = loadCoverageFloors();
  const violations: ValidationViolation[] = [];

  for (const { filePath, localeId, value } of locales) {
    const localeKeys = new Set(collectPaths(value));
    violations.push(...collectCoverageViolations(filePath, localeId, localeKeys, floors));
    violations.push(...collectMissingCriticalKeyViolations(filePath, localeKeys));
    violations.push(...collectOrphanKeyViolations(filePath, localeKeys));
  }

  if (criticalReferenceKeys.length === 0) {
    violations.push({
      filePath: CRITICAL_NAMESPACES_PATH,
      line: 1,
      message: "Critical namespace list matched zero en-US keys — gate would be vacuous.",
    });
  }

  return violations;
};

if (import.meta.main) {
  await reportViolations(
    "Locale parity validation failed:",
    collectViolations(),
    "Locale parity validation passed.",
  );
}

export { collectViolations, isCriticalKey };

#!/usr/bin/env bun
/**
 * Headed visual + binary proof for resume / cover-letter / portfolio exports.
 * Creates entities via API, downloads PDF/DOCX, validates signatures, then
 * opens UI pages and exercises AppExportMenu with screenshots + one UI download.
 */
import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import { chromium, type Download, type Locator, type Page, type Response } from "playwright";
import {
  API_ENDPOINTS,
  buildCoverLetterExportEndpoint,
  buildResumeExportEndpoint,
} from "../packages/shared/src/constants/endpoints";
import { HTTP_STATUS_CREATED, HTTP_STATUS_OK } from "../packages/shared/src/constants/http";
import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import { safeParseJson } from "../packages/shared/src/utils/json";
import { settle } from "../packages/shared/src/utils/promise";
import {
  COUNT_FOUR,
  COUNT_TWO,
  COUNT_TWO_HUNDRED,
  MS_ONE_HUNDRED,
} from "./constants/numeric-literals";
import { writeError, writeOutput } from "./utils/cli-output";

const API_BASE = (process.env.PAGE_PROOF_API_BASE ?? "http://127.0.0.1:3000").replace(/\/$/u, "");
const CLIENT_BASE = (process.env.PAGE_PROOF_CLIENT_BASE ?? "http://127.0.0.1:3001").replace(
  /\/$/u,
  "",
);
const OUT_DIR = process.env.EXPORT_PROOF_OUT ?? join("/opt/cursor/artifacts/exports", "proof");
const VIEWPORT = { width: 1440, height: 900 } as const;
const NAV_TIMEOUT_MS = 60_000;
const MENU_TIMEOUT_MS = 10_000;
const MAIN_WAIT_MS = 30_000;
const EXPAND_POLL_ATTEMPTS = 20;
const PDF_HEADER_BYTES = COUNT_FOUR;
const ERROR_SNIPPET_LENGTH = COUNT_TWO_HUNDRED;

const PDF_MAGIC = "%PDF";
const DOCX_MAGIC_0 = 0x50;
const DOCX_MAGIC_1 = 0x4b;
const EXPORT_LABEL_PATTERN = /export/iu;
const PDF_MENU_PATTERN = /pdf/iu;
const DOCX_MENU_PATTERN = /docx/iu;
const EXPORT_PATH_PATTERN = /\/export/u;

type ProofRow = {
  surface: string;
  format: "pdf" | "docx";
  ok: boolean;
  bytes: number;
  path?: string;
  reason?: string;
};

type UiProofRow = {
  slug: string;
  ok: boolean;
  reason?: string;
  downloadBytes?: number;
};

type UiSurface = {
  slug: string;
  route: string;
  downloadPdf: boolean;
};

const apiJson = async <T>(
  method: string,
  path: string,
  body?: unknown,
): Promise<{ status: number; body: T; raw: string }> => {
  const response = await fetch(`${API_BASE}${path}`, {
    method,
    headers: body ? { "content-type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const raw = await response.text();
  const parsed = safeParseJson(raw);
  if (parsed === null) {
    throw new Error(
      `${method} ${path} non-JSON (${String(response.status)}): ${raw.slice(0, ERROR_SNIPPET_LENGTH)}`,
    );
  }
  return { status: response.status, body: parsed as T, raw };
};

const apiBinary = async (
  method: string,
  path: string,
  body: unknown,
): Promise<{ status: number; contentType: string | null; bytes: Uint8Array }> => {
  const response = await fetch(`${API_BASE}${path}`, {
    method,
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  const buffer = new Uint8Array(await response.arrayBuffer());
  return {
    status: response.status,
    contentType: response.headers.get("content-type"),
    bytes: buffer,
  };
};

const isPdf = (bytes: Uint8Array): boolean => {
  if (bytes.length < PDF_HEADER_BYTES) {
    return false;
  }
  return String.fromCharCode(bytes[0], bytes[1], bytes[2], bytes[3]) === PDF_MAGIC;
};

const isDocxZip = (bytes: Uint8Array): boolean =>
  bytes.length >= COUNT_TWO && bytes[0] === DOCX_MAGIC_0 && bytes[1] === DOCX_MAGIC_1;

const saveExport = async (
  rows: ProofRow[],
  surface: string,
  format: "pdf" | "docx",
  path: string,
  body: Record<string, unknown>,
): Promise<void> => {
  const result = await apiBinary("POST", path, body);
  const filePath = join(OUT_DIR, `${surface}.${format}`);
  const magicOk = format === "pdf" ? isPdf(result.bytes) : isDocxZip(result.bytes);
  const ok = result.status === HTTP_STATUS_OK && result.bytes.length > 0 && magicOk;
  if (ok) {
    await Bun.write(filePath, result.bytes);
  }
  rows.push({
    surface,
    format,
    ok,
    bytes: result.bytes.length,
    path: ok ? filePath : undefined,
    reason: ok
      ? undefined
      : `status=${String(result.status)} type=${result.contentType ?? "none"} magic=${String(magicOk)}`,
  });
};

const seedEntities = async (): Promise<{
  resumeId: string;
  coverLetterId: string;
}> => {
  const resume = await apiJson<{ id: string }>("POST", API_ENDPOINTS.resumes, {
    name: "Export Visual Resume",
    summary: "Shipped multiplayer combat systems for AAA titles.",
    personalInfo: {
      name: "Alex Rivera",
      email: "alex.rivera@example.com",
      location: "Remote",
      github: "https://github.com/example",
    },
    experience: [
      {
        company: "Pixel Forge",
        title: "Gameplay Engineer",
        startDate: "2022-01",
        endDate: "Present",
        description: "Owned combat netcode and tools for designers.",
      },
    ],
    skills: { technical: ["C++", "Unreal Engine", "TypeScript"] },
  });
  if (resume.status !== HTTP_STATUS_CREATED) {
    throw new Error(`resume create failed: ${String(resume.status)}`);
  }

  const cover = await apiJson<{ id: string }>("POST", API_ENDPOINTS.coverLetters, {
    company: "Indie Studio",
    position: "Gameplay Engineer",
    content: {
      introduction: "Dear Hiring Manager,",
      body: "I am excited to apply for the Gameplay Engineer role at your studio.",
      conclusion: "Sincerely,",
    },
  });
  if (cover.status !== HTTP_STATUS_CREATED || !cover.body.id) {
    throw new Error(`cover letter create failed: ${String(cover.status)}`);
  }

  const portfolioGet = await apiJson<{ id: string }>("GET", API_ENDPOINTS.portfolio);
  if (portfolioGet.status !== HTTP_STATUS_OK) {
    throw new Error(`portfolio get failed: ${String(portfolioGet.status)}`);
  }
  const portfolioPut = await apiJson("PUT", API_ENDPOINTS.portfolio, {
    metadata: {
      title: "Alex Rivera Portfolio",
      summary: "Selected shipped work across combat and tools.",
      tagline: "Gameplay systems that ship",
    },
  });
  if (portfolioPut.status !== HTTP_STATUS_OK) {
    throw new Error(`portfolio put failed: ${String(portfolioPut.status)}`);
  }

  await apiJson("POST", API_ENDPOINTS.portfolioProjects, {
    title: "Netcode Arena",
    description: "Rollback-friendly multiplayer combat prototype.",
    technologies: ["Unreal", "C++"],
    url: "https://example.com/netcode-arena",
  });

  return { resumeId: resume.body.id, coverLetterId: cover.body.id };
};

const expectExpanded = async (trigger: Locator): Promise<void> => {
  const poll = async (attempt: number): Promise<void> => {
    if (attempt >= EXPAND_POLL_ATTEMPTS) {
      return;
    }
    const expanded = await trigger.getAttribute("aria-expanded");
    if (expanded === "true") {
      return;
    }
    await Bun.sleep(MS_ONE_HUNDRED);
    await poll(attempt + 1);
  };
  await poll(0);
};

const isExportPostOk = (response: Response): boolean =>
  response.request().method() === "POST" &&
  EXPORT_PATH_PATTERN.test(response.url()) &&
  response.status() === HTTP_STATUS_OK;

const readDownloadBytes = async (
  download: Download | null,
  exportResponse: Response,
  filePath: string,
): Promise<Uint8Array> => {
  if (download) {
    await download.saveAs(filePath);
    return new Uint8Array(await Bun.file(filePath).arrayBuffer());
  }
  const bytes = new Uint8Array(await exportResponse.body());
  await Bun.write(filePath, bytes);
  return bytes;
};

const downloadPdfFromMenu = async (
  page: Page,
  pdfItem: Locator,
  slug: string,
): Promise<{ ok: boolean; reason?: string; downloadBytes?: number }> => {
  const exportResponsePromise = page.waitForResponse(isExportPostOk, {
    timeout: MENU_TIMEOUT_MS,
  });
  const downloadPromise = page.waitForEvent("download", { timeout: MENU_TIMEOUT_MS });
  await pdfItem.click();
  const exportSettled = await settle(exportResponsePromise);
  const downloadSettled = await settle(downloadPromise);
  if (exportSettled.status === "rejected") {
    return {
      ok: false,
      reason: `ui pdf download failed: ${exportSettled.reason.message}`,
    };
  }
  const filePath = join(OUT_DIR, `${slug}-ui-download.pdf`);
  const download =
    downloadSettled.status === "fulfilled" ? downloadSettled.value : null;
  const bytes = await readDownloadBytes(download, exportSettled.value, filePath);
  if (!isPdf(bytes)) {
    return {
      ok: false,
      reason: "ui pdf download failed magic check",
      downloadBytes: bytes.length,
    };
  }
  return { ok: true, downloadBytes: bytes.length };
};

const openExportMenuAndShot = async (
  page: Page,
  route: string,
  slug: string,
  options?: { downloadPdf?: boolean },
): Promise<UiProofRow> => {
  await page.goto(`${CLIENT_BASE}${route}`, {
    waitUntil: "domcontentloaded",
    timeout: NAV_TIMEOUT_MS,
  });
  await page.locator("main").waitFor({ state: "visible", timeout: MAIN_WAIT_MS });

  const trigger = page
    .locator('button[aria-haspopup="menu"]')
    .filter({ hasText: EXPORT_LABEL_PATTERN })
    .first();
  const visibleResult = await settle(trigger.isVisible());
  const visible = visibleResult.status === "fulfilled" && visibleResult.value;
  if (!visible) {
    await page.screenshot({
      path: join(OUT_DIR, `${slug}-missing-export.png`),
      fullPage: true,
    });
    return { slug, ok: false, reason: "export menu trigger not visible" };
  }

  await trigger.click();
  await expectExpanded(trigger);

  const pdfItem = page.getByRole("menuitem", { name: PDF_MENU_PATTERN }).first();
  const docxItem = page.getByRole("menuitem", { name: DOCX_MENU_PATTERN }).first();
  await settle(pdfItem.waitFor({ state: "visible", timeout: MENU_TIMEOUT_MS }));
  const pdfVisible = await settle(pdfItem.isVisible());
  const docxVisible = await settle(docxItem.isVisible());
  const menuOk =
    pdfVisible.status === "fulfilled" &&
    pdfVisible.value &&
    docxVisible.status === "fulfilled" &&
    docxVisible.value;

  await page.screenshot({
    path: join(OUT_DIR, `${slug}-menu-open.png`),
    fullPage: true,
  });

  if (!menuOk) {
    return { slug, ok: false, reason: "pdf/docx menuitems missing" };
  }

  if (!options?.downloadPdf) {
    return { slug, ok: true };
  }

  const downloadResult = await downloadPdfFromMenu(page, pdfItem, slug);
  return { slug, ...downloadResult };
};

const runUiSurfaces = async (
  page: Page,
  surfaces: readonly UiSurface[],
): Promise<UiProofRow[]> => {
  const [head, ...tail] = surfaces;
  if (!head) {
    return [];
  }
  const first = await openExportMenuAndShot(page, head.route, head.slug, {
    downloadPdf: head.downloadPdf,
  });
  const rest = await runUiSurfaces(page, tail);
  return [first, ...rest];
};

const persistBinaryExports = async (
  rows: ProofRow[],
  resumeId: string,
  coverLetterId: string,
): Promise<void> => {
  await saveExport(rows, "resume", "pdf", buildResumeExportEndpoint(resumeId), {
    format: "pdf",
  });
  await saveExport(rows, "resume", "docx", buildResumeExportEndpoint(resumeId), {
    format: "docx",
  });
  await saveExport(rows, "cover-letter", "pdf", buildCoverLetterExportEndpoint(coverLetterId), {
    format: "pdf",
  });
  await saveExport(rows, "cover-letter", "docx", buildCoverLetterExportEndpoint(coverLetterId), {
    format: "docx",
  });
  await saveExport(rows, "portfolio", "pdf", `${API_ENDPOINTS.portfolio}/export`, {
    format: "pdf",
  });
  await saveExport(rows, "portfolio", "docx", `${API_ENDPOINTS.portfolio}/export`, {
    format: "docx",
  });
};

const main = async (): Promise<void> => {
  await mkdir(OUT_DIR, { recursive: true });
  const rows: ProofRow[] = [];
  const { resumeId, coverLetterId } = await seedEntities();
  await persistBinaryExports(rows, resumeId, coverLetterId);

  const hasDisplay = Boolean(process.env.DISPLAY && process.env.DISPLAY.length > 0);
  const forceHeadless = process.env.PAGE_PROOF_HEADLESS === "true";
  const browser = await chromium.launch(
    !forceHeadless && hasDisplay
      ? { headless: false, channel: "chrome" }
      : { headless: true },
  );
  const page = await browser.newPage({ viewport: VIEWPORT, acceptDownloads: true });

  const surfaces: readonly UiSurface[] = [
    {
      slug: "resume-preview",
      route: `${APP_ROUTES.resumePreview}?id=${encodeURIComponent(resumeId)}`,
      downloadPdf: true,
    },
    { slug: "portfolio", route: APP_ROUTES.portfolio, downloadPdf: false },
    { slug: "portfolio-preview", route: APP_ROUTES.portfolioPreview, downloadPdf: false },
    {
      slug: "cover-letter-detail",
      route: `${APP_ROUTES.coverLetter}/${encodeURIComponent(coverLetterId)}`,
      downloadPdf: false,
    },
  ];
  const uiRows = await runUiSurfaces(page, surfaces);
  await browser.close();

  const report = { API_BASE, CLIENT_BASE, binary: rows, ui: uiRows };
  const reportPath = join(OUT_DIR, "export-proof-report.json");
  await Bun.write(reportPath, JSON.stringify(report, null, 2));

  const binaryFails = rows.filter((row) => !row.ok);
  const uiFails = uiRows.filter((row) => !row.ok);
  await writeOutput(
    `export-proof: binary ${String(rows.length - binaryFails.length)}/${String(rows.length)} ok; ui ${String(uiRows.length - uiFails.length)}/${String(uiRows.length)} ok → ${reportPath}`,
  );
  if (binaryFails.length > 0 || uiFails.length > 0) {
    await writeError(
      [
        ...binaryFails.map(
          (fail) => `- binary ${fail.surface}.${fail.format}: ${fail.reason ?? "fail"}`,
        ),
        ...uiFails.map((fail) => `- ui ${fail.slug}: ${fail.reason ?? "fail"}`),
      ].join("\n"),
    );
    process.exitCode = 1;
  }
};

await main();

