const requestJson = async <T>(
  path: string,
  init: RequestInit = {},
): Promise<{ status: number; body: T }> => {
  const response = await fetch(`${VERIFY_API_BASE}${path}`, {
    ...init,
    headers: {
      ...(init.body ? { "content-type": "application/json" } : {}),
      ...(init.headers ?? {}),
    },
    signal:
      init.signal ??
      AbortSignal.timeout(init.body ? RUN_COMPLETION_TIMEOUT_MS : POLL_INTERVAL_MS * NUM_8),
  });
  const rawBody = await response.text();
  if (rawBody.trim().length === 0) {
    throw new Error(`Expected JSON response body for ${path}, received an empty payload.`);
  }

  return {
    status: response.status,
    body: JSON.parse(rawBody) as T,
  };
};

const normalizePathname = (pathname: string): string =>
