import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";
const NUM_40 = 40;
const NUM_80 = 80;

/**
 * Stub / noop / placeholder detection gate (AGENTS.md prohibited debt vocabulary).
 *
 * Catches:
 *   1. Inert event handlers: `@click=""`, `@click="noop"`, `@click="() => {}"`,
 *      `@click="undefined"`.
 *   2. Placeholder copy: "Lorem ipsum", "TBD", "coming soon", "not implemented".
 *   3. Dead CTAs: actionable controls (`<button`, `.btn`, `role="button"`) with
 *      no wiring — including icon-only / nested-content controls.
 *   4. Banned debt vocabulary in script/comments (authority paths exempt).
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts"]);

const inertHandlerPattern =
  /@(?:click|change|input|submit|focus|blur)(?:\.[\w-]+)*\s*=\s*["'](?:|noop|undefined)["']/gu;
const inertArrowHandlerPattern =
  /@(?:click|change|input|submit|focus|blur)(?:\.[\w-]+)*\s*=\s*"\(\)\s*=>\s*\{?\s*\}?"/gu;
const placeholderCopyPattern =
  /(?<!\w)(?:Lorem\s+ipsum|TBD|WIP|coming\s+soon|not\s+implemented)(?!\w)/giu;
const bannedVocabularyPattern =
  /\b(?:TODO|FIXME|HACK|XXX)\b|\b(?:barrel)\b|\b(?:deprecated\s+(?:since|in)\s+v\d)/giu;

/** Opening tag matcher — attributes may span lines; stops at unquoted `>`. */
const OPENING_TAG_PATTERN = /<([A-Za-z][\w-]*)\b((?:[^>"']|"[^"]*"|'[^']*')*)>/gu;

const CONTROL_HANDLER_PATTERN =
  /@click(?:\.[\w-]+)*\s*=|:(?:to|href)\s*=|\bto\s*=\s*["']|\bhref\s*=\s*["']|type\s*=\s*["']submit["']|\bform\s*=|\bfor\s*=/u;
const CONTROL_DISABLED_PATTERN = /\bdisabled\b|:disabled\s*=/u;
const BTN_CLASS_PATTERN = /\bbtn\b/u;
const ROLE_BUTTON_PATTERN = /\brole\s*=\s*["']button["']/u;
const COMMENT_SCAN_PATTERN = /<!--[\s\S]*?-->|\/\*[\s\S]*?\*\/|\/\/[^\n]*/gu;
const NESTED_TAG_STRIP_PATTERN = /<[^>]+>/gu;
const I18N_BINDING_STRIP_PATTERN = /\{\{[\s\S]*?\}\}/gu;
const WHITESPACE_COLLAPSE_PATTERN = /\s+/gu;
const VUE_COMPONENT_TAG_PATTERN = /^[A-Z]/u;
const NATIVE_CONTROL_INNER_PATTERN = /<(?:input|select|textarea)\b/iu;
const LINK_TO_ATTR_PATTERN = /(?:^|\s)(?:to|:to)\s*=/u;
const CLOSE_TAG_START_PATTERN = /<\//u;
const ARIA_HIDDEN_TRUE_PATTERN = /\baria-hidden\s*=\s*["']true["']/u;
const SWAP_CLASS_PATTERN = /\bswap\b/u;
const SCRIPT_BLOCK_PATTERN = /<script\b[^>]*>([\s\S]*?)<\/script>/gu;

const extractTemplateBlocks = (content: string): string => {
  const templateStart = content.indexOf("<template>");
  if (templateStart < 0) return "";
  const templateEnd = content.lastIndexOf("</template>");
  if (templateEnd <= templateStart) return content.slice(templateStart);
  return content.slice(templateStart, templateEnd + "</template>".length);
};

const extractScriptBlocks = (content: string): string => {
  const matches: string[] = [];
  SCRIPT_BLOCK_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(SCRIPT_BLOCK_PATTERN)) {
    matches.push(match[1] ?? "");
  }
  return matches.join("\n");
};

const isVueComponentTag = (tagName: string): boolean => VUE_COMPONENT_TAG_PATTERN.test(tagName);

const isActionableControlTag = (tagName: string, attrs: string): boolean => {
  // PascalCase Vue SFCs encapsulate their own wiring (e.g. AppExportMenu).
  if (isVueComponentTag(tagName)) return false;
  const normalized = tagName.toLowerCase();
  if (normalized === "button") return true;
  if (ROLE_BUTTON_PATTERN.test(attrs)) return true;
  if (BTN_CLASS_PATTERN.test(attrs)) return true;
  return false;
};

const hasNestedNativeControl = (template: string, openTagEnd: number, tagName: string): boolean => {
  const closeNeedle = `</${tagName}>`;
  const after = template.slice(openTagEnd);
  const closeIdx = after.toLowerCase().indexOf(closeNeedle.toLowerCase());
  if (closeIdx < 0) return false;
  const inner = after.slice(0, closeIdx);
  return NATIVE_CONTROL_INNER_PATTERN.test(inner);
};

const isLinkComponent = (tagName: string): boolean => {
  const normalized = tagName.toLowerCase();
  return normalized === "nuxtlink" || normalized === "nuxt-link" || normalized === "router-link";
};

const hasControlWiring = (tagName: string, attrs: string): boolean => {
  if (CONTROL_HANDLER_PATTERN.test(attrs)) return true;
  // NuxtLink / RouterLink without explicit attrs still needs :to — do not auto-pass.
  if (isLinkComponent(tagName) && LINK_TO_ATTR_PATTERN.test(attrs)) return true;
  return false;
};

const extractControlInnerPreview = (template: string, openTagEnd: number): string => {
  const after = template.slice(openTagEnd);
  const closeIdx = after.search(CLOSE_TAG_START_PATTERN);
  const inner = closeIdx >= 0 ? after.slice(0, closeIdx) : after.slice(0, NUM_80);
  return inner
    .replace(NESTED_TAG_STRIP_PATTERN, " ")
    .replace(I18N_BINDING_STRIP_PATTERN, " ")
    .replace(WHITESPACE_COLLAPSE_PATTERN, " ")
    .trim()
    .slice(0, NUM_40);
};

const collectInertHandlerViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const violations: ValidationViolation[] = [];
  const templateOffset = content.indexOf("<template>");

  inertHandlerPattern.lastIndex = 0;
  for (const match of template.matchAll(inertHandlerPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, (match.index ?? 0) + Math.max(0, templateOffset)),
      message: `Inert event handler ("${match[0]}") is a noop. Wire the handler to real state/service or remove the control. Stubs are forbidden.`,
    });
  }

  inertArrowHandlerPattern.lastIndex = 0;
  for (const match of template.matchAll(inertArrowHandlerPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, (match.index ?? 0) + Math.max(0, templateOffset)),
      message: `Inert arrow event handler ("${match[0]}") is a noop. Wire the handler to real state/service or remove the control. Stubs are forbidden.`,
    });
  }

  return violations;
};

const isExemptDeadControl = (
  tagName: string,
  attrs: string,
  template: string,
  openTagEnd: number,
): boolean => {
  if (!isActionableControlTag(tagName, attrs)) return true;
  if (CONTROL_DISABLED_PATTERN.test(attrs)) return true;
  if (ARIA_HIDDEN_TRUE_PATTERN.test(attrs)) return true;
  if (hasControlWiring(tagName, attrs)) return true;
  const normalized = tagName.toLowerCase();
  if (normalized === "summary") return true;
  if (
    normalized === "label" &&
    (SWAP_CLASS_PATTERN.test(attrs) || hasNestedNativeControl(template, openTagEnd, tagName))
  ) {
    return true;
  }
  return false;
};

const collectDeadControlViolations = (filePath: string, content: string): ValidationViolation[] => {
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const violations: ValidationViolation[] = [];
  const templateOffset = content.indexOf("<template>");

  OPENING_TAG_PATTERN.lastIndex = 0;
  for (const match of template.matchAll(OPENING_TAG_PATTERN)) {
    const tagName = match[1] ?? "";
    const attrs = match[2] ?? "";
    const openTagEnd = (match.index ?? 0) + match[0].length;
    if (isExemptDeadControl(tagName, attrs, template, openTagEnd)) continue;

    const preview = extractControlInnerPreview(template, openTagEnd);
    const label = preview.length > 0 ? preview : `(icon-only ${tagName})`;
    violations.push({
      filePath,
      line: getLineFromOffset(content, (match.index ?? 0) + Math.max(0, templateOffset)),
      message: `Dead CTA control "${label}" (<${tagName}> / .btn / role=button) has no @click / :to / to / type="submit" / href / for / form association. Wire it or remove it.`,
    });
  }

  return violations;
};

const collectPlaceholderCopyViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const violations: ValidationViolation[] = [];
  const templateOffset = content.indexOf("<template>");

  placeholderCopyPattern.lastIndex = 0;
  for (const match of template.matchAll(placeholderCopyPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, (match.index ?? 0) + Math.max(0, templateOffset)),
      message: `Placeholder copy "${match[0]}" found in template. Replace with real content or remove the surface. Stubs are forbidden.`,
    });
  }

  return violations;
};

const collectBannedVocabularyViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isUiSsotAuthority(filePath)) return [];
  if (filePath.endsWith(".test.ts") || filePath.endsWith(".spec.ts")) return [];
  // Locale catalogs carry natural-language copy (e.g. Spanish "todo" = "all").
  if (filePath.includes("/locales/")) return [];

  const script = extractScriptBlocks(content);
  const comments: string[] = [];
  COMMENT_SCAN_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(COMMENT_SCAN_PATTERN)) {
    comments.push(match[0] ?? "");
  }
  // Non-Vue TS modules: scan full content as script surface.
  const combined =
    script.length > 0 ? `${script}\n${comments.join("\n")}` : `${content}\n${comments.join("\n")}`;
  const violations: ValidationViolation[] = [];

  bannedVocabularyPattern.lastIndex = 0;
  for (const match of combined.matchAll(bannedVocabularyPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(combined, match.index ?? 0),
      message: `Banned debt vocabulary "${match[0]}" found. Replace with a real implementation. See AGENTS.md prohibited debt vocabulary.`,
    });
  }

  return violations;
};

export const collectStubNoopViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => [
  ...collectInertHandlerViolations(filePath, content),
  ...collectDeadControlViolations(filePath, content),
  ...collectPlaceholderCopyViolations(filePath, content),
  ...collectBannedVocabularyViolations(filePath, content),
];

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectStubNoopViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "UI stub/noop validation failed:",
    await collectViolations(),
    "UI stub/noop validation passed.",
  );
}

import { readdir } from "node:fs/promises";
import { join, relative, resolve } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

const REPO_ROOT = resolve(import.meta.dir, "..");
const CLIENT_OUTPUT_SERVER = join(REPO_ROOT, "packages", "client", ".output", "server");
const CLIENT_OUTPUT_PUBLIC = join(REPO_ROOT, "packages", "client", ".output", "public");

const pathExists = async (absolutePath: string): Promise<boolean> =>
  readdir(absolutePath).then(
    () => true,
    () => false,
  );

const collectMapFilesRecursive = async (
  directoryPath: string,
  accumulator: string[],
): Promise<void> => {
  const entries = await readdir(directoryPath, { withFileTypes: true });
  await Promise.all(
    entries.map(async (entry) => {
      const entryPath = join(directoryPath, entry.name);
      if (entry.isDirectory()) {
        await collectMapFilesRecursive(entryPath, accumulator);
        return;
      }
      if (entry.isFile() && entry.name.endsWith(".map")) {
        accumulator.push(entryPath);
      }
    }),
  );
};

const verifyNoSourceMapsUnder = async (
  rootLabel: string,
  absoluteRoot: string,
): Promise<readonly string[]> => {
  if (!(await pathExists(absoluteRoot))) {
    await writeOutput(`verify:production-client skip ${rootLabel} (directory missing)`);
    return [] as const;
  }

  const mapPaths: string[] = [];
  await collectMapFilesRecursive(absoluteRoot, mapPaths);
  return mapPaths.map((mapPath) => relative(REPO_ROOT, mapPath));
};

const main = async (): Promise<void> => {
  const [serverMaps, publicMaps] = await Promise.all([
    verifyNoSourceMapsUnder("ssr-output", CLIENT_OUTPUT_SERVER),
    verifyNoSourceMapsUnder("static-public", CLIENT_OUTPUT_PUBLIC),
  ]);
  const unexpectedMaps = [...serverMaps, ...publicMaps].sort((left, right) =>
    left.localeCompare(right),
  );

  if (unexpectedMaps.length > 0) {
    await writeError(
      `verify:production-client failed: unexpected source map files under .output:\n${unexpectedMaps.join("\n")}`,
    );
    process.exit(1);
  }

  await writeOutput(
    "verify:production-client passed (no .map under packages/client/.output/server|public).",
  );
};

await main().then(undefined, async (error: unknown) => {
  await writeError(error instanceof Error ? error.message : String(error));
  process.exit(1);
});

/**
 * ESLint softener gate — bans quality-rule demotions in client/root ESLint configs.
 *
 * Allowed "off" only:
 * - no-undef (TypeScript projectService owns globals)
 * - vue/multi-word-component-names on Nuxt pages/layouts/app/error only
 *
 * Layout/format rule mute-lists after flat/recommended are FORBIDDEN — use flat/essential
 * + explicit quality ratchets (Biome owns formatting).
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { reportViolations, type ValidationViolation } from "./utils/validation-helpers";

const CLIENT_ESLINT_PATH = "packages/client/eslint.config.js";
const ROOT_ESLINT_PATH = "eslint.config.mjs";

const ALLOWED_GLOBAL_OFF = new Set(["no-undef"]);
const ALLOWED_NUXT_PAGE_OFF = new Set(["vue/multi-word-component-names"]);

const RULE_OFF_PATTERN = /["']([^"']+)["']\s*:\s*["']off["']/gu;
const LAYOUT_MUTE_PATTERN =
  /vue\/(?:max-attributes-per-line|html-self-closing|singleline-html-element-content-newline|attributes-order|html-closing-bracket-spacing|first-attribute-linebreak|html-closing-bracket-newline)\s*["']?\s*:\s*["']off["']/u;
const NUXT_PAGES_GLOB_PATTERN = /pages\/\*\*\/\*\.vue/u;
const NUXT_LAYOUTS_GLOB_PATTERN = /layouts\/\*\*\/\*\.vue/u;

/**
 * Unused-ignore patterns are an evasion loophole: declaring
 * `argsIgnorePattern: "^_"` lets a developer silence noUnusedParameters by
 * prefixing any arg with `_`, hiding a real unused parameter (or in the
 * underscore-evasion case, an unused top-level declaration that eslint
 * classifies as a var). The canonical fix is to remove the unused symbol; the
 * gate bans these config keys so the loophole cannot be re-opened.
 */
const IGNORE_PATTERN_BAN_PATTERNS: ReadonlyArray<{ name: string; pattern: RegExp }> = [
  { name: "argsIgnorePattern", pattern: /argsIgnorePattern\s*:/u },
  { name: "varsIgnorePattern", pattern: /varsIgnorePattern\s*:/u },
  { name: "caughtErrorsIgnorePattern", pattern: /caughtErrorsIgnorePattern\s*:/u },
  { name: "destructuredArrayIgnorePattern", pattern: /destructuredArrayIgnorePattern\s*:/u },
];

const collectOffRules = (content: string): string[] => {
  const found: string[] = [];
  for (const match of content.matchAll(RULE_OFF_PATTERN)) {
    const rule = match[1];
    if (rule) {
      found.push(rule);
    }
  }
  return found;
};

const hasNuxtPageOverride = (content: string): boolean =>
  NUXT_PAGES_GLOB_PATTERN.test(content) && NUXT_LAYOUTS_GLOB_PATTERN.test(content);

const collectLayoutSoftenerViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  if (LAYOUT_MUTE_PATTERN.test(content)) {
    violations.push({
      filePath,
      line: 1,
      message:
        "Vue layout/format rule muted with off — forbidden softener. Use flat/essential + quality ratchets; Biome formats.",
    });
  }
  if (content.includes("flat/recommended") && content.includes("html-self-closing")) {
    violations.push({
      filePath,
      line: 1,
      message:
        "flat/recommended + layout mute pattern detected — switch to flat/essential (no layout softens).",
    });
  }
  if (!content.includes("flat/essential") && filePath === CLIENT_ESLINT_PATH) {
    violations.push({
      filePath,
      line: 1,
      message:
        'Client ESLint must use pluginVue.configs["flat/essential"] (quality, no layout mute).',
    });
  }
  return violations;
};

const collectOffRuleViolations = (filePath: string, content: string): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  const offRules = collectOffRules(content);
  for (const rule of offRules) {
    if (ALLOWED_GLOBAL_OFF.has(rule)) {
      continue;
    }
    if (ALLOWED_NUXT_PAGE_OFF.has(rule) && hasNuxtPageOverride(content)) {
      continue;
    }
    violations.push({
      filePath,
      line: 1,
      message: `ESLint rule "${rule}" set to off — forbidden softener (allowlist: no-undef; multi-word on Nuxt pages only).`,
    });
  }
  return violations;
};

const collectWarnSeverityViolations = (filePath: string, content: string): ValidationViolation[] => {
  if (!content.includes(': "warn"') && !content.includes(": 'warn'")) {
    return [];
  }
  return [
    {
      filePath,
      line: 1,
      message: 'ESLint severity "warn" is forbidden softener — use "error".',
    },
  ];
};

const collectIgnorePatternViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  for (const { name, pattern } of IGNORE_PATTERN_BAN_PATTERNS) {
    if (pattern.test(content)) {
      violations.push({
        filePath,
        line: 1,
        message: `ESLint ${name} config key is a forbidden unused-ignore evasion. Remove unused symbols at the source; do not open a prefix-ignore loophole.`,
      });
    }
  }
  return violations;
};

export const collectEslintSofteningViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  return [
    ...collectLayoutSoftenerViolations(filePath, content),
    ...collectOffRuleViolations(filePath, content),
    ...collectWarnSeverityViolations(filePath, content),
    ...collectIgnorePatternViolations(filePath, content),
  ];
};

const collectViolations = (): ValidationViolation[] => {
  const paths = [CLIENT_ESLINT_PATH, ROOT_ESLINT_PATH];
  return paths.flatMap((relativePath) => {
    const absolutePath = resolve(process.cwd(), relativePath);
    const content = readFileSync(absolutePath, "utf8");
    return collectEslintSofteningViolationsForContent(relativePath, content);
  });
};

if (import.meta.main) {
  await reportViolations(
    "ESLint softener validation failed:",
    collectViolations(),
    "ESLint softener validation passed.",
  );
}

