const pushBoundedLogLine = (target: string[], value: string): void => {
  const normalized = value.trim();
  if (normalized.length === 0) {
    return;
  }
  target.push(normalized);
  if (target.length > LOG_LINE_LIMIT) {
    target.shift();
  }
};

const resolveTauriCacheDir = (): string => {
  const envOverride = process.env.TAURI_CACHE_DIR?.trim();
  if (envOverride) {
    return envOverride;
  }

  if (process.platform === "darwin") {
    return join(homedir(), "Library", "Caches", "tauri");
  }

  if (process.platform === "win32") {
    const localAppData = process.env.LOCALAPPDATA?.trim();
    return join(
      localAppData && localAppData.length > 0 ? localAppData : join(homedir(), "AppData", "Local"),
      "tauri",
    );
  }

  const xdgCacheHome = process.env.XDG_CACHE_HOME?.trim();
  return join(
    xdgCacheHome && xdgCacheHome.length > 0 ? xdgCacheHome : join(homedir(), ".cache"),
    "tauri",
  );
};

const resolveWebviewBootstrapperSourcePath = (): string => {
  const envOverride = process.env.BAO_DESKTOP_WEBVIEW_BOOTSTRAPPER_PATH?.trim();
  if (envOverride) {
    return envOverride;
  }

  return join(resolveTauriCacheDir(), DESKTOP_RUNTIME_WINDOWS_WEBVIEW_BOOTSTRAPPER_FILENAME);
};

const resolveRuntimeTargetInfo = (tauriTarget: string | null): DesktopRuntimeTargetInfo =>
  tauriTarget
    ? resolveDesktopRuntimeTargetInfoFromTauriTarget(tauriTarget)
    : resolveDesktopRuntimeTargetInfoFromHost(process.platform, process.arch);

const captureStreamLines = async (
  stream: number | ReadableStream<Uint8Array> | undefined,
  target: string[],
): Promise<void> => {
  if (!(stream instanceof ReadableStream)) {
    return;
  }

  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let pending = "";

  const readChunk = async (): Promise<void> => {
    const result = await reader.read();
    if (result.done) {
      const trailing = `${pending}${decoder.decode()}`.trim();
      if (trailing.length > 0) {
        pushBoundedLogLine(target, trailing);
      }
      return;
    }

    const decoded = `${pending}${decoder.decode(result.value, { stream: true })}`;
    const lines = decoded.split(/\r?\n/gu);
    pending = lines.pop() ?? "";
    for (const line of lines) {
      pushBoundedLogLine(target, line);
    }

    await readChunk();
  };

  await readChunk();
};

const recordStreamCapture = (
  stream: number | ReadableStream<Uint8Array> | undefined,
  target: string[],
  label: string,
): void => {
  Promise.allSettled([captureStreamLines(stream, target)]).then(
    ([result]) => {
      if (result.status === "rejected") {
        pushBoundedLogLine(
          target,
          `[${label}] ${toErrorMessage(result.reason, `Failed to capture ${label}.`)}`,
        );
      }
    },
    (error) => {
      pushBoundedLogLine(
        target,
        `[${label}] ${toErrorMessage(error, `Failed to observe ${label}.`)}`,
      );
    },
  );
};

const waitForProcessExit = async (
  proc: ReturnType<typeof Bun.spawn>,
  processLabel: string,
): Promise<void> => {
  const [result] = await Promise.allSettled([proc.exited]);
  if (result.status === "rejected") {
    throw new Error(`Failed waiting for ${processLabel} to exit cleanly.`, {
      cause: result.reason,
    });
  }
};

const parseTargetArg = (argv: readonly string[]): string | null => {
  const targetIndex = argv.findIndex((argument) => argument === "--target" || argument === "-t");
  if (targetIndex === -1) {
    return null;
  }

  const targetValue = argv[targetIndex + 1];
  return typeof targetValue === "string" && targetValue.trim().length > 0
    ? targetValue.trim()
    : null;
};

const resolveTargetFromEnvironment = (): string | null => {
  const targetTriple = process.env.TAURI_ENV_TARGET_TRIPLE?.trim();
  if (targetTriple && targetTriple.length > 0) {
    return targetTriple;
  }

  const cargoTarget = process.env.CARGO_BUILD_TARGET?.trim();
  return cargoTarget && cargoTarget.length > 0 ? cargoTarget : null;
};

const resolveHostBunCompileTarget = (): string => {
  if (process.platform === "darwin") {
    return process.arch === "arm64" ? "bun-darwin-arm64" : "bun-darwin-x64";
  }
  if (process.platform === "linux") {
    return process.arch === "arm64" ? "bun-linux-arm64" : "bun-linux-x64";
  }
  if (process.platform === "win32") {
    return process.arch === "arm64" ? "bun-windows-arm64" : "bun-windows-x64-baseline";
  }

  throw new Error(
    `Unsupported host platform for Bun compile target: ${process.platform}/${process.arch}`,
  );
};

const resolveBunCompileTarget = (tauriTarget: string | null): string => {
  if (tauriTarget === null) {
    return resolveHostBunCompileTarget();
  }

  switch (tauriTarget) {
    case "aarch64-apple-darwin":
      return "bun-darwin-arm64";
    case "x86_64-apple-darwin":
      return "bun-darwin-x64";
    case "aarch64-unknown-linux-gnu":
      return "bun-linux-arm64";
    case "x86_64-unknown-linux-gnu":
      return "bun-linux-x64";
    case "x86_64-unknown-linux-musl":
      return "bun-linux-x64-musl";
    case "aarch64-unknown-linux-musl":
      return "bun-linux-arm64-musl";
    case "x86_64-pc-windows-msvc":
    case "x86_64-pc-windows-gnu":
      return "bun-windows-x64-baseline";
    case "i686-pc-windows-msvc":
    case "i686-pc-windows-gnu":
      throw new Error(
        "Unsupported desktop target for Bun compile: 32-bit Windows (i686) is not supported because Bun only provides Windows x64 and arm64 standalone runtime targets.",
      );
    case "aarch64-pc-windows-msvc":
      return "bun-windows-arm64";
    default:
      throw new Error(`Unsupported desktop target for Bun compile: ${tauriTarget}`);
  }
};

const resolveCompileTargetScratchRoot = (): string => {
  if (!compileTargetScratchRoot) {
    throw new Error("Compile target scratch root is not initialized.");
  }

  return compileTargetScratchRoot;
};

const shouldPrewarmCompileTarget = (compileTarget: string): boolean =>
  process.platform === "win32" && compileTarget.startsWith("bun-windows-");

const buildCompileTargetExecutableName = (compileTarget: string): string =>
  `${compileTarget}-v${Bun.version}`;

const buildCompileTargetTarballUrl = (compileTarget: string): string => {
  if (!compileTarget.startsWith("bun-")) {
    throw new Error(`Unsupported Bun compile target package name: ${compileTarget}`);
  }

  const packageSuffix = compileTarget.slice("bun-".length);
  return [
    BUN_COMPILE_TARGET_REGISTRY_URL,
    "@oven",
    `bun-${packageSuffix}`,
    "-",
    `bun-${packageSuffix}-${Bun.version}.tgz`,
  ].join("/");
};

type PrewarmedCompileTargetPaths = {
  readonly workingDirectory: string;
  readonly tarballPath: string;
  readonly extractedExecutablePath: string;
  readonly prewarmedExecutablePath: string;
};

const buildPrewarmedCompileTargetPaths = (compileTarget: string): PrewarmedCompileTargetPaths => {
  const scratchRoot = resolveCompileTargetScratchRoot();
  const workingDirectory = join(scratchRoot, "compile-targets", compileTarget);
  const extractedDirectory = join(workingDirectory, "package");

  return {
    workingDirectory,
    tarballPath: join(workingDirectory, "target.tgz"),
    extractedExecutablePath: join(extractedDirectory, "bin", "bun.exe"),
    prewarmedExecutablePath: join(
      workingDirectory,
      buildCompileTargetExecutableName(compileTarget),
    ),
  };
};

const downloadCompileTargetTarball = async (
  compileTarget: string,
  tarballPath: string,
): Promise<void> => {
  const tarballUrl = buildCompileTargetTarballUrl(compileTarget);
  const tarballResponse = await fetch(tarballUrl, {
    signal: AbortSignal.timeout(READY_TIMEOUT_MS),
  });
  if (!tarballResponse.ok) {
    throw new Error(
      `Unable to download ${compileTarget} tarball from ${tarballUrl}: ${tarballResponse.status} ${tarballResponse.statusText}`,
    );
  }

  await writeFile(tarballPath, Buffer.from(await tarballResponse.arrayBuffer()));
};

const extractCompileTargetExecutable = async (
  paths: PrewarmedCompileTargetPaths,
): Promise<void> => {
  await runCommand(["tar", "-xzf", paths.tarballPath, "-C", paths.workingDirectory]);

  if (!(await Bun.file(paths.extractedExecutablePath).exists())) {
    throw new Error(
      `Prewarmed Bun compile target executable is missing after extraction: ${paths.extractedExecutablePath}`,
    );
  }

  await cp(paths.extractedExecutablePath, paths.prewarmedExecutablePath, { force: true });
};

const prepareCompileTargetDirectory = async (compileTarget: string): Promise<string> => {
  const paths = buildPrewarmedCompileTargetPaths(compileTarget);
  if (await Bun.file(paths.prewarmedExecutablePath).exists()) {
    return paths.workingDirectory;
  }

  await mkdir(paths.workingDirectory, { recursive: true });
  await writeOutput(
    `desktop-runtime: prewarming official Bun compile target ${compileTarget} for ${Bun.version}`,
  );
  await downloadCompileTargetTarball(compileTarget, paths.tarballPath);
  await extractCompileTargetExecutable(paths);
  return paths.workingDirectory;
};

const ensurePrewarmedCompileTargetDirectory = async (compileTarget: string): Promise<string> => {
  const existingDirectory = prewarmedCompileTargetDirectories.get(compileTarget);
  if (existingDirectory) {
    return await existingDirectory;
  }

  const preparation = prepareCompileTargetDirectory(compileTarget);

  const trackedPreparation = preparation.then(
    (workingDirectory) => workingDirectory,
    (error: unknown) => {
      prewarmedCompileTargetDirectories.delete(compileTarget);
      return Promise.reject(error instanceof Error ? error : new Error(toErrorMessage(error)));
    },
  );

  prewarmedCompileTargetDirectories.set(compileTarget, trackedPreparation);
  return trackedPreparation;
};

const runCommand = async (
  command: readonly string[],
  options: {
    cwd?: string;
    env?: Record<string, string | undefined>;
  } = {},
): Promise<void> => {
  const proc = Bun.spawn(command as string[], {
    cwd: options.cwd ?? REPO_ROOT,
    env: options.env ?? process.env,
    stdout: "inherit",
    stderr: "inherit",
  });
  const exitCode = await proc.exited;
  if (exitCode !== 0) {
    throw new Error(`${command.join(" ")} exited with code ${exitCode}`);
  }
};

const readStreamText = async (
  stream: number | ReadableStream<Uint8Array> | undefined,
): Promise<string> => {
  if (!(stream instanceof ReadableStream)) {
    return "";
  }

  return await new Response(stream).text();
};

const runCommandCaptured = async (
  command: readonly string[],
  options: {
    cwd?: string;
    env?: Record<string, string | undefined>;
  } = {},
): Promise<{
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
}> => {
  const proc = Bun.spawn(command as string[], {
    cwd: options.cwd ?? REPO_ROOT,
    env: options.env ?? process.env,
    stdout: "pipe",
    stderr: "pipe",
  });

  const [stdout, stderr, exitCode] = await Promise.all([
    readStreamText(proc.stdout),
    readStreamText(proc.stderr),
    proc.exited,
  ]);

  if (stdout.length > 0) {
    process.stdout.write(stdout);
  }
  if (stderr.length > 0) {
    process.stderr.write(stderr);
  }

  return {
    exitCode,
    stdout,
    stderr,
  };
};

const isServiceReady = async (url: string): Promise<boolean> => {
  const fetchResult = await Promise.resolve(
    fetch(url, { signal: AbortSignal.timeout(POLL_INTERVAL_MS) }),
  ).then(
    (response) => response.ok,
    () => false,
  );

  return fetchResult;
};

const waitForCondition = async (
  condition: () => Promise<boolean>,
  timeoutMessage: string,
  deadline: number = Date.now() + READY_TIMEOUT_MS,
): Promise<void> => {
  if (await condition()) {
    return;
  }

  if (Date.now() >= deadline) {
    throw new Error(timeoutMessage);
  }

  await Bun.sleep(POLL_INTERVAL_MS);
  await waitForCondition(condition, timeoutMessage, deadline);
};

const waitForService = async (url: string): Promise<void> => {
  await waitForCondition(() => isServiceReady(url), `Timed out waiting for ${url}`);
};

const ensureBuildServerPortIsFree = async (): Promise<void> => {
  if (await isServiceReady(`${BUILD_SERVER_API_BASE}/api/health`)) {
    throw new Error(
      `Desktop runtime build port ${DESKTOP_RUNTIME_BUILD_SERVER_PORT} is already serving HTTP traffic.`,
    );
  }
};

const startBuildServer = async (
  tempDbPath: string,
): Promise<{
  proc: ReturnType<typeof Bun.spawn>;
}> => {
  const stdoutLines: string[] = [];
  const stderrLines: string[] = [];
  const env = {
    ...process.env,
    BAO_DISABLE_AUTH: "true",
    CLIENT_PORT: `${DESKTOP_RUNTIME_VERIFY_FRONTEND_PORT}`,
    CORS_ORIGINS: DESKTOP_RUNTIME_CORS_ORIGINS.join(","),
    DB_PATH: tempDbPath,
    HOST: DESKTOP_RUNTIME_HOST,
    LOG_LEVEL: "warn",
    PORT: `${DESKTOP_RUNTIME_BUILD_SERVER_PORT}`,
  };

  const proc = Bun.spawn([process.execPath, SERVER_DIST_ENTRYPOINT], {
    cwd: REPO_ROOT,
    env,
    stdin: "ignore",
    stdout: "pipe",
    stderr: "pipe",
  });

  recordStreamCapture(proc.stdout, stdoutLines, "desktop-runtime-build-stdout");
  recordStreamCapture(proc.stderr, stderrLines, "desktop-runtime-build-stderr");

  const waitResult = await captureResult(() =>
    waitForService(`${BUILD_SERVER_API_BASE}/api/health`),
  );
  if (!waitResult.ok) {
    proc.kill();
    await waitForProcessExit(proc, "desktop runtime build server");
    const logDump = [...stdoutLines, ...stderrLines].join("\n");
    const message = toErrorMessage(
      waitResult.error,
      `Timed out waiting for ${BUILD_SERVER_API_BASE}/api/health`,
    );
    throw new Error(logDump.length > 0 ? `${message}\n${logDump}` : message, {
      cause: waitResult.error,
    });
  }

  return {
    proc,
  };
};

const stopProcess = async (proc: ReturnType<typeof Bun.spawn>): Promise<void> => {
  proc.kill();
  await waitForProcessExit(proc, "desktop runtime build server");
};

const isTextFile = (filePath: string): boolean => {
  const extension = extname(filePath).toLowerCase();
  return extension.length === 0 || TEXT_FILE_EXTENSIONS.has(extension);
};

const visitTextFiles = async (
  path: string,
  visitor: (filePath: string) => Promise<void>,
): Promise<void> => {
  const currentStat = await stat(path);
  if (currentStat.isDirectory()) {
    const entries = await readdir(path, { withFileTypes: true });
    await Promise.all(entries.map((entry) => visitTextFiles(join(path, entry.name), visitor)));
    return;
  }

  if (isTextFile(path)) {
    await visitor(path);
  }
};

const rewriteGeneratedRuntimeBase = async (directoryPath: string): Promise<void> => {
  await visitTextFiles(directoryPath, async (filePath) => {
    const sourceText = await readFile(filePath, "utf8");
    const nextText = sourceText
      .replaceAll(BUILD_SERVER_API_BASE, DESKTOP_RUNTIME_API_BASE)
      .replaceAll(BUILD_SERVER_WS_BASE, DESKTOP_RUNTIME_WS_BASE);

    if (nextText !== sourceText) {
      await writeFile(filePath, nextText, "utf8");
    }
  });
};

const assertNoBuildRuntimeLeak = async (directoryPath: string): Promise<void> => {
  await visitTextFiles(directoryPath, async (filePath) => {
    const fileText = await readFile(filePath, "utf8");
    if (fileText.includes(BUILD_SERVER_API_BASE) || fileText.includes(BUILD_SERVER_WS_BASE)) {
      throw new Error(`Build-only desktop API endpoint leaked into ${filePath}`);
    }
  });
};

const ensureStaticFrontendEntrypoint = async (directoryPath: string): Promise<void> => {
  const indexPath = join(directoryPath, "index.html");
  if (await Bun.file(indexPath).exists()) {
    return;
  }

  const spaFallbackPath = join(directoryPath, "200.html");
  if (!(await Bun.file(spaFallbackPath).exists())) {
    throw new Error(
      "Static desktop frontend is missing packages/client/.output/public/index.html and 200.html",
    );
  }

  await cp(spaFallbackPath, indexPath, { force: true });
};

const buildDesktopClient = async (tempDbPath: string): Promise<void> => {
  await writeOutput("desktop-runtime: building server bundle for desktop prerender");
  await runCommand([process.execPath, "run", "--cwd", "packages/server", "build"]);

  await ensureBuildServerPortIsFree();
  await writeOutput(
    "desktop-runtime: starting temporary API server for static desktop client generation",
  );
  const { proc } = await startBuildServer(tempDbPath);

  await withCleanup(
    async () => {
      await writeOutput("desktop-runtime: generating static Nuxt desktop frontend");
      const clientNuxtDir = join(CLIENT_ROOT, ".nuxt");
      const clientOutputDir = join(CLIENT_ROOT, ".output");
      await rm(clientNuxtDir, { recursive: true, force: true });
      await rm(clientOutputDir, { recursive: true, force: true });

      const generateEnv = {
        ...process.env,
        BAO_DISABLE_AUTH: "true",
        NUXT_PUBLIC_API_BASE: BUILD_SERVER_API_BASE,
        NUXT_PUBLIC_WS_BASE: BUILD_SERVER_WS_BASE,
      };

      if (process.platform === "win32") {
        /**
         * On Windows, `bun --bun run nuxt generate` (the package.json script)
         * causes a segfault because Bun's Node interop layer cannot handle
         * Nuxt's complex SSR/prerender pipeline. Invoke `nuxt generate` directly
         * without the `--bun` override so Bun delegates heavy Node.js work to
         * its standard execution path.
         */
        await runCommand([process.execPath, "run", "nuxt", "generate"], {
          cwd: CLIENT_ROOT,
          env: generateEnv,
        });
      } else {
        await runCommand([process.execPath, "run", "--cwd", "packages/client", "generate"], {
          env: generateEnv,
        });
      }
    },
    () => stopProcess(proc),
  );

  await rewriteGeneratedRuntimeBase(CLIENT_PUBLIC_ROOT);
  await ensureStaticFrontendEntrypoint(CLIENT_PUBLIC_ROOT);
  await assertNoBuildRuntimeLeak(CLIENT_PUBLIC_ROOT);
};

type CompileRetryContext = {
  readonly command: readonly string[];
  readonly commandCwd: string;
  readonly compileTarget: string;
  readonly outputPath: string;
  readonly attempt?: number;
};

const runCompileCommandWithRetries = async ({
  command,
  commandCwd,
  compileTarget,
  outputPath,
  attempt = 1,
}: CompileRetryContext): Promise<void> => {
  const result = await runCommandCaptured(command, { cwd: commandCwd });
  if (result.exitCode === 0) {
    return;
  }

  const combinedOutput = `${result.stdout}\n${result.stderr}`;
  const canRetryExtractionFailure =
    process.platform === "win32" &&
    compileTarget.startsWith("bun-windows-") &&
    attempt < COMPILE_RETRY_LIMIT &&
    BUN_COMPILE_EXTRACTION_FAILURE_PATTERN.test(combinedOutput);

  if (!canRetryExtractionFailure) {
    throw new Error(`${command.join(" ")} exited with code ${result.exitCode}`);
  }

  await writeOutput(
    `desktop-runtime: Bun compile target download for ${compileTarget} was incomplete; clearing Bun package cache and retrying`,
  );
  await runCommand([process.execPath, "pm", "cache", "rm"]);
  await rm(outputPath, { force: true });
  await runCompileCommandWithRetries({
    command,
    commandCwd,
    compileTarget,
    outputPath,
    attempt: attempt + 1,
  });
};

const STAGED_TEST_FILE_SUFFIXES = [".test.ts", ".test.tsx", ".spec.ts", ".spec.tsx"] as const;

const removeStagedTestSourcesUnder = async (rootDir: string): Promise<void> => {
  const entries = await readdir(rootDir, { withFileTypes: true });
  await Promise.all(
    entries.map(async (entry) => {
      const fullPath = join(rootDir, entry.name);
      if (entry.isDirectory()) {
        await removeStagedTestSourcesUnder(fullPath);
        return;
      }
      if (
        entry.isFile() &&
        STAGED_TEST_FILE_SUFFIXES.some((suffix) => entry.name.endsWith(suffix))
      ) {
        await rm(fullPath, { force: true });
      }
    }),
  );
};

const LINUX_DESKTOP_SERVER_PAYLOAD_BASENAME = "bao-desktop-server.payload.gz" as const;
const LINUX_BUN_SCRIPT_RUNNER_PAYLOAD_BASENAME = "bao-bun.payload.gz" as const;

/**
 * Build a POSIX shell launcher script that extracts and executes a gzipped payload.
 * Uses character code assembly to avoid biome false positives on shell syntax in string literals.
 */
const buildLauncherScript = (payloadBasename: string): string => {
  const lines: string[] = [];
  lines.push("#!/usr/bin/env sh");
  lines.push("set -eu");
  const cd = [
    NUM_36, NUM_40, NUM_67, NUM_68, NUM_80, NUM_65, NUM_84, NUM_72, NUM_61, NUM_32, NUM_99, NUM_100, NUM_32, NUM_45, NUM_45, NUM_32, NUM_36, NUM_40, NUM_100, NUM_105, NUM_114, NUM_110, NUM_97,
    NUM_109, NUM_101, NUM_32, NUM_36, NUM_48, NUM_41, NUM_32, NUM_38, NUM_38, NUM_32, NUM_112, NUM_119, NUM_100, NUM_41,
  ];
  lines.push(
    `here=${String.fromCharCode(NUM_34)}${String.fromCharCode(...cd)}${String.fromCharCode(NUM_34)}`,
  );
  lines.push(`payload="$here/${payloadBasename}"`);
  const tmpChars = [
    NUM_36, NUM_40, NUM_109, NUM_107, NUM_116, NUM_101, NUM_109, NUM_112, NUM_32, NUM_36, NUM_123, NUM_84, NUM_77, NUM_80, NUM_68, NUM_73, NUM_82, NUM_58, NUM_45, NUM_47, NUM_116, NUM_109,
    NUM_112, NUM_125, NUM_47, NUM_98, NUM_97, NUM_111, NUM_45, NUM_114, NUM_116, NUM_46, NUM_88, NUM_88, NUM_88, NUM_88, NUM_88, NUM_41,
  ];
  lines.push(
    `tmp=${String.fromCharCode(NUM_34)}${String.fromCharCode(...tmpChars)}${String.fromCharCode(NUM_34)}`,
  );
  lines.push(`cleanup() { rm -f ${String.fromCharCode(NUM_34)}$tmp${String.fromCharCode(NUM_34)}; }`);
  lines.push("trap cleanup EXIT INT HUP TERM");
  lines.push(
    `command -v gzip >/dev/null 2>&1 || { echo ${String.fromCharCode(NUM_34)}error: gzip is not installed or not in PATH${String.fromCharCode(NUM_34)} >&2; exit 1; }`,
  );
  lines.push(
    `gzip -dc ${String.fromCharCode(NUM_34)}$payload${String.fromCharCode(NUM_34)} > ${String.fromCharCode(NUM_34)}$tmp${String.fromCharCode(NUM_34)}`,
  );
  lines.push(`chmod 700 ${String.fromCharCode(NUM_34)}$tmp${String.fromCharCode(NUM_34)}`);
  lines.push(
    `exec ${String.fromCharCode(NUM_34)}$tmp${String.fromCharCode(NUM_34)} ${String.fromCharCode(NUM_34)}$@${String.fromCharCode(NUM_34)}`,
  );
  return `${lines.join("\n")}\n`;
};

/**
 * AppImage bundling runs linuxdeploy, which walks bundled ELFs under `usr/lib/<app>/` and runs `ldd`.
 * Bun-produced binaries can make that step abort; a shell launcher plus a `.gz` payload keeps the manifest
 * paths stable while avoiding extra ELF registrations in the AppDir.
 */
const packLinuxElfBinaryAsGzipLauncher = async (
  executablePath: string,
  payloadBasename: string,
): Promise<void> => {
  const payloadPath = join(dirname(executablePath), payloadBasename);
  const raw = await Bun.file(executablePath).arrayBuffer();
  await Bun.write(payloadPath, gzipSync(Buffer.from(raw)));
  await chmod(payloadPath, FILE_MODE_RW_R_R);
  const launcher = buildLauncherScript(payloadBasename);
  await Bun.write(executablePath, launcher);
  await chmod(executablePath, FILE_MODE_RWX_RX_RX);
};

const compileRuntimeBinary = async (
  compileTarget: string,
  entrypointPath: string,
  outputPath: string,
): Promise<void> => {
  await mkdir(dirname(outputPath), { recursive: true });
  const commandCwd = shouldPrewarmCompileTarget(compileTarget)
    ? await ensurePrewarmedCompileTargetDirectory(compileTarget)
    : REPO_ROOT;
  const command = [
    process.execPath,
    "build",
    "--compile",
    "--target",
    compileTarget,
    entrypointPath,
    "--outfile",
    outputPath,
  ];
  await runCompileCommandWithRetries({
    command,
    commandCwd,
    compileTarget,
    outputPath,
  });
};

const stageScraperRuntime = async (): Promise<void> => {
  const destinationPath = join(RUNTIME_ROOT, DESKTOP_RUNTIME_SCRAPER_DIR);
  await writeOutput("desktop-runtime: staging scraper runtime resources");
  await mkdir(destinationPath, { recursive: true });

  await Promise.all(
    SCRAPER_RUNTIME_STAGE_SOURCE_PATHS.map((relativePath) =>
      cp(join(SCRAPER_ROOT, relativePath), join(destinationPath, relativePath), {
        recursive: true,
        force: true,
      }),
    ),
  );

  const runtimeDependencyRoots = await collectRuntimeDependencySourceRoots(SCRAPER_ROOT);
  await Promise.all(
    Array.from(runtimeDependencyRoots, async ([packageName, sourceRoot]) => {
      const packageDestinationPath = join(destinationPath, "node_modules", packageName);
      await mkdir(dirname(packageDestinationPath), { recursive: true });
      await cp(sourceRoot, packageDestinationPath, {
        recursive: true,
        force: true,
      });
      await rm(join(packageDestinationPath, "node_modules"), {
        recursive: true,
        force: true,
      });
    }),
  );

  await removeStagedTestSourcesUnder(destinationPath);

  await writeOutput(
    `desktop-runtime: staged scraper runtime package plus ${runtimeDependencyRoots.size} runtime dependencies`,
  );
};

const stageWebviewBootstrapper = async (
  runtimeTargetInfo: DesktopRuntimeTargetInfo,
): Promise<string | null> => {
  if (!runtimeTargetInfo.defaultWebviewBootstrapperExecutable) {
    return null;
  }

  const sourcePath = resolveWebviewBootstrapperSourcePath();
  if (!(await Bun.file(sourcePath).exists())) {
    throw new Error(
      `Bundled WebView2 bootstrapper was not found at ${sourcePath}. Set BAO_DESKTOP_WEBVIEW_BOOTSTRAPPER_PATH or TAURI_CACHE_DIR before building the Windows desktop release.`,
    );
  }

  const destinationRelativePath = runtimeTargetInfo.defaultWebviewBootstrapperExecutable;
  const destinationPath = join(RUNTIME_ROOT, destinationRelativePath);
  await mkdir(dirname(destinationPath), { recursive: true });
  await cp(sourcePath, destinationPath, { force: true });
  await writeOutput(`desktop-runtime: staged bundled WebView2 bootstrapper from ${sourcePath}`);
  return destinationRelativePath;
};

const stageBundledScriptRunnerRuntime = async (
  runtimeTargetInfo: DesktopRuntimeTargetInfo,
): Promise<void> => {
  const bunBinaryPath = join(RUNTIME_ROOT, runtimeTargetInfo.scriptRunnerExecutable);
  const entrypointPath = join(RUNTIME_ROOT, runtimeTargetInfo.scriptRunnerEntrypoint);

  await mkdir(dirname(bunBinaryPath), { recursive: true });
  await cp(process.execPath, bunBinaryPath, { force: true });
  await cp(SCRIPT_RUNNER_ENTRYPOINT, entrypointPath, { force: true });
  await chmod(bunBinaryPath, FILE_MODE_RWX_RX_RX);
};

const writeRuntimeManifest = async (
  runtimeTargetInfo: DesktopRuntimeTargetInfo,
  webviewBootstrapperExecutable: string | null,
): Promise<void> => {
  const manifest: DesktopRuntimeManifest = buildDesktopRuntimeManifest(runtimeTargetInfo.target, {
    webviewBootstrapperExecutable,
  });

  await mkdir(resolve(RUNTIME_MANIFEST_PATH, ".."), { recursive: true });
  await writeFile(RUNTIME_MANIFEST_PATH, `${JSON.stringify(manifest, null, 2)}\n`, "utf8");
};

const prepareRuntimeResources = async (tauriTarget: string | null): Promise<void> => {
  const compileTarget = resolveBunCompileTarget(tauriTarget);
  const runtimeTargetInfo = resolveRuntimeTargetInfo(tauriTarget);
  const serverExecutablePath = join(RUNTIME_ROOT, runtimeTargetInfo.serverExecutable);

  await writeOutput(`desktop-runtime: compiling bundled desktop server (${compileTarget})`);
  await compileRuntimeBinary(compileTarget, SERVER_ENTRYPOINT, serverExecutablePath);
  if (compileTarget.startsWith("bun-linux")) {
    await writeOutput(
      "desktop-runtime: packing Linux server as gzip payload + POSIX launcher (AppImage / linuxdeploy support)",
    );
    await packLinuxElfBinaryAsGzipLauncher(
      serverExecutablePath,
      LINUX_DESKTOP_SERVER_PAYLOAD_BASENAME,
    );
  }

  await writeOutput(
    `desktop-runtime: staging bundled Bun runtime and entrypoint helper for script execution (${compileTarget})`,
  );
  await stageBundledScriptRunnerRuntime(runtimeTargetInfo);
  if (compileTarget.startsWith("bun-linux")) {
    await writeOutput(
      "desktop-runtime: packing Linux bundled Bun binary as gzip payload + POSIX launcher (AppImage / linuxdeploy support)",
    );
    await packLinuxElfBinaryAsGzipLauncher(
      join(RUNTIME_ROOT, runtimeTargetInfo.scriptRunnerExecutable),
      LINUX_BUN_SCRIPT_RUNNER_PAYLOAD_BASENAME,
    );
  }

  await stageScraperRuntime();
  const webviewBootstrapperExecutable = await stageWebviewBootstrapper(runtimeTargetInfo);
  await writeRuntimeManifest(runtimeTargetInfo, webviewBootstrapperExecutable);
};

const main = async (): Promise<void> => {
  const tauriTarget = parseTargetArg(process.argv.slice(2)) ?? resolveTargetFromEnvironment();
  const tempRoot = await mkdtemp(join(tmpdir(), "bao-desktop-runtime-"));
  const tempDbPath = join(tempRoot, "desktop-build.db");
  compileTargetScratchRoot = tempRoot;
  prewarmedCompileTargetDirectories.clear();

  await withCleanup(
    async () => {
      await writeOutput(
        `desktop-runtime: preparing resources${tauriTarget ? ` for ${tauriTarget}` : ""}`,
      );
      await rm(RUNTIME_ROOT, { recursive: true, force: true });
      await mkdir(RUNTIME_ROOT, { recursive: true });

      await buildDesktopClient(tempDbPath);
      await prepareRuntimeResources(tauriTarget);

      await ensureStaticFrontendEntrypoint(CLIENT_PUBLIC_ROOT);

      await writeOutput("desktop-runtime: preparation complete");
    },
    async () => {
      compileTargetScratchRoot = null;
      prewarmedCompileTargetDirectories.clear();
      await rm(tempRoot, { recursive: true, force: true });
    },
  );
};

await main().then(undefined, async (error: unknown) => {
  const message = toErrorMessage(error);
  await writeError(`desktop-runtime: preparation failed: ${message}`);
  process.exit(1);
});

#!/usr/bin/env bun
/**
 * Playwright interaction proof for the setup wizard.
 *
 * Drives the wizard with real keystrokes (page.type) and real clicks
 * (page.click) — the same DOM events a human produces. Verifies Vue
 * reactivity binds the typed name and advances steps on click.
 *
 * Run: bun run scripts/verify-setup-wizard-interaction.ts
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright";

const __dirname = dirname(fileURLToPath(import.meta.url));
const CLIENT_BASE = "http://127.0.0.1:3001";
const PROOF_DIR = join(__dirname, "..", "docs", "ssot-ledger", "setup-wizard-proof");
mkdirSync(PROOF_DIR, { recursive: true });
const NAV_TIMEOUT_MS = 30_000;
const SELECTOR_TIMEOUT_MS = 10_000;
const TYPE_DELAY_MS = 30;
const STEP2_INDICATOR_SELECTOR = "li.step:nth-child(2).step-primary";
const STEP3_INDICATOR_SELECTOR = "li.step:nth-child(3).step-primary";
const results: string[] = [];
const record = (msg: string): void => {
  results.push(msg);
};

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

const consoleErrors: string[] = [];
page.on("console", (msg) => {
  if (msg.type() === "error") consoleErrors.push(msg.text());
});

await page.goto(`${CLIENT_BASE}/setup`, {
  waitUntil: "domcontentloaded",
  timeout: NAV_TIMEOUT_MS,
});
// Web-first wait: button presence proves Vue hydrated and attached listeners
await page.waitForSelector("button.btn", { timeout: SELECTOR_TIMEOUT_MS });

const step1Heading = await page.textContent("h2");
record(`step1-heading: ${step1Heading ?? "null"}`);

// Real keystroke typing — dispatches keydown/keypress/input/keyup per char
await page.click("input.input");
await page.type("input.input", "Brandon", { delay: TYPE_DELAY_MS });
const nameValue = await page.inputValue("input.input");
record(`name-value-after-type: ${nameValue}`);

// Real click — dispatches mousedown/mouseup/click
const buttonCount = await page.locator("button.btn").count();
record(`button-count: ${String(buttonCount)}`);
const buttonText = await page.textContent("button.btn");
record(`button-text: ${buttonText ?? "null"}`);
await page.click("button.btn");
// Web-first wait: step 2 indicator proves the step advanced
await page.waitForSelector(STEP2_INDICATOR_SELECTOR, { timeout: SELECTOR_TIMEOUT_MS });

const step2Heading = await page.textContent("h2");
record(`step2-heading: ${step2Heading ?? "null"}`);
const step2Active = await page.locator("li.step.step-primary").count();
record(`step-primary-count: ${String(step2Active)}`);

await page.screenshot({ path: join(PROOF_DIR, "step2.png"), fullPage: true });
record("screenshot-step2: /tmp/bbb-setup-step2.png");

// Advance to step 3 — click the forward button on step 2
const step2ButtonCount = await page.locator("button.btn").count();
record(`step2-button-count: ${String(step2ButtonCount)}`);
const lastButtonText = await page.locator("button.btn").last().textContent();
record(`step2-last-button-text: ${lastButtonText ?? "null"}`);
await page.locator("button.btn").last().click();
// Web-first wait: step 3 indicator proves the step advanced
await page.waitForSelector(STEP3_INDICATOR_SELECTOR, { timeout: SELECTOR_TIMEOUT_MS });

const step3Heading = await page.textContent("h2");
record(`step3-heading: ${step3Heading ?? "null"}`);
const step3Active = await page.locator("li.step.step-primary").count();
record(`step3-primary-count: ${String(step3Active)}`);

await page.screenshot({ path: join(PROOF_DIR, "step3.png"), fullPage: true });
record("screenshot-step3: /tmp/bbb-setup-step3.png");

// Complete the wizard — click the final action button on step 3
const step3ButtonCount = await page.locator("button.btn").count();
record(`step3-button-count: ${String(step3ButtonCount)}`);
const completeButtonText = await page.locator("button.btn").last().textContent();
record(`step3-last-button-text: ${completeButtonText ?? "null"}`);
await page.locator("button.btn").last().click();

const finalUrl = page.url();
record(`final-url: ${finalUrl}`);
const finalHeading = await page.textContent("h1").then(
  (text) => text ?? "null",
  () => "null",
);
record(`final-h1: ${finalHeading}`);

await page.screenshot({ path: join(PROOF_DIR, "complete.png"), fullPage: true });
record("screenshot-complete: /tmp/bbb-setup-complete.png");

record(`console-errors: ${String(consoleErrors.length)}`);
for (const err of consoleErrors) {
  record(`  console-error: ${err}`);
}

await browser.close();

const output = results.join("\n");
writeFileSync(join(PROOF_DIR, "results.txt"), output);

if (consoleErrors.length > 0) {
  throw new Error(
    `Setup wizard interaction proof failed: ${consoleErrors.length} console error(s)`,
  );
}

import {
  AGENTIFLOW_CAPABILITY_MATRIX_PATH,
  buildAgentiflowCapabilityMatrix,
  resolveAgentiflowCapabilityMatrixRelativePath,
} from "./utils/agentiflow-capability-matrix";
import { captureResult, toErrorMessage } from "./utils/async-control";
import { formatJsonWithBiome } from "./utils/biome-format";
import { writeError, writeOutput } from "./utils/cli-output";

type JsonRecord = Record<string, unknown>;

const isRecord = (value: unknown): value is JsonRecord =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const normalizeMatrixForComparison = (value: unknown): unknown => {
  if (!isRecord(value)) {
    return value;
  }

  const normalizedValue = { ...value };
  normalizedValue.generatedAt = undefined;
  return normalizedValue;
};

const main = async (): Promise<void> => {
  const matrix = await buildAgentiflowCapabilityMatrix();
  const expectedText = await formatJsonWithBiome(
    AGENTIFLOW_CAPABILITY_MATRIX_PATH,
    normalizeMatrixForComparison(matrix),
  );
  const matrixFile = Bun.file(AGENTIFLOW_CAPABILITY_MATRIX_PATH);
  const currentText = (await matrixFile.exists()) ? await matrixFile.text() : "";

  if (currentText.length === 0) {
    throw new Error(
      `Capability matrix drift detected in ${resolveAgentiflowCapabilityMatrixRelativePath()}. Run bun run capability:matrix.`,
    );
  }

  const currentValue: unknown = JSON.parse(currentText);
  const normalizedCurrentText = await formatJsonWithBiome(
    AGENTIFLOW_CAPABILITY_MATRIX_PATH,
    normalizeMatrixForComparison(currentValue),
  );

  if (normalizedCurrentText !== expectedText) {
    throw new Error(
      `Capability matrix drift detected in ${resolveAgentiflowCapabilityMatrixRelativePath()}. Run bun run capability:matrix.`,
    );
  }

  await writeOutput(
    `agentiflow capability matrix is current: ${resolveAgentiflowCapabilityMatrixRelativePath()}`,
  );
};

const result = await captureResult(main);
if (!result.ok) {
  await writeError(
    toErrorMessage(result.error, "Failed to validate the agentiflow capability matrix."),
  );
  process.exit(1);
}

import {
  FORBIDDEN_FEATURE_TREE_PREFIXES,
  isForbiddenConsumerExemptionPath,
} from "./ui-control-primitive-owners";
import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

/**
 * Meta-gate: UI validators must not carry consumer path allowlists or
 * feature-tree startsWith waivers. Authority + control-primitive owners only.
 */

const VALIDATOR_FILE_PATTERN =
  /^scripts\/(?:validate-ui-[\w-]+\.ts|validate-no-raw-design-tokens\.ts)$/u;

const PATH_LITERAL_PATTERN =
  /["'](packages\/client\/(?:pages|components|layouts|composables)\/[^"']+)["']/gu;

const STARTS_WITH_FEATURE_PATTERN =
  /\.startsWith\(\s*["'](packages\/client\/(?:pages|components)\/[^"']+)["']\s*\)/gu;

const ALLOWLIST_SET_NAME_PATTERN =
  /(?:SSOT_ALLOWLIST_PATHS|ALLOWLIST_PATHS|EXEMPT_PATHS)\s*=\s*new\s+Set/u;

const collectStartsWithViolations = (filePath: string, content: string): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  STARTS_WITH_FEATURE_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(STARTS_WITH_FEATURE_PATTERN)) {
    const prefix = match[1] ?? "";
    const isForbiddenPrefix = FORBIDDEN_FEATURE_TREE_PREFIXES.some(
      (forbidden) => prefix === forbidden || prefix.startsWith(forbidden),
    );
    const isUiOrIcons =
      prefix.startsWith("packages/client/components/ui/") ||
      prefix.startsWith("packages/client/components/icons/");
    if (isForbiddenPrefix || (!isUiOrIcons && prefix.startsWith("packages/client/components/"))) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Forbidden feature-tree startsWith waiver "${prefix}". Use isUiSsotAuthority / isControlPrimitiveOwner only — zero consumer exemptions.`,
      });
    }
    if (prefix.startsWith("packages/client/pages/")) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        message: `Forbidden pages/ startsWith waiver "${prefix}". Pages are never SSOT-exempt.`,
      });
    }
  }
  return violations;
};

const collectAllowlistSetViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (!ALLOWLIST_SET_NAME_PATTERN.test(content)) {
    return [];
  }
  const violations: ValidationViolation[] = [];
  PATH_LITERAL_PATTERN.lastIndex = 0;
  for (const match of content.matchAll(PATH_LITERAL_PATTERN)) {
    const pathLiteral = match[1] ?? "";
    if (isUiSsotAuthority(pathLiteral)) continue;
    if (!isForbiddenConsumerExemptionPath(pathLiteral)) continue;
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Consumer path "${pathLiteral}" in an allowlist Set. Delete the exemption; fix the consumer source (ui-ux). Only AUTHORITY_PATHS + CONTROL_PRIMITIVE_OWNERS may be exempt.`,
    });
  }
  return violations;
};

export const collectSsotAuthorityMetaViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (!VALIDATOR_FILE_PATTERN.test(filePath)) return [];
  if (
    filePath === "scripts/validate-ui-ssot-authority.ts" ||
    filePath === "scripts/ui-ssot-authority.ts" ||
    filePath === "scripts/ui-control-primitive-owners.ts"
  ) {
    return [];
  }
  if (filePath.endsWith(".test.ts")) return [];

  return [
    ...collectStartsWithViolations(filePath, content),
    ...collectAllowlistSetViolations(filePath, content),
  ];
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const glob = new Bun.Glob("scripts/validate-*.ts");
  const files: string[] = [];
  for await (const relative of glob.scan({ cwd: process.cwd(), onlyFiles: true })) {
    const normalized = relative.replace(/\\/gu, "/");
    if (VALIDATOR_FILE_PATTERN.test(normalized) && !normalized.endsWith(".test.ts")) {
      files.push(normalized);
    }
  }

  const violationGroups = await Promise.all(
    files.map(async (filePath) =>
      collectSsotAuthorityMetaViolationsForContent(filePath, await Bun.file(filePath).text()),
    ),
  );
  return violationGroups.flat();
};

if (import.meta.main) {
  await reportViolations(
    "UI SSOT authority meta-gate failed:",
    await collectViolations(),
    "UI SSOT authority meta-gate passed.",
  );
}

