import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";
const NUM_120 = 120;

const schemaPattern = /\b(?:Type|z)\.(?:Object|object)\(\{[\s\S]*?\}\)/gu;

const normalizeSchema = (value: string): string =>
  value.replace(/\s+/gu, " ").replace(/['"`]/gu, '"').trim();

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots: ["packages/server/src", "packages/shared/src"],
    allowedExtensions: new Set([".ts"]),
  });

  const seenSchemas = new Map<string, { filePath: string; line: number }>();
  const violations: ValidationViolation[] = [];

  for (const { filePath, content } of files) {
    schemaPattern.lastIndex = 0;
    for (const match of content.matchAll(schemaPattern)) {
      const rawValue = match[0] ?? "";
      if (rawValue.length < NUM_120) {
        continue;
      }
      const normalizedSchema = normalizeSchema(rawValue);
      const line = getLineFromOffset(content, match.index ?? 0);
      const previous = seenSchemas.get(normalizedSchema);
      if (previous) {
        violations.push({
          filePath,
          line,
          message: `Schema block duplicates ${previous.filePath}:${previous.line}. Extract the shared schema instead of copying it.`,
        });
        continue;
      }
      seenSchemas.set(normalizedSchema, { filePath, line });
    }
  }

  return violations;
};

if (import.meta.main) {
  await reportViolations(
    "Schema duplication validation failed:",
    await collectViolations(),
    "Schema duplication validation passed.",
  );
}

/**
 * Bun installs `@typescript/native` as an alias of `typescript@7`, which makes
 * nested `require("typescript")` from typescript-eslint resolve to TS 7 (no
 * programmatic API → `ts.Extension.Cjs` crash). Pin eslint/ts-api-utils peers
 * to the TS 6.0.3 package that carries the API typescript-eslint needs.
 *
 * Idempotent. Invoked from root `postinstall` after `bun install`.
 */
import { existsSync, mkdirSync, readdirSync, rmSync, symlinkSync } from "node:fs";
import { join } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

const ROOT = process.cwd();
const BUN_STORE = join(ROOT, "node_modules", ".bun");
const TS6_RELATIVE = "../../typescript@6.0.3/node_modules/typescript";
const TS6_ABSOLUTE = join(BUN_STORE, "typescript@6.0.3", "node_modules", "typescript");

const PACKAGE_PREFIXES = [
  "@typescript-eslint+typescript-estree@",
  "@typescript-eslint+parser@",
  "@typescript-eslint+eslint-plugin@",
  "@typescript-eslint+type-utils@",
  "@typescript-eslint+project-service@",
  "@typescript-eslint+utils@",
  "typescript-eslint@",
  "ts-api-utils@",
  "eslint-plugin-vue@",
  "vue-eslint-parser@",
] as const;

const linkTypescript6 = (packageDir: string): void => {
  const nodeModulesDir = join(packageDir, "node_modules");
  const linkPath = join(nodeModulesDir, "typescript");
  mkdirSync(nodeModulesDir, { recursive: true });
  rmSync(linkPath, { force: true });
  symlinkSync(TS6_RELATIVE, linkPath);
};

if (!existsSync(TS6_ABSOLUTE)) {
  await writeError("typescript@6.0.3 not found in bun store; skip eslint TS6 peer link.");
  process.exit(0);
}

if (!existsSync(BUN_STORE)) {
  await writeError("bun store missing; skip eslint TS6 peer link.");
  process.exit(0);
}

let linked = 0;
for (const entry of readdirSync(BUN_STORE)) {
  if (!PACKAGE_PREFIXES.some((prefix) => entry.startsWith(prefix))) continue;
  const packageDir = join(BUN_STORE, entry);
  if (!existsSync(packageDir)) continue;
  linkTypescript6(packageDir);
  linked += 1;
}

// Workspace package node_modules may also host eslint-plugin-vue / parsers.
const workspacePackageDirs = [
  "packages/client",
  "packages/server",
  "packages/shared",
  "packages/scraper",
];
for (const workspacePackage of workspacePackageDirs) {
  for (const nestedName of [
    "eslint-plugin-vue",
    "vue-eslint-parser",
    "typescript-eslint",
    "ts-api-utils",
  ]) {
    const packageDir = join(ROOT, workspacePackage, "node_modules", nestedName);
    if (!existsSync(packageDir)) continue;
    // Workspace packages resolve typescript via the root bun store; use an absolute-relative link.
    const nodeModulesDir = join(packageDir, "node_modules");
    const linkPath = join(nodeModulesDir, "typescript");
    mkdirSync(nodeModulesDir, { recursive: true });
    rmSync(linkPath, { force: true });
    symlinkSync(TS6_ABSOLUTE, linkPath);
    linked += 1;
  }
}

await writeOutput(`Linked typescript@6.0.3 into ${String(linked)} eslint peer package(s).`);

import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import { getLineFromOffset, shouldIgnorePath } from "./utils/validation-helpers";

type ViolationCategory = "route" | "api";

type Violation = {
  filePath: string;
  line: number;
  literal: string;
  category: ViolationCategory;
};

const projectRoot = process.cwd();
const clientRoot = "packages/client";
const allowedExtensions = new Set([".ts", ".tsx", ".vue", ".js", ".mjs", ".cjs"]);
const appRouteLiterals = Object.values(APP_ROUTES).filter((route) => route !== "/");
const hardcodedApiLiteralPattern = /(["'])\/api(?:\/[^"']+)?\1/gu;

const hasAllowedExtension = (pathValue: string): boolean => {
  const normalized = pathValue.toLowerCase();
  for (const extension of allowedExtensions) {
    if (normalized.endsWith(extension)) {
      return true;
    }
  }
  return false;
};

import { escapeRegExp } from "../packages/shared/src/utils/string";

const collectClientFiles = async (): Promise<string[]> => {
  const files: string[] = [];
  const glob = new Bun.Glob(`${clientRoot}/**/*`);
  for await (const relativeFilePath of glob.scan({ cwd: projectRoot, onlyFiles: true })) {
    const normalizedPath = relativeFilePath.replace(/\\/gu, "/");
    if (!hasAllowedExtension(normalizedPath) || shouldIgnorePath(normalizedPath)) {
      continue;
    }
    files.push(normalizedPath);
  }
  return files;
};

const collectRouteViolations = (filePath: string, content: string): Violation[] => {
  const violations: Violation[] = [];
  for (const routeLiteral of appRouteLiterals) {
    const routePattern = new RegExp(`(["'])${escapeRegExp(routeLiteral)}\\1`, "gu");
    for (const match of content.matchAll(routePattern)) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, match.index ?? 0),
        literal: routeLiteral,
        category: "route",
      });
    }
  }
  return violations;
};

const collectApiViolations = (filePath: string, content: string): Violation[] => {
  const violations: Violation[] = [];
  hardcodedApiLiteralPattern.lastIndex = 0;
  for (const match of content.matchAll(hardcodedApiLiteralPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      literal: match[0],
      category: "api",
    });
  }
  return violations;
};

export const collectHardcodedPathViolationsForContent = (
  filePath: string,
  content: string,
): Violation[] => [
  ...collectRouteViolations(filePath, content),
  ...collectApiViolations(filePath, content),
];

const collectViolations = async (): Promise<Violation[]> => {
  const files = await collectClientFiles();
  const violationGroups = await Promise.all(
    files.map(async (filePath) => {
      const fileContent = await Bun.file(filePath).text();
      return collectHardcodedPathViolationsForContent(filePath, fileContent);
    }),
  );
  return violationGroups.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();
  if (violations.length === 0) {
    process.stdout.write(
      "Hardcoded path validation passed: client routes and API endpoints use shared constants.\n",
    );
    return;
  }

  process.stderr.write("Hardcoded path validation failed:\n");
  const lines = violations.map((violation) => {
    const reason =
      violation.category === "route"
        ? "Use APP_ROUTES/APP_ROUTE_BUILDERS instead of a route literal."
        : "Use API_ENDPOINTS/builders instead of a hardcoded /api path literal.";
    return `- ${violation.filePath}:${violation.line} ${violation.literal} ${reason}`;
  });
  process.stderr.write(`${lines.join("\n")}\n`);
  process.exit(1);
};

if (import.meta.main) {
  await main();
}

