const NUM_240 = 240;
const NUM_400 = 400;
/**
 * Headed visual proof recorder (no curl, no headless).
 * Tours primary routes at mobile → tablet → desktop and writes WebM + stills.
 */
import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import { type ConsoleMessage, chromium } from "playwright";
import { APP_ROUTES } from "../packages/shared/src/constants/routes";
import {
  finalizeVisualProof,
  mapSequential,
  tourRoute,
  waitForPageReady,
} from "./browser-record-visual-proof-helpers";

const CLIENT_BASE = (process.env.PAGE_PROOF_CLIENT_BASE ?? "http://localhost:3001").replace(
  /\/$/u,
  "",
);
const OUT_DIR =
  process.env.BROWSER_PROOF_OUT ?? join("/opt/cursor/artifacts/baseline/browser-video-proof");

const ROUTES: readonly { readonly slug: string; readonly path: string }[] = [
  { slug: "dashboard", path: APP_ROUTES.dashboard },
  { slug: "jobs", path: APP_ROUTES.jobs },
  { slug: "resume", path: APP_ROUTES.resume },
  { slug: "interview", path: APP_ROUTES.interview },
  { slug: "skills", path: APP_ROUTES.skills },
  { slug: "studios", path: APP_ROUTES.studios },
  { slug: "ai-dashboard", path: APP_ROUTES.aiDashboard },
  { slug: "ai-chat", path: APP_ROUTES.aiChat },
  { slug: "automation", path: APP_ROUTES.automation },
  { slug: "settings", path: APP_ROUTES.settings },
  { slug: "setup", path: APP_ROUTES.setup },
];

const VIEWPORTS = [
  { name: "mobile", width: 390, height: 844 },
  { name: "tablet", width: 768, height: 1024 },
  { name: "desktop", width: 1440, height: 900 },
] as const;

const main = async (): Promise<void> => {
  await mkdir(OUT_DIR, { recursive: true });
  const stillsDir = join(OUT_DIR, "stills");
  await mkdir(stillsDir, { recursive: true });
  await mkdir(join(OUT_DIR, "raw-segments"), { recursive: true });

  const consoleErrors: string[] = [];
  const browser = await chromium.launch({
    headless: false,
    args: ["--disable-dev-shm-usage"],
  });
  const context = await browser.newContext({
    recordVideo: {
      dir: join(OUT_DIR, "raw-segments"),
      size: { width: 1440, height: 900 },
    },
    viewport: { width: 1440, height: 900 },
  });
  const page = await context.newPage();
  page.on("console", (message: ConsoleMessage) => {
    if (message.type() === "error") {
      consoleErrors.push(`[${new Date().toISOString()}] ${message.text().slice(0, NUM_240)}`);
    }
  });
  page.on("pageerror", (error: Error) => {
    consoleErrors.push(`[pageerror] ${error.message.slice(0, NUM_240)}`);
  });

  await mapSequential(VIEWPORTS, async (viewport) => {
    await page.setViewportSize({ width: viewport.width, height: viewport.height });
    await waitForPageReady(page, NUM_400);
    await mapSequential(ROUTES, async (route) => {
      await tourRoute(page, stillsDir, consoleErrors, CLIENT_BASE, viewport, route);
    });
  });

  const video = page.video();
  await context.close();
  await browser.close();
  const videoPath = video ? await video.path() : null;
  await finalizeVisualProof({
    outDir: OUT_DIR,
    stillsDir,
    clientBase: CLIENT_BASE,
    videoPath,
    consoleErrors,
    viewports: VIEWPORTS,
    routes: ROUTES,
    display: null,
  });
};

await main();

import {
  collectProjectFileEntries,
  countLines,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const sourceExtensions = new Set([".ts", ".tsx", ".vue", ".rs"]);
const scanRoots = [
  "packages/client",
  "packages/server/src",
  "packages/shared/src",
  "packages/scraper/src",
  "packages/desktop/src-tauri/src",
] as const;
const maxVueLines = 350;
const maxTypeScriptLines = 400;
const maxRustLines = 700;
const maxFunctionBodyLines = 80;
const maxParameterCount = 5;
const maxBranchCount = 15;
const maxNestedConditionalDepth = 3;
const isIgnoredFile = (filePath: string): boolean =>
  filePath.endsWith(".test.ts") ||
  (filePath.includes("/locales/") && filePath.endsWith("/catalog.ts")) ||
  filePath.includes("/dist-types/") ||
  filePath.includes("/db/seed/") ||
  filePath.endsWith("/studios.generated.ts");

const resolveMaxLineCount = (filePath: string): number => {
  if (filePath.endsWith(".vue")) {
    return maxVueLines;
  }
  if (filePath.endsWith(".rs")) {
    return maxRustLines;
  }
  return maxTypeScriptLines;
};

const functionPattern =
  /(?:^|\n)(?:export\s+)?(?:async\s+)?function\s+[A-Za-z0-9_]+\s*\(([^)]*)\)\s*(?::[^{=\n]+)?\{/gu;
const methodPattern =
  /(?:^|\n)\s*(?:private|protected|public)?\s*(?:static\s+)?(?:async\s+)?(?!(?:for|while|if|switch|catch|do|return|class|interface|type|enum|namespace)\b)[A-Za-z0-9_]+\s*\(([^)]*)\)\s*(?::[^{=\n]+)?\{/gu;
const arrowPattern =
  /(?:^|\n)(?:const|let|var)\s+[A-Za-z0-9_]+\s*=\s*(?:async\s*)?\(([^)]*)\)\s*(?::[^{=\n]+)?=>\s*\{/gu;

const countParameterList = (parameterList: string): number => {
  const trimmed = parameterList.trim();
  if (trimmed.length === 0) {
    return 0;
  }
  if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
    return 1;
  }
  return trimmed
    .split(",")
    .map((value) => value.trim())
    .filter((value) => value.length > 0).length;
};

const findBlockEndOffset = (content: string, openBraceOffset: number): number => {
  let depth = 0;
  for (let index = openBraceOffset; index < content.length; index += 1) {
    const char = content[index];
    if (char === "{") {
      depth += 1;
    } else if (char === "}") {
      depth -= 1;
      if (depth === 0) {
        return index;
      }
    }
  }
  return content.length - 1;
};

const stripStringsAndComments = (value: string): string =>
  value
    .replace(/\/\*[\s\S]*?\*\//gu, " ")
    .replace(/\/\/.*$/gmu, " ")
    .replace(/"(?:\\.|[^"\\])*"/gu, '""')
    .replace(/'(?:\\.|[^'\\])*'/gu, "''")
    .replace(/`(?:\\.|[^`\\])*`/gu, "``");

const collectBranchStats = (
  block: string,
): { branchCount: number; nestedConditionalDepth: number } => {
  const sanitized = stripStringsAndComments(block);
  const branchMatches = sanitized.match(/\b(?:if|else\s+if|switch|case|for|while)\b/gu) ?? [];

  let nestedConditionalDepth = 0;
  let currentDepth = 0;
  const conditionalPattern = /\b(?:if|switch)\b|\{/gu;
  for (const match of sanitized.matchAll(conditionalPattern)) {
    const token = match[0] ?? "";
    if (token === "{") {
      continue;
    }
    currentDepth += 1;
    nestedConditionalDepth = Math.max(nestedConditionalDepth, currentDepth);
    const startOffset = match.index ?? 0;
    const braceOffset = sanitized.indexOf("{", startOffset);
    if (braceOffset === -1) {
      continue;
    }
    const endOffset = findBlockEndOffset(sanitized, braceOffset);
    currentDepth -= 1;
    conditionalPattern.lastIndex = Math.max(conditionalPattern.lastIndex, endOffset);
  }

  return {
    branchCount: branchMatches.length,
    nestedConditionalDepth,
  };
};

const collectFunctionViolations = (
  filePath: string,
  content: string,
  pattern: RegExp,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];

  pattern.lastIndex = 0;
  for (const match of content.matchAll(pattern)) {
    const matchIndex = match.index ?? 0;
    const openBraceOffset = content.indexOf("{", matchIndex);
    if (openBraceOffset === -1) {
      continue;
    }
    const closeBraceOffset = findBlockEndOffset(content, openBraceOffset);
    const bodyLineCount = countLines(content.slice(openBraceOffset, closeBraceOffset + 1));
    const parameterCount = countParameterList(match[1] ?? "");
    const block = content.slice(openBraceOffset, closeBraceOffset + 1);
    const branchStats = collectBranchStats(block);

    if (bodyLineCount > maxFunctionBodyLines) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, matchIndex),
        message: `Function body exceeds ${maxFunctionBodyLines} lines. Break the monolith into focused helpers.`,
      });
    }

    if (parameterCount > maxParameterCount) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, matchIndex),
        message: `Function signature exposes ${parameterCount} parameters. Use an options object or split responsibilities.`,
      });
    }

    if (branchStats.branchCount > maxBranchCount) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, matchIndex),
        message: `Function branch count ${branchStats.branchCount} exceeds ${maxBranchCount}. Break the control flow into smaller units.`,
      });
    }

    if (branchStats.nestedConditionalDepth > maxNestedConditionalDepth) {
      violations.push({
        filePath,
        line: getLineFromOffset(content, matchIndex),
        message: `Nested conditional depth ${branchStats.nestedConditionalDepth} exceeds ${maxNestedConditionalDepth}. Flatten the logic and extract helpers.`,
      });
    }
  }

  return violations;
};

export const collectMonolithViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isIgnoredFile(filePath)) {
    return [];
  }

  const violations: ValidationViolation[] = [];
  const maxLines = resolveMaxLineCount(filePath);
  const lineCount = countLines(content);

  if (lineCount > maxLines) {
    violations.push({
      filePath,
      line: 1,
      message: `File exceeds ${maxLines} lines. Split the monolith into smaller modules.`,
    });
  }

  if (filePath.endsWith(".rs")) {
    return violations;
  }

  return [
    ...violations,
    ...collectFunctionViolations(filePath, content, functionPattern),
    ...collectFunctionViolations(filePath, content, methodPattern),
    ...collectFunctionViolations(filePath, content, arrowPattern),
  ];
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });

  return files.flatMap(({ filePath, content }) =>
    collectMonolithViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Monolith validation failed:",
    await collectViolations(),
    "Monolith validation passed.",
  );
}

import { writeError, writeOutput } from "./utils/cli-output";
import { shouldIgnorePath } from "./utils/validation-helpers";

type Violation = {
  filePath: string;
  line: number;
  message: string;
};

type SeoBlock = {
  body: string;
  offset: number;
};

const projectRoot = process.cwd();
const clientPagesRoot = "packages/client/pages";

const seoComposableCallPattern = /\buseSeoMeta\s*\(/u;
const seoComposableClosePattern = /\}\s*\)\s*;/u;
const serverSeoComposableCallPattern = /\buseServerSeoMeta\s*\(/u;
const humanTextPattern = /\p{L}/u;

const getLineFromOffset = (text: string, offset: number): number => {
  if (offset <= 0) {
    return 1;
  }

  let line = 1;
  for (let index = 0; index < offset; index += 1) {
    if (text.charCodeAt(index) === 10) {
      line += 1;
    }
  }
  return line;
};

const findSeoBlock = (fileContent: string): SeoBlock | null => {
  const seoComposableMatch = seoComposableCallPattern.exec(fileContent);
  if (!seoComposableMatch || seoComposableMatch.index === undefined) {
    return null;
  }
  const seoComposableOffset = seoComposableMatch.index;

  const openParenthesisOffset = fileContent.indexOf("(", seoComposableOffset);
  if (openParenthesisOffset === -1) {
    return null;
  }

  const openBraceOffset = fileContent.indexOf("{", openParenthesisOffset + 1);
  if (openBraceOffset === -1) {
    return null;
  }

  const remaining = fileContent.slice(openBraceOffset + 1);
  const closeMatch = seoComposableClosePattern.exec(remaining);
  if (!closeMatch || closeMatch.index === undefined) {
    return null;
  }

  const closeOffset = openBraceOffset + 1 + closeMatch.index;
  return {
    body: fileContent.slice(openBraceOffset + 1, closeOffset),
    offset: openBraceOffset + 1,
  };
};

const usesServerOnlySeoComposable = (fileContent: string): boolean =>
  serverSeoComposableCallPattern.test(fileContent);

const resolveSeoPropertyValue = (
  seoBody: string,
  propertyName: "title" | "description",
): string | null => {
  const propertyPattern = new RegExp(
    `\\b${propertyName}\\s*:\\s*([\\s\\S]*?)(?=,\\s*(?:\\n|$)|\\n\\s*[A-Za-z_$][\\w$]*\\s*:|$)`,
    "u",
  );
  const match = propertyPattern.exec(seoBody);
  if (!match) {
    return null;
  }

  return (match[1] ?? "").trim();
};

const isStaticLiteralSeoValue = (value: string): boolean => {
  if (value.length < 2) {
    return false;
  }

  const startsWithSingleQuote = value.startsWith("'");
  const endsWithSingleQuote = value.endsWith("'");
  const startsWithDoubleQuote = value.startsWith('"');
  const endsWithDoubleQuote = value.endsWith('"');
  const startsWithBacktick = value.startsWith("`");
  const endsWithBacktick = value.endsWith("`");

  if (
    (startsWithSingleQuote && endsWithSingleQuote) ||
    (startsWithDoubleQuote && endsWithDoubleQuote)
  ) {
    const literal = value.slice(1, -1).trim();
    return literal.length > 0 && humanTextPattern.test(literal);
  }

  if (startsWithBacktick && endsWithBacktick && !value.includes("${")) {
    const literal = value.slice(1, -1).trim();
    return literal.length > 0 && humanTextPattern.test(literal);
  }

  return false;
};

export const collectPageSeoViolationsForContent = (
  filePath: string,
  fileContent: string,
): Violation[] => {
  if (usesServerOnlySeoComposable(fileContent)) {
    return [
      {
        filePath,
        line: 1,
        message:
          "Page uses useServerSeoMeta(). Use useSeoMeta() so SSR metadata stays aligned after browser hydration.",
      },
    ];
  }

  const seoBlock = findSeoBlock(fileContent);

  if (!seoBlock) {
    return [
      {
        filePath,
        line: 1,
        message:
          "Missing useSeoMeta call. Core pages must define SSR and hydrated title/description metadata.",
      },
    ];
  }

  const violations: Violation[] = [];
  for (const propertyName of ["title", "description"] as const) {
    const value = resolveSeoPropertyValue(seoBlock.body, propertyName);
    if (!value) {
      violations.push({
        filePath,
        line: getLineFromOffset(fileContent, seoBlock.offset),
        message: `Missing "${propertyName}" in useSeoMeta payload.`,
      });
      continue;
    }

    if (isStaticLiteralSeoValue(value)) {
      violations.push({
        filePath,
        line: getLineFromOffset(fileContent, seoBlock.offset),
        message:
          `Static literal "${propertyName}" metadata detected. ` +
          `Use localized values (for example t('...')) or shared constants.`,
      });
    }
  }

  return violations;
};

const collectFileViolations = async (filePath: string): Promise<Violation[]> => {
  const fileContent = await Bun.file(filePath).text();
  return collectPageSeoViolationsForContent(filePath, fileContent);
};

const collectViolations = async (): Promise<Violation[]> => {
  const glob = new Bun.Glob(`${clientPagesRoot}/**/*.vue`);
  const scannedPaths = await Array.fromAsync(glob.scan({ cwd: projectRoot, onlyFiles: true }));
  const pagePaths = scannedPaths
    .map((pathValue) => pathValue.replace(/\\/gu, "/"))
    .filter((pathValue) => !shouldIgnorePath(pathValue));

  const perFileViolations = await Promise.all(
    pagePaths.map((pathValue) => collectFileViolations(pathValue)),
  );
  return perFileViolations.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();
  if (violations.length === 0) {
    await writeOutput("Page SEO metadata validation passed for all client pages.");
    return;
  }

  await writeError("Page SEO metadata validation failed:");
  const lines = violations.map(
    (violation) => `- ${violation.filePath}:${violation.line} ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }
  process.exit(1);
};

if (import.meta.main) {
  await main();
}

import { rm, stat } from "node:fs/promises";
import { join, resolve } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

type MountedDesktopImage = {
  readonly imagePath: string;
  readonly mountPaths: readonly string[];
};

const REPO_ROOT = resolve(import.meta.dir, "..");
const DESKTOP_TAURI_ROOT = join(REPO_ROOT, "packages", "desktop", "src-tauri");
const DESKTOP_TEMP_DMG_GLOB = new Bun.Glob("target/**/bundle/**/rw.*.dmg");
const DESKTOP_MOUNTED_IMAGE_PATTERN = /\/bundle\/(?:dmg|macos)\/rw\..+\.dmg$/;
const MOUNT_LINE_SPLIT_PATTERN = /\t+/;

const runCommand = async (
  command: readonly string[],
  cwd: string = REPO_ROOT,
  env: Record<string, string | undefined> = process.env,
): Promise<number> => {
  const proc = Bun.spawn(command as string[], {
    cwd,
    env,
    stdout: "inherit",
    stderr: "inherit",
  });

  return proc.exited;
};

const readCommand = async (command: readonly string[]): Promise<string> => {
  const proc = Bun.spawn(command as string[], {
    cwd: REPO_ROOT,
    env: process.env,
    stdout: "pipe",
    stderr: "inherit",
  });
  const exitCode = await proc.exited;
  if (exitCode !== 0 || !(proc.stdout instanceof ReadableStream)) {
    await writeError(`${command.join(" ")} failed with exit code ${exitCode}.`);
    process.exit(exitCode || 1);
  }

  return new Response(proc.stdout).text();
};

const pathExists = async (candidatePath: string): Promise<boolean> =>
  stat(candidatePath).then(
    () => true,
    () => false,
  );

const parseMountedDesktopImages = (infoText: string): readonly MountedDesktopImage[] =>
  infoText.split("================================================").flatMap((sectionText) => {
    const lines = sectionText
      .split("\n")
      .map((line) => line.trim())
      .filter((line) => line.length > 0);
    const imagePathLine = lines.find((line) => line.startsWith("image-path"));
    if (!imagePathLine) {
      return [];
    }

    const imagePath = imagePathLine.split(":").slice(1).join(":").trim();
    if (
      !(imagePath.startsWith(DESKTOP_TAURI_ROOT) && DESKTOP_MOUNTED_IMAGE_PATTERN.test(imagePath))
    ) {
      return [];
    }

    const mountPaths = lines.flatMap((line) => {
      const parts = line.split(MOUNT_LINE_SPLIT_PATTERN);
      return parts.filter((part) => part.startsWith("/Volumes/"));
    });

    return [{ imagePath, mountPaths }];
  });

const collectTemporaryDiskImages = async (): Promise<readonly string[]> => {
  const imagePaths: string[] = [];
  for await (const relativePath of DESKTOP_TEMP_DMG_GLOB.scan({
    cwd: DESKTOP_TAURI_ROOT,
  })) {
    imagePaths.push(join(DESKTOP_TAURI_ROOT, relativePath));
  }

  return imagePaths;
};

const detachMountPathsSequentially = async (
  mountPaths: readonly string[],
  index: number = 0,
): Promise<void> => {
  const mountPath = mountPaths[index];
  if (!mountPath) {
    return;
  }

  await writeOutput(`Detaching stale desktop image mount ${mountPath}`);
  const exitCode = await runCommand(["hdiutil", "detach", mountPath]);
  if (exitCode !== 0) {
    await writeError(`Failed to detach stale desktop image mount ${mountPath}.`);
    process.exit(exitCode);
  }

  await detachMountPathsSequentially(mountPaths, index + 1);
};

const detachMountedImages = async (
  mountedImages: readonly MountedDesktopImage[],
): Promise<void> => {
  const mountPaths = mountedImages.flatMap((mountedImage) => mountedImage.mountPaths);
  await detachMountPathsSequentially(mountPaths);
};

const removeTemporaryDiskImages = async (imagePaths: readonly string[]): Promise<void> => {
  await Promise.all(
    imagePaths.map(async (imagePath) => {
      if (!(await pathExists(imagePath))) {
        return;
      }

      await rm(imagePath, { force: true });
      await writeOutput(`Removed stale desktop disk image ${imagePath}`);
    }),
  );
};

const runPrebuildCleanup = async (): Promise<void> => {
  if (process.platform !== "darwin") {
    await writeOutput("Skipping desktop disk image cleanup outside macOS.");
    return;
  }

  const mountedImages = parseMountedDesktopImages(await readCommand(["hdiutil", "info"]));
  await detachMountedImages(mountedImages);
  await removeTemporaryDiskImages(await collectTemporaryDiskImages());
};

const command = process.argv[2];
if (command !== "prebuild") {
  await writeError("Usage: bun scripts/cleanup-desktop-build.ts prebuild");
  process.exit(1);
}

await runPrebuildCleanup();

