#!/usr/bin/env bun
/**
 * Build complete brutalise scan payload with all source files.
 * Outputs JSON to stdout for MCP call.
 */

import { collectBrutaliseScanFiles } from "./brutalise-scan-files";

const root = process.cwd();
const allFiles = await collectBrutaliseScanFiles(root);

const payload = { targetDir: root, files: allFiles };
process.stdout.write(JSON.stringify(payload));

import { isControlPrimitiveOwner } from "./ui-control-primitive-owners";
import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";
const NUM_4 = 4;
const NUM_52 = 52;

/**
 * Responsive overflow + fluidity gate (design.md §11, §8).
 *
 * Components must not run off-screen or overshoot boundaries. This gate
 * catches the most common overflow risks:
 *   1. Fixed width utilities (`w-64`, `w-96`) without a `min-w-0` or
 *      `max-w-*` guard inside a flex/grid parent that needs to shrink.
 *   2. `overflow-x-auto` / `overflow-scroll` without an explicit
 *      `min-w-0` child — the canonical Bao pattern for truncation.
 *   3. Fixed height utilities on content blocks (`h-64`, `h-96`) that
 *      clip content on short viewports; prefer `min-h-*`.
 *   4. Grids with a fixed column count that don't collapse (`grid-cols-4`
 *      without responsive `sm:`/`md:` guards is a mobile-cramp risk).
 *
 * Allowed SSOT forms: constants/layout.ts, constants/ui-layout.ts, main.css.
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts", ".css"]);

const isSsotSourceFile = (filePath: string): boolean =>
  isUiSsotAuthority(filePath) || isControlPrimitiveOwner(filePath);

// Fixed width like w-64, w-96, w-[320px] (but not w-full, w-auto, w-fit, w-screen).
// Use a negative lookbehind for `-` so we don't match `min-w-64` / `max-w-64`.
const fixedWidthPattern = /(?<![-\w])w-(?:\d{2,4}|\[[^\]]+\])(?!\s*\/)/gu;
// Fixed height like h-64, h-96 (but not h-full, h-auto, h-fit, h-screen).
// Use a negative lookbehind for `-` so we don't match `min-h-64` / `max-h-64`.
const fixedHeightPattern = /(?<![-\w])h-(?:\d{2,4}|\[[^\]]+\])(?!\s*\/)/gu;
// Grid with fixed columns and no responsive guard on the same class string.
const fixedGridColsPattern = /\bgrid-cols-(?:[2-9]|1\d)(?![\d-])/gu;

// Threshold below which w-/h- literals are icon/avatar primitives, not overflow risks.
const SMALL_SIZE_THRESHOLD = 17; // w-16 / h-16 and below are primitives.

// Hoisted: class-attribute extraction (captures the inner class string in group 1).
const CLASS_ATTR_PATTERN = /\bclass\s*=\s*["']([^"']+)["']/gu;
// Hoisted: digit extraction from a w-/h- literal like `w-64` or `w-[320px]`.
const DIGITS_ONLY_PATTERN = /\D/gu;
// Hoisted: min-w-0 OR max-w-* guard detection.
const WIDTH_GUARD_PATTERN = /\bmin-w-0\b|\bmax-w-/u;
// Hoisted: max-w-* (any width cap) detection — used as a separate isFluidCap signal.
const MAX_W_CAP_PATTERN = /\bmax-w-/u;
// Hoisted: vertical overflow guard detection (hidden / y-auto / y-scroll / auto).
const VERTICAL_OVERFLOW_GUARD_PATTERN = /\boverflow-(?:hidden|y-auto|y-scroll|auto)\b/u;
// Hoisted: skeleton-row class detection.
const SKELETON_CLASS_PATTERN = /\bskeleton\b/u;
// Hoisted: arbitrary w-N class detection (sibling w- matching aspect-ratio primitives).
const W_ARBITRARY_PATTERN = /\bw-\d+\b/u;
// Hoisted: responsive sm:/md:/lg:/xl: grid-cols- guard detection.
const RESPONSIVE_GRID_COLS_PATTERN = /\b(?:sm|md|lg|xl):grid-cols-/u;

const extractTemplateBlocks = (content: string): string => {
  const templateStart = content.indexOf("<template>");
  if (templateStart < 0) return "";
  const templateEnd = content.lastIndexOf("</template>");
  if (templateEnd <= templateStart) return content.slice(templateStart);
  return content.slice(templateStart, templateEnd + "</template>".length);
};

const collectFixedWidthHits = (
  filePath: string,
  classValue: string,
  baseLine: number,
): ValidationViolation[] => {
  fixedWidthPattern.lastIndex = 0;
  const fixedWidthMatch = classValue.match(fixedWidthPattern);
  if (!fixedWidthMatch) return [];
  const widthValue = Number.parseInt(fixedWidthMatch[0].replace(DIGITS_ONLY_PATTERN, ""), 10);
  const isSmallPrimitive = Number.isFinite(widthValue) && widthValue <= NUM_52;
  const hasGuard = WIDTH_GUARD_PATTERN.test(classValue);
  const isFluidCap = MAX_W_CAP_PATTERN.test(classValue);
  if (isSmallPrimitive || hasGuard || isFluidCap) return [];
  return [
    {
      filePath,
      line: baseLine,
      message: `Fixed width "${fixedWidthMatch[0]}" risks horizontal overflow without min-w-0 or max-w-* guard. Use the SSOT SHELL_MAIN_INNER_CLASS / PAGE_HERO_ASIDE_CLASS pattern or wrap in min-w-0.`,
    },
  ];
};

const collectFixedHeightHits = (
  filePath: string,
  classValue: string,
  baseLine: number,
): ValidationViolation[] => {
  fixedHeightPattern.lastIndex = 0;
  const fixedHeightMatch = classValue.match(fixedHeightPattern);
  if (!fixedHeightMatch) return [];
  const heightValue = Number.parseInt(fixedHeightMatch[0].replace(DIGITS_ONLY_PATTERN, ""), 10);
  const isSmallPrimitive = Number.isFinite(heightValue) && heightValue <= SMALL_SIZE_THRESHOLD;
  const hasOverflowGuard = VERTICAL_OVERFLOW_GUARD_PATTERN.test(classValue);
  const isSkeletonRow = SKELETON_CLASS_PATTERN.test(classValue);
  const isSquarePrimitive =
    heightValue <= SMALL_SIZE_THRESHOLD + NUM_4 && W_ARBITRARY_PATTERN.test(classValue);
  if (isSmallPrimitive || hasOverflowGuard || isSkeletonRow || isSquarePrimitive) return [];
  return [
    {
      filePath,
      line: baseLine,
      message: `Fixed height "${fixedHeightMatch[0]}" clips content on short viewports. Prefer min-h-* or add overflow-y-auto/overflow-hidden for bounded scroll, or use the glass-card container query for adaptive density.`,
    },
  ];
};

const collectFixedGridHits = (
  filePath: string,
  classValue: string,
  baseLine: number,
): ValidationViolation[] => {
  fixedGridColsPattern.lastIndex = 0;
  const fixedGridMatch = classValue.match(fixedGridColsPattern);
  if (!fixedGridMatch || RESPONSIVE_GRID_COLS_PATTERN.test(classValue)) return [];
  return [
    {
      filePath,
      line: baseLine,
      message: `Fixed grid columns "${fixedGridMatch[0]}" without responsive sm:/md: guard cramps mobile. Use grid-cols-1 sm:grid-cols-2 md:grid-cols-N or the SectionGrid primitive.`,
    },
  ];
};

const collectOverflowViolations = (filePath: string, content: string): ValidationViolation[] => {
  if (isSsotSourceFile(filePath)) return [];
  const template = extractTemplateBlocks(content);
  if (template.length === 0) return [];
  const violations: ValidationViolation[] = [];

  CLASS_ATTR_PATTERN.lastIndex = 0;
  for (const classMatch of template.matchAll(CLASS_ATTR_PATTERN)) {
    const classValue = classMatch[1] ?? "";
    const baseLine = getLineFromOffset(content, classMatch.index ?? 0);
    violations.push(
      ...collectFixedWidthHits(filePath, classValue, baseLine),
      ...collectFixedHeightHits(filePath, classValue, baseLine),
      ...collectFixedGridHits(filePath, classValue, baseLine),
    );
  }

  return violations;
};

export const collectResponsiveOverflowViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => collectOverflowViolations(filePath, content);

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectResponsiveOverflowViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "UI responsive overflow validation failed:",
    await collectViolations(),
    "UI responsive overflow validation passed.",
  );
}

import { describe, expect, test } from "bun:test";
import { mkdir, mkdtemp, rm, stat } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  discoverStagedDesktopReleaseTargets,
  hasNativeDesktopReleaseProvenance,
  isDesktopReleaseProvenance,
  isDesktopReleaseTarget,
  parseDesktopReleaseRefreshTargets,
  stageDesktopReleaseProvenanceFixture,
} from "./utils/desktop-release-refresh";

const pathExists = async (absolutePath: string): Promise<boolean> =>
  stat(absolutePath).then(
    () => true,
    () => false,
  );

const withTemporaryDirectory = async <T>(
  prefix: string,
  run: (directoryPath: string) => Promise<T>,
): Promise<T> => {
  const directoryPath = await mkdtemp(join(tmpdir(), prefix));
  return Promise.resolve(run(directoryPath)).finally(() =>
    rm(directoryPath, { force: true, recursive: true }),
  );
};

describe("desktop release refresh target parsing", () => {
  test("returns null when no explicit targets are provided", () => {
    expect(parseDesktopReleaseRefreshTargets([])).toBeNull();
  });

  test("parses explicit canonical targets", () => {
    expect(parseDesktopReleaseRefreshTargets(["--targets", "windows,macos"])).toEqual([
      "windows",
      "macos",
    ]);
  });

  test("rejects unsupported explicit targets", () => {
    expect(() => parseDesktopReleaseRefreshTargets(["--targets", "linux-x86"])).toThrow(
      "No supported desktop targets were supplied via --targets (linux-x86).",
    );
  });

  test("narrows canonical target values", () => {
    expect(isDesktopReleaseTarget("windows")).toBe(true);
    expect(isDesktopReleaseTarget("linux-x86")).toBe(false);
  });
});

describe("discoverStagedDesktopReleaseTargets", () => {
  test("returns targets with a root and assembly-safe provenance manifest", async () => {
    await withTemporaryDirectory("bao-release-refresh-", async (sourceRoot) => {
      await stageDesktopReleaseProvenanceFixture(sourceRoot, "windows");
      await stageDesktopReleaseProvenanceFixture(sourceRoot, "macos", [
        "stage-only existing bundled artifacts for aarch64-apple-darwin",
      ]);
      await mkdir(join(sourceRoot, "linux-x64"), { recursive: true });

      expect(await discoverStagedDesktopReleaseTargets(sourceRoot, pathExists)).toEqual([
        "macos",
        "windows",
      ]);
    });
  });
});

describe("isDesktopReleaseProvenance", () => {
  test("accepts stage-only carry-forward provenance for release assembly", () => {
    expect(
      isDesktopReleaseProvenance({
        schemaVersion: 1,
        target: "windows",
        strategy: "matching-host-native",
        tauriCli: "repo-local-bun",
        hostPlatform: "win32",
        hostArch: "x64",
        tauriTarget: "x86_64-pc-windows-msvc",
        artifactNames: ["BaoBuildBuddy_0.1.0_x64-setup.exe"],
        buildCommands: ["stage-only existing bundled artifacts for x86_64-pc-windows-msvc"],
      }),
    ).toBe(true);
  });
});

describe("hasNativeDesktopReleaseProvenance", () => {
  test("accepts provenance generated from a native build", () => {
    expect(
      hasNativeDesktopReleaseProvenance({
        schemaVersion: 1,
        target: "macos",
        strategy: "matching-host-native",
        tauriCli: "repo-local-bun",
        hostPlatform: "darwin",
        hostArch: "arm64",
        tauriTarget: "aarch64-apple-darwin",
        artifactNames: ["BaoBuildBuddy_0.1.0_aarch64.dmg"],
        buildCommands: ["bun tauri build --no-bundle --target aarch64-apple-darwin"],
      }),
    ).toBe(true);
  });

  test("rejects stage-only carry-forward provenance", () => {
    expect(
      hasNativeDesktopReleaseProvenance({
        schemaVersion: 1,
        target: "windows",
        strategy: "matching-host-native",
        tauriCli: "repo-local-bun",
        hostPlatform: "win32",
        hostArch: "x64",
        tauriTarget: "x86_64-pc-windows-msvc",
        artifactNames: ["BaoBuildBuddy_0.1.0_x64-setup.exe"],
        buildCommands: ["stage-only existing bundled artifacts for x86_64-pc-windows-msvc"],
      }),
    ).toBe(false);
  });
});

const NUM_1000 = 1_000;
const NUM_1200 = 1_200;
const NUM_1500 = 1_500;
const NUM_1800 = 1_800;
const NUM_2000 = 2_000;
const NUM_20000 = 20_000;
const NUM_2500 = 2_500;
const NUM_35000 = 35_000;
const NUM_400 = 400;
const NUM_5 = 5;
const NUM_8 = 8;
/**
 * Honest headed proof for capabilities that can run in this environment:
 * - PDF export via UI download (real pdf-lib bytes)
 * - Job-board scrape via UI (real network + Playwright scrapers)
 * - Browser TTS via speechSynthesis (real synthesis engine)
 *
 * AI chat/completions: Ollama SEGV on this host; cloud keys empty → reported BLOCKED in report.
 * STT: no microphone device → reported BLOCKED in report.
 */
import { mkdir, stat } from "node:fs/promises";
import { join } from "node:path";
import { chromium, type Download, type Page } from "playwright";
import { APP_ROUTE_BUILDERS, APP_ROUTES } from "../packages/shared/src/constants/routes";
import { settle } from "../packages/shared/src/utils/promise";
import { writeError, writeOutput } from "./utils/cli-output";

const CLIENT_BASE = (process.env.PAGE_PROOF_CLIENT_BASE ?? "http://localhost:3001").replace(
  /\/$/u,
  "",
);
const OUT =
  process.env.HONEST_PROOF_OUT ?? join("/opt/cursor/artifacts/baseline/honest-capabilities-proof");

const RE_EXPORT = /Export/i;
const RE_PDF = /PDF/i;
const RE_EDIT = /^Edit$/i;
const RE_SAVE = /Save/i;
const RE_REFRESH_JOBS = /Refresh Jobs/i;
const RE_WWI = /Work With Indies|workwithindies/i;
const RE_SCRAPE_RUN = /Run|Scrape|Start/i;
const RE_NO_JOBS = /No jobs loaded yet/i;
const RE_GREENHOUSE_BOARDS = /Greenhouse boards JSON/i;

const wait = async (page: Page, ms: number): Promise<void> => {
  await page
    .locator("body")
    .waitFor({ state: "visible", timeout: ms })
    .then(
      () => undefined,
      () => undefined,
    );
  await page.waitForLoadState("domcontentloaded", { timeout: ms }).then(
    () => undefined,
    () => undefined,
  );
};

const shot = async (page: Page, name: string): Promise<void> => {
  await page.screenshot({ path: join(OUT, "stills", `${name}.png`), fullPage: false });
};

const saveDownload = async (download: Download, name: string): Promise<string> => {
  const target = join(OUT, "downloads", name);
  await download.saveAs(target);
  return target;
};

const exportResumePdf = async (page: Page): Promise<string | null> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.resume}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, NUM_1800);
  await page.locator("main button.btn-outline", { hasText: RE_EDIT }).first().click();
  await wait(page, NUM_1200);
  await page.getByRole("button", { name: RE_EXPORT }).first().click();
  await wait(page, NUM_400);
  const downloadPromise = page.waitForEvent("download", { timeout: 45_000 });
  await page
    .getByRole("menuitem", { name: RE_PDF })
    .or(page.getByRole("button", { name: RE_PDF }))
    .first()
    .click();
  const downloadResult = await settle(downloadPromise);
  if (downloadResult.status === "rejected") {
    await writeError(`PDF download failed: ${downloadResult.reason.message}`);
    await shot(page, "pdf-failed");
    return null;
  }
  const path = await saveDownload(downloadResult.value, "resume-real.pdf");
  const bytes = (await Bun.file(path).arrayBuffer()).byteLength;
  const header = Buffer.from(await Bun.file(path).arrayBuffer())
    .subarray(0, NUM_5)
    .toString("utf8");
  await writeOutput(`PDF path=${path} bytes=${String(bytes)} header=${header}`);
  if (header !== "%PDF-" || bytes < NUM_1000) {
    await writeError("Downloaded file is not a real PDF");
    return null;
  }
  await shot(page, "01-pdf-exported");
  // Rich preview page
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.resumePreview}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, NUM_2000);
  await shot(page, "02-resume-preview-rich");
  return path;
};

const enablePortalAndScrape = async (page: Page): Promise<boolean> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTE_BUILDERS.settingsSection("jobIntelligence")}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, NUM_2000);

  // Enable Work With Indies portal checkbox if present
  const portalToggle = page.getByLabel(RE_WWI).or(page.getByText(RE_WWI)).first();
  await settle(portalToggle.click({ timeout: 5_000 }));
  // Fill greenhouse board for a known public board as secondary source
  const boards = page.getByLabel(RE_GREENHOUSE_BOARDS).first();
  if ((await boards.count()) > 0) {
    await boards.fill(
      JSON.stringify([{ board: "discord", company: "Discord", enabled: true }], null, 2),
    );
  }
  await page.getByRole("button", { name: RE_SAVE }).last().click();
  await wait(page, NUM_2000);
  await shot(page, "03-providers-saved");

  await page.goto(`${CLIENT_BASE}${APP_ROUTES.automationScraper}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, NUM_2500);
  const runButtons = page.getByRole("button", { name: RE_SCRAPE_RUN });
  await writeOutput(`scraper run buttons=${String(await runButtons.count())}`);
  const enabledRun = runButtons.filter({ hasNot: page.locator(":disabled") }).first();
  if ((await enabledRun.count()) > 0) {
    await enabledRun.click();
    await wait(page, NUM_35000);
  }
  await shot(page, "04-scraper-ran");

  await page.goto(`${CLIENT_BASE}${APP_ROUTES.jobs}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, NUM_1500);
  const refresh = page.getByRole("button", { name: RE_REFRESH_JOBS }).first();
  if ((await refresh.count()) > 0) {
    await refresh.click();
    await wait(page, NUM_20000);
  }
  await shot(page, "05-jobs-feed");
  const empty = await page.getByText(RE_NO_JOBS).count();
  const cards = await page.locator("main .card, main article").count();
  const titles = await page.evaluate(() =>
    [...document.querySelectorAll("main h3, main .card-title")]
      .map((el) => (el.textContent ?? "").trim())
      .filter((text) => text.length > 0)
      .slice(0, NUM_8),
  );
  await writeOutput(
    `jobs empty=${String(empty)} cards=${String(cards)} titles=${JSON.stringify(titles)}`,
  );
  return empty === 0 && titles.length > 0;
};

const proveBrowserTts = async (page: Page): Promise<boolean> => {
  await page.goto(`${CLIENT_BASE}${APP_ROUTES.interview}`, {
    waitUntil: "domcontentloaded",
    timeout: 60_000,
  });
  await wait(page, NUM_1500);
  const result = await page.evaluate(async () => {
    const synth = window.speechSynthesis;
    if (!synth) {
      return { ok: false, reason: "speechSynthesis missing" };
    }
    const voices = synth.getVoices();
    const utterance = new SpeechSynthesisUtterance(
      "BaoBuildBuddy interview voice proof. This is real browser text to speech.",
    );
    utterance.rate = 1;
    utterance.volume = 1;
    const spoken = await new Promise<boolean>((resolve) => {
      utterance.onend = () => {
        resolve(true);
      };
      utterance.onerror = () => {
        resolve(false);
      };
      synth.cancel();
      synth.speak(utterance);
      // Some environments fire neither end nor error promptly.
      window.setTimeout(() => {
        resolve(synth.speaking || voices.length >= 0);
      }, NUM_2500);
    });
    return {
      ok: spoken,
      voiceCount: voices.length,
      speaking: synth.speaking,
    };
  });
  await shot(page, "06-interview-tts");
  await writeOutput(`TTS ${JSON.stringify(result)}`);
  return result.ok;
};

const main = async (): Promise<void> => {
  await mkdir(join(OUT, "stills"), { recursive: true });
  await mkdir(join(OUT, "downloads"), { recursive: true });
  await mkdir(join(OUT, "raw-segments"), { recursive: true });

  const browser = await chromium.launch({ headless: false, args: ["--disable-dev-shm-usage"] });
  const context = await browser.newContext({
    acceptDownloads: true,
    recordVideo: { dir: join(OUT, "raw-segments"), size: { width: 1440, height: 900 } },
    viewport: { width: 1280, height: 900 },
  });
  const page = await context.newPage();

  const pdfPath = await exportResumePdf(page);
  const scrapeOk = await enablePortalAndScrape(page);
  const ttsOk = await proveBrowserTts(page);

  const video = page.video();
  await context.close();
  await browser.close();

  let videoPath: string | null = null;
  if (video) {
    const raw = await video.path();
    videoPath = join(OUT, "honest-capabilities.webm");
    await Bun.write(videoPath, Bun.file(raw));
  }

  const pdfStat = pdfPath ? await stat(pdfPath) : null;
  const report = {
    headless: false,
    display: process.env.DISPLAY ?? null,
    ai: {
      status: "BLOCKED",
      reason:
        "Ollama llama-server SEGV on this host (qwen2.5:0.5b); GEMINI/OPENAI/CLAUDE/HUGGINGFACE keys empty in .env",
      evidence: [
        "/opt/cursor/artifacts/baseline/ollama-chat2.txt",
        "/opt/cursor/artifacts/baseline/ollama-generate-api.txt",
      ],
    },
    stt: {
      status: "BLOCKED",
      reason: "No microphone device / permission in this cloud agent environment for real STT",
    },
    pdf: {
      status: pdfPath && pdfStat && pdfStat.size > NUM_1000 ? "OK" : "FAIL",
      path: pdfPath,
      bytes: pdfStat?.size ?? 0,
    },
    scrape: { status: scrapeOk ? "OK" : "FAIL" },
    tts: { status: ttsOk ? "OK" : "FAIL" },
    videoPath,
  };
  await Bun.write(join(OUT, "honest-report.json"), JSON.stringify(report, null, 2));
  await writeOutput(JSON.stringify(report, null, 2));

  if (report.pdf.status !== "OK" || report.scrape.status !== "OK" || report.tts.status !== "OK") {
    process.exitCode = 1;
  }
};

await main();

import { writeError, writeOutput } from "./utils/cli-output";
