  },
] as const;

type LlmSource = (typeof LLM_SOURCES)[number];

type SourceAudit = {
  name: string;
  url: string;
  finalUrl: string;
  statusCode: number;
  ok: boolean;
  redirected: boolean;
  lineCount: number;
  contentLength: number;
  missingMarkers: string[];
  fetchError: string | null;
  failureClass: "none" | "timeout" | "network" | "http" | "marker" | "unknown";
  attempts: number;
};

const countLines = (text: string): number =>
  text.length === 0 ? 0 : text.split(LINE_BREAK_PATTERN).length;

const classifyFetchError = (reason: string): SourceAudit["failureClass"] => {
  if (reason.toLowerCase().includes("timeout")) {
    return "timeout";
  }
  if (
    reason.toLowerCase().includes("network") ||
    reason.toLowerCase().includes("fetch") ||
    reason.toLowerCase().includes("dns")
  ) {
    return "network";
  }
  return "unknown";
};

const auditResponse = async (
  source: LlmSource,
  attempts: number,
  response: Response,
): Promise<SourceAudit> => {
  const content = await response.text();
  const missingMarkers = source.requiredMarkers.filter((marker) => !content.includes(marker));
  let failureClass: "http" | "marker" | "none" = "none";
  if (!response.ok) {
    failureClass = "http";
  } else if (missingMarkers.length > 0) {
    failureClass = "marker";
  }

  return {
    name: source.name,
    url: source.url,
    finalUrl: response.url,
    statusCode: response.status,
    ok: response.ok && missingMarkers.length === 0,
    redirected: response.url !== source.url,
    lineCount: countLines(content),
    contentLength: content.length,
    missingMarkers,
    fetchError: null,
    failureClass,
    attempts,
  };
};

const createFetchErrorAudit = (
  source: LlmSource,
  reason: unknown,
  attempts: number,
): SourceAudit => {
  const errorMessage = String(reason);

  return {
    name: source.name,
    url: source.url,
    finalUrl: source.url,
    statusCode: 0,
    ok: false,
    redirected: false,
    lineCount: 0,
    contentLength: 0,
    missingMarkers: [...source.requiredMarkers],
    fetchError: errorMessage,
    failureClass: classifyFetchError(errorMessage),
    attempts,
  };
};

const attemptAudit = async (source: LlmSource, attempts: number): Promise<SourceAudit> => {
  const result = await Promise.allSettled([
    fetch(source.url, {
      redirect: "follow",
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
    }),
  ]);
  const fetchResult = result[0];

  if (fetchResult.status === "rejected") {
    return createFetchErrorAudit(source, fetchResult.reason, attempts);
  }

  return auditResponse(source, attempts, fetchResult.value);
};

const auditSource = async (source: LlmSource, attempts = 1): Promise<SourceAudit> => {
  const audit = await attemptAudit(source, attempts);
  if (
    attempts >= FETCH_RETRY_COUNT ||
    audit.failureClass === "none" ||
    audit.failureClass === "marker"
  ) {
    return audit;
  }

  return auditSource(source, attempts + 1);
};

const formatResult = (audit: SourceAudit): string => {
  const statusToken = audit.ok ? "PASS" : "FAIL";
  const markerStatus =
    audit.missingMarkers.length === 0
      ? "markers=ok"
      : `markers=missing(${audit.missingMarkers.join(" | ")})`;
  const errorStatus = audit.fetchError ? `error=${audit.fetchError}` : "error=none";
  const failureStatus = `failureClass=${audit.failureClass}`;
  const attemptStatus = `attempts=${audit.attempts}`;

  return [
    `[${statusToken}]`,
    audit.name,
    `source=${audit.url}`,
    `final=${audit.finalUrl}`,
    `status=${audit.statusCode}`,
    `redirected=${audit.redirected}`,
    `lines=${audit.lineCount}`,
    `bytes=${audit.contentLength}`,
    markerStatus,
    failureStatus,
    attemptStatus,
    errorStatus,
  ].join(" ");
};

const writeLine = (line: string): void => {
  process.stdout.write(`${line}\n`);
};

const settledAudits = await Promise.allSettled(LLM_SOURCES.map((source) => auditSource(source)));
const audits: SourceAudit[] = settledAudits.map((result, index) =>
  result.status === "fulfilled"
    ? result.value
    : createFetchErrorAudit(LLM_SOURCES[index], result.reason, FETCH_RETRY_COUNT),
);

writeLine("Official llms.txt audit results");
for (const audit of audits) {
  writeLine(formatResult(audit));
}

const failedAudits = audits.filter((audit) => !audit.ok);
writeLine(
  failedAudits.length === 0
    ? "Summary: all official llms.txt sources are reachable and contain required markers."
    : `Summary: ${failedAudits.length} source(s) failed validation.`,
);

if (failedAudits.length > 0) {
  process.exitCode = 1;
}

const NUM_122 = 122;
const NUM_4 = 4;
const NUM_40 = 40;
const NUM_65 = 65;
const NUM_90 = 90;
const NUM_97 = 97;
/**
 * Chrome signal collectors for browser-interaction-burndown (complexity split).
 */
import type { Page } from "playwright";

export type ChromeSignals = {
  readonly mains: number;
  readonly h1: string;
  readonly title: string;
  readonly overflowX: number;
  readonly truncatedChrome: boolean;
  readonly clippedSectionTabs: boolean;
  readonly duplicateChromeCopy: readonly string[];
  readonly rawGlass: boolean;
  readonly bodyLen: number;
};

const collectShellLandmarks = async (page: Page) =>
  page.evaluate(() => {
    const collapseWs = (value: string): string => {
      let out = "";
      let prevSpace = false;
      for (const ch of value) {
        const isSpace = ch === " " || ch === "\n" || ch === "\t" || ch === "\r";
        if (isSpace) {
          if (!prevSpace) out += " ";
          prevSpace = true;
          continue;
        }
        out += ch;
        prevSpace = false;
      }
      return out.trim();
    };
    return {
      mains: document.querySelectorAll("main").length,
      h1: collapseWs(document.querySelector("h1")?.textContent ?? ""),
      title: document.title.trim(),
      overflowX:
        Math.max(document.documentElement.scrollWidth, document.body?.scrollWidth ?? 0) -
        window.innerWidth,
      bodyLen: collapseWs(document.body?.innerText ?? "").length,
    };
  });

const collectChromeQuality = async (page: Page) =>
  page.evaluate(() => {
    const isAsciiLetter = (ch: string): boolean => {
      const code = ch.charCodeAt(0);
      return (code >= NUM_65 && code <= NUM_90) || (code >= NUM_97 && code <= NUM_122);
    };
    const isNavbarEllipsisGut = (text: string): boolean => {
      if (text.length === 2) return isAsciiLetter(text[0] ?? "") && text[1] === "…";
      if (text.length === NUM_4) return isAsciiLetter(text[0] ?? "") && text.slice(1) === "...";
      return false;
    };
    const collapseWs = (value: string): string => value.replace(/\s+/gu, " ").trim();
    const clippedSectionTabs = [...document.querySelectorAll(".tabs .tab")].some((el) => {
      const label =
        el.querySelector("span.truncate, span.font-medium, span.whitespace-nowrap") ??
        (el instanceof HTMLElement ? el : null);
      if (!(label instanceof HTMLElement)) return false;
      if (label.scrollWidth <= label.clientWidth + 1) return false;
      const className = label.className?.toString?.() ?? "";
      const style = getComputedStyle(label);
      const intentionalTruncate =
        className.includes("truncate") || style.textOverflow === "ellipsis";
      return !intentionalTruncate;
    });
    const texts = [...document.querySelectorAll("p")]
      .filter((el) => !el.closest(".grid, .stats, [role='log']"))
      .map((el) => collapseWs(el.textContent ?? ""))
      .filter((text) => text.length > NUM_40);
    const counts = new Map<string, number>();
    for (const text of texts) {
      counts.set(text, (counts.get(text) ?? 0) + 1);
    }
    const rawGlass = [...document.querySelectorAll("*")].some((el) => {
      const style = getComputedStyle(el);
      const filter =
        style.getPropertyValue("backdrop-filter") ||
        style.getPropertyValue("-webkit-backdrop-filter") ||
        "";
      if (!filter || filter === "none") return false;
      return !(el.className?.toString?.() ?? "").includes("glass");
    });
    return {
      truncatedChrome: [...document.querySelectorAll(".navbar *")]
        .map((el) => (el.textContent ?? "").trim())
        .some((text) => isNavbarEllipsisGut(text)),
      clippedSectionTabs,
      duplicateChromeCopy: [...counts.entries()]
        .filter(([, count]) => count > 1)
        .map(([text]) => text),
      rawGlass,
    };
  });

export const collectChromeSignals = async (page: Page): Promise<ChromeSignals> => {
  const landmarks = await collectShellLandmarks(page);
  const quality = await collectChromeQuality(page);
  return {
    mains: landmarks.mains,
    h1: landmarks.h1,
    title: landmarks.title,
    overflowX: landmarks.overflowX,
    bodyLen: landmarks.bodyLen,
    truncatedChrome: quality.truncatedChrome,
    clippedSectionTabs: quality.clippedSectionTabs,
    duplicateChromeCopy: quality.duplicateChromeCopy,
    rawGlass: quality.rawGlass,
  };
};

import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";
const NUM_16 = 16;

const bannedPattern =
  /\b(?:shims?|polyfills?|compat(?:ibility|ibilities)?|wrappers?|adapters?)\b/giu;
const disabledPolyfillPattern = /\bpolyfill\s*:\s*false\b/u;

const isDisabledPolyfillConfiguration = (content: string, matchIndex: number): boolean => {
  const surroundingSnippet = content.slice(
    Math.max(0, matchIndex - NUM_16),
    Math.min(content.length, matchIndex + 24),
  );
  return disabledPolyfillPattern.test(surroundingSnippet);
};

export const collectFallbackShimViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (filePath.endsWith(".test.ts") || filePath.endsWith(".spec.ts")) {
    return [];
  }
  const violations: ValidationViolation[] = [];
  bannedPattern.lastIndex = 0;
  for (const match of content.matchAll(bannedPattern)) {
    const value = match[0] ?? "";
    const matchIndex = match.index ?? 0;
    if (filePath.endsWith("scripts/validate-no-fallback-shims.ts")) {
      continue;
    }
    if (
      value.toLowerCase().startsWith("polyfill") &&
      isDisabledPolyfillConfiguration(content, matchIndex)
    ) {
      continue;
    }
    violations.push({
      filePath,
      line: getLineFromOffset(content, matchIndex),
      message: `Fallback term "${value}" is forbidden. Replace it with the concrete single-source implementation.`,
    });
  }
  return violations;
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots: ["packages", "scripts"],
    allowedExtensions: new Set([".ts", ".tsx", ".vue", ".md", ".rs"]),
  });

  return files.flatMap(({ filePath, content }) =>
    collectFallbackShimViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Fallback term validation failed:",
    await collectViolations(),
    "Fallback term validation passed.",
  );
}

import { writeError, writeOutput } from "./utils/cli-output";
import { getLineFromOffset, shouldIgnorePath } from "./utils/validation-helpers";
const NUM_120 = 120;
const NUM_160 = 160;

type Violation = {
  filePath: string;
  line: number;
  message: string;
};

const projectRoot = process.cwd();
const vueScanRoots = [
  "packages/client/pages",
  "packages/client/components",
  "packages/client/layouts",
] as const;
const bootstrapScanRoots = ["packages/client/composables"] as const;
const vueFileLimit = 310;
const styleBlockPattern = /<style\b/gu;
const lineBreakPattern = /\r?\n/u;
const settingsPanelPathPattern =
  /^packages\/client\/components\/settings\/Settings[A-Za-z0-9]+Panel\.vue$/u;
const settingsPanelHeaderUsagePattern = /<SettingsPanelHeader\b/u;
const brittleSettingsHeaderPattern =
  /\bclass\s*=\s*["']flex items-center justify-between gap-3["']/gu;
const settingsBootstrapFilePattern =
  /^packages\/client\/composables\/(?:.*bootstrap.*|settings-page\/runtime\.ts)$/u;
const settingsFetchCallPattern = /\b(?:[A-Za-z0-9_$]+\.)?fetchSettings\(\)/gu;
const settingsFetchGuardPatterns = [
  /if\s*\(\s*!\s*[A-Za-z0-9_$.]+\.value\s*\)/u,
  /[A-Za-z0-9_$.]+\.value\s*\?\s*Promise\.resolve\(\)\s*:\s*(?:[A-Za-z0-9_$]+\.)?fetchSettings\(\)/u,
] as const;

const collectFiles = async (roots: readonly string[], pattern: string): Promise<string[]> => {
  const fileGroups = await Promise.all(
    roots.map(async (root) => {
      const glob = new Bun.Glob(`${root}/**/${pattern}`);
      return Array.fromAsync(glob.scan({ cwd: projectRoot, onlyFiles: true }));
    }),
  );

  return fileGroups
    .flat()
    .map((filePath) => filePath.replace(/\\/gu, "/"))
    .filter((filePath) => !shouldIgnorePath(filePath));
};

const createViolation = (filePath: string, line: number, message: string): Violation => ({
  filePath,
  line,
  message,
});

const collectStyleBlockViolations = (filePath: string, fileContent: string): Violation[] => {
  const violations: Violation[] = [];
  styleBlockPattern.lastIndex = 0;
  for (const match of fileContent.matchAll(styleBlockPattern)) {
    violations.push(
      createViolation(
        filePath,
        getLineFromOffset(fileContent, match.index ?? 0),
        "Vue SFC <style> blocks are forbidden. Use shared daisyUI/Tailwind tokens or centralized CSS.",
      ),
    );
  }
  return violations;
};

const collectVueLineCountViolations = (filePath: string, fileContent: string): Violation[] => {
  const lineCount = fileContent.split(lineBreakPattern).length;
  if (lineCount <= vueFileLimit) {
    return [];
  }

  return [
    createViolation(
      filePath,
      1,
      `Vue UI file exceeds ${vueFileLimit} lines. Break the monolith into focused components/composables.`,
    ),
  ];
};

const collectSettingsPanelViolations = (filePath: string, fileContent: string): Violation[] => {
  if (!settingsPanelPathPattern.test(filePath)) {
    return [];
  }

  const violations: Violation[] = [];
  if (!settingsPanelHeaderUsagePattern.test(fileContent)) {
    violations.push(
      createViolation(
        filePath,
        1,
        "Settings panels must use the shared `SettingsPanelHeader` component so title, subtitle, and trailing status content stay DRY and responsive.",
      ),
    );
  }

  brittleSettingsHeaderPattern.lastIndex = 0;
  for (const match of fileContent.matchAll(brittleSettingsHeaderPattern)) {
    violations.push(
      createViolation(
        filePath,
        getLineFromOffset(fileContent, match.index ?? 0),
        "Bespoke `flex items-center justify-between gap-3` settings headers are forbidden. Use `SettingsPanelHeader` for wrapped copy and trailing badges.",
      ),
    );
  }

  return violations;
};

const hasSettingsFetchGuard = (fileContent: string, matchIndex: number): boolean => {
  const contextWindow = fileContent.slice(
    Math.max(0, matchIndex - NUM_160),
    Math.min(fileContent.length, matchIndex + NUM_120),
  );
  return settingsFetchGuardPatterns.some((pattern) => pattern.test(contextWindow));
};

const collectSettingsBootstrapViolations = (filePath: string, fileContent: string): Violation[] => {
  if (!settingsBootstrapFilePattern.test(filePath)) {
    return [];
  }

  const violations: Violation[] = [];
  settingsFetchCallPattern.lastIndex = 0;
  for (const match of fileContent.matchAll(settingsFetchCallPattern)) {
    const matchIndex = match.index ?? 0;
    if (hasSettingsFetchGuard(fileContent, matchIndex)) {
      continue;
    }

    violations.push(
      createViolation(
        filePath,
        getLineFromOffset(fileContent, matchIndex),
        "App settings bootstrap must stay single-source. Guard page/composable `fetchSettings()` calls behind a missing-state check instead of refetching during every bootstrap.",
      ),
    );
  }

  return violations;
};

const collectVueFileViolations = (filePath: string, fileContent: string): Violation[] => {
  if (!filePath.endsWith(".vue")) {
    return [];
  }

  return [
    ...collectStyleBlockViolations(filePath, fileContent),
    ...collectVueLineCountViolations(filePath, fileContent),
    ...collectSettingsPanelViolations(filePath, fileContent),
  ];
};

export const collectUiSingleSourceViolationsForContent = (
  filePath: string,
  fileContent: string,
): Violation[] => [
  ...collectVueFileViolations(filePath, fileContent),
  ...collectSettingsBootstrapViolations(filePath, fileContent),
];

const collectViolations = async (): Promise<Violation[]> => {
  const [vueFiles, bootstrapFiles] = await Promise.all([
    collectFiles(vueScanRoots, "*.vue"),
    collectFiles(bootstrapScanRoots, "*.ts"),
  ]);
  const files = [...vueFiles, ...bootstrapFiles];
  const violationGroups = await Promise.all(
    files.map(async (filePath) =>
      collectUiSingleSourceViolationsForContent(filePath, await Bun.file(filePath).text()),
    ),
  );

  return violationGroups.flat();
};

const main = async (): Promise<void> => {
  const violations = await collectViolations();
  if (violations.length === 0) {
    await writeOutput("UI single-source-of-truth validation passed.");
    return;
  }

  await writeError(
    "UI single-source-of-truth validation failed. Break monoliths and move custom styles into shared tokens:",
  );
  const lines = violations.map(
    (violation) => `- ${violation.filePath}:${violation.line} ${violation.message}`,
  );
  if (lines.length > 0) {
    await writeError(lines.join("\n"));
  }

  process.exit(1);
};

if (import.meta.main) {
  await main();
}

