import { readFile } from "node:fs/promises";
import { reportViolations, type ValidationViolation } from "./utils/validation-helpers";

const AI_CHAT_DOCK_ID_THEN_FLAG_PATTERN = /id:\s*["']ai-chat["'][\s\S]*?includeInDock:\s*true/u;
const AI_CHAT_DOCK_FLAG_THEN_ID_PATTERN = /includeInDock:\s*true[\s\S]*?id:\s*["']ai-chat["']/u;

/**
 * Dual-chat chrome gate: when mobile dock owns AI Chat, floating chat must be
 * gated to desktop (isDesktopViewport) and never on /ai/*.
 * Catches papered-over dual primary destinations.
 */
export const collectDualChatChromeViolations = async (): Promise<ValidationViolation[]> => {
  const violations: ValidationViolation[] = [];
  const layoutPath = "packages/client/layouts/default.vue";
  const navPath = "packages/client/constants/navigation.ts";
  const [layout, nav] = await Promise.all([
    readFile(layoutPath, "utf8"),
    readFile(navPath, "utf8"),
  ]);

  const dockHasAiChat =
    AI_CHAT_DOCK_ID_THEN_FLAG_PATTERN.test(nav) || AI_CHAT_DOCK_FLAG_THEN_ID_PATTERN.test(nav);

  if (!dockHasAiChat) {
    return violations;
  }

  if (!layout.includes("FloatingChatWidget") && !layout.includes("LazyFloatingChatWidget")) {
    return violations;
  }

  if (!layout.includes("isDesktopViewport")) {
    violations.push({
      filePath: layoutPath,
      line: 1,
      message:
        "Dock includes ai-chat but floating chat is not gated on isDesktopViewport — dual chat chrome below lg.",
    });
  }

  if (!layout.includes("APP_ROUTES.ai") && !layout.includes("AI_CHAT_PAGE_PATH")) {
    violations.push({
      filePath: layoutPath,
      line: 1,
      message: "Floating chat must hide on APP_ROUTES.ai (and children) when dock owns AI Chat.",
    });
  }

  return violations;
};

if (import.meta.main) {
  await reportViolations(
    "Dual chat chrome validation failed:",
    await collectDualChatChromeViolations(),
    "Dual chat chrome validation passed.",
  );
}

import { describe, expect, test } from "bun:test";
import { collectResponsiveOverflowViolationsForContent } from "./validate-ui-responsive-overflow";

const CONSUMER_PATH = "packages/client/components/dashboard/ExampleWidget.vue";
const SSOT_LAYOUT_PATH = "packages/client/constants/layout.ts";

describe("collectResponsiveOverflowViolationsForContent", () => {
  test("flags fixed width w-64 without min-w-0 or max-w guard", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="flex w-64"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("w-64"))).toBe(true);
  });

  test("allows w-64 with min-w-0 guard", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="flex w-64 min-w-0"></div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("allows w-full", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="w-full"></div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("flags fixed height h-64 on content block", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="h-64"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("h-64"))).toBe(true);
  });

  test("flags grid-cols-4 without responsive guard", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="grid grid-cols-4"></div></template>',
    );
    expect(violations.some((v) => v.message.includes("grid-cols-4"))).toBe(true);
  });

  test("allows grid-cols-1 sm:grid-cols-4", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      CONSUMER_PATH,
      '<template><div class="grid grid-cols-1 sm:grid-cols-4"></div></template>',
    );
    expect(violations).toHaveLength(0);
  });

  test("allows SSOT layout constants to define fixed widths", () => {
    const violations = collectResponsiveOverflowViolationsForContent(
      SSOT_LAYOUT_PATH,
      'export const X = "lg:w-64 shrink-0";',
    );
    expect(violations).toHaveLength(0);
  });
});

import { isUiSsotAuthority } from "./ui-ssot-authority";
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

/**
 * Ban physical CSS direction utilities in consumers (brutalise UI010).
 * SSOT authority may still define migration aliases until tokens are fully logical.
 */

const scanRoots = ["packages/client"] as const;
const sourceExtensions = new Set([".vue", ".ts", ".css"]);
// Require a scale/position suffix for ml|mr|pl|pr|left|right so bare JS identifiers
// and natural-language substrings (e.g. French "pr" before accents) are not flagged.
// Complete utilities text-left|text-right|float-left|float-right match as wholes.
const physicalUtilityPattern =
  /(?:^|[\s"'`:])((?:(?:ml|mr|pl|pr|left|right)(?:-\[[^\]]+\]|-(?:auto|px|full|\d+(?:\.\d+)?))|(?:text|float)-(?:left|right)))\b/gu;
const physicalCssPropertyPattern =
  /(?:^|[;{\s])((?:margin|padding)-(?:left|right)|(?:left|right)\s*:|text-align\s*:\s*(?:left|right))/giu;

export const collectLogicalCssViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (isUiSsotAuthority(filePath)) {
    return [];
  }
  const violations: ValidationViolation[] = [];
  physicalUtilityPattern.lastIndex = 0;
  for (const match of content.matchAll(physicalUtilityPattern)) {
    const token = match[1] ?? match[0];
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Physical direction token "${token}" is forbidden. Use logical ms/me/ps/pe/text-start|end/inset-inline-*.`,
    });
  }
  physicalCssPropertyPattern.lastIndex = 0;
  for (const match of content.matchAll(physicalCssPropertyPattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message: `Physical CSS "${(match[1] ?? match[0]).trim()}" is forbidden. Use logical properties.`,
    });
  }
  return violations;
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots: [...scanRoots],
    allowedExtensions: sourceExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectLogicalCssViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Logical CSS validation failed:",
    await collectViolations(),
    "Logical CSS validation passed.",
  );
}

