import {
  collectProjectFileEntries,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const importPathPattern = /from\s+['"`]([^'"`]+)['"`]/gu;
const sideEffectImportPathPattern = /\bimport\s+['"`]([^'"`]+)['"`]/gu;
const dynamicImportPathPattern = /import\(\s*['"`]([^'"`]+)['"`]\s*\)/gu;
const namedExportPattern =
  /\bexport\s+(?:async\s+)?(?:class|function|const|let|var|type|interface)\s+([A-Za-z0-9_]+)/gu;
const reExportPattern = /\bexport\s*\{\s*([^}]+)\s*\}/gu;
const exportFromPathPattern =
  /\bexport\s+(?:\*\s*(?:as\s+[A-Za-z0-9_]+\s*)?|\{[^}]+\})\s*from\s*['"`]([^'"`]+)['"`]/gu;
const defaultExportPattern = /\bexport\s+default\b/gu;
const LEADING_SLASH_PATTERN = /^\/+/u;
const FILE_EXTENSION_PATTERN = /\.(ts|vue)$/u;
const NUXT_IMPORTS_MANIFEST_PATH = "packages/client/.nuxt/imports.d.ts";
const autoImportExportPattern = /\bexport\s*\{\s*([^}]+)\s*\}\s*from\s*['"`][^'"`]+['"`]/gu;
const AS_CLAUSE_PATTERN = /\s+as\s+/u;
const SOURCE_FILE_EXTENSIONS = [".ts", ".tsx", ".vue", ".js", ".mjs", ".cjs"] as const;

const stripSourceExtension = (pathValue: string): string => {
  for (const extension of SOURCE_FILE_EXTENSIONS) {
    if (pathValue.endsWith(extension)) {
      return pathValue.slice(0, -extension.length);
    }
  }
  return pathValue;
};

const collectSourceCandidates = (pathValue: string): string[] => {
  const basePath = stripSourceExtension(pathValue);
  const candidates = new Set<string>([pathValue, basePath]);

  for (const extension of SOURCE_FILE_EXTENSIONS) {
    candidates.add(`${basePath}${extension}`);
    candidates.add(`${basePath}/index${extension}`);
  }

  return [...candidates];
};

const LOCALE_ENTRY_FILE_PATTERN = /^packages\/client\/locales\/[^/]+\.ts$/u;
const LOCALE_CATALOG_FILE_PATTERN = /^packages\/client\/locales\/[^/]+\/catalog\.ts$/u;

const isLocaleCatalogEntrypoint = (filePath: string): boolean =>
  LOCALE_ENTRY_FILE_PATTERN.test(filePath) || LOCALE_CATALOG_FILE_PATTERN.test(filePath);

const isFrameworkEntrypointFile = (filePath: string): boolean =>
  filePath.endsWith(".test.ts") ||
  filePath.endsWith(".d.ts") ||
  filePath === "packages/client/app.vue" ||
  filePath === "packages/client/error.vue" ||
  filePath === "packages/client/nuxt.config.ts" ||
  filePath === "packages/client/vitest.config.ts" ||
  filePath.startsWith("packages/client/pages/") ||
  filePath.startsWith("packages/client/plugins/") ||
  filePath.startsWith("packages/client/layouts/") ||
  filePath.startsWith("packages/client/middleware/") ||
  isLocaleCatalogEntrypoint(filePath);

const normalizeImportTargets = (sourceFilePath: string, importPath: string): string[] => {
  if (importPath.startsWith("@bao/shared/")) {
    const relative = importPath.slice("@bao/shared/".length);
    return collectSourceCandidates(`packages/shared/src/${relative}`);
  }

  if (importPath.startsWith(".")) {
    const sourceDir = sourceFilePath.slice(0, sourceFilePath.lastIndexOf("/"));
    const joined = new URL(`${sourceDir}/${importPath}`, "file:///").pathname.replace(
      LEADING_SLASH_PATTERN,
      "",
    );
    return collectSourceCandidates(joined);
  }

  if (importPath.startsWith("~/")) {
    const relative = importPath.slice(2);
    return collectSourceCandidates(`packages/client/${relative}`);
  }

  return [];
};

const collectExportedRuntimeNames = (content: string): string[] => {
  const exportedNames = new Set<string>();
  const runtimeExportPattern =
    /\bexport\s+(?:async\s+)?(?:class|function|const|let|var)\s+([A-Za-z0-9_]+)/gu;
  runtimeExportPattern.lastIndex = 0;
  for (const match of content.matchAll(runtimeExportPattern)) {
    const exportedName = match[1];
    if (exportedName) {
      exportedNames.add(exportedName);
    }
  }

  reExportPattern.lastIndex = 0;
  for (const match of content.matchAll(reExportPattern)) {
    const clause = match[1] ?? "";
    for (const part of clause.split(",")) {
      const normalized = part.trim().split(AS_CLAUSE_PATTERN).at(-1)?.trim();
      if (normalized) {
        exportedNames.add(normalized);
      }
    }
  }

  return [...exportedNames];
};

const collectNuxtAutoImportNames = async (): Promise<Set<string>> => {
  const manifest = Bun.file(NUXT_IMPORTS_MANIFEST_PATH);
  if (!(await manifest.exists())) {
    return new Set();
  }

  const content = await manifest.text();
  const names = new Set<string>();

  autoImportExportPattern.lastIndex = 0;
  for (const match of content.matchAll(autoImportExportPattern)) {
    const clause = match[1] ?? "";
    for (const part of clause.split(",")) {
      const normalized = part.trim().split(AS_CLAUSE_PATTERN).at(-1)?.trim();
      if (normalized) {
        names.add(normalized);
      }
    }
  }

  return names;
};

const hasExports = (content: string): boolean => {
  namedExportPattern.lastIndex = 0;
  if (namedExportPattern.test(content)) {
    return true;
  }

  reExportPattern.lastIndex = 0;
  if (reExportPattern.test(content)) {
    return true;
  }

  exportFromPathPattern.lastIndex = 0;
  if (exportFromPathPattern.test(content)) {
    return true;
  }

  defaultExportPattern.lastIndex = 0;
  return defaultExportPattern.test(content);
};

const hasAutoImportConsumer = (
  filePath: string,
  exportName: string,
  sourceFiles: Array<{ filePath: string; content: string }>,
  autoImportNames: Set<string>,
): boolean => {
  const usagePattern = new RegExp(
    `\\b${exportName.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}\\b`,
    "u",
  );
  const isNuxtAutoImport = autoImportNames.has(exportName);
  return sourceFiles.some(({ filePath: sourceFilePath, content }) => {
    if (sourceFilePath === filePath) {
      return false;
    }
    if (!(isNuxtAutoImport || exportName.startsWith("use"))) {
      return false;
    }
    usagePattern.lastIndex = 0;
    return usagePattern.test(content);
  });
};

export const collectImportedTargets = (
  importSources: Array<{ filePath: string; content: string }>,
): Set<string> => {
  const importedTargets = new Set<string>();
  const importPatterns = [
    importPathPattern,
    sideEffectImportPathPattern,
    dynamicImportPathPattern,
    exportFromPathPattern,
  ];

  const collectPatternTargets = (filePath: string, content: string, pattern: RegExp): string[] => {
    pattern.lastIndex = 0;
    const targets: string[] = [];
    for (const match of content.matchAll(pattern)) {
      const importPath = match[1] ?? "";
      targets.push(...normalizeImportTargets(filePath, importPath));
    }
    return targets;
  };

  for (const { filePath, content } of importSources) {
    for (const importPattern of importPatterns) {
      for (const normalizedTarget of collectPatternTargets(filePath, content, importPattern)) {
        importedTargets.add(normalizedTarget);
      }
    }
  }

  return importedTargets;
};

export const isDeadExportViolation = (options: {
  filePath: string;
  content: string;
  importSources: Array<{ filePath: string; content: string }>;
  autoImportNames: Set<string>;
  importedTargets: Set<string>;
}): ValidationViolation[] => {
  const { filePath, content, importSources, autoImportNames, importedTargets } = options;
  if (isFrameworkEntrypointFile(filePath) || !hasExports(content)) {
    return [];
  }

  const exportedNames = collectExportedRuntimeNames(content);
  if (
    filePath.startsWith("packages/client/composables/") &&
    exportedNames.some((exportName) => exportName.startsWith("use")) &&
    exportedNames.every((exportName) =>
      hasAutoImportConsumer(filePath, exportName, importSources, autoImportNames),
    )
  ) {
    return [];
  }

  const candidatePaths = [filePath, filePath.replace(FILE_EXTENSION_PATTERN, "/index.ts")];
  const isImported = candidatePaths.some((candidatePath) => importedTargets.has(candidatePath));
  return isImported
    ? []
    : [
        {
          filePath,
          line: 1,
          message:
            "Exported module has no internal consumers. Remove the dead export or wire it into a real caller.",
        },
      ];
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots: [
      "packages/client",
      "packages/server/src",
      "packages/shared/src",
      "packages/scraper/src",
      "scripts",
    ],
    allowedExtensions: new Set([".ts", ".vue"]),
  });
  const importSources = await collectProjectFileEntries({
    scanRoots: [
      "packages/client",
      "packages/server/src",
      "packages/shared/src",
      "packages/scraper/src",
      "scripts",
    ],
    allowedExtensions: new Set([".ts", ".vue"]),
  });
  const autoImportNames = await collectNuxtAutoImportNames();
  const importedTargets = collectImportedTargets(importSources);

  return files.flatMap(({ filePath, content }) =>
    isDeadExportViolation({
      filePath,
      content,
      importSources,
      autoImportNames,
      importedTargets,
    }),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Dead export validation failed:",
    await collectViolations(),
    "Dead export validation passed.",
  );
}

/**
 * Ban requestApi + API_ENDPOINTS.* once Eden ClientApi owns the branch.
 * Softening ban: typed Eden fabric must be the sole HTTP path for owned prefixes.
 */
import {
  collectProjectFileEntries,
  getLineFromOffset,
  reportViolations,
  type ValidationViolation,
} from "./utils/validation-helpers";

const scanRoots = ["packages/client"] as const;
const allowedExtensions = new Set([".vue", ".ts"]);

/** Eden-owned prefixes — requestApi(API_ENDPOINTS.<prefix>*) is banned. */
const EDEN_OWNED_ENDPOINT_PREFIXES = [
  "automation",
  "coverLetters",
  "resumes",
  "studios",
  "jobs",
  "apiDocs",
] as const;

const REQUEST_API_EDEN_PATTERN = new RegExp(
  `requestApi\\s*(?:<[^>]*>)?\\s*\\([^)]*API_ENDPOINTS\\.(?:${EDEN_OWNED_ENDPOINT_PREFIXES.join("|")})`,
  "gu",
);
const BUILD_AUTOMATION_RUN_PATTERN = /buildAutomationRunEndpoint\s*\(/gu;
const BUILD_COVER_LETTER_DETAIL_PATTERN = /buildCoverLetterDetailEndpoint\s*\(/gu;
const BUILD_JOB_DETAIL_PATTERN = /buildJobDetailEndpoint\s*\(/gu;
const BUILD_RESUME_DETAIL_PATTERN = /buildResumeDetailEndpoint\s*\(/gu;
const BUILD_STUDIO_DETAIL_PATTERN = /buildStudioDetailEndpoint\s*\(/gu;
const REQUEST_API_CALL_PATTERN = /requestApi\s*(?:<[^>]*>)?\s*\(/u;
/** Eden maps `coverLetters` → camel path (404); route segment is `cover-letters`. */
const CAMEL_COVER_LETTERS_API_PATTERN = /\bapi\.coverLetters\b/gu;

const isAllowedFile = (filePath: string): boolean =>
  filePath.endsWith(".test.ts") ||
  filePath.endsWith(".spec.ts") ||
  filePath.includes("/locales/") ||
  // Binary export download still uses downloadApiFile + build*ExportEndpoint.
  filePath === "packages/client/composables/useCoverLetter.ts" ||
  filePath === "packages/client/composables/useResume.ts";

const collectMatchViolations = (
  filePath: string,
  content: string,
  pattern: RegExp,
  message: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  for (const match of content.matchAll(pattern)) {
    violations.push({
      filePath,
      line: getLineFromOffset(content, match.index ?? 0),
      message,
    });
  }
  return violations;
};

const collectCoverResumeEdenViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  if (REQUEST_API_CALL_PATTERN.test(content)) {
    violations.push({
      filePath,
      line: 1,
      message: `${filePath.split("/").pop()} must use Eden api.*.* for JSON CRUD — requestApi dual path banned.`,
    });
  }
  if (filePath.endsWith("useCoverLetter.ts")) {
    violations.push(
      ...collectMatchViolations(
        filePath,
        content,
        BUILD_COVER_LETTER_DETAIL_PATTERN,
        'useCoverLetter must resolve detail via Eden api["cover-letters"]({ id }) — buildCoverLetterDetailEndpoint dual path banned.',
      ),
      ...collectMatchViolations(
        filePath,
        content,
        CAMEL_COVER_LETTERS_API_PATTERN,
        'Eden cover-letters path is kebab-case — use api["cover-letters"], not api.coverLetters (404).',
      ),
    );
  }
  if (filePath.endsWith("useResume.ts")) {
    violations.push(
      ...collectMatchViolations(
        filePath,
        content,
        BUILD_RESUME_DETAIL_PATTERN,
        "useResume must resolve detail via Eden api.resumes({ id }) — buildResumeDetailEndpoint dual path banned.",
      ),
    );
  }
  return violations;
};

const collectJobsStudioEdenViolations = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  const violations: ValidationViolation[] = [];
  if (filePath.endsWith("useJobs.ts")) {
    if (REQUEST_API_CALL_PATTERN.test(content)) {
      violations.push({
        filePath,
        line: 1,
        message: "useJobs must use Eden api.jobs.* — requestApi dual path banned.",
      });
    }
    violations.push(
      ...collectMatchViolations(
        filePath,
        content,
        BUILD_JOB_DETAIL_PATTERN,
        "useJobs must resolve detail via Eden api.jobs({ id }) — buildJobDetailEndpoint dual path banned.",
      ),
    );
  }
  if (filePath.endsWith("useStudio.ts")) {
    if (REQUEST_API_CALL_PATTERN.test(content)) {
      violations.push({
        filePath,
        line: 1,
        message: "useStudio must use Eden api.studios.* — requestApi dual path banned.",
      });
    }
    violations.push(
      ...collectMatchViolations(
        filePath,
        content,
        BUILD_STUDIO_DETAIL_PATTERN,
        "useStudio must resolve detail via Eden api.studios({ id }) — buildStudioDetailEndpoint dual path banned.",
      ),
    );
  }
  return violations;
};

const collectGenericEdenViolations = (filePath: string, content: string): ValidationViolation[] => {
  const violations = [
    ...collectMatchViolations(
      filePath,
      content,
      REQUEST_API_EDEN_PATTERN,
      "Eden-owned HTTP must use useApi() branch — requestApi(API_ENDPOINTS.<owned>*) dual path banned.",
    ),
    ...collectMatchViolations(
      filePath,
      content,
      CAMEL_COVER_LETTERS_API_PATTERN,
      'Eden cover-letters path is kebab-case — use api["cover-letters"], not api.coverLetters (404).',
    ),
  ];
  if (filePath.includes("/composables/useAutomation.ts")) {
    violations.push(
      ...collectMatchViolations(
        filePath,
        content,
        BUILD_AUTOMATION_RUN_PATTERN,
        "useAutomation must resolve runs via Eden api.automation.runs({ id }) — buildAutomationRunEndpoint dual path banned.",
      ),
    );
  }
  return violations;
};

export const collectEdenDualPathViolationsForContent = (
  filePath: string,
  content: string,
): ValidationViolation[] => {
  if (
    isAllowedFile(filePath) &&
    !filePath.endsWith("useCoverLetter.ts") &&
    !filePath.endsWith("useResume.ts")
  ) {
    return [];
  }
  if (filePath.endsWith("useCoverLetter.ts") || filePath.endsWith("useResume.ts")) {
    return collectCoverResumeEdenViolations(filePath, content);
  }
  return [
    ...collectJobsStudioEdenViolations(filePath, content),
    ...collectGenericEdenViolations(filePath, content),
  ];
};

const collectViolations = async (): Promise<ValidationViolation[]> => {
  const files = await collectProjectFileEntries({
    scanRoots,
    allowedExtensions,
  });
  return files.flatMap(({ filePath, content }) =>
    collectEdenDualPathViolationsForContent(filePath, content),
  );
};

if (import.meta.main) {
  await reportViolations(
    "Eden dual-path validation failed:",
    await collectViolations(),
    "Eden dual-path validation passed.",
  );
}

import { createHash } from "node:crypto";
import { cp, mkdir, readdir, rm, stat, writeFile } from "node:fs/promises";
import { isAbsolute, join, resolve } from "node:path";
import {
  DESKTOP_RELEASE_METADATA_DIR,
  DESKTOP_RELEASE_PROVENANCE_FILENAME,
  DESKTOP_RELEASE_STAGING_ROOT,
  DESKTOP_RELEASE_TARGETS,
} from "../packages/shared/src/constants/scripts";
import { captureResult, toErrorMessage } from "./utils/async-control";
import { writeFormattedJsonFile } from "./utils/biome-format";
import { writeError, writeOutput } from "./utils/cli-output";
import {
  discoverStagedDesktopReleaseTargets,
  isDesktopReleaseProvenance,
  parseDesktopReleaseRefreshTargets,
} from "./utils/desktop-release-refresh";

type DesktopReleaseTarget = (typeof DESKTOP_RELEASE_TARGETS)[number];

type ReleaseProvenance = {
  readonly schemaVersion: 1;
  readonly target: DesktopReleaseTarget;
  readonly strategy: "matching-host-native";
  readonly tauriCli: "repo-local-bun";
  readonly hostPlatform: NodeJS.Platform;
  readonly hostArch: string;
  readonly tauriTarget: string;
  readonly artifactNames: readonly string[];
  readonly buildCommands: readonly string[];
  readonly builtAt: string;
  readonly ci: {
    readonly workflow: string | null;
    readonly runId: string | null;
    readonly runAttempt: string | null;
  };
};

/** Monorepo root (directory that contains `scripts/`). Used to spawn the verifier regardless of release layout root. */
const MONOREPO_ROOT = resolve(import.meta.dir, "..");
/**
 * Root that contains `packages/desktop/releases`. Override for tests via `BAO_DESKTOP_RELEASE_WORKSPACE_ROOT` (absolute path).
 */
const RELEASE_WORKSPACE_ROOT = (() => {
  const raw = process.env.BAO_DESKTOP_RELEASE_WORKSPACE_ROOT?.trim();
  if (!raw) {
    return MONOREPO_ROOT;
  }
  return isAbsolute(raw) ? resolve(raw) : resolve(process.cwd(), raw);
})();

const REPLACE_RELEASE_TREE_FLAG = "--replace-release-tree";
const SKIP_VERIFY_FLAG = "--skip-verify";

const DESKTOP_RELEASE_ROOT = join(RELEASE_WORKSPACE_ROOT, "packages", "desktop", "releases");
const DESKTOP_RELEASE_ASSEMBLED_PROVENANCE_PATH = join(
  DESKTOP_RELEASE_ROOT,
  DESKTOP_RELEASE_PROVENANCE_FILENAME,
);
const DESKTOP_RELEASE_METADATA_ROOT = join(DESKTOP_RELEASE_ROOT, DESKTOP_RELEASE_METADATA_DIR);
const DESKTOP_RELEASE_CHECKSUM_PATH = join(DESKTOP_RELEASE_ROOT, "sha256.txt");
const DESKTOP_RELEASE_ROOT_ALLOWED_FILES = new Set<string>([
  "README.md",
  "provenance.json",
  "sha256.txt",
]);
const DESKTOP_RELEASE_ROOT_ALLOWED_DIRECTORIES = new Set<string>([
  DESKTOP_RELEASE_METADATA_DIR,
  ...DESKTOP_RELEASE_TARGETS,
]);
const LEADING_PATH_SEPARATOR_PATTERN = /^\//u;
const MACOS_HOME_DIRECTORY_PATTERN = /\/Users\/[^/]+\//g;
const LINUX_HOME_DIRECTORY_PATTERN = /\/home\/[^/]+\//g;
const WINDOWS_HOME_DIRECTORY_PATTERN = /C:\\Users\\[^\\]+\\/g;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const resolveSourceRoot = (argv: readonly string[]): string => {
  const rootIndex = argv.indexOf("--source-root");
  const sourceRoot =
    rootIndex === -1
      ? DESKTOP_RELEASE_STAGING_ROOT
      : (argv[rootIndex + 1] ?? DESKTOP_RELEASE_STAGING_ROOT);
  return resolve(RELEASE_WORKSPACE_ROOT, sourceRoot);
};

/** Returns a path safe for committing (no username or host-specific dirs). */
const sanitizeSourceRootForProvenance = (sourceRoot: string): string => {
  if (sourceRoot.startsWith(RELEASE_WORKSPACE_ROOT)) {
    const suffix = sourceRoot
      .slice(RELEASE_WORKSPACE_ROOT.length)
      .replace(LEADING_PATH_SEPARATOR_PATTERN, "");
    return suffix ? suffix : ".desktop-release-artifacts";
  }
  return DESKTOP_RELEASE_STAGING_ROOT;
};

/** Sanitizes build command strings to remove PII before committing. */
const sanitizeBuildCommandsForProvenance = (
  commands: readonly string[],
  repoRoot: string,
): readonly string[] =>
  commands.map((cmd) => {
    let s = cmd;
    s = s.split(repoRoot).join(".");
    s = s.replace(MACOS_HOME_DIRECTORY_PATTERN, "~/");
    s = s.replace(LINUX_HOME_DIRECTORY_PATTERN, "~/");
    s = s.replace(WINDOWS_HOME_DIRECTORY_PATTERN, "<home>\\");
    return s;
  });

const sanitizeProvenanceForCommit = (p: ReleaseProvenance): ReleaseProvenance => ({
  ...p,
  buildCommands: sanitizeBuildCommandsForProvenance(p.buildCommands, MONOREPO_ROOT),
});

const pathExists = async (absolutePath: string): Promise<boolean> =>
  stat(absolutePath).then(
    () => true,
    () => false,
  );

const computeSha256 = async (absolutePath: string): Promise<string> => {
  const hasher = createHash("sha256");
  const file = Bun.file(absolutePath);
  hasher.update(Buffer.from(await file.arrayBuffer()));
  return hasher.digest("hex");
};

const parseReplaceReleaseTreeFlag = (argv: readonly string[]): boolean =>
  argv.includes(REPLACE_RELEASE_TREE_FLAG);

const parseSkipVerifyFlag = (argv: readonly string[]): boolean => argv.includes(SKIP_VERIFY_FLAG);

const readExistingAssembledTargets = async (): Promise<
  Map<DesktopReleaseTarget, ReleaseProvenance>
> => {
  const result = new Map<DesktopReleaseTarget, ReleaseProvenance>();
  if (!(await pathExists(DESKTOP_RELEASE_ASSEMBLED_PROVENANCE_PATH))) {
    return result;
  }

  const parsed: unknown = JSON.parse(
    await Bun.file(DESKTOP_RELEASE_ASSEMBLED_PROVENANCE_PATH).text(),
  );
  if (!(isRecord(parsed) && isRecord(parsed.targets))) {
    return result;
  }

  for (const target of DESKTOP_RELEASE_TARGETS) {
    const entry = parsed.targets[target];
    if (!isRecord(entry)) {
      continue;
    }
    if (!isDesktopReleaseProvenance(entry) || entry.target !== target) {
      continue;
    }
    result.set(target, entry as ReleaseProvenance);
  }

  return result;
};

const buildOrderedAssembledTargets = (
  targetMap: Map<DesktopReleaseTarget, ReleaseProvenance>,
): Record<string, ReleaseProvenance> => {
  const ordered: Record<string, ReleaseProvenance> = {};
  for (const target of DESKTOP_RELEASE_TARGETS) {
    const provenance = targetMap.get(target);
    if (provenance) {
      ordered[target] = provenance;
    }
  }
  return ordered;
};

const readProvenance = async (
  sourceRoot: string,
  target: DesktopReleaseTarget,
): Promise<ReleaseProvenance> => {
  const provenancePath = join(
    sourceRoot,
    target,
    DESKTOP_RELEASE_METADATA_DIR,
    DESKTOP_RELEASE_PROVENANCE_FILENAME,
  );
  if (!(await pathExists(provenancePath))) {
    throw new Error(`Missing provenance manifest for ${target}: ${provenancePath}`);
  }

  const parsed: unknown = JSON.parse(await Bun.file(provenancePath).text());
  if (!isRecord(parsed)) {
    throw new Error(`Invalid provenance manifest for ${target}.`);
  }

  if (!isDesktopReleaseProvenance(parsed)) {
    throw new Error(
      `Canonical release refresh requires valid release provenance for ${target}: ${provenancePath}`,
    );
  }

  return parsed as ReleaseProvenance;
};

const collectTargetArtifacts = async (
  sourceRoot: string,
  target: DesktopReleaseTarget,
): Promise<readonly string[]> => {
  const targetRoot = join(sourceRoot, target);
  if (!(await pathExists(targetRoot))) {
    throw new Error(`Missing staged source root for ${target}: ${targetRoot}`);
  }

  const entries = await readdir(targetRoot, { withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => entry.name)
    .sort((left, right) => left.localeCompare(right));
};

const stageTargetArtifacts = async (
  sourceRoot: string,
  target: DesktopReleaseTarget,
  artifactNames: readonly string[],
): Promise<void> => {
  const sourceTargetRoot = join(sourceRoot, target);
  const releaseTargetRoot = join(DESKTOP_RELEASE_ROOT, target);
  const sourceMetadataRoot = join(sourceTargetRoot, DESKTOP_RELEASE_METADATA_DIR);
  const releaseMetadataRoot = join(DESKTOP_RELEASE_METADATA_ROOT, target);

  await rm(releaseTargetRoot, { force: true, recursive: true });
  await rm(releaseMetadataRoot, { force: true, recursive: true });
  await mkdir(releaseTargetRoot, { recursive: true });
  await mkdir(releaseMetadataRoot, { recursive: true });

  await Promise.all(
    artifactNames.map((artifactName) =>
      cp(join(sourceTargetRoot, artifactName), join(releaseTargetRoot, artifactName)),
    ),
  );

  if (await pathExists(sourceMetadataRoot)) {
    await cp(sourceMetadataRoot, releaseMetadataRoot, { recursive: true });
  }
};

const pruneLegacyReleaseEntries = async (): Promise<void> => {
  if (!(await pathExists(DESKTOP_RELEASE_ROOT))) {
    return;
  }

  const releaseEntries = await readdir(DESKTOP_RELEASE_ROOT, { withFileTypes: true });
  await Promise.all(
    releaseEntries.map(async (entry) => {
      const entryPath = join(DESKTOP_RELEASE_ROOT, entry.name);
      if (entry.isDirectory()) {
        if (DESKTOP_RELEASE_ROOT_ALLOWED_DIRECTORIES.has(entry.name)) {
          return;
        }

        await rm(entryPath, { recursive: true, force: true });
        return;
      }

      if (DESKTOP_RELEASE_ROOT_ALLOWED_FILES.has(entry.name)) {
        return;
      }

      await rm(entryPath, { force: true });
    }),
  );

  if (!(await pathExists(DESKTOP_RELEASE_METADATA_ROOT))) {
    return;
  }

  const metadataEntries = await readdir(DESKTOP_RELEASE_METADATA_ROOT, { withFileTypes: true });
  await Promise.all(
    metadataEntries.map(async (entry) => {
      if (
        entry.isDirectory() &&
        DESKTOP_RELEASE_TARGETS.includes(entry.name as DesktopReleaseTarget)
      ) {
        return;
      }

      await rm(join(DESKTOP_RELEASE_METADATA_ROOT, entry.name), {
        recursive: true,
        force: true,
      });
    }),
  );
};

const pruneUnselectedReleaseTargets = async (
  selectedTargets: readonly DesktopReleaseTarget[],
): Promise<void> => {
  const selectedTargetSet = new Set(selectedTargets);

  await Promise.all(
    DESKTOP_RELEASE_TARGETS.filter((target) => !selectedTargetSet.has(target)).map(
      async (target) => {
        await rm(join(DESKTOP_RELEASE_ROOT, target), { recursive: true, force: true });
        await rm(join(DESKTOP_RELEASE_METADATA_ROOT, target), {
          recursive: true,
          force: true,
        });
      },
    ),
  );
};

const writeChecksumManifest = async (): Promise<void> => {
  const checksumEntries = (
    await Promise.all(
      DESKTOP_RELEASE_TARGETS.map(async (target) => {
        const targetRoot = join(DESKTOP_RELEASE_ROOT, target);
        if (!(await pathExists(targetRoot))) {
          return [];
        }

        const entries = await readdir(targetRoot, { withFileTypes: true });
        const fileNames = entries.filter((entry) => entry.isFile()).map((entry) => entry.name);
        return Promise.all(
          fileNames.map(async (fileName) => {
            const relativePath = join(target, fileName);
            return `${await computeSha256(join(DESKTOP_RELEASE_ROOT, relativePath))}  ${relativePath}`;
          }),
        );
      }),
    )
  ).flat();

  const sortedEntries = checksumEntries.sort((left, right) => left.localeCompare(right));
  await writeFile(DESKTOP_RELEASE_CHECKSUM_PATH, `${sortedEntries.join("\n")}\n`);
};

const runVerifier = async (targets: readonly DesktopReleaseTarget[]): Promise<void> => {
  const verifierExitCode = await Bun.spawn(
    [
      process.execPath,
      "run",
      "scripts/verify-desktop-release-artifacts.ts",
      "--targets",
      targets.join(","),
    ],
    {
      cwd: MONOREPO_ROOT,
      stdout: "inherit",
      stderr: "inherit",
      env: process.env,
    },
  ).exited;

  if (verifierExitCode !== 0) {
    process.exit(verifierExitCode);
  }
};

type RefreshDesktopReleaseConfig = {
  argv: readonly string[];
  replaceReleaseTree: boolean;
  skipVerify: boolean;
  preserveOtherTargets: boolean;
  sourceRoot: string;
};

const createRefreshDesktopReleaseConfig = (
  argv: readonly string[],
): RefreshDesktopReleaseConfig => {
  const replaceReleaseTree = parseReplaceReleaseTreeFlag(argv);
  return {
    argv,
    replaceReleaseTree,
    skipVerify: parseSkipVerifyFlag(argv),
    preserveOtherTargets: !replaceReleaseTree,
    sourceRoot: resolveSourceRoot(argv),
  };
};

const resolveRefreshTargets = async (
  argv: readonly string[],
  sourceRoot: string,
): Promise<readonly DesktopReleaseTarget[]> => {
  const explicitTargets = parseDesktopReleaseRefreshTargets(argv);
  const targets =
    explicitTargets ?? (await discoverStagedDesktopReleaseTargets(sourceRoot, pathExists));
  if (targets.length === 0) {
    throw new Error(`No staged desktop release targets were found in ${sourceRoot}.`);
  }
  return targets;
};

const stageReleaseProvenanceEntries = async (
  sourceRoot: string,
  targets: readonly DesktopReleaseTarget[],
): Promise<readonly (readonly [DesktopReleaseTarget, ReleaseProvenance])[]> =>
  Promise.all(
    targets.map(async (target) => {
      const provenance = await readProvenance(sourceRoot, target);
      const artifactNames = await collectTargetArtifacts(sourceRoot, target);
      const missingArtifacts = provenance.artifactNames.filter(
        (artifactName) => !artifactNames.includes(artifactName),
      );
      if (missingArtifacts.length > 0) {
        throw new Error(
          `Target ${target} is missing staged artifacts declared in provenance: ${missingArtifacts.join(", ")}`,
        );
      }

      const sanitized = sanitizeProvenanceForCommit(provenance);
      await stageTargetArtifacts(sourceRoot, target, provenance.artifactNames);
      await writeFormattedJsonFile(
        join(DESKTOP_RELEASE_METADATA_ROOT, target, DESKTOP_RELEASE_PROVENANCE_FILENAME),
        sanitized,
      );
      return [target, sanitized] as const;
    }),
  );

const mergeAssembledTargetMap = (
  preMergeTargets: Map<DesktopReleaseTarget, ReleaseProvenance>,
  provenanceEntries: readonly (readonly [DesktopReleaseTarget, ReleaseProvenance])[],
): Map<DesktopReleaseTarget, ReleaseProvenance> => {
  const mergedTargetMap = new Map<DesktopReleaseTarget, ReleaseProvenance>();
  const existingEntries: ReadonlyArray<[DesktopReleaseTarget, ReleaseProvenance]> = Array.from(
    preMergeTargets.entries(),
  );
  for (const [existingTarget, existingProvenance] of existingEntries) {
    mergedTargetMap.set(existingTarget, sanitizeProvenanceForCommit(existingProvenance));
  }
  for (const [target, provenance] of provenanceEntries) {
    mergedTargetMap.set(target, provenance);
  }
  return mergedTargetMap;
};

const writeAssembledReleaseManifests = async (
  sourceRoot: string,
  mergedTargetMap: Map<DesktopReleaseTarget, ReleaseProvenance>,
): Promise<void> => {
  await mkdir(DESKTOP_RELEASE_METADATA_ROOT, { recursive: true });
  await writeFormattedJsonFile(DESKTOP_RELEASE_ASSEMBLED_PROVENANCE_PATH, {
    schemaVersion: 1,
    assembledAt: new Date().toISOString(),
    sourceRoot: sanitizeSourceRootForProvenance(sourceRoot),
    targets: buildOrderedAssembledTargets(mergedTargetMap),
  });
  await writeChecksumManifest();
};

const main = async (): Promise<void> => {
  const config = createRefreshDesktopReleaseConfig(process.argv.slice(2));
  const targets = await resolveRefreshTargets(config.argv, config.sourceRoot);
  const preMergeTargets = config.preserveOtherTargets
    ? await readExistingAssembledTargets()
    : new Map<DesktopReleaseTarget, ReleaseProvenance>();
  await pruneLegacyReleaseEntries();
  if (config.replaceReleaseTree) {
    await pruneUnselectedReleaseTargets(targets);
  }
  const provenanceEntries = await stageReleaseProvenanceEntries(config.sourceRoot, targets);
  const mergedTargetMap = mergeAssembledTargetMap(preMergeTargets, provenanceEntries);
  await writeAssembledReleaseManifests(config.sourceRoot, mergedTargetMap);
  await writeOutput(
    config.replaceReleaseTree
      ? `desktop-release:refreshed ${targets.join(", ")} from ${config.sourceRoot} into ${DESKTOP_RELEASE_ROOT} (replace-release-tree: pruned unstaged canonical targets)`
      : `desktop-release:refreshed ${targets.join(", ")} from ${config.sourceRoot} into ${DESKTOP_RELEASE_ROOT} (other canonical targets preserved; pass ${REPLACE_RELEASE_TREE_FLAG} to prune them)`,
  );
  if (!config.skipVerify) {
    await runVerifier(targets);
  }
  await writeOutput("desktop-release:refresh complete");
};

const result = await captureResult(main);
if (!result.ok) {
  await writeError(toErrorMessage(result.error, "Unexpected desktop release refresh failure."));
  process.exit(1);
}

/**
 * Ensures workspace section rails use SSOT scroll-snap tokens (not ad-hoc classes).
 */
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

const ROOT = process.cwd();
const TARGET = join(ROOT, "packages/client/components/ui/WorkspaceSectionNavigator.vue");

const REQUIRED_TOKENS = [
  "SCROLL_SNAP_X_MANDATORY_CLASS",
  "SCROLL_SNAP_ALIGN_START_CLASS",
  "SCROLL_TOUCH_PAN_X_CLASS",
  "SECTION_RAIL_LABEL_CLASS",
] as const;

const BANNED_INLINE = /\bsnap-x\b|\btouch-pan-x\b/u;
/** overflow-x-clip on the navigator card kills horizontal section-rail scroll @320. */
const BANNED_OVERFLOW_CLIP = /\boverflow-x-clip\b/u;
/** Papered discoverability fix: hiding labels @320 instead of truncating. */
const BANNED_LABEL_HIDE = /\bhidden\b[^"']*\bsm:inline\b|\bmax-sm:sr-only\b/u;

export const collectSectionRailScrollViolations = (content: string): string[] => {
  const violations: string[] = [];
  for (const token of REQUIRED_TOKENS) {
    if (!content.includes(token)) {
      violations.push(`missing SSOT token import/use: ${token}`);
    }
  }
  // Ban raw snap / overflow-clip utilities in class="..." string literals (token constants OK).
  const classLiterals = content.matchAll(/class="([^"]*)"/gu);
  for (const match of classLiterals) {
    const classValue = match[1] ?? "";
    if (BANNED_INLINE.test(classValue)) {
      violations.push(`raw scroll utility in class literal: ${classValue}`);
    }
    if (BANNED_OVERFLOW_CLIP.test(classValue)) {
      violations.push("overflow-x-clip banned on WorkspaceSectionNavigator (clips section rail)");
    }
    if (BANNED_LABEL_HIDE.test(classValue)) {
      violations.push("section-rail labels must use SECTION_RAIL_LABEL_CLASS (not hidden/sr-only)");
    }
  }
  return violations;
};

const main = async (): Promise<void> => {
  const content = await readFile(TARGET, "utf8");
  const violations = collectSectionRailScrollViolations(content);
  if (violations.length > 0) {
    await Promise.all(violations.map((violation) => writeError(`${TARGET}: ${violation}`)));
    process.exitCode = 1;
    return;
  }
  await writeOutput("section-rail scroll SSOT OK");
};

if (import.meta.main) {
  await main();
}

