/**
 * Runs package typecheck with TypeScript 7 (`@typescript/native`) and fails only
 * on first-party source errors. Upstream declaration noise from Elysia 2 / Drizzle
 * is reported in summary counts but does not fail the gate until those packages
 * ship TS7-clean `.d.ts` files (see docs/STACK-CONTRACT.md).
 */
import { spawnSync } from "node:child_process";
import { join } from "node:path";
import { writeError, writeOutput } from "./utils/cli-output";

const packages = ["shared", "scraper", "server", "client"] as const;
const tscBin = join(process.cwd(), "node_modules", "@typescript", "native", "bin", "tsc");

const packageResults = packages.map((pkg) => {
  const cwd = join(process.cwd(), "packages", pkg);
  // Client typecheck self-bootstraps Nuxt + server generated types; use package script.
  const result =
    pkg === "client"
      ? spawnSync("bun", ["run", "typecheck"], {
          cwd,
          encoding: "utf8",
          env: process.env,
        })
      : spawnSync(process.execPath, [tscBin, "--noEmit", "--pretty", "false"], {
          cwd,
          encoding: "utf8",
          env: process.env,
        });
  const output = `${result.stdout ?? ""}${result.stderr ?? ""}`;
  const lines = output
    .split("\n")
    .map((line) => line.trimEnd())
    .filter((line) => line.includes("error TS"));
  const sourceErrors = lines.filter((line) => !line.includes("node_modules"));
  const upstreamErrors = lines.filter((line) => line.includes("node_modules"));
  return { pkg, sourceErrors, upstreamErrors };
});

await Promise.all(
  packageResults.map(({ pkg, sourceErrors, upstreamErrors }) =>
    writeOutput(
      `[typecheck:${pkg}] sourceErrors=${sourceErrors.length} upstreamDeclarationErrors=${upstreamErrors.length}`,
    ),
  ),
);

const allSourceErrors = packageResults.flatMap(({ sourceErrors }) => sourceErrors);
if (allSourceErrors.length > 0) {
  await Promise.all(allSourceErrors.map((line) => writeError(line)));
  process.exit(1);
}

await writeOutput("Workspace source typecheck passed (TypeScript 7 native).");

/**
 * Emit a standard output message.
 */
export const writeOutput = (value: string): Promise<void> => {
  process.stdout.write(`${value}\n`);
  return Promise.resolve();
};

/**
 * Emit a standard error message.
 */
export const writeError = (value: string): Promise<void> => {
  process.stderr.write(`${value}\n`);
  return Promise.resolve();
};

/**
 * Biome ratchet additions for industry-best-practice UI/UX/wiring rules.
 *
 * Extracted from biome-softener-ratchet.ts to stay under the HB023 400-line
 * file ceiling. These predicates enforce the rules added in the 2026-07-21
 * lint-hardening pass: noMagicNumbers, noShoutyConstants, noCommonJs,
 * useThrowOnlyError, useExplicitLengthCheck, noDoneCallback,
 * noEmptyBlockStatements, noTemplateCurlyInString.
 *
 * noUndeclaredClasses and noUnusedClasses are intentionally NOT enforced:
 * they produce false positives on Tailwind/daisyUI utility classes (the rule
 * cannot resolve classes generated by the Tailwind compiler). Enforcing them
 * would require 268+ suppressions or a custom class allowlist that drifts from
 * the Tailwind config. The canonical fix is to wait for biome to support
 * Tailwind class resolution (tracked in
 * scripts/docs/biome-tailwind-incompatibility.md).
 */
import type { SoftenerJsonValue } from "./biome-softener-ratchet";
import type { ValidationViolation } from "./validation-helpers";
import { isSoftenerRecord, requireRuleError } from "./biome-softener-ratchet";

export const validateStyleAdditionsRatchet = (
  style: { [key: string]: SoftenerJsonValue },
  violations: ValidationViolation[],
  biomePath: string,
): void => {
  for (const ruleName of [
    "noShoutyConstants",
    "noCommonJs",
    "useThrowOnlyError",
    "useExplicitLengthCheck",
    "noDoneCallback",
  ] as const) {
    requireRuleError(style, ruleName, "linter.rules.style", violations, biomePath);
  }
  const magicNumbers = style.noMagicNumbers;
  const magicNumbersOk =
    magicNumbers === "error" || (isSoftenerRecord(magicNumbers) && magicNumbers.level === "error");
  if (!magicNumbersOk) {
    violations.push({
      filePath: biomePath,
      line: 1,
      message:
        'linter.rules.style.noMagicNumbers must be "error" (extract magic numbers to named constants).',
    });
  }
};

export const validateSuspiciousAdditionsRatchet = (
  suspicious: { [key: string]: SoftenerJsonValue },
  violations: ValidationViolation[],
  biomePath: string,
): void => {
  for (const ruleName of ["noEmptyBlockStatements", "noTemplateCurlyInString"] as const) {
    requireRuleError(suspicious, ruleName, "linter.rules.suspicious", violations, biomePath);
  }
};

